import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { ProjectProvider } from './context/ProjectContext';
import { SubscriptionProvider } from './context/SubscriptionContext';
import { ThemeProvider } from './context/ThemeContext';
import { PricingModalProvider } from './context/PricingModalContext';
import { ErrorProvider } from './context/ErrorContext';
import { SidebarProvider } from './context/SidebarContext';
import ProtectedRoute from './components/ProtectedRoute';
import Layout from './components/layout/Layout';
import ErrorBoundary from './components/ErrorBoundary';
import Dashboard from './pages/Dashboard';
import Editor from './pages/Editor';
import Catalog from './pages/Catalog';
import History from './pages/History';
import Templates from './pages/Templates';
import PDFTemplatesPage from './pages/PDFTemplatesPage';
import Login from './pages/Login';
import LandingPage from './pages/LandingPage';
import DemoPage from './pages/DemoPage';
import BitacoraPage from './pages/BitacoraPage';
import PhotographicReportPage from './pages/PhotographicReportPage';
import PricingPage from './pages/PricingPage';
import UsageDashboard from './pages/UsageDashboard';
import ScheduleGanttPage from './pages/ScheduleGanttPage';
import SharedProjectPage from './pages/SharedProjectPage';
import UsageNotification from './components/subscription/UsageNotification';
import ConfirmEmail from './pages/ConfirmEmail';
import NotFound from './pages/NotFound';
import InactivityHandler from './components/auth/InactivityHandler';
import KeepAlive from './components/KeepAlive';
import AdminDashboard from './pages/AdminDashboard';
import AdminRoute from './components/auth/AdminRoute';
import PriceSearchPage from './pages/PriceSearchPage';
import PDFEditorPage from './pages/PDFEditorPage';
import ProjectReportsDashboard from './pages/ProjectReportsDashboard';


const App = () => {
    return (
        <ErrorBoundary>
            <ThemeProvider>
                <ErrorProvider>
                    <AuthProvider>
                        <SubscriptionProvider>
                            <PricingModalProvider>
                                <SidebarProvider>
                                    <ProjectProvider>
                                        <Router>
                                            <InactivityHandler />
                                            <KeepAlive />
                                            <Routes>
                                                {/* Landing Page - Public */}
                                                <Route path="/" element={<LandingPage />} />

                                                {/* Demo Page - Public */}
                                                <Route path="/demo" element={<DemoPage />} />

                                                {/* Email Confirmation - Public */}
                                                <Route path="/confirm-email" element={<ConfirmEmail />} />
                                                <Route path="/auth/callback" element={<ConfirmEmail />} />
                                                <Route path="/auth/confirm" element={<ConfirmEmail />} />

                                                {/* Shared Project Routes - Public */}
                                                <Route path="/share/:token" element={<SharedProjectPage />} />
                                                <Route path="/s/:token" element={<SharedProjectPage />} />

                                                {/* Public route - Login */}
                                                <Route path="/login" element={
                                                    <ProtectedRoute requireAuth={false}>
                                                        <Login />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Protected routes - Require authentication */}
                                                <Route path="/dashboard" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Visión General"><Dashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Editor Routes */}
                                                <Route path="/editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/editor/:id" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Bitacora Route */}
                                                <Route path="/project/:id/bitacora" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Bitácora de Obra"><BitacoraPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Schedule Gantt Route */}
                                                <Route path="/project/:id/schedule" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <ScheduleGanttPage />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Photographic Report Routes */}
                                                <Route path="/project/:projectId/report/new" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Nuevo Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/project/:projectId/report/:logId/edit" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                <Route path="/catalog" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Base de Datos Maestra"><Catalog /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Plantillas"><Templates /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pdf-templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Configurar PDF"><PDFTemplatesPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/history" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Archivos Guardados"><History /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pricing" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Planes y Precios"><PricingPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/usage" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Dashboard de Uso"><UsageDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/reports" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Módulo de Reportes"><ProjectReportsDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Price Search Route */}
                                                <Route path="/pricesearch" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Búsqueda de Precios"><PriceSearchPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* PDF Editor Route */}
                                                <Route path="/pdf-editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar PDF"><PDFEditorPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Admin Route */}
                                                <Route path="/admin" element={
                                                    <AdminRoute>
                                                        <Layout title="Administración del Sistema"><AdminDashboard /></Layout>
                                                    </AdminRoute>
                                                } />

                                                {/* Catch-all route - 404 Not Found */}
                                                <Route path="*" element={<NotFound />} />
                                            </Routes>
                                        </Router>
                                    </ProjectProvider>
                                </SidebarProvider>
                            </PricingModalProvider>
                        </SubscriptionProvider>
                    </AuthProvider>
                </ErrorProvider>
            </ThemeProvider>
        </ErrorBoundary>
    );
};

export default App;

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App'

// Inicializar Sentry (solo si está configurado)
import './lib/sentry'

// Configurar handlers de errores globales
import './lib/errorHandlers'

// Utilidades de prueba en desarrollo
if (import.meta.env.DEV) {
  import('./utils/testErrorHandling.js')
}

// Prevenir problemas de seguridad con el cache del navegador (Back/Forward Cache)
// Esto asegura que al dar "Atrás" después de cerrar sesión, la página se recargue y verifique auth
window.addEventListener('pageshow', (event) => {
  if (event.persisted) {
    window.location.reload();
  }
});

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>,
)

#root {
  width: 100%;
  margin: 0;
  padding: 0;
}

.logo {
  height: 6em;
  padding: 1.5em;
  will-change: filter;
  transition: filter 300ms;
}
.logo:hover {
  filter: drop-shadow(0 0 2em #646cffaa);
}
.logo.react:hover {
  filter: drop-shadow(0 0 2em #61dafbaa);
}

@keyframes logo-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: no-preference) {
  a:nth-of-type(2) .logo {
    animation: logo-spin infinite 20s linear;
  }
}

.card {
  padding: 2em;
}

.read-the-docs {
  color: #888;
}

import React, { useState } from 'react';
import { Sparkles, Loader, X, Check } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';

const AIDescriptionGenerator = ({ itemData, context, onSelect, onClose }) => {
    const [loading, setLoading] = useState(false);
    const [suggestions, setSuggestions] = useState([]);
    const [error, setError] = useState('');
    const [selectedIndex, setSelectedIndex] = useState(null);

    const generateSuggestions = async () => {
        setLoading(true);
        setError('');
        setSuggestions([]);

        try {
            const descriptions = await AIBudgetService.generateDescription(itemData, context);
            setSuggestions(descriptions);
        } catch (err) {
            console.error('Error generating descriptions:', err);
            setError(err.message || 'Error al generar descripciones');
        } finally {
            setLoading(false);
        }
    };

    const handleSelect = (description, index) => {
        setSelectedIndex(index);
        onSelect(description);
    };

    React.useEffect(() => {
        // Always try to generate, error handling will catch if service is down
        generateSuggestions();
    }, []);

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[80vh] overflow-hidden flex flex-col">
                {/* Header */}
                <div className="bg-gradient-to-r from-purple-600 to-indigo-600 p-6 text-white">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <Sparkles size={24} />
                            <div>
                                <h3 className="text-xl font-bold">Generador de Descripciones IA</h3>
                                <p className="text-purple-100 text-sm">Powered by Gemini AI</p>
                            </div>
                        </div>
                        <button
                            onClick={onClose}
                            className="hover:bg-white/20 p-2 rounded-lg transition"
                        >
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {/* Item Info */}
                    <div className="bg-slate-50 rounded-lg p-4 mb-6">
                        <h4 className="font-semibold text-slate-700 mb-2">Información de la partida:</h4>
                        <div className="grid grid-cols-2 gap-2 text-sm">
                            {itemData.code && (
                                <div>
                                    <span className="text-slate-500">Código:</span>
                                    <span className="ml-2 font-medium">{itemData.code}</span>
                                </div>
                            )}
                            {itemData.unit && (
                                <div>
                                    <span className="text-slate-500">Unidad:</span>
                                    <span className="ml-2 font-medium">{itemData.unit}</span>
                                </div>
                            )}
                            {itemData.category && (
                                <div>
                                    <span className="text-slate-500">Categoría:</span>
                                    <span className="ml-2 font-medium">{itemData.category}</span>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Loading State */}
                    {loading && (
                        <div className="flex flex-col items-center justify-center py-12">
                            <Loader className="animate-spin text-purple-600 mb-4" size={40} />
                            <p className="text-slate-600">Generando descripciones profesionales...</p>
                        </div>
                    )}

                    {/* Error State */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
                            <p className="text-red-700 text-sm">{error}</p>
                            {error.includes('API key') && (
                                <p className="text-red-600 text-xs mt-2">
                                    Configura tu API key de Gemini en el archivo .env
                                </p>
                            )}
                        </div>
                    )}

                    {/* Suggestions */}
                    {suggestions.length > 0 && (
                        <div className="space-y-3">
                            <h4 className="font-semibold text-slate-700 mb-3">
                                Selecciona una descripción:
                            </h4>
                            {suggestions.map((description, index) => (
                                <button
                                    key={index}
                                    onClick={() => handleSelect(description, index)}
                                    className={`w-full text-left p-4 rounded-lg border-2 transition-all ${selectedIndex === index
                                        ? 'border-purple-600 bg-purple-50'
                                        : 'border-slate-200 hover:border-purple-300 bg-white'
                                        }`}
                                >
                                    <div className="flex items-start justify-between gap-3">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className="text-xs font-semibold text-purple-600 bg-purple-100 px-2 py-1 rounded">
                                                    Opción {index + 1}
                                                </span>
                                            </div>
                                            <p className="text-slate-800">{description}</p>
                                        </div>
                                        {selectedIndex === index && (
                                            <Check className="text-purple-600 flex-shrink-0" size={20} />
                                        )}
                                    </div>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Retry Button */}
                    {!loading && suggestions.length > 0 && (
                        <button
                            onClick={generateSuggestions}
                            className="mt-4 w-full py-2 text-purple-600 hover:bg-purple-50 rounded-lg transition font-medium text-sm"
                        >
                            🔄 Generar nuevas opciones
                        </button>
                    )}
                </div>

                {/* Footer */}
                <div className="border-t border-slate-200 p-4 bg-slate-50">
                    <div className="flex gap-3 justify-end">
                        <button
                            onClick={onClose}
                            className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg transition"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={onClose}
                            disabled={selectedIndex === null}
                            className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            Usar descripción seleccionada
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AIDescriptionGenerator;

import React, { useState, useEffect } from 'react';
import { TrendingUp, Sparkles, AlertCircle } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';

const AIPriceHelper = ({ itemData, catalogData, onSuggestionClick }) => {
    const [suggestion, setSuggestion] = useState(null);
    const [loading, setLoading] = useState(false);
    const [visible, setVisible] = useState(false);

    // Removed auto-fetch useEffect to prevent rate limit errors

    const fetchSuggestion = async () => {
        setLoading(true);
        try {
            const result = await AIBudgetService.suggestPrice(itemData, catalogData);
            setSuggestion(result);
            setVisible(true);
        } catch (error) {
            console.error('Error fetching price suggestion:', error);
            setVisible(false);
        } finally {
            setLoading(false);
        }
    };

    const getConfidenceColor = (confidence) => {
        switch (confidence) {
            case 'high': return 'text-green-600 bg-green-50 border-green-200';
            case 'medium': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
            case 'low': return 'text-orange-600 bg-orange-50 border-orange-200';
            default: return 'text-slate-600 bg-slate-50 border-slate-200';
        }
    };

    const getConfidenceLabel = (confidence) => {
        switch (confidence) {
            case 'high': return 'Alta confianza';
            case 'medium': return 'Confianza media';
            case 'low': return 'Baja confianza';
            default: return 'Sin datos';
        }
    };

    if (!visible || !suggestion) {
        return (
            <button
                onClick={fetchSuggestion}
                disabled={loading}
                className="mt-1 text-xs flex items-center gap-1 text-purple-600 hover:text-purple-700 font-medium transition-colors"
                title="Consultar precio sugerido con IA"
            >
                {loading ? (
                    <span className="animate-spin">⏳</span>
                ) : (
                    <Sparkles size={14} />
                )}
                {loading ? 'Analizando...' : 'Sugerir Precio'}
            </button>
        );
    }

    if (suggestion.suggested === null) {
        return (
            <div className="mt-2 p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm relative group">
                <button
                    onClick={() => setVisible(false)}
                    className="absolute top-1 right-1 text-slate-400 hover:text-slate-600"
                >
                    ×
                </button>
                <div className="flex items-center gap-2 text-slate-600">
                    <AlertCircle size={16} />
                    <span>{suggestion.message}</span>
                </div>
            </div>
        );
    }

    return (
        <div className="mt-2 p-3 bg-gradient-to-r from-purple-50 to-indigo-50 border border-purple-200 rounded-lg">
            <div className="flex items-start gap-3">
                <div className="flex-shrink-0">
                    <div className="w-8 h-8 bg-purple-600 rounded-lg flex items-center justify-center">
                        <Sparkles size={16} className="text-white" />
                    </div>
                </div>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-2">
                        <span className="text-sm font-semibold text-purple-900">
                            Sugerencia de IA
                        </span>
                        <span className={`text-xs px-2 py-0.5 rounded-full border ${getConfidenceColor(suggestion.confidence)}`}>
                            {getConfidenceLabel(suggestion.confidence)}
                        </span>
                    </div>

                    <div className="space-y-2">
                        {/* Suggested Price */}
                        <div>
                            <button
                                onClick={() => onSuggestionClick(suggestion.suggested)}
                                className="text-lg font-bold text-purple-600 hover:text-purple-700 transition"
                            >
                                ${suggestion.suggested.toFixed(2)}
                            </button>
                            <span className="text-xs text-slate-500 ml-2">
                                (Click para usar)
                            </span>
                        </div>

                        {/* Price Range */}
                        <div className="flex items-center gap-2 text-xs text-slate-600">
                            <TrendingUp size={14} />
                            <span>
                                Rango típico: ${suggestion.min.toFixed(2)} - ${suggestion.max.toFixed(2)}
                            </span>
                        </div>

                        {/* Similar Items Count */}
                        {suggestion.similarCount > 0 && (
                            <div className="text-xs text-slate-500">
                                Basado en {suggestion.similarCount} partida{suggestion.similarCount !== 1 ? 's' : ''} similar{suggestion.similarCount !== 1 ? 'es' : ''} del catálogo
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AIPriceHelper;

import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Loader } from 'lucide-react';
import { SubscriptionService } from '../../services/SubscriptionService';

const AdminRoute = ({ children }) => {
    const { user, loading } = useAuth();

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="text-center">
                    <Loader size={48} className="animate-spin text-blue-600 mx-auto mb-4" />
                    <p className="text-slate-600">Verificando permisos...</p>
                </div>
            </div>
        );
    }

    // Verificar si hay usuario y si es email admin (Pro email)
    if (!user || !user.email || !SubscriptionService.isProEmail(user.email)) {
        return <Navigate to="/dashboard" replace />;
    }

    return children;
};

export default AdminRoute;

import React, { useState } from 'react';
import { X, Lock, Eye, EyeOff, CheckCircle, AlertCircle } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';

const ChangePasswordModal = ({ isOpen, onClose }) => {
    const { updatePassword } = useAuth();
    const [formData, setFormData] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [showPasswords, setShowPasswords] = useState({
        current: false,
        new: false,
        confirm: false
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);

    // Validación de contraseña segura
    const validatePassword = (password) => {
        const validations = {
            length: password.length >= 12,
            uppercase: /[A-Z]/.test(password),
            lowercase: /[a-z]/.test(password),
            number: /[0-9]/.test(password),
            special: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)
        };

        const strength = Object.values(validations).filter(Boolean).length;
        const strengthLevel = strength <= 2 ? 'débil' : strength <= 4 ? 'media' : 'fuerte';

        return {
            valid: validations.length && validations.uppercase && validations.lowercase && validations.number,
            validations,
            strength,
            strengthLevel
        };
    };

    const passwordValidation = formData.newPassword ? validatePassword(formData.newPassword) : null;

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setSuccess(false);

        // Validaciones
        if (!formData.currentPassword) {
            setError('Ingresa tu contraseña actual');
            return;
        }

        if (!formData.newPassword) {
            setError('Ingresa una nueva contraseña');
            return;
        }

        if (!passwordValidation?.valid) {
            setError('La nueva contraseña no cumple con los requisitos de seguridad');
            return;
        }

        if (formData.newPassword !== formData.confirmPassword) {
            setError('Las contraseñas no coinciden');
            return;
        }

        if (formData.currentPassword === formData.newPassword) {
            setError('La nueva contraseña debe ser diferente a la actual');
            return;
        }

        setLoading(true);
        try {
            const { error: updateError } = await updatePassword(formData.newPassword);
            
            if (updateError) {
                // Si el error es de autenticación, puede ser que necesite reautenticarse
                if (updateError.message.includes('password') || updateError.message.includes('auth')) {
                    setError('Error al actualizar la contraseña. Asegúrate de que tu contraseña actual sea correcta.');
                } else {
                    setError(updateError.message || 'Error al actualizar la contraseña');
                }
                setLoading(false);
                return;
            }

            setSuccess(true);
            setFormData({ currentPassword: '', newPassword: '', confirmPassword: '' });
            
            // Cerrar modal después de 2 segundos
            setTimeout(() => {
                onClose();
                setSuccess(false);
            }, 2000);
        } catch (err) {
            setError('Error inesperado al actualizar la contraseña');
            console.error('Error updating password:', err);
        } finally {
            setLoading(false);
        }
    };

    const handleClose = () => {
        setFormData({ currentPassword: '', newPassword: '', confirmPassword: '' });
        setError('');
        setSuccess(false);
        onClose();
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-gradient-to-r from-blue-600 to-blue-700 text-white">
                    <h3 className="font-bold text-lg flex items-center">
                        <Lock className="mr-2" size={20} /> Cambiar Contraseña
                    </h3>
                    <button
                        onClick={handleClose}
                        className="text-white/60 hover:text-white hover:bg-white/10 p-1 rounded-full transition"
                    >
                        <X size={20} />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {success ? (
                        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4 flex items-center gap-3">
                            <CheckCircle className="text-emerald-600" size={20} />
                            <div>
                                <p className="font-bold text-emerald-800">Contraseña actualizada exitosamente</p>
                                <p className="text-sm text-emerald-600">El modal se cerrará automáticamente...</p>
                            </div>
                        </div>
                    ) : (
                        <>
                            {error && (
