import React, { useState } from 'react';
import { X, FileText, Save, Cloud, Users, Package, AlertCircle } from 'lucide-react';
import BitacoraService from '../../services/BitacoraService';
import { useSubscription } from '../../context/SubscriptionContext';
import LimitModal from '../subscription/LimitModal';

const LogEntryModal = ({ isOpen, onClose, task, projectId, onSave, editingLog = null }) => {
    const { checkLimit, incrementUsage, isPro } = useSubscription();
    const [content, setContent] = useState('');
    const [progress, setProgress] = useState(0);
    const [uploading, setUploading] = useState(false);
    const [limitModal, setLimitModal] = useState({
        isOpen: false,
        actionType: null,
        usage: 0,
        limit: 0
    });

    // Campos profesionales
    const [subject, setSubject] = useState('');
    const [classification, setClassification] = useState('Informe');
    const [authorRole, setAuthorRole] = useState('Residente');
    const [status, setStatus] = useState('Abierta');
    const [noteNumber, setNoteNumber] = useState(null);
    
    // Campos específicos para bitácora de obra civil
    const [weather, setWeather] = useState(''); // Condiciones climáticas
    const [materials, setMaterials] = useState(''); // Materiales utilizados
    const [personnel, setPersonnel] = useState(''); // Personal utilizado
    const [observations, setObservations] = useState(''); // Observaciones adicionales

    // Cargar datos si se está editando
    React.useEffect(() => {
        if (isOpen && editingLog) {
            // Limpiar contenido de metadata
            const cleanContent = BitacoraService.getCleanContent(editingLog.content || '');
            setContent(cleanContent);
            setProgress(editingLog.progress_percentage || 0);
            setSubject(editingLog.subject || '');
            setClassification(editingLog.classification || 'Informe');
            setAuthorRole(editingLog.author_role || 'Residente');
            setStatus(editingLog.status || 'Abierta');
            setNoteNumber(editingLog.note_number);
            // Cargar campos adicionales (extraer de metadata del contenido)
            const metadata = BitacoraService.extractBitacoraMetadata(editingLog.content) || {};
            setWeather(metadata.weather || '');
            setMaterials(metadata.materials || '');
            setPersonnel(metadata.personnel || '');
            setObservations(metadata.observations || '');
        } else if (isOpen && !editingLog) {
            // Resetear para nueva nota
            setContent('');
            setProgress(task?.progress || 0);
            setSubject('');
            setClassification('Informe');
            setAuthorRole('Residente');
            setStatus('Abierta');
            setWeather('');
            setMaterials('');
            setPersonnel('');
            setObservations('');
        }
    }, [isOpen, editingLog, task]);

    // Fetch next note number on open (solo si no se está editando)
    React.useEffect(() => {
        if (isOpen && projectId && !editingLog) {
            const fetchNextNoteNumber = async () => {
                try {
                    const nextNumber = await BitacoraService.getNextNoteNumber(projectId);
                    setNoteNumber(nextNumber);
                } catch (error) {
                    console.error('Error fetching note number:', error);
                    setNoteNumber(1); // Fallback
                }
            };
            fetchNextNoteNumber();
        } else if (editingLog) {
            setNoteNumber(editingLog.note_number);
        }
    }, [isOpen, projectId, editingLog]);

    if (!isOpen) return null;
    
    // Si no hay task, crear una por defecto
    const taskData = task || { id: 'general', name: 'Nota General', progress: 0 };

    const handleSubmit = async () => {
        if (!projectId) {
            alert('Error: No se encontró el ID del proyecto');
            return;
        }

        // Validar datos
        const validation = BitacoraService.validateLogData({
            projectId,
            taskId: taskData.id,
            subject,
            progressPercentage: progress,
            classification,
            authorRole,
            status
        });

        if (!validation.valid) {
            alert('Errores de validación:\n' + validation.errors.join('\n'));
            return;
        }

        setUploading(true);
        try {
            // Preparar metadata con campos adicionales
            const metadata = {
                weather,
                materials,
                personnel,
                observations
            };

            // Crear o actualizar nota
            if (editingLog) {
                // Actualizar nota existente
                await BitacoraService.updateLog(editingLog.id, {
                    content,
                    progressPercentage: progress,
                    subject,
                    classification,
                    authorRole,
                    status,
                    noteNumber,
                    metadata
                });
            } else {
                // Verificar límite antes de crear nueva nota
                if (!isPro) {
                    const limitCheck = await checkLimit('bitacoraEntries');
                    if (!limitCheck.allowed) {
                        setLimitModal({
                            isOpen: true,
                            actionType: 'bitacoraEntries',
                            usage: limitCheck.current,
                            limit: limitCheck.limit
                        });
                        setUploading(false);
                        return;
                    }
                }

                // Crear nueva nota
                await BitacoraService.createLog({
                    projectId,
                    taskId: taskData.id,
                    content,
                    progressPercentage: progress,
                    subject,
                    classification,
                    authorRole,
                    status,
                    noteNumber,
                    metadata
                });

                // Incrementar contador de uso
                if (!isPro) {
                    await incrementUsage('bitacoraEntries');
                }
            }

            onSave();
            onClose();
            
            // Resetear formulario
            setContent('');
            setProgress(taskData.progress || 0);
            setSubject('');
            setWeather('');
            setMaterials('');
            setPersonnel('');
            setObservations('');
        } catch (error) {
            console.error('Error saving log:', error);
            alert('Error al guardar la nota: ' + error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-800 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-lg">
                            <FileText className="mr-2" size={20} /> {editingLog ? 'Editar Nota de Bitácora' : 'Nueva Nota de Bitácora'}
                        </h3>
                        <p className="text-xs text-slate-400 mt-1">Folio #{noteNumber || '...'} • {taskData.name}</p>
                    </div>
                    <button onClick={onClose} className="text-white/60 hover:text-white"><X size={24} /></button>
                </div>

                <div className="p-6 space-y-5 overflow-y-auto flex-1">
                    {/* Top Row: Classification & Status */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Clasificación</label>
                            <select
                                value={classification}
                                onChange={(e) => setClassification(e.target.value)}
                                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm font-medium text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500"
                            >
                                <option>Apertura</option>
                                <option>Orden</option>
                                <option>Solicitud</option>
                                <option>Autorización</option>
                                <option>Informe</option>
                                <option>Cierre</option>
                                <option>Otro</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estatus</label>
                            <div className="flex bg-slate-100 rounded-lg p-1">
                                <button
                                    onClick={() => setStatus('Abierta')}
                                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition ${status === 'Abierta' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    Abierta
                                </button>
                                <button
                                    onClick={() => setStatus('Cerrada')}
                                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition ${status === 'Cerrada' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    Cerrada
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Subject */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Asunto <span className="text-red-500">*</span></label>
                        <input
                            value={subject}
                            onChange={(e) => setSubject(e.target.value)}
                            className="w-full font-bold text-slate-800 border-b-2 border-slate-200 focus:border-indigo-500 outline-none py-2 px-1 transition"
                            placeholder="Ej: Solicitud de estimación 1"
                        />
                    </div>

                    {/* Author Role */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Firma como</label>
                        <div className="flex gap-3">
                            {['Supervisor', 'Residente', 'Superintendente'].map(role => (
                                <button
                                    key={role}
                                    onClick={() => setAuthorRole(role)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-bold border transition ${authorRole === role ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                                >
                                    {role}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Content */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descripción de Actividades <span className="text-red-500">*</span></label>
                        <textarea
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            className="w-full p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-32 text-sm"
                            placeholder="Describe detalladamente las actividades realizadas, hechos, órdenes o solicitudes..."
                        />
                    </div>

                    {/* Campos específicos de bitácora de obra civil */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4 border-t border-slate-100">
                        {/* Condiciones Climáticas */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Cloud size={14} /> Condiciones Climáticas
                            </label>
                            <input
                                type="text"
                                value={weather}
                                onChange={(e) => setWeather(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                placeholder="Ej: Soleado, 25°C, sin viento"
                            />
                        </div>

                        {/* Avance Físico */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Avance Físico (%)</label>
                            <div className="flex items-center gap-3">
                                <input
                                    type="range"
                                    min="0"
                                    max="100"
                                    value={progress}
                                    onChange={(e) => setProgress(parseInt(e.target.value))}
                                    className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                                />
                                <div className="text-right text-sm font-bold text-indigo-600 w-12">{progress}%</div>
                            </div>
                        </div>
                    </div>

                    {/* Recursos Utilizados */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4 border-t border-slate-100">
                        {/* Materiales */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Package size={14} /> Materiales Utilizados
                            </label>
                            <textarea
                                value={materials}
                                onChange={(e) => setMaterials(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-20 text-sm"
                                placeholder="Ej: 50 m³ de concreto, 200 kg de acero..."
                            />
                        </div>

                        {/* Personal */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Users size={14} /> Personal Utilizado
                            </label>
                            <textarea
                                value={personnel}
                                onChange={(e) => setPersonnel(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-20 text-sm"
                                placeholder="Ej: 3 albañiles, 1 capataz, 1 ayudante..."
                            />
                        </div>
                    </div>

                    {/* Observaciones */}
                    <div className="pt-4 border-t border-slate-100">
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                            <AlertCircle size={14} /> Observaciones Adicionales
                        </label>
                        <textarea
                            value={observations}
                            onChange={(e) => setObservations(e.target.value)}
                            className="w-full p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-24 text-sm"
                            placeholder="Incidentes, desviaciones, correcciones, o cualquier observación relevante..."
                        />
                    </div>
                </div>

                <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition">
                        Cancelar
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={uploading}
                        className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold transition flex items-center shadow-lg shadow-indigo-200 disabled:opacity-50"
                    >
                        {uploading ? 'Firmando...' : <><Save size={18} className="mr-2" /> Firmar Nota</>}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default LogEntryModal;

import React, { useState, useEffect } from 'react';
import { X, Camera, Save, Plus, Trash2, Check, Upload } from 'lucide-react';
import BitacoraService from '../../services/BitacoraService';
import ImageUploadService from '../../services/ImageUploadService';

const PhotographicReportModal = ({ isOpen, onClose, projectId, items = [], onSave, editingLog = null }) => {
    const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);
    const [entries, setEntries] = useState([]);
    const [uploading, setUploading] = useState(false);

    // Cargar datos del log cuando se está editando
    useEffect(() => {
        if (isOpen && editingLog) {
            // Establecer fecha del reporte
            const logDate = editingLog.log_date ? new Date(editingLog.log_date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0];
            setReportDate(logDate);

            // Extraer nombre del concepto del subject
            const conceptName = editingLog.subject?.replace('Reporte Fotográfico: ', '') || 'Concepto';
            
            // Buscar el item correspondiente
            const item = items.find(i => 
                i.description === conceptName || 
                i.id?.toString() === editingLog.task_id
            );

            // Crear entrada con los datos del log
            const entry = {
                id: Date.now(),
                logId: editingLog.id, // ID del log para actualizar
                itemId: item?.id || editingLog.task_id,
                itemName: conceptName,
                itemCode: item?.code || '',
                photos: [], // Se cargarán desde las URLs
                previewUrls: editingLog.photos || [], // URLs existentes
                photoUrls: editingLog.photos || [], // URLs originales para mantener
                description: editingLog.content || '',
                progress: editingLog.progress_percentage || 100,
                isCompleted: editingLog.progress_percentage === 100
            };

            setEntries([entry]);
        } else if (isOpen && !editingLog) {
            // Resetear cuando se crea uno nuevo
            setReportDate(new Date().toISOString().split('T')[0]);
            setEntries([]);
        }
    }, [isOpen, editingLog, items]);

    // Limpiar previews al cerrar
    useEffect(() => {
        return () => {
            entries.forEach(entry => {
                entry.previewUrls.forEach(url => {
                    // Solo revocar si es un blob URL (no URLs de servidor)
                    if (url.startsWith('blob:')) {
                        ImageUploadService.revokePreviewUrl(url);
                    }
                });
            });
        };
    }, [entries]);

    if (!isOpen) return null;

    const handleAddBlock = () => {
        setEntries([...entries, {
            id: Date.now(),
            itemId: 'block-' + Date.now(),
            itemName: '',
            itemCode: '',
            photos: [],
            previewUrls: [],
            photoUrls: [],
            description: '',
            progress: 100,
            isCompleted: true
        }]);
    };

    const handleRemoveEntry = (entryId) => {
        const entry = entries.find(e => e.id === entryId);
        if (entry) {
            entry.previewUrls.forEach(url => ImageUploadService.revokePreviewUrl(url));
        }
        setEntries(entries.filter(e => e.id !== entryId));
    };

    const handleFileChange = (entryId, e) => {
        const selectedFiles = Array.from(e.target.files || []);
        if (selectedFiles.length === 0) return;

        const validFiles = [];
        const newPreviewUrls = [];

        selectedFiles.forEach(file => {
            const validation = ImageUploadService.validateImage(file);
            if (validation.valid) {
                validFiles.push(file);
                newPreviewUrls.push(ImageUploadService.createPreviewUrl(file));
            } else {
                alert(`Error en ${file.name}: ${validation.error}`);
            }
        });

        setEntries(entries.map(entry => {
            if (entry.id === entryId) {
                return {
                    ...entry,
                    photos: [...entry.photos, ...validFiles],
                    previewUrls: [...entry.previewUrls, ...newPreviewUrls]
                };
            }
            return entry;
        }));
    };

    const updateEntry = (entryId, field, value) => {
        setEntries(entries.map(entry => {
            if (entry.id === entryId) {
                return { ...entry, [field]: value };
            }
            return entry;
        }));
    };

    /** Actualiza varios campos de una entrada a la vez (evita estados intermedios al eliminar fotos). */
    const updateEntryFields = (entryId, updates) => {
        setEntries(entries.map(entry =>
            entry.id === entryId ? { ...entry, ...updates } : entry
        ));
    };

    const handleSave = async () => {
        if (entries.length === 0) {
            alert('Agrega al menos un bloque (fotos y concepto).');
            return;
        }

        setUploading(true);
        try {
            // Procesar cada entrada secuencialmente
            for (const entry of entries) {
                // 1. Subir nuevas fotos (si hay)
                let newPhotoUrls = [];
                if (entry.photos.length > 0) {
                    newPhotoUrls = await ImageUploadService.uploadMultipleImages(
                        entry.photos,
                        projectId,
                        'report-' + entry.itemId
                    );
                }

                // 2. Combinar URLs existentes con nuevas
                const existingUrls = entry.photoUrls || [];
                const allPhotoUrls = [...existingUrls, ...newPhotoUrls];

                // 3. Fecha del reporte
                const logDate = new Date(reportDate + 'T12:00:00').toISOString();

                const conceptName = (entry.itemName || '').trim() || `Concepto ${entry.itemId}`;
                if (editingLog && entry.logId) {
                    await BitacoraService.updateLog(entry.logId, {
                        content: entry.description || `Reporte fotográfico: ${conceptName}`,
                        progressPercentage: entry.isCompleted ? 100 : entry.progress,
                        photos: allPhotoUrls,
                        subject: `Reporte Fotográfico: ${conceptName}`
                    });
                } else {
                    await BitacoraService.createLog({
                        projectId,
                        taskId: entry.itemId.toString(),
                        content: entry.description || `Reporte fotográfico: ${conceptName}`,
                        progressPercentage: entry.isCompleted ? 100 : entry.progress,
                        photos: allPhotoUrls,
                        subject: `Reporte Fotográfico: ${conceptName}`,
                        classification: 'Informe',
                        authorRole: 'Residente',
                        status: 'Abierta',
                        logDate: logDate
                    });
                }
            }

            onSave();
            onClose();
        } catch (error) {
            console.error('Error saving report:', error);
            alert('Error al guardar el reporte: ' + error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[90] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-t-2xl sm:rounded-2xl shadow-2xl max-w-4xl w-full h-[92vh] sm:h-[90vh] max-h-[900px] flex flex-col overflow-hidden">
                {/* Header: título, fecha y acciones */}
                <div className="shrink-0 p-4 sm:p-5 border-b border-slate-200 bg-slate-800 text-white flex flex-wrap items-center justify-between gap-3">
                    <div className="min-w-0 flex items-center gap-4 flex-wrap">
                        <div>
                            <h3 className="font-bold text-lg sm:text-xl flex items-center gap-2">
                                <Camera className="shrink-0" size={24} /> <span className="truncate">{editingLog ? 'Editar' : 'Nuevo'} Reporte Fotográfico</span>
                            </h3>
                            <p className="text-slate-400 text-xs sm:text-sm truncate mt-0.5">
                                {editingLog ? 'Modifica el reporte' : 'Fotos y concepto por bloque'}
                            </p>
                        </div>
                        <label className="flex items-center gap-2 shrink-0">
                            <span className="text-slate-400 text-xs font-medium">Fecha:</span>
                            <input
                                type="date"
                                value={reportDate}
                                onChange={(e) => setReportDate(e.target.value)}
                                className="bg-white/10 border border-slate-500 rounded-lg px-3 py-1.5 text-sm font-medium text-white focus:ring-2 focus:ring-indigo-400 outline-none"
                            />
                        </label>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                        <button
                            type="button"
                            onClick={handleSave}
                            disabled={uploading || entries.length === 0}
                            className="bg-indigo-500 hover:bg-indigo-600 text-white font-bold px-4 py-2 rounded-xl transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed min-h-[40px] touch-manipulation"
                        >
                            {uploading ? (
                                <><span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> Guardando...</>
                            ) : (
                                <><Save size={18} /> {editingLog ? 'Actualizar' : 'Guardar'}</>
                            )}
                        </button>
                        <button type="button" onClick={onClose} className="p-2 rounded-lg text-white/70 hover:text-white hover:bg-white/10 transition touch-manipulation" aria-label="Cerrar">
                            <X size={24} />
                        </button>
                    </div>
                </div>

                {/* Contenido: bloques de fotos + concepto debajo, sin barra lateral */}
                <div className="flex-1 min-h-0 overflow-y-auto p-4 sm:p-6 bg-slate-100">
                    {entries.length === 0 ? (
                        <div className="min-h-[280px] flex flex-col items-center justify-center text-slate-500 px-4">
                            <div className="w-16 h-16 rounded-2xl bg-slate-200/80 flex items-center justify-center mb-4">
                                <Camera size={32} className="text-slate-400" />
                            </div>
                            <p className="font-semibold text-base text-slate-600 text-center">Agrega fotos y concepto</p>
                            <p className="text-sm text-slate-400 text-center mt-1">Cada bloque puede tener varias fotos y un concepto debajo.</p>
                            <button
                                type="button"
                                onClick={handleAddBlock}
                                className="mt-6 inline-flex items-center gap-2 px-5 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl transition shadow-lg shadow-indigo-200/50 min-h-[44px] touch-manipulation"
                            >
                                <Plus size={20} /> Agregar fotos y concepto
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6 max-w-3xl mx-auto">
                            {entries.map((entry, index) => (
                                <div key={entry.id} className="bg-white rounded-xl shadow-sm border-2 border-slate-200 overflow-hidden">
                                    <div className="p-4 sm:p-5">
                                        <div className="flex items-center justify-between gap-3 mb-4">
                                            <span className="text-xs font-bold text-slate-500 uppercase tracking-wide">Bloque {index + 1}</span>
                                            <button
                                                type="button"
                                                onClick={() => handleRemoveEntry(entry.id)}
                                                className="p-2 rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 transition touch-manipulation"
                                                title="Eliminar bloque"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </div>

                                        {/* Fotos */}
                                        <div className="mb-4">
                                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                                                {entry.previewUrls.map((url, idx) => (
                                                    <div key={idx} className="aspect-square relative group rounded-lg overflow-hidden border border-slate-200">
                                                        <img src={url} className="w-full h-full object-cover" alt="Evidencia" />
                                                        <button
                                                            type="button"
                                                            onClick={() => {
                                                                const newPreviewUrls = entry.previewUrls.filter((_, i) => i !== idx);
                                                                const newPhotoUrls = (entry.photoUrls || []).filter((_, i) => i !== idx);
                                                                const existingCount = (entry.photoUrls || []).length;
                                                                const newPhotos = idx >= existingCount ? entry.photos.filter((_, i) => i !== idx - existingCount) : entry.photos;
                                                                updateEntryFields(entry.id, { previewUrls: newPreviewUrls, photoUrls: newPhotoUrls, photos: newPhotos });
                                                            }}
                                                            className="absolute top-1.5 right-1.5 p-1.5 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition shadow-lg hover:bg-red-600 min-w-[28px] min-h-[28px] flex items-center justify-center"
                                                            title="Eliminar foto"
                                                        >
                                                            <Trash2 size={12} />
                                                        </button>
                                                    </div>
                                                ))}
                                                <label className="aspect-square border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-50/50 hover:border-indigo-400 transition text-slate-400 hover:text-indigo-600 touch-manipulation">
                                                    <Upload size={22} className="mb-1" />
                                                    <span className="text-xs font-bold">Subir</span>
                                                    <input type="file" accept="image/*" multiple className="hidden" onChange={(e) => handleFileChange(entry.id, e)} />
                                                </label>
                                            </div>
                                        </div>

                                        {/* Concepto debajo de las fotos (input, no select que se despliega) */}
                                        <div className="mb-4">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto</label>
                                            <input
                                                type="text"
                                                value={entry.itemName}
                                                onChange={(e) => updateEntry(entry.id, 'itemName', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl px-3 py-2.5 text-sm font-medium text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                                                placeholder="Nombre del concepto o partida"
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto general</label>
                                            <textarea
                                                value={entry.description}
                                                onChange={(e) => updateEntry(entry.id, 'description', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500 resize-none min-h-[80px]"
                                                placeholder="Concepto general de todas las fotos de este bloque..."
                                                rows={2}
                                            />
                                        </div>

                                        <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl border border-slate-100">
                                            <button
                                                type="button"
                                                onClick={() => updateEntry(entry.id, 'isCompleted', !entry.isCompleted)}
                                                className={`shrink-0 w-6 h-6 rounded-md border-2 flex items-center justify-center transition ${entry.isCompleted ? 'bg-green-500 border-green-600 text-white' : 'bg-white border-slate-300'}`}
                                                aria-checked={entry.isCompleted}
                                            >
                                                <Check size={14} strokeWidth={4} />
                                            </button>
                                            <span className="text-sm font-medium text-slate-700">Terminado (100%)</span>
                                        </div>
                                    </div>
                                </div>
                            ))}

                            <button
                                type="button"
                                onClick={handleAddBlock}
                                className="w-full py-4 border-2 border-dashed border-slate-300 rounded-xl text-slate-500 hover:border-indigo-400 hover:text-indigo-600 hover:bg-indigo-50/30 font-bold transition flex items-center justify-center gap-2 touch-manipulation"
                            >
                                <Plus size={22} /> Agregar más fotos y concepto
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PhotographicReportModal;

import React, { useState, useEffect } from 'react';
import { X, Calculator, Check, AlertTriangle, Settings } from 'lucide-react';
import { APUService } from '../../services/APUService';

const APUModal = ({ item, apuData, onClose, onApply }) => {
    const [editableData, setEditableData] = useState(null);
    const [totals, setTotals] = useState({
        materialsTotal: 0,
        laborTotal: 0,
        equipmentTotal: 0,
        minorToolsCost: 0,
        directCost: 0,
        indirectCost: 0,
        subtotal1: 0,
        financingCost: 0,
        subtotal2: 0,
        profitCost: 0,
        subtotal3: 0,
        additionalCost: 0,
        finalPrice: 0
    });

    useEffect(() => {
        if (apuData) {
            // Normalizar datos usando el servicio
            const normalized = APUService.normalizeAPUData(apuData);
            setEditableData(normalized);
        }
    }, [apuData]);

    useEffect(() => {
        if (editableData) {
            calculateTotals();
        }
    }, [editableData]);

    if (!item || !editableData) return null;

    const formatCurrency = (amount) => {
        return new Intl.NumberFormat('es-MX', {
            style: 'currency',
            currency: 'MXN'
        }).format(amount);
    };

    const formatPercent = (val) => `${(val * 100).toFixed(2)}%`;

    const calculateTotals = () => {
        // Usar el servicio para calcular todos los totales
        const calculatedTotals = APUService.calculateAPUTotals(editableData);
        setTotals(calculatedTotals);
    };

    const handleUpdateRow = (category, index, field, value) => {
        const newData = { ...editableData };
        const row = newData[category][index];
        row[field] = parseFloat(value) || 0;
        setEditableData(newData);
    };

    const handleUpdatePct = (field, value) => {
        const newData = { ...editableData };
        newData[field] = parseFloat(value) / 100;
        setEditableData(newData);
    };

    const renderLaborTable = () => (
        <div className="mb-6">
            <h3 className="text-sm font-bold uppercase tracking-wider mb-2 text-orange-700 dark:text-orange-400 border-b border-orange-200 dark:border-orange-700 pb-1">
                Mano de Obra
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-300 font-medium">
                        <tr>
                            <th className="px-3 py-2">Categoría</th>
                            <th className="px-3 py-2 w-16 text-center">Und</th>
                            <th className="px-3 py-2 w-20 text-right">Cant.</th>
                            <th className="px-3 py-2 w-24 text-right">Salario Base</th>
                            <th className="px-3 py-2 w-16 text-right">FSR</th>
                            <th className="px-3 py-2 w-24 text-right">Salario Real</th>
                            <th className="px-3 py-2 w-24 text-right">Total</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                        {(editableData.labor || []).map((row, index) => {
                            const realSalary = APUService.getRealSalary(row);
                            const itemTotal = APUService.calculateLaborItemTotal(row);
                            return (
                                <tr key={index} className="hover:bg-slate-50 dark:hover:bg-slate-800">
                                    <td className="px-3 py-2 text-slate-700 dark:text-slate-200"><input value={row.description} onChange={(e) => handleUpdateRow('labor', index, 'description', e.target.value)} className="w-full bg-transparent outline-none text-slate-700 dark:text-slate-200" /></td>
                                    <td className="px-3 py-2 text-center text-xs text-slate-600 dark:text-slate-300">{row.unit}</td>
                                    <td className="px-3 py-2 text-right"><input type="number" value={row.quantity} onChange={(e) => handleUpdateRow('labor', index, 'quantity', e.target.value)} className="w-16 text-right bg-slate-50 dark:bg-slate-700 dark:text-slate-200 rounded outline-none" /></td>
                                    <td className="px-3 py-2 text-right"><input type="number" value={row.baseSalary || row.unitPrice} onChange={(e) => handleUpdateRow('labor', index, 'baseSalary', e.target.value)} className="w-20 text-right bg-slate-50 dark:bg-slate-700 dark:text-slate-200 rounded outline-none" /></td>
                                    <td className="px-3 py-2 text-right"><input type="number" step="0.01" value={row.fsr || APUService.DEFAULT_CONFIG.defaultFSR} onChange={(e) => handleUpdateRow('labor', index, 'fsr', e.target.value)} className="w-14 text-right bg-slate-50 dark:bg-slate-700 dark:text-slate-200 rounded outline-none" /></td>
                                    <td className="px-3 py-2 text-right text-slate-500 dark:text-slate-400 text-xs">{formatCurrency(realSalary)}</td>
                                    <td className="px-3 py-2 text-right font-medium text-slate-700 dark:text-slate-200">{formatCurrency(itemTotal)}</td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );

    const renderSimpleTable = (title, key, color) => {
        const colorClasses = {
            emerald: 'text-emerald-700 dark:text-emerald-400 border-emerald-200 dark:border-emerald-700',
            slate: 'text-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-600'
        };
        return (
            <div className="mb-6">
                <h3 className={`text-sm font-bold uppercase tracking-wider mb-2 ${colorClasses[color] || colorClasses.slate} border-b pb-1`}>
                    {title}
                </h3>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-300 font-medium">
                            <tr>
                                <th className="px-3 py-2">Descripción</th>
                                <th className="px-3 py-2 w-16 text-center">Und</th>
                                <th className="px-3 py-2 w-20 text-right">Cant.</th>
                                <th className="px-3 py-2 w-24 text-right">P. Unitario</th>
                                <th className="px-3 py-2 w-24 text-right">Total</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                            {(editableData[key] || []).map((row, index) => (
                                <tr key={index} className="hover:bg-slate-50 dark:hover:bg-slate-800">
                                    <td className="px-3 py-2 text-slate-700 dark:text-slate-200"><input value={row.description} onChange={(e) => handleUpdateRow(key, index, 'description', e.target.value)} className="w-full bg-transparent outline-none text-slate-700 dark:text-slate-200" /></td>
                                    <td className="px-3 py-2 text-center text-xs text-slate-600 dark:text-slate-300">{row.unit}</td>
                                    <td className="px-3 py-2 text-right"><input type="number" value={row.quantity} onChange={(e) => handleUpdateRow(key, index, 'quantity', e.target.value)} className="w-16 text-right bg-slate-50 dark:bg-slate-700 dark:text-slate-200 rounded outline-none" /></td>
                                    <td className="px-3 py-2 text-right"><input type="number" value={row.unitPrice} onChange={(e) => handleUpdateRow(key, index, 'unitPrice', e.target.value)} className="w-20 text-right bg-slate-50 dark:bg-slate-700 dark:text-slate-200 rounded outline-none" /></td>
                                    <td className="px-3 py-2 text-right font-medium text-slate-700 dark:text-slate-200">{formatCurrency(row.quantity * row.unitPrice)}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col">
                {/* Header */}
                <div className="p-4 border-b border-slate-200 dark:border-slate-700 flex justify-between items-start bg-slate-50 dark:bg-slate-800 rounded-t-xl flex-shrink-0">
                    <div>
                        <div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-400 mb-1">
                            <Calculator size={20} />
                            <span className="font-bold text-sm uppercase tracking-wide">Análisis de Precios Unitarios (Neodata Style)</span>
                        </div>
                        <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 line-clamp-1">{item.description}</h2>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full text-slate-500 dark:text-slate-400"><X size={20} /></button>
                </div>

                {/* Content - Scrollable */}
                <div className="flex-1 overflow-y-auto p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column: Tables */}
                    <div className="lg:col-span-2 space-y-6">
                        {renderSimpleTable("Materiales", "materials", "emerald")}
                        {renderLaborTable()}
                        {renderSimpleTable("Equipo y Maquinaria", "equipment", "slate")}

                        {/* Minor Tools Row */}
                        <div className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-700 rounded border border-slate-200 dark:border-slate-600 text-sm">
                            <span className="font-medium text-slate-600 dark:text-slate-300">Herramienta Menor (% de Mano de Obra)</span>
                            <div className="flex items-center gap-4">
                                <div className="flex items-center gap-1">
                                    <input
                                        type="number"
                                        value={editableData.minorToolsPct * 100}
                                        onChange={(e) => handleUpdatePct('minorToolsPct', e.target.value)}
                                        className="w-12 text-right bg-white dark:bg-slate-600 dark:text-slate-200 border border-slate-300 dark:border-slate-500 rounded px-1"
                                    />
                                    <span className="text-slate-500 dark:text-slate-400">%</span>
                                </div>
                                <span className="font-bold text-slate-800 dark:text-slate-200 w-24 text-right">{formatCurrency(totals.minorToolsCost)}</span>
                            </div>
                        </div>
                    </div>

                    {/* Right Column: Cascade Summary */}
                    <div className="lg:col-span-1">
                        <div className="bg-slate-50 dark:bg-slate-700 p-5 rounded-xl border border-slate-200 dark:border-slate-600">
                            <h3 className="font-bold text-slate-800 dark:text-slate-100 mb-4 flex items-center gap-2">
                                <Settings size={18} /> Resumen de Costos
                            </h3>

                            <div className="space-y-3 text-sm">
                                <div className="flex justify-between text-slate-600 dark:text-slate-300">
                                    <span>Costo Directo</span>
                                    <span className="font-bold text-slate-800 dark:text-slate-100">{formatCurrency(totals.directCost)}</span>
                                </div>

                                <div className="border-t border-slate-200 dark:border-slate-600 my-2"></div>

                                <div className="flex justify-between items-center">
                                    <span className="text-slate-600 dark:text-slate-300">Indirectos</span>
                                    <div className="flex items-center gap-2">
                                        <input type="number" value={editableData.indirectsPct * 100} onChange={(e) => handleUpdatePct('indirectsPct', e.target.value)} className="w-10 text-right bg-white dark:bg-slate-600 dark:text-slate-200 border border-slate-300 dark:border-slate-500 rounded px-1 text-xs" />
                                        <span className="text-xs text-slate-400 dark:text-slate-500">%</span>
                                        <span className="w-20 text-right text-slate-700 dark:text-slate-200">{formatCurrency(totals.indirectCost)}</span>
                                    </div>
                                </div>

                                <div className="flex justify-between font-medium text-slate-700 dark:text-slate-200 bg-slate-100 dark:bg-slate-600 p-1 rounded">
                                    <span>Subtotal 1</span>
                                    <span>{formatCurrency(totals.subtotal1)}</span>
                                </div>

                                <div className="flex justify-between items-center">
                                    <span className="text-slate-600 dark:text-slate-300">Financiamiento</span>
                                    <div className="flex items-center gap-2">
                                        <input type="number" value={editableData.financingPct * 100} onChange={(e) => handleUpdatePct('financingPct', e.target.value)} className="w-10 text-right bg-white dark:bg-slate-600 dark:text-slate-200 border border-slate-300 dark:border-slate-500 rounded px-1 text-xs" />
                                        <span className="text-xs text-slate-400 dark:text-slate-500">%</span>
                                        <span className="w-20 text-right text-slate-700 dark:text-slate-200">{formatCurrency(totals.financingCost)}</span>
                                    </div>
                                </div>

                                <div className="flex justify-between font-medium text-slate-700 dark:text-slate-200 bg-slate-100 dark:bg-slate-600 p-1 rounded">
                                    <span>Subtotal 2</span>
                                    <span>{formatCurrency(totals.subtotal2)}</span>
                                </div>

                                <div className="flex justify-between items-center">
                                    <span className="text-slate-600 dark:text-slate-300">Utilidad</span>
                                    <div className="flex items-center gap-2">
                                        <input type="number" value={editableData.profitPct * 100} onChange={(e) => handleUpdatePct('profitPct', e.target.value)} className="w-10 text-right bg-white dark:bg-slate-600 dark:text-slate-200 border border-slate-300 dark:border-slate-500 rounded px-1 text-xs" />
                                        <span className="text-xs text-slate-400 dark:text-slate-500">%</span>
                                        <span className="w-20 text-right text-slate-700 dark:text-slate-200">{formatCurrency(totals.profitCost)}</span>
                                    </div>
                                </div>

                                <div className="flex justify-between items-center">
                                    <span className="text-slate-600 dark:text-slate-300">Cargos Adic.</span>
                                    <div className="flex items-center gap-2">
                                        <input type="number" value={editableData.additionalPct * 100} onChange={(e) => handleUpdatePct('additionalPct', e.target.value)} className="w-10 text-right bg-white dark:bg-slate-600 dark:text-slate-200 border border-slate-300 dark:border-slate-500 rounded px-1 text-xs" />
                                        <span className="text-xs text-slate-400 dark:text-slate-500">%</span>
                                        <span className="w-20 text-right text-slate-700 dark:text-slate-200">{formatCurrency(totals.additionalCost)}</span>
                                    </div>
                                </div>

                                <div className="border-t-2 border-slate-800 dark:border-slate-500 my-4"></div>

                                <div className="border-t-2 border-slate-800 dark:border-slate-500 my-4"></div>

                                <div className="flex justify-between items-end mb-2">
                                    <span className="font-bold text-lg text-slate-800 dark:text-slate-100">Precio Unitario</span>
                                    <span className="font-bold text-2xl text-indigo-600 dark:text-indigo-400">{formatCurrency(totals.finalPrice)}</span>
                                </div>
                                <p className="text-xs text-slate-500 dark:text-slate-400 italic">
                                    Precio por 1 {item.unit || 'unidad'} del concepto. Se aplicará como precio unitario al item.
                                </p>
                            </div>

                            <button
                                onClick={() => onApply(totals.finalPrice)}
                                className="w-full mt-6 bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-lg font-bold shadow-lg shadow-indigo-200 transition flex justify-center items-center gap-2"
                            >
                                <Check size={20} /> Aplicar Precio Final
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default APUModal;

import React, { useState, useEffect } from 'react';
import { X, Sparkles, Bot, AlertTriangle, AlertCircle, Info, CheckCircle, ArrowRight } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';

const BudgetAnalysisModal = ({ isOpen, onClose, items, projectInfo, onApplyFix }) => {
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [analysisData, setAnalysisData] = useState(null);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (isOpen && items && items.length > 0) {
            analyzeBudget();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isOpen]);

    const analyzeBudget = async () => {
        if (!items || items.length === 0) {
            setError('No hay partidas para analizar');
            return;
        }

        setIsAnalyzing(true);
        setError(null);
        setAnalysisData(null);

        try {
            const result = await AIBudgetService.analyzeBudgetStructured(items, projectInfo);
            setAnalysisData(result);
        } catch (err) {
            console.error('Error analyzing budget:', err);
            setError('Error al analizar el presupuesto. Por favor, intenta de nuevo.');
        } finally {
            setIsAnalyzing(false);
        }
    };

    const handleApplyFix = (alert) => {
        if (onApplyFix && alert.suggestedAction && alert.itemId) {
            onApplyFix(alert.itemId, alert.suggestedAction);
            // Mark alert as fixed locally (optional UI enhancement)
            setAnalysisData(prev => ({
                ...prev,
                alerts: prev.alerts.map(a =>
                    a === alert ? { ...a, fixed: true } : a
                )
            }));
        }
    };

    const handleClose = () => {
        setAnalysisData(null);
        setError(null);
        setIsAnalyzing(false);
        onClose();
    };

    if (!isOpen) return null;

    const getAlertIcon = (type) => {
        switch (type) {
            case 'critical': return <AlertTriangle className="text-red-500" size={20} />;
            case 'warning': return <AlertCircle className="text-amber-500" size={20} />;
            case 'info': return <Info className="text-blue-500" size={20} />;
            default: return <Sparkles className="text-indigo-500" size={20} />;
        }
    };

    const getAlertColor = (type) => {
        switch (type) {
            case 'critical': return 'border-red-100 bg-red-50';
            case 'warning': return 'border-amber-100 bg-amber-50';
            case 'info': return 'border-blue-100 bg-blue-50';
            default: return 'border-slate-100 bg-slate-50';
        }
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[85vh] flex flex-col overflow-hidden transform transition-all scale-100">
                {/* Header Premium */}
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-gradient-to-r from-slate-900 to-slate-800 text-white">
                    <div className="flex flex-col">
                        <h3 className="font-bold flex items-center text-lg">
                            <Sparkles className="mr-2 text-amber-400" /> Auditoría Inteligente
                        </h3>
                        <span className="text-xs text-slate-400 ml-8 flex items-center">
                            <Bot size={10} className="mr-1" /> Analizando precios para: <strong className="text-slate-200 ml-1">{projectInfo?.location || 'México'}</strong>
                        </span>
                    </div>
                    <button
                        onClick={handleClose}
                        className="text-white/60 hover:text-white hover:bg-white/10 p-1 rounded-full transition"
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* Content */}
                <div className="p-0 overflow-y-auto flex-1 bg-slate-50">
                    {isAnalyzing ? (
                        <div className="text-center py-12 space-y-6">
                            <div className="relative mx-auto w-16 h-16">
                                <div className="absolute inset-0 bg-indigo-100 rounded-full animate-ping opacity-75"></div>
                                <div className="relative bg-white p-3 rounded-full shadow-sm border border-indigo-100">
                                    <Bot size={40} className="text-indigo-600 animate-bounce" />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <h4 className="text-lg font-bold text-slate-800">Analizando Presupuesto</h4>
                                <p className="text-slate-500">Revisando precios unitarios, rendimientos y coherencia técnica...</p>
                            </div>
                        </div>
                    ) : error ? (
                        <div className="text-center py-12 space-y-4 px-8">
                            <div className="bg-red-50 p-4 rounded-xl border border-red-100 inline-block mb-2">
                                <AlertTriangle className="text-red-500 w-8 h-8 mx-auto" />
                            </div>
                            <div className="text-slate-800 font-bold">{error}</div>
                            <button
                                onClick={analyzeBudget}
                                className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold transition shadow-lg shadow-indigo-200"
                            >
                                Reintentar
                            </button>
                        </div>
                    ) : analysisData ? (
                        <div className="space-y-6 p-6">
                            {/* Summary Card */}
                            {analysisData.summary && (
                                <div className="bg-white p-5 rounded-xl border border-indigo-100 shadow-sm">
                                    <h4 className="text-xs font-bold text-indigo-500 uppercase mb-2 flex items-center">
                                        <Bot size={14} className="mr-1" /> Diagnóstico General
                                    </h4>
                                    <p className="text-slate-700 leading-relaxed">{analysisData.summary}</p>
                                </div>
                            )}

                            {/* Alerts List */}
                            <div className="space-y-3">
                                {analysisData.alerts && analysisData.alerts.length > 0 ? (
                                    analysisData.alerts.map((alert, idx) => (
                                        <div
                                            key={idx}
                                            className={`p-4 rounded-xl border ${getAlertColor(alert.type)} transition-all hover:shadow-md`}
                                        >
                                            <div className="flex gap-3 items-start">
                                                <div className="mt-0.5 shrink-0">
                                                    {alert.fixed ? <CheckCircle className="text-emerald-500" size={20} /> : getAlertIcon(alert.type)}
                                                </div>
                                                <div className="flex-1">
                                                    <h5 className={`font-bold text-sm ${alert.fixed ? 'text-slate-400 line-through' : 'text-slate-800'}`}>
                                                        {alert.title}
                                                    </h5>
                                                    <p className={`text-sm mt-1 ${alert.fixed ? 'text-slate-400' : 'text-slate-600'}`}>
                                                        {alert.message}
                                                    </p>

                                                    {/* Action Button */}
                                                    {!alert.fixed && alert.suggestedAction && (
                                                        <button
                                                            onClick={() => handleApplyFix(alert)}
                                                            className="mt-3 flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 hover:border-indigo-300 hover:text-indigo-600 text-slate-600 text-xs font-bold rounded-lg transition shadow-sm group"
                                                        >
                                                            <Sparkles size={12} className="text-indigo-500 group-hover:animate-pulse" />
                                                            {alert.suggestedAction.label || 'Aplicar Corrección'}
                                                            <ArrowRight size={12} className="opacity-0 group-hover:opacity-100 transition-opacity -ml-1 group-hover:ml-0" />
                                                        </button>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                ) : (
                                    <div className="text-center py-8 text-slate-400">
                                        <CheckCircle size={48} className="mx-auto mb-2 text-emerald-100" />
                                        <p>No se encontraron problemas críticos.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : null}
                </div>

                {/* Footer */}
                <div className="p-4 bg-white border-t border-slate-100 flex justify-between items-center">
                    {analysisData && (
                        <button
                            onClick={analyzeBudget}
                            className="px-4 py-2 text-sm text-slate-500 hover:text-slate-700 font-medium transition flex items-center"
                        >
                            <Sparkles size={14} className="mr-1" /> Reanalizar
                        </button>
                    )}
                    <button
                        onClick={handleClose}
                        className="px-6 py-2.5 bg-slate-900 text-white rounded-lg font-bold hover:bg-slate-800 transition shadow-lg shadow-slate-900/20 ml-auto"
                    >
                        Cerrar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default BudgetAnalysisModal;

import React from 'react';
import { X, Info, TrendingUp, DollarSign, Receipt } from 'lucide-react';

const CostConceptsModal = ({ isOpen, onClose, concept }) => {
