                                <ul className="space-y-2">
                                    {item.examples.map((example, exIndex) => (
                                        <li key={exIndex} className="flex items-start gap-2 text-slate-700 dark:text-slate-300">
                                            <span className="text-indigo-500 dark:text-indigo-400 mt-1">•</span>
                                            <span>{example}</span>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        ))}
                    </div>

                    {/* Footer Tip */}
                    <div className="mt-6 p-4 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg border border-indigo-200 dark:border-indigo-800">
                        <p className="text-sm text-indigo-800 dark:text-indigo-300 flex items-start gap-2">
                            <Info size={16} className="mt-0.5 flex-shrink-0" />
                            <span>
                                <strong>Tip:</strong> Estos porcentajes son guías generales. Ajusta según tu experiencia, tipo de proyecto, ubicación y condiciones del mercado. Consulta con un profesional contable o constructor para casos específicos.
                            </span>
                        </p>
                    </div>
                </div>

                {/* Footer */}
                <div className="p-4 border-t border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 rounded-b-xl">
                    <button
                        onClick={onClose}
                        className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-lg font-bold transition-colors"
                    >
                        Entendido
                    </button>
                </div>
            </div>
        </div>
    );
};

export default CostConceptsModal;

import React, { useState } from 'react';
import { Ruler, Calculator, Check, X, ArrowRight, BrainCircuit } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';

const GeneratorModal = ({ isOpen, onClose, onApply, item }) => {
    const [description, setDescription] = useState('');
    const [isCalculating, setIsCalculating] = useState(false);
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);

    if (!isOpen) return null;

    const handleCalculate = async () => {
        if (!description.trim()) return;

        setIsCalculating(true);
        setError(null);
        setResult(null);

        try {
            const data = await AIBudgetService.calculateVolume(description, item.unit);
            setResult(data);
        } catch (err) {
            setError('No se pudo calcular el volumen. Intenta ser más específico.');
        } finally {
            setIsCalculating(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden transform transition-all scale-100">
                {/* Header */}
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-gradient-to-r from-indigo-600 to-purple-600 text-white">
                    <h3 className="font-bold flex items-center text-lg">
                        <Ruler className="mr-2 text-indigo-200" /> Generador Inteligente
                    </h3>
                    <button
                        onClick={onClose}
                        className="text-white/60 hover:text-white hover:bg-white/10 p-1 rounded-full transition"
                    >
                        <X size={20} />
                    </button>
                </div>

                <div className="p-6 space-y-6">
                    {/* Item Context */}
                    <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                        <p className="text-xs text-slate-500 uppercase font-bold mb-1">Concepto</p>
                        <p className="text-sm font-medium text-slate-800 line-clamp-2">{item.description || 'Sin descripción'}</p>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-xs bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded font-bold">Unidad: {item.unit}</span>
                        </div>
                    </div>

                    {/* Input Area */}
                    <div>
                        <label className="block text-sm font-bold text-slate-700 mb-2">Describe las medidas o el área</label>
                        <textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Ej: Muro de 5 metros de largo por 3 metros de alto..."
                            className="w-full p-3 bg-white border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition resize-none text-slate-700"
                            rows={3}
                        />
                        <p className="text-xs text-slate-400 mt-1 text-right">La IA detectará las dimensiones y calculará el total.</p>
                    </div>

                    {/* Action Button */}
                    {!result && (
                        <button
                            onClick={handleCalculate}
                            disabled={isCalculating || !description.trim()}
                            className={`w-full py-3 rounded-xl font-bold flex items-center justify-center transition shadow-lg ${isCalculating || !description.trim()
                                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
                                    : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-500/30'
                                }`}
                        >
                            {isCalculating ? (
                                <>
                                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent mr-2"></div>
                                    Calculando...
                                </>
                            ) : (
                                <>
                                    <BrainCircuit size={18} className="mr-2" /> Calcular Cantidad
                                </>
                            )}
                        </button>
                    )}

                    {/* Error Message */}
                    {error && (
                        <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center">
                            <X size={16} className="mr-2 shrink-0" /> {error}
                        </div>
                    )}

                    {/* Result Area */}
                    {result && (
                        <div className="bg-emerald-50 rounded-xl border border-emerald-100 overflow-hidden animate-fadeIn">
                            <div className="p-4 border-b border-emerald-100/50">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <p className="text-xs text-emerald-600 font-bold uppercase mb-1">Resultado Calculado</p>
                                        <div className="flex items-baseline gap-1">
                                            <span className="text-3xl font-bold text-emerald-700">{result.result}</span>
                                            <span className="text-sm font-medium text-emerald-600">{item.unit}</span>
                                        </div>
                                    </div>
                                    <div className="bg-white p-2 rounded-lg shadow-sm">
                                        <code className="text-xs font-mono text-slate-600 block bg-slate-50 px-2 py-1 rounded mb-1 border border-slate-100">
                                            {result.formula}
                                        </code>
                                    </div>
                                </div>
                                <p className="text-sm text-emerald-800 mt-3 italic">
                                    "{result.explanation}"
                                </p>
                            </div>
                            <div className="p-3 bg-emerald-100/50 flex gap-3">
                                <button
                                    onClick={() => setResult(null)}
                                    className="flex-1 py-2 text-emerald-700 font-bold text-sm hover:bg-emerald-100 rounded-lg transition"
                                >
                                    Recalcular
                                </button>
                                <button
                                    onClick={() => onApply(result.result)}
                                    className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm rounded-lg shadow-sm transition flex items-center justify-center"
                                >
                                    <Check size={16} className="mr-1" /> Aplicar Cantidad
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default GeneratorModal;

import React, { useState } from 'react';
import { X, Upload, FileText, Edit3, Save, Trash2, Plus, AlertCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const PDFEditorModal = ({ isOpen, onClose }) => {
    const navigate = useNavigate();
    const [pdfFile, setPdfFile] = useState(null);
    const [isExtracting, setIsExtracting] = useState(false);
    const [extractedData, setExtractedData] = useState(null);
    const [editableItems, setEditableItems] = useState([]);
    const [projectInfo, setProjectInfo] = useState({});
    const [error, setError] = useState(null);

    const handleFileSelect = (e) => {
        const file = e.target.files[0];
        if (file && file.type === 'application/pdf') {
            setPdfFile(file);
            setError(null);
        } else {
            setError('Por favor selecciona un archivo PDF válido');
        }
    };

    const handleDrop = (e) => {
        e.preventDefault();
        const file = e.dataTransfer.files[0];
        if (file && file.type === 'application/pdf') {
            setPdfFile(file);
            setError(null);
        } else {
            setError('Por favor selecciona un archivo PDF válido');
        }
    };

    const handleExtract = async () => {
        if (!pdfFile) return;

        setIsExtracting(true);
        setError(null);

        const formData = new FormData();
        formData.append('file', pdfFile);

        try {
            const response = await fetch('/api/ai/extract-pdf', {
                method: 'POST',
                body: formData
            });

            if (!response.ok) {
                const err = await response.json();
                throw new Error(err.error || 'Error al extraer PDF');
            }

            const data = await response.json();

            if (data.success) {
                setExtractedData(data);
                setEditableItems(data.items || []);
                setProjectInfo(data.projectInfo || {});
            } else {
                throw new Error('No se pudieron extraer datos del PDF');
            }
        } catch (err) {
            console.error(err);
            setError(err.message || 'Error al procesar el PDF');
        } finally {
            setIsExtracting(false);
        }
    };

    const handleUpdateItem = (index, field, value) => {
        const updated = [...editableItems];
        updated[index] = { ...updated[index], [field]: value };
        setEditableItems(updated);
    };

    const handleDeleteItem = (index) => {
        setEditableItems(editableItems.filter((_, i) => i !== index));
    };

    const handleAddItem = () => {
        setEditableItems([
            ...editableItems,
            {
                description: '',
                unit: 'pza',
                quantity: 0,
                unitPrice: 0,
                category: 'Materiales'
            }
        ]);
    };

    const handleSaveAsProject = () => {
        // Guardar en localStorage para que el Editor lo cargue
        const projectData = {
            projectInfo: {
                ...projectInfo,
                id: `pdf-import-${Date.now()}`,
                project: projectInfo.project || 'Presupuesto desde PDF'
            },
            items: editableItems.map((item, index) => ({
                ...item,
                id: `item-${index}-${Date.now()}`
            }))
        };

        localStorage.setItem('pendingPDFImport', JSON.stringify(projectData));

        // Navegar al editor
        navigate('/editor');
        onClose();
    };

    const calculateTotals = () => {
        const subtotal = editableItems.reduce((sum, item) =>
            sum + (item.quantity * item.unitPrice), 0
        );
        const tax = subtotal * ((projectInfo.taxRate || 16) / 100);
        const total = subtotal + tax;
        return { subtotal, tax, total };
    };

    const totals = calculateTotals();

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                {/* Header */}
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="bg-indigo-100 dark:bg-indigo-900/30 p-3 rounded-xl">
                            <FileText className="text-indigo-600 dark:text-indigo-400" size={24} />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100">
                                Cargar y Editar PDF
                            </h2>
                            <p className="text-sm text-slate-500 dark:text-slate-400">
                                Importa presupuestos desde PDF y edítalos antes de guardar
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition"
                    >
                        <X size={24} className="text-slate-600 dark:text-slate-300" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {!extractedData ? (
                        // Upload Section
                        <div className="space-y-6">
                            <div
                                onDrop={handleDrop}
                                onDragOver={(e) => e.preventDefault()}
                                className="border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-12 text-center hover:border-indigo-500 dark:hover:border-indigo-400 transition cursor-pointer"
                                onClick={() => document.getElementById('pdf-file-input').click()}
                            >
                                <Upload className="mx-auto text-slate-400 dark:text-slate-500 mb-4" size={48} />
                                <p className="text-lg font-medium text-slate-700 dark:text-slate-200 mb-2">
                                    {pdfFile ? pdfFile.name : 'Arrastra un PDF aquí o haz clic para seleccionar'}
                                </p>
                                <p className="text-sm text-slate-500 dark:text-slate-400">
                                    Soporta presupuestos en formato PDF
                                </p>
                                <input
                                    id="pdf-file-input"
                                    type="file"
                                    accept="application/pdf"
                                    onChange={handleFileSelect}
                                    className="hidden"
                                />
                            </div>

                            {error && (
                                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4 flex items-start gap-3">
                                    <AlertCircle className="text-red-600 dark:text-red-400 flex-shrink-0" size={20} />
                                    <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
                                </div>
                            )}

                            {pdfFile && (
                                <button
                                    onClick={handleExtract}
                                    disabled={isExtracting}
                                    className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white py-3 rounded-xl font-medium transition flex items-center justify-center gap-2"
                                >
                                    {isExtracting ? (
                                        <>
                                            <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent" />
                                            Extrayendo datos con IA...
                                        </>
                                    ) : (
                                        <>
                                            <Edit3 size={20} />
                                            Extraer y Editar
                                        </>
                                    )}
                                </button>
                            )}
                        </div>
                    ) : (
                        // Editor Section
                        <div className="space-y-6">
                            {/* Project Info */}
                            <div className="bg-slate-50 dark:bg-slate-900/50 rounded-xl p-6 space-y-4">
                                <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100 mb-4">
                                    Información del Proyecto
                                </h3>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    <div>
                                        <label className="block text-xs font-medium text-slate-600 dark:text-slate-400 mb-1">
                                            Proyecto
                                        </label>
                                        <input
                                            type="text"
                                            value={projectInfo.project || ''}
                                            onChange={(e) => setProjectInfo({ ...projectInfo, project: e.target.value })}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-lg text-sm"
                                            placeholder="Nombre del proyecto"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-medium text-slate-600 dark:text-slate-400 mb-1">
                                            Cliente
                                        </label>
                                        <input
                                            type="text"
                                            value={projectInfo.client || ''}
                                            onChange={(e) => setProjectInfo({ ...projectInfo, client: e.target.value })}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-lg text-sm"
                                            placeholder="Nombre del cliente"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-medium text-slate-600 dark:text-slate-400 mb-1">
                                            Ubicación
                                        </label>
                                        <input
                                            type="text"
                                            value={projectInfo.location || ''}
                                            onChange={(e) => setProjectInfo({ ...projectInfo, location: e.target.value })}
                                            className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-lg text-sm"
                                            placeholder="Ciudad, Estado"
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Items Table */}
                            <div>
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100">
                                        Conceptos ({editableItems.length})
                                    </h3>
                                    <button
                                        onClick={handleAddItem}
                                        className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-medium transition"
                                    >
                                        <Plus size={16} />
                                        Agregar Concepto
                                    </button>
                                </div>

                                <div className="overflow-x-auto">
                                    <table className="w-full text-sm">
                                        <thead className="bg-slate-100 dark:bg-slate-900/50">
                                            <tr>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">#</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">Descripción</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">Unidad</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">Cantidad</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">P.U.</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">Categoría</th>
                                                <th className="px-3 py-2 text-left text-xs font-medium text-slate-600 dark:text-slate-400">Total</th>
                                                <th className="px-3 py-2 text-xs font-medium text-slate-600 dark:text-slate-400"></th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
                                            {editableItems.map((item, index) => (
                                                <tr key={index} className="hover:bg-slate-50 dark:hover:bg-slate-900/30">
                                                    <td className="px-3 py-2 text-slate-600 dark:text-slate-400">{index + 1}</td>
                                                    <td className="px-3 py-2">
                                                        <input
                                                            type="text"
                                                            value={item.description}
                                                            onChange={(e) => handleUpdateItem(index, 'description', e.target.value)}
                                                            className="w-full px-2 py-1 bg-transparent border border-transparent hover:border-slate-300 dark:hover:border-slate-600 focus:border-indigo-500 rounded text-slate-700 dark:text-slate-200"
                                                        />
                                                    </td>
                                                    <td className="px-3 py-2">
                                                        <input
                                                            type="text"
                                                            value={item.unit}
                                                            onChange={(e) => handleUpdateItem(index, 'unit', e.target.value)}
                                                            className="w-20 px-2 py-1 bg-transparent border border-transparent hover:border-slate-300 dark:hover:border-slate-600 focus:border-indigo-500 rounded text-slate-700 dark:text-slate-200"
