                                >
                                    <Key size={14} />
                                    Cambiar Contraseña
                                </button>
                                <button
                                    onClick={handleLogout}
                                    className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg text-sm font-medium transition"
                                >
                                    <LogOut size={14} />
                                    Cerrar Sesión
                                </button>
                            </div>
                        )}
                    </>
                ) : (
                    isExpanded && (
                        <div className="bg-slate-800/50 rounded-xl p-4 block border border-slate-700">
                            <p className="text-xs text-slate-400 mb-2">Modo Local</p>
                            <button
                                onClick={() => navigate('/login')}
                                className="w-full px-3 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm font-medium transition"
                            >
                                Iniciar Sesión
                            </button>
                        </div>
                    )
                )}
            </div>

            {/* Change Password Modal */}
            <ChangePasswordModal
                isOpen={showChangePasswordModal}
                onClose={() => setShowChangePasswordModal(false)}
            />
        </aside>
    );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { Package, Sparkles, X, AlertTriangle, Loader } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';
import ProjectPersistenceService from '../../services/ProjectPersistenceService';
import MaterialModal from './MaterialModal';

/**
 * MaterialGenerator
 * Componente independiente para generar listas de materiales/insumos con IA
 * Maneja toda la lógica de generación, validación y persistencia
 */
const MaterialGenerator = ({
    items = [],
    projectInfo = {},
    projectId = null,
    materialList: initialMaterialList = [],
    materialAssumptions: initialMaterialAssumptions = [],
    onMaterialsGenerated = null,
    onClose = null,
    showToast = null
}) => {
    const [materialList, setMaterialList] = useState(initialMaterialList);
    const [materialAssumptions, setMaterialAssumptions] = useState(initialMaterialAssumptions);
    const [isGenerating, setIsGenerating] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState(null);

    // Sincronizar cuando cambien las props
    useEffect(() => {
        if (initialMaterialList !== null) {
            setMaterialList(initialMaterialList);
        }
        if (initialMaterialAssumptions !== null) {
            setMaterialAssumptions(initialMaterialAssumptions);
        }
    }, [initialMaterialList, initialMaterialAssumptions]);

    // Validar items antes de generar
    const validateItems = () => {
        if (!items || items.length === 0) {
            return { valid: false, message: 'Agrega partidas antes de generar la lista de insumos' };
        }
        return { valid: true };
    };

    // Abrir modal o generar
    const handleOpenMaterials = () => {
        const validation = validateItems();
        if (!validation.valid) {
            if (showToast) {
                showToast(validation.message, 'warning');
            } else {
                setError(validation.message);
            }
            return;
        }

        // Si ya existe lista de materiales VÁLIDA, abrir el visualizador
        const hasValidMaterials = materialList && Array.isArray(materialList) && materialList.length > 0;

        if (hasValidMaterials) {
            setShowModal(true);
            return;
        }

        // Si no existe, generar directamente
        handleGenerateMaterials();
    };

    // Generar materiales con IA
    const handleGenerateMaterials = async (forceRegenerate = false) => {
        if (items.length === 0) {
            if (showToast) {
                showToast('Agrega partidas primero para generar insumos', 'warning');
            }
            return;
        }

        // Si ya existe y no se fuerza regeneración, solo mostrar
        if (materialList.length > 0 && !forceRegenerate) {
            setShowModal(true);
            return;
        }

        setIsGenerating(true);
        setError(null);
        setShowModal(true);

        try {
            const { materials, assumptions } = await AIBudgetService.generateMaterialTakeoff(items);
            setMaterialList(materials);
            setMaterialAssumptions(assumptions || []);

            // Auto-guardar si hay projectId
            if (projectId && materials) {
                try {
                    // Guardar mediante el guardado del proyecto completo
                    // El autoguardado se encargará de guardarlo
                    if (showToast) {
                        showToast('Lista de insumos generada exitosamente. Se guardará automáticamente.', 'success');
                    }
                } catch (err) {
                    console.error('Error saving materials:', err);
                }
            }

            // Callback opcional
            if (onMaterialsGenerated) {
                onMaterialsGenerated(materials, assumptions || []);
            }
        } catch (error) {
            console.error('Error generating materials:', error);
            const errorMessage = error.message || 'Error al generar la lista de insumos';
            setError(errorMessage);
            if (showToast) {
                showToast(errorMessage, 'error');
            }
            setMaterialList([]);
            setMaterialAssumptions([]);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleClose = () => {
        setShowModal(false);
        if (onClose) {
            onClose();
        }
    };

    // Función para regenerar materiales
    const handleRegenerate = () => {
        setShowModal(false);
        handleGenerateMaterials(true);
    };

    // Actualizar materiales cuando se editen
    const handleMaterialsUpdate = (updatedList, updatedAssumptions) => {
        setMaterialList(updatedList);
        setMaterialAssumptions(updatedAssumptions || []);
        
        // Callback para notificar al componente padre
        if (onMaterialsGenerated) {
            onMaterialsGenerated(updatedList, updatedAssumptions || []);
        }
    };

    return (
        <>
            {/* Botón de Generar/Ver Insumos */}
            <button
                onClick={handleOpenMaterials}
                disabled={isGenerating || !items || items.length === 0}
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg font-bold shadow-lg transition-all text-sm
                    ${isGenerating || !items || items.length === 0
                        ? 'bg-slate-700 text-slate-500 cursor-not-allowed shadow-none'
                        : 'bg-indigo-500 hover:bg-indigo-600 text-white shadow-indigo-900/20'
                    }
                `}
                title={!items || items.length === 0 ? 'Agrega partidas primero' : materialList.length > 0 ? 'Ver Lista de Insumos' : 'Generar Lista de Insumos con IA'}
            >
                {isGenerating ? (
                    <>
                        <Loader className="animate-spin" size={16} />
                        <span>Generando...</span>
                    </>
                ) : (
                    <>
                        <Package size={16} />
                        <span className="hidden sm:inline">Insumos</span>
                    </>
                )}
            </button>

            {/* Modal de Materiales */}
            {showModal && (
                <MaterialModal
                    isOpen={showModal}
                    onClose={handleClose}
                    materialList={materialList}
                    materialAssumptions={materialAssumptions}
                    isGenerating={isGenerating}
                    onRegenerate={handleRegenerate}
                    onMaterialsUpdate={handleMaterialsUpdate}
                    projectInfo={projectInfo}
                    error={error}
                />
            )}

            {/* Mensaje de Error (si no hay showToast) */}
            {error && !showToast && (
                <div className="fixed bottom-4 right-4 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 z-50 animate-fadeIn">
                    <AlertTriangle size={20} />
                    <span className="text-sm font-medium">{error}</span>
                    <button
                        onClick={() => setError(null)}
                        className="text-red-600 hover:text-red-800"
                    >
                        <X size={16} />
                    </button>
                </div>
            )}
        </>
    );
};

export default MaterialGenerator;

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Package, X, Sparkles, AlertTriangle, Printer, Plus, Trash2, ChevronDown, ChevronUp, Info } from 'lucide-react';
import { formatCurrency } from '../../utils/format';
import { PDFService } from '../../services/PDFService';

/**
 * MaterialModal
 * Modal para visualizar y editar la lista de insumos/materiales
 */
const MaterialModal = ({
    isOpen,
    onClose,
    materialList: initialMaterialList = [],
    materialAssumptions: initialMaterialAssumptions = [],
    isGenerating = false,
    onRegenerate = null,
    onMaterialsUpdate = null,
    projectInfo = {},
    error = null
}) => {
    const [materialList, setMaterialList] = useState(initialMaterialList);
    const [materialAssumptions, setMaterialAssumptions] = useState(initialMaterialAssumptions);
    const [showAssumptions, setShowAssumptions] = useState(false); // Colapsado por defecto

    // Sincronizar cuando cambien las props
    useEffect(() => {
        setMaterialList(initialMaterialList);
        setMaterialAssumptions(initialMaterialAssumptions);
    }, [initialMaterialList, initialMaterialAssumptions]);

    // Notificar cambios al componente padre solo cuando se actualiza manualmente
    // No usar useEffect para evitar loops infinitos - se llama directamente en las funciones de manejo

    const handleUpdateMaterial = (idx, field, value) => {
        const newList = [...materialList];
        newList[idx][field] = value;
        setMaterialList(newList);
        // NO notificar inmediatamente para evitar loops - se notificará al cerrar el modal
    };

    const handleDeleteMaterial = (idx) => {
        const newList = materialList.filter((_, i) => i !== idx);
        setMaterialList(newList);
        // NO notificar inmediatamente para evitar loops - se notificará al cerrar el modal
    };

    const handleAddMaterial = () => {
        const newList = [...materialList, {
            material: 'Nuevo Material',
            unit: 'pza',
            quantity: 1,
            unitPrice: 0,
            category: 'Materiales',
            notes: ''
        }];
        setMaterialList(newList);
        // NO notificar inmediatamente para evitar loops - se notificará al cerrar el modal
    };

    // Notificar cambios cuando se cierra el modal
    const handleClose = () => {
        // Notificar cambios finales antes de cerrar
        if (onMaterialsUpdate) {
            onMaterialsUpdate(materialList, materialAssumptions);
        }
        if (onClose) {
            onClose();
        }
    };

    const handleExportPDF = () => {
        PDFService.exportMaterials(projectInfo, materialList);
    };

    if (!isOpen) return null;

    const modalContent = (
        <>
            {/* Overlay de fondo que cubre TODA la pantalla, incluido el sidebar */}
            <div 
                className="fixed top-0 left-0 right-0 bottom-0 bg-slate-900/80 backdrop-blur-md animate-fadeIn" 
                style={{ 
                    zIndex: 999999,
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    width: '100vw',
                    height: '100vh'
                }}
                onClick={handleClose}
            />
            {/* Contenedor centrado del modal */}
            <div 
                className="fixed top-0 left-0 right-0 bottom-0 flex items-center justify-center pointer-events-none animate-fadeIn" 
                style={{ 
                    zIndex: 1000000,
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    width: '100vw',
                    height: '100vh',
                    padding: '1rem'
                }}
            >
                <div 
                    className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-5xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-slate-200 dark:border-slate-700 relative pointer-events-auto"
                    style={{ 
                        zIndex: 1000001,
                        position: 'relative'
                    }}
                    onClick={(e) => e.stopPropagation()}
                >
                {/* Header */}
                <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-gradient-to-r from-indigo-900 to-indigo-800 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-lg">
                            <Package className="mr-2 text-indigo-300" /> Explosión de Insumos (Estimada)
                        </h3>
                        {materialList.length > 0 && (
                            <p className="text-xs text-indigo-200 mt-1">
                                Lista guardada - Puedes editar o regenerar con IA
                            </p>
                        )}
                    </div>
                    <div className="flex items-center gap-2">
                        {onRegenerate && materialList.length > 0 && (
                            <button
                                onClick={onRegenerate}
                                disabled={isGenerating}
                                className="px-3 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-white text-xs font-medium rounded-lg transition flex items-center gap-1 disabled:opacity-50"
                                title="Regenerar lista con IA"
                            >
                                <Sparkles size={14} />
                                Regenerar
                            </button>
                        )}
                        <button onClick={handleClose} className="text-white/60 hover:text-white transition">
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Content */}
                <div className="p-0 overflow-y-auto flex-1 bg-slate-50 dark:bg-slate-700/50">
                    {isGenerating ? (
                        <div className="flex flex-col items-center justify-center h-64 space-y-4">
                            <div className="animate-spin rounded-full h-12 w-12 border-4 border-indigo-500 border-t-transparent"></div>
                            <p className="text-slate-500 dark:text-slate-300 font-medium">Calculando materiales necesarios...</p>
                        </div>
                    ) : error ? (
                        <div className="p-12 text-center">
                            <AlertTriangle className="mx-auto mb-4 text-red-500" size={48} />
                            <p className="text-red-600 dark:text-red-400 font-medium mb-2">Error al generar insumos</p>
                            <p className="text-sm text-slate-600 dark:text-slate-400">{error}</p>
                        </div>
                    ) : materialList.length > 0 ? (
                        <div className="flex flex-col h-full">
                            {/* Base Técnica - Colapsable y discreta */}
                            {materialAssumptions.length > 0 && (
                                <div className="bg-slate-100 dark:bg-slate-700/30 border-b border-slate-200 dark:border-slate-600">
                                    <button
                                        onClick={() => setShowAssumptions(!showAssumptions)}
                                        className="w-full p-3 flex items-center justify-between hover:bg-slate-200 dark:hover:bg-slate-700/50 transition text-left"
                                    >
                                        <div className="flex items-center gap-2">
                                            <Info className="text-slate-500 dark:text-slate-400" size={16} />
                                            <span className="text-xs font-medium text-slate-600 dark:text-slate-300">
                                                Base de Cálculo
                                            </span>
                                            <span className="text-xs text-slate-400 dark:text-slate-500">
                                                ({materialAssumptions.length} parámetros)
                                            </span>
