                                </div>

                                {/* Recursos */}
                                {selectedTask.resources && selectedTask.resources.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Wrench size={16} className="text-blue-600" />
                                            <h4 className="font-bold text-slate-700">Recursos Clave</h4>
