import React, { useState, useEffect } from 'react';
import { Calendar, X, Sparkles, AlertTriangle, CheckCircle, Loader } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';
import ProjectPersistenceService from '../../services/ProjectPersistenceService';
import ScheduleModal from '../budget/ScheduleModal';

/**
 * ScheduleGenerator
 * Componente independiente para generar cronogramas de obra con IA
 * Maneja toda la lógica de generación, validación y persistencia
 */
const ScheduleGenerator = ({
    items = [],
    projectInfo = {},
    projectId = null,
    scheduleData: initialScheduleData = null,
    onScheduleGenerated = null,
    onClose = null,
    showToast = null,
    onSaveToBitacora = null
}) => {
    const [scheduleData, setScheduleData] = useState(initialScheduleData);
    const [isGenerating, setIsGenerating] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState(null);
    const [showConfigModal, setShowConfigModal] = useState(false);
    const [config, setConfig] = useState({
        startDate: new Date().toISOString().split('T')[0],
        workDays: {
            mon: true,
            tue: true,
            wed: true,
            thu: true,
            fri: true,
            sat: true,
            sun: false
        },
        notes: ''
    });

    // Sincronizar scheduleData cuando cambie la prop
    useEffect(() => {
        if (initialScheduleData !== null) {
            setScheduleData(initialScheduleData);
        }
    }, [initialScheduleData]);

    // Validar items antes de generar
    const validateItems = () => {
        if (!items || items.length === 0) {
            return { valid: false, message: 'Agrega partidas antes de generar el cronograma' };
        }

        const hasZeroQuantity = items.some(item => item.quantity <= 0);
        if (hasZeroQuantity) {
            return {
                valid: false,
                message: 'Hay partidas con cantidad 0. Por favor completa las cantidades antes de continuar.'
            };
        }

        return { valid: true };
    };

    // Abrir modal de configuración
    const handleOpenConfig = () => {
        const validation = validateItems();
        if (!validation.valid) {
            if (showToast) {
                showToast(validation.message, 'warning');
            } else {
                setError(validation.message);
            }
            return;
        }

        // Si ya existe cronograma VÁLIDO, abrir el visualizador sin regenerar
        // Si existe pero está vacío o inválido, permitir configurar uno nuevo
        const hasValidSchedule = scheduleData && (
            (scheduleData.tasks && Array.isArray(scheduleData.tasks) && scheduleData.tasks.length > 0) ||
            (scheduleData.phases && Array.isArray(scheduleData.phases) && scheduleData.phases.length > 0)
        );

        if (hasValidSchedule) {
            setShowModal(true);
            return;
        }

        setShowConfigModal(true);
    };

    // Generar cronograma con IA (llamado desde el modal de config)
    const handleGenerateSchedule = async () => {
        setShowConfigModal(false);
        setIsGenerating(true);
        setError(null);
        setShowModal(true);

        try {
            const data = await AIBudgetService.generateSchedule(items, projectInfo, config);
            setScheduleData(data);

            // Auto-guardar si hay projectId
            if (projectId && data) {
                try {
                    await ProjectPersistenceService.syncSchedule(projectId, data);
                    if (showToast) {
                        showToast('Cronograma generado y guardado exitosamente', 'success');
                    }
                } catch (err) {
                    console.error('Error saving schedule:', err);
                    // No mostrar error al usuario, el cronograma se generó correctamente
                }
            }

            // Callback opcional
            if (onScheduleGenerated) {
                onScheduleGenerated(data);
            }
        } catch (error) {
            console.error('Error generating schedule:', error);
            const errorMessage = error.message || 'Error al generar el cronograma';
            setError(errorMessage);
            if (showToast) {
                showToast(errorMessage, 'error');
            }
            setScheduleData(null);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleClose = () => {
        setShowModal(false);
        if (onClose) {
            onClose();
        }
    };

    // Función para regenerar cronograma
    const handleRegenerate = () => {
        setShowModal(false);
        setShowConfigModal(true);
    };

    const handleSaveToBitacoraInternal = async () => {
        if (!projectId) {
            if (showToast) {
                showToast('Guarda el proyecto antes de ir a la bitácora', 'warning');
            }
            return;
        }

        // Guardar cronograma si no está guardado
        if (scheduleData && projectId) {
            try {
                await ProjectPersistenceService.syncSchedule(projectId, scheduleData);
            } catch (err) {
                console.error('Error saving schedule:', err);
            }
        }

        // Usar callback del padre si existe
        if (onSaveToBitacora) {
            onSaveToBitacora();
        } else if (onClose) {
            onClose();
        }
    };

    const toggleWorkDay = (day) => {
        setConfig(prev => ({
            ...prev,
            workDays: {
                ...prev.workDays,
                [day]: !prev.workDays[day]
            }
        }));
    };

    return (
        <>
            {/* Botón de Generar Cronograma */}
            <button
                onClick={handleOpenConfig}
                disabled={isGenerating || !items || items.length === 0}
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all
                    ${isGenerating || !items || items.length === 0
                        ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                        : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-900/20 hover:shadow-xl transform hover:-translate-y-0.5'
                    }
                `}
                title={!items || items.length === 0 ? 'Agrega partidas primero' : 'Generar Cronograma con IA'}
            >
                {isGenerating ? (
                    <>
                        <Loader className="animate-spin" size={18} />
                        <span>Generando...</span>
                    </>
                ) : (
                    <>
                        <Calendar size={18} />
                        <span>Cronograma</span>
                    </>
                )}
            </button>

            {/* Modal de Configuración */}
            {showConfigModal && (
                <div className="fixed inset-0 z-[90] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-xl shadow-2xl max-w-md w-full overflow-hidden">
                        <div className="p-5 border-b border-slate-100 bg-slate-50">
                            <h3 className="font-bold text-lg text-slate-800">Configurar Cronograma</h3>
                            <p className="text-xs text-slate-500">Define los parámetros para la IA</p>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1">Fecha de Inicio</label>
                                <input
                                    type="date"
                                    value={config.startDate}
                                    onChange={(e) => setConfig({ ...config, startDate: e.target.value })}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500 outline-none"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-2">Días Laborables</label>
                                <div className="flex flex-wrap gap-2">
                                    {[
                                        { key: 'mon', label: 'L' },
                                        { key: 'tue', label: 'M' },
                                        { key: 'wed', label: 'X' },
                                        { key: 'thu', label: 'J' },
                                        { key: 'fri', label: 'V' },
                                        { key: 'sat', label: 'S' },
                                        { key: 'sun', label: 'D' },
                                    ].map((day) => (
                                        <button
                                            key={day.key}
                                            onClick={() => toggleWorkDay(day.key)}
                                            className={`w-8 h-8 rounded-full text-xs font-bold flex items-center justify-center transition-colors ${config.workDays[day.key]
                                                    ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                                                    : 'bg-slate-100 text-slate-400 border border-slate-200'
                                                }`}
                                        >
                                            {day.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1">Restricciones / Notas</label>
                                <textarea
                                    value={config.notes}
                                    onChange={(e) => setConfig({ ...config, notes: e.target.value })}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-700 h-20 resize-none focus:ring-2 focus:ring-emerald-500 outline-none"
                                    placeholder="Ej: La cimentación depende de permisos, lluvias esperadas en semana 2..."
                                />
                            </div>
                        </div>
                        <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
                            <button
                                onClick={() => setShowConfigModal(false)}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition"
                            >
                                Cancelar
                            </button>
                            <button
                                onClick={handleGenerateSchedule}
                                className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-bold shadow-lg shadow-emerald-200 transition flex items-center gap-2"
                            >
                                <Sparkles size={16} />
                                Generar con IA
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Cronograma */}
            {
                showModal && (
                    <ScheduleModal
                        isOpen={showModal}
                        onClose={handleClose}
                        scheduleData={scheduleData}
                        isGenerating={isGenerating}
                        onSaveToBitacora={handleSaveToBitacoraInternal}
                        error={error}
                        projectId={projectId}
                        onRegenerate={handleRegenerate}
                        onScheduleUpdate={async (updatedSchedule) => {
                            setScheduleData(updatedSchedule);
                            // Guardar actualización si hay projectId
                            if (projectId && updatedSchedule) {
                                try {
                                    await ProjectPersistenceService.syncSchedule(projectId, updatedSchedule);
                                    if (showToast) {
                                        showToast('Cronograma actualizado', 'success');
                                    }
                                } catch (err) {
                                    console.error('Error saving schedule update:', err);
                                }
                            }
                        }}
                    />
                )
            }

            {/* Mensaje de Error (si no hay showToast) */}
            {
                error && !showToast && (
                    <div className="fixed bottom-4 right-4 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 z-50 animate-fadeIn">
                        <AlertTriangle size={20} />
                        <span className="text-sm font-medium">{error}</span>
                        <button
                            onClick={() => setError(null)}
                            className="text-red-600 hover:text-red-800"
                        >
                            <X size={16} />
                        </button>
                    </div>
                )
            }
        </>
    );
};

export default ScheduleGenerator;

import React, { useState, useEffect } from 'react';
import { Share2, X, Copy, Check, Lock, Calendar, Trash2, Eye, ExternalLink, Settings, Clock } from 'lucide-react';
import { ShareService } from '../../services/ShareService';

const ShareProjectModal = ({ isOpen, onClose, projectId, projectName }) => {
    const [shares, setShares] = useState([]);
    const [loading, setLoading] = useState(false);
    const [creating, setCreating] = useState(false);
    const [copiedToken, setCopiedToken] = useState(null);
    const [shareConfig, setShareConfig] = useState({
        expiresIn: null, // días
        password: '',
        includeShortCode: true,
        canEdit: false,
        showSchedule: true // Por defecto mostrar cronograma
    });

    useEffect(() => {
        if (isOpen && projectId) {
            loadShares();
        }
    }, [isOpen, projectId]);

    const loadShares = async () => {
        try {
            setLoading(true);
            const data = await ShareService.getProjectShares(projectId);
            setShares(data || []);
        } catch (error) {
            console.error('Error loading shares:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateShare = async () => {
        if (!projectId) return;

        try {
            setCreating(true);
            
            const expiresAt = shareConfig.expiresIn 
                ? new Date(Date.now() + shareConfig.expiresIn * 24 * 60 * 60 * 1000).toISOString()
                : null;

            const share = await ShareService.createShare(projectId, {
                expiresAt,
                password: shareConfig.password || null,
                includeShortCode: shareConfig.includeShortCode,
                canEdit: shareConfig.canEdit,
                metadata: {
                    showSchedule: shareConfig.showSchedule
                }
            });

            // Recargar lista
            await loadShares();

            // Resetear config
            setShareConfig({
                expiresIn: null,
                password: '',
                includeShortCode: true,
                canEdit: false,
                showSchedule: true
            });

            // Copiar automáticamente
            copyToClipboard(share.shareUrl);
        } catch (error) {
            console.error('Error creating share:', error);
            const errorMessage = error.message || 'Error al crear el enlace compartido. Verifica que el proyecto esté guardado y que la tabla project_shares exista en Supabase.';
            alert(errorMessage);
        } finally {
            setCreating(false);
        }
    };

    const copyToClipboard = async (text) => {
        try {
            await navigator.clipboard.writeText(text);
            setCopiedToken(text);
            setTimeout(() => setCopiedToken(null), 2000);
        } catch (error) {
            console.error('Error copying to clipboard:', error);
        }
    };

    const handleDeleteShare = async (shareId) => {
        if (!confirm('¿Eliminar este enlace compartido?')) return;

        try {
            await ShareService.deleteShare(shareId);
            await loadShares();
        } catch (error) {
            console.error('Error deleting share:', error);
            alert('Error al eliminar el enlace');
        }
    };

    const formatExpiresAt = (date) => {
        if (!date) return 'Sin expiración';
        const expires = new Date(date);
        const now = new Date();
        const diffDays = Math.ceil((expires - now) / (1000 * 60 * 60 * 24));
        
        if (diffDays < 0) return 'Expirado';
        if (diffDays === 0) return 'Expira hoy';
        if (diffDays === 1) return 'Expira mañana';
        return `Expira en ${diffDays} días`;
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 dark:bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-slate-200 dark:border-slate-700">
                {/* Header */}
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-xl">
                            <Share2 className="mr-2 text-emerald-200" size={24} />
                            Compartir Presupuesto
                        </h3>
                        <p className="text-sm text-emerald-100 mt-1">{projectName}</p>
                    </div>
                    <button onClick={onClose} className="text-white/80 hover:text-white transition">
                        <X size={24} />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {/* Crear nuevo enlace */}
                    <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-600">
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Crear Nuevo Enlace Compartido</h4>
                        
                        <div className="space-y-4">
                            {/* Opciones de expiración */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Expiración (opcional)
                                </label>
                                <select
                                    value={shareConfig.expiresIn || ''}
                                    onChange={(e) => setShareConfig({ ...shareConfig, expiresIn: e.target.value ? parseInt(e.target.value) : null })}
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200"
                                >
                                    <option value="">Sin expiración</option>
                                    <option value="1">1 día</option>
                                    <option value="7">7 días</option>
                                    <option value="30">30 días</option>
                                    <option value="90">90 días</option>
                                </select>
                            </div>

                            {/* Contraseña opcional */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Contraseña (opcional)
                                </label>
                                <input
                                    type="password"
                                    value={shareConfig.password}
                                    onChange={(e) => setShareConfig({ ...shareConfig, password: e.target.value })}
                                    placeholder="Dejar vacío para sin contraseña"
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200 placeholder:text-slate-400 dark:placeholder:text-slate-500"
                                />
                            </div>

                            {/* Opciones adicionales */}
                            <div className="space-y-3">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.includeShortCode}
                                        onChange={(e) => setShareConfig({ ...shareConfig, includeShortCode: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">Generar código corto</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.showSchedule}
                                        onChange={(e) => setShareConfig({ ...shareConfig, showSchedule: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">
                                        Mostrar cronograma al cliente
                                        <span className="text-xs text-slate-500 dark:text-slate-400 ml-1">(si existe)</span>
                                    </span>
                                </label>
                            </div>

                            <button
                                onClick={handleCreateShare}
                                disabled={creating}
                                className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {creating ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                                        Creando...
                                    </>
                                ) : (
                                    <>
                                        <Share2 size={20} />
                                        Crear Enlace Compartido
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {/* Lista de enlaces existentes */}
                    <div>
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Enlaces Compartidos Activos</h4>
                        
                        {loading ? (
                            <div className="text-center py-8">
                                <div className="animate-spin rounded-full h-8 w-8 border-4 border-emerald-500 border-t-transparent mx-auto mb-2"></div>
                                <p className="text-slate-600 dark:text-slate-400 text-sm">Cargando...</p>
                            </div>
                        ) : shares.length === 0 ? (
                            <div className="text-center py-8 bg-slate-50 dark:bg-slate-700/50 rounded-lg border-2 border-dashed border-slate-300 dark:border-slate-600">
                                <Share2 className="mx-auto mb-3 text-slate-400 dark:text-slate-500" size={32} />
                                <p className="text-slate-600 dark:text-slate-300">No hay enlaces compartidos aún</p>
                                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Crea uno usando el formulario de arriba</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {shares.map((share) => {
                                    const isExpired = share.expires_at && new Date(share.expires_at) < new Date();
                                    const isCopied = copiedToken === share.shareUrl;

                                    return (
                                        <div
                                            key={share.id}
                                            className={`rounded-lg border-2 p-4 ${
                                                isExpired 
                                                    ? 'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20' 
                                                    : 'border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-700/50'
                                            }`}
                                        >
                                            <div className="flex items-start justify-between gap-4">
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center gap-2 mb-2">
                                                        <ExternalLink size={16} className="text-slate-400 dark:text-slate-500" />
                                                        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 truncate">
                                                            {share.shareUrl}
                                                        </span>
                                                        {share.password && (
                                                            <Lock size={14} className="text-amber-600 dark:text-amber-500" />
                                                        )}
                                                        {isExpired && (
                                                            <span className="px-2 py-0.5 bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-400 rounded text-xs font-bold">
                                                                Expirado
                                                            </span>
                                                        )}
                                                    </div>

                                                    {share.shortUrl && (
                                                        <div className="flex items-center gap-2 mb-2">
                                                            <span className="text-xs text-slate-400 dark:text-slate-500">Código corto:</span>
                                                            <span className="text-xs font-mono text-slate-600 dark:text-slate-300">{share.shortUrl}</span>
                                                        </div>
                                                    )}

                                                    <div className="flex items-center gap-4 text-xs text-slate-500 dark:text-slate-400">
                                                        <div className="flex items-center gap-1">
                                                            <Eye size={12} />
                                                            <span>{share.access_count || 0} vistas</span>
                                                        </div>
                                                        <div className="flex items-center gap-1">
                                                            <Calendar size={12} />
                                                            <span>{formatExpiresAt(share.expires_at)}</span>
                                                        </div>
                                                        {share.last_accessed_at && (
                                                            <div className="flex items-center gap-1">
                                                                <Clock size={12} />
                                                                <span>Último acceso: {new Date(share.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-2 shrink-0">
                                                    <button
                                                        onClick={() => copyToClipboard(share.shareUrl)}
                                                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded-lg transition"
                                                        title="Copiar enlace"
                                                    >
                                                        {isCopied ? (
                                                            <Check size={18} className="text-emerald-600 dark:text-emerald-400" />
                                                        ) : (
                                                            <Copy size={18} className="text-slate-600 dark:text-slate-400" />
                                                        )}
                                                    </button>
                                                    <button
                                                        onClick={() => window.open(share.shareUrl, '_blank')}
                                                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded-lg transition"
                                                        title="Abrir enlace"
                                                    >
                                                        <ExternalLink size={18} className="text-slate-600 dark:text-slate-400" />
                                                    </button>
                                                    <button
                                                        onClick={() => handleDeleteShare(share.id)}
                                                        className="p-2 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg transition"
                                                        title="Eliminar enlace"
                                                    >
                                                        <Trash2 size={18} className="text-red-600 dark:text-red-400" />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </div>

                {/* Footer */}
                <div className="p-4 bg-slate-50 dark:bg-slate-700/50 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center text-xs text-slate-500 dark:text-slate-400">
                    <p>Los enlaces compartidos permiten ver el presupuesto sin crear cuenta</p>
                    <button onClick={onClose} className="px-4 py-2 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600 rounded-lg font-medium transition">
                        Cerrar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ShareProjectModal;

import React from 'react';
import { X, Crown, AlertCircle, ArrowRight } from 'lucide-react';
import { SubscriptionService } from '../../services/SubscriptionService';
import { usePricingModal } from '../../context/PricingModalContext';

const LimitModal = ({ isOpen, onClose, actionType, usage, limit }) => {
    const { openPricingModal } = usePricingModal();

    if (!isOpen) return null;

    const message = SubscriptionService.getLimitMessage(actionType, SubscriptionService.PLANS.FREE);

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 relative">
                <button
                    onClick={onClose}
                    className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"
                >
                    <X size={24} />
                </button>

                <div className="text-center mb-6">
                    <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-r from-amber-500 to-orange-500 rounded-full mb-4">
                        <AlertCircle className="text-white" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-900 mb-2">
                        Límite Alcanzado
                    </h2>
                    <p className="text-slate-600">
                        {message}
                    </p>
                </div>

                {/* Usage Stats */}
                <div className="bg-slate-50 rounded-xl p-4 mb-6">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm text-slate-600">Uso actual</span>
                        <span className="text-sm font-bold text-slate-900">
                            {usage} / {limit}
                        </span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2">
                        <div
                            className="bg-gradient-to-r from-amber-500 to-orange-500 h-2 rounded-full"
                            style={{ width: '100%' }}
                        ></div>
                    </div>
                </div>

                {/* Features Comparison */}
                <div className="bg-gradient-to-r from-purple-50 to-pink-50 rounded-xl p-4 mb-6">
                    <div className="flex items-center gap-2 mb-3">
                        <Crown className="text-purple-600" size={20} />
                        <span className="font-bold text-purple-900">Con Pro obtienes:</span>
                    </div>
                    <ul className="space-y-2 text-sm text-purple-800">
                        <li>• Uso ilimitado de todas las funciones</li>
                        <li>• Presupuestos ilimitados</li>
                        <li>• IA ilimitada</li>
                        <li>• Bitácoras y reportes ilimitados</li>
                        <li>• Soporte prioritario</li>
                    </ul>
                </div>

                {/* Actions */}
                <div className="flex flex-col gap-3">
                    <button
                        onClick={() => {
                            onClose();
                            openPricingModal();
                        }}
                        className="w-full py-3 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white rounded-xl font-bold transition shadow-lg shadow-indigo-500/50 flex items-center justify-center gap-2"
                    >
                        <Crown size={20} />
                        Ver Planes y Precios
                        <ArrowRight size={20} />
                    </button>
                    <button
                        onClick={onClose}
                        className="w-full py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-medium transition"
                    >
                        Cerrar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default LimitModal;

import React from 'react';
import { X, Check, Zap, Crown, ArrowRight, Sparkles, Shield, CheckCircle, Smartphone } from 'lucide-react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useSubscription } from '../../context/SubscriptionContext';
import { SubscriptionService } from '../../services/SubscriptionService';

const PricingModal = ({ isOpen, onClose, previewData = null }) => {
    const { plan } = useSubscription();
    const [pricingData, setPricingData] = React.useState(null);
    const [loading, setLoading] = React.useState(true);
    const [showPayment, setShowPayment] = React.useState(false);

    React.useEffect(() => {
        const loadData = async () => {
            if (previewData) {
                setPricingData(previewData);
                setLoading(false);
                return;
            }

            try {
                const data = await SubscriptionService.getPricingData();
                setPricingData(data);
            } catch (error) {
                console.error('Error loading pricing data:', error);
            } finally {
                setLoading(false);
            }
        };

        if (isOpen) {
            loadData();
        }
    }, [isOpen, previewData]);

    // Reset payment view when modal closes or opens
    React.useEffect(() => {
        if (!isOpen) {
            setShowPayment(false);
        }
    }, [isOpen]);

    if (!isOpen) return null;

    // Default features as fallback
    const defaultFeatures = {
        free: [],
        pro: []
    };

    const plans = [
        {
            id: 'free',
            name: 'Gratis',
            price: 0,
            description: pricingData?.free?.description || 'Perfecto para probar la plataforma',
            icon: Zap,
            iconBg: 'bg-blue-100',
            iconColor: 'text-blue-600',
            borderColor: 'border-slate-200',
            hoverBorder: 'hover:border-blue-300',
            features: (pricingData?.free?.features || defaultFeatures.free).map(text => ({ text, included: true }))
        },
        {
            id: 'pro',
            name: 'Pro',
            price: pricingData?.pro?.price || 299,
            description: pricingData?.pro?.description || 'Para profesionales que necesitan más',
            icon: Crown,
            iconBg: 'bg-indigo-100',
            iconColor: 'text-indigo-600',
            borderColor: 'border-indigo-500',
            hoverBorder: 'hover:border-indigo-600',
            popular: true,
            features: (pricingData?.pro?.features || defaultFeatures.pro).map(text => ({ text, included: true }))
        }
    ];

    const handleUpgrade = (planId) => {
        if (planId === 'pro') {
            setShowPayment(true);
        } else {
            // Logic for downgrading to free if needed
            console.log('Downgrade to free requested');
        }
    };

    const handleCopyInstructions = () => {
        const textToCopy = pricingData?.bankDetails || '';
        navigator.clipboard.writeText(textToCopy);
        // Could add a toast here but for now just simple copy
    };

    const handleWhatsAppClick = () => {
        const text = encodeURIComponent(`Hola, acabo de realizar mi transferencia para el Plan Pro. Mi correo es: [TU CORREO AQUÍ]`);
        window.open(`https://wa.me/5216677981504?text=${text}`, '_blank');
    };

    if (showPayment) {
        return (
            <div
                className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-fadeIn"
                onClick={onClose}
            >
                <div
                    className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col border border-slate-200 dark:border-slate-800"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-2xl translate-x-1/2 -translate-y-1/2"></div>
                        <h2 className="text-2xl font-bold relative z-10">¡Excelente Elección! 🚀</h2>
                        <p className="text-indigo-100 text-sm relative z-10">Estás a un paso de activar tu cuenta Pro</p>
                        <button onClick={() => setShowPayment(false)} className="absolute top-4 left-4 text-white/70 hover:text-white transition z-50">
                            <ArrowRight className="rotate-180" size={20} />
                        </button>
                    </div>

                    <div className="p-8 space-y-6">
                        <div className="bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-200 dark:border-yellow-800 rounded-xl p-4">
                            <p className="text-sm text-yellow-800 dark:text-yellow-200 text-center">
                                Por el momento los pagos son <strong>manuales vía transferencia</strong>.
                            </p>
                        </div>

                        <div className="space-y-2">
                            <div className="flex justify-between items-center mb-2">
                                <h3 className="font-bold text-slate-700 dark:text-slate-300 uppercase text-xs tracking-wider">Instrucciones de Pago</h3>
                                <button
                                    onClick={handleCopyInstructions}
                                    className="text-xs text-indigo-600 hover:text-indigo-700 font-bold flex items-center gap-1 bg-indigo-50 px-2 py-1 rounded-full transition-colors"
                                >
                                    COPIAR DATOS
                                </button>
                            </div>
                            <div className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-5 rounded-2xl text-left text-sm leading-relaxed text-slate-700 dark:text-slate-300">
                                {renderMarkdown(pricingData?.bankDetails || 'Datos bancarios no configurados. Contacta a soporte.')}
                            </div>
                        </div>

                        <div className="pt-2">
                            <button
                                onClick={handleWhatsAppClick}
                                className="w-full bg-[#25D366] hover:bg-[#20bd5a] text-white font-bold py-3.5 rounded-xl flex items-center justify-center gap-2 transition-transform hover:-translate-y-0.5 shadow-lg shadow-green-500/20"
                            >
                                <Smartphone size={20} />
                                Enviar Comprobante por WhatsApp
                            </button>
                            <p className="text-xs text-center text-slate-400 mt-3">
                                Tu cuenta será activada manualmente en cuanto verifiquemos tu pago.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-fadeIn"
            onClick={onClose}
        >
            <div
                className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col transform transition-all scale-100 border border-slate-200 dark:border-slate-800"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Compact Header */}
                <div className="relative bg-gradient-to-r from-blue-700 via-indigo-700 to-purple-700 text-white p-6 overflow-hidden shrink-0">
                    {/* Decorative background shapes */}
                    <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-2xl"></div>
                    <div className="absolute bottom-0 left-0 w-32 h-32 bg-purple-500/20 rounded-full translate-y-1/2 -translate-x-1/2 blur-xl"></div>

                    <button
                        onClick={onClose}
                        className="absolute top-4 right-4 text-white/70 hover:text-white transition p-2 hover:bg-white/10 rounded-full z-50"
                    >
                        <X size={20} />
                    </button>

                    <div className="flex flex-col items-center text-center relative z-10">
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 backdrop-blur-sm border border-white/20 text-xs font-medium mb-3 text-blue-100">
                            <Sparkles size={12} className="text-yellow-300" />
                            <span>Sube de nivel tu productividad</span>
                        </div>
                        <h2 className="text-2xl md:text-3xl font-bold mb-1 tracking-tight">Elige tu Plan Ideal</h2>
                        <p className="text-blue-100 text-sm max-w-lg mx-auto leading-relaxed opacity-90">
                            Desbloquea todo el potencial de la IA para tus presupuestos
                        </p>
                    </div>
                </div>

                {/* Scrollable Content */}
                <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-slate-50 dark:bg-slate-950/50">
                    <div className="grid md:grid-cols-2 gap-6 max-w-3xl mx-auto items-start">
                        {plans.map((planOption) => {
                            const Icon = planOption.icon;
                            const isCurrentPlan = plan.id === planOption.id;
                            const isPro = planOption.id === 'pro';

                            return (
                                <div
                                    key={planOption.id}
                                    className={`relative rounded-2xl transition-all duration-300 ${isPro
                                        ? 'bg-white dark:bg-slate-900 border-2 border-indigo-500 shadow-xl shadow-indigo-500/10 scale-[1.02] md:-mt-2 z-10'
                                        : 'bg-white/80 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm hover:shadow-md'
                                        }`}
                                >
                                    {isPro && (
                                        <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 z-20">
                                            <span className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white px-3 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider shadow-lg border border-white/20">
                                                Recomendado
                                            </span>
                                        </div>
                                    )}

                                    <div className={`p-6 ${isPro ? 'pt-8' : ''}`}>
                                        <div className="flex justify-between items-start mb-4">
                                            <div>
                                                <h3 className={`text-lg font-bold ${isPro ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-700 dark:text-slate-300'}`}>
                                                    {planOption.name}
                                                </h3>
                                                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 min-h-[32px] md:min-h-0">
                                                    {planOption.description}
                                                </p>
                                            </div>
                                            <div className={`p-2.5 rounded-xl ${planOption.iconBg} ${planOption.iconColor}`}>
                                                <Icon size={20} />
                                            </div>
                                        </div>

                                        <div className="flex items-baseline gap-1 mb-6">
                                            <span className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">
                                                ${planOption.price}
                                            </span>
                                            {planOption.price > 0 && (
                                                <span className="text-slate-500 text-sm font-medium">/mes</span>
                                            )}
                                        </div>

                                        <button
                                            onClick={isCurrentPlan ? undefined : () => handleUpgrade(planOption.id)}
                                            disabled={isCurrentPlan}
                                            className={`w-full py-2.5 rounded-lg text-sm font-bold transition-all mb-6 flex items-center justify-center gap-2 ${isCurrentPlan
                                                ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 cursor-default'
                                                : isPro
                                                    ? 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white shadow-lg shadow-indigo-500/25 hover:shadow-indigo-500/40 transform hover:-translate-y-0.5'
                                                    : 'bg-white border-2 border-slate-200 hover:border-slate-300 text-slate-600 hover:text-slate-800'
                                                }`}
                                        >
                                            {isCurrentPlan ? (
                                                <>Plan Actual <CheckCircle size={14} /></>
                                            ) : isPro ? (
                                                <>Actualizar Ahora <Sparkles size={14} /></>
                                            ) : (
                                                'Continuar Gratis'
                                            )}
                                        </button>

                                        <div className="space-y-3">
                                            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">
                                                Incluye:
                                            </div>
                                            {planOption.features.map((feature, index) => (
                                                <div key={index} className="flex items-start gap-2.5 group">
                                                    <div className={`mt-0.5 shrink-0 w-4 h-4 rounded-full flex items-center justify-center ${isPro ? 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400' : 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'
                                                        }`}>
                                                        <Check size={10} strokeWidth={3} />
                                                    </div>
                                                    <span className={`text-sm ${isPro ? 'text-slate-700 dark:text-slate-200 font-medium' : 'text-slate-600 dark:text-slate-400'}`}>
                                                        {feature.text}
                                                    </span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Footer Minimal */}
                <div className="p-4 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-center">
                    <p className="text-xs text-slate-400 dark:text-slate-500 flex items-center justify-center gap-4">
                        <span className="flex items-center gap-1"><Shield size={12} /> Pago Seguro</span>
                        <span className="flex items-center gap-1"><Zap size={12} /> Cancelación en cualquier momento</span>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default PricingModal;

import React, { useEffect, useState } from 'react';
import { useSubscription } from '../../context/SubscriptionContext';
import { AlertTriangle, X, Crown, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { SubscriptionService } from '../../services/SubscriptionService';
import { usePricingModal } from '../../context/PricingModalContext';

const UsageNotification = () => {
    const { plan, usage, isPro } = useSubscription();
    const navigate = useNavigate();
    const { openPricingModal } = usePricingModal();
    const [warnings, setWarnings] = useState([]);
    const [dismissed, setDismissed] = useState({});

    useEffect(() => {
        if (isPro) return; // No mostrar notificaciones para usuarios Pro

        const newWarnings = [];
        Object.keys(plan.limits).forEach(key => {
            const limit = plan.limits[key];
            const current = usage[key] || 0;
            
            if (limit !== -1) {
                const percentage = (current / limit) * 100;
                
                // Mostrar advertencia si está entre 80% y 100%
                if (percentage >= 80 && percentage < 100 && !dismissed[key]) {
                    const limitName = {
                        budgets: 'Presupuestos',
                        aiGenerations: 'Generaciones con IA',
                        aiDescriptions: 'Descripciones con IA',
                        aiPriceSuggestions: 'Sugerencias de Precio',
                        bitacoraEntries: 'Bitácoras',
                        photoReports: 'Reportes Fotográficos',
                        pdfExports: 'Exportaciones PDF',
                        catalogItems: 'Items en Catálogo'
                    }[key] || key;

                    newWarnings.push({
                        key,
                        name: limitName,
                        current,
                        limit,
                        percentage: Math.round(percentage),
                        remaining: limit - current
                    });
                }
            }
        });

        setWarnings(newWarnings);
    }, [plan, usage, isPro, dismissed]);

    const handleDismiss = (key) => {
        setDismissed(prev => ({ ...prev, [key]: true }));
    };

    if (isPro || warnings.length === 0) return null;

    return (
        <div className="fixed bottom-4 right-4 z-50 space-y-3 max-w-md">
            {warnings.map((warning) => (
                <div
                    key={warning.key}
                    className="bg-white rounded-xl shadow-2xl border-2 border-amber-200 p-4 animate-slide-up"
                >
                    <div className="flex items-start gap-3">
                        <div className="p-2 bg-amber-100 rounded-lg">
                            <AlertTriangle className="text-amber-600" size={20} />
                        </div>
                        <div className="flex-1">
                            <h4 className="font-bold text-slate-900 mb-1">
                                Límite cercano: {warning.name}
                            </h4>
                            <p className="text-sm text-slate-600 mb-2">
                                Has usado {warning.current} de {warning.limit} ({warning.percentage}%). 
                                Te quedan {warning.remaining} usos.
                            </p>
                            <div className="w-full bg-slate-200 rounded-full h-2 mb-3">
                                <div
                                    className="bg-amber-500 h-2 rounded-full transition-all"
                                    style={{ width: `${warning.percentage}%` }}
                                ></div>
                            </div>
                            <div className="flex gap-2">
                                <button
                                    onClick={openPricingModal}
                                    className="flex-1 px-3 py-1.5 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white rounded-lg text-xs font-bold transition flex items-center justify-center gap-1"
                                >
                                    <Crown size={14} />
                                    Actualizar
                                </button>
                                <button
                                    onClick={() => navigate('/usage')}
                                    className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-medium transition"
                                >
                                    Ver Detalles
                                </button>
                            </div>
                        </div>
                        <button
                            onClick={() => handleDismiss(warning.key)}
                            className="text-slate-400 hover:text-slate-600 transition"
                        >
                            <X size={18} />
                        </button>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default UsageNotification;

import React, { useState, useEffect, useRef } from 'react';
import { systemSettingsService } from '../../services/SystemSettingsService';
import {
    MessageCircle,
    X,
    Send,
    Loader,
    Bot,
    User,
    Phone,
    Sparkles,
    ChevronDown,
    RefreshCw,
    ExternalLink,
    AlertTriangle
} from 'lucide-react';
import { SupportAIService } from '../../services/SupportAIService';
import { useSubscription } from '../../context/SubscriptionContext';
import { useProject } from '../../context/ProjectContext';
import { useAuth } from '../../context/AuthContext';
import { useError } from '../../context/ErrorContext';
import { ErrorService } from '../../services/ErrorService';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useLocation } from 'react-router-dom';

const SupportChat = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState([]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [showQuickReplies, setShowQuickReplies] = useState(true);
    const [isMinimized, setIsMinimized] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);
    const [errorReportMode, setErrorReportMode] = useState(false);
    const [whatsappNumber, setWhatsappNumber] = useState('522811975587'); // Default fallback

    const messagesEndRef = useRef(null);
    const inputRef = useRef(null);
    const { plan } = useSubscription();
    const { user } = useAuth();
    const { showRateLimitModal } = useProject();
    const errorContext = useError(); // Retorna funciones por defecto si no está disponible
    const location = useLocation();

    // Get user's first name
    const getUserFirstName = () => {
        if (!user) return '';

        // Try to get from user metadata
        const fullName = user.user_metadata?.full_name || user.email?.split('@')[0] || '';

        // Get first name only
        const firstName = fullName.split(' ')[0];

        // Capitalize first letter
        return firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
    };

    // Scroll to bottom when new messages arrive
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages]);

    // Focus input when chat opens
    useEffect(() => {
        if (isOpen && inputRef.current) {
            inputRef.current.focus();
        }
    }, [isOpen]);

    // Initialize chat with personalized welcome message
    useEffect(() => {
        if (isOpen && messages.length === 0) {
            const firstName = getUserFirstName();
            const greeting = firstName
                ? `¡Hola ${firstName}! 👋`
                : '¡Hola! 👋';

            setMessages([{
                id: 1,
                type: 'bot',
                text: `${greeting} Soy Geni, tu asistente de PresuGenius. Estoy aquí para ayudarte con lo que necesites. ¿Cómo puedo apoyarte hoy?`,
                timestamp: new Date()
            }]);
        }
    }, [isOpen, user, messages]); // AÃ±adir 'messages' a las dependencias

    // Reset unread count when chat opens
    useEffect(() => {
        if (isOpen) {
            setUnreadCount(0);
        }
    }, [isOpen]);

    // Escuchar evento para abrir el chat desde otros componentes
    useEffect(() => {
        const handleOpenSupport = (event) => {
            if (event.detail?.errorReport) {
                setIsOpen(true);
                setErrorReportMode(true);
                // Auto-enviar mensaje sobre el error
                setTimeout(() => {
                    handleSendMessage('Tengo un error en la plataforma');
                }, 300);
            } else {
                setIsOpen(true);
            }
        };

        window.addEventListener('openSupportChat', handleOpenSupport);
        return () => window.removeEventListener('openSupportChat', handleOpenSupport);
    }, []);

    // Cargar configuración dinámica
    useEffect(() => {
        const loadSettings = async () => {
            const number = await systemSettingsService.getSetting('whatsapp_number');
            if (number) setWhatsappNumber(number);
        };
        loadSettings();
    }, []);

    const isProcessingRef = useRef(false);

    const handleSendMessage = async (text = inputValue) => {
        if (!text.trim() || isProcessingRef.current) return;

        isProcessingRef.current = true;
        setIsLoading(true);

        const userMessage = {
            id: Date.now(),
            type: 'user',
            text: text.trim(),
            timestamp: new Date()
        };

        setMessages(prev => [...prev, userMessage]);
        setInputValue('');
        setShowQuickReplies(false);

        // Check if user wants human support
        if (text.toLowerCase().includes('humano') || text.toLowerCase().includes('whatsapp') || text.toLowerCase().includes('persona')) {
            setTimeout(() => {
            setMessages(prev => [...prev, {
                id: Date.now(),
                type: 'bot',
                text: '¡Entendido! Con gusto te pongo en contacto con nuestro equipo. 🧑‍💻\n\nPara una atención más personalizada, puedes escribirnos directamente por WhatsApp. ¡Haz clic en el botón de abajo para empezar a chatear!',
                timestamp: new Date(),
                showWhatsApp: true
            }]);
                setIsLoading(false);
                isProcessingRef.current = false;
            }, 500);
            return;
        }

        // Check if user is reporting an error
        const errorKeywords = ['error', 'falla', 'no funciona', 'problema', 'bug', 'no carga', 'no abre', 'crashea', 'se traba'];
        const isReportingError = errorKeywords.some(keyword => text.toLowerCase().includes(keyword));

        if (isReportingError && !errorReportMode) {
            setErrorReportMode(true);

            // Intentar obtener el último error automáticamente
            const lastError = errorContext.getLastError ? errorContext.getLastError() : null;
            const errorDetails = lastError && errorContext.formatErrorForSupport ? errorContext.formatErrorForSupport() : null;

            setTimeout(() => {
                let helpMessage = `¡Oh no! Parece que hay un problema técnico. No te preocupes, estoy aquí para ayudarte a resolverlo. 🛠️\n\n`;

                if (errorDetails) {
                    helpMessage += `✅ **¡Buena noticia! He detectado un error reciente en tu sesión y lo estoy analizando automáticamente.** Esto nos ayudará mucho.\n\nPara que podamos darte la mejor solución, por favor cuéntame:\n\n1. **¿Qué estabas haciendo justo antes de que apareciera el error?**\n2. **¿Qué fue lo que viste o pasó exactamente?**\n\nSi tienes el mensaje de error exacto, ¡copiarlo y pegarlo sería genial!`;
                } else {
                    helpMessage += `Para que pueda ayudarte de la mejor manera, por favor cuéntame un poco más:\n\n1. **¿Qué estabas intentando hacer cuando ocurrió el problema?**\n2. **¿Apareció algún mensaje de error? Si es así, ¿cuál fue?**\n3. **¿En qué parte de la plataforma estabas?**\n\nCualquier detalle que me des, ¡por pequeño que sea, es de gran ayuda!`;
                }

                setMessages(prev => [...prev, {
                    id: Date.now(),
                    type: 'bot',
                    text: helpMessage,
                    timestamp: new Date(),
                    isErrorHelp: true,
                    hasAutoDetectedError: !!errorDetails,
                    autoErrorDetails: errorDetails
                }]);
                setIsLoading(false);
                isProcessingRef.current = false;
            }, 500);
            return;
        }

        try {
            // Obtener detalles del error si está en modo de reporte
            let errorDetails = null;
            if (errorReportMode && errorContext.getLastError && errorContext.formatErrorForSupport) {
                const lastError = errorContext.getLastError();
                if (lastError) {
                    errorDetails = errorContext.formatErrorForSupport();
                }
            }

            const response = await SupportAIService.sendMessage(text, {
                plan: plan?.name || 'Gratis',
                currentPage: location.pathname,
                userName: getUserFirstName(),
                userEmail: user?.email,
                isErrorReport: errorReportMode,
                errorDetails: errorDetails
            });

            // Reset error mode after getting response
            if (errorReportMode) {
                setErrorReportMode(false);
            }

            // Manejar errores de Rate Limit o mostrar respuesta exitosa
            if (!response.success && response.error && (response.message.includes('límite') || response.message.includes('espera'))) {
                const retryMatch = response.message.match(/espera (\d+)s/);
                const retryAfter = retryMatch ? parseInt(retryMatch[1]) : 60;
                showRateLimitModal(response.message, retryAfter);
            }

            // Detectar respuesta vacía, genérica o sin información útil
            const genericResponses = [
                '',
                'No tengo información suficiente para responder a eso.',
                'Lo siento, no tengo información sobre eso.',
                'Lo siento, tuve un problema al procesar tu mensaje.'
            ];
            const isGeneric =
                !response.message ||
                genericResponses.includes(response.message.trim()) ||
                (response.message.trim().toLowerCase().startsWith('lo siento') && response.message.trim().length < 80);

            let botMessage = {
                id: Date.now(),
                type: 'bot',
                text: response.message || "Lo siento, tuve un problema al procesar tu mensaje.",
                sender: 'bot',
                timestamp: new Date(),
                isError: !response.success || response.isError,
                showWhatsApp: response.showWhatsApp || false
            };

            if (isGeneric) {
                botMessage = {
                    ...botMessage,
                    text: 'No tengo información suficiente para responder a eso. Si lo deseas, puedes reformular tu pregunta o contactar a soporte humano por WhatsApp.',
                    showWhatsApp: true,
                    isError: true
                };
            }

            setMessages(prev => [...prev, botMessage]);

            if (!isOpen) {
                setUnreadCount(prev => prev + 1);
            }
        } catch (error) {
            console.error('Error sending message:', error);

            // Capturar el error para que pueda ser reportado
            ErrorService.logError(error, 'SupportChat.handleSendMessage');

            setMessages(prev => [...prev, {
                id: Date.now(),
                type: 'bot',
                text: '¡Ups! 😬 Parece que estoy teniendo algunos problemas técnicos en este momento. No te preocupes, nuestro equipo ya está al tanto y trabajando para solucionarlo.\n\nMientras tanto, si necesitas ayuda urgente, por favor contáctanos directamente por WhatsApp: +52 281 197 5587. ¡Estaremos encantados de ayudarte!',
                timestamp: new Date(),
                isError: true,
                showWhatsApp: true
            }]);
        } finally {
            setIsLoading(false);
            isProcessingRef.current = false;
        }
    };

    const handleQuickReply = (reply) => {
        if (reply.text === 'Hablar con soporte humano') {
            handleSendMessage('Quiero hablar con soporte humano');
        } else {
            handleSendMessage(reply.text);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSendMessage();
        }
    };

    const resetChat = () => {
        SupportAIService.resetChat();
        setErrorReportMode(false);
        const firstName = getUserFirstName();
        const greeting = firstName ? `¡Hola de nuevo ${firstName}!` : '¡Hola de nuevo!';
        setMessages([{
            id: Date.now(),
            type: 'bot',
            text: `${greeting} 👋 ¡Listo para seguir ayudándote! ¿Qué tienes en mente hoy?`,
            timestamp: new Date()
        }]);
        setShowQuickReplies(true);
    };

    const openWhatsApp = () => {
        const message = encodeURIComponent('Hola, necesito ayuda con PresuGenius');
        window.open(`https://wa.me/${whatsappNumber}?text=${message}`, '_blank');
    };

    const quickReplies = SupportAIService.getQuickReplies();

    return (
        <>
            {/* Floating Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`fixed bottom-6 right-6 z-50 w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all duration-300 transform hover:scale-110 ${isOpen
                    ? 'bg-slate-700 rotate-0'
                    : 'bg-gradient-to-r from-blue-600 to-purple-600 animate-pulse-slow'
                    }`}
            >
                {isOpen ? (
                    <X className="w-6 h-6 text-white" />
                ) : (
                    <>
                        <MessageCircle className="w-6 h-6 text-white" />
                        {unreadCount > 0 && (
                            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center font-bold animate-bounce">
                                {unreadCount}
                            </span>
                        )}
                    </>
                )}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className={`fixed bottom-24 right-6 z-50 w-96 max-w-[calc(100vw-3rem)] bg-white dark:bg-slate-800 rounded-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 transition-all duration-300 flex flex-col ${isMinimized ? 'h-14' : 'h-[500px] max-h-[70vh]'
                    }`}>
                    {/* Header */}
                    <div
                        className="bg-gradient-to-r from-blue-600 via-purple-600 to-blue-600 p-4 flex items-center justify-between cursor-pointer shadow-xl relative overflow-hidden"
                        onClick={() => setIsMinimized(!isMinimized)}
                    >
                        {/* Efecto de brillo sutil animado */}
                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent animate-shimmer"></div>

                        <div className="flex items-center gap-3 relative z-10">
                            <div className="w-11 h-11 bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center shadow-lg border border-white/30 ring-2 ring-white/20">
                                <Bot className="w-6 h-6 text-white drop-shadow-sm" />
                            </div>
                            <div>
                                <h3 className="text-white font-bold text-base leading-tight drop-shadow-sm">Geni - Soporte</h3>
                                <p className="text-white/95 text-xs flex items-center gap-1.5 mt-0.5">
                                    <span className="relative flex items-center justify-center">
                                        <span className="absolute w-2.5 h-2.5 bg-green-400 rounded-full animate-ping opacity-75"></span>
                                        <span className="relative w-2 h-2 bg-green-400 rounded-full block ring-2 ring-green-400/50"></span>
                                    </span>
                                    <span className="font-semibold">En línea</span>
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-1 relative z-10">
                            <button
                                onClick={(e) => { e.stopPropagation(); resetChat(); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95 group"
                                title="Reiniciar chat"
                            >
                                <RefreshCw className="w-4 h-4 text-white group-hover:rotate-180 transition-transform duration-500" />
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); openWhatsApp(); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95"
                                title="WhatsApp"
                            >
                                <Phone className="w-4 h-4 text-white" />
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95"
                                title={isMinimized ? 'Expandir' : 'Minimizar'}
                            >
                                <ChevronDown className={`w-5 h-5 text-white transition-transform duration-300 ${isMinimized ? 'rotate-180' : ''}`} />
                            </button>
                        </div>
                    </div>

                    {!isMinimized && (
                        <>
                            {/* Messages */}
                            <div className="flex-1 overflow-y-auto p-4 space-y-4 h-[calc(100%-140px)] bg-slate-50 dark:bg-slate-900 scrollbar-hide">
                                {messages.map((message) => (
                                    <div
                                        key={message.id}
                                        className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
                                    >
                                        <div className={`flex items-start gap-2 max-w-[85%] ${message.type === 'user' ? 'flex-row-reverse' : ''}`}>
                                            {/* Avatar */}
                                            <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${message.type === 'user'
                                                ? 'bg-blue-600'
                                                : 'bg-gradient-to-br from-purple-500 to-blue-500'
                                                }`}>
                                                {message.type === 'user' ? (
                                                    <User className="w-4 h-4 text-white" />
                                                ) : (
                                                    <Sparkles className="w-4 h-4 text-white" />
                                                )}
                                            </div>

                                            {/* Message Bubble */}
                                            <div className={`rounded-2xl px-4 py-2.5 ${message.type === 'user'
                                                ? 'bg-blue-600 text-white rounded-tr-sm'
                                                : message.isError
                                                    ? 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200 rounded-tl-sm'
                                                    : message.isErrorHelp
                                                        ? 'bg-amber-50 dark:bg-amber-900/30 text-amber-800 dark:text-amber-200 rounded-tl-sm border border-amber-200 dark:border-amber-700'
                                                        : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 shadow-sm rounded-tl-sm'
                                                }`}>
                                                {message.isErrorHelp && (
                                                    <div className="flex items-center gap-2 mb-2 text-amber-600 dark:text-amber-400">
                                                        <AlertTriangle className="w-4 h-4" />
                                                        <span className="text-xs font-semibold">Modo Diagnóstico</span>
                                                    </div>
                                                )}
                                                <div className="text-sm leading-relaxed">
                                                    {renderMarkdown(message.text)}
                                                </div>

                                                {/* WhatsApp Button */}
                                                {message.showWhatsApp && (
                                                    <button
                                                        onClick={openWhatsApp}
                                                        className="mt-3 w-full bg-green-500 hover:bg-green-600 text-white font-medium py-2 px-4 rounded-xl flex items-center justify-center gap-2 transition-colors"
                                                    >
                                                        <Phone className="w-4 h-4" />
                                                        Abrir WhatsApp
                                                        <ExternalLink className="w-3 h-3" />
                                                    </button>
                                                )}

                                                <p className="text-[10px] opacity-50 mt-1">
                                                    {message.timestamp.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })}
                                                </p>
                                            </div>
                                        </div>
                                    </div>
                                ))}

                                {/* Loading indicator */}
                                {isLoading && (
                                    <div className="flex justify-start">
                                        <div className="flex items-start gap-2">
                                            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-500 to-blue-500 flex items-center justify-center">
                                                <Sparkles className="w-4 h-4 text-white" />
                                            </div>
                                            <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm">
                                                <div className="flex items-center gap-1">
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Quick Replies */}
                                {showQuickReplies && messages.length <= 1 && !isLoading && (
                                    <div className="space-y-2">
                                        <p className="text-xs text-slate-500 dark:text-slate-400 text-center">Preguntas frecuentes:</p>
                                        <div className="flex flex-wrap gap-2 justify-center">
                                            {quickReplies.map((reply) => (
                                                <button
                                                    key={reply.id}
                                                    onClick={() => handleQuickReply(reply)}
                                                    className="px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-xs text-slate-700 dark:text-slate-300 hover:bg-blue-50 dark:hover:bg-slate-700 hover:border-blue-300 transition-colors flex items-center gap-1"
                                                >
                                                    <span>{reply.icon}</span>
                                                    <span>{reply.text}</span>
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                <div ref={messagesEndRef} />
                            </div>

                            {/* Input */}
                            <div className="p-3 bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700">
                                <div className="flex items-center gap-2">
                                    <input
                                        ref={inputRef}
                                        type="text"
                                        value={inputValue}
                                        onChange={(e) => setInputValue(e.target.value)}
                                        onKeyPress={handleKeyPress}
                                        placeholder="Escribe tu mensaje..."
                                        disabled={isLoading}
                                        className="flex-1 px-4 py-2.5 bg-slate-100 dark:bg-slate-900 border-0 rounded-xl text-sm text-slate-800 dark:text-slate-200 placeholder-slate-500 focus:ring-2 focus:ring-blue-500/30 outline-none transition-all disabled:opacity-50"
                                    />
                                    <button
                                        onClick={() => handleSendMessage()}
                                        disabled={!inputValue.trim() || isLoading}
                                        className="w-10 h-10 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 rounded-xl flex items-center justify-center text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed transform hover:scale-105 active:scale-95"
                                    >
                                        {isLoading ? (
                                            <Loader className="w-5 h-5 animate-spin" />
                                        ) : (
                                            <Send className="w-5 h-5" />
                                        )}
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-400 text-center mt-2">
                                    Powered by AI • <button onClick={openWhatsApp} className="text-green-500 hover:underline">WhatsApp: +{whatsappNumber}</button>
                                </p>
                            </div>
                        </>
                    )}
                </div>
            )}

            {/* CSS for animations and scrollbar */}
            <style>{`
                @keyframes pulse-slow {
                    0%, 100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.5); }
                    50% { box-shadow: 0 0 0 10px rgba(59, 130, 246, 0); }
                }
                .animate-pulse-slow {
                    animation: pulse-slow 2s infinite;
                }
                
                @keyframes shimmer {
                    0% {
                        transform: translateX(-100%);
                    }
                    100% {
                        transform: translateX(100%);
                    }
                }
                .animate-shimmer {
                    animation: shimmer 3s ease-in-out infinite;
                }
                
                /* Ocultar scrollbar pero mantener funcionalidad */
                .scrollbar-hide {
                    -ms-overflow-style: none;  /* IE and Edge */
                    scrollbar-width: none;  /* Firefox */
                    scroll-behavior: smooth;
                }
                
                .scrollbar-hide::-webkit-scrollbar {
                    display: none;  /* Chrome, Safari and Opera */
                    width: 0;
                    height: 0;
                    background: transparent;
                }
            `}</style>
        </>
    );
};

export default SupportChat;

import React, { useState, useEffect } from 'react';
import { X, Save, Loader, Globe, Lock, AlertTriangle } from 'lucide-react';
import { TemplateService } from '../../services/TemplateService';
import { ErrorService } from '../../services/ErrorService';

const CreateTemplateModal = ({ project, onClose, onSuccess }) => {
    // Safety check
    if (!project) return null;

    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState([]);
    const [error, setError] = useState(null);
    const [formData, setFormData] = useState({
        name: project.name || '',
        description: '',
        categoryId: '',
        isPublic: false
    });

    useEffect(() => {
        loadCategories();
    }, []);

    const loadCategories = async () => {
        try {
            const cats = await TemplateService.getCategories();
            if (cats && cats.length > 0) {
                setCategories(cats);
                setFormData(prev => ({ ...prev, categoryId: cats[0].id }));
            } else {
                setError('No se encontraron categorías disponibles.');
            }
        } catch (error) {
            console.error('Error loading categories:', error);
            setError('Error al cargar las categorías. Por favor recarga la página.');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        // Validate category
        if (!formData.categoryId) {
            setError('Por favor selecciona una categoría.');
            return;
        }

        setLoading(true);
        setError(null); // Limpiar errores anteriores

        try {
            await TemplateService.createTemplate(project.id, formData);
            onSuccess();
            onClose();
        } catch (error) {
            // Capturar el error con ErrorService
            ErrorService.logError(error, 'CreateTemplateModal.handleSubmit', {
                projectId: project.id,
                formData: formData
            });

            // Obtener mensaje amigable
            let userMessage = 'Error al crear la plantilla. Por favor intenta de nuevo.';

            // Mensajes específicos según el tipo de error
            if (error?.code === 'PGRST204') {
                userMessage = 'Error de configuración en la base de datos. Por favor contacta a soporte.';
            } else if (error?.message?.includes('Could not find')) {
                userMessage = 'Error de configuración del servidor. El equipo técnico ha sido notificado.';
            } else if (error?.message) {
                // Usar mensaje del error si es amigable
                userMessage = ErrorService.getErrorMessage(error);
            }

            setError(userMessage);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full">
                {/* Header */}
                <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white rounded-t-xl">
                    <div className="flex items-center justify-between">
                        <h3 className="text-xl font-bold">Guardar como Plantilla</h3>
                        <button
                            onClick={onClose}
                            className="hover:bg-white/20 p-2 rounded-lg transition"
                        >
                            <X size={20} />
                        </button>
                    </div>
                    <p className="text-indigo-100 text-sm mt-2">
                        Convierte este presupuesto en una plantilla reutilizable
                    </p>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {/* Error Message */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-start gap-3">
                            <AlertTriangle className="text-red-600 flex-shrink-0 mt-0.5" size={20} />
                            <div className="flex-1">
                                <p className="text-sm font-medium text-red-800">{error}</p>
                                <p className="text-xs text-red-600 mt-1">
                                    Si el problema persiste, puedes contactar a soporte desde el chat de ayuda.
                                </p>
                            </div>
                            <button
                                type="button"
                                onClick={() => setError(null)}
                                className="text-red-400 hover:text-red-600 transition"
                            >
                                <X size={16} />
                            </button>
                        </div>
                    )}

                    {/* Name */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Nombre de la Plantilla *
                        </label>
                        <input
                            type="text"
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Ej: Casa Habitación Estándar"
                        />
                    </div>

                    {/* Description */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Descripción
                        </label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            rows={3}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Describe para qué tipo de proyectos es útil esta plantilla..."
                        />
                    </div>

                    {/* Category */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Categoría *
                        </label>
                        <select
                            value={formData.categoryId}
                            onChange={(e) => setFormData({ ...formData, categoryId: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-800"
                        >
                            {categories.map(cat => (
                                <option key={cat.id} value={cat.id}>{cat.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Public/Private */}
                    <div className="bg-slate-50 rounded-lg p-4 border border-slate-200">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.isPublic}
                                onChange={(e) => setFormData({ ...formData, isPublic: e.target.checked })}
                                className="w-4 h-4 text-indigo-600 rounded focus:ring-2 focus:ring-indigo-500"
                            />
                            <div className="flex-1">
                                <div className="flex items-center gap-2">
                                    {formData.isPublic ? (
                                        <>
                                            <Globe size={16} className="text-green-600" />
                                            <span className="font-medium text-slate-800">Plantilla Pública</span>
                                        </>
                                    ) : (
                                        <>
                                            <Lock size={16} className="text-slate-600" />
                                            <span className="font-medium text-slate-800">Plantilla Privada</span>
                                        </>
                                    )}
                                </div>
                                <p className="text-xs text-slate-500 mt-1">
                                    {formData.isPublic
                                        ? 'Otros usuarios podrán ver y usar esta plantilla'
                                        : 'Solo tú podrás ver y usar esta plantilla'}
                                </p>
                            </div>
                        </label>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition font-medium"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={loading}
                            className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition font-medium flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            {loading ? (
                                <>
                                    <Loader size={18} className="animate-spin" />
                                    Guardando...
                                </>
                            ) : (
                                <>
                                    <Save size={18} />
                                    Crear Plantilla
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CreateTemplateModal;

import React, { useState } from 'react';
import { AlertTriangle, Bug, Zap, Code, Database, RefreshCw } from 'lucide-react';
import { ErrorService } from '../../services/ErrorService';

/**
 * Panel de prueba para simular diferentes tipos de errores
 * Útil para verificar que el sistema de manejo de errores funciona correctamente
 */
const ErrorTestPanel = () => {
    const [testResults, setTestResults] = useState([]);

    const addTestResult = (type, success) => {
        setTestResults(prev => [
            {
                id: Date.now(),
                type,
                success,
                timestamp: new Date().toLocaleTimeString()
            },
            ...prev
        ].slice(0, 5));
    };

    // 1. Error de JavaScript puro (no capturado)
    const testJavaScriptError = () => {
        try {
            addTestResult('JavaScript Error', true);
            // Crear un error que será capturado por window.onerror
            setTimeout(() => {
                // Esto será capturado por el handler global
                throw new Error('Error de prueba: JavaScript no capturado');
            }, 100);
        } catch (e) {
            // Este catch no capturará el error del setTimeout
        }
    };

    // 2. Error en una promesa rechazada
    const testPromiseError = () => {
        addTestResult('Promise Error', true);
        Promise.reject(new Error('Error de prueba: Promesa rechazada sin catch'))
            .catch(() => {
                // Ignorar para que sea unhandled
            });
        
        // Crear una promesa realmente sin catch
        setTimeout(() => {
            new Promise((resolve, reject) => {
                reject(new Error('Promesa rechazada no manejada'));
            });
        }, 100);
    };

    // 3. Error capturado manualmente
    const testManualError = () => {
        try {
            addTestResult('Manual Error', true);
            const error = new Error('Error de prueba: Capturado manualmente');
            ErrorService.logError(error, 'ErrorTestPanel.testManualError', {
                test: true,
                usuario: 'Testing'
            });
            alert('✅ Error capturado manualmente. Revisa la consola y el ErrorContext.');
        } catch (e) {
            console.error('Error al probar:', e);
        }
    };

    // 4. Error de validación
    const testValidationError = () => {
        addTestResult('Validation Error', true);
        const error = new Error('Error de validación: El campo nombre es requerido');
        ErrorService.logError(error, 'ErrorTestPanel.testValidationError', {
            field: 'nombre',
            validation: true
        });
        alert('✅ Error de validación capturado. Debería mostrarse un Toast.');
    };

    // 5. Error de red/API
    const testNetworkError = () => {
        addTestResult('Network Error', true);
        const error = new Error('Failed to fetch: NetworkError when attempting to fetch resource');
        ErrorService.logError(error, 'ErrorTestPanel.testNetworkError');
        alert('✅ Error de red simulado. Revisa cómo se maneja.');
    };

    // 6. Error que crashea un componente React
    const testReactError = () => {
        addTestResult('React Error', true);
        // Este error será capturado por ErrorBoundary
        throw new Error('Error de prueba: Esto crasheará el componente React');
    };

    // 7. Error de null/undefined
    const testNullError = () => {
        addTestResult('Null Error', true);
        try {
            const obj = null;
            const result = obj.propiedad.nested; // Esto causará un error
        } catch (error) {
            ErrorService.logError(error, 'ErrorTestPanel.testNullError');
            alert('✅ Error de null/undefined capturado.');
        }
    };

    const clearResults = () => {
        setTestResults([]);
    };

    const testButtons = [
        {
            name: 'Error JavaScript',
            icon: <Code size={18} />,
            color: 'bg-red-600 hover:bg-red-700',
            onClick: testJavaScriptError,
            description: 'Error de JS no capturado (se captura automáticamente)'
        },
        {
            name: 'Error de Promesa',
            icon: <Zap size={18} />,
            color: 'bg-orange-600 hover:bg-orange-700',
            onClick: testPromiseError,
            description: 'Promesa rechazada sin catch (unhandledrejection)'
        },
        {
            name: 'Error Manual',
            icon: <Bug size={18} />,
            color: 'bg-blue-600 hover:bg-blue-700',
            onClick: testManualError,
            description: 'Error capturado con ErrorService.logError()'
        },
        {
            name: 'Error Validación',
            icon: <AlertTriangle size={18} />,
            color: 'bg-amber-600 hover:bg-amber-700',
            onClick: testValidationError,
            description: 'Error de validación con contexto'
        },
        {
            name: 'Error de Red',
            icon: <Database size={18} />,
            color: 'bg-purple-600 hover:bg-purple-700',
            onClick: testNetworkError,
            description: 'Error de conexión/red simulado'
        },
        {
            name: 'Error Null',
            icon: <AlertTriangle size={18} />,
            color: 'bg-pink-600 hover:bg-pink-700',
            onClick: testNullError,
            description: 'Error por null/undefined'
        },
        {
            name: 'Error React (⚠️)',
            icon: <AlertTriangle size={18} />,
            color: 'bg-red-700 hover:bg-red-800',
            onClick: testReactError,
            description: 'Crashea el componente (ErrorBoundary lo captura)'
        }
    ];

    return (
        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg border border-slate-200 dark:border-slate-700 p-6 space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2">
                        <Bug className="text-blue-600" size={24} />
                        Panel de Prueba de Errores
                    </h2>
                    <p className="text-sm text-slate-600 dark:text-slate-400 mt-1">
                        Prueba diferentes tipos de errores para verificar el sistema de manejo
                    </p>
                </div>
                {testResults.length > 0 && (
                    <button
                        onClick={clearResults}
                        className="flex items-center gap-2 px-3 py-2 text-sm bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 rounded-lg transition"
                    >
                        <RefreshCw size={16} />
                        Limpiar
                    </button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                {testButtons.map((btn, index) => (
                    <button
                        key={index}
                        onClick={btn.onClick}
                        className={`${btn.color} text-white p-4 rounded-lg shadow-md hover:shadow-lg transition-all transform hover:scale-105 active:scale-95 flex flex-col items-center gap-2`}
                        title={btn.description}
                    >
                        <div className="flex items-center gap-2">
                            {btn.icon}
                            <span className="font-semibold text-sm">{btn.name}</span>
                        </div>
                        <span className="text-xs opacity-90 text-center">{btn.description}</span>
                    </button>
                ))}
            </div>

            {testResults.length > 0 && (
                <div className="border-t border-slate-200 dark:border-slate-700 pt-4">
                    <h3 className="font-semibold text-slate-700 dark:text-slate-300 mb-2">
                        Resultados de pruebas:
                    </h3>
                    <div className="space-y-2">
                        {testResults.map((result) => (
                            <div
                                key={result.id}
                                className="flex items-center justify-between p-2 bg-slate-50 dark:bg-slate-900 rounded-lg text-sm"
                            >
                                <span className="text-slate-700 dark:text-slate-300">
                                    {result.type}
                                </span>
                                <div className="flex items-center gap-2">
                                    <span className="text-xs text-slate-500">
                                        {result.timestamp}
                                    </span>
                                    {result.success && (
                                        <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
                <h3 className="font-semibold text-blue-900 dark:text-blue-200 mb-2">
                    💡 Cómo verificar los errores:
                </h3>
                <ul className="text-sm text-blue-800 dark:text-blue-300 space-y-1 list-disc list-inside">
                    <li>Abre la consola del navegador (F12) para ver los logs</li>
                    <li>Revisa ErrorContext: <code className="bg-blue-100 dark:bg-blue-900 px-1 rounded">localStorage.getItem('presugenius_recent_errors')</code></li>
                    <li>Prueba el chat de soporte: abre el chat y di "Tengo un error"</li>
                    <li>Verifica Sentry (si está configurado): los errores aparecerán en el dashboard</li>
                </ul>
            </div>
        </div>
    );
};

export default ErrorTestPanel;

import React from 'react';
import { Info, CheckCircle, AlertCircle, X } from 'lucide-react';

const AlertModal = ({ isOpen, onClose, title, message, type = 'info' }) => {
    if (!isOpen) return null;

    const icons = {
        info: <Info className="h-6 w-6 text-blue-600" />,
        success: <CheckCircle className="h-6 w-6 text-emerald-600" />,
        warning: <AlertCircle className="h-6 w-6 text-amber-600" />,
        error: <AlertCircle className="h-6 w-6 text-red-600" />
    };

    const bgColors = {
        info: 'bg-blue-100',
        success: 'bg-emerald-100',
        warning: 'bg-amber-100',
        error: 'bg-red-100'
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden transform transition-all scale-100">
                <div className="p-6">
                    <div className="flex items-start gap-4">
                        <div className={`flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full ${bgColors[type]}`}>
                            {icons[type]}
                        </div>
                        <div className="flex-1">
                            <div className="flex items-start justify-between mb-2">
                                <h3 className="text-lg font-bold text-slate-900">{title}</h3>
                                <button
                                    onClick={onClose}
                                    className="text-slate-400 hover:text-slate-600 transition p-1 -mt-1 -mr-1"
                                >
                                    <X size={18} />
                                </button>
                            </div>
                            <p className="text-sm text-slate-600 mb-6 whitespace-pre-line">{message}</p>
                            <div className="flex justify-end">
                                <button
                                    onClick={onClose}
                                    className={`px-4 py-2 text-white rounded-lg font-bold transition shadow-lg ${
                                        type === 'error' ? 'bg-red-600 hover:bg-red-700 shadow-red-200' :
                                        type === 'success' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200' :
                                        type === 'warning' ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-200' :
                                        'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'
                                    }`}
                                >
                                    Aceptar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

