    const [pendingUpdates, setPendingUpdates] = useState([]);
    const [selectedUpdates, setSelectedUpdates] = useState({}); // { itemId: boolean }

    const handleAdd = async (e) => {
        e.preventDefault();
        if (!newItem.description || !newItem.unitPrice) return;

        const success = await addToCatalog({
            ...newItem,
            unitPrice: parseFloat(newItem.unitPrice)
        });

        if (success) {
            setShowAddModal(false);
            setNewItem({ description: '', unit: 'pza', unitPrice: '', category: 'Materiales' });
        }
    };

    const handleOpenUpdateModal = () => {
        if (catalog.length === 0) {
            showToast('No hay conceptos en el catálogo para actualizar', 'warning');
            return;
        }
        setShowUpdateModal(true);
    };

    const handleDetectLocation = async () => {
        setIsDetectingLocation(true);

        const detectViaIp = async () => {
            try {
                const response = await fetch('https://ipapi.co/json/');
                if (!response.ok) throw new Error('Error fetching location');
                const data = await response.json();
                if (data.city && data.region) {
                    setUpdateLocation(`${data.city}, ${data.region}`);
                    showToast('Ubicación detectada (IP)', 'success');
                } else {
                    setUpdateLocation('México');
                    showToast('No se pudo detectar ciudad exacta', 'warning');
                }
            } catch (error) {
                console.error('Error detecting location:', error);
                setUpdateLocation('México');
                showToast('No se pudo detectar la ubicación', 'info');
            } finally {
                setIsDetectingLocation(false);
            }
        };

        if ('geolocation' in navigator) {
            navigator.geolocation.getCurrentPosition(
                async (position) => {
                    try {
                        const { latitude, longitude } = position.coords;
                        // Use OpenStreetMap Nominatim for free reverse geocoding
                        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                        const data = await response.json();

                        const address = data.address;
                        const city = address.city || address.town || address.village || address.municipality;
                        const state = address.state;

                        if (city) {
                            setUpdateLocation(`${city}, ${state || ''}`);
                            showToast('Ubicación detectada (GPS)', 'success');
                            setIsDetectingLocation(false);
                        } else {
                            detectViaIp();
                        }
                    } catch (error) {
                        console.warn('GPS Reverse geocoding failed, falling back to IP', error);
                        detectViaIp();
                    }
                },
                (error) => {
                    console.warn('GPS denied or failed', error);
                    detectViaIp();
                }
            );
        } else {
            detectViaIp();
        }
    };

    const confirmUpdatePrices = async () => {
        setShowUpdateModal(false);
        setIsUpdatingPrices(true);
        try {
            // 1. Get AI updates (without applying them yet)
            const updatedCatalog = await AIBudgetService.updateCatalogPrices(catalog, updateLocation);

            // 2. Identify ONLY items that changed
            const changes = updatedCatalog.filter(updatedItem => {
                const original = catalog.find(c => c.id === updatedItem.id);
                return original && Math.abs(original.unitPrice - updatedItem.unitPrice) > 0.01;
            }).map(updatedItem => {
                const original = catalog.find(c => c.id === updatedItem.id);
                return {
                    ...updatedItem,
                    originalPrice: original.unitPrice,
                    priceDiff: updatedItem.unitPrice - original.unitPrice,
                    diffPercent: ((updatedItem.unitPrice - original.unitPrice) / original.unitPrice) * 100
                };
            });

            if (changes.length === 0) {
                showToast('La IA analizó tu catálogo y los precios parecen actuales.', 'success');
                setIsUpdatingPrices(false);
                return;
            }

            // 3. Prepare Review Modal
            setPendingUpdates(changes);
            // Select all by default
            const initialSelection = {};
            changes.forEach(item => initialSelection[item.id] = true);
            setSelectedUpdates(initialSelection);

            setShowReviewModal(true);

        } catch (error) {
            console.error('Error updating prices:', error);
            showToast('Error al analizar precios', 'error');
        } finally {
            setIsUpdatingPrices(false);
        }
    };

    const handleApplyUpdates = async () => {
        const itemsToUpdate = pendingUpdates.filter(item => selectedUpdates[item.id]);

        if (itemsToUpdate.length === 0) {
            setShowReviewModal(false);
            return;
        }

        // Merge updates into catalog
        const newCatalog = catalog.map(item => {
            const update = itemsToUpdate.find(u => u.id === item.id);
            if (update) {
                return {
                    ...item,
                    unitPrice: update.unitPrice,
                    lastUpdate: update.lastUpdate,
                    priceNote: update.priceNote,
                    source: update.source
                };
            }
            return item;
        });

        await updateCatalogBulk(newCatalog);
        showToast(`${itemsToUpdate.length} precios actualizados correctamente`, 'success');
        setShowReviewModal(false);
    };

    const toggleUpdateSelection = (id) => {
        setSelectedUpdates(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const [activeTab, setActiveTab] = useState('personal'); // 'personal' | 'market'
    const [viewItem, setViewItem] = useState(null);
    const [marketItems, setMarketItems] = useState([]);
    const [marketLoading, setMarketLoading] = useState(false);
    const [marketPage, setMarketPage] = useState(1);
    const [marketTotal, setMarketTotal] = useState(0);
    const [marketSearch, setMarketSearch] = useState('');

    // Load market items when tab changes or search changes
    React.useEffect(() => {
        if (activeTab === 'market') {
            loadMarketItems();
        }
    }, [activeTab, marketPage, marketSearch]);

    const loadMarketItems = async () => {
        setMarketLoading(true);
        try {
            const { MarketPriceService } = await import('../services/MarketPriceService');
            const { data, count } = await MarketPriceService.searchPrices(marketSearch, marketPage, 20);
            setMarketItems(data);
            setMarketTotal(count);
        } catch (error) {
            console.error('Error loading market items:', error);
            showToast('Error al cargar precios de mercado', 'error');
        } finally {
            setMarketLoading(false);
        }
    };

    const handleAddToMyCatalog = async (item) => {
        const success = await addToCatalog({
            description: item.description,
            unit: item.unit,
            unitPrice: item.base_price,
            category: item.category || 'Materiales'
        });
        if (success) {
            showToast('Agregado a tu catálogo', 'success');
        }
    };

    return (
        <div className="space-y-6 animate-fadeIn pb-20">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Catálogo Maestro</h2>
                    <p className="text-slate-500 text-sm">
                        {activeTab === 'personal'
                            ? 'Gestiona tus precios personales y conceptos personalizados.'
                            : 'Consulta la base de datos compartida del mercado (solo lectura).'}
                    </p>
                </div>

                <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button
                        onClick={() => setActiveTab('personal')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Mis Conceptos
                    </button>
                    <button
                        onClick={() => setActiveTab('market')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition ${activeTab === 'market' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Base de Datos Maestra
                    </button>
                </div>
            </div>

            {/* Toolbar */}
            <div className="flex justify-between items-center">
                <div className="flex gap-3">
                    {activeTab === 'personal' && (
                        <button
                            onClick={handleOpenUpdateModal}
                            disabled={isUpdatingPrices}
                            className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition font-bold text-sm border border-indigo-200"
                            title="Actualizar precios con IA"
                        >
                            {isUpdatingPrices ? (
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-600 border-t-transparent"></div>
                            ) : (
                                <Sparkles size={16} />
                            )}
                            <span>{isUpdatingPrices ? 'Actualizando...' : 'Actualizar Precios IA'}</span>
                        </button>
                    )}
                </div>

                <div className="relative">
                    <Search className="absolute left-3 top-2.5 text-slate-400" size={16} />
                    <input
                        value={activeTab === 'personal' ? search : marketSearch}
                        onChange={(e) => activeTab === 'personal' ? setSearch(e.target.value) : setMarketSearch(e.target.value)}
                        placeholder={activeTab === 'personal' ? "Buscar en mis conceptos..." : "Buscar en base de datos maestra..."}
                        className="pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none w-64 md:w-80"
                    />
                </div>
            </div>

            {/* Content */}
            {activeTab === 'personal' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {catalog.filter(c => c.description.toLowerCase().includes(search.toLowerCase())).map(c => (
                        <div key={c.id} className="bg-white p-4 rounded-xl border border-slate-200 hover:shadow-md transition group relative">
                            <div className="flex justify-between items-start mb-2">
                                <Badge type={c.category} />
                                <button
                                    onClick={() => deleteFromCatalog(c.id)}
                                    className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition"
                                    title="Eliminar del catálogo"
                                >
                                    <Trash2 size={14} />
                                </button>
                            </div>
                            <p className="font-medium text-slate-800 text-sm mb-3 line-clamp-3 min-h-[3rem]">{c.description}</p>
                            <div className="flex justify-between items-center text-sm border-t border-slate-100 pt-3">
                                <span className="text-slate-500 bg-slate-50 px-2 py-0.5 rounded text-xs font-medium">{c.unit}</span>
                                <span className="font-mono font-bold text-blue-600">{formatCurrency(c.unitPrice)}</span>
                            </div>
                        </div>
                    ))}

                    {/* Add New Card - Solo visible en pestaña personal */}
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center p-6 text-slate-400 hover:border-blue-400 hover:text-blue-500 hover:bg-blue-50 transition cursor-pointer min-h-[160px]"
                    >
                        <div className="bg-blue-50 p-3 rounded-full mb-3 group-hover:bg-blue-100 transition">
                            <Plus size={24} />
                        </div>
                        <span className="font-bold">Nuevo Concepto</span>
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Información de solo lectura */}
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-sm text-blue-800 flex items-start gap-2">
                        <Eye size={18} className="text-blue-600 mt-0.5 flex-shrink-0" />
                        <div>
                            <span className="font-bold">Base de Datos Maestra (Solo Lectura)</span>
                            <p className="text-xs text-blue-700 mt-1">Esta base de datos es compartida y no se puede modificar. Puedes agregar conceptos a tu catálogo personal usando el botón +.</p>
                        </div>
                    </div>

                    {marketLoading ? (
                        <div className="flex justify-center py-12">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {marketItems.map(item => (
                                <div key={item.id} className="bg-white p-4 rounded-xl border border-indigo-100 hover:border-indigo-300 hover:shadow-md transition group relative">
                                    <div className="flex justify-between items-start mb-2">
                                        <Badge type={item.category || 'Materiales'} />
                                        <span className="text-[10px] text-slate-400 bg-slate-50 px-2 py-1 rounded-full border border-slate-100">
                                            {item.source === 'cdmx_tabulador' ? 'CDMX' :
                                                item.source === 'construbase_libre' ? 'Construbase' :
                                                    item.source === 'neodata' ? 'Neodata' : item.source}
                                        </span>
                                    </div>
                                    {/* Mostrar partida o código si está disponible */}
                                    {(item.metadata?.partida || item.metadata?.codigo) && (
                                        <div className="mb-2">
                                            <span className="text-[10px] font-mono text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-200">
                                                {item.metadata?.partida || item.metadata?.codigo}
                                                {item.metadata?.renglon && ` - ${item.metadata.renglon}`}
                                            </span>
                                        </div>
                                    )}
                                    <p className="font-medium text-slate-800 text-sm mb-3 line-clamp-3 min-h-[3rem]">{item.description}</p>
                                    <div className="flex justify-between items-center text-sm border-t border-slate-100 pt-3">
                                        <div className="flex flex-col">
                                            <span className="text-slate-500 text-xs">{item.unit}</span>
                                            <span className="text-[10px] text-slate-400">{item.location}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="font-mono font-bold text-indigo-600">{formatCurrency(item.base_price)}</span>
                                            <button
                                                onClick={() => setViewItem(item)}
                                                className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition"
                                                title="Ver detalles completos (Solo lectura)"
                                            >
                                                <Eye size={16} />
                                            </button>
                                            <button
                                                onClick={() => handleAddToMyCatalog(item)}
                                                className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition"
                                                title="Agregar a mi catálogo personal"
                                            >
                                                <Plus size={16} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Pagination */}
                    <div className="flex justify-between items-center pt-4 border-t border-slate-200">
                        <span className="text-sm text-slate-500">
                            Mostrando {marketItems.length} de {marketTotal} resultados
                        </span>
                        <div className="flex gap-2">
                            <button
                                onClick={() => setMarketPage(p => Math.max(1, p - 1))}
                                disabled={marketPage === 1}
                                className="px-3 py-1 border rounded hover:bg-slate-50 disabled:opacity-50 text-sm"
                            >
                                Anterior
                            </button>
                            <span className="px-3 py-1 text-sm font-medium text-slate-600 bg-slate-50 rounded">
                                Página {marketPage}
                            </span>
                            <button
                                onClick={() => setMarketPage(p => p + 1)}
                                disabled={marketItems.length < 20}
                                className="px-3 py-1 border rounded hover:bg-slate-50 disabled:opacity-50 text-sm"
                            >
                                Siguiente
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal Agregar */}
            {showAddModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                            <h3 className="font-bold text-slate-800">Agregar al Catálogo</h3>
                            <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleAdd} className="p-6 space-y-4">

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descripción</label>
                                <textarea
                                    value={newItem.description}
                                    onChange={e => setNewItem({ ...newItem, description: e.target.value })}
                                    className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                                    rows={3}
                                    placeholder="Ej: Muro de block..."
                                    required
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Unidad</label>
                                    <input
                                        value={newItem.unit}
                                        onChange={e => setNewItem({ ...newItem, unit: e.target.value })}
                                        className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                        placeholder="m2, pza..."
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Precio Unitario</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        min="0"
                                        value={newItem.unitPrice}
                                        onChange={e => setNewItem({ ...newItem, unitPrice: e.target.value })}
                                        className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                        placeholder="0.00"
                                        required
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría</label>
                                <select
                                    value={newItem.category}
                                    onChange={e => setNewItem({ ...newItem, category: e.target.value })}
                                    className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                                >
                                    {['Materiales', 'Mano de Obra', 'Equipos', 'Instalaciones', 'Obra Civil'].map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition">Cancelar</button>
                                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white font-bold hover:bg-blue-700 rounded-lg transition shadow-lg shadow-blue-200">Guardar</button>
                            </div>
                        </form>
                    </div>
                </div>
            )
            }

            {/* Modal Actualizar Precios */}
            {showUpdateModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-50">
                            <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                                <Sparkles size={18} className="text-indigo-600" /> Actualizar Precios con IA
                            </h3>
                            <button onClick={() => setShowUpdateModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-sm text-slate-600">
                                La IA analizará tu catálogo y actualizará los precios unitarios basándose en el mercado actual.
                            </p>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ubicación de Referencia</label>
                                <div className="flex gap-2">
                                    <input
                                        value={updateLocation}
                                        onChange={e => setUpdateLocation(e.target.value)}
                                        className="flex-1 border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                                        placeholder="Ej: Ciudad de México, Monterrey..."
                                    />
                                    <button
                                        onClick={handleDetectLocation}
                                        disabled={isDetectingLocation}
                                        className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition border border-slate-200"
                                        title="Usar ubicación actual"
                                    >
                                        {isDetectingLocation ? (
                                            <div className="animate-spin rounded-full h-4 w-4 border-2 border-slate-500 border-t-transparent"></div>
                                        ) : (
                                            <MapPin size={18} />
                                        )}
                                    </button>
                                </div>
                                <p className="text-xs text-slate-400 mt-1">Especifica la ciudad para obtener precios regionales más precisos.</p>
                            </div>

                            <div className="bg-amber-50 border border-amber-100 rounded-lg p-3 text-xs text-amber-800 flex gap-2">
                                <span className="font-bold">Nota:</span>
                                Este proceso puede tomar unos segundos dependiendo del tamaño de tu catálogo.
                            </div>

                            <div className="pt-2 flex gap-3">
                                <button onClick={() => setShowUpdateModal(false)} className="flex-1 px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition">Cancelar</button>
                                <button
                                    onClick={confirmUpdatePrices}
                                    className="flex-1 px-4 py-2 bg-indigo-600 text-white font-bold hover:bg-indigo-700 rounded-lg transition shadow-lg shadow-indigo-200"
                                >
                                    Confirmar Actualización
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Revisión de Precios */}
            {showReviewModal && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-50 flex-shrink-0">
                            <div>
                                <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                                    <Sparkles size={18} className="text-indigo-600" /> Revisión de Actualizaciones
                                </h3>
                                <p className="text-xs text-indigo-700 mt-1">
                                    Se encontraron {pendingUpdates.length} ajustes de precios para {updateLocation}. Selecciona los que deseas aplicar.
                                </p>
                            </div>
                            <button onClick={() => setShowReviewModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-0">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                                    <tr>
                                        <th className="p-4 w-10">
                                            <input
                                                type="checkbox"
                                                checked={Object.values(selectedUpdates).every(Boolean)}
                                                onChange={() => {
                                                    const allSelected = Object.values(selectedUpdates).every(Boolean);
                                                    const newSelection = {};
                                                    pendingUpdates.forEach(item => newSelection[item.id] = !allSelected);
                                                    setSelectedUpdates(newSelection);
                                                }}
                                                className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                                            />
                                        </th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase">Concepto</th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase text-right">Precio Anterior</th>
                                        <th className="p-4 w-8"></th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase text-right">Nuevo Precio</th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase">Razón / Fuente</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {pendingUpdates.map(item => (
                                        <tr key={item.id} className={`hover:bg-slate-50 transition ${!selectedUpdates[item.id] ? 'opacity-50 grayscale bg-slate-50' : ''}`}>
                                            <td className="p-4">
                                                <input
                                                    type="checkbox"
                                                    checked={!!selectedUpdates[item.id]}
                                                    onChange={() => toggleUpdateSelection(item.id)}
                                                    className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                                                />
                                            </td>
                                            <td className="p-4">
                                                <p className="text-sm font-medium text-slate-800 line-clamp-2">{item.description}</p>
                                                <span className="text-[10px] text-slate-400">{item.unit} | {item.category}</span>
                                            </td>
                                            <td className="p-4 text-right font-mono text-slate-500 text-sm">
                                                {formatCurrency(item.originalPrice)}
                                            </td>
                                            <td className="p-4 text-center text-slate-300">
                                                <ArrowRight size={14} />
                                            </td>
                                            <td className="p-4 text-right">
                                                <div className="flex flex-col items-end">
                                                    <span className="font-mono font-bold text-indigo-600 text-sm">{formatCurrency(item.unitPrice)}</span>
                                                    <span className={`text-[10px] font-bold px-1.5 rounded-full ${item.priceDiff > 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                                                        {item.priceDiff > 0 ? '+' : ''}{item.diffPercent.toFixed(1)}%
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="p-4">
                                                <div className="flex items-start gap-2">
                                                    <span className={`mt-0.5 w-1.5 h-1.5 rounded-full flex-shrink-0 ${item.source === 'ai' ? 'bg-purple-500' : 'bg-blue-500'}`}></span>
                                                    <p className="text-xs text-slate-600 max-w-[200px]">{item.priceNote || 'Actualización automática'}</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-between items-center flex-shrink-0">
                            <span className="text-sm text-slate-500">
                                {Object.values(selectedUpdates).filter(Boolean).length} seleccionados
                            </span>
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setShowReviewModal(false)}
                                    className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    onClick={handleApplyUpdates}
                                    className="px-6 py-2 bg-indigo-600 text-white font-bold hover:bg-indigo-700 rounded-lg transition shadow-lg shadow-indigo-200 flex items-center gap-2"
                                >
                                    <Check size={18} /> Aplicar Actualizaciones
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal Ver Detalles (Solo Lectura) */}
            {viewItem && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-2xl w-full max-h-[90vh] flex flex-col overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 flex-shrink-0">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <Eye size={18} className="text-slate-500" /> Detalle de Concepto
                            </h3>
                            <button onClick={() => setViewItem(null)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>
                        <div className="overflow-y-auto flex-1 p-6 space-y-4">
                            {/* Descripción */}
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Descripción</label>
                                <p className="text-sm text-slate-800 bg-slate-50 p-3 rounded-lg border border-slate-200 whitespace-pre-wrap break-words leading-relaxed">{viewItem.description || 'Sin descripción'}</p>
                            </div>

                            {/* Información Principal del Excel */}
                            <div className="bg-gradient-to-br from-indigo-50 to-blue-50 border border-indigo-200 rounded-lg p-4 space-y-3">
                                <p className="text-xs font-bold text-indigo-900 uppercase mb-3 flex items-center gap-2">
                                    <span className="w-1 h-4 bg-indigo-600 rounded"></span>
                                    Información Principal
                                </p>
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                                    {viewItem.metadata?.partida && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Partida</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.partida}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.codigo && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Código</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.codigo}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.renglon && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Renglón</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.renglon}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.n !== null && viewItem.metadata?.n !== undefined && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">N</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.n}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.tipo !== null && viewItem.metadata?.tipo !== undefined && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Tipo</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.tipo}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.codigo_auxiliar && (
                                        <div className="bg-white p-2 rounded border border-indigo-100">
                                            <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Código Auxiliar</span>
                                            <span className="text-sm font-mono text-indigo-900">{viewItem.metadata.codigo_auxiliar}</span>
                                        </div>
                                    )}
                                </div>
                                {viewItem.metadata?.descripcion_partida && (
                                    <div className="mt-3 pt-3 border-t border-indigo-200 bg-white p-3 rounded border border-indigo-100">
                                        <span className="text-[10px] font-bold text-indigo-600 uppercase block mb-1">Clasificación / Descripción de la Partida</span>
                                        <p className="text-sm text-indigo-900 font-medium">{viewItem.metadata.descripcion_partida}</p>
                                    </div>
                                )}
                            </div>

                            {/* Información de Precios y Unidades */}
                            <div className="bg-gradient-to-br from-emerald-50 to-teal-50 border border-emerald-200 rounded-lg p-4 space-y-3">
                                <p className="text-xs font-bold text-emerald-900 uppercase mb-3 flex items-center gap-2">
                                    <span className="w-1 h-4 bg-emerald-600 rounded"></span>
                                    Precios y Unidades
                                </p>
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                                    <div className="bg-white p-3 rounded border border-emerald-100">
                                        <span className="text-[10px] font-bold text-emerald-600 uppercase block mb-1">Unidad</span>
                                        <span className="text-sm font-mono font-bold text-emerald-900">{viewItem.unit || 'N/A'}</span>
                                    </div>
                                    <div className="bg-white p-3 rounded border border-emerald-100">
                                        <span className="text-[10px] font-bold text-emerald-600 uppercase block mb-1">Precio Base</span>
                                        <span className="text-sm font-mono font-bold text-emerald-700">{formatCurrency(viewItem.base_price)}</span>
                                    </div>
                                    {viewItem.metadata?.cantidad && (
                                        <div className="bg-white p-3 rounded border border-emerald-100">
                                            <span className="text-[10px] font-bold text-emerald-600 uppercase block mb-1">Cantidad</span>
                                            <span className="text-sm font-mono text-emerald-900">{parseFloat(viewItem.metadata.cantidad).toFixed(4)}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.importe && (
                                        <div className="bg-white p-3 rounded border border-emerald-100">
                                            <span className="text-[10px] font-bold text-emerald-600 uppercase block mb-1">Importe</span>
                                            <span className="text-sm font-mono font-bold text-emerald-700">{formatCurrency(viewItem.metadata.importe)}</span>
                                        </div>
                                    )}
                                    {viewItem.metadata?.costo && (
                                        <div className="bg-white p-3 rounded border border-emerald-100">
                                            <span className="text-[10px] font-bold text-emerald-600 uppercase block mb-1">Costo</span>
                                            <span className="text-sm font-mono font-bold text-emerald-700">{formatCurrency(viewItem.metadata.costo)}</span>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Información Adicional y Notas */}
                            {(viewItem.metadata?.texto_auxiliar || viewItem.metadata?.correo_nube || viewItem.metadata?.maestro_nube) && (
                                <div className="bg-gradient-to-br from-amber-50 to-orange-50 border border-amber-200 rounded-lg p-4 space-y-3">
                                    <p className="text-xs font-bold text-amber-900 uppercase mb-3 flex items-center gap-2">
                                        <span className="w-1 h-4 bg-amber-600 rounded"></span>
                                        Información Adicional
                                    </p>
                                    {viewItem.metadata?.texto_auxiliar && (
                                        <div className="bg-white p-3 rounded border border-amber-100">
                                            <span className="text-[10px] font-bold text-amber-600 uppercase block mb-2">Texto Auxiliar / Notas</span>
                                            <p className="text-sm text-amber-900 whitespace-pre-wrap break-words">{viewItem.metadata.texto_auxiliar}</p>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-2 gap-3">
                                        {viewItem.metadata?.correo_nube && (
                                            <div className="bg-white p-2 rounded border border-amber-100">
                                                <span className="text-[10px] font-bold text-amber-600 uppercase block mb-1">Correo Nube</span>
                                                <span className="text-xs text-amber-900 break-all">{viewItem.metadata.correo_nube}</span>
                                            </div>
                                        )}
                                        {viewItem.metadata?.maestro_nube && (
                                            <div className="bg-white p-2 rounded border border-amber-100">
                                                <span className="text-[10px] font-bold text-amber-600 uppercase block mb-1">Maestro Nube</span>
                                                <span className="text-xs text-amber-900">{viewItem.metadata.maestro_nube}</span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* Información de Categoría y Fuente */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría</label>
                                    <p className="text-sm font-medium text-slate-800">{viewItem.category || 'N/A'}</p>
                                </div>
                                <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fuente</label>
                                    <p className="text-sm font-medium text-slate-800 capitalize">{viewItem.source?.replace(/_/g, ' ') || 'N/A'}</p>
                                </div>
                            </div>

                        </div>
                        <div className="p-4 border-t border-slate-200 bg-slate-50 flex-shrink-0">
                            <button
                                onClick={() => {
                                    handleAddToMyCatalog(viewItem);
                                    setViewItem(null);
                                }}
                                className="w-full py-3 bg-indigo-600 text-white font-bold hover:bg-indigo-700 rounded-lg transition shadow-lg shadow-indigo-200 flex justify-center items-center gap-2"
                            >
                                <Plus size={18} /> Agregar a Mi Catálogo
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Catalog;

import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '../lib/supabaseClient';
import { CheckCircle, XCircle, Loader, Mail, Sparkles, ArrowRight } from 'lucide-react';

const ConfirmEmail = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const [status, setStatus] = useState('verifying'); // verifying, success, error
    const [message, setMessage] = useState('');
    const [countdown, setCountdown] = useState(5);

    useEffect(() => {
        handleEmailConfirmation();
    }, []);

    useEffect(() => {
        if (status === 'success' && countdown > 0) {
            const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
            return () => clearTimeout(timer);
        } else if (status === 'success' && countdown === 0) {
            navigate('/login');
        }
    }, [status, countdown, navigate]);

    const handleEmailConfirmation = async () => {
        try {
            // Supabase maneja automáticamente la confirmación a través de los parámetros de URL
            // Verificamos si hay un token de acceso o error en los parámetros
            const hashParams = new URLSearchParams(window.location.hash.substring(1));
            const accessToken = hashParams.get('access_token');
            const errorDescription = hashParams.get('error_description');
            const type = hashParams.get('type');

            if (errorDescription) {
                setStatus('error');
                setMessage(decodeURIComponent(errorDescription));
                return;
            }

            if (accessToken || type === 'signup' || type === 'recovery' || type === 'email_change') {
                // La confirmación fue exitosa
                setStatus('success');
                setMessage('¡Tu correo electrónico ha sido verificado exitosamente!');
                return;
            }

            // Verificar si hay una sesión activa (el usuario ya confirmó)
            const { data: { session } } = await supabase.auth.getSession();
            
            if (session) {
                setStatus('success');
                setMessage('¡Tu cuenta está verificada y lista para usar!');
                return;
            }

            // Si no hay token ni sesión, puede ser que el enlace ya fue usado
            // o que el usuario llegó aquí directamente
            const token = searchParams.get('token');
            const tokenHash = searchParams.get('token_hash');
            
            if (token || tokenHash) {
                // Intentar verificar con el token
                const { error } = await supabase.auth.verifyOtp({
                    token_hash: tokenHash || token,
                    type: 'email'
                });

                if (error) {
                    if (error.message.includes('expired')) {
                        setStatus('error');
                        setMessage('El enlace de confirmación ha expirado. Por favor solicita uno nuevo.');
                    } else {
                        setStatus('error');
                        setMessage(error.message);
                    }
                } else {
                    setStatus('success');
                    setMessage('¡Tu correo electrónico ha sido verificado exitosamente!');
                }
            } else {
                // No hay parámetros de confirmación
                setStatus('success');
                setMessage('¡Bienvenido! Tu cuenta está lista para usar.');
            }
        } catch (error) {
            console.error('Error during email confirmation:', error);
            setStatus('error');
            setMessage('Ocurrió un error al verificar tu correo. Por favor intenta de nuevo.');
        }
    };

    const goToLogin = () => {
        navigate('/login');
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-950 to-slate-900 flex items-center justify-center p-4 overflow-hidden relative">
            {/* Animated Background Elements */}
            <div className="absolute inset-0 overflow-hidden">
                <div className="absolute -top-20 -left-20 w-96 h-96 bg-gradient-to-br from-blue-600/20 to-transparent rounded-full blur-3xl animate-float"></div>
                <div className="absolute top-1/4 -right-10 w-64 h-64 bg-gradient-to-r from-purple-600/15 to-transparent rounded-full blur-2xl animate-float-delayed"></div>
                <div className="absolute bottom-1/4 left-1/4 w-48 h-48 bg-gradient-to-tr from-green-500/15 to-transparent rounded-full blur-2xl animate-float"></div>
            </div>

            {/* Main Card */}
            <div className="relative z-10 w-full max-w-md bg-slate-800/50 backdrop-blur-sm rounded-3xl shadow-2xl overflow-hidden border border-slate-700/50 p-8">
                {/* Verifying State */}
                {status === 'verifying' && (
                    <div className="text-center animate-fade-in">
                        <div className="relative mx-auto mb-8 w-24 h-24">
                            <div className="absolute inset-0 border-4 border-blue-500/30 rounded-full animate-ping"></div>
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-20 h-20 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full flex items-center justify-center shadow-lg shadow-blue-500/30">
                                    <Mail className="w-10 h-10 text-white animate-pulse" />
                                </div>
                            </div>
                        </div>
                        <h2 className="text-2xl font-bold text-white mb-3">Verificando tu correo</h2>
                        <p className="text-slate-400 mb-6">Por favor espera un momento...</p>
                        <div className="flex justify-center">
                            <Loader className="w-8 h-8 text-blue-400 animate-spin" />
                        </div>
                    </div>
                )}

                {/* Success State */}
                {status === 'success' && (
                    <div className="text-center animate-success-content">
                        {/* Success Icon */}
                        <div className="relative mx-auto mb-8">
                            <div className="w-24 h-24 rounded-full border-4 border-green-500/30 animate-success-ring"></div>
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-20 h-20 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center shadow-2xl shadow-green-500/50 animate-success-circle">
                                    <CheckCircle className="w-10 h-10 text-white animate-success-check" />
                                </div>
                            </div>
                            <Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-yellow-400 animate-sparkle" />
                            <Sparkles className="absolute -bottom-2 -left-2 w-5 h-5 text-blue-400 animate-sparkle-delayed" />
                        </div>

                        <h2 className="text-2xl font-bold text-white mb-3 animate-success-text">
                            ¡Verificación Exitosa!
                        </h2>
                        <p className="text-slate-300 mb-6 animate-success-text-delayed">
                            {message}
                        </p>

                        {/* Countdown */}
                        <div className="mb-6 animate-success-text-delayed">
                            <p className="text-slate-400 text-sm mb-2">
                                Redirigiendo al inicio de sesión en...
                            </p>
                            <div className="w-16 h-16 mx-auto bg-slate-700/50 rounded-full flex items-center justify-center border-2 border-green-500/50">
                                <span className="text-2xl font-bold text-green-400">{countdown}</span>
                            </div>
                        </div>

                        {/* Progress Bar */}
                        <div className="w-full h-1.5 bg-slate-700 rounded-full overflow-hidden mb-6">
                            <div 
                                className="h-full bg-gradient-to-r from-green-500 to-emerald-500 rounded-full transition-all duration-1000"
                                style={{ width: `${((5 - countdown) / 5) * 100}%` }}
                            ></div>
                        </div>

                        <button
                            onClick={goToLogin}
                            className="w-full bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transform hover:scale-[1.02] active:scale-[0.98]"
                        >
                            Ir al Inicio de Sesión
                            <ArrowRight size={20} />
                        </button>
                    </div>
                )}

                {/* Error State */}
                {status === 'error' && (
                    <div className="text-center animate-fade-in">
                        {/* Error Icon */}
                        <div className="relative mx-auto mb-8">
                            <div className="w-24 h-24 rounded-full border-4 border-red-500/30"></div>
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-20 h-20 bg-gradient-to-br from-red-500 to-rose-600 rounded-full flex items-center justify-center shadow-2xl shadow-red-500/50 animate-shake">
                                    <XCircle className="w-10 h-10 text-white" />
                                </div>
                            </div>
                        </div>

                        <h2 className="text-2xl font-bold text-white mb-3">
                            Error de Verificación
                        </h2>
                        <p className="text-slate-300 mb-6">
                            {message}
                        </p>

                        <div className="space-y-3">
                            <button
                                onClick={goToLogin}
                                className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg shadow-blue-900/50 flex items-center justify-center gap-2 transform hover:scale-[1.02] active:scale-[0.98]"
                            >
                                Ir al Inicio de Sesión
                                <ArrowRight size={20} />
                            </button>
                            <button
                                onClick={() => navigate('/')}
                                className="w-full bg-slate-700 hover:bg-slate-600 text-white font-medium py-3 rounded-xl transition-all"
                            >
                                Volver al Inicio
                            </button>
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-8 text-center text-slate-500 text-xs">
                    © 2025 PresuGenius Pro. Todos los derechos reservados.
                </div>
            </div>

            {/* CSS Animations */}
            <style>{`
                @keyframes float {
                    0%, 100% { transform: translateY(0) rotate(0deg); }
                    50% { transform: translateY(-20px) rotate(5deg); }
                }
                @keyframes float-delayed {
                    0%, 100% { transform: translateY(0) rotate(0deg); }
                    50% { transform: translateY(-15px) rotate(-5deg); }
                }
                @keyframes fadeIn {
                    from { opacity: 0; transform: translateY(20px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                @keyframes successContent {
                    0% { opacity: 0; transform: scale(0.9); }
                    100% { opacity: 1; transform: scale(1); }
                }
                @keyframes successRing {
                    0% { transform: scale(0.5); opacity: 0; }
                    50% { transform: scale(1.1); opacity: 1; }
                    100% { transform: scale(1); opacity: 1; }
                }
                @keyframes successCircle {
                    0% { transform: scale(0); }
                    50% { transform: scale(1.1); }
                    100% { transform: scale(1); }
                }
                @keyframes successCheck {
                    0% { transform: scale(0) rotate(-45deg); opacity: 0; }
                    50% { transform: scale(1.2) rotate(0deg); }
                    100% { transform: scale(1) rotate(0deg); opacity: 1; }
                }
                @keyframes successText {
                    0% { opacity: 0; transform: translateY(10px); }
                    100% { opacity: 1; transform: translateY(0); }
                }
                @keyframes sparkle {
                    0%, 100% { transform: scale(0) rotate(0deg); opacity: 0; }
                    50% { transform: scale(1) rotate(180deg); opacity: 1; }
                }
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    25% { transform: translateX(-5px); }
                    75% { transform: translateX(5px); }
                }
                @keyframes pulse-glow {
                    0%, 100% { box-shadow: 0 0 20px rgba(34, 197, 94, 0.5); }
                    50% { box-shadow: 0 0 40px rgba(34, 197, 94, 0.8); }
                }
                
                .animate-float { animation: float 6s ease-in-out infinite; }
                .animate-float-delayed { animation: float-delayed 8s ease-in-out infinite; }
                .animate-fade-in { animation: fadeIn 0.6s ease-out forwards; }
                .animate-success-content { animation: successContent 0.5s ease-out forwards; }
                .animate-success-ring { animation: successRing 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards, pulse-glow 2s ease-in-out infinite 1s; }
                .animate-success-circle { animation: successCircle 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.2s forwards; transform: scale(0); }
                .animate-success-check { animation: successCheck 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.4s forwards; opacity: 0; }
                .animate-success-text { animation: successText 0.5s ease-out 0.5s forwards; opacity: 0; }
                .animate-success-text-delayed { animation: successText 0.5s ease-out 0.7s forwards; opacity: 0; }
                .animate-sparkle { animation: sparkle 1s ease-in-out infinite; }
                .animate-sparkle-delayed { animation: sparkle 1s ease-in-out infinite 0.5s; }
                .animate-shake { animation: shake 0.5s ease-in-out; }
            `}</style>
        </div>
    );
};

export default ConfirmEmail;

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { ArrowRight, Info, Sparkles, PieChart, Bot, FolderOpen, TrendingUp, Calendar, DollarSign, FileText, Plus, Clock, BarChart3, Camera } from 'lucide-react';

import { useNavigate } from 'react-router-dom';
import Card from '../components/ui/Card';
import { useProject } from '../context/ProjectContext';
import { useAuth } from '../context/AuthContext';
import { formatCurrency } from '../utils/format';
import { AIBudgetService } from '../services/AIBudgetService';
import { ValidationService } from '../services/ValidationService';
import { ErrorService } from '../services/ErrorService';
import { CalculationsService } from '../services/CalculationsService';
import ErrorTestPanel from '../components/testing/ErrorTestPanel';
import { supabase } from '../lib/supabaseClient';

const Dashboard = () => {
    const { items, projectInfo, calculateSubtotal, calculateTotal, showToast, setItems, catalog, savedBudgets } = useProject();
    const { user } = useAuth();
    const navigate = useNavigate();
    const [aiPrompt, setAiPrompt] = useState('');
    const [isAiLoading, setIsAiLoading] = useState(false);
    const [showErrorTestPanel, setShowErrorTestPanel] = useState(false);
    const [recentProjects, setRecentProjects] = useState([]);
    const [overallStats, setOverallStats] = useState(null);
    const [loadingProjects, setLoadingProjects] = useState(false);

    // Cargar proyectos recientes y estadísticas
    useEffect(() => {
        loadProjectsAndStats();
    }, [user, savedBudgets]);

    const loadProjectsAndStats = async () => {
        if (!user) return;

        setLoadingProjects(true);
        try {
            // Cargar proyectos con sus items
            const { data: projects, error: projectsError } = await supabase
                .from('projects')
                .select('*')
                .eq('user_id', user.id)
                .order('updated_at', { ascending: false })
                .limit(10);

            if (projectsError) throw projectsError;

            // Calcular estadísticas de cada proyecto
            const projectsWithStats = await Promise.all(
                (projects || []).map(async (project) => {
                    const { data: projectItems } = await supabase
                        .from('budget_items')
                        .select('*')
                        .eq('project_id', project.id);

                    const itemsList = projectItems || [];
                    const subtotal = CalculationsService.calculateSubtotal(itemsList);
                    const total = CalculationsService.calculateTotal(itemsList, {
                        indirectPercentage: project.indirect_percentage || 0,
                        profitPercentage: project.profit_percentage || 0,
                        taxRate: project.tax_rate || 16
                    });

                    return {
                        id: project.id,
                        name: project.name,
                        client: project.client || 'Sin cliente',
                        type: project.type || 'General',
                        location: project.location || '',
                        updatedAt: project.updated_at,
                        createdAt: project.created_at,
                        itemsCount: itemsList.length,
                        total: total.total,
                        subtotal: subtotal
                    };
                })
            );

            setRecentProjects(projectsWithStats);

            // Calcular estadísticas generales
            const stats = {
                totalProjects: projects?.length || 0,
                totalValue: projectsWithStats.reduce((sum, p) => sum + (p.total || 0), 0),
                totalItems: projectsWithStats.reduce((sum, p) => sum + (p.itemsCount || 0), 0),
                avgProjectValue: projectsWithStats.length > 0
                    ? projectsWithStats.reduce((sum, p) => sum + (p.total || 0), 0) / projectsWithStats.length
                    : 0,
                projectsByType: {},
                recentCount: projectsWithStats.filter(p => {
                    const daysSinceUpdate = (Date.now() - new Date(p.updatedAt).getTime()) / (1000 * 60 * 60 * 24);
                    return daysSinceUpdate <= 30;
                }).length
            };

            // Agrupar por tipo
            projectsWithStats.forEach(p => {
                stats.projectsByType[p.type] = (stats.projectsByType[p.type] || 0) + 1;
            });

            setOverallStats(stats);
        } catch (error) {
            console.error('Error loading projects:', error);
        } finally {
            setLoadingProjects(false);
        }
    };

    // Memoized calculations para proyecto actual
    const total = useMemo(() => calculateTotal(), [items, projectInfo, calculateTotal]);
    const subtotal = useMemo(() => calculateSubtotal(), [items, calculateSubtotal]);
    const categories = ['Materiales', 'Mano de Obra', 'Equipos', 'Instalaciones', 'Obra Civil'];

    // Memoized category data
    const catData = useMemo(() => {
        return categories.map(cat => {
            const amount = items.filter(i => i.category === cat).reduce((a, b) => a + (b.quantity * b.unitPrice), 0);
            return { cat, amount, percent: subtotal > 0 ? (amount / subtotal * 100) : 0 };
        }).filter(d => d.amount > 0);
    }, [items, subtotal]);

    // Generate budget from AI prompt
    const generateBudgetFromAI = useCallback(async () => {
        if (!aiPrompt.trim()) {
            showToast('Por favor, describe qué necesitas agregar', 'warning');
            return;
        }

        setIsAiLoading(true);
        try {
            const generatedItems = await AIBudgetService.generateBudgetFromPrompt(
                aiPrompt,
                projectInfo,
                catalog
            );

            if (generatedItems.length === 0) {
                showToast('No se pudieron generar partidas. Intenta con una descripción más específica.', 'warning');
                return;
            }

            // Validate generated items
            const validItems = generatedItems.filter(item => {
                const validation = ValidationService.validateItem(item);
                return validation.valid;
            });

            if (validItems.length === 0) {
                showToast('Las partidas generadas no son válidas', 'error');
                return;
            }

            setItems([...items, ...validItems]);
            setAiPrompt('');
            showToast(`Se generaron ${validItems.length} partidas`, 'success');
        } catch (error) {
            const errorMessage = ErrorService.getErrorMessage(error);
            ErrorService.logError(error, 'Dashboard.generateBudgetFromAI');
            showToast(errorMessage, 'error');
        } finally {
            setIsAiLoading(false);
        }
    }, [aiPrompt, projectInfo, catalog, items, setItems, showToast]);

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        const date = new Date(dateString);
        const now = new Date();
        const diffTime = Math.abs(now - date);
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays === 0) return 'Hoy';
        if (diffDays === 1) return 'Ayer';
        if (diffDays < 7) return `Hace ${diffDays} días`;
        if (diffDays < 30) return `Hace ${Math.floor(diffDays / 7)} semanas`;
        return date.toLocaleDateString('es-MX', { day: 'numeric', month: 'short' });
    };

    const openProject = async (projectId) => {
        navigate(`/editor?project=${projectId}`);
    };

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header */}
            <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-end">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-slate-50 mb-1">Visión General</h1>
                    <p className="text-slate-700 dark:text-slate-200">Panel de Control - Resumen de tus proyectos y estadísticas</p>
                </div>
                <div className="flex gap-3 flex-wrap justify-end">
                    <button
                        onClick={() => navigate('/reports')}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-xl font-semibold shadow-lg shadow-indigo-200 dark:shadow-indigo-900/50 transition flex items-center gap-2"
                    >
                        <Camera size={18} />
                        Reportes de Obra
                    </button>
                    <button
                        onClick={() => navigate('/editor?new=true')}
                        className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-xl font-semibold shadow-lg shadow-green-200 dark:shadow-green-900/50 transition flex items-center gap-2"
                    >
                        <Plus size={18} />
                        Nuevo Presupuesto
                    </button>
                    {items.length > 0 && (
                        <button
                            onClick={() => navigate('/editor')}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-xl font-semibold shadow-lg shadow-blue-200 dark:shadow-blue-900/50 transition flex items-center gap-2"
                        >
                            Ir al Editor <ArrowRight size={18} />
                        </button>
                    )}
                </div>

            </div>

            {/* Estadísticas Generales */}
            {overallStats && overallStats.totalProjects > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <Card className="bg-gradient-to-br from-blue-500 to-blue-600 text-white border-none">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-blue-100 text-sm font-medium">Total Proyectos</p>
                                <p className="text-3xl font-bold mt-1">{overallStats.totalProjects}</p>
                            </div>
                            <FolderOpen size={32} className="text-blue-200 opacity-70" />
                        </div>
                    </Card>

                    <Card className="bg-gradient-to-br from-emerald-500 to-emerald-600 text-white border-none">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-emerald-100 text-sm font-medium">Valor Total</p>
                                <p className="text-3xl font-bold mt-1">{formatCurrency(overallStats.totalValue)}</p>
                            </div>
                            <DollarSign size={32} className="text-emerald-200 opacity-70" />
                        </div>
                    </Card>

                    <Card className="bg-gradient-to-br from-purple-500 to-purple-600 text-white border-none">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-purple-100 text-sm font-medium">Total Partidas</p>
                                <p className="text-3xl font-bold mt-1">{overallStats.totalItems}</p>
                            </div>
                            <FileText size={32} className="text-purple-200 opacity-70" />
                        </div>
                    </Card>

                    <Card className="bg-gradient-to-br from-orange-500 to-orange-600 text-white border-none">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-orange-100 text-sm font-medium">Promedio/Proyecto</p>
                                <p className="text-3xl font-bold mt-1">{formatCurrency(overallStats.avgProjectValue)}</p>
                            </div>
                            <TrendingUp size={32} className="text-orange-200 opacity-70" />
                        </div>
                    </Card>
                </div>
            )}

            {/* Proyecto Actual */}
            {items.length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Tarjeta de Total del Proyecto Actual */}
                    <Card className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white border-none relative overflow-hidden">
                        <div className="relative z-10">
                            <p className="text-blue-100 font-medium mb-1">Proyecto Actual</p>
                            <h3 className="text-2xl font-bold mb-2">{projectInfo.project || 'Sin nombre'}</h3>
                            <p className="text-4xl font-bold mb-4">{formatCurrency(total)}</p>
                            <div className="flex items-center text-sm bg-white/10 w-fit px-3 py-1 rounded-full">
                                <Info size={14} className="mr-2" /> Incluye {projectInfo.taxRate}% IVA
                            </div>
                        </div>
                        <Sparkles className="absolute -right-6 -bottom-6 text-white opacity-10" size={150} />
                    </Card>

                    {/* Estadísticas del Proyecto Actual */}
                    <Card title="Métricas del Proyecto">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-3 bg-slate-50 dark:bg-slate-800/80 rounded-lg border border-slate-200 dark:border-slate-700">
                                <p className="text-xs text-slate-600 dark:text-slate-200 uppercase font-bold">Partidas</p>
                                <p className="text-2xl font-bold text-slate-900 dark:text-slate-50">{items.length}</p>
                            </div>
                            <div className="p-3 bg-slate-50 dark:bg-slate-800/80 rounded-lg border border-slate-200 dark:border-slate-700">
                                <p className="text-xs text-slate-600 dark:text-slate-200 uppercase font-bold">Cliente</p>
                                <p className="text-lg font-bold text-slate-900 dark:text-slate-50 truncate">{projectInfo.client || "Sin asignar"}</p>
                            </div>
                            <div className="col-span-2 p-3 bg-slate-50 dark:bg-slate-800/80 rounded-lg border border-slate-200 dark:border-slate-700">
                                <p className="text-xs text-slate-600 dark:text-slate-200 uppercase font-bold">Tipo de Proyecto</p>
                                <p className="text-md font-bold text-blue-700 dark:text-blue-300">{projectInfo.type}</p>
                            </div>
                        </div>
                    </Card>

                    {/* Desglose por Categoría */}
                    <Card title="Desglose por Categoría">
                        {catData.length > 0 ? (
                            <div className="space-y-4">
                                {catData.map(d => (
                                    <div key={d.cat}>
                                        <div className="flex justify-between text-sm mb-1">
                                            <span className="font-medium text-slate-700 dark:text-slate-200">{d.cat}</span>
                                            <span className="text-slate-900 dark:text-slate-50 font-mono font-semibold">{formatCurrency(d.amount)}</span>
                                        </div>
                                        <div className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                                            <div className="h-full bg-blue-600 dark:bg-blue-500 rounded-full" style={{ width: `${d.percent}%` }}></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-slate-400 dark:text-slate-500 py-8">
                                <PieChart size={40} className="mb-2 opacity-30 dark:opacity-50" />
                                <p className="text-sm text-slate-500 dark:text-slate-300">Sin datos aún</p>
                            </div>
                        )}
                    </Card>
                </div>
            )}

            {/* Sin Proyecto Actual */}
            {items.length === 0 && !loadingProjects && (
                <Card className="text-center py-12 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-900 border-2 border-dashed border-slate-400 dark:border-slate-600">
                    <FolderOpen size={64} className="mx-auto text-slate-400 dark:text-slate-500 mb-4" />
                    <h3 className="text-xl font-bold text-slate-800 dark:text-slate-50 mb-2">No hay proyecto activo</h3>
                    <p className="text-slate-600 dark:text-slate-200 mb-6">Crea un nuevo proyecto o abre uno existente para comenzar</p>
                    <button
                        onClick={() => navigate('/editor?new=true')}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-semibold shadow-lg transition inline-flex items-center gap-2"
                    >
                        <Plus size={20} />
                        Crear Nuevo Proyecto
                    </button>
                </Card>
            )}

            {/* Proyectos Recientes */}
            {recentProjects.length > 0 && (
                <Card title="Proyectos Recientes" className="overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b-2 border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-800">
                                    <th className="text-left py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Proyecto</th>
                                    <th className="text-left py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Cliente</th>
                                    <th className="text-left py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Tipo</th>
                                    <th className="text-right py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Valor</th>
                                    <th className="text-center py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Partidas</th>
                                    <th className="text-left py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Última Modificación</th>
                                    <th className="text-center py-3 px-4 text-xs font-bold text-slate-700 dark:text-slate-200 uppercase">Acciones</th>
                                </tr>
                            </thead>
                            <tbody>
                                {recentProjects.map((project) => (
                                    <tr
                                        key={project.id}
                                        className="border-b border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800/80 transition cursor-pointer"
                                        onClick={() => openProject(project.id)}
                                    >
                                        <td className="py-4 px-4">
                                            <p className="font-semibold text-slate-900 dark:text-slate-50">{project.name}</p>
                                        </td>
                                        <td className="py-4 px-4 text-sm text-slate-700 dark:text-slate-200">{project.client}</td>
                                        <td className="py-4 px-4">
                                            <span className="inline-block px-3 py-1 bg-blue-100 dark:bg-blue-900/50 text-blue-800 dark:text-blue-100 rounded-md text-xs font-semibold border border-blue-200 dark:border-blue-700">
                                                {project.type}
                                            </span>
                                        </td>
                                        <td className="py-4 px-4 text-right font-bold text-slate-900 dark:text-slate-50">
                                            {formatCurrency(project.total || 0)}
                                        </td>
                                        <td className="py-4 px-4 text-center text-sm text-slate-700 dark:text-slate-200 font-medium">
                                            {project.itemsCount}
                                        </td>
                                        <td className="py-4 px-4 text-sm text-slate-600 dark:text-slate-200 flex items-center gap-1">
                                            <Clock size={14} className="text-slate-500 dark:text-slate-200" />
                                            {formatDate(project.updatedAt)}
                                        </td>
                                        <td className="py-4 px-4 text-center">
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    openProject(project.id);
                                                }}
                                                className="text-blue-700 dark:text-blue-300 hover:text-blue-800 dark:hover:text-blue-200 font-semibold text-sm underline-offset-2 hover:underline"
                                            >
                                                Abrir →
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            )}

            {/* Sin Proyectos */}
            {!loadingProjects && recentProjects.length === 0 && items.length === 0 && (
                <Card className="text-center py-12">
                    <FolderOpen size={64} className="mx-auto text-slate-400 dark:text-slate-500 mb-4" />
                    <h3 className="text-xl font-bold text-slate-800 dark:text-slate-50 mb-2">No tienes proyectos aún</h3>
                    <p className="text-slate-600 dark:text-slate-200 mb-6">Crea tu primer proyecto para comenzar a trabajar</p>
                    <button
                        onClick={() => navigate('/editor?new=true')}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-semibold shadow-lg transition inline-flex items-center gap-2"
                    >
                        <Plus size={20} />
                        Crear Primer Proyecto
                    </button>
                </Card>
            )}

            {/* Gráfico de Distribución por Tipo (si hay proyectos) */}
            {overallStats && overallStats.totalProjects > 0 && Object.keys(overallStats.projectsByType).length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Card title="Distribución por Tipo de Proyecto">
                        <div className="space-y-3">
                            {Object.entries(overallStats.projectsByType).map(([type, count]) => {
                                const percent = (count / overallStats.totalProjects) * 100;
                                return (
                                    <div key={type}>
                                        <div className="flex justify-between text-sm mb-1">
                                            <span className="font-medium text-slate-700 dark:text-slate-200">{type}</span>
                                            <span className="text-slate-900 dark:text-slate-50 font-bold">{count} proyectos</span>
                                        </div>
                                        <div className="w-full h-3 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                                            <div className="h-full bg-gradient-to-r from-purple-600 to-pink-600 dark:from-purple-500 dark:to-pink-500 rounded-full" style={{ width: `${percent}%` }}></div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </Card>

                    <Card title="Actividad Reciente">
                        <div className="space-y-4">
                            <div className="flex items-center justify-between p-4 bg-slate-100 dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-green-100 dark:bg-green-900/50 rounded-lg border border-green-200 dark:border-green-800">
                                        <Calendar size={20} className="text-green-700 dark:text-green-400" />
                                    </div>
                                    <div>
                                        <p className="font-semibold text-slate-900 dark:text-slate-50">Proyectos Activos</p>
                                        <p className="text-sm text-slate-600 dark:text-slate-200">Últimos 30 días</p>
                                    </div>
                                </div>
                                <p className="text-3xl font-bold text-green-700 dark:text-green-400">{overallStats.recentCount}</p>
                            </div>
                            {recentProjects.length > 0 && (
                                <div className="p-4 bg-blue-50 dark:bg-blue-900/30 rounded-lg border border-blue-200 dark:border-blue-800">
                                    <p className="text-sm text-slate-700 dark:text-slate-200 mb-2">Último proyecto modificado:</p>
                                    <p className="font-semibold text-slate-900 dark:text-slate-50">{recentProjects[0]?.name}</p>
                                    <p className="text-xs text-slate-600 dark:text-slate-200 mt-1">{formatDate(recentProjects[0]?.updatedAt)}</p>
                                </div>
                            )}
                        </div>
                    </Card>
                </div>
            )}

            {/* AI Quick Actions */}
            <Card className="bg-gradient-to-r from-indigo-50 to-purple-50 dark:from-indigo-900/30 dark:to-purple-900/30 border-2 border-indigo-300 dark:border-indigo-700">
                <div className="flex flex-col md:flex-row items-center gap-6">
                    <div className="bg-white dark:bg-slate-800 p-4 rounded-full shadow-lg text-indigo-700 dark:text-indigo-300 border-2 border-indigo-200 dark:border-indigo-700">
                        <Bot size={32} />
                    </div>
                    <div className="flex-1">
                        <h3 className="font-bold text-indigo-900 dark:text-indigo-50 text-lg mb-1">Asistente Inteligente</h3>
                        <p className="text-indigo-800 dark:text-indigo-200 text-sm">Genera partidas rápidamente con inteligencia artificial. Describe tu proyecto y la IA creará el presupuesto.</p>
                    </div>
                    <div className="flex-1 w-full flex gap-2">
                        <input
                            value={aiPrompt}
                            onChange={(e) => setAiPrompt(e.target.value)}
                            placeholder="Ej: Remodelación de baño 2x2 metros con azulejo y regadera..."
                            className="w-full px-4 py-3 rounded-lg border-2 border-indigo-300 dark:border-indigo-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-50 placeholder:text-slate-500 dark:placeholder:text-slate-400 dark:placeholder:opacity-80 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 dark:focus:border-indigo-400 outline-none"
                            onKeyDown={(e) => e.key === 'Enter' && generateBudgetFromAI()}
                            disabled={isAiLoading}
                        />
                        <button
                            onClick={generateBudgetFromAI}
                            disabled={isAiLoading || !aiPrompt.trim()}
                            className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-lg font-bold shadow-lg disabled:opacity-50 disabled:cursor-not-allowed transition flex items-center justify-center min-w-[60px]"
                        >
                            {isAiLoading ? (
                                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                            ) : (
                                <Sparkles size={20} />
                            )}
                        </button>
                    </div>
                </div>
            </Card>

            {/* Panel de Prueba de Errores - Solo en desarrollo */}
