            {/* Generator Modal */}
            {showGeneratorModal && currentGeneratorItem && (
                <GeneratorModal
                    isOpen={showGeneratorModal}
                    onClose={() => {
                        setShowGeneratorModal(false);
                        setCurrentGeneratorItem(null);
                    }}
                    onApply={handleApplyGenerator}
