    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState('date'); // 'date', 'name', 'total', 'items'
    const [sortOrder, setSortOrder] = useState('desc'); // 'asc', 'desc'
    const [filterType, setFilterType] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [priceRange, setPriceRange] = useState({ min: '', max: '' });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            // Import dynamically to avoid circular dependencies if any, or just use the imported service
            const { default: ProjectPersistenceService } = await import('../services/ProjectPersistenceService');
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading history:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id, name) => {
        if (window.confirm(`¿Eliminar el proyecto "${name}"?`)) {
            await contextDeleteBudget(id);
            // Reload list to ensure sync
            loadProjects();
        }
    };

    // Filtrar y ordenar proyectos
    const filteredAndSortedProjects = useMemo(() => {
        let filtered = [...projects];

        // Búsqueda por texto
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => 
                p.project?.toLowerCase().includes(searchLower) ||
                p.client?.toLowerCase().includes(searchLower) ||
                p.type?.toLowerCase().includes(searchLower)
            );
        }

        // Filtro por tipo
        if (filterType !== 'all') {
            filtered = filtered.filter(p => p.type === filterType);
        }

        // Filtro por rango de fechas
        if (dateRange.start || dateRange.end) {
            filtered = filtered.filter(p => {
                if (!p.lastModified) return false;
                const projectDate = new Date(p.lastModified);
                if (dateRange.start && projectDate < new Date(dateRange.start)) return false;
                if (dateRange.end && projectDate > new Date(dateRange.end + 'T23:59:59')) return false;
                return true;
            });
        }

        // Filtro por rango de precios
        if (priceRange.min || priceRange.max) {
            filtered = filtered.filter(p => {
                const total = p.total || 0;
                if (priceRange.min && total < parseFloat(priceRange.min)) return false;
                if (priceRange.max && total > parseFloat(priceRange.max)) return false;
                return true;
            });
        }

        // Ordenamiento
        filtered.sort((a, b) => {
            let aVal, bVal;
            switch (sortBy) {
                case 'name':
                    aVal = (a.project || '').toLowerCase();
                    bVal = (b.project || '').toLowerCase();
                    break;
                case 'total':
                    aVal = a.total || 0;
                    bVal = b.total || 0;
                    break;
                case 'items':
                    aVal = a.items?.length || 0;
                    bVal = b.items?.length || 0;
                    break;
                case 'date':
                default:
                    aVal = new Date(a.lastModified || 0).getTime();
                    bVal = new Date(b.lastModified || 0).getTime();
                    break;
            }

            if (sortOrder === 'asc') {
                return aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
            } else {
                return aVal < bVal ? 1 : aVal > bVal ? -1 : 0;
            }
        });

        return filtered;
    }, [projects, searchTerm, filterType, dateRange, priceRange, sortBy, sortOrder]);

    // Obtener tipos únicos para el filtro
    const projectTypes = useMemo(() => {
        const types = new Set(projects.map(p => p.type).filter(Boolean));
        return ['all', ...Array.from(types)];
    }, [projects]);

    const handleSort = (field) => {
        if (sortBy === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setSortOrder('desc');
        }
    };

    const clearFilters = () => {
        setSearchTerm('');
        setFilterType('all');
        setDateRange({ start: '', end: '' });
        setPriceRange({ min: '', max: '' });
    };

    const hasActiveFilters = searchTerm || filterType !== 'all' || dateRange.start || dateRange.end || priceRange.min || priceRange.max;

    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-50">Historial de Proyectos</h2>
                <button 
                    onClick={loadProjects} 
                    className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                >
                    Actualizar
                </button>
            </div>

            {/* Búsqueda y Filtros */}
            <Card className="p-4">
                <div className="space-y-4">
                    {/* Barra de búsqueda */}
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar por nombre, cliente o tipo..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                        />
                    </div>

                    {/* Botón de filtros */}
                    <div className="flex items-center justify-between">
                        <button
                            onClick={() => setShowFilters(!showFilters)}
                            className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition"
                        >
                            <Filter size={18} />
                            Filtros Avanzados
                            {hasActiveFilters && (
                                <span className="bg-blue-500 text-white text-xs px-2 py-0.5 rounded-full">
                                    {[searchTerm && 1, filterType !== 'all' && 1, dateRange.start && 1, dateRange.end && 1, priceRange.min && 1, priceRange.max && 1].filter(Boolean).length}
                                </span>
                            )}
                        </button>
                        {hasActiveFilters && (
                            <button
                                onClick={clearFilters}
                                className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200"
                            >
                                <X size={16} />
                                Limpiar filtros
                            </button>
                        )}
                    </div>

                    {/* Panel de filtros expandible */}
                    {showFilters && (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pt-4 border-t border-slate-200 dark:border-slate-700">
                            {/* Filtro por tipo */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    Tipo de Proyecto
                                </label>
                                <select
                                    value={filterType}
                                    onChange={(e) => setFilterType(e.target.value)}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                >
                                    {projectTypes.map(type => (
                                        <option key={type} value={type}>
                                            {type === 'all' ? 'Todos los tipos' : type}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Rango de fechas - Inicio */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Desde
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.start}
                                    onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de fechas - Fin */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Hasta
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.end}
                                    onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de precios */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <DollarSign size={14} className="inline mr-1" />
                                    Rango de Precio
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="number"
                                        placeholder="Mín"
                                        value={priceRange.min}
                                        onChange={(e) => setPriceRange({ ...priceRange, min: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                    <input
                                        type="number"
                                        placeholder="Máx"
                                        value={priceRange.max}
                                        onChange={(e) => setPriceRange({ ...priceRange, max: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Ordenamiento */}
                    <div className="flex items-center gap-4 pt-2 border-t border-slate-200 dark:border-slate-700">
                        <span className="text-sm text-slate-600 dark:text-slate-400">Ordenar por:</span>
                        <div className="flex gap-2">
                            {[
                                { key: 'date', label: 'Fecha' },
                                { key: 'name', label: 'Nombre' },
                                { key: 'total', label: 'Total' },
                                { key: 'items', label: 'Partidas' }
                            ].map(option => (
                                <button
                                    key={option.key}
                                    onClick={() => handleSort(option.key)}
                                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm transition ${
                                        sortBy === option.key
                                            ? 'bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 font-medium'
                                            : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                                    }`}
                                >
                                    {option.label}
                                    {sortBy === option.key && (
                                        sortOrder === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </Card>

            {/* Contador de resultados */}
            {!loading && projects.length > 0 && (
                <div className="text-sm text-slate-600 dark:text-slate-400">
                    Mostrando {filteredAndSortedProjects.length} de {projects.length} proyectos
                    {hasActiveFilters && ' (filtrados)'}
                </div>
            )}

            {loading ? (
                <div className="text-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                </div>
            ) : projects.length === 0 ? (
                <Card className="text-center py-20">
                    <HistoryIcon size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400">No hay proyectos guardados aún.</p>
                </Card>
            ) : filteredAndSortedProjects.length === 0 ? (
                <Card className="text-center py-20">
                    <Search size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400 mb-2">No se encontraron proyectos con los filtros seleccionados.</p>
                    <button
                        onClick={clearFilters}
                        className="text-blue-600 dark:text-blue-400 hover:underline"
                    >
                        Limpiar filtros
                    </button>
                </Card>
            ) : (
                <div className="grid gap-4">
                    {filteredAndSortedProjects.map(b => (
                        <Card key={b.id} className="p-6 hover:shadow-md transition">
                            <div className="flex justify-between items-center">
                                <div className="flex-1">
                                    <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100 mb-1">{b.project}</h3>
                                    <p className="text-sm text-slate-600 dark:text-slate-400 mb-2">
                                        Cliente: {b.client || 'Sin cliente'} • {b.lastModified ? new Date(b.lastModified).toLocaleDateString('es-MX', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        }) : 'Fecha desconocida'}
                                    </p>
                                    <div className="flex gap-2 flex-wrap">
                                        <span className="text-xs bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 px-2 py-1 rounded font-medium">{b.type || 'General'}</span>
                                        <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 px-2 py-1 rounded">{b.items?.length || 0} partidas</span>
                                    </div>
                                </div>
                                <div className="text-right ml-4">
                                    <p className="font-bold text-xl text-blue-600 dark:text-blue-400 font-mono mb-3">{formatCurrency(b.total || 0)}</p>
                                    <div className="flex gap-2 justify-end">
                                        <button 
                                            onClick={() => loadBudget(b)} 
                                            className="px-4 py-2 text-sm bg-blue-600 dark:bg-blue-500 hover:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold rounded-lg transition"
                                        >
                                            Abrir
                                        </button>
                                        <button
                                            onClick={() => handleDelete(b.id, b.project)}
                                            className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                            title="Eliminar proyecto"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

export default History;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Hammer, Mail, Lock, User, AlertCircle, Loader, CheckCircle, Sparkles } from 'lucide-react';

const Login = () => {
    const navigate = useNavigate();
    const { signIn, signUp } = useAuth();

    const [isSignUp, setIsSignUp] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [rememberMe, setRememberMe] = useState(false);
    const [loginSuccess, setLoginSuccess] = useState(false);
    const [particles, setParticles] = useState([]);

    const [formData, setFormData] = useState({
        email: '',
        password: '',
        confirmPassword: '',
        fullName: ''
    });

    // Generate confetti particles
    const generateParticles = () => {
        const colors = ['#3b82f6', '#8b5cf6', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#ec4899'];
        const newParticles = [];
        for (let i = 0; i < 50; i++) {
            newParticles.push({
                id: i,
                x: Math.random() * 100,
                y: Math.random() * 100,
                size: Math.random() * 8 + 4,
                color: colors[Math.floor(Math.random() * colors.length)],
                delay: Math.random() * 0.5,
                duration: Math.random() * 1 + 1.5,
                rotation: Math.random() * 360
            });
        }
        setParticles(newParticles);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (isSignUp) {
                if (formData.password !== formData.confirmPassword) {
                    setError('Las contraseñas no coinciden');
                    setLoading(false);
                    return;
                }

                if (formData.password.length < 6) {
                    setError('La contraseña debe tener al menos 6 caracteres');
                    setLoading(false);
                    return;
                }

                const { error: signUpError } = await signUp(
                    formData.email,
                    formData.password,
                    { full_name: formData.fullName }
                );

                if (signUpError) throw signUpError;

                setError('');
                alert('Cuenta creada! Por favor revisa tu email para confirmar tu cuenta.');
                setIsSignUp(false);
            } else {
                const { error: signInError } = await signIn(formData.email, formData.password);

                if (signInError) throw signInError;

                // Show success animation
                setLoginSuccess(true);
                generateParticles();
                
                // Navigate after animation
                setTimeout(() => {
                    navigate('/dashboard');
                }, 2000);
            }
        } catch (err) {
            console.error('Auth error:', err);

            if (err.message?.includes('Failed to fetch') || err.message?.includes('ERR_NAME_NOT_RESOLVED')) {
                setError('⚠️ No se puede conectar con Supabase. Usa el modo local para continuar.');
            } else {
                setError(err.message || 'Error de autenticación');
            }
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-950 to-slate-900 flex items-center justify-center p-4 overflow-hidden relative">
            {/* Success Overlay */}
            {loginSuccess && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/90 backdrop-blur-md animate-success-overlay">
                    {/* Confetti Particles */}
                    <div className="absolute inset-0 overflow-hidden pointer-events-none">
                        {particles.map((particle) => (
                            <div
                                key={particle.id}
                                className="absolute animate-confetti"
                                style={{
                                    left: `${particle.x}%`,
                                    top: '-10%',
                                    width: `${particle.size}px`,
                                    height: `${particle.size}px`,
                                    backgroundColor: particle.color,
                                    borderRadius: Math.random() > 0.5 ? '50%' : '2px',
                                    animationDelay: `${particle.delay}s`,
                                    animationDuration: `${particle.duration}s`,
                                    transform: `rotate(${particle.rotation}deg)`
                                }}
                            />
                        ))}
                    </div>

                    {/* Success Content */}
                    <div className="relative z-10 text-center animate-success-content">
                        {/* Animated Circle with Checkmark */}
                        <div className="relative mx-auto mb-8">
                            {/* Outer Ring */}
                            <div className="w-32 h-32 rounded-full border-4 border-green-500/30 animate-success-ring"></div>
                            
                            {/* Inner Circle */}
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-24 h-24 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center shadow-2xl shadow-green-500/50 animate-success-circle">
                                    <CheckCircle className="w-12 h-12 text-white animate-success-check" />
                                </div>
                            </div>

                            {/* Sparkles */}
                            <Sparkles className="absolute -top-2 -right-2 w-8 h-8 text-yellow-400 animate-sparkle" />
                            <Sparkles className="absolute -bottom-2 -left-2 w-6 h-6 text-blue-400 animate-sparkle-delayed" />
                            <Sparkles className="absolute top-1/2 -right-4 w-5 h-5 text-purple-400 animate-sparkle" />
                        </div>

                        {/* Success Text */}
                        <h2 className="text-3xl font-bold text-white mb-3 animate-success-text">
                            ¡Bienvenido!
                        </h2>
                        <p className="text-slate-300 text-lg mb-6 animate-success-text-delayed">
                            Inicio de sesión exitoso
                        </p>

                        {/* Loading Bar */}
                        <div className="w-64 h-1.5 bg-slate-700 rounded-full mx-auto overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-blue-500 via-purple-500 to-green-500 rounded-full animate-success-bar"></div>
                        </div>
                        <p className="text-slate-500 text-sm mt-3 animate-success-text-delayed">
                            Redirigiendo al dashboard...
                        </p>
                    </div>
                </div>
            )}

            {/* Animated Background Elements */}
            <div className="absolute inset-0 overflow-hidden">
                {/* Diagonal Lines/Shapes */}
                <div className="absolute -top-20 -left-20 w-96 h-96 bg-gradient-to-br from-blue-600/20 to-transparent rounded-full blur-3xl animate-float"></div>
                <div className="absolute top-1/4 -left-10 w-64 h-64 bg-gradient-to-r from-purple-600/15 to-transparent rounded-full blur-2xl animate-float-delayed"></div>
                <div className="absolute bottom-1/4 left-1/4 w-48 h-48 bg-gradient-to-tr from-blue-500/15 to-transparent rounded-full blur-2xl animate-float"></div>
                
                {/* Diagonal Stripes */}
                <div className="absolute inset-0 opacity-10">
                    <div className="absolute top-0 left-0 w-full h-full">
                        <div className="absolute top-20 -left-20 w-[600px] h-3 bg-gradient-to-r from-transparent via-blue-400 to-transparent transform rotate-45 animate-slide"></div>
                        <div className="absolute top-40 -left-10 w-[500px] h-2 bg-gradient-to-r from-transparent via-purple-400/70 to-transparent transform rotate-45 animate-slide-delayed"></div>
                        <div className="absolute top-60 left-0 w-[400px] h-4 bg-gradient-to-r from-transparent via-blue-300/50 to-transparent transform rotate-45 animate-slide"></div>
                        <div className="absolute top-80 left-10 w-[300px] h-2 bg-gradient-to-r from-transparent via-purple-300/60 to-transparent transform rotate-45 animate-slide-delayed"></div>
                        <div className="absolute bottom-40 -left-20 w-[550px] h-3 bg-gradient-to-r from-transparent via-blue-400/40 to-transparent transform rotate-45 animate-slide"></div>
                    </div>
                </div>

                {/* Floating Circles */}
                <div className="absolute top-1/3 left-1/6 w-4 h-4 bg-blue-400/40 rounded-full animate-bounce-slow"></div>
                <div className="absolute top-2/3 left-1/4 w-3 h-3 bg-purple-400/40 rounded-full animate-bounce-delayed"></div>
                <div className="absolute bottom-1/4 left-1/3 w-5 h-5 bg-indigo-400/30 rounded-full animate-bounce-slow"></div>
            </div>

            {/* Main Card Container */}
            <div className="relative z-10 w-full max-w-5xl bg-slate-800/50 backdrop-blur-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col lg:flex-row min-h-[600px] border border-slate-700/50">
                
                {/* Left Side - Welcome Panel */}
                <div className="lg:w-1/2 p-8 lg:p-12 flex flex-col justify-center relative overflow-hidden bg-gradient-to-br from-blue-900/40 to-purple-900/40">
                    {/* Decorative Elements */}
                    <div className="absolute inset-0 overflow-hidden">
                        <div className="absolute -top-10 -right-10 w-40 h-40 bg-blue-500/15 rounded-full blur-2xl"></div>
                        <div className="absolute -bottom-10 -left-10 w-40 h-40 bg-purple-500/15 rounded-full blur-2xl"></div>
                        
                        {/* Diagonal Decorative Lines */}
                        <svg className="absolute inset-0 w-full h-full opacity-20" viewBox="0 0 400 400" preserveAspectRatio="none">
                            <defs>
                                <linearGradient id="lineGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                                    <stop offset="0%" stopColor="#60a5fa" stopOpacity="0" />
                                    <stop offset="50%" stopColor="#60a5fa" stopOpacity="0.5" />
                                    <stop offset="100%" stopColor="#60a5fa" stopOpacity="0" />
                                </linearGradient>
