                    // Recalcular el precio final
                    finalPrice = APUService.calculateFinalPrice(apuData);
                    wasCorrected = true;

                    console.warn(`   ✅ Precio corregido: $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })} por 1 ${item.unit || 'unidad'}`);
