/**
 * ProjectPersistenceService
 * Servicio centralizado para persistencia de proyectos
 * Maneja guardado, carga, eliminación y sincronización con Supabase
 */

import SupabaseService from './SupabaseService';
import { supabase } from '../lib/supabaseClient';

export class ProjectPersistenceService {
    /**
     * Guarda un proyecto completo con sincronización de cronograma
     * @param {Object} projectData - Datos completos del proyecto
     * @returns {Promise<Object>} - Proyecto guardado con ID actualizado
     */
    static async saveProject(projectData) {
        // Validar que tenga nombre
        if (!projectData.projectInfo?.project) {
            throw new Error('El proyecto debe tener un nombre');
        }
        if (import.meta.env?.DEV) {
            console.debug('[Reporte] ProjectPersistence.saveProject - id:', projectData?.id, 'projectInfo:', {
                project: projectData.projectInfo?.project,
                contractor: projectData.projectInfo?.contractor,
                concepts: projectData.projectInfo?.concepts,
                ubicacion: projectData.projectInfo?.ubicacion,
                lastReportDate: projectData.projectInfo?.lastReportDate,
            })
        }
        // Guardar proyecto principal
        const saved = await SupabaseService.saveProject(projectData);
        if (import.meta.env?.DEV) console.debug('[Reporte] ProjectPersistence.saveProject - resultado OK, id:', saved?.id)

        // Sincronizar cronograma si existe
        if (projectData.scheduleData && saved.id) {
            await this.syncSchedule(saved.id, projectData.scheduleData);
        }

        return saved;
    }

    /**
     * Sincroniza el cronograma con la tabla project_schedules
     * @param {string} projectId - ID del proyecto
     * @param {Object} scheduleData - Datos del cronograma
     */
    static async syncSchedule(projectId, scheduleData) {
        if (!projectId || !scheduleData) return;

        try {
            // Verificar si existe cronograma
            const { data: existing } = await supabase
                .from('project_schedules')
                .select('id')
                .eq('project_id', projectId)
                .maybeSingle();

            if (existing) {
                // Actualizar existente
                await supabase
                    .from('project_schedules')
                    .update({
                        tasks: scheduleData,
                        updated_at: new Date().toISOString()
                    })
                    .eq('id', existing.id);
            } else {
                // Crear nuevo
                await supabase
                    .from('project_schedules')
                    .insert([{
                        project_id: projectId,
                        tasks: scheduleData
                    }]);
            }
        } catch (error) {
            console.error('Error syncing schedule:', error);
            // No lanzar error para no interrumpir el guardado del proyecto
        }
    }

    /**
     * Carga un proyecto completo por ID
     * Valida que el proyecto pertenezca al usuario actual
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Datos completos del proyecto o null
     * @throws {Error} - Si el proyecto no existe o el usuario no tiene permisos
     */
    static async loadProject(projectId) {
        if (!projectId) {
            throw new Error('ID de proyecto requerido');
        }

        try {
            const fullData = await SupabaseService.getProject(projectId);
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] ProjectPersistence.loadProject - projectId:', projectId, 'projectInfo leído:', {
                    project: fullData.projectInfo?.project,
                    contractor: fullData.projectInfo?.contractor,
                    concepts: fullData.projectInfo?.concepts,
                    ubicacion: fullData.projectInfo?.ubicacion,
                    lastReportDate: fullData.projectInfo?.lastReportDate,
                })
            }
            if (!fullData) {
                throw new Error('Proyecto no encontrado');
            }

            // Cargar cronograma desde tabla separada si existe
            const { data: schedule } = await supabase
                .from('project_schedules')
                .select('tasks')
                .eq('project_id', projectId)
                .maybeSingle();

            // Priorizar cronograma de tabla separada, sino usar el del JSON
            if (schedule) {
                fullData.scheduleData = schedule.tasks;
            }

            return fullData;
        } catch (error) {
            console.error('Error loading project:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Lista todos los proyectos (solo metadata)
     * @returns {Promise<Array>} - Lista de proyectos
     */
    static async listProjects() {
        return await SupabaseService.listProjects();
    }

    /**
     * Elimina un proyecto
     * @param {string} projectId - ID del proyecto a eliminar
     */
    static async deleteProject(projectId) {
        if (!projectId) throw new Error('Project ID is required');

        // 1. Eliminar logs de bitácora
        try {
            await supabase
                .from('site_logs')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting logs:', error);
        }

        // 2. Eliminar cronograma asociado
        try {
            await supabase
                .from('project_schedules')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting schedule:', error);
        }

        // 3. Eliminar proyecto principal
        await SupabaseService.deleteProject(projectId);
    }


    /**
     * Renombra un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {string} newName - Nuevo nombre
     */
    static async renameProject(projectId, newName) {
        if (!projectId || !newName) {
            throw new Error('Project ID and new name are required');
        }

        await SupabaseService.updateProjectName(projectId, newName);
    }

    /**
     * Carga un proyecto desde URL params
     * Incluye carga de cronograma desde tabla separada
     * @param {string} projectId - ID del proyecto desde URL
     * @returns {Promise<Object|null>} - Datos completos del proyecto
     */
    static async loadProjectFromUrl(projectId) {
        return await this.loadProject(projectId);
    }
}

export default ProjectPersistenceService;

/**
 * ShareService
 * Servicio para manejar el compartir proyectos con clientes mediante enlaces seguros
 */

import { supabase } from '../lib/supabaseClient';

export class ShareService {
    /**
     * Crear un enlace compartido para un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {Object} options - Opciones de compartir
     * @returns {Promise<Object>} - Información del enlace compartido
     */
    static async createShare(projectId, options = {}) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            if (!projectId) {
                throw new Error('ID del proyecto es requerido');
            }

            // Verificar que el proyecto existe y pertenece al usuario
            const { data: project, error: projectError } = await supabase
                .from('projects')
                .select('id, user_id')
                .eq('id', projectId)
                .single();

            if (projectError || !project) {
                throw new Error('Proyecto no encontrado');
            }

            if (project.user_id !== user.id) {
                throw new Error('No tienes permisos para compartir este proyecto');
            }

            // Generar token único
            const shareToken = this.generateToken();

            // Generar código corto opcional (verificar unicidad)
            let shareCode = null;
            if (options.includeShortCode) {
                let attempts = 0;
                let codeExists = true;
                while (codeExists && attempts < 10) {
                    shareCode = this.generateShortCode();
                    // Verificar si ya existe - usar consulta sin single() para evitar error si no existe
                    const { data: existing, error: checkError } = await supabase
                        .from('project_shares')
                        .select('id')
                        .eq('share_code', shareCode)
                        .limit(1);
                    
                    // Si hay datos, el código existe
                    codeExists = existing && existing.length > 0;
                    attempts++;
                }
                if (codeExists) {
                    // Si después de 10 intentos no encontramos uno único, no usar código corto
                    shareCode = null;
                }
            }

            // Preparar metadata
            const metadata = options.metadata || {};
            
            const shareData = {
                project_id: projectId,
                share_token: shareToken,
                share_code: shareCode,
                can_edit: options.canEdit || false,
                expires_at: options.expiresAt || null,
                password: options.password || null,
                allowed_emails: options.allowedEmails || null,
                metadata: metadata,
                created_by: user.id
            };

            const { data, error } = await supabase
                .from('project_shares')
                .insert(shareData)
                .select()
                .single();

            if (error) {
                console.error('Error al crear share:', error);
                
                // Si el error es por token duplicado (poco probable pero posible), reintentar
                if (error.code === '23505') {
                    // Reintentar con nuevo token/código
                    shareData.share_token = this.generateToken();
                    if (shareData.share_code) {
                        shareData.share_code = this.generateShortCode();
                    }
                    
                    const { data: retryData, error: retryError } = await supabase
                        .from('project_shares')
                        .insert(shareData)
                        .select()
                        .single();
                    
                    if (retryError) {
                        console.error('Error en reintento:', retryError);
                        throw new Error('Error al crear el enlace compartido. Por favor intenta de nuevo.');
                    }
                    
                    return {
                        ...retryData,
                        shareUrl: `${window.location.origin}/share/${retryData.share_token}`,
                        shortUrl: retryData.share_code ? `${window.location.origin}/s/${retryData.share_code}` : null
                    };
                }
                
                // Otros errores
                if (error.message) {
                    throw new Error(`Error al crear el enlace: ${error.message}`);
                }
                throw new Error('Error desconocido al crear el enlace compartido');
            }

            // Generar URL completa
            const baseUrl = window.location.origin;
            const shareUrl = `${baseUrl}/share/${shareToken}`;

            return {
                ...data,
                shareUrl: shareUrl,
                shortUrl: shareCode ? `${baseUrl}/s/${shareCode}` : null
            };
        } catch (error) {
            console.error('Error creating share:', error);
            throw error;
        }
    }

    /**
     * Obtener información de un enlace compartido por token
     * @param {string} token - Token del enlace compartido
     * @returns {Promise<Object>} - Información del share y proyecto
     */
    static async getShareByToken(token) {
        try {
            if (!token) {
                throw new Error('Token no proporcionado');
            }

            // Buscar por token o código corto - hacer dos consultas separadas para evitar problemas con .or()
            let data = null;

            // Primero intentar buscar por token
            const { data: tokenData, error: tokenError } = await supabase
                .from('project_shares')
                .select(`
                    *,
                    projects (
                        id,
                        name,
                        client,
                        type,
                        created_at,
                        updated_at,
                        data
                    )
                `)
                .eq('share_token', token)
                .single();

            // Si se encuentra por token, usarlo
            if (tokenData && !tokenError) {
                data = tokenData;
            } else {
                // Si no se encuentra por token, buscar por código corto
                const { data: codeData, error: codeError } = await supabase
                    .from('project_shares')
                    .select(`
                        *,
                        projects (
                            id,
                            name,
                            client,
                            type,
                            created_at,
                            updated_at,
                            data
                        )
                    `)
                    .eq('share_code', token)
                    .single();

                if (codeError && codeError.code !== 'PGRST116') { // PGRST116 = no rows found
                    throw codeError;
                }
                if (codeData) {
                    data = codeData;
                }
            }

            if (!data) {
                throw new Error('Enlace no encontrado o inválido');
            }

            // Verificar si ha expirado
            if (data.expires_at && new Date(data.expires_at) < new Date()) {
                throw new Error('Este enlace ha expirado');
            }

            // Incrementar contador de accesos
            await this.recordAccess(data.id);

            return data;
        } catch (error) {
            console.error('Error getting share:', error);
            throw error;
        }
    }

    /**
     * Verificar contraseña del enlace compartido
     * @param {string} token - Token del enlace
     * @param {string} password - Contraseña ingresada
     * @returns {Promise<boolean>} - True si la contraseña es correcta
     */
    static async verifyPassword(token, password) {
        try {
            if (!token) return false;

            // Buscar por token primero
            let data = null;
            const { data: tokenData, error: tokenError } = await supabase
                .from('project_shares')
                .select('password')
                .eq('share_token', token)
                .single();

            if (tokenData) {
                data = tokenData;
            } else {
                // Si no se encuentra por token, buscar por código corto
                const { data: codeData, error: codeError } = await supabase
                    .from('project_shares')
                    .select('password')
                    .eq('share_code', token)
                    .single();

                if (codeError && codeError.code !== 'PGRST116') {
                    return false;
                }
                data = codeData;
            }

            if (!data || !data.password) return false;

            // Comparación simple (en producción debería usar hash)
            return data.password === password;
        } catch (error) {
            console.error('Error verifying password:', error);
            return false;
        }
    }

    /**
     * Registrar acceso al enlace compartido
     * @param {string} shareId - ID del share
     */
    static async recordAccess(shareId, metadata = {}) {
        try {
            // Obtener IP y user agent
            const accessData = {
                share_id: shareId,
                ip_address: metadata.ipAddress || null,
                user_agent: metadata.userAgent || navigator.userAgent,
                metadata: metadata.extra || {}
            };

            await supabase
                .from('project_share_access')
                .insert(accessData);

            // Actualizar contador en project_shares
            // Primero obtener el valor actual
            const { data: currentShare } = await supabase
                .from('project_shares')
                .select('access_count')
                .eq('id', shareId)
                .single();

            const newCount = (currentShare?.access_count || 0) + 1;

            await supabase
                .from('project_shares')
                .update({
                    access_count: newCount,
                    last_accessed_at: new Date().toISOString()
                })
                .eq('id', shareId);
        } catch (error) {
            console.error('Error recording access:', error);
            // No lanzar error, solo registrar
        }
    }

    /**
     * Obtener todos los enlaces compartidos de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Lista de enlaces compartidos
     */
    static async getProjectShares(projectId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { data, error } = await supabase
                .from('project_shares')
                .select('*')
                .eq('project_id', projectId)
                .order('created_at', { ascending: false });

            if (error) throw error;

            // Generar URLs completas
            const baseUrl = window.location.origin;
            return data.map(share => ({
                ...share,
                shareUrl: `${baseUrl}/share/${share.share_token}`,
                shortUrl: share.share_code ? `${baseUrl}/s/${share.share_code}` : null
            }));
        } catch (error) {
            console.error('Error getting project shares:', error);
            throw error;
        }
    }

    /**
     * Obtener estadísticas de un enlace compartido
     * @param {string} shareId - ID del share
     * @returns {Promise<Object>} - Estadísticas de acceso
     */
    static async getShareStats(shareId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            // Obtener información del share
            const { data: share, error: shareError } = await supabase
                .from('project_shares')
                .select('*')
                .eq('id', shareId)
                .single();

            if (shareError) throw shareError;

            // Obtener accesos recientes
            const { data: accesses, error: accessError } = await supabase
                .from('project_share_access')
                .select('*')
                .eq('share_id', shareId)
                .order('accessed_at', { ascending: false })
                .limit(50);

            if (accessError) throw accessError;

            // Calcular estadísticas
            const stats = {
                totalAccesses: share.access_count || 0,
                recentAccesses: accesses || [],
                lastAccessed: share.last_accessed_at,
                createdAt: share.created_at,
                expiresAt: share.expires_at,
                isExpired: share.expires_at ? new Date(share.expires_at) < new Date() : false
            };

            return stats;
        } catch (error) {
            console.error('Error getting share stats:', error);
            throw error;
        }
    }

    /**
     * Eliminar un enlace compartido
     * @param {string} shareId - ID del share
     */
    static async deleteShare(shareId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { error } = await supabase
                .from('project_shares')
                .delete()
                .eq('id', shareId);

            if (error) throw error;

            return true;
        } catch (error) {
            console.error('Error deleting share:', error);
            throw error;
        }
    }

    /**
     * Actualizar configuración de un enlace compartido
     * @param {string} shareId - ID del share
     * @param {Object} updates - Campos a actualizar
     */
    static async updateShare(shareId, updates) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { data, error } = await supabase
                .from('project_shares')
                .update(updates)
                .eq('id', shareId)
                .select()
                .single();

            if (error) throw error;

            return data;
        } catch (error) {
            console.error('Error updating share:', error);
            throw error;
        }
    }

    /**
     * Generar token único
     */
    static generateToken() {
        const array = new Uint8Array(32);
        crypto.getRandomValues(array);
        return btoa(String.fromCharCode.apply(null, array))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');
    }

    /**
     * Generar código corto único (6 caracteres)
     */
    static generateShortCode() {
        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // Sin caracteres confusos
        let code = '';
        for (let i = 0; i < 6; i++) {
            code += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return code;
    }
}

/**
 * StorageService
 * Handles local persistence of projects using LocalStorage
 */

import { generateId } from '../utils/helpers';

const STORAGE_KEY = 'presupuesto_ia_projects';

export class StorageService {
    /**
     * Save a project to local storage
     * @param {Object} projectData - Full project data
     * @returns {Object} - Saved project metadata
     */
    static saveProject(projectData) {
        try {
            const projects = this.getAllProjects();
            const now = new Date().toISOString();

            const projectToSave = {
                ...projectData,
                id: projectData.id || generateId(),
                lastModified: now,
                createdAt: projectData.createdAt || now
            };

            // Check if exists to update, or add new
            const index = projects.findIndex(p => p.id === projectToSave.id);
            if (index >= 0) {
                projects[index] = projectToSave;
            } else {
                projects.push(projectToSave);
            }

            localStorage.setItem(STORAGE_KEY, JSON.stringify(projects));
            return projectToSave;
        } catch (error) {
            console.error('Error saving project:', error);
            throw new Error('No se pudo guardar el proyecto. Es posible que el almacenamiento esté lleno.');
        }
    }

    /**
     * Get all projects (metadata only ideally, but localstorage loads all)
     * @returns {Array} - List of projects sorted by date
     */
    static getAllProjects() {
        try {
            const data = localStorage.getItem(STORAGE_KEY);
            if (!data) return [];
            const projects = JSON.parse(data);
            return projects.sort((a, b) => new Date(b.lastModified) - new Date(a.lastModified));
        } catch (error) {
            console.error('Error loading projects:', error);
            return [];
        }
    }

    /**
     * Get a specific project by ID
     * @param {string} id 
     * @returns {Object|null}
     */
    static getProject(id) {
        const projects = this.getAllProjects();
        return projects.find(p => p.id === id) || null;
    }

    /**
     * Delete a project by ID
     * @param {string} id 
     */
    static deleteProject(id) {
        const projects = this.getAllProjects();
        const filtered = projects.filter(p => p.id !== id);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
    }
}

