const App = () => {
    return (
        <ErrorBoundary>
            <ThemeProvider>
                <ErrorProvider>
                    <AuthProvider>
                        <SubscriptionProvider>
                            <PricingModalProvider>
                                <SidebarProvider>
                                    <ProjectProvider>
                                        <Router>
                                            <InactivityHandler />
                                            <KeepAlive />
                                            <Routes>
                                                {/* Landing Page - Public */}
                                                <Route path="/" element={<LandingPage />} />

