                                                    </ProtectedRoute>
                                                } />

                                                {/* Price Search Route */}
                                                <Route path="/pricesearch" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Búsqueda de Precios"><PriceSearchPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* PDF Editor Route */}
                                                <Route path="/pdf-editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar PDF"><PDFEditorPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Admin Route */}
