                                                <Route path="*" element={<NotFound />} />
                                            </Routes>
                                        </Router>
                                    </ProjectProvider>
                                </SidebarProvider>
                            </PricingModalProvider>
                        </SubscriptionProvider>
                    </AuthProvider>
                </ErrorProvider>
            </ThemeProvider>
        </ErrorBoundary>
    );
};

