import React from 'react';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';
import { captureException } from '../lib/sentry';

/**
 * Error Boundary para capturar errores de React
 * Envía errores a Sentry automáticamente
 */
class ErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { 
            hasError: false, 
            error: null,
            errorInfo: null 
        };
    }

    static getDerivedStateFromError(error) {
        // Actualizar state para mostrar UI de error
        return { hasError: true };
    }

    componentDidCatch(error, errorInfo) {
        // Guardar información del error
        this.setState({
            error,
            errorInfo
        });

        // Enviar a Sentry
        captureException(error, {
            componentStack: errorInfo.componentStack,
            source: 'React Error Boundary',
            errorBoundary: true,
        }, 'error');

        // Log en consola para desarrollo
        console.error('Error capturado por ErrorBoundary:', error, errorInfo);
    }

    handleReset = () => {
        this.setState({ 
            hasError: false, 
            error: null, 
            errorInfo: null 
        });
        // Recargar la página para asegurar estado limpio
        window.location.reload();
    };

    handleGoHome = () => {
        window.location.href = '/';
    };

    render() {
        if (this.state.hasError) {
            // UI de error personalizada
            return (
                <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center p-4">
                    <div className="max-w-md w-full bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 p-8 text-center">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-red-100 dark:bg-red-900/20 mb-4">
                            <AlertTriangle className="h-8 w-8 text-red-600 dark:text-red-400" />
                        </div>
                        
                        <h1 className="text-2xl font-bold text-slate-900 dark:text-slate-100 mb-2">
                            Algo salió mal
                        </h1>
                        
                        <p className="text-slate-600 dark:text-slate-400 mb-6">
                            Ocurrió un error inesperado. Hemos sido notificados y estamos trabajando en solucionarlo.
                        </p>

                        {process.env.NODE_ENV === 'development' && this.state.error && (
                            <details className="mb-6 text-left">
                                <summary className="cursor-pointer text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Detalles del error (solo desarrollo)
                                </summary>
                                <div className="bg-slate-50 dark:bg-slate-900 rounded-lg p-4 text-xs font-mono text-slate-800 dark:text-slate-200 overflow-auto max-h-48">
                                    <div className="mb-2">
                                        <strong>Error:</strong> {this.state.error.toString()}
                                    </div>
                                    {this.state.errorInfo && (
                                        <div>
                                            <strong>Stack:</strong>
                                            <pre className="whitespace-pre-wrap mt-1">
                                                {this.state.errorInfo.componentStack}
                                            </pre>
                                        </div>
                                    )}
                                </div>
                            </details>
                        )}

                        <div className="flex gap-3 justify-center">
                            <button
                                onClick={this.handleReset}
                                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition"
                            >
                                <RefreshCw size={18} />
                                Recargar
                            </button>
                            
                            <button
                                onClick={this.handleGoHome}
                                className="flex items-center gap-2 px-4 py-2 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-300 rounded-lg font-medium transition"
                            >
                                <Home size={18} />
                                Ir al Inicio
                            </button>
                        </div>

                        <p className="text-xs text-slate-500 dark:text-slate-400 mt-6">
                            Si el problema persiste, por favor contacta a soporte.
                        </p>
                    </div>
                </div>
            );
        }

        return this.props.children;
    }
}

export default ErrorBoundary;

import { useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';

/**
 * KeepAlive Component
 * 
 * Este componente envía un "pulso" a Supabase y al Servidor Proxy (Render) 
 * para evitar que entren en modo de pausa por inactividad.
 */
export default function KeepAlive() {
    useEffect(() => {
        // Render Free suspende la app tras 15 MINUTOS de inactividad.
        // Usamos 10 minutos para estar seguros mientras el usuario tenga la pestaña abierta.
        const RENDER_INTERVAL = 10 * 60 * 1000;

        // Supabase Free pausa el proyecto tras 7 DÍAS de inactividad.
        // Un pulso cada 24 horas es más que suficiente para esto.
        const SUPABASE_INTERVAL = 24 * 60 * 60 * 1000;

        const sendRenderPulse = async () => {
            // Solo enviar pulso si hay API configurada (producción o backend en 4001); evita ERR_CONNECTION_REFUSED en dev sin servidor
            const apiBaseUrl = import.meta.env.VITE_API_URL;
            if (!apiBaseUrl) return;
            try {
                await fetch(`${apiBaseUrl}/api/ai/health`, { mode: 'no-cors' }).catch(() => {
                    fetch(`${apiBaseUrl}/`, { mode: 'no-cors' }).catch(() => {});
                });
            } catch {
                // Silenciar: servidor no disponible
            }
        };

        const sendSupabasePulse = async () => {
            try {
                await supabase.from('projects').select('id').limit(1);
            } catch {
                // Silenciar: conexión o permisos
            }
        };

        // Ejecutar inmediatamente
        sendRenderPulse();
        sendSupabasePulse();

        // Configurar intervalos
        const renderTimer = setInterval(sendRenderPulse, RENDER_INTERVAL);
        const supabaseTimer = setInterval(sendSupabasePulse, SUPABASE_INTERVAL);

        return () => {
            clearInterval(renderTimer);
            clearInterval(supabaseTimer);
        };
    }, []);

    return null;
}

