import React, { useEffect } from 'react';
import { Navigate, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Loader } from 'lucide-react';

const ProtectedRoute = ({ children, requireAuth = false }) => {
    const { user, loading } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();

    // Monitorear continuamente el estado de autenticación
    useEffect(() => {
        if (!loading) {
            // Si requiere autenticación y no hay usuario, forzar redirección
            if (requireAuth && !user) {
                navigate('/login', { replace: true });
            }
            // Si está en login/registro y ya hay usuario, forzar redirección al dashboard
            if (!requireAuth && user && (location.pathname === '/login' || location.pathname === '/register')) {
                navigate('/dashboard', { replace: true });
            }
        }
    }, [user, loading, requireAuth, navigate, location.pathname]);

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="text-center">
                    <Loader size={48} className="animate-spin text-blue-600 mx-auto mb-4" />
                    <p className="text-slate-600">Cargando...</p>
                </div>
            </div>
        );
    }

    // Si requiere autenticación y no hay usuario, redirigir a login
    if (requireAuth && !user) {
        return <Navigate to="/login" replace />;
    }

    // Si está en login y ya hay usuario, redirigir al dashboard
    if (!requireAuth && user) {
        return <Navigate to="/dashboard" replace />;
    }

    return children;
};

export default ProtectedRoute;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Calendar, ChevronLeft, ChevronRight, ZoomIn, ZoomOut, Maximize2, Minimize2, Save, Move, Link as LinkIcon, X, Info, AlertTriangle, Wrench, Package } from 'lucide-react';

// Helper para obtener días laborables entre dos fechas
const getWorkingDays = (start, end, workDays) => {
    let count = 0;
    const current = new Date(start);
    while (current <= end) {
        const dayName = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][current.getDay()];
        if (workDays[dayName]) count++;
        current.setDate(current.getDate() + 1);
    }
    return count;
};

/**
 * GanttChart Component
 * Visualización interactiva tipo Gantt del cronograma con drag & drop y dependencias
 */
const GanttChart = ({ 
    scheduleData, 
    onUpdate, 
    startDate = null,
    workDays = { mon: true, tue: true, wed: true, thu: true, fri: true, sat: true, sun: false }
}) => {
    const { phases = [], totalDurationWeeks = 0 } = scheduleData || {};
    const [viewMode, setViewMode] = useState('weeks'); // 'days', 'weeks', 'months'
    const [zoomLevel, setZoomLevel] = useState(1);
    const [scrollPosition, setScrollPosition] = useState(0);
    const [isFullscreen, setIsFullscreen] = useState(false);
    const [draggingTask, setDraggingTask] = useState(null);
    const [dragStartPos, setDragStartPos] = useState(null);
    const [selectedTask, setSelectedTask] = useState(null);
    const [showTaskDetails, setShowTaskDetails] = useState(false);
    const ganttContainerRef = useRef(null);
    const [startDateState, setStartDateState] = useState(startDate || new Date());

    // Convertir phases a tasks para el Gantt
    const tasks = useMemo(() => {
        if (!phases || phases.length === 0) return [];
        
        let currentDate = new Date(startDateState);
        const weekMs = 7 * 24 * 60 * 60 * 1000;
        
        return phases.map((phase, index) => {
            let start, end, duration;
            
            if (phase.startDate && phase.endDate) {
                start = new Date(phase.startDate);
                end = new Date(phase.endDate);
                duration = Math.ceil((end - start) / weekMs);
            } else if (phase.startWeek && phase.durationWeeks) {
                // Calcular fechas basadas en semanas desde startDateState
                const weeksOffset = (phase.startWeek - 1) * 7;
                start = new Date(currentDate.getTime() + weeksOffset * 24 * 60 * 60 * 1000);
                duration = phase.durationWeeks;
                end = new Date(start.getTime() + duration * weekMs);
            } else {
                // Fallback: usar duración estimada
                duration = phase.durationWeeks || 2;
                start = new Date(currentDate);
                end = new Date(start.getTime() + duration * weekMs);
                currentDate = new Date(end);
            }

            return {
                id: `phase-${index}`,
                name: phase.name,
                start: start,
                end: end,
                duration: duration,
                progress: 0, // Se puede calcular desde bitácora
                isCritical: phase.isCritical || false,
                dependencies: [], // Se puede calcular desde lógica de fases
                resources: phase.resources || [],
                risks: phase.risks || [],
                notes: phase.notes || '',
                originalPhase: phase
            };
        });
    }, [phases, startDateState]);

    // Calcular dependencias automáticamente (una fase depende de la anterior)
    const tasksWithDependencies = useMemo(() => {
        return tasks.map((task, index) => ({
            ...task,
            dependencies: index > 0 ? [`phase-${index - 1}`] : []
        }));
    }, [tasks]);

    // Calcular dimensiones del Gantt
    const { timelineStart, timelineEnd, totalDays } = useMemo(() => {
        if (tasksWithDependencies.length === 0) {
            return { timelineStart: new Date(), timelineEnd: new Date(), totalDays: 1 };
        }

        const allDates = tasksWithDependencies.flatMap(t => [t.start, t.end]);
        const minDate = new Date(Math.min(...allDates.map(d => d.getTime())));
        const maxDate = new Date(Math.max(...allDates.map(d => d.getTime())));
        
        // Ajustar a lunes si es necesario
        const startOfWeek = new Date(minDate);
        startOfWeek.setDate(minDate.getDate() - minDate.getDay() + 1);
        
        const endOfWeek = new Date(maxDate);
        endOfWeek.setDate(maxDate.getDate() + (7 - maxDate.getDay()));
        
        const days = Math.ceil((endOfWeek - startOfWeek) / (24 * 60 * 60 * 1000));
        
        return {
            timelineStart: startOfWeek,
            timelineEnd: endOfWeek,
            totalDays: days
        };
    }, [tasksWithDependencies]);


    // Convertir fecha a posición X en el timeline según el modo
    const dateToX = (date) => {
        if (viewMode === 'days') {
            const daysSinceStart = Math.ceil((date - timelineStart) / (24 * 60 * 60 * 1000));
            const dayWidth = containerWidth / totalDays;
            return Math.max(0, daysSinceStart * dayWidth);
        } else if (viewMode === 'weeks') {
            const weeksSinceStart = Math.ceil((date - timelineStart) / (7 * 24 * 60 * 60 * 1000));
            const weekWidth = containerWidth / Math.ceil(totalDays / 7);
            return Math.max(0, (weeksSinceStart - 1) * weekWidth);
        } else {
            // Meses
            const monthsSinceStart = (date.getFullYear() - timelineStart.getFullYear()) * 12 + 
                                   (date.getMonth() - timelineStart.getMonth());
            const monthWidth = containerWidth / Math.ceil(totalDays / 30);
            return Math.max(0, monthsSinceStart * monthWidth);
        }
    };

    // Convertir posición X a fecha
    const xToDate = (x) => {
        const dayWidth = containerWidth / totalDays;
        const days = x / dayWidth;
        const date = new Date(timelineStart);
        date.setDate(date.getDate() + Math.round(days));
        return date;
    };

    // Manejar drag start
    const handleTaskMouseDown = (task, e) => {
        e.preventDefault();
        setDraggingTask(task);
        setDragStartPos({ x: e.clientX, initialStart: task.start, initialEnd: task.end });
    };

    // Manejar drag durante movimiento
    useEffect(() => {
        if (!draggingTask || !dragStartPos) return;

        const handleMouseMove = (e) => {
            // Preview visual durante el arrastre (opcional)
        };

        const handleMouseUp = (e) => {
            if (!ganttContainerRef.current || !draggingTask) return;
            
            const container = ganttContainerRef.current.querySelector('.gantt-timeline');
            if (!container) {
                setDraggingTask(null);
                setDragStartPos(null);
                return;
            }
            
            const rect = container.getBoundingClientRect();
            const deltaX = e.clientX - dragStartPos.x;
            const dayWidth = containerWidth / totalDays;
            const daysDelta = Math.round(deltaX / dayWidth);
            
            if (daysDelta !== 0 && onUpdate) {
                const newStart = new Date(dragStartPos.initialStart);
                newStart.setDate(newStart.getDate() + daysDelta);
                const duration = Math.ceil((dragStartPos.initialEnd - dragStartPos.initialStart) / (24 * 60 * 60 * 1000));
                const newEnd = new Date(newStart);
                newEnd.setDate(newEnd.getDate() + duration);
                
                // Actualizar la tarea
                const updatedTasks = tasksWithDependencies.map(t => 
                    t.id === draggingTask.id 
                        ? { ...t, start: newStart, end: newEnd }
                        : t
                );
                
                // Convertir de vuelta a formato de phases
                const updatedPhases = updatedTasks.map(t => ({
                    ...t.originalPhase,
                    startDate: t.start.toISOString().split('T')[0],
                    endDate: t.end.toISOString().split('T')[0]
                }));
                
                onUpdate({
                    ...scheduleData,
                    phases: updatedPhases
                });
            }
            
            setDraggingTask(null);
            setDragStartPos(null);
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [draggingTask, dragStartPos, totalDays, zoomLevel, tasksWithDependencies, scheduleData, onUpdate]);

    // Generar grid de días/semanas/meses según el modo
    const timeGrid = useMemo(() => {
        const grid = [];
        const current = new Date(timelineStart);
        
        while (current <= timelineEnd) {
            grid.push(new Date(current));
            
            // Avanzar según el modo seleccionado
            if (viewMode === 'days') {
                current.setDate(current.getDate() + 1);
            } else if (viewMode === 'weeks') {
                // Avanzar al siguiente lunes (inicio de semana)
                current.setDate(current.getDate() + 7);
            } else if (viewMode === 'months') {
                current.setMonth(current.getMonth() + 1);
            }
        }
        
        return grid;
    }, [timelineStart, timelineEnd, viewMode]);

    if (!scheduleData || phases.length === 0) {
        return (
            <div className="p-12 text-center bg-slate-50 rounded-lg border-2 border-dashed border-slate-300">
                <Calendar className="mx-auto mb-4 text-slate-400" size={48} />
                <p className="text-slate-500 font-medium">No hay cronograma disponible</p>
            </div>
        );
    }

    const rowHeight = 35;
    const headerHeight = 40;
    const [containerWidth, setContainerWidth] = useState(1200);

    // Calcular ancho del contenedor dinámicamente
    useEffect(() => {
        const updateWidth = () => {
            if (ganttContainerRef.current) {
                const container = ganttContainerRef.current;
                const availableWidth = container.offsetWidth || container.clientWidth;
                const width = Math.max(availableWidth - 180, 800); // Restar ancho de columna de nombres, mínimo 800px
                setContainerWidth(width * zoomLevel);
            }
        };
        
        // Ejecutar inmediatamente
        updateWidth();
        
        // También después de un pequeño delay para asegurar que el DOM esté listo
        const timeoutId = setTimeout(updateWidth, 100);
        
        window.addEventListener('resize', updateWidth);
        return () => {
            clearTimeout(timeoutId);
            window.removeEventListener('resize', updateWidth);
        };
    }, [zoomLevel]);

    return (
        <div 
            ref={ganttContainerRef}
            className={`h-full w-full flex flex-col bg-white ${isFullscreen ? 'fixed inset-4 z-50 rounded-2xl shadow-2xl' : ''}`}
        >
            {/* Toolbar */}
            <div className="p-1.5 bg-slate-50 border-b border-slate-200 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-1.5">
                    <button
                        onClick={() => setViewMode('days')}
                        className={`px-1.5 py-0.5 rounded text-[10px] font-medium transition ${
                            viewMode === 'days' 
                                ? 'bg-blue-600 text-white' 
                                : 'bg-white text-slate-700 hover:bg-slate-100'
                        }`}
                    >
                        Días
                    </button>
                    <button
                        onClick={() => setViewMode('weeks')}
                        className={`px-1.5 py-0.5 rounded text-[10px] font-medium transition ${
                            viewMode === 'weeks' 
                                ? 'bg-blue-600 text-white' 
                                : 'bg-white text-slate-700 hover:bg-slate-100'
                        }`}
                    >
                        Semanas
                    </button>
                    <button
                        onClick={() => setViewMode('months')}
                        className={`px-1.5 py-0.5 rounded text-[10px] font-medium transition ${
                            viewMode === 'months' 
                                ? 'bg-blue-600 text-white' 
                                : 'bg-white text-slate-700 hover:bg-slate-100'
                        }`}
                    >
                        Meses
                    </button>
                </div>
                
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => setZoomLevel(Math.max(0.5, zoomLevel - 0.25))}
                        className="p-1 hover:bg-slate-200 rounded transition"
                        title="Alejar"
                    >
                        <ZoomOut size={14} />
                    </button>
                    <span className="text-[10px] text-slate-600 font-medium min-w-[35px] text-center">{Math.round(zoomLevel * 100)}%</span>
                    <button
                        onClick={() => setZoomLevel(Math.min(2, zoomLevel + 0.25))}
                        className="p-1 hover:bg-slate-200 rounded transition"
                        title="Acercar"
                    >
                        <ZoomIn size={14} />
                    </button>
                </div>
            </div>

            {/* Gantt Chart */}
            <div className="flex-1 overflow-auto bg-white">
                <div className="gantt-timeline relative" style={{ width: `${containerWidth + 180}px`, minHeight: `${headerHeight + (tasksWithDependencies.length * rowHeight)}px` }}>
                    {/* Header con fechas */}
                    <div 
                        className="sticky top-0 z-10 bg-white border-b-2 border-slate-300"
                        style={{ height: `${headerHeight}px` }}
                    >
                        <div className="flex" style={{ width: `${containerWidth}px` }}>
                            {/* Columna de nombres de tareas */}
                            <div className="sticky left-0 z-20 bg-white border-r-2 border-slate-300" style={{ width: '180px', height: `${headerHeight}px` }}>
                                <div className="p-1.5 h-full flex items-center">
                                    <span className="font-bold text-slate-700 text-[10px]">Fases del Proyecto</span>
                                </div>
                            </div>
                            
                            {/* Timeline de fechas */}
                            <div className="flex-1 relative">
                                {timeGrid.map((date, index) => {
                                    let xPos, cellWidth, label;
                                    
                                    if (viewMode === 'days') {
                                        const daysSinceStart = Math.ceil((date - timelineStart) / (24 * 60 * 60 * 1000));
                                        const dayWidth = containerWidth / totalDays;
                                        xPos = daysSinceStart * dayWidth;
                                        cellWidth = dayWidth;
                                        label = date.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' });
                                    } else if (viewMode === 'weeks') {
                                        const weeksSinceStart = Math.ceil((date - timelineStart) / (7 * 24 * 60 * 60 * 1000));
                                        const weekWidth = containerWidth / Math.ceil(totalDays / 7);
                                        xPos = (weeksSinceStart - 1) * weekWidth;
                                        cellWidth = weekWidth;
                                        label = `Sem ${weeksSinceStart}`;
                                    } else {
                                        // Meses
                                        const monthsSinceStart = (date.getFullYear() - timelineStart.getFullYear()) * 12 + 
                                                               (date.getMonth() - timelineStart.getMonth());
                                        const monthWidth = containerWidth / Math.ceil(totalDays / 30);
                                        xPos = monthsSinceStart * monthWidth;
                                        cellWidth = monthWidth;
                                        label = date.toLocaleDateString('es-MX', { month: 'short', year: '2-digit' });
                                    }
                                    
                                    return (
                                        <div
                                            key={index}
                                            className="absolute top-0 border-r border-slate-200"
                                            style={{
                                                left: `${xPos + 180}px`,
                                                width: `${cellWidth}px`,
                                                height: `${headerHeight}px`
                                            }}
                                        >
                                            <div className="p-0.5 text-[9px] font-medium text-slate-600 text-center">
                                                {label}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    {/* Filas de tareas */}
                    <div className="relative">
                        {tasksWithDependencies.map((task, index) => {
                            const taskX = dateToX(task.start);
                            const taskWidth = dateToX(task.end) - taskX;
                            const taskY = index * rowHeight;
                            const isDragging = draggingTask?.id === task.id;

                            return (
                                <div key={task.id} className="relative" style={{ height: `${rowHeight}px` }}>
                                    {/* Fondo de la fila */}
                                    <div className="absolute inset-0 bg-slate-50 border-b border-slate-100" />
                                    
                                    {/* Nombre de la tarea (sticky) */}
                                    <div 
                                        className="sticky left-0 z-10 bg-white border-r-2 border-slate-300 px-1.5 py-0.5 h-full flex items-center"
                                        style={{ width: '180px' }}
                                    >
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-1">
                                                <span className="font-medium text-slate-800 text-[10px] truncate leading-tight">{task.name}</span>
                                                {task.isCritical && (
                                                    <span className="px-0.5 py-0 bg-red-100 text-red-700 rounded text-[8px] font-bold shrink-0">
                                                        C
                                                    </span>
                                                )}
                                            </div>
                                            <div className="text-[9px] text-slate-500 mt-0 truncate leading-tight">
                                                {task.start.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })} - {task.end.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })}
                                            </div>
                                        </div>
                                        <Move size={10} className="text-slate-400 shrink-0 ml-0.5" />
                                    </div>

                                    {/* Barra de la tarea */}
                                    <div
                                        className={`absolute cursor-pointer transition-all group ${
                                            task.isCritical 
                                                ? 'bg-red-500 hover:bg-red-600' 
                                                : 'bg-blue-500 hover:bg-blue-600'
                                        } ${isDragging ? 'opacity-70 shadow-lg' : 'shadow-sm'} rounded px-1 flex items-center`}
                                        style={{
                                            left: `${taskX + 180}px`,
                                            top: '4px',
                                            width: `${Math.max(taskWidth, 50)}px`,
                                            height: `${rowHeight - 8}px`,
                                            zIndex: isDragging ? 50 : 5
                                        }}
                                        onMouseDown={(e) => {
                                            // Si es click simple, mostrar detalles; si es drag, mover
                                            if (e.button === 0) {
                                                const startX = e.clientX;
                                                const startY = e.clientY;
                                                const handleMouseMove = (moveEvent) => {
                                                    const deltaX = Math.abs(moveEvent.clientX - startX);
                                                    const deltaY = Math.abs(moveEvent.clientY - startY);
                                                    if (deltaX > 5 || deltaY > 5) {
                                                        // Es un drag, usar función de drag
                                                        handleTaskMouseDown(task, e);
                                                        document.removeEventListener('mousemove', handleMouseMove);
                                                    }
                                                };
                                                const handleMouseUp = () => {
                                                    document.removeEventListener('mousemove', handleMouseMove);
                                                    document.removeEventListener('mouseup', handleMouseUp);
                                                    // Si no hubo movimiento significativo, mostrar detalles
                                                    setSelectedTask(task);
                                                    setShowTaskDetails(true);
                                                };
                                                document.addEventListener('mousemove', handleMouseMove);
                                                document.addEventListener('mouseup', handleMouseUp);
                                            } else {
                                                handleTaskMouseDown(task, e);
                                            }
                                        }}
                                        title={`${task.name} - Click para ver detalles, arrastra para mover`}
                                    >
                                        <span className="text-white text-[9px] font-medium truncate leading-tight">
                                            {task.name}
                                        </span>
                                        {/* Indicador de que tiene detalles */}
                                        {(task.resources?.length > 0 || task.risks?.length > 0 || task.notes || task.originalPhase?.items?.length > 0) && (
                                            <Info size={8} className="text-white opacity-70 group-hover:opacity-100 ml-1" />
                                        )}
                                    </div>

                                    {/* Dependencias (líneas) */}
                                    {task.dependencies && task.dependencies.length > 0 && (
                                        <svg 
                                            className="absolute pointer-events-none"
                                            style={{ width: `${containerWidth}px`, height: `${rowHeight}px`, top: 0, left: 0, zIndex: 1 }}
                                        >
                                            {task.dependencies.map((depId, depIndex) => {
                                                const depTask = tasksWithDependencies.find(t => t.id === depId);
                                                if (!depTask) return null;
                                                
                                                const depX = dateToX(depTask.end) + 180;
                                                const depY = tasksWithDependencies.findIndex(t => t.id === depId) * rowHeight + (rowHeight / 2);
                                                const taskXCenter = taskX + 180;
                                                const taskYCenter = taskY + (rowHeight / 2);
                                                
                                                return (
                                                    <g key={depIndex}>
                                                        <path
                                                            d={`M ${depX} ${depY} L ${depX + 20} ${depY} L ${depX + 20} ${taskYCenter} L ${taskXCenter} ${taskYCenter}`}
                                                            stroke="#64748b"
                                                            strokeWidth="2"
                                                            fill="none"
                                                            strokeDasharray="5,5"
                                                            markerEnd="url(#arrowhead)"
                                                        />
                                                    </g>
                                                );
                                            })}
                                        </svg>
                                    )}
                                </div>
                            );
                        })}
                    </div>

                    {/* SVG markers para flechas */}
                    <svg style={{ position: 'absolute', width: 0, height: 0 }}>
                        <defs>
                            <marker
                                id="arrowhead"
                                markerWidth="10"
                                markerHeight="10"
                                refX="9"
                                refY="3"
                                orient="auto"
                            >
                                <polygon points="0 0, 10 3, 0 6" fill="#64748b" />
                            </marker>
                        </defs>
                    </svg>
                </div>
            </div>

            {/* Modal de Detalles de Tarea */}
            {showTaskDetails && selectedTask && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                        {/* Header */}
                        <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                            <h3 className="font-bold flex items-center text-lg">
                                <Info className="mr-2 text-emerald-200" size={20} />
                                {selectedTask.name}
                            </h3>
                            <button 
                                onClick={() => {
                                    setShowTaskDetails(false);
                                    setSelectedTask(null);
                                }}
                                className="text-white/60 hover:text-white transition"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        {/* Content */}
                        <div className="p-6 overflow-y-auto flex-1">
                            <div className="space-y-4">
                                {/* Fechas */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Fecha Inicio</div>
                                        <div className="text-sm font-medium text-slate-800">
                                            {selectedTask.start.toLocaleDateString('es-MX', { 
                                                weekday: 'long', 
                                                year: 'numeric', 
                                                month: 'long', 
                                                day: 'numeric' 
                                            })}
                                        </div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Fecha Fin</div>
                                        <div className="text-sm font-medium text-slate-800">
                                            {selectedTask.end.toLocaleDateString('es-MX', { 
                                                weekday: 'long', 
                                                year: 'numeric', 
                                                month: 'long', 
                                                day: 'numeric' 
                                            })}
                                        </div>
                                    </div>
                                </div>

                                {/* Duración y Estado */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Duración</div>
                                        <div className="text-sm font-medium text-slate-800">{selectedTask.duration} semanas</div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Estado</div>
                                        <div className="flex items-center gap-2">
                                            {selectedTask.isCritical ? (
                                                <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">
                                                    Ruta Crítica
                                                </span>
                                            ) : (
                                                <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-bold">
                                                    Fase Normal
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                {/* Recursos */}
                                {selectedTask.resources && selectedTask.resources.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Wrench size={16} className="text-blue-600" />
                                            <h4 className="font-bold text-slate-700">Recursos Clave</h4>
                                        </div>
                                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                                            <div className="flex flex-wrap gap-2">
                                                {selectedTask.resources.map((resource, i) => (
                                                    <span key={i} className="px-3 py-1.5 bg-white text-blue-700 rounded-lg text-xs font-medium border border-blue-200">
                                                        {resource}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Riesgos */}
                                {selectedTask.risks && selectedTask.risks.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <AlertTriangle size={16} className="text-amber-600" />
                                            <h4 className="font-bold text-slate-700">Riesgos Potenciales</h4>
                                        </div>
                                        <div className="bg-amber-50 p-4 rounded-lg border border-amber-100">
                                            <ul className="space-y-2">
                                                {selectedTask.risks.map((risk, i) => (
                                                    <li key={i} className="flex items-start gap-2 text-sm text-amber-800">
                                                        <span className="text-amber-600 mt-0.5">•</span>
                                                        <span>{risk}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    </div>
                                )}

                                {/* Partidas Incluidas */}
                                {selectedTask.originalPhase?.items && selectedTask.originalPhase.items.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Package size={16} className="text-emerald-600" />
                                            <h4 className="font-bold text-slate-700">Partidas Incluidas</h4>
                                        </div>
                                        <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-100">
                                            <div className="flex flex-wrap gap-2">
                                                {selectedTask.originalPhase.items.map((item, i) => (
                                                    <span key={i} className="px-3 py-1.5 bg-white text-emerald-700 rounded-lg text-xs font-medium border border-emerald-200">
                                                        {item}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Notas */}
                                {selectedTask.notes && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Info size={16} className="text-slate-600" />
                                            <h4 className="font-bold text-slate-700">Notas</h4>
                                        </div>
                                        <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                                            <p className="text-sm text-slate-700 leading-relaxed">{selectedTask.notes}</p>
                                        </div>
                                    </div>
                                )}

                                {/* Dependencias */}
                                {selectedTask.dependencies && selectedTask.dependencies.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <LinkIcon size={16} className="text-purple-600" />
                                            <h4 className="font-bold text-slate-700">Dependencias</h4>
                                        </div>
                                        <div className="bg-purple-50 p-4 rounded-lg border border-purple-100">
                                            <ul className="space-y-2">
                                                {selectedTask.dependencies.map((depId, i) => {
                                                    const depTask = tasksWithDependencies.find(t => t.id === depId);
                                                    return depTask ? (
                                                        <li key={i} className="text-sm text-purple-800">
                                                            <span className="font-medium">→</span> {depTask.name}
                                                        </li>
                                                    ) : null;
                                                })}
                                            </ul>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Footer */}
                        <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end">
                            <button
                                onClick={() => {
                                    setShowTaskDetails(false);
                                    setSelectedTask(null);
                                }}
                                className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                            >
                                Cerrar
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Leyenda */}
            <div className="p-1.5 bg-slate-50 border-t border-slate-200 flex items-center justify-between text-[9px] shrink-0">
                <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1">
                        <div className="w-2.5 h-2.5 bg-blue-500 rounded"></div>
                        <span className="text-slate-600">Fase Normal</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <div className="w-2.5 h-2.5 bg-red-500 rounded"></div>
                        <span className="text-slate-600">Ruta Crítica</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <LinkIcon size={10} className="text-slate-600" />
                        <span className="text-slate-600">Dependencias</span>
                    </div>
                </div>
                <div className="text-slate-500">
                    Arrastra las barras para cambiar fechas
                </div>
            </div>
        </div>
    );
};

export default GanttChart;

import React, { useState, useEffect } from 'react';
import { Calendar, X, Sparkles, AlertTriangle, CheckCircle, Loader } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';
import ProjectPersistenceService from '../../services/ProjectPersistenceService';
import ScheduleModal from '../budget/ScheduleModal';

/**
 * ScheduleGenerator
 * Componente independiente para generar cronogramas de obra con IA
 * Maneja toda la lógica de generación, validación y persistencia
 */
const ScheduleGenerator = ({
    items = [],
    projectInfo = {},
    projectId = null,
    scheduleData: initialScheduleData = null,
    onScheduleGenerated = null,
    onClose = null,
    showToast = null,
    onSaveToBitacora = null
}) => {
    const [scheduleData, setScheduleData] = useState(initialScheduleData);
    const [isGenerating, setIsGenerating] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState(null);
    const [showConfigModal, setShowConfigModal] = useState(false);
    const [config, setConfig] = useState({
        startDate: new Date().toISOString().split('T')[0],
        workDays: {
            mon: true,
            tue: true,
            wed: true,
            thu: true,
            fri: true,
            sat: true,
            sun: false
        },
        notes: ''
    });

    // Sincronizar scheduleData cuando cambie la prop
    useEffect(() => {
        if (initialScheduleData !== null) {
            setScheduleData(initialScheduleData);
        }
    }, [initialScheduleData]);

    // Validar items antes de generar
    const validateItems = () => {
        if (!items || items.length === 0) {
            return { valid: false, message: 'Agrega partidas antes de generar el cronograma' };
        }

        const hasZeroQuantity = items.some(item => item.quantity <= 0);
        if (hasZeroQuantity) {
            return {
                valid: false,
                message: 'Hay partidas con cantidad 0. Por favor completa las cantidades antes de continuar.'
            };
        }

        return { valid: true };
    };

    // Abrir modal de configuración
    const handleOpenConfig = () => {
        const validation = validateItems();
        if (!validation.valid) {
            if (showToast) {
                showToast(validation.message, 'warning');
            } else {
                setError(validation.message);
            }
            return;
        }

        // Si ya existe cronograma VÁLIDO, abrir el visualizador sin regenerar
        // Si existe pero está vacío o inválido, permitir configurar uno nuevo
        const hasValidSchedule = scheduleData && (
            (scheduleData.tasks && Array.isArray(scheduleData.tasks) && scheduleData.tasks.length > 0) ||
            (scheduleData.phases && Array.isArray(scheduleData.phases) && scheduleData.phases.length > 0)
        );

        if (hasValidSchedule) {
            setShowModal(true);
            return;
        }

        setShowConfigModal(true);
    };

    // Generar cronograma con IA (llamado desde el modal de config)
    const handleGenerateSchedule = async () => {
        setShowConfigModal(false);
        setIsGenerating(true);
        setError(null);
        setShowModal(true);

        try {
            const data = await AIBudgetService.generateSchedule(items, projectInfo, config);
            setScheduleData(data);

            // Auto-guardar si hay projectId
            if (projectId && data) {
                try {
                    await ProjectPersistenceService.syncSchedule(projectId, data);
                    if (showToast) {
                        showToast('Cronograma generado y guardado exitosamente', 'success');
                    }
                } catch (err) {
                    console.error('Error saving schedule:', err);
                    // No mostrar error al usuario, el cronograma se generó correctamente
                }
            }

            // Callback opcional
            if (onScheduleGenerated) {
                onScheduleGenerated(data);
            }
        } catch (error) {
            console.error('Error generating schedule:', error);
            const errorMessage = error.message || 'Error al generar el cronograma';
            setError(errorMessage);
            if (showToast) {
                showToast(errorMessage, 'error');
            }
            setScheduleData(null);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleClose = () => {
        setShowModal(false);
        if (onClose) {
            onClose();
        }
    };

    // Función para regenerar cronograma
    const handleRegenerate = () => {
        setShowModal(false);
        setShowConfigModal(true);
    };

    const handleSaveToBitacoraInternal = async () => {
        if (!projectId) {
            if (showToast) {
                showToast('Guarda el proyecto antes de ir a la bitácora', 'warning');
            }
            return;
        }

        // Guardar cronograma si no está guardado
        if (scheduleData && projectId) {
            try {
                await ProjectPersistenceService.syncSchedule(projectId, scheduleData);
            } catch (err) {
                console.error('Error saving schedule:', err);
            }
        }

        // Usar callback del padre si existe
        if (onSaveToBitacora) {
            onSaveToBitacora();
        } else if (onClose) {
            onClose();
        }
    };

    const toggleWorkDay = (day) => {
        setConfig(prev => ({
            ...prev,
            workDays: {
                ...prev.workDays,
                [day]: !prev.workDays[day]
            }
        }));
    };

    return (
        <>
            {/* Botón de Generar Cronograma */}
            <button
                onClick={handleOpenConfig}
                disabled={isGenerating || !items || items.length === 0}
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all
                    ${isGenerating || !items || items.length === 0
                        ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                        : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-900/20 hover:shadow-xl transform hover:-translate-y-0.5'
                    }
                `}
                title={!items || items.length === 0 ? 'Agrega partidas primero' : 'Generar Cronograma con IA'}
            >
                {isGenerating ? (
                    <>
                        <Loader className="animate-spin" size={18} />
                        <span>Generando...</span>
                    </>
                ) : (
                    <>
                        <Calendar size={18} />
                        <span>Cronograma</span>
                    </>
                )}
            </button>

            {/* Modal de Configuración */}
            {showConfigModal && (
                <div className="fixed inset-0 z-[90] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-xl shadow-2xl max-w-md w-full overflow-hidden">
                        <div className="p-5 border-b border-slate-100 bg-slate-50">
                            <h3 className="font-bold text-lg text-slate-800">Configurar Cronograma</h3>
                            <p className="text-xs text-slate-500">Define los parámetros para la IA</p>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1">Fecha de Inicio</label>
                                <input
                                    type="date"
                                    value={config.startDate}
                                    onChange={(e) => setConfig({ ...config, startDate: e.target.value })}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500 outline-none"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-2">Días Laborables</label>
                                <div className="flex flex-wrap gap-2">
                                    {[
                                        { key: 'mon', label: 'L' },
                                        { key: 'tue', label: 'M' },
                                        { key: 'wed', label: 'X' },
                                        { key: 'thu', label: 'J' },
                                        { key: 'fri', label: 'V' },
                                        { key: 'sat', label: 'S' },
                                        { key: 'sun', label: 'D' },
                                    ].map((day) => (
                                        <button
                                            key={day.key}
                                            onClick={() => toggleWorkDay(day.key)}
                                            className={`w-8 h-8 rounded-full text-xs font-bold flex items-center justify-center transition-colors ${config.workDays[day.key]
                                                    ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                                                    : 'bg-slate-100 text-slate-400 border border-slate-200'
                                                }`}
                                        >
                                            {day.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1">Restricciones / Notas</label>
                                <textarea
                                    value={config.notes}
                                    onChange={(e) => setConfig({ ...config, notes: e.target.value })}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-700 h-20 resize-none focus:ring-2 focus:ring-emerald-500 outline-none"
                                    placeholder="Ej: La cimentación depende de permisos, lluvias esperadas en semana 2..."
                                />
                            </div>
                        </div>
                        <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
                            <button
                                onClick={() => setShowConfigModal(false)}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg text-sm font-medium transition"
                            >
                                Cancelar
                            </button>
                            <button
                                onClick={handleGenerateSchedule}
                                className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-bold shadow-lg shadow-emerald-200 transition flex items-center gap-2"
                            >
                                <Sparkles size={16} />
                                Generar con IA
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Cronograma */}
            {
                showModal && (
                    <ScheduleModal
                        isOpen={showModal}
                        onClose={handleClose}
                        scheduleData={scheduleData}
                        isGenerating={isGenerating}
                        onSaveToBitacora={handleSaveToBitacoraInternal}
                        error={error}
                        projectId={projectId}
                        onRegenerate={handleRegenerate}
                        onScheduleUpdate={async (updatedSchedule) => {
                            setScheduleData(updatedSchedule);
                            // Guardar actualización si hay projectId
                            if (projectId && updatedSchedule) {
                                try {
                                    await ProjectPersistenceService.syncSchedule(projectId, updatedSchedule);
                                    if (showToast) {
                                        showToast('Cronograma actualizado', 'success');
                                    }
                                } catch (err) {
                                    console.error('Error saving schedule update:', err);
                                }
                            }
                        }}
                    />
                )
            }

            {/* Mensaje de Error (si no hay showToast) */}
            {
                error && !showToast && (
                    <div className="fixed bottom-4 right-4 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 z-50 animate-fadeIn">
                        <AlertTriangle size={20} />
                        <span className="text-sm font-medium">{error}</span>
                        <button
                            onClick={() => setError(null)}
                            className="text-red-600 hover:text-red-800"
                        >
                            <X size={16} />
                        </button>
                    </div>
                )
            }
        </>
    );
};

export default ScheduleGenerator;

import React, { useState, useEffect } from 'react';
import { Share2, X, Copy, Check, Lock, Calendar, Trash2, Eye, ExternalLink, Settings, Clock } from 'lucide-react';
import { ShareService } from '../../services/ShareService';

const ShareProjectModal = ({ isOpen, onClose, projectId, projectName }) => {
    const [shares, setShares] = useState([]);
    const [loading, setLoading] = useState(false);
    const [creating, setCreating] = useState(false);
    const [copiedToken, setCopiedToken] = useState(null);
    const [shareConfig, setShareConfig] = useState({
        expiresIn: null, // días
        password: '',
        includeShortCode: true,
        canEdit: false,
        showSchedule: true // Por defecto mostrar cronograma
    });

    useEffect(() => {
        if (isOpen && projectId) {
            loadShares();
        }
    }, [isOpen, projectId]);

    const loadShares = async () => {
        try {
            setLoading(true);
            const data = await ShareService.getProjectShares(projectId);
            setShares(data || []);
        } catch (error) {
            console.error('Error loading shares:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateShare = async () => {
        if (!projectId) return;

        try {
            setCreating(true);
            
            const expiresAt = shareConfig.expiresIn 
                ? new Date(Date.now() + shareConfig.expiresIn * 24 * 60 * 60 * 1000).toISOString()
                : null;

            const share = await ShareService.createShare(projectId, {
                expiresAt,
                password: shareConfig.password || null,
                includeShortCode: shareConfig.includeShortCode,
                canEdit: shareConfig.canEdit,
                metadata: {
                    showSchedule: shareConfig.showSchedule
                }
            });

            // Recargar lista
            await loadShares();

            // Resetear config
            setShareConfig({
                expiresIn: null,
                password: '',
                includeShortCode: true,
                canEdit: false,
                showSchedule: true
            });

            // Copiar automáticamente
            copyToClipboard(share.shareUrl);
        } catch (error) {
            console.error('Error creating share:', error);
            const errorMessage = error.message || 'Error al crear el enlace compartido. Verifica que el proyecto esté guardado y que la tabla project_shares exista en Supabase.';
            alert(errorMessage);
        } finally {
            setCreating(false);
        }
    };

    const copyToClipboard = async (text) => {
        try {
            await navigator.clipboard.writeText(text);
            setCopiedToken(text);
            setTimeout(() => setCopiedToken(null), 2000);
        } catch (error) {
            console.error('Error copying to clipboard:', error);
        }
    };

    const handleDeleteShare = async (shareId) => {
        if (!confirm('¿Eliminar este enlace compartido?')) return;

        try {
            await ShareService.deleteShare(shareId);
            await loadShares();
        } catch (error) {
            console.error('Error deleting share:', error);
            alert('Error al eliminar el enlace');
        }
    };

    const formatExpiresAt = (date) => {
        if (!date) return 'Sin expiración';
        const expires = new Date(date);
        const now = new Date();
        const diffDays = Math.ceil((expires - now) / (1000 * 60 * 60 * 24));
        
        if (diffDays < 0) return 'Expirado';
        if (diffDays === 0) return 'Expira hoy';
        if (diffDays === 1) return 'Expira mañana';
        return `Expira en ${diffDays} días`;
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 dark:bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-slate-200 dark:border-slate-700">
                {/* Header */}
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-xl">
                            <Share2 className="mr-2 text-emerald-200" size={24} />
                            Compartir Presupuesto
                        </h3>
                        <p className="text-sm text-emerald-100 mt-1">{projectName}</p>
                    </div>
                    <button onClick={onClose} className="text-white/80 hover:text-white transition">
                        <X size={24} />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {/* Crear nuevo enlace */}
                    <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-600">
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Crear Nuevo Enlace Compartido</h4>
                        
                        <div className="space-y-4">
                            {/* Opciones de expiración */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Expiración (opcional)
                                </label>
                                <select
                                    value={shareConfig.expiresIn || ''}
                                    onChange={(e) => setShareConfig({ ...shareConfig, expiresIn: e.target.value ? parseInt(e.target.value) : null })}
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200"
                                >
                                    <option value="">Sin expiración</option>
                                    <option value="1">1 día</option>
                                    <option value="7">7 días</option>
                                    <option value="30">30 días</option>
                                    <option value="90">90 días</option>
                                </select>
                            </div>

                            {/* Contraseña opcional */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Contraseña (opcional)
                                </label>
                                <input
                                    type="password"
                                    value={shareConfig.password}
                                    onChange={(e) => setShareConfig({ ...shareConfig, password: e.target.value })}
                                    placeholder="Dejar vacío para sin contraseña"
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200 placeholder:text-slate-400 dark:placeholder:text-slate-500"
                                />
                            </div>

                            {/* Opciones adicionales */}
                            <div className="space-y-3">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.includeShortCode}
                                        onChange={(e) => setShareConfig({ ...shareConfig, includeShortCode: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">Generar código corto</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.showSchedule}
                                        onChange={(e) => setShareConfig({ ...shareConfig, showSchedule: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">
                                        Mostrar cronograma al cliente
                                        <span className="text-xs text-slate-500 dark:text-slate-400 ml-1">(si existe)</span>
                                    </span>
                                </label>
                            </div>

                            <button
                                onClick={handleCreateShare}
                                disabled={creating}
                                className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {creating ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                                        Creando...
                                    </>
                                ) : (
                                    <>
                                        <Share2 size={20} />
                                        Crear Enlace Compartido
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {/* Lista de enlaces existentes */}
                    <div>
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Enlaces Compartidos Activos</h4>
                        
                        {loading ? (
                            <div className="text-center py-8">
                                <div className="animate-spin rounded-full h-8 w-8 border-4 border-emerald-500 border-t-transparent mx-auto mb-2"></div>
                                <p className="text-slate-600 dark:text-slate-400 text-sm">Cargando...</p>
                            </div>
                        ) : shares.length === 0 ? (
                            <div className="text-center py-8 bg-slate-50 dark:bg-slate-700/50 rounded-lg border-2 border-dashed border-slate-300 dark:border-slate-600">
                                <Share2 className="mx-auto mb-3 text-slate-400 dark:text-slate-500" size={32} />
                                <p className="text-slate-600 dark:text-slate-300">No hay enlaces compartidos aún</p>
                                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Crea uno usando el formulario de arriba</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {shares.map((share) => {
                                    const isExpired = share.expires_at && new Date(share.expires_at) < new Date();
                                    const isCopied = copiedToken === share.shareUrl;

                                    return (
                                        <div
                                            key={share.id}
                                            className={`rounded-lg border-2 p-4 ${
                                                isExpired 
                                                    ? 'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20' 
                                                    : 'border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-700/50'
                                            }`}
                                        >
                                            <div className="flex items-start justify-between gap-4">
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center gap-2 mb-2">
                                                        <ExternalLink size={16} className="text-slate-400 dark:text-slate-500" />
                                                        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 truncate">
                                                            {share.shareUrl}
                                                        </span>
                                                        {share.password && (
                                                            <Lock size={14} className="text-amber-600 dark:text-amber-500" />
                                                        )}
                                                        {isExpired && (
                                                            <span className="px-2 py-0.5 bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-400 rounded text-xs font-bold">
                                                                Expirado
                                                            </span>
                                                        )}
                                                    </div>

                                                    {share.shortUrl && (
                                                        <div className="flex items-center gap-2 mb-2">
                                                            <span className="text-xs text-slate-400 dark:text-slate-500">Código corto:</span>
                                                            <span className="text-xs font-mono text-slate-600 dark:text-slate-300">{share.shortUrl}</span>
                                                        </div>
                                                    )}

                                                    <div className="flex items-center gap-4 text-xs text-slate-500 dark:text-slate-400">
                                                        <div className="flex items-center gap-1">
                                                            <Eye size={12} />
                                                            <span>{share.access_count || 0} vistas</span>
                                                        </div>
                                                        <div className="flex items-center gap-1">
                                                            <Calendar size={12} />
                                                            <span>{formatExpiresAt(share.expires_at)}</span>
                                                        </div>
                                                        {share.last_accessed_at && (
                                                            <div className="flex items-center gap-1">
                                                                <Clock size={12} />
                                                                <span>Último acceso: {new Date(share.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-2 shrink-0">
                                                    <button
                                                        onClick={() => copyToClipboard(share.shareUrl)}
                                                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded-lg transition"
                                                        title="Copiar enlace"
                                                    >
                                                        {isCopied ? (
                                                            <Check size={18} className="text-emerald-600 dark:text-emerald-400" />
                                                        ) : (
                                                            <Copy size={18} className="text-slate-600 dark:text-slate-400" />
                                                        )}
                                                    </button>
                                                    <button
                                                        onClick={() => window.open(share.shareUrl, '_blank')}
                                                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded-lg transition"
                                                        title="Abrir enlace"
                                                    >
                                                        <ExternalLink size={18} className="text-slate-600 dark:text-slate-400" />
                                                    </button>
                                                    <button
                                                        onClick={() => handleDeleteShare(share.id)}
