                // Actualizar estado local con el item devuelto (que tendrá el ID real de DB)
                const addedItem = {
                    id: data.id,
                    description: data.description,
                    unit: data.unit,
                    unitPrice: data.unit_price,
                    category: data.category
                };
                setCatalog([addedItem, ...catalog]);
            } else {
                // Guardar en LocalStorage
                const newCatalog = [newItem, ...catalog];
                setCatalog(newCatalog);
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }
            showToast('Concepto agregado al catálogo', 'success');
            return true;
        } catch (error) {
            console.error('Error adding to catalog:', error);
            showToast('Error al agregar al catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    const deleteFromCatalog = async (id) => {
        if (!window.confirm('¿Estás seguro de eliminar este concepto del catálogo?')) return;

        setLoading(true);
        try {
            if (user) {
                const { error } = await supabase
                    .from('catalog_items')
                    .delete()
                    .eq('id', id);

                if (error) throw error;
            }

            // Actualizar estado local (para ambos casos)
            const newCatalog = catalog.filter(item => item.id !== id);
            setCatalog(newCatalog);

            if (!user) {
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }

            showToast('Concepto eliminado del catálogo');
        } catch (error) {
            console.error('Error deleting from catalog:', error);
            showToast('Error al eliminar del catálogo', 'error');
        } finally {
            setLoading(false);
        }
    };

    const updateCatalogBulk = async (updatedItems) => {
        setLoading(true);
        try {
            if (user) {
                // Upsert to Supabase
                const itemsToUpsert = updatedItems.map(item => ({
                    id: item.id,
                    user_id: user.id,
                    description: item.description,
                    unit: item.unit,
                    unit_price: item.unitPrice,
                    category: item.category,
                    is_public: false,
                    updated_at: new Date().toISOString()
                }));

                const { error } = await supabase
                    .from('catalog_items')
                    .upsert(itemsToUpsert);

                if (error) throw error;
            } else {
                // Save to LocalStorage
                localStorage.setItem('presugenius_catalog', JSON.stringify(updatedItems));
            }

            setCatalog(updatedItems);
            showToast('Catálogo actualizado correctamente', 'success');
            return true;
        } catch (error) {
            console.error('Error updating catalog bulk:', error.message || error);
            if (error.details) console.error('Error details:', error.details);
            showToast('Error al actualizar el catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR DATOS AL INICIAR ---
    // Evitar bucle: solo ejecutar carga una vez por user.id; si falla la red no reintentar en cada render
    useEffect(() => {
        if (authLoading) return;

        if (!user) {
            lastLoadedUserIdRef.current = null;
            loadFromLocalStorage();
            return;
        }

        if (lastLoadedUserIdRef.current === user.id) return;
        lastLoadedUserIdRef.current = user.id;
        loadUserData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user?.id, authLoading]);

    // --- Auto-timeout para toasts ---
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    const calculateSubtotal = () => CalculationsService.calculateSubtotal(items);

    const calculateTotal = () => {
        const calc = CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
        return calc.total;
    };

    const getCalculations = () => {
        return CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
    };

    // --- GUARDAR PROYECTO ---
    const saveBudget = async () => {
        setLoading(true);

        try {
            if (user) {
                // Guardar en Supabase
                const projectData = {
                    user_id: user.id,
                    name: projectInfo.project,
                    client: projectInfo.client,
                    type: projectInfo.type,
                    currency: projectInfo.currency,
                    tax_rate: projectInfo.taxRate,
                    indirect_percentage: projectInfo.indirect_percentage || 0,
                    profit_percentage: projectInfo.profit_percentage || 0,
                    updated_at: new Date().toISOString()
                };

                let projectId = projectInfo.id;

                // Verificar si el proyecto ya existe
                const { data: existingProject } = await supabase
                    .from('projects')
                    .select('id')
                    .eq('id', projectInfo.id)
                    .single();

                if (existingProject) {
                    // Actualizar proyecto existente
                    await supabase
                        .from('projects')
                        .update(projectData)
                        .eq('id', projectInfo.id);
                } else {
                    // Crear nuevo proyecto
                    const { data: newProject, error: projectError } = await supabase
                        .from('projects')
                        .insert([{ ...projectData, id: projectInfo.id }])
                        .select()
                        .single();

                    if (projectError) throw projectError;
                    projectId = newProject.id;
                }

                // Eliminar items antiguos
                await supabase
                    .from('budget_items')
                    .delete()
                    .eq('project_id', projectId);

                // Insertar items nuevos
                if (items.length > 0) {
                    const itemsData = items.map((item, index) => ({
                        project_id: projectId,
                        description: item.description,
                        unit: item.unit,
                        quantity: item.quantity,
                        unit_price: item.unitPrice,
                        category: item.category,
                        subcategory: item.subcategory || null,
                        tags: item.tags || [],
                        notes: item.notes || '',
                        is_catalog_item: item.isCatalogItem || false,
                        order_index: index
                    }));

                    await supabase
                        .from('budget_items')
                        .insert(itemsData);
                }

                // Recargar proyectos
                await loadUserData();
                showToast('Proyecto guardado en la nube', 'success');

            } else {
                // Guardar en localStorage (modo offline)
                const budgetData = {
                    ...projectInfo,
                    items,
                    lastModified: new Date().toISOString(),
                    total: calculateTotal()
                };

                const existingIndex = savedBudgets.findIndex(b => b.id === projectInfo.id);
                let newSaved;

                if (existingIndex >= 0) {
                    newSaved = [...savedBudgets];
                    newSaved[existingIndex] = budgetData;
                } else {
                    newSaved = [...savedBudgets, budgetData];
                }

                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto guardado localmente', 'success');
            }
        } catch (error) {
            console.error('Error saving budget:', error);
            showToast('Error al guardar proyecto', 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR PROYECTO ---
    const loadBudget = (budget) => {
        setProjectInfo({
            id: budget.id,
            client: budget.client,
            project: budget.name || budget.project,
            date: budget.date || new Date().toISOString().split('T')[0],
            currency: budget.currency,
            taxRate: budget.tax_rate || budget.taxRate,
            type: budget.type,
            indirect_percentage: budget.indirect_percentage || 0,
            profit_percentage: budget.profit_percentage || 0
        });
        setItems(budget.items || []);
        showToast(`Proyecto "${budget.name || budget.project}" cargado`);
    };

    // --- ELIMINAR PROYECTO ---
    const deleteBudget = async (id) => {
        setLoading(true);

        try {
            if (user) {
                // Eliminar de Supabase
                await supabase
                    .from('projects')
                    .delete()
                    .eq('id', id);

                await loadUserData();
                showToast('Proyecto eliminado de la nube', 'success');
            } else {
                // Eliminar de localStorage
                const newSaved = savedBudgets.filter(b => b.id !== id);
                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto eliminado');
            }
        } catch (error) {
            const errorMessage = error.message || 'Error al eliminar proyecto';
            console.error('Error deleting budget:', error);
            showToast(errorMessage, 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- NUEVO PROYECTO ---
    const newProject = () => {
        setProjectInfo({
            id: generateId(),
            client: '',
            project: 'Presupuesto Nuevo',
            date: new Date().toISOString().split('T')[0],
            currency: 'MXN',
            taxRate: 16,
            type: 'General',
            indirect_percentage: 0,
            profit_percentage: 0
        });
        setItems([]);
        showToast('Nuevo proyecto creado');
    };

    const value = React.useMemo(() => ({
        projectInfo, setProjectInfo,
        items, setItems,
        savedBudgets, setSavedBudgets,
        catalog, setCatalog,
        toast, showToast, setToast,
        calculateSubtotal, calculateTotal, getCalculations,
        saveBudget, loadBudget, deleteBudget, newProject,
        addToCatalog, deleteFromCatalog, updateCatalogBulk,
        loading,
        rateLimitModal, showRateLimitModal, closeRateLimitModal
    }), [
        projectInfo, items, savedBudgets, catalog, toast, loading, rateLimitModal,
        showToast, showRateLimitModal, closeRateLimitModal
    ]);

    return <ProjectContext.Provider value={value}>{children}</ProjectContext.Provider>;
};

import React, { createContext, useContext, useState, useEffect } from 'react';

const SidebarContext = createContext();

export const useSidebar = () => {
    const context = useContext(SidebarContext);
    if (!context) {
        throw new Error('useSidebar must be used within a SidebarProvider');
    }
    return context;
};

export const SidebarProvider = ({ children }) => {
    const [isCollapsed, setIsCollapsed] = useState(() => {
        const saved = localStorage.getItem('sidebarCollapsed');
        return saved ? JSON.parse(saved) : false;
    });

    useEffect(() => {
        localStorage.setItem('sidebarCollapsed', JSON.stringify(isCollapsed));
    }, [isCollapsed]);

    const toggleSidebar = () => {
        setIsCollapsed(prev => !prev);
    };

    return (
        <SidebarContext.Provider value={{ isCollapsed, setIsCollapsed, toggleSidebar }}>
            {children}
        </SidebarContext.Provider>
    );
};

import React, { createContext, useState, useEffect, useContext } from 'react';
import { useAuth } from './AuthContext';
import { SubscriptionService } from '../services/SubscriptionService';

const SubscriptionContext = createContext();

export const useSubscription = () => {
    const context = useContext(SubscriptionContext);
    if (context === undefined) {
        throw new Error('useSubscription must be used within a SubscriptionProvider');
    }
    return context;
};

export const SubscriptionProvider = ({ children }) => {
    const { user } = useAuth();
    const [plan, setPlan] = useState(SubscriptionService.PLANS.FREE);
    const [usage, setUsage] = useState(SubscriptionService.getDefaultUsage());
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            // Verificar inmediatamente si es un email Pro
            if (user.email && SubscriptionService.isProEmail(user.email)) {
                setPlan(SubscriptionService.PLANS.PRO);
                setUsage(SubscriptionService.getDefaultUsage());
                setLoading(false);
            } else {
                loadSubscriptionData();
            }
        } else {
            setPlan(SubscriptionService.PLANS.FREE);
            setUsage(SubscriptionService.getDefaultUsage());
            setLoading(false);
        }
    }, [user]);

    const loadSubscriptionData = async () => {
        if (!user) return;

        // Verificar primero si es email Pro
        if (user.email && SubscriptionService.isProEmail(user.email)) {
            setPlan(SubscriptionService.PLANS.PRO);
            setUsage(SubscriptionService.getDefaultUsage());
            setLoading(false);
            return;
        }

        setLoading(true);
        try {
            const [userPlan, userUsage] = await Promise.all([
                SubscriptionService.getUserPlan(user.id),
                SubscriptionService.getUserUsage(user.id)
            ]);

            setPlan(userPlan);
            setUsage(userUsage);
        } catch (error) {
            console.error('Error loading subscription data:', error);
            // Si hay error pero es email Pro, asignar Pro
            if (user.email && SubscriptionService.isProEmail(user.email)) {
                setPlan(SubscriptionService.PLANS.PRO);
            }
        } finally {
            setLoading(false);
        }
    };

    const checkLimit = async (actionType) => {
        if (!user) return { allowed: false, remaining: 0 };

        // Si es email Pro, siempre permitir
        if (user.email && SubscriptionService.isProEmail(user.email)) {
            return { allowed: true, remaining: -1, limit: -1, current: 0 };
        }

        const result = await SubscriptionService.canPerformAction(user.id, actionType);

        // Actualizar uso local
        if (result.allowed) {
            setUsage(prev => ({
                ...prev,
                [actionType]: (prev[actionType] || 0) + 1
            }));
        }

        return result;
    };

    const incrementUsage = async (actionType) => {
        if (!user) return;

        try {
            await SubscriptionService.incrementUsage(user.id, actionType);
            await loadSubscriptionData(); // Recargar datos
        } catch (error) {
            console.error('Error incrementing usage:', error);
        }
    };

    const refreshData = async () => {
        await loadSubscriptionData();
    };

    // Determinar si es Pro (por plan o por email especial)
    const isProUser = plan.id === 'pro' || (user?.email && SubscriptionService.isProEmail(user.email));

    const value = {
        plan: isProUser ? SubscriptionService.PLANS.PRO : plan,
        usage,
        loading,
        checkLimit,
        incrementUsage,
        refreshData,
        isPro: isProUser
    };

    return (
        <SubscriptionContext.Provider value={value}>
            {children}
        </SubscriptionContext.Provider>
    );
};

import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext();

export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useTheme must be used within a ThemeProvider');
    }
    return context;
};

export const ThemeProvider = ({ children }) => {
    // Leer preferencia guardada o usar preferencia del sistema
    const getInitialTheme = () => {
        // Verificar que estamos en el cliente
        if (typeof window === 'undefined') {
            return false;
        }
        
        try {
            const savedTheme = localStorage.getItem('presugenius_theme');
            if (savedTheme) {
                return savedTheme === 'dark';
            }
            // Detectar preferencia del sistema
            if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
                return true;
            }
        } catch (e) {
            console.warn('Error reading theme preference:', e);
        }
        return false;
    };

    const [isDark, setIsDark] = useState(() => {
        // Lazy initialization para evitar problemas en SSR
        return getInitialTheme();
    });

    useEffect(() => {
        // Verificar que estamos en el cliente
        if (typeof window === 'undefined' || typeof document === 'undefined') {
            return;
        }
        
        // Aplicar tema al documento
        if (isDark) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
        
        // Guardar preferencia
        try {
            localStorage.setItem('presugenius_theme', isDark ? 'dark' : 'light');
        } catch (e) {
            console.warn('Error saving theme preference:', e);
        }
    }, [isDark]);

    // Escuchar cambios en la preferencia del sistema
    useEffect(() => {
        if (typeof window === 'undefined' || !window.matchMedia) {
            return;
        }
        
        try {
            const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
            const handleChange = (e) => {
                // Solo aplicar si no hay preferencia guardada
                try {
                    if (!localStorage.getItem('presugenius_theme')) {
                        setIsDark(e.matches);
                    }
                } catch (err) {
                    console.warn('Error reading theme preference:', err);
                }
            };
            mediaQuery.addEventListener('change', handleChange);
            return () => mediaQuery.removeEventListener('change', handleChange);
        } catch (e) {
            console.warn('Error setting up theme listener:', e);
        }
    }, []);

    const toggleTheme = () => {
        setIsDark(!isDark);
    };

    const value = {
        isDark,
        toggleTheme,
        setTheme: setIsDark
    };

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};

