                                                                {phase.resources.map((res, i) => (
                                                                    <span key={i} className="text-[10px] text-blue-700 bg-white px-2 py-0.5 rounded border border-blue-200">
                                                                        {res}
                                                                    </span>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    )}
                                                    {phase.risks?.length > 0 && (
                                                        <div className="mb-2">
