                                                <div className="divide-y divide-slate-100">
                                                    {phase.tasks.map((task, tIndex) => {
                                                        const taskId = task.id || `task-${pIndex}-${tIndex}`;
                                                        const progress = getTaskProgress(taskId);
                                                        const taskLogs = getTaskLogs(taskId);

