                                >
                                    <Plus size={22} /> Agregar más fotos y concepto
                                </button>
                            </div>
                        )}

                        {/* Footer con Firmas */}
                        {entries.length > 0 && (
                            <div className="mt-6 sm:mt-8 bg-white border-2 border-slate-300 rounded-xl sm:rounded-2xl p-5 sm:p-8 shadow-md">
