import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    FileText,
    Camera,
    Plus,
    Search,
    Filter,
    Folder,
    Calendar,
    ChevronRight,
    LayoutGrid,
    List,
    Clock,
    User,
    MapPin,
    AlertCircle,
    BookOpen,
    Trash2
} from 'lucide-react';
import ConfirmModal from '../components/ui/ConfirmModal';

import Card from '../components/ui/Card';
import ProjectPersistenceService from '../services/ProjectPersistenceService';
import { formatCurrency } from '../utils/format';
import AlertModal from '../components/ui/AlertModal';

const ProjectReportsDashboard = () => {
    const navigate = useNavigate();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
    const [showNewProjectModal, setShowNewProjectModal] = useState(false);
    const [alertModal, setAlertModal] = useState({ isOpen: false, title: '', message: '', type: 'info' });
    const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', type: 'danger', onConfirm: () => { } });


    // Formulario para nuevo proyecto express (sin presupuesto)
    const [newProject, setNewProject] = useState({
        name: '',
        client: '',
        location: '',
        type: 'General'
    });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading projects:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateProject = async (e) => {
        e.preventDefault();
        if (!newProject.name.trim()) {
            setAlertModal({
                isOpen: true,
                title: 'Campo requerido',
                message: 'El nombre del proyecto es obligatorio.',
                type: 'warning'
            });
            return;
        }

        try {
            const projectData = {
                projectInfo: {
                    project: newProject.name,
                    client: newProject.client,
                    location: newProject.location,
                    type: newProject.type,
                    taxRate: 16
                },
                items: [],
                lastModified: new Date().toISOString()
            };

            const saved = await ProjectPersistenceService.saveProject(projectData);
            setShowNewProjectModal(false);
            setNewProject({ name: '', client: '', location: '', type: 'General' });
            loadProjects();

            setAlertModal({
                isOpen: true,
                title: 'Proyecto Creado',
                message: `El proyecto "${newProject.name}" ha sido creado. Ahora puedes agregar bitácoras o reportes.`,
                type: 'success'
            });
        } catch (error) {
            console.error('Error creating project:', error);
            setAlertModal({
                isOpen: true,
                title: 'Error',
                message: 'No se pudo crear el proyecto: ' + error.message,
                type: 'error'
            });
        }
    };

    const handleDeleteProject = (project) => {
        setConfirmModal({
            isOpen: true,
            title: 'Eliminar Proyecto',
            message: `¿Estás seguro de que deseas eliminar el proyecto "${project.project}"? Se eliminarán también todas las bitácoras y reportes asociados. Esta acción no se puede deshacer.`,
            type: 'danger',
            onConfirm: async () => {
                try {
                    await ProjectPersistenceService.deleteProject(project.id);
                    loadProjects();
                    setAlertModal({
                        isOpen: true,
                        title: 'Proyecto Eliminado',
                        message: 'El proyecto y todos sus datos asociados han sido eliminados.',
                        type: 'success'
                    });
                } catch (error) {
                    console.error('Error deleting project:', error);
                    setAlertModal({
                        isOpen: true,
                        title: 'Error',
                        message: 'No se pudo eliminar el proyecto: ' + error.message,
                        type: 'error'
                    });
                }
            }
        });
    };


    const filteredProjects = useMemo(() => {
        return projects.filter(p =>
            p.project?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.client?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.location?.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [projects, searchTerm]);

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleDateString('es-MX', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    return (
        <div className="flex flex-col min-h-[calc(100vh-140px)] animate-fadeIn pb-4">

            {/* Header */}
            <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center">
                <div>
                    <h1 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-slate-50 mb-1">Módulo de Reportes</h1>
                    <p className="text-sm md:text-base text-slate-600 dark:text-slate-300">Gestiona Bitácoras y Reportes Fotográficos de tus obras</p>
                </div>
                <button
                    onClick={() => setShowNewProjectModal(true)}
                    className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-blue-200 dark:shadow-blue-900/50 transition flex items-center justify-center gap-2"
                >
                    <Plus size={20} />
                    <span>Nuevo Proyecto</span>
                </button>
            </div>


            <div className="space-y-6 flex-1 flex flex-col">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">

                    <div className="flex-1 relative order-2 sm:order-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar proyecto..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 sm:py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setViewMode('grid')}
                            className={`p-2 rounded-lg transition ${viewMode === 'grid' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <LayoutGrid size={20} />
                        </button>
                        <button
                            onClick={() => setViewMode('list')}
                            className={`p-2 rounded-lg transition ${viewMode === 'list' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <List size={20} />
                        </button>
                    </div>
                </div>

                {/* Projects Content */}
                {loading ? (
                    <div className="flex flex-col items-center justify-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-600 border-t-transparent mb-4"></div>
                        <p className="text-slate-500">Cargando proyectos...</p>
                    </div>
                ) : filteredProjects.length === 0 ? (
                    <div className="flex-1 flex flex-col items-center justify-center bg-white dark:bg-slate-800 rounded-2xl p-8 md:p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-700 my-4">
                        <Folder size={64} className="mx-auto text-slate-300 mb-4" />
                        <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200">No se encontraron proyectos</h3>
                        <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-md">Crea un proyecto nuevo para comenzar a generar reportes bibliográficos, fotográficos y bitácoras.</p>
                        <button
                            onClick={() => setShowNewProjectModal(true)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-bold transition shadow-lg shadow-blue-200"
                        >
                            Crear mi primer proyecto
                        </button>
                    </div>
                ) : viewMode === 'grid' ? (

                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">

                        {filteredProjects.map(project => (
                            <Card key={project.id} className="group hover:shadow-xl transition-all duration-300 border-t-4 border-t-blue-500">
                                <div className="p-1">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                                            <Folder size={24} />
                                        </div>
                                        <span className="text-[10px] font-bold uppercase tracking-widest px-2 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 rounded">
                                            {project.type || 'General'}
                                        </span>
                                    </div>
                                    <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2 line-clamp-1">{project.project}</h3>

                                    <div className="space-y-2 mb-6">
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <User size={14} />
                                            <span className="truncate">{project.client || 'Sin cliente'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <MapPin size={14} />
                                            <span className="truncate">{project.location || 'Sin ubicación'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-500 gap-2">
                                            <Clock size={14} />
                                            <span>Última mod: {formatDate(project.lastModified)}</span>
                                        </div>
                                    </div>

                                    <div className="mt-4 flex gap-2">
                                        <button
                                            onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                            className="flex-1 flex items-center justify-center gap-2 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition shadow-lg shadow-blue-200 dark:shadow-none"
                                        >
                                            <Folder size={18} />
                                            Gestionar
                                        </button>
                                        <button
                                            onClick={() => handleDeleteProject(project)}
                                            className="p-3 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition"
                                            title="Eliminar Proyecto"
                                        >
                                            <Trash2 size={20} />
                                        </button>
                                    </div>


                                </div>
                            </Card>
                        ))}
                    </div>
                ) : (
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-x-auto overflow-y-hidden">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Proyecto</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Cliente</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Última Modificación</th>
                                    <th className="px-6 py-4 text-center text-xs font-bold text-slate-500 uppercase tracking-wider">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {filteredProjects.map(project => (
                                    <tr key={project.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="p-2 bg-blue-100 dark:bg-blue-900/50 text-blue-600 rounded-lg">
                                                    <Folder size={18} />
                                                </div>
                                                <div>
                                                    <p className="font-bold text-slate-900 dark:text-white">{project.project}</p>
                                                    <p className="text-xs text-slate-500">{project.type || 'General'}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-400">
                                            {project.client || 'N/A'}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-500">
                                            {formatDate(project.lastModified)}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex items-center justify-center gap-2">
                                                <button
                                                    onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                                    className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-300 rounded-lg font-bold hover:bg-blue-100 transition flex items-center gap-2"
                                                >
                                                    <Folder size={16} />
                                                    Gestionar
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteProject(project)}
                                                    className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                                    title="Eliminar"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>


                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modal para Nuevo Proyecto Express */}
            {showNewProjectModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100 border border-slate-200 dark:border-slate-700">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                <Plus className="text-blue-500" size={24} />
                                Nuevo Proyecto de Obra
                            </h2>
                            <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
                                <Plus size={24} className="rotate-45" />
                            </button>
                        </div>

                        <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Nombre de la Obra *</label>
                                <input
                                    autoFocus
                                    type="text"
                                    required
                                    value={newProject.name}
                                    onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ej: Remodelación Casa Blanca"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Cliente/Empresa</label>
                                <input
                                    type="text"
                                    value={newProject.client}
                                    onChange={(e) => setNewProject({ ...newProject, client: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Nombre del cliente"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Ubicación</label>
                                <input
                                    type="text"
                                    value={newProject.location}
                                    onChange={(e) => setNewProject({ ...newProject, location: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ubicación de la obra"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Tipo de Proyecto</label>
                                <select
                                    value={newProject.type}
                                    onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                >
                                    <option value="General">General</option>
                                    <option value="Residencial">Residencial</option>
                                    <option value="Comercial">Comercial</option>
                                    <option value="Industrial">Industrial</option>
                                    <option value="Infraestructura">Infraestructura</option>
                                </select>
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setShowNewProjectModal(false)}
                                    className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-bold hover:bg-slate-200 transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none transition"
                                >
                                    Crear Proyecto
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={confirmModal.onConfirm}
                type={confirmModal.type}
            />

            {/* Alert Modal */}

            <AlertModal
                isOpen={alertModal.isOpen}
                onClose={() => setAlertModal({ ...alertModal, isOpen: false })}
                title={alertModal.title}
                message={alertModal.message}
                type={alertModal.type}
            />
        </div>
    );
};

export default ProjectReportsDashboard;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Calendar, Clock } from 'lucide-react';
import GanttChart from '../components/schedule/GanttChart';
import ProjectPersistenceService from '../services/ProjectPersistenceService';

const ScheduleGanttPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [scheduleData, setScheduleData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [projectInfo, setProjectInfo] = useState(null);

    useEffect(() => {
        loadSchedule();
    }, [id]);

    const loadSchedule = async () => {
        if (!id) {
            navigate('/editor');
            return;
        }

        try {
            setLoading(true);
            const project = await ProjectPersistenceService.loadProject(id);
            
            if (project && project.scheduleData) {
                setScheduleData(project.scheduleData);
                setProjectInfo(project.projectInfo);
            } else {
                // Si no hay cronograma, redirigir al editor
                navigate(`/editor/${id}`);
            }
        } catch (error) {
            console.error('Error loading schedule:', error);
            navigate(`/editor/${id}`);
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = async (updatedSchedule) => {
        setScheduleData(updatedSchedule);
        
        // Guardar automáticamente
        if (id) {
            try {
                await ProjectPersistenceService.syncSchedule(id, updatedSchedule);
            } catch (error) {
                console.error('Error saving schedule:', error);
            }
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600">Cargando cronograma...</p>
                </div>
            </div>
        );
    }

    if (!scheduleData || !scheduleData.phases || scheduleData.phases.length === 0) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-lg p-8 max-w-md w-full text-center">
                    <Calendar className="mx-auto mb-4 text-slate-400" size={48} />
                    <h2 className="text-xl font-bold text-slate-800 mb-2">No hay cronograma disponible</h2>
                    <p className="text-slate-600 mb-6">Genera un cronograma desde el editor del proyecto.</p>
                    <button
                        onClick={() => navigate(`/editor/${id}`)}
                        className="px-6 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition"
                    >
                        Ir al Editor
                    </button>
                </div>
            </div>
        );
    }

    const { totalDurationWeeks = 0, startDate = new Date().toISOString().split('T')[0] } = scheduleData || {};

    return (
        <div className="min-h-screen bg-slate-50">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 sticky top-0 z-10">
                <div className="w-full px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <button
                                onClick={() => navigate(`/editor/${id}`)}
                                className="p-2 hover:bg-slate-100 rounded-lg transition"
                                title="Volver al editor"
                            >
                                <ArrowLeft size={20} className="text-slate-600" />
                            </button>
                            <div>
                                <h1 className="text-xl font-bold text-slate-800">
                                    {projectInfo?.project || 'Cronograma de Obra'}
                                </h1>
                                <p className="text-sm text-slate-500">
                                    Vista Gantt - Cronograma Visual Interactivo
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4">
                            {/* Summary Card Compacta */}
                            <div className="bg-emerald-50 px-4 py-2 rounded-lg border border-emerald-200">
                                <div className="flex items-center gap-2">
                                    <Clock className="text-emerald-600" size={18} />
                                    <div>
                                        <div className="text-xs text-emerald-600 font-medium">Duración Total</div>
                                        <div className="text-sm font-bold text-emerald-700">{totalDurationWeeks} Semanas</div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Gantt Chart - Ocupa todo el espacio disponible */}
            <div className="w-full h-[calc(100vh-100px)] p-4">
                <div className="h-full w-full bg-slate-50 rounded-lg overflow-hidden border border-slate-200">
                    <GanttChart
                        scheduleData={scheduleData}
                        onUpdate={handleUpdate}
                        startDate={startDate ? new Date(startDate) : new Date()}
                    />
                </div>
            </div>
        </div>
    );
};

export default ScheduleGanttPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, Lock, Eye, Download, ArrowLeft, Clock, User, Building2, Package, Calendar as CalendarIcon } from 'lucide-react';
import { ShareService } from '../services/ShareService';
import { PDFService } from '../services/PDFService';
import { formatCurrency } from '../utils/format';

const SharedProjectPage = () => {
    const { token } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [projectData, setProjectData] = useState(null);
    const [shareInfo, setShareInfo] = useState(null);
    const [passwordRequired, setPasswordRequired] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [error, setError] = useState(null);

    useEffect(() => {
        loadSharedProject();
    }, [token]);

    const loadSharedProject = async () => {
        try {
            setLoading(true);
            setError(null);

            const shareData = await ShareService.getShareByToken(token);

            // Verificar si requiere contraseña
            if (shareData.password) {
                // Verificar si ya se verificó (usando sessionStorage)
                const verified = sessionStorage.getItem(`share_verified_${token}`);
                if (!verified) {
                    setPasswordRequired(true);
                    setShareInfo(shareData);
                    setLoading(false);
                    return;
                }
            }

            setShareInfo(shareData);

            // Extraer datos del proyecto
            const project = shareData.projects;
            if (!project || !project.data) {
                throw new Error('Proyecto no encontrado o no disponible');
            }

            const fullProjectData = project.data;
            
            // Normalizar projectInfo para asegurar que todos los campos se carguen correctamente
            const normalizedProjectInfo = {
                project: fullProjectData.projectInfo?.project || project.name,
                client: fullProjectData.projectInfo?.client || project.client,
                type: fullProjectData.projectInfo?.type || project.type,
                taxRate: fullProjectData.projectInfo?.taxRate ?? 16, // Usar ?? para permitir 0
                currency: fullProjectData.projectInfo?.currency || 'MXN',
                date: fullProjectData.projectInfo?.date || new Date().toISOString().split('T')[0],
                location: fullProjectData.projectInfo?.location || 'México',
                ...fullProjectData.projectInfo // Preservar otros campos
            };
            
            setProjectData({
                projectInfo: normalizedProjectInfo,
                items: fullProjectData.items || [],
                scheduleData: fullProjectData.scheduleData,
                materialList: fullProjectData.materialList,
                apuData: fullProjectData.apuData
            });

        } catch (error) {
            console.error('Error loading shared project:', error);
            setError(error.message || 'No se pudo cargar el proyecto compartido');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        setPasswordError('');

        try {
            const isValid = await ShareService.verifyPassword(token, password);
            if (isValid) {
                // Guardar en sessionStorage para esta sesión
                sessionStorage.setItem(`share_verified_${token}`, 'true');
                setPasswordRequired(false);
                // Recargar con contraseña verificada
                await loadSharedProject();
            } else {
                setPasswordError('Contraseña incorrecta');
            }
        } catch (error) {
            setPasswordError('Error al verificar contraseña');
        }
    };

    const calculateTotals = () => {
        if (!projectData || !projectData.items || projectData.items.length === 0) {
            return { subtotal: 0, tax: 0, total: 0 };
        }

        const subtotal = projectData.items.reduce((sum, item) => {
            return sum + (item.quantity || 0) * (item.unitPrice || 0);
        }, 0);

        // Usar nullish coalescing para permitir taxRate = 0
        const taxRateValue = projectData.projectInfo?.taxRate ?? 16;
        const taxRate = taxRateValue / 100;
        const tax = subtotal * taxRate;
        const total = subtotal + tax;

        return { subtotal, tax, total };
    };

    const handleExportPDF = () => {
        if (!projectData) return;

        const { subtotal, tax, total } = calculateTotals();
        PDFService.exportBudget(
            projectData.projectInfo,
            projectData.items,
            total,
            subtotal,
            tax
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600 font-medium">Cargando presupuesto...</p>
                </div>
            </div>
        );
    }

    if (passwordRequired) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
                    <div className="text-center mb-6">
                        <div className="bg-emerald-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <Lock className="text-emerald-600" size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 mb-2">Presupuesto Protegido</h2>
                        <p className="text-slate-600">Este presupuesto está protegido con contraseña</p>
                    </div>

                    <form onSubmit={handlePasswordSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                Contraseña
                            </label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                placeholder="Ingresa la contraseña"
                                required
                                autoFocus
                            />
                            {passwordError && (
                                <p className="text-red-600 text-sm mt-2">{passwordError}</p>
                            )}
                        </div>

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition shadow-lg shadow-emerald-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full text-center">
                    <div className="bg-red-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                        <Lock className="text-red-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">No disponible</h2>
                    <p className="text-slate-600 mb-6">{error}</p>
                    <button
                        onClick={() => navigate('/')}
                        className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                    >
                        Ir al Inicio
                    </button>
                </div>
            </div>
        );
    }

    if (!projectData) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <p className="text-slate-600">No hay datos disponibles</p>
                </div>
            </div>
        );
    }

    const { subtotal, tax, total } = calculateTotals();
    const items = projectData.items || [];

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 shadow-sm">
                <div className="max-w-6xl mx-auto px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                {projectData.projectInfo?.project || 'Presupuesto'}
                            </h1>
                            <div className="flex items-center gap-4 mt-2 text-sm text-slate-600">
                                {projectData.projectInfo?.client && (
                                    <div className="flex items-center gap-1">
                                        <User size={14} />
                                        <span>{projectData.projectInfo.client}</span>
                                    </div>
                                )}
                                {projectData.projectInfo?.type && (
                                    <div className="flex items-center gap-1">
                                        <Building2 size={14} />
                                        <span>{projectData.projectInfo.type}</span>
                                    </div>
                                )}
                                {shareInfo?.last_accessed_at && (
                                    <div className="flex items-center gap-1">
                                        <Clock size={14} />
                                        <span>Visto {new Date(shareInfo.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleExportPDF}
                                className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 shadow-lg shadow-emerald-200"
                            >
                                <Download size={18} />
                                Descargar PDF
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="max-w-6xl mx-auto px-6 py-8">
                {/* Resumen */}
                <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
                    <h2 className="text-lg font-bold text-slate-800 mb-4">Resumen del Presupuesto</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">Subtotal</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(subtotal)}</div>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">IVA ({projectData.projectInfo?.taxRate ?? 16}%)</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(tax)}</div>
                        </div>
                        <div className="bg-emerald-50 p-4 rounded-lg border-2 border-emerald-200">
                            <div className="text-sm text-emerald-600 font-medium mb-1">Total</div>
                            <div className="text-3xl font-bold text-emerald-700">{formatCurrency(total)}</div>
                        </div>
                    </div>
                </div>

                {/* Partidas */}
                <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                    <div className="p-6 border-b border-slate-200">
                        <h2 className="text-lg font-bold text-slate-800">Partidas del Presupuesto</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-slate-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">#</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Descripción</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">P. Unit.</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200">
                                {items.map((item, index) => (
                                    <tr key={item.id || index} className="hover:bg-slate-50 transition">
                                        <td className="px-6 py-4 text-sm text-slate-600">{index + 1}</td>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-medium text-slate-800">{item.description}</div>
                                            {item.category && (
                                                <div className="text-xs text-slate-500 mt-1">{item.category}</div>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600">{item.unit || 'pza'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{item.quantity?.toFixed(2) || '0.00'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(item.unitPrice || 0)}</td>
                                        <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                            {formatCurrency((item.quantity || 0) * (item.unitPrice || 0))}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot className="bg-slate-50">
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">Subtotal:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(subtotal)}</td>
                                </tr>
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                        IVA ({projectData.projectInfo?.taxRate ?? 16}%):
                                    </td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(tax)}</td>
                                </tr>
                                <tr className="bg-emerald-50">
                                    <td colSpan="4" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">Total:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">{formatCurrency(total)}</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>

                {/* Lista de Materiales/Insumos */}
                {projectData.materialList && projectData.materialList.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <Package size={20} className="text-indigo-600" />
                                Lista de Insumos y Materiales
                            </h2>
                        </div>
                        {projectData.materialAssumptions && projectData.materialAssumptions.length > 0 && (
                            <div className="bg-amber-50 border-b border-amber-100 p-4">
                                <h4 className="text-sm font-bold text-amber-800 mb-2">Notas Importantes</h4>
                                <ul className="list-disc list-inside text-xs text-amber-700 space-y-1">
                                    {projectData.materialAssumptions.map((assumption, idx) => (
                                        <li key={idx}>{assumption}</li>
                                    ))}
                                </ul>
                            </div>
                        )}
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-slate-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Material</th>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Categoría</th>
                                        <th className="px-6 py-3 text-center text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Costo Est.</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                        {projectData.materialList.some(m => m.notes) && (
                                            <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Notas</th>
                                        )}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-200">
                                    {projectData.materialList.map((mat, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50 transition">
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800">{mat.material}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600">{mat.category || 'Materiales'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600 text-center">{mat.unit || 'pza'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{mat.quantity?.toFixed(2) || '0.00'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(mat.unitPrice || 0)}</td>
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                                {formatCurrency((mat.quantity || 0) * (mat.unitPrice || 0))}
                                            </td>
                                            {projectData.materialList.some(m => m.notes) && (
                                                <td className="px-6 py-4 text-xs text-slate-500 italic">{mat.notes || '-'}</td>
                                            )}
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot className="bg-slate-50">
                                    <tr>
                                        <td colSpan={projectData.materialList.some(m => m.notes) ? 5 : 4} className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                            Total Estimado:
                                        </td>
                                        <td colSpan={2} className="px-6 py-4 text-right text-sm font-bold text-slate-800">
                                            {formatCurrency(
                                                projectData.materialList.reduce((sum, m) => sum + ((m.quantity || 0) * (m.unitPrice || 0)), 0)
                                            )}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                )}

                {/* Cronograma */}
                {shareInfo?.metadata?.showSchedule !== false && projectData.scheduleData && projectData.scheduleData.tasks && projectData.scheduleData.tasks.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <CalendarIcon size={20} className="text-blue-600" />
                                Cronograma de Obra
                            </h2>
                        </div>
                        <div className="p-6">
                            <div className="space-y-4">
                                {projectData.scheduleData.tasks.map((task, idx) => (
                                    <div key={task.id || idx} className="border border-slate-200 rounded-lg p-4 hover:bg-slate-50 transition">
                                        <div className="flex items-start justify-between mb-2">
                                            <div className="flex-1">
                                                <h3 className="text-sm font-bold text-slate-800">{task.name || `Tarea ${idx + 1}`}</h3>
                                                {task.description && (
                                                    <p className="text-xs text-slate-600 mt-1">{task.description}</p>
                                                )}
                                            </div>
                                            {task.progress !== undefined && (
                                                <div className="ml-4 text-right">
                                                    <div className="text-xs text-slate-500 mb-1">Progreso</div>
                                                    <div className="text-sm font-bold text-blue-600">{task.progress || 0}%</div>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-4 mt-3 text-xs text-slate-500">
                                            {task.startDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Inicio: {new Date(task.startDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.endDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Fin: {new Date(task.endDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.duration && (
                                                <div>
                                                    <span>Duración: {task.duration} {task.durationUnit || 'días'}</span>
                                                </div>
                                            )}
                                        </div>
                                        {task.dependencies && task.dependencies.length > 0 && (
                                            <div className="mt-2 text-xs text-slate-500">
                                                <span className="font-medium">Depende de:</span> {task.dependencies.join(', ')}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-8 text-center text-sm text-slate-500">
                    <p>Este presupuesto fue compartido contigo desde PresuGenius</p>
                    <p className="mt-1">Generado el {new Date().toLocaleDateString('es-MX', { 
                        year: 'numeric', 
                        month: 'long', 
                        day: 'numeric' 
                    })}</p>
                </div>
            </div>
        </div>
    );
};

export default SharedProjectPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FileText, Search, Filter, Plus, Sparkles, Download, Eye, Trash2, Lock, Globe } from 'lucide-react';
import Card from '../components/ui/Card';
import { useAuth } from '../context/AuthContext';
import { useProject } from '../context/ProjectContext';
import { TemplateService } from '../services/TemplateService';
import { formatCurrency } from '../utils/format';

const Templates = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const { showToast } = useProject();

    const [templates, setTemplates] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [showOnlyMyTemplates, setShowOnlyMyTemplates] = useState(false);

    useEffect(() => {
        loadData();
    }, [selectedCategory, showOnlyMyTemplates, user]);

    // Listen for template creation events
    useEffect(() => {
        const handleTemplateCreated = () => {
            loadData();
        };
        window.addEventListener('templateCreated', handleTemplateCreated);
        return () => window.removeEventListener('templateCreated', handleTemplateCreated);
    }, []);

    const loadData = async () => {
        setLoading(true);
        try {
            let templatesData;
            
            if (user) {
                // If user is logged in:
                if (showOnlyMyTemplates) {
                    // Show only user's own templates (private + public they created)
                    templatesData = await TemplateService.getUserTemplates(user.id);
                } else {
                    // Show user's templates + public templates from others
                    templatesData = await TemplateService.getUserTemplatesWithPublic(user.id, selectedCategory);
                }
            } else {
                // If not logged in, show only public templates
                templatesData = await TemplateService.getTemplates(selectedCategory, true);
            }

            const categoriesData = await TemplateService.getCategories();

            setTemplates(templatesData || []);
            setCategories(categoriesData || []);
        } catch (error) {
            console.error('Error loading templates:', error);
            showToast('Error al cargar plantillas', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = async () => {
        if (!searchQuery.trim()) {
            loadData();
            return;
        }

        setLoading(true);
        try {
            const results = await TemplateService.searchTemplates(searchQuery, user?.id || null);
            setTemplates(results);
        } catch (error) {
            console.error('Error en búsqueda:', error);
            showToast('Error en la búsqueda', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleUseTemplate = async (template) => {
        if (!user) {
            showToast('Inicia sesión para usar plantillas', 'warning');
            navigate('/login');
            return;
        }

        try {
            const customization = {
                projectName: `${template.name} - Copia`,
                client: '',
                location: ''
            };

            const result = await TemplateService.useTemplate(template.id, customization, user.id);
            showToast(`Proyecto creado con ${result.itemsCount} partidas`, 'success');
            navigate('/dashboard');
        } catch (error) {
            showToast('Error al crear proyecto desde plantilla', 'error');
        }
    };

    const handleDeleteTemplate = async (templateId) => {
        if (!confirm('¿Eliminar esta plantilla?')) return;

        try {
            await TemplateService.deleteTemplate(templateId, user.id);
            showToast('Plantilla eliminada', 'success');
            loadData();
        } catch (error) {
            showToast('Error al eliminar plantilla', 'error');
        }
    };

    const filteredTemplates = templates.filter(template =>
        template.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.description?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header */}
            <div className="bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 rounded-2xl p-8 shadow-xl relative overflow-hidden">
                {/* Decorative background elements */}
                <div className="absolute inset-0 opacity-10">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-white rounded-full -mr-32 -mt-32"></div>
                    <div className="absolute bottom-0 left-0 w-48 h-48 bg-white rounded-full -ml-24 -mb-24"></div>
                </div>
                
                <div className="relative z-10 flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-bold mb-2 flex items-center gap-3 text-white">
                            <div className="bg-white/20 backdrop-blur-sm p-2 rounded-lg">
                                <FileText size={32} className="text-white" />
                            </div>
                            Plantillas de Presupuesto
                        </h1>
                        <p className="text-blue-100 text-lg">
                            Comienza rápido con presupuestos predefinidos para diferentes tipos de obra
                        </p>
                    </div>
                    <div className="hidden md:block">
                        <Sparkles size={64} className="text-white/30" />
                    </div>
                </div>
            </div>

            {/* Search and Filters */}
            <Card className="p-6 bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700">
                <div className="flex flex-col md:flex-row gap-4">
                    {/* Search */}
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500" size={20} />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                            placeholder="Buscar plantillas..."
                            className="w-full pl-10 pr-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 placeholder:text-slate-400 dark:placeholder:text-slate-500"
                        />
                    </div>

                    {/* Category Filter */}
                    <select
                        value={selectedCategory || ''}
                        onChange={(e) => setSelectedCategory(e.target.value || null)}
                        className="px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100"
                    >
                        <option value="">Todas las categorías</option>
                        {categories.map(cat => (
                            <option key={cat.id} value={cat.id}>{cat.name}</option>
                        ))}
                    </select>

                    {/* My Templates Toggle */}
                    {user && (
                        <button
                            onClick={() => setShowOnlyMyTemplates(!showOnlyMyTemplates)}
                            className={`px-4 py-2.5 rounded-lg font-medium transition flex items-center gap-2 ${showOnlyMyTemplates
                                ? 'bg-blue-600 text-white hover:bg-blue-700'
                                : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-200 dark:hover:bg-slate-600'
                                }`}
                        >
                            <Lock size={18} />
                            Mis Plantillas
                        </button>
                    )}
                </div>
