            .map(item => item.unitPrice || item.price || 0)
            .filter(p => p > 0);

        // Prevent division by zero
        if (prices.length === 0) {
            return {
                suggested: null,
                min: null,
                max: null,
                confidence: 'low',
                message: 'No hay precios válidos en los items similares'
