            }
        });

        // Summary
        const finalY = doc.lastAutoTable.finalY + 10;

        doc.setFontSize(10);
        doc.text('Subtotal:', 140, finalY);
        doc.text(formatCurrency(calculations.subtotal), 180, finalY, { align: 'right' });

