        summaryData.push(['', '', '', '', '', `IVA (${projectInfo.taxRate}%):`, calculations.tax]);
        summaryData.push(['', '', '', '', '', 'TOTAL:', calculations.total]);

        const sheetData = [...infoData, itemsHeader, ...itemsData, ...summaryData];

