            // Datos de la constructora (nombre, RFC u otros)
            const companyName = options.companyName || projectInfo.companyName || contractor;
            const companyRfc = options.companyRfc || projectInfo.companyRfc || '';
            const companyExtra = options.companyExtra || projectInfo.companyExtra || '';

            doc.setFont('helvetica', 'bold');
            doc.setFontSize(11);
            doc.text((companyName || '').toUpperCase(), textX, textYBase);

            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            let extraLineY = textYBase + 4;
            if (companyRfc) {
                doc.text(`RFC: ${companyRfc.toUpperCase()}`, textX, extraLineY);
                extraLineY += 3.5;
            }
            if (companyExtra) {
                doc.text(companyExtra.toUpperCase(), textX, extraLineY);
            }

            // Título del reporte, más pequeño, debajo del membrete
            const titleY = headerTop + headerHeight + 5;
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(10);
            doc.text("REPORTE FOTOGRAFICO DE OBRA", pageWidth / 2, titleY, { align: 'center' });

            // Preparar datos para la tabla
            // Solo mostrar el nombre de la obra; la ubicación va en su propia celda
            const conceptsText = Array.isArray(concepts) ? concepts.join(', ') : concepts;

            // Crear tabla real usando autoTable
            const tableStartY = titleY + 4;

            // Verificar que autoTable esté disponible
            if (typeof autoTable !== 'function') {
                throw new Error('autoTable no está disponible. Verifica que jspdf-autotable esté correctamente instalado.');
            }

            autoTable(doc, {
                startY: tableStartY,
                margin: { left: margin, right: margin },
                tableWidth: pageWidth - (margin * 2),
                head: [],
                body: [
                    [
                        { content: 'CONTRATISTA:\n' + contractor, styles: { fontSize: 8, cellPadding: 2 } },
                        { content: 'OBRA:\n' + obra, styles: { fontSize: 8, cellPadding: 2 } },
                        { content: 'CONTRATO No.:\n' + contractNumber, styles: { fontSize: 8, cellPadding: 2 } }
                    ],
                    [
                        { content: 'UBICACIÓN:\n' + ubicacion, styles: { fontSize: 8, cellPadding: 2 } },
                        { content: 'CONCEPTOS:\n' + conceptsText, styles: { fontSize: 8, cellPadding: 2 } },
                        { content: 'FECHA:\n' + fechaFormateada, styles: { fontSize: 8, cellPadding: 2 } }
                    ]
                ],
                columnStyles: {
                    0: { cellWidth: 50, halign: 'left', valign: 'top' },
                    1: { cellWidth: 'auto', halign: 'left', valign: 'top' },
                    2: { cellWidth: 50, halign: 'left', valign: 'top' }
                },
                styles: {
                    lineWidth: 0.3,
                    lineColor: [0, 0, 0],
                    fontSize: 7,
                    cellPadding: 2
                },
                theme: 'grid',
                headStyles: {
                    fillColor: false,
                    textColor: [0, 0, 0]
                },
                bodyStyles: {
                    fillColor: false,
                    textColor: [0, 0, 0]
                }
            });

            // Retornar la posición Y final del header
            return doc.lastAutoTable.finalY + 3;
        };

        const addFooter = () => {
            const footerY = pageHeight - 30; // Subido un poco para que no queden tan a la orilla

            // Signatures Section (formato exacto del ejemplo)
            doc.setLineWidth(0.5);
            doc.setDrawColor(0);

            // Left Signature - El Contratista (usando valores editables)
            const leftSigX = margin + 42.5;
            doc.line(leftSigX - 25, footerY, leftSigX + 25, footerY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.text(contractorTitle, leftSigX, footerY + 5, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text(contractorName, leftSigX, footerY + 10, { align: 'center' });
            doc.setFontSize(6);
            doc.text(contractorRole, leftSigX, footerY + 15, { align: 'center' });

            // Right Signature - H. Ayuntamiento (usando valores editables)
            const rightSigX = pageWidth - margin - 42.5;
            doc.line(rightSigX - 25, footerY, rightSigX + 25, footerY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.text(municipalityTitle, rightSigX, footerY + 5, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text(supervisorName, rightSigX, footerY + 10, { align: 'center' });
            doc.setFontSize(6);
            doc.text(supervisorRole, rightSigX, footerY + 15, { align: 'center' });
        };

        // Agrupar logs por concepto/tarea
        const logsByConcept = this.groupLogsByConcept(logs);

        // --- Content Generation ---
        const headerEndY = await addHeader(); // Obtener posición final del header

        // Configuración de fotos: 6 por hoja (2 filas x 3 columnas) en A4 horizontal
        let yPos = headerEndY + 4;
        // Fotos ligeramente más chicas para dejar más espacio en la página (preview)
        const photoWidth = 78;
        const photoHeight = 45;
        const gapX = 6;
        const gapY = 56;
        const photosPerRow = 3;
        const photosPerPage = 6;


        // Recolectar fotos: bajo cada foto solo descripción opcional (concepto general no se repite)
        const allPhotos = [];
        for (const [conceptName, conceptLogs] of Object.entries(logsByConcept)) {
            for (const log of conceptLogs) {
                if (!log.photos || log.photos.length === 0) continue;
                const { photoCaptions: savedCaptions } = this.parsePhotoReportContent(log.content || '');
                const photos = log.photos || [];
                for (let i = 0; i < photos.length; i++) {
                    const optionalCaption = (savedCaptions[i] || '').trim();
                    allPhotos.push({
                        url: photos[i],
                        caption: optionalCaption,
                        concept: conceptName
                    });
                }
            }
        }

        // Procesar fotos en grid 2x4 (formato horizontal)
        let photoIndex = 0;
        let pageStartIndex = 0;

        for (const photo of allPhotos) {
            // Verificar si necesitamos nueva página (cada 8 fotos = 2 filas x 4 columnas)
            if (photoIndex > 0 && (photoIndex - pageStartIndex) >= photosPerPage) {
                addFooter();
                doc.addPage('landscape'); // Nueva página también en horizontal
                const newHeaderEndY = await addHeader(); // Obtener posición final del header en nueva página
                yPos = newHeaderEndY + 3; // Inicio después del header con menos espacio
                pageStartIndex = photoIndex;
            }

            // Calcular posición dentro de la página actual (grid 2x4)
            const indexInPage = photoIndex - pageStartIndex;
            const col = indexInPage % photosPerRow; // 0, 1, 2, 3
            const row = Math.floor(indexInPage / photosPerRow); // 0 o 1
            const xPos = margin + (col * (photoWidth + gapX));
            const currentYPos = yPos + (row * gapY);

            try {
                // Agregar imagen
                const imgData = await this.fetchImage(photo.url);

                if (!imgData) {
                    throw new Error('No se pudo obtener datos de la imagen');
                }

                // Agregar imagen al PDF
                doc.addImage(imgData, 'JPEG', xPos, currentYPos, photoWidth, photoHeight);

                // Borde alrededor de la imagen (más visible como en el ejemplo)
                doc.setLineWidth(0.3);
                doc.setDrawColor(0);
                doc.rect(xPos, currentYPos, photoWidth, photoHeight);

                // Solo mostrar descripción opcional bajo la foto si existe (no repetir concepto general)
                if (photo.caption) {
                    doc.setFontSize(6);
                    doc.setFont('helvetica', 'normal');
                    const splitCaption = doc.splitTextToSize(photo.caption.toUpperCase(), photoWidth - 4);
                    const captionY = currentYPos + photoHeight + 4;
                    doc.text(splitCaption.length ? splitCaption[0] : '', xPos + 2, captionY);
                }

            } catch (err) {
                console.error(`Error adding image ${photoIndex + 1} to PDF:`, err);
                // Placeholder si falla la carga
                doc.setLineWidth(0.3);
                doc.setDrawColor(200, 200, 200);
                doc.rect(xPos, currentYPos, photoWidth, photoHeight);
                doc.setFontSize(5);
                doc.setTextColor(150, 150, 150);
                doc.text("Error al cargar imagen", xPos + 2, currentYPos + photoHeight / 2);
                doc.setTextColor(0, 0, 0);
            }

            photoIndex++;
        }

        addFooter();

        // Devolver blob en lugar de descargar
        return doc.output('blob');
    }

    /**
     * Extrae los conceptos únicos de los logs
     */
    static extractConceptsFromLogs(logs) {
        const concepts = new Set();
        logs.forEach(log => {
            if (log.subject) {
                // Extraer nombre del concepto del subject
                const match = log.subject.match(/Reporte Fotográfico:\s*(.+)/);
                if (match) {
                    concepts.add(match[1]);
                } else {
                    concepts.add(log.subject);
                }
            }
        });
        return Array.from(concepts);
    }

    /**
     * Agrupa logs por concepto/tarea
     */
    static groupLogsByConcept(logs) {
        const grouped = {};
        logs.forEach(log => {
            const conceptName = log.subject?.replace('Reporte Fotográfico: ', '') ||
                log.task_id ||
                'Concepto General';
            if (!grouped[conceptName]) {
                grouped[conceptName] = [];
            }
            grouped[conceptName].push(log);
        });
        return grouped;
    }

    // Helper to fetch image and convert to base64
    static async fetchImage(url) {
        try {
            // Si la URL es relativa o local, intentar cargarla directamente
            if (url.startsWith('blob:') || url.startsWith('data:')) {
                return url;
            }

            // Si es una URL completa, hacer fetch
            const response = await fetch(url, {
                mode: 'cors',
                credentials: 'omit'
            });

            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            const blob = await response.blob();
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => {
                    if (reader.result) {
                        resolve(reader.result);
                    } else {
                        reject(new Error('Failed to convert image to base64'));
                    }
                };
                reader.onerror = () => reject(new Error('Error reading image'));
                reader.readAsDataURL(blob);
            });
        } catch (error) {
            console.error('Error fetching image:', error);
            console.error('Image URL:', url);
            throw error;
        }
    }

    /**
     * Genera un reporte completo de bitácora en PDF (notas, textos, avances)
     * @param {Object} projectInfo - Información del proyecto
     * @param {Array} logs - Lista completa de logs de bitácora
     * @param {string} reportDate - Fecha del reporte
     * @param {Object} options - Opciones adicionales
     */
    // Helper para extraer metadata de bitácora
    static extractBitacoraMetadata(content) {
        if (!content) return null;
        const metadataMatch = content.match(/<!--BITACORA_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                return null;
            }
        }
        return null;
    }

    // Helper para limpiar contenido de metadata
    static getCleanContent(content) {
        if (!content) return '';
        return content.replace(/<!--BITACORA_METADATA:.*?-->/, '').trim();
    }

    /**
     * Parsea content de un log de reporte fotográfico: extrae concepto general y descripciones opcionales por foto.
     * El concepto general va arriba (CONCEPTOS); bajo cada foto solo se muestra descripción opcional si la hay.
     * @param {string} content
     * @returns {{ cleanContent: string, photoCaptions: string[] }}
     */
    static parsePhotoReportContent(content) {
        if (!content) return { cleanContent: '', photoCaptions: [] };
        const match = content.match(/<!--PHOTO_CAPTIONS:(.*?)-->$/s);
        let photoCaptions = [];
        let cleanContent = content;
        if (match) {
            try {
                photoCaptions = JSON.parse(match[1].trim());
                if (!Array.isArray(photoCaptions)) photoCaptions = [];
            } catch (_) {}
            cleanContent = content.replace(/\n?\s*<!--PHOTO_CAPTIONS:.*?-->$/s, '').trim();
        }
        return { cleanContent, photoCaptions };
    }

    static async generateBitacoraReport(projectInfo, logs, reportDate, options = {}) {
        // Validar y depurar logs
        console.log('generateBitacoraReport llamado con', logs?.length || 0, 'logs');
        if (!logs || logs.length === 0) {
            throw new Error('No hay notas de bitácora para generar el reporte');
        }
        console.log('Logs recibidos:', logs.map(l => ({
            id: l.id,
            subject: l.subject,
            content: l.content?.substring(0, 50),
            note_number: l.note_number,
            photos: l.photos?.length || 0,
            isDiaryEntry: l.isDiaryEntry,
            task_id: l.task_id
        })));

        const doc = new jsPDF('landscape', 'mm', 'a4');
        const pageWidth = doc.internal.pageSize.width; // 297mm en horizontal
        const pageHeight = doc.internal.pageSize.height; // 210mm en horizontal
        const margin = 15;
        const gutter = 8; // Espacio entre columnas
        const columnWidth = (pageWidth - (margin * 2) - gutter) / 2; // Dos columnas con espacio entre ellas

        // Colores profesionales
        const primaryColor = [79, 70, 229]; // Indigo
        const secondaryColor = [251, 191, 36]; // Amber
        const lightAmber = [255, 251, 235];
        const darkGray = [51, 65, 85];
        const mediumGray = [100, 116, 139];

        // Helper para agregar header en cada página
        const addHeader = () => {
            // Fondo del header con gradiente
            doc.setFillColor(...primaryColor);
            doc.rect(0, 0, pageWidth, 35, 'F');

            // Título principal
            doc.setFontSize(20);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(255, 255, 255);
            doc.text("BITÁCORA DE OBRA", pageWidth / 2, 18, { align: 'center' });

            // Subtítulo
            doc.setFontSize(9);
            doc.setFont('helvetica', 'normal');
            doc.text("DOCUMENTO OFICIAL DE SEGUIMIENTO", pageWidth / 2, 26, { align: 'center' });

            // Línea decorativa
            doc.setDrawColor(255, 255, 255);
            doc.setLineWidth(0.5);
            doc.line(margin, 32, pageWidth - margin, 32);

            return 40; // Retornar posición Y después del header
        };

        // Helper para agregar footer con firma
        const addFooter = (pageNum, totalPages) => {
            const footerY = pageHeight - 50;

            // Línea separadora
            doc.setLineWidth(0.3);
            doc.setDrawColor(200, 200, 200);
            doc.line(margin, footerY, pageWidth - margin, footerY);

            // Sección de firma
            const signatureY = footerY + 8;
            doc.setLineWidth(0.5);
            doc.setDrawColor(0, 0, 0);

            // Línea de firma izquierda
            const leftSigX = margin + 50;
            doc.line(leftSigX - 40, signatureY, leftSigX + 40, signatureY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text("RESIDENTE", leftSigX, signatureY + 6, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text("Firma y Sello", leftSigX, signatureY + 11, { align: 'center' });

            // Línea de firma derecha
            const rightSigX = pageWidth - margin - 50;
            doc.line(rightSigX - 40, signatureY, rightSigX + 40, signatureY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.text("SUPERVISOR", rightSigX, signatureY + 6, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text("Firma y Sello", rightSigX, signatureY + 11, { align: 'center' });

            // Información de página
            doc.setFontSize(7);
            doc.setTextColor(150, 150, 150);
            doc.text(`Página ${pageNum}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
        };

        // Ordenar logs por fecha
        const sortedLogs = [...logs].sort((a, b) =>
            new Date(a.log_date || a.created_at) - new Date(b.log_date || b.created_at)
        );

        let yPos = addHeader();
        let pageNum = 1;
        const totalPages = Math.ceil(sortedLogs.length / 2) + 1; // Estimación

        // Información del proyecto con estilo elegante (solo en primera página)
        doc.setFillColor(...lightAmber);
        doc.setDrawColor(...secondaryColor);
        doc.setLineWidth(0.5);
        doc.rect(margin, yPos, pageWidth - (margin * 2), 18, 'FD');

        yPos += 5;
        doc.setFontSize(9);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...darkGray);
        doc.text("PROYECTO:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.project || projectInfo.name || 'Proyecto', margin + 28, yPos);

        yPos += 5;
        doc.setFont('helvetica', 'bold');
        doc.text("UBICACIÓN:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.location || 'No especificada', margin + 28, yPos);

        yPos += 5;
        doc.setFont('helvetica', 'bold');
        doc.text("FECHA:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(new Date(reportDate).toLocaleDateString('es-MX', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        }), margin + 28, yPos);

        yPos += 12;

        // Variables para control de columnas (simular libro abierto)
        let currentColumn = 0; // 0 = izquierda, 1 = derecha
        let leftY = yPos;
        let rightY = yPos;
        const columnMargin = 2;

        // Procesar cada nota en dos columnas
        for (const log of sortedLogs) {
            let logProcessed = false;

            while (!logProcessed) {
                // Determinar en qué columna colocar la nota
                const useLeftColumn = currentColumn === 0;
                const columnX = useLeftColumn ? margin : (margin + columnWidth + gutter);
                let currentY = useLeftColumn ? leftY : rightY;
                const noteStartY = currentY;

                // Verificar si necesitamos nueva página o cambiar de columna
                // Ajustar límite a 60mm para dar más espacio (antes era 100mm)
                if (currentY > pageHeight - 60) {
                    if (useLeftColumn && rightY <= pageHeight - 60) {
                        // Columna izquierda llena, cambiar a derecha
                        currentColumn = 1;
                        continue; // Reintentar en columna derecha
                    } else {
                        // Ambas columnas llenas o columna derecha llena, nueva página
                        addFooter(pageNum, totalPages);
                        doc.addPage('landscape');
                        pageNum++;
                        yPos = addHeader();
                        leftY = yPos;
                        rightY = yPos;
                        currentColumn = 0;
                        continue; // Reintentar en nueva página
                    }
                }

                // Extraer metadata y limpiar contenido
                const metadata = this.extractBitacoraMetadata(log.content);
                const cleanContent = this.getCleanContent(log.content);

                // Tarjeta de nota con diseño elegante
                const noteWidth = columnWidth - (columnMargin * 2);

                // Header de la nota con fondo de color
                doc.setFillColor(...primaryColor);
                doc.rect(columnX + columnMargin, currentY, noteWidth, 10, 'F');

                doc.setFontSize(9);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(255, 255, 255);
                doc.text(`FOLIO #${log.note_number || 'N/A'}`, columnX + columnMargin + 3, currentY + 6);

                doc.setFontSize(7);
                doc.setFont('helvetica', 'normal');
                const classification = (log.classification || 'Informe').toUpperCase();
                doc.text(classification, columnX + columnMargin + 35, currentY + 6);

                currentY += 12;

                // Asunto
                doc.setFontSize(10);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(...darkGray);
                const subject = log.subject || log.content?.substring(0, 50) || 'Sin asunto';
                const subjectLines = doc.splitTextToSize(subject, noteWidth - 6);
                doc.text(subjectLines, columnX + columnMargin + 3, currentY);
                currentY += subjectLines.length * 5 + 3;

                // Línea decorativa
                doc.setLineWidth(0.2);
                doc.setDrawColor(200, 200, 200);
                doc.line(columnX + columnMargin + 3, currentY, columnX + noteWidth - columnMargin - 3, currentY);
                currentY += 3;

                // Contenido principal
                const contentToShow = cleanContent || log.content || '';
                if (contentToShow && contentToShow.trim()) {
                    doc.setFontSize(8);
                    doc.setFont('helvetica', 'normal');
                    doc.setTextColor(51, 65, 85);
                    const contentLines = doc.splitTextToSize(contentToShow, noteWidth - 6);
                    doc.text(contentLines, columnX + columnMargin + 3, currentY);
                    currentY += contentLines.length * 4 + 3;
                } else if (!log.subject && !log.content) {
                    // Si no hay asunto ni contenido, mostrar al menos un mensaje
                    doc.setFontSize(8);
                    doc.setFont('helvetica', 'italic');
                    doc.setTextColor(150, 150, 150);
                    doc.text('(Nota sin contenido)', columnX + columnMargin + 3, currentY);
                    currentY += 5;
                }

                // Metadata adicional
                if (metadata && (metadata.weather || metadata.materials || metadata.personnel)) {
                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'bold');
                    doc.setTextColor(...primaryColor);
                    doc.text("INFO ADICIONAL:", columnX + columnMargin + 3, currentY);
                    currentY += 4;

                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'normal');
                    doc.setTextColor(51, 65, 85);

                    if (metadata.weather) {
                        doc.text(`• Clima: ${metadata.weather}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    if (metadata.materials) {
                        doc.text(`• Materiales: ${metadata.materials}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    if (metadata.personnel) {
                        doc.text(`• Personal: ${metadata.personnel}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    currentY += 2;
                }

                // Observaciones
                if (metadata && metadata.observations) {
                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'bold');
                    doc.setTextColor(139, 92, 246);
                    doc.text("OBSERVACIONES:", columnX + columnMargin + 3, currentY);
                    currentY += 4;

                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'italic');
                    doc.setTextColor(71, 85, 105);
                    const obsLines = doc.splitTextToSize(metadata.observations, noteWidth - 6);
                    doc.text(obsLines, columnX + columnMargin + 5, currentY);
                    currentY += obsLines.length * 4 + 3;
                }

                // Footer de la nota con badges
                doc.setLineWidth(0.2);
                doc.setDrawColor(220, 220, 220);
                doc.line(columnX + columnMargin + 3, currentY, columnX + noteWidth - columnMargin - 3, currentY);
                currentY += 4;

                // Badges de información (más pequeños para caber)
                const badgeY = currentY;
                let badgeX = columnX + columnMargin + 3;

                // Badge de avance
                doc.setFillColor(...primaryColor);
                doc.rect(badgeX, badgeY, 22, 6, 'F');
                doc.setFontSize(6);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(255, 255, 255);
                doc.text(`${log.progress_percentage || 0}%`, badgeX + 1, badgeY + 4.5);
                badgeX += 24;

                // Badge de autor
                doc.setFillColor(139, 92, 246);
                doc.rect(badgeX, badgeY, 25, 6, 'F');
                doc.text(log.author_role || 'N/A', badgeX + 1, badgeY + 4.5);
                badgeX += 27;

                // Badge de estatus
                const statusColor = log.status === 'Cerrada' ? [34, 197, 94] : [251, 191, 36];
                doc.setFillColor(...statusColor);
                doc.rect(badgeX, badgeY, 20, 6, 'F');
                doc.text(log.status || 'Abierta', badgeX + 1, badgeY + 4.5);

                currentY += 9;

                // Dibujar borde de la tarjeta completa
                const noteCardHeight = currentY - noteStartY;
                doc.setFillColor(255, 255, 255);
                doc.setDrawColor(...secondaryColor);
                doc.setLineWidth(0.5);
                doc.rect(columnX + columnMargin, noteStartY, noteWidth, noteCardHeight, 'FD');

                // Actualizar posición Y de la columna correspondiente
                if (useLeftColumn) {
                    leftY = currentY + 5;
                    currentColumn = 1; // Cambiar a columna derecha para la próxima nota
                } else {
                    rightY = currentY + 5;
                    currentColumn = 0; // Cambiar a columna izquierda para la próxima nota
                }

                logProcessed = true; // Marcar como procesado
                console.log(`  Nota ${log.note_number} renderizada exitosamente en Y=${noteStartY} a Y=${currentY}`);
            }
        }

        console.log('Renderizado completado. Total de notas procesadas:', sortedLogs.length);

        // Footer final
        addFooter(pageNum, totalPages);

        // Guardar
        const fileName = `BITACORA_${projectInfo.project?.replace(/\s+/g, '_') || 'OBRA'}_${reportDate}.pdf`;
        doc.save(fileName);
    }

    /**
     * Genera un preview del reporte de bitácora en PDF (retorna blob en lugar de descargar)
     * @param {Object} projectInfo - Información del proyecto
     * @param {Array} logs - Lista completa de logs de bitácora
     * @param {string} reportDate - Fecha del reporte
     * @param {Object} options - Opciones adicionales
     * @returns {Blob} - Blob del PDF generado
     */
    static async generateBitacoraReportPreview(projectInfo, logs, reportDate, options = {}) {
        const doc = new jsPDF('landscape', 'mm', 'a4');
        const pageWidth = doc.internal.pageSize.width; // 297mm en horizontal
        const pageHeight = doc.internal.pageSize.height; // 210mm en horizontal
        const margin = 15;
        const gutter = 8; // Espacio entre columnas
        const columnWidth = (pageWidth - (margin * 2) - gutter) / 2; // Dos columnas con espacio entre ellas

        // Colores profesionales
        const primaryColor = [79, 70, 229]; // Indigo
        const secondaryColor = [251, 191, 36]; // Amber
        const lightAmber = [255, 251, 235];
        const darkGray = [51, 65, 85];
        const mediumGray = [100, 116, 139];

        // Helper para agregar header en cada página
        const addHeader = () => {
            // Fondo del header con gradiente
            doc.setFillColor(...primaryColor);
            doc.rect(0, 0, pageWidth, 35, 'F');

            // Título principal
            doc.setFontSize(20);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(255, 255, 255);
            doc.text("BITÁCORA DE OBRA", pageWidth / 2, 18, { align: 'center' });

            // Subtítulo
            doc.setFontSize(9);
            doc.setFont('helvetica', 'normal');
            doc.text("DOCUMENTO OFICIAL DE SEGUIMIENTO", pageWidth / 2, 26, { align: 'center' });

            // Línea decorativa
            doc.setDrawColor(255, 255, 255);
            doc.setLineWidth(0.5);
            doc.line(margin, 32, pageWidth - margin, 32);

            return 40; // Retornar posición Y después del header
        };

        // Helper para agregar footer con firma
        const addFooter = (pageNum, totalPages) => {
            const footerY = pageHeight - 50;

            // Línea separadora
            doc.setLineWidth(0.3);
            doc.setDrawColor(200, 200, 200);
            doc.line(margin, footerY, pageWidth - margin, footerY);

            // Sección de firma
            const signatureY = footerY + 8;
            doc.setLineWidth(0.5);
            doc.setDrawColor(0, 0, 0);

            // Línea de firma izquierda
            const leftSigX = margin + 50;
            doc.line(leftSigX - 40, signatureY, leftSigX + 40, signatureY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text("RESIDENTE", leftSigX, signatureY + 6, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text("Firma y Sello", leftSigX, signatureY + 11, { align: 'center' });

            // Línea de firma derecha
            const rightSigX = pageWidth - margin - 50;
            doc.line(rightSigX - 40, signatureY, rightSigX + 40, signatureY);
            doc.setFontSize(8);
            doc.setFont('helvetica', 'bold');
            doc.text("SUPERVISOR", rightSigX, signatureY + 6, { align: 'center' });
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(7);
            doc.text("Firma y Sello", rightSigX, signatureY + 11, { align: 'center' });

            // Información de página
            doc.setFontSize(7);
            doc.setTextColor(150, 150, 150);
            doc.text(`Página ${pageNum}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
        };

        // Ordenar logs por fecha
        const sortedLogs = [...logs].sort((a, b) =>
            new Date(a.log_date || a.created_at) - new Date(b.log_date || b.created_at)
        );

        let yPos = addHeader();
        let pageNum = 1;
        const totalPages = Math.ceil(sortedLogs.length / 2) + 1; // Estimación

        // Información del proyecto con estilo elegante (solo en primera página)
        doc.setFillColor(...lightAmber);
        doc.setDrawColor(...secondaryColor);
        doc.setLineWidth(0.5);
        doc.rect(margin, yPos, pageWidth - (margin * 2), 18, 'FD');

        yPos += 5;
        doc.setFontSize(9);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...darkGray);
        doc.text("PROYECTO:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.project || projectInfo.name || 'Proyecto', margin + 28, yPos);

        yPos += 5;
        doc.setFont('helvetica', 'bold');
        doc.text("UBICACIÓN:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.location || 'No especificada', margin + 28, yPos);

        yPos += 5;
        doc.setFont('helvetica', 'bold');
        doc.text("FECHA:", margin + 5, yPos);
        doc.setFont('helvetica', 'normal');
        doc.text(new Date(reportDate).toLocaleDateString('es-MX', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        }), margin + 28, yPos);

        yPos += 12;

        // Variables para control de columnas (simular libro abierto)
        let currentColumn = 0; // 0 = izquierda, 1 = derecha
        let leftY = yPos;
        let rightY = yPos;
        const columnMargin = 2;

        // Procesar cada nota en dos columnas
        for (const log of sortedLogs) {
            let logProcessed = false;

            while (!logProcessed) {
                // Determinar en qué columna colocar la nota
                const useLeftColumn = currentColumn === 0;
                const columnX = useLeftColumn ? margin : (margin + columnWidth + gutter);
                let currentY = useLeftColumn ? leftY : rightY;
                const noteStartY = currentY;

                // Verificar si necesitamos nueva página o cambiar de columna
                // Ajustar límite a 60mm para dar más espacio (antes era 100mm)
                if (currentY > pageHeight - 60) {
                    if (useLeftColumn && rightY <= pageHeight - 60) {
                        // Columna izquierda llena, cambiar a derecha
                        currentColumn = 1;
                        continue; // Reintentar en columna derecha
                    } else {
                        // Ambas columnas llenas o columna derecha llena, nueva página
                        addFooter(pageNum, totalPages);
                        doc.addPage('landscape');
                        pageNum++;
                        yPos = addHeader();
                        leftY = yPos;
                        rightY = yPos;
                        currentColumn = 0;
                        continue; // Reintentar en nueva página
                    }
                }

                // Extraer metadata y limpiar contenido
                const metadata = this.extractBitacoraMetadata(log.content);
                const cleanContent = this.getCleanContent(log.content);

                // Tarjeta de nota con diseño elegante
                const noteWidth = columnWidth - (columnMargin * 2);

                // Header de la nota con fondo de color
                doc.setFillColor(...primaryColor);
                doc.rect(columnX + columnMargin, currentY, noteWidth, 10, 'F');

                doc.setFontSize(9);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(255, 255, 255);
                doc.text(`FOLIO #${log.note_number || 'N/A'}`, columnX + columnMargin + 3, currentY + 6);

                doc.setFontSize(7);
                doc.setFont('helvetica', 'normal');
                const classification = (log.classification || 'Informe').toUpperCase();
                doc.text(classification, columnX + columnMargin + 35, currentY + 6);

                currentY += 12;

                // Asunto
                doc.setFontSize(10);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(...darkGray);
                const subjectLines = doc.splitTextToSize(log.subject || 'Sin asunto', noteWidth - 6);
                doc.text(subjectLines, columnX + columnMargin + 3, currentY);
                currentY += subjectLines.length * 5 + 3;

                // Línea decorativa
                doc.setLineWidth(0.2);
                doc.setDrawColor(200, 200, 200);
                doc.line(columnX + columnMargin + 3, currentY, columnX + noteWidth - columnMargin - 3, currentY);
                currentY += 3;

                // Contenido principal
                if (cleanContent) {
                    doc.setFontSize(8);
                    doc.setFont('helvetica', 'normal');
                    doc.setTextColor(51, 65, 85);
                    const contentLines = doc.splitTextToSize(cleanContent, noteWidth - 6);
                    doc.text(contentLines, columnX + columnMargin + 3, currentY);
                    currentY += contentLines.length * 4 + 3;
                }

                // Metadata adicional
                if (metadata && (metadata.weather || metadata.materials || metadata.personnel)) {
                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'bold');
                    doc.setTextColor(...primaryColor);
                    doc.text("INFO ADICIONAL:", columnX + columnMargin + 3, currentY);
                    currentY += 4;

                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'normal');
                    doc.setTextColor(51, 65, 85);

                    if (metadata.weather) {
                        doc.text(`• Clima: ${metadata.weather}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    if (metadata.materials) {
                        doc.text(`• Materiales: ${metadata.materials}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    if (metadata.personnel) {
                        doc.text(`• Personal: ${metadata.personnel}`, columnX + columnMargin + 5, currentY);
                        currentY += 4;
                    }
                    currentY += 2;
                }

                // Observaciones
                if (metadata && metadata.observations) {
                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'bold');
                    doc.setTextColor(139, 92, 246);
                    doc.text("OBSERVACIONES:", columnX + columnMargin + 3, currentY);
                    currentY += 4;

                    doc.setFontSize(7);
                    doc.setFont('helvetica', 'italic');
                    doc.setTextColor(71, 85, 105);
                    const obsLines = doc.splitTextToSize(metadata.observations, noteWidth - 6);
                    doc.text(obsLines, columnX + columnMargin + 5, currentY);
                    currentY += obsLines.length * 4 + 3;
                }

                // Footer de la nota con badges
                doc.setLineWidth(0.2);
                doc.setDrawColor(220, 220, 220);
                doc.line(columnX + columnMargin + 3, currentY, columnX + noteWidth - columnMargin - 3, currentY);
                currentY += 4;

                // Badges de información (más pequeños para caber)
                const badgeY = currentY;
                let badgeX = columnX + columnMargin + 3;

                // Badge de avance
                doc.setFillColor(...primaryColor);
                doc.rect(badgeX, badgeY, 22, 6, 'F');
                doc.setFontSize(6);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(255, 255, 255);
                doc.text(`${log.progress_percentage || 0}%`, badgeX + 1, badgeY + 4.5);
                badgeX += 24;

                // Badge de autor
                doc.setFillColor(139, 92, 246);
                doc.rect(badgeX, badgeY, 25, 6, 'F');
                doc.text(log.author_role || 'N/A', badgeX + 1, badgeY + 4.5);
                badgeX += 27;

                // Badge de estatus
                const statusColor = log.status === 'Cerrada' ? [34, 197, 94] : [251, 191, 36];
                doc.setFillColor(...statusColor);
                doc.rect(badgeX, badgeY, 20, 6, 'F');
                doc.text(log.status || 'Abierta', badgeX + 1, badgeY + 4.5);

                currentY += 9;

                // Dibujar borde de la tarjeta completa
                const noteCardHeight = currentY - noteStartY;
                doc.setFillColor(255, 255, 255);
                doc.setDrawColor(...secondaryColor);
                doc.setLineWidth(0.5);
                doc.rect(columnX + columnMargin, noteStartY, noteWidth, noteCardHeight, 'FD');

                // Actualizar posición Y de la columna correspondiente
                if (useLeftColumn) {
                    leftY = currentY + 5;
                    currentColumn = 1; // Cambiar a columna derecha para la próxima nota
                } else {
                    rightY = currentY + 5;
                    currentColumn = 0; // Cambiar a columna izquierda para la próxima nota
                }

                logProcessed = true; // Marcar como procesado
            }
        }

        // Footer final
        addFooter(pageNum, totalPages);

        // Devolver blob en lugar de descargar
        return doc.output('blob');
    }

    /**
     * Genera un reporte de diario tipo libro en PDF (solo texto, sin fotos)
     * Formato elegante tipo diario con firmas
     * @param {Object} projectInfo - Información del proyecto
     * @param {Array} diaryEntries - Lista de entradas del diario
     * @param {string} reportDate - Fecha del reporte
     * @param {Object} options - Opciones adicionales
     */
    static async generateDiaryReport(projectInfo, diaryEntries, reportDate, options = {}) {
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.width;
        const pageHeight = doc.internal.pageSize.height;
        const margin = 20;
        const contentWidth = pageWidth - (margin * 2);

        // Header elegante tipo libro
        doc.setFillColor(240, 240, 240);
        doc.rect(0, 0, pageWidth, 40, 'F');

        doc.setFontSize(18);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(0, 0, 0);
        doc.text("DIARIO DE OBRA", pageWidth / 2, 18, { align: 'center' });

        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(100, 100, 100);
        doc.text(projectInfo.project || projectInfo.name || 'Proyecto', pageWidth / 2, 28, { align: 'center' });

        doc.setFontSize(8);
        doc.text(`Generado el ${new Date(reportDate).toLocaleDateString('es-MX')}`, pageWidth / 2, 35, { align: 'center' });

        let yPos = 50;

        // Ordenar entradas por fecha (más antiguas primero, como un diario)
        const sortedEntries = [...diaryEntries].sort((a, b) => {
            const dateA = new Date(a.log_date || a.created_at);
            const dateB = new Date(b.log_date || b.created_at);
            return dateA - dateB;
        });

        // Procesar cada entrada del diario
        for (let i = 0; i < sortedEntries.length; i++) {
            const entry = sortedEntries[i];

            // Verificar si necesitamos nueva página
            if (yPos > pageHeight - 80) {
                doc.addPage();
                // Repetir header en nueva página
                doc.setFillColor(240, 240, 240);
                doc.rect(0, 0, pageWidth, 40, 'F');
                doc.setFontSize(18);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(0, 0, 0);
                doc.text("DIARIO DE OBRA", pageWidth / 2, 18, { align: 'center' });
                doc.setFontSize(10);
                doc.setFont('helvetica', 'normal');
                doc.setTextColor(100, 100, 100);
                doc.text(projectInfo.project || projectInfo.name || 'Proyecto', pageWidth / 2, 28, { align: 'center' });
                yPos = 50;
            }

            // Número de entrada y fecha
            doc.setFontSize(10);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(59, 130, 246); // Azul
            const entryDate = new Date(entry.log_date || entry.created_at);
            const dateStr = entryDate.toLocaleDateString('es-MX', {
                weekday: 'long',
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });
            doc.text(`ENTRADA #${entry.note_number || i + 1} - ${dateStr}`, margin, yPos);

            yPos += 8;

            // Línea decorativa
            doc.setLineWidth(0.5);
            doc.setDrawColor(200, 200, 200);
            doc.line(margin, yPos, pageWidth - margin, yPos);
            yPos += 5;

            // Contenido del diario
            if (entry.content) {
                doc.setFontSize(9);
                doc.setFont('helvetica', 'normal');
                doc.setTextColor(0, 0, 0);
                const contentLines = doc.splitTextToSize(entry.content, contentWidth);
                doc.text(contentLines, margin, yPos);
                yPos += contentLines.length * 4.5 + 5;
            }

            // Información del autor y firma
            yPos += 3;
            doc.setFontSize(7);
            doc.setFont('helvetica', 'normal');
            doc.setTextColor(100, 100, 100);

            const authorInfo = [];
            if (entry.authorName) authorInfo.push(entry.authorName);
            if (entry.authorRole) authorInfo.push(entry.authorRole);
            if (entry.authorSignature) authorInfo.push(`Firma: ${entry.authorSignature}`);

            if (authorInfo.length > 0) {
                doc.text(authorInfo.join(' • '), margin, yPos);
                yPos += 6;
            }

            // Línea separadora entre entradas
            if (i < sortedEntries.length - 1) {
                doc.setLineWidth(0.2);
                doc.setDrawColor(220, 220, 220);
                doc.line(margin, yPos, pageWidth - margin, yPos);
                yPos += 10;
            }
        }

        // Footer con información del proyecto
        const footerY = pageHeight - 25;
        doc.setFontSize(7);
        doc.setTextColor(150, 150, 150);
        doc.text(`Diario de Obra - ${projectInfo.project || projectInfo.name || 'Proyecto'}`, pageWidth / 2, footerY, { align: 'center' });
        doc.text(`Total de entradas: ${sortedEntries.length}`, pageWidth / 2, footerY + 5, { align: 'center' });

        // Guardar
        const fileName = `DIARIO_DE_OBRA_${projectInfo.project?.replace(/\s+/g, '_') || 'OBRA'}_${reportDate}.pdf`;
        doc.save(fileName);
    }
}

export default PDFReportService;

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { formatCurrency, numberToWords } from '../utils/format';
import { PDFTemplateService } from './PDFTemplateService';

export class PDFService {
    static exportBudget(projectInfo, items, total, subtotal, taxAmount) {
        const doc = new jsPDF();
        const primaryColor = [26, 35, 126]; // Dark Blue
        const secondaryColor = [69, 90, 100]; // Blue Grey

        // --- HEADER ---
        doc.setFillColor(...primaryColor);
        doc.rect(0, 0, 210, 35, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(18);
        doc.setFont('helvetica', 'bold');
        doc.text('PRESUPUESTO DE OBRA', 105, 18, { align: 'center' });
        doc.setFontSize(9);
        doc.setFont('helvetica', 'normal');
        doc.text('DOCUMENTO TÉCNICO', 105, 25, { align: 'center' });

        // --- PROJECT INFO ---
        const startY = 45;
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);

        doc.setFont('helvetica', 'bold');
        doc.text('PROYECTO:', 14, startY);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.project || '---', 40, startY);

        doc.setFont('helvetica', 'bold');
        doc.text('CLIENTE:', 14, startY + 6);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.client || '---', 40, startY + 6);

        const currentDate = new Date();
        const options = { day: 'numeric', month: 'long', year: 'numeric' };
        const formattedDate = currentDate.toLocaleDateString('es-MX', options);
        const locationText = projectInfo.location || 'México';
        const fullLocationAndDateText = `${locationText} a ${formattedDate}`;

        doc.setFont('helvetica', 'normal');
        doc.text(fullLocationAndDateText, 140, startY, { maxWidth: 60 });

        // --- TABLE ---
        const groupedItems = items.reduce((acc, item) => {
            const cat = item.category || 'Sin Categoría';
            if (!acc[cat]) acc[cat] = [];
            acc[cat].push(item);
            return acc;
        }, {});

        const tableBody = [];
        let globalIndex = 1;

        Object.keys(groupedItems).forEach(category => {
            tableBody.push([{
                content: category.toUpperCase(),
                colSpan: 7,
                styles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold', halign: 'left' }
            }]);

            groupedItems[category].forEach(item => {
                tableBody.push([
                    globalIndex++,
                    `C-${globalIndex.toString().padStart(3, '0')}`,
                    item.description,
                    item.unit,
                    item.quantity,
                    formatCurrency(item.unitPrice),
                    formatCurrency(item.quantity * item.unitPrice)
                ]);
            });
        });

        autoTable(doc, {
            head: [['#', 'CLAVE', 'CONCEPTO', 'UND', 'CANT', 'P.U.', 'IMPORTE']],
            body: tableBody,
            startY: 60,
            theme: 'grid',
            headStyles: { fillColor: primaryColor, textColor: 255, fontStyle: 'bold', halign: 'center', fontSize: 8 },
            columnStyles: {
                0: { halign: 'center', cellWidth: 8 },
                1: { halign: 'center', cellWidth: 15 },
                2: { halign: 'left' },
                3: { halign: 'center', cellWidth: 12 },
                4: { halign: 'right', cellWidth: 15 },
                5: { halign: 'right', cellWidth: 22 },
                6: { halign: 'right', cellWidth: 25, fontStyle: 'bold' }
            },
            styles: { fontSize: 8, cellPadding: 2, valign: 'middle' }
        });

        // --- TOTALS ---
        const finalY = doc.lastAutoTable.finalY + 10;
        doc.setFontSize(8);
        doc.setFont('helvetica', 'bold');
        doc.text(`IMPORTE CON LETRA: (${numberToWords(total)})`, 14, finalY);

        const totalsX = 140;
        doc.setFontSize(9);
        doc.setTextColor(...secondaryColor);
        doc.text('SUBTOTAL:', totalsX, finalY + 10);
        doc.setTextColor(0, 0, 0);
        doc.text(formatCurrency(subtotal), 195, finalY + 10, { align: 'right' });

        doc.setTextColor(...secondaryColor);
        doc.text(`IVA (${projectInfo.taxRate}%):`, totalsX, finalY + 16);
        doc.setTextColor(0, 0, 0);
        doc.text(formatCurrency(taxAmount), 195, finalY + 16, { align: 'right' });

        doc.setDrawColor(0, 0, 0);
        doc.line(totalsX, finalY + 20, 195, finalY + 20);

        doc.setFontSize(11);
        doc.setFont('helvetica', 'bold');
        doc.text('TOTAL:', totalsX, finalY + 26);
        doc.text(formatCurrency(total), 195, finalY + 26, { align: 'right' });

        // --- SIGNATURES ---
        const pageHeight = doc.internal.pageSize.height;
        const signatureY = pageHeight - 40;
        doc.setDrawColor(150);
        doc.line(40, signatureY, 90, signatureY);
        doc.line(120, signatureY, 170, signatureY);
        doc.setFontSize(8);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(100);
        doc.text('ELABORÓ', 65, signatureY + 5, { align: 'center' });
        doc.text('AUTORIZÓ', 145, signatureY + 5, { align: 'center' });

        doc.save(`Presupuesto_${projectInfo.project.replace(/\s+/g, '_')}.pdf`);
    }

    static async generateBudgetPDF(doc, { projectInfo, items, subtotal, indirectCosts = 0, profit = 0, tax, total, technicalDescription = '', isPreview = false }) {
        // Cargar plantilla activa
        const template = PDFTemplateService.getActiveTemplate();

        // Usar valores de la plantilla o valores por defecto
        const primaryColor = template?.headerColor || [26, 35, 126]; // Dark Blue por defecto
        const secondaryColor = [69, 90, 100]; // Blue Grey
        const headerTextColor = template?.headerTextColor || [255, 255, 255]; // Blanco por defecto
        const headerTextSize = template?.headerTextSize || 18; // Tamaño del título
        const headerSubtextSize = template?.headerSubtextSize || 9; // Tamaño del subtítulo
        const headerText = template?.headerText || 'PRESUPUESTO DE OBRA';
        const headerSubtext = template?.headerSubtext || 'DOCUMENTO TÉCNICO';
        const showHeader = template?.showHeader !== false;

        // --- HEADER ---
        if (showHeader) {
            const headerHeight = 35;
            const headerCenterY = headerHeight / 2;

            doc.setFillColor(...primaryColor);
            doc.rect(0, 0, 210, headerHeight, 'F');

            // Logo si existe
            let hasLogo = false;
            let logoX = 0;
            let logoY = 0;
            let logoWidth = 0;
            let logoHeight = 0;

            if (template?.logoUrl) {
                try {
                    const logoSize = template.logoSize || { width: 40, height: 40 };
                    // Limitar tamaño máximo del logo para que no ocupe todo el header
                    const maxLogoWidth = 50;
                    const maxLogoHeight = 25;
                    logoWidth = Math.min(logoSize.width, maxLogoWidth);
                    logoHeight = Math.min(logoSize.height, maxLogoHeight);

                    logoY = headerCenterY - (logoHeight / 2);

                    if (template.logoPosition === 'left') {
                        logoX = 5; // Margen izquierdo más pequeño para acercar el logo
                    } else if (template.logoPosition === 'center') {
                        logoX = 105 - (logoWidth / 2);
                    } else if (template.logoPosition === 'right') {
                        logoX = 205 - logoWidth; // Margen derecho más pequeño
                    }

                    // Detectar formato de imagen
                    let imageFormat = 'PNG';
                    if (template.logoUrl.startsWith('data:image/jpeg') || template.logoUrl.startsWith('data:image/jpg')) {
                        imageFormat = 'JPEG';
                    } else if (template.logoUrl.startsWith('data:image/png')) {
                        imageFormat = 'PNG';
                    }

                    // Agregar imagen
                    doc.addImage(
                        template.logoUrl,
                        imageFormat,
                        logoX,
                        logoY,
                        logoWidth,
                        logoHeight
                    );
                    hasLogo = true;
                } catch (error) {
                    console.error('Error adding logo to PDF:', error);
                    // Continuar sin logo si hay error
                }
            }

            // Calcular posición del texto según la posición del logo
            // Siempre centrar el texto en toda la página para mejor balance visual
            let textX = 105; // Centro de la página (210mm / 2)
            let textAlign = 'center';

            // El texto siempre se centra en toda la página, el logo simplemente se posiciona
            // Esto crea un mejor balance visual

            // Aplicar color del texto
            doc.setTextColor(...headerTextColor);

            // Calcular posiciones verticales - siempre centrado verticalmente en el header
            let titleY, subtextY;

            // Calcular altura aproximada del texto en mm
            // jsPDF usa puntos, donde 1 punto ≈ 0.352778mm, pero para posicionamiento vertical
            // usamos un factor más simple basado en el tamaño de fuente
            const titleLineHeight = headerTextSize * 0.4; // Factor de altura de línea
            const subtextLineHeight = headerSubtextSize * 0.4;
            const spacing = 1.5; // Espacio entre título y subtítulo en mm

            if (hasLogo && template.logoPosition === 'center') {
                // Logo en centro: texto arriba del logo
                titleY = headerCenterY - (logoHeight / 2) - spacing - subtextLineHeight;
                subtextY = titleY + titleLineHeight + spacing;
            } else {
                // Logo a los lados o sin logo: texto centrado verticalmente
                const totalTextHeight = titleLineHeight + spacing + subtextLineHeight;
                titleY = headerCenterY - (totalTextHeight / 2) + (titleLineHeight / 2);
                subtextY = titleY + titleLineHeight + spacing;
            }

            // Título con tamaño personalizado
            doc.setFontSize(headerTextSize);
            doc.setFont('helvetica', 'bold');
            doc.text(headerText, textX, titleY, { align: textAlign });

            // Subtítulo con tamaño personalizado
            doc.setFontSize(headerSubtextSize);
            doc.setFont('helvetica', 'normal');
            doc.text(headerSubtext, textX, subtextY, { align: textAlign });
        }

        // --- GENERAR NÚMERO DE PRESUPUESTO AUTOMÁTICO ---
        const getNextBudgetNumber = () => {
            const key = 'presugenius_last_budget_number';
            const lastNumber = parseInt(localStorage.getItem(key) || '0', 10);

            if (isPreview) {
                // En vista previa, mostramos el siguiente número pero NO lo guardamos
                return (lastNumber + 1).toString().padStart(2, '0');
            } else {
                // En descarga real, incrementamos y guardamos
                const nextNumber = lastNumber + 1;
                localStorage.setItem(key, nextNumber.toString());
                return nextNumber.toString().padStart(2, '0');
            }
        };
        const budgetNumber = getNextBudgetNumber();

        // --- PROJECT INFO ---
        const startY = 45;
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);

        doc.setFont('helvetica', 'bold');
        doc.text('PROYECTO:', 14, startY);
        doc.setFont('helvetica', 'normal');
        const projectText = projectInfo.project || '---';
        doc.text(projectText, 40, startY, { maxWidth: 90 });

        doc.setFont('helvetica', 'bold');
        doc.text('CLIENTE:', 14, startY + 6);
        doc.setFont('helvetica', 'normal');
        // Ajustar ancho máximo para textos largos
        const clientText = projectInfo.client || '---';
        doc.text(clientText, 40, startY + 6, { maxWidth: 90 });

        // Fecha y Ubicación sin etiquetas, solo valores, más a la derecha
        const rightMargin = 10; // Margen derecho
        doc.setFont('helvetica', 'normal');
        const currentDate = new Date();
        const options = { day: 'numeric', month: 'long', year: 'numeric' };
        const formattedDate = currentDate.toLocaleDateString('es-MX', options); // Formato "3 de febrero de 2026"

        const locationText = projectInfo.location || 'México';
        const fullLocationAndDateText = `${locationText} a ${formattedDate}`;
        const maxRightWidth = 210 - 165 - rightMargin; // Ancho disponible (35mm)

        // Alinear a la derecha para que textos largos no se salgan
        doc.text(fullLocationAndDateText, 210 - rightMargin, startY, { align: 'right', maxWidth: maxRightWidth });

        // Número de presupuesto en letras pequeñas debajo de la ubicación
        doc.setFontSize(7);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(100, 100, 100); // Color gris
        doc.text(`Presupuesto No. ${budgetNumber}`, 210 - rightMargin, startY + 12, { align: 'right' });

        // --- TABLE ---
        const groupedItems = items.reduce((acc, item) => {
            const cat = item.category || 'Sin Categoría';
            if (!acc[cat]) acc[cat] = [];
            acc[cat].push(item);
            return acc;
        }, {});

        const tableBody = [];
        let globalIndex = 1;

        Object.keys(groupedItems).forEach(category => {
            tableBody.push([{
                content: category.toUpperCase(),
                colSpan: 7,
                styles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold', halign: 'left' }
            }]);

            groupedItems[category].forEach(item => {
                let description = item.description;
                // Add source verification if available
                if (item.calculation_basis) {
                    // Check common keywords for offical sources to highlight them
                    const isOfficial = /neodata|catálogo|base maestra|oficial/i.test(item.calculation_basis);
                    const sourceText = item.calculation_basis.length > 50
                        ? item.calculation_basis.substring(0, 47) + '...'
                        : item.calculation_basis;

                    description += `\n(Ref: ${sourceText})`;
                }

                tableBody.push([
                    globalIndex++,
                    `C-${globalIndex.toString().padStart(3, '0')}`,
                    description,
                    item.unit,
                    item.quantity,
                    formatCurrency(item.unitPrice),
                    formatCurrency(item.quantity * item.unitPrice)
                ]);
            });
        });

        autoTable(doc, {
            head: [['#', 'CLAVE', 'CONCEPTO', 'UND', 'CANT', 'P.U.', 'IMPORTE']],
            body: tableBody,
            startY: 60,
            theme: 'grid',
            headStyles: { fillColor: primaryColor, textColor: 255, fontStyle: 'bold', halign: 'center', fontSize: 8 },
            columnStyles: {
                0: { halign: 'center', cellWidth: 8 },
                1: { halign: 'center', cellWidth: 15 },
                2: { halign: 'left' },
                3: { halign: 'center', cellWidth: 12 },
                4: { halign: 'right', cellWidth: 15 },
                5: { halign: 'right', cellWidth: 22 },
                6: { halign: 'right', cellWidth: 25, fontStyle: 'bold' }
            },
            styles: { fontSize: 8, cellPadding: 2, valign: 'middle' }
        });

        // --- TOTALS & SIGNATURES BLOCK ---
        const pageHeight = doc.internal.pageSize.height;
        const signatureHeight = 40;
        const signatureY = pageHeight - signatureHeight;

        // Calculate required space for Totals
        let requiredHeight = 20; // Initial padding + Amount in text
        requiredHeight += 6; // Subtotal
        if (indirectCosts > 0) requiredHeight += 6;
        if (profit > 0) requiredHeight += 6;
        requiredHeight += 6; // IVA
        requiredHeight += 10; // Total (with line)
        requiredHeight += 10; // Buffer before signatures

        // Initialize currentY safely
        let currentY = 20; // Default fallback
        const lastTableY = doc.lastAutoTable ? doc.lastAutoTable.finalY : 20;

        // Check if we need a new page
        if (lastTableY + requiredHeight > signatureY) {
            doc.addPage();
            currentY = 20; // Start fresh on new page
        } else {
            currentY = lastTableY + 10;
        }

        doc.setFontSize(8);
        doc.setFont('helvetica', 'bold');
        doc.text(`IMPORTE CON LETRA: (${numberToWords(total)})`, 14, currentY);

        // Align Totals Frame
        const totalsX = 130; // Moved slightly left for better alignment
        const valueX = 195;

        currentY += 8; // Spacing after text amount

        doc.setFontSize(9);

        // Helper for rows
        const addTotalRow = (label, value, isBold = false) => {
            doc.setTextColor(...secondaryColor);
            doc.setFont('helvetica', isBold ? 'bold' : 'bold'); // Labels always boldish
            doc.text(label, totalsX, currentY);

            doc.setTextColor(0, 0, 0);
            doc.setFont('helvetica', isBold ? 'bold' : 'normal');
            doc.text(formatCurrency(value), valueX, currentY, { align: 'right' });
            currentY += 6;
        };

        addTotalRow('SUBTOTAL:', subtotal);

        if (indirectCosts > 0) {
            addTotalRow(`INDIRECTOS (${projectInfo.indirect_percentage || 0}%):`, indirectCosts);
        }

        if (profit > 0) {
            addTotalRow(`UTILIDAD (${projectInfo.profit_percentage || 0}%):`, profit);
        }

        addTotalRow(`IVA (${projectInfo.taxRate || 0}%):`, tax);

        // Line for Total
        doc.setDrawColor(0, 0, 0);
        doc.setLineWidth(0.5);
        doc.line(totalsX, currentY - 2, valueX, currentY - 2);
        currentY += 2;

        doc.setFontSize(11);
        doc.setFont('helvetica', 'bold');
        doc.text('TOTAL:', totalsX, currentY);
        doc.text(formatCurrency(total), valueX, currentY, { align: 'right' });

        // --- SIGNATURES ---
        // Always at bottom of the page
        doc.setDrawColor(150);
        doc.setLineWidth(0.2);
        doc.line(40, signatureY, 90, signatureY);
        doc.line(120, signatureY, 170, signatureY);

        doc.setFontSize(8);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(100);
        doc.text('ELABORÓ', 65, signatureY + 5, { align: 'center' });
        doc.text('AUTORIZÓ', 145, signatureY + 5, { align: 'center' });

        // Footer text si está configurado en la plantilla
        if (template?.footerText) {
            doc.setFontSize(7);
            doc.setTextColor(150);
            doc.text(template.footerText, 105, pageHeight - 10, { align: 'center' });
        }
    }

    static exportMaterials(projectInfo, materials) {
        const doc = new jsPDF();
        const primaryColor = [230, 81, 0]; // Orange for Materials

        // --- HEADER ---
        doc.setFillColor(...primaryColor);
        doc.rect(0, 0, 210, 35, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(18);
        doc.setFont('helvetica', 'bold');
        doc.text('EXPLOSIÓN DE INSUMOS', 105, 18, { align: 'center' });
        doc.setFontSize(9);
        doc.setFont('helvetica', 'normal');
        doc.text('LISTADO DE MATERIALES REQUERIDOS', 105, 25, { align: 'center' });

        // --- PROJECT INFO ---
        const startY = 45;
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        doc.setFont('helvetica', 'bold');
        doc.text('PROYECTO:', 14, startY);
        doc.setFont('helvetica', 'normal');
        doc.text(projectInfo.project || '---', 40, startY);

        const currentDate = new Date();
        const options = { day: 'numeric', month: 'long', year: 'numeric' };
        const formattedDate = currentDate.toLocaleDateString('es-MX', options);

        doc.setFont('helvetica', 'bold');
        doc.text('FECHA:', 140, startY);
        doc.setFont('helvetica', 'normal');
        doc.text(formattedDate, 160, startY);

        // --- TABLE ---
        // --- TABLE ---
        const tableBody = materials.map(mat => [
            mat.material,
            mat.unit,
            mat.quantity,
            formatCurrency(mat.unitPrice),
            formatCurrency(mat.quantity * mat.unitPrice),
            mat.notes || ''
        ]);

        const totalMaterials = materials.reduce((sum, m) => sum + (m.quantity * m.unitPrice), 0);

        autoTable(doc, {
            head: [['MATERIAL', 'UND', 'CANT', 'P.U. EST.', 'TOTAL', 'NOTAS']],
            body: tableBody,
            startY: 55,
            theme: 'grid',
            headStyles: { fillColor: primaryColor, textColor: 255, fontStyle: 'bold', halign: 'center', fontSize: 8 },
            columnStyles: {
                0: { halign: 'left', fontStyle: 'bold' }, // Material
                1: { halign: 'center' }, // Unit
                2: { halign: 'right' }, // Quantity
                3: { halign: 'right' }, // Unit Price
                4: { halign: 'right', fontStyle: 'bold' }, // Total
                5: { halign: 'left', fontSize: 7 } // Notes
            },
            styles: { fontSize: 8, cellPadding: 2, valign: 'middle' }
        });

        // --- TOTAL ---
        const finalY = doc.lastAutoTable.finalY + 10;
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        doc.text('TOTAL ESTIMADO DE MATERIALES:', 100, finalY); // Moved left to avoid overlap
        doc.text(formatCurrency(totalMaterials), 195, finalY, { align: 'right' });

        doc.save(`Insumos_${projectInfo.project.replace(/\s+/g, '_')}.pdf`);
    }
}

/**
 * PDFTemplateService
 * Maneja las plantillas de PDF para presupuestos
 * Guarda en localStorage y permite sincronizar con Supabase
 */

import { generateId } from '../utils/helpers';

const STORAGE_KEY = 'presugenius_pdf_templates';
const ACTIVE_TEMPLATE_KEY = 'presugenius_active_pdf_template';

export class PDFTemplateService {
    /**
     * Obtener todas las plantillas
     * @returns {Array} Lista de plantillas
     */
    static getTemplates() {
        try {
            const stored = localStorage.getItem(STORAGE_KEY);
            return stored ? JSON.parse(stored) : [];
        } catch (error) {
            console.error('Error loading PDF templates:', error);
            return [];
        }
    }

    /**
     * Obtener la plantilla activa
     * @returns {Object|null} Plantilla activa o null
     */
    static getActiveTemplate() {
        try {
            const activeId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
            if (!activeId) return null;

            const templates = this.getTemplates();
            return templates.find(t => t.id === activeId) || null;
        } catch (error) {
            console.error('Error loading active template:', error);
            return null;
        }
    }

    /**
     * Guardar una nueva plantilla
     * @param {Object} templateData - Datos de la plantilla
     * @returns {Object} Plantilla guardada
     */
    static saveTemplate(templateData) {
        try {
            const templates = this.getTemplates();
            const now = new Date().toISOString();

            const template = {
                id: templateData.id || generateId(),
                name: templateData.name || 'Plantilla sin nombre',
                headerColor: templateData.headerColor || null, // null = sin color, o array [r, g, b]
                headerTextColor: templateData.headerTextColor || [255, 255, 255], // Color del texto [r, g, b]
                headerTextSize: templateData.headerTextSize || 18, // Tamaño del título en pt
                headerSubtextSize: templateData.headerSubtextSize || 9, // Tamaño del subtítulo en pt
                logoUrl: templateData.logoUrl || null, // URL base64 o blob URL
                logoPosition: templateData.logoPosition || 'left', // 'left', 'center', 'right'
                logoSize: templateData.logoSize || { width: 40, height: 40 }, // mm
                showHeader: templateData.showHeader !== false, // true por defecto
                headerText: templateData.headerText || 'PRESUPUESTO DE OBRA',
                headerSubtext: templateData.headerSubtext || 'DOCUMENTO TÉCNICO',
                footerText: templateData.footerText || '',
                createdAt: templateData.createdAt || now,
                updatedAt: now,
                isActive: templateData.isActive || false
            };

            // Si es la plantilla activa, actualizar la referencia
            // IMPORTANTE: Solo activar si explícitamente se indica isActive = true
            if (template.isActive === true) {
                localStorage.setItem(ACTIVE_TEMPLATE_KEY, template.id);
                // Desactivar otras plantillas
                templates.forEach(t => {
                    if (t.id !== template.id) t.isActive = false;
                });
            } else {
                // Si no está activa, asegurarse de que no esté en la referencia activa
                const currentActiveId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
                if (currentActiveId === template.id) {
                    // Esta plantilla estaba activa pero ahora no lo está, limpiar referencia
                    localStorage.removeItem(ACTIVE_TEMPLATE_KEY);
                }
            }

            // Actualizar o agregar
            const index = templates.findIndex(t => t.id === template.id);
            if (index >= 0) {
                templates[index] = template;
            } else {
                templates.push(template);
            }

            localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
            return template;
        } catch (error) {
            console.error('Error saving PDF template:', error);
            throw new Error('No se pudo guardar la plantilla');
        }
    }

    /**
     * Eliminar una plantilla
     * @param {string} templateId - ID de la plantilla
     */
    static deleteTemplate(templateId) {
        try {
            const templates = this.getTemplates();
            const filtered = templates.filter(t => t.id !== templateId);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));

            // Si era la activa, limpiar referencia
            const activeId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
            if (activeId === templateId) {
                localStorage.removeItem(ACTIVE_TEMPLATE_KEY);
            }
        } catch (error) {
            console.error('Error deleting template:', error);
            throw new Error('No se pudo eliminar la plantilla');
        }
    }

    /**
     * Establecer una plantilla como activa
     * @param {string} templateId - ID de la plantilla
     */
    static setActiveTemplate(templateId) {
        try {
            const templates = this.getTemplates();

            // Desactivar todas
            templates.forEach(t => t.isActive = false);

            // Activar la seleccionada
            const template = templates.find(t => t.id === templateId);
            if (template) {
                template.isActive = true;
                localStorage.setItem(ACTIVE_TEMPLATE_KEY, templateId);
                localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
                return template;
            }
            return null;
        } catch (error) {
            console.error('Error setting active template:', error);
            throw new Error('No se pudo activar la plantilla');
        }
    }

    /**
     * Convertir imagen a base64
     * @param {File} file - Archivo de imagen
     * @returns {Promise<string>} Base64 string
     */
    static async imageToBase64(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => {
                const base64 = reader.result;
                resolve(base64);
            };
            reader.onerror = reject;
            reader.readAsDataURL(file);
        });
    }

    /**
     * Validar plantilla
     * @param {Object} template - Plantilla a validar
     * @returns {{valid: boolean, errors: string[]}}
     */
    static validateTemplate(template) {
        const errors = [];

        if (!template.name || template.name.trim() === '') {
            errors.push('El nombre de la plantilla es requerido');
        }

        if (template.headerColor && !Array.isArray(template.headerColor)) {
            errors.push('El color del header debe ser un array [r, g, b]');
        }

        if (template.headerColor && template.headerColor.length !== 3) {
            errors.push('El color del header debe tener 3 valores (RGB)');
        }

        if (template.logoUrl && !template.logoUrl.startsWith('data:image')) {
            errors.push('La URL del logo debe ser una imagen en base64');
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }
}

