import React from 'react';

/**
 * Renderiza texto con formato markdown básico a elementos React
 * Soporta: **negrita**, listas numeradas (1. 2. 3.), listas con viñetas (- *), saltos de línea
 */
export function renderMarkdown(text) {
    if (!text || typeof text !== 'string') return null;

    // Dividir por líneas
    const lines = text.split('\n');
    const elements = [];
    let inList = false;
    let listItems = [];
    let listType = null;
    let keyCounter = 0;

    const closeList = () => {
        if (inList && listItems.length > 0) {
            if (listType === 'ordered') {
                elements.push(
                    <ol key={`list-${keyCounter++}`} className="list-decimal list-inside space-y-1 my-2 ml-4">
                        {listItems.map((item, idx) => (
                            <li key={idx} className="ml-2">{renderInlineMarkdown(item)}</li>
                        ))}
                    </ol>
                );
            } else {
                elements.push(
                    <ul key={`list-${keyCounter++}`} className="list-disc list-inside space-y-1 my-2 ml-4">
                        {listItems.map((item, idx) => (
                            <li key={idx} className="ml-2">{renderInlineMarkdown(item)}</li>
                        ))}
                    </ul>
                );
            }
            listItems = [];
            inList = false;
            listType = null;
        }
    };

    lines.forEach((line, index) => {
        const trimmedLine = line.trim();

        // Lista numerada (1. 2. 3.)
        if (/^\d+\.\s/.test(trimmedLine)) {
            if (inList && listType !== 'ordered') {
                closeList();
            }
            inList = true;
            listType = 'ordered';
            const itemText = trimmedLine.replace(/^\d+\.\s/, '');
            listItems.push(itemText);
            return;
        }

        // Lista con viñetas (- * •)
        if (/^[-*•]\s/.test(trimmedLine)) {
            if (inList && listType !== 'unordered') {
                closeList();
            }
            inList = true;
            listType = 'unordered';
            const itemText = trimmedLine.replace(/^[-*•]\s/, '');
            listItems.push(itemText);
            return;
        }

        // Si hay una lista acumulada y esta línea no es parte de la lista
        if (inList) {
            closeList();
        }

        // Línea vacía
        if (trimmedLine.length === 0) {
            if (index > 0 && index < lines.length - 1 && elements.length > 0) {
                elements.push(<br key={`br-${keyCounter++}`} />);
            }
            return;
        }

        // Párrafo normal
        elements.push(
            <p key={`p-${keyCounter++}`} className="my-1.5 leading-relaxed">
                {renderInlineMarkdown(trimmedLine)}
            </p>
        );
    });

    // Cerrar lista si quedó abierta
    closeList();

    return elements.length > 0 ? <>{elements}</> : <p>{text}</p>;
}

/**
 * Renderiza markdown inline (negritas, código, etc.)
 */
function renderInlineMarkdown(text) {
    if (!text || typeof text !== 'string') return null;

    const result = [];
    let remainingText = text;
    let keyCounter = 0;

    // Procesar mientras haya texto
    while (remainingText.length > 0) {
        // Buscar próxima negrita
        const boldMatch = remainingText.match(/\*\*([^*]+?)\*\*/);

        // Buscar próximo código
        const codeMatch = remainingText.match(/`([^`]+)`/);

        // Determinar qué viene primero
        let nextIndex = remainingText.length;
        let nextType = null;
        let nextContent = null;

        if (boldMatch && boldMatch.index !== undefined) {
            if (boldMatch.index < nextIndex) {
                nextIndex = boldMatch.index;
                nextType = 'bold';
                nextContent = boldMatch[1];
            }
        }

        if (codeMatch && codeMatch.index !== undefined) {
            if (codeMatch.index < nextIndex) {
                nextIndex = codeMatch.index;
                nextType = 'code';
                nextContent = codeMatch[1];
            }
        }

        // Si encontramos un formato
        if (nextType) {
            // Agregar texto previo al formato
            if (nextIndex > 0) {
                const beforeText = remainingText.substring(0, nextIndex);
                if (beforeText) {
                    result.push(<span key={`text-${keyCounter++}`}>{beforeText}</span>);
                }
            }

            // Procesar el formato encontrado
            if (nextType === 'bold') {
                result.push(
                    <strong key={`bold-${keyCounter++}`} className="font-semibold">
                        {nextContent}
                    </strong>
                );
                remainingText = remainingText.substring(nextIndex + boldMatch[0].length);
            } else if (nextType === 'code') {
                result.push(
                    <code
                        key={`code-${keyCounter++}`}
                        className="bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded text-xs font-mono"
                    >
                        {nextContent}
                    </code>
                );
                remainingText = remainingText.substring(nextIndex + codeMatch[0].length);
            }
        } else {
            // No hay más formato, agregar el resto del texto y terminar
            if (remainingText) {
                result.push(<span key={`text-${keyCounter++}`}>{remainingText}</span>);
            }
            break;
        }
    }

    return result.length > 0 ? <>{result}</> : text;
}

/**
 * SecurityUtils
 * Universal Encryption/Decryption using Web Crypto API (Node.js 19+ / Modern Browsers)
 */

export class SecurityUtils {
    // Get the master key from env
    static getMasterKey() {
        if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_APP_SECRET_KEY) {
            return import.meta.env.VITE_APP_SECRET_KEY;
        }
        if (typeof process !== 'undefined' && process.env && process.env.VITE_APP_SECRET_KEY) {
            return process.env.VITE_APP_SECRET_KEY;
        }
        console.error('CRITICAL: VITE_APP_SECRET_KEY is missing. Encryption will fail.');
        return null;
    }

    /**
     * Encrypts a string value
     * @param {string} text - The plain text to encrypt
     * @returns {Promise<Object>} - The encrypted data { ciphertext, iv, salt } (all base64)
     */
    static async encrypt(text) {
        if (!text) return null;
        const password = this.getMasterKey();
        if (!password) throw new Error('Encryption key missing');

        const crypto = await this.getCryptoSubtle();
        const encoder = new TextEncoder();

        // 1. Generate random salt
        const salt = this.getRandomValues(new Uint8Array(16));

        // 2. Import password
        const keyMaterial = await crypto.importKey(
            "raw",
            encoder.encode(password),
            { name: "PBKDF2" },
            false,
            ["deriveKey"]
        );

        // 3. Derive key
        const key = await crypto.deriveKey(
            {
                name: "PBKDF2",
                salt: salt,
                iterations: 100000,
                hash: "SHA-256"
            },
            keyMaterial,
            { name: "AES-GCM", length: 256 },
            true,
            ["encrypt", "decrypt"]
        );

        // 4. Generate IV
        const iv = this.getRandomValues(new Uint8Array(12));

        // 5. Encrypt
        const encodedData = encoder.encode(text);
        const encryptedBuffer = await crypto.encrypt(
            { name: "AES-GCM", iv: iv },
            key,
            encodedData
        );

        // 6. Return as Base64
        return {
            ciphertext: this.arrayBufferToBase64(encryptedBuffer),
            iv: this.arrayBufferToBase64(iv),
            salt: this.arrayBufferToBase64(salt),
            v: 1 // version
        };
    }

    /**
     * Decrypts an encrypted object
     * @param {Object} encryptedData - { ciphertext, iv, salt }
     * @returns {Promise<string>} - The decrypted text
     */
    static async decrypt(encryptedData) {
        if (!encryptedData || !encryptedData.ciphertext || !encryptedData.iv || !encryptedData.salt) {
            return null;
        }

        const password = this.getMasterKey();
        if (!password) throw new Error('Encryption key missing');

        const crypto = await this.getCryptoSubtle();
        const decoder = new TextDecoder();
        const encoder = new TextEncoder();

        // 1. Convert Base64 back to buffers
        const salt = this.base64ToArrayBuffer(encryptedData.salt);
        const iv = this.base64ToArrayBuffer(encryptedData.iv);
        const ciphertext = this.base64ToArrayBuffer(encryptedData.ciphertext);

        // 2. Import password
        const keyMaterial = await crypto.importKey(
            "raw",
            encoder.encode(password),
            { name: "PBKDF2" },
            false,
            ["deriveKey"]
        );

        // 3. Derive key (must match encryption)
        const key = await crypto.deriveKey(
            {
                name: "PBKDF2",
                salt: salt,
                iterations: 100000,
                hash: "SHA-256"
            },
            keyMaterial,
            { name: "AES-GCM", length: 256 },
            true,
            ["encrypt", "decrypt"]
        );

        // 4. Decrypt
        try {
            const decryptedBuffer = await crypto.decrypt(
                { name: "AES-GCM", iv: iv },
                key,
                ciphertext
            );
            return decoder.decode(decryptedBuffer);
        } catch (e) {
            console.error('Decryption failed. Wrong key or corrupted data.', e);
            return null;
        }
    }

    // --- Helpers ---

    static async getCryptoSubtle() {
        if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.subtle) {
            return globalThis.crypto.subtle;
        }
        // Node.js fallback for older versions (though Node 19+ has global crypto)
        try {
            // Dynamic import for Node environment
            const cryptoModule = await import('node:crypto');
            return cryptoModule.webcrypto.subtle;
        } catch (e) {
            throw new Error('Web Crypto API not supported in this environment');
        }
    }

    static getRandomValues(typedArray) {
        if (typeof globalThis !== 'undefined' && globalThis.crypto) {
            return globalThis.crypto.getRandomValues(typedArray);
        }
        // Very basic node fallback if global crypto missing but required logic runs there
        // Note: This shouldn't be reached in valid Node environments
        return typedArray;
    }

    static arrayBufferToBase64(buffer) {
        if (typeof window !== 'undefined') {
            // Browser
            let binary = '';
            const bytes = new Uint8Array(buffer);
            const len = bytes.byteLength;
            for (let i = 0; i < len; i++) {
                binary += String.fromCharCode(bytes[i]);
            }
            return window.btoa(binary);
        } else {
            // Node
            return Buffer.from(buffer).toString('base64');
        }
    }

    static base64ToArrayBuffer(base64) {
        if (typeof window !== 'undefined') {
            // Browser
            const binary_string = window.atob(base64);
            const len = binary_string.length;
            const bytes = new Uint8Array(len);
            for (let i = 0; i < len; i++) {
                bytes[i] = binary_string.charCodeAt(i);
            }
            return bytes.buffer;
        } else {
            // Node
            const buf = Buffer.from(base64, 'base64');
            return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
        }
    }
}

