        // Intentar dividir por tabs o múltiples espacios
        const columns = line.split(/\t+/).map(col => col.trim());
        
        if (columns.length > 1) {
            // Formatear como CSV
            const csvLine = columns.map(col => {
                // Escapar comillas y envolver si contiene comas
