        const dataBuffer = fs.readFileSync(pdfPath);
        let debugLog = "";

        let pdfPkg;
        try {
            pdfPkg = require('pdf-parse');
            debugLog += "Required 'pdf-parse' successfully.\n";
        } catch (e) {
            debugLog += `Failed to require 'pdf-parse': ${e.message}\n`;
        }

        if (pdfPkg && pdfPkg.PDFParse) {
            try {
                debugLog += "Instantiating new pdfPkg.PDFParse(buffer)...\n";
                const instance = new pdfPkg.PDFParse(dataBuffer);
                debugLog += `Instance created. Keys: ${Object.keys(instance).join(', ')}\n`;
                debugLog += `Prototype keys: ${Object.getOwnPropertyNames(Object.getPrototypeOf(instance)).join(', ')}\n`;

                // Try common method names
                const methods = ['getText', 'extract', 'parse', 'extractText'];
                for (const m of methods) {
                    if (typeof instance[m] === 'function') {
                        debugLog += `Calling method ${m}()...\n`;
                        try {
                            const res = await instance[m]();
                            debugLog += `Method ${m} returned: ${typeof res}\n`;
                            if (typeof res === 'string') debugLog += `Result len: ${res.length}\n`;
                            else if (res && res.text) debugLog += `Result.text len: ${res.text.length}\n`;
                        } catch (errM) {
                            debugLog += `Method ${m} failed: ${errM.message}\n`;
                        }
                    }
                }
            } catch (e) {
                debugLog += `Instantiation failed: ${e.message}\n`;
            }
        }

        // Also try 'pdf-parse/node' if available
        try {
            const pdfNode = require('pdf-parse/node');
            debugLog += "\nRequired 'pdf-parse/node' successfully.\n";
            debugLog += `Keys: ${Object.keys(pdfNode).join(', ')}\n`;

            // Maybe this one is different?
            if (typeof pdfNode.default === 'function') {
                debugLog += "pdfNode.default is function. Calling...\n";
                try {
                    const res = await pdfNode.default(dataBuffer);
                    debugLog += `Result: ${JSON.stringify(res).substring(0, 100)}\n`;
                } catch (e) { debugLog += `Call failed: ${e.message}\n`; }
            }
        } catch (e) {
            debugLog += `Failed to require 'pdf-parse/node': ${e.message}\n`;
        }

        fs.writeFileSync(outputPath, debugLog);
        console.log("Done.");

    } catch (error) {
        console.error('Fatal Error:', error);
        fs.writeFileSync(outputPath, `FATAL ERROR: ${error.message}`);
    }
})();

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import path from 'path'
import fs from 'fs'
import multer from 'multer'

// Carpeta de subidas local (reporte fotográfico): uploads/reporte
const UPLOAD_REPORTE_DIR = path.resolve(process.cwd(), 'uploads', 'reporte')

// https://vite.dev/config/
export default defineConfig({
  plugins: [
    react(),
    // En desarrollo: POST /api/upload guarda en uploads/reporte (sin necesidad del backend 4001)
    {
      name: 'local-upload-api',
      configureServer(server) {
        if (!fs.existsSync(UPLOAD_REPORTE_DIR)) {
          fs.mkdirSync(UPLOAD_REPORTE_DIR, { recursive: true })
        }
        const storage = multer.diskStorage({
          destination: (_req, _file, cb) => cb(null, UPLOAD_REPORTE_DIR),
          filename: (_req, file, cb) => {
            const ext = path.extname(file.originalname) || '.jpg'
            const name = Date.now() + '-' + Math.round(Math.random() * 1e9) + ext
            cb(null, name)
          },
        })
        const upload = multer({ storage, limits: { fileSize: 5 * 1024 * 1024 } })
        server.middlewares.use((req, res, next) => {
          if (req.url !== '/api/upload' || req.method !== 'POST') return next()
          upload.single('file')(req, res, (err) => {
            if (err) {
              res.statusCode = 500
              res.setHeader('Content-Type', 'application/json')
              res.end(JSON.stringify({ error: err.message || 'Error al subir' }))
              return
            }
            if (!req.file) {
              res.statusCode = 400
              res.setHeader('Content-Type', 'application/json')
              res.end(JSON.stringify({ error: 'No file uploaded' }))
              return
            }
            const url = '/uploads/reporte/' + req.file.filename
            res.statusCode = 200
            res.setHeader('Content-Type', 'application/json')
            res.end(JSON.stringify({ url, filename: req.file.filename }))
          })
        })
      },
    },
    // Servir archivos estáticos desde uploads/ (incluye uploads/reporte)
    {
      name: 'serve-uploads-local',
      configureServer(server) {
        const uploadsDir = path.resolve(process.cwd(), 'uploads')
        server.middlewares.use('/uploads', (req, res, next) => {
          if (req.method !== 'GET' && req.method !== 'HEAD') return next()
          const subpath = (req.url || '').replace(/\?.*$/, '').replace(/^\//, '')
          if (!subpath) return next()
          const filePath = path.join(uploadsDir, subpath)
          const resolved = path.resolve(filePath)
          const base = path.resolve(uploadsDir) + path.sep
          if (!resolved.startsWith(base) || !fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) return next()
          const ext = path.extname(subpath).toLowerCase()
          const mime = { '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png', '.webp': 'image/webp', '.gif': 'image/gif' }[ext] || 'application/octet-stream'
          res.setHeader('Content-Type', mime)
          fs.createReadStream(resolved).on('error', next).pipe(res)
        })
      },
    },
  ],
  server: {
    port: 3005,
    host: true,
    strictPort: false,
    // Solo proxy de /api/ai al backend 4001; /api/upload lo maneja el plugin local-upload-api
    proxy: {
      '/api/ai': {
        target: 'http://localhost:4001',
        changeOrigin: true,
        secure: false,
      },
    },
  },
})

