                </button>
            </div>

            {/* Lista de Plantillas */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {templates.length === 0 ? (
                    <Card className="col-span-full p-16 text-center bg-gradient-to-br from-slate-50 to-white">
