                                                textShadow: '0 1px 2px rgba(0,0,0,0.1)'
                                            }}>
                                            <p className="font-bold mb-1" style={{ fontSize: `${Math.min(template.headerTextSize || 18, 22)}px` }}>
                                                {template.headerText}
