                                        />
                                        <label htmlFor="color-custom" className="cursor-pointer flex items-center gap-2 text-slate-700 dark:text-slate-300">
                                            Color personalizado:
                                            <input
                                                type="color"
                                                value={getColorHex(formData.headerColor)}
                                                onChange={(e) => handleColorChange('custom', e.target.value)}
