                        </div>
                        <div className="flex-1 min-h-0 overflow-hidden bg-slate-100">
                            <iframe
                                src={pdfPreviewUrl}
                                className="w-full h-full border-0"
                                title="Vista previa del PDF"
                            />
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

