                                                    Gestionar
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteProject(project)}
                                                    className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                                    title="Eliminar"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>


                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modal para Nuevo Proyecto Express */}
            {showNewProjectModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100 border border-slate-200 dark:border-slate-700">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                <Plus className="text-blue-500" size={24} />
                                Nuevo Proyecto de Obra
                            </h2>
                            <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
                                <Plus size={24} className="rotate-45" />
                            </button>
                        </div>

                        <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Nombre de la Obra *</label>
                                <input
                                    autoFocus
                                    type="text"
                                    required
                                    value={newProject.name}
                                    onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ej: Remodelación Casa Blanca"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Cliente/Empresa</label>
                                <input
                                    type="text"
                                    value={newProject.client}
                                    onChange={(e) => setNewProject({ ...newProject, client: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Nombre del cliente"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Ubicación</label>
                                <input
                                    type="text"
                                    value={newProject.location}
                                    onChange={(e) => setNewProject({ ...newProject, location: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ubicación de la obra"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Tipo de Proyecto</label>
                                <select
                                    value={newProject.type}
                                    onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                >
                                    <option value="General">General</option>
                                    <option value="Residencial">Residencial</option>
                                    <option value="Comercial">Comercial</option>
                                    <option value="Industrial">Industrial</option>
                                    <option value="Infraestructura">Infraestructura</option>
                                </select>
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setShowNewProjectModal(false)}
                                    className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-bold hover:bg-slate-200 transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none transition"
                                >
                                    Crear Proyecto
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={confirmModal.onConfirm}
                type={confirmModal.type}
            />

            {/* Alert Modal */}

            <AlertModal
                isOpen={alertModal.isOpen}
                onClose={() => setAlertModal({ ...alertModal, isOpen: false })}
                title={alertModal.title}
                message={alertModal.message}
                type={alertModal.type}
            />
        </div>
    );
};

export default ProjectReportsDashboard;

import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { ProjectProvider } from './context/ProjectContext';
import { SubscriptionProvider } from './context/SubscriptionContext';
import { ThemeProvider } from './context/ThemeContext';
import { PricingModalProvider } from './context/PricingModalContext';
import { ErrorProvider } from './context/ErrorContext';
import { SidebarProvider } from './context/SidebarContext';
import ProtectedRoute from './components/ProtectedRoute';
import Layout from './components/layout/Layout';
import ErrorBoundary from './components/ErrorBoundary';
import Dashboard from './pages/Dashboard';
import Editor from './pages/Editor';
import Catalog from './pages/Catalog';
import History from './pages/History';
import Templates from './pages/Templates';
import PDFTemplatesPage from './pages/PDFTemplatesPage';
import Login from './pages/Login';
import LandingPage from './pages/LandingPage';
import DemoPage from './pages/DemoPage';
import BitacoraPage from './pages/BitacoraPage';
import PhotographicReportPage from './pages/PhotographicReportPage';
import PricingPage from './pages/PricingPage';
import UsageDashboard from './pages/UsageDashboard';
import ScheduleGanttPage from './pages/ScheduleGanttPage';
import SharedProjectPage from './pages/SharedProjectPage';
import UsageNotification from './components/subscription/UsageNotification';
import ConfirmEmail from './pages/ConfirmEmail';
import NotFound from './pages/NotFound';
import InactivityHandler from './components/auth/InactivityHandler';
import KeepAlive from './components/KeepAlive';
import AdminDashboard from './pages/AdminDashboard';
import AdminRoute from './components/auth/AdminRoute';
import PriceSearchPage from './pages/PriceSearchPage';
import PDFEditorPage from './pages/PDFEditorPage';
import ProjectReportsDashboard from './pages/ProjectReportsDashboard';


const App = () => {
    return (
        <ErrorBoundary>
            <ThemeProvider>
                <ErrorProvider>
                    <AuthProvider>
                        <SubscriptionProvider>
                            <PricingModalProvider>
                                <SidebarProvider>
                                    <ProjectProvider>
                                        <Router>
                                            <InactivityHandler />
                                            <KeepAlive />
                                            <Routes>
                                                {/* Landing Page - Public */}
                                                <Route path="/" element={<LandingPage />} />

                                                {/* Demo Page - Public */}
                                                <Route path="/demo" element={<DemoPage />} />

                                                {/* Email Confirmation - Public */}
                                                <Route path="/confirm-email" element={<ConfirmEmail />} />
                                                <Route path="/auth/callback" element={<ConfirmEmail />} />
                                                <Route path="/auth/confirm" element={<ConfirmEmail />} />

                                                {/* Shared Project Routes - Public */}
                                                <Route path="/share/:token" element={<SharedProjectPage />} />
                                                <Route path="/s/:token" element={<SharedProjectPage />} />

                                                {/* Public route - Login */}
                                                <Route path="/login" element={
                                                    <ProtectedRoute requireAuth={false}>
                                                        <Login />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Protected routes - Require authentication */}
                                                <Route path="/dashboard" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Visión General"><Dashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Editor Routes */}
                                                <Route path="/editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/editor/:id" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Bitacora Route */}
                                                <Route path="/project/:id/bitacora" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Bitácora de Obra"><BitacoraPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Schedule Gantt Route */}
                                                <Route path="/project/:id/schedule" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <ScheduleGanttPage />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Photographic Report Routes */}
                                                <Route path="/project/:projectId/report/new" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Nuevo Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/project/:projectId/report/:logId/edit" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                <Route path="/catalog" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Base de Datos Maestra"><Catalog /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Plantillas"><Templates /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pdf-templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Configurar PDF"><PDFTemplatesPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/history" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Archivos Guardados"><History /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pricing" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Planes y Precios"><PricingPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/usage" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Dashboard de Uso"><UsageDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/reports" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Módulo de Reportes"><ProjectReportsDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Price Search Route */}
                                                <Route path="/pricesearch" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Búsqueda de Precios"><PriceSearchPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* PDF Editor Route */}
                                                <Route path="/pdf-editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar PDF"><PDFEditorPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Admin Route */}
                                                <Route path="/admin" element={
                                                    <AdminRoute>
                                                        <Layout title="Administración del Sistema"><AdminDashboard /></Layout>
                                                    </AdminRoute>
                                                } />

                                                {/* Catch-all route - 404 Not Found */}
                                                <Route path="*" element={<NotFound />} />
                                            </Routes>
                                        </Router>
                                    </ProjectProvider>
                                </SidebarProvider>
                            </PricingModalProvider>
                        </SubscriptionProvider>
                    </AuthProvider>
                </ErrorProvider>
            </ThemeProvider>
        </ErrorBoundary>
    );
};

export default App;

import { useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';

/**
 * KeepAlive Component
 * 
 * Este componente envía un "pulso" a Supabase y al Servidor Proxy (Render) 
 * para evitar que entren en modo de pausa por inactividad.
 */
export default function KeepAlive() {
    useEffect(() => {
        // Render Free suspende la app tras 15 MINUTOS de inactividad.
        // Usamos 10 minutos para estar seguros mientras el usuario tenga la pestaña abierta.
        const RENDER_INTERVAL = 10 * 60 * 1000;

        // Supabase Free pausa el proyecto tras 7 DÍAS de inactividad.
        // Un pulso cada 24 horas es más que suficiente para esto.
        const SUPABASE_INTERVAL = 24 * 60 * 60 * 1000;

        const sendRenderPulse = async () => {
            // Solo enviar pulso si hay API configurada (producción o backend en 4001); evita ERR_CONNECTION_REFUSED en dev sin servidor
            const apiBaseUrl = import.meta.env.VITE_API_URL;
            if (!apiBaseUrl) return;
            try {
                await fetch(`${apiBaseUrl}/api/ai/health`, { mode: 'no-cors' }).catch(() => {
                    fetch(`${apiBaseUrl}/`, { mode: 'no-cors' }).catch(() => {});
                });
            } catch {
                // Silenciar: servidor no disponible
            }
        };

        const sendSupabasePulse = async () => {
            try {
                await supabase.from('projects').select('id').limit(1);
            } catch {
                // Silenciar: conexión o permisos
            }
        };

        // Ejecutar inmediatamente
        sendRenderPulse();
        sendSupabasePulse();

        // Configurar intervalos
        const renderTimer = setInterval(sendRenderPulse, RENDER_INTERVAL);
        const supabaseTimer = setInterval(sendSupabasePulse, SUPABASE_INTERVAL);

        return () => {
            clearInterval(renderTimer);
            clearInterval(supabaseTimer);
        };
    }, []);

    return null;
}

