import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, Lock, Eye, Download, ArrowLeft, Clock, User, Building2, Package, Calendar as CalendarIcon } from 'lucide-react';
import { ShareService } from '../services/ShareService';
import { PDFService } from '../services/PDFService';
import { formatCurrency } from '../utils/format';

const SharedProjectPage = () => {
    const { token } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [projectData, setProjectData] = useState(null);
    const [shareInfo, setShareInfo] = useState(null);
    const [passwordRequired, setPasswordRequired] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [error, setError] = useState(null);

    useEffect(() => {
        loadSharedProject();
    }, [token]);

    const loadSharedProject = async () => {
        try {
            setLoading(true);
            setError(null);

            const shareData = await ShareService.getShareByToken(token);

            // Verificar si requiere contraseña
            if (shareData.password) {
                // Verificar si ya se verificó (usando sessionStorage)
                const verified = sessionStorage.getItem(`share_verified_${token}`);
                if (!verified) {
                    setPasswordRequired(true);
                    setShareInfo(shareData);
                    setLoading(false);
                    return;
                }
            }

            setShareInfo(shareData);

            // Extraer datos del proyecto
            const project = shareData.projects;
            if (!project || !project.data) {
                throw new Error('Proyecto no encontrado o no disponible');
            }

            const fullProjectData = project.data;
            
            // Normalizar projectInfo para asegurar que todos los campos se carguen correctamente
            const normalizedProjectInfo = {
                project: fullProjectData.projectInfo?.project || project.name,
                client: fullProjectData.projectInfo?.client || project.client,
                type: fullProjectData.projectInfo?.type || project.type,
                taxRate: fullProjectData.projectInfo?.taxRate ?? 16, // Usar ?? para permitir 0
                currency: fullProjectData.projectInfo?.currency || 'MXN',
                date: fullProjectData.projectInfo?.date || new Date().toISOString().split('T')[0],
                location: fullProjectData.projectInfo?.location || 'México',
                ...fullProjectData.projectInfo // Preservar otros campos
            };
            
            setProjectData({
                projectInfo: normalizedProjectInfo,
                items: fullProjectData.items || [],
                scheduleData: fullProjectData.scheduleData,
                materialList: fullProjectData.materialList,
                apuData: fullProjectData.apuData
            });

        } catch (error) {
            console.error('Error loading shared project:', error);
            setError(error.message || 'No se pudo cargar el proyecto compartido');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        setPasswordError('');

        try {
            const isValid = await ShareService.verifyPassword(token, password);
            if (isValid) {
                // Guardar en sessionStorage para esta sesión
                sessionStorage.setItem(`share_verified_${token}`, 'true');
                setPasswordRequired(false);
                // Recargar con contraseña verificada
                await loadSharedProject();
            } else {
                setPasswordError('Contraseña incorrecta');
            }
        } catch (error) {
            setPasswordError('Error al verificar contraseña');
        }
    };

    const calculateTotals = () => {
        if (!projectData || !projectData.items || projectData.items.length === 0) {
            return { subtotal: 0, tax: 0, total: 0 };
        }

        const subtotal = projectData.items.reduce((sum, item) => {
            return sum + (item.quantity || 0) * (item.unitPrice || 0);
        }, 0);

        // Usar nullish coalescing para permitir taxRate = 0
        const taxRateValue = projectData.projectInfo?.taxRate ?? 16;
        const taxRate = taxRateValue / 100;
        const tax = subtotal * taxRate;
        const total = subtotal + tax;

        return { subtotal, tax, total };
    };

    const handleExportPDF = () => {
        if (!projectData) return;

        const { subtotal, tax, total } = calculateTotals();
        PDFService.exportBudget(
            projectData.projectInfo,
            projectData.items,
            total,
            subtotal,
            tax
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600 font-medium">Cargando presupuesto...</p>
                </div>
            </div>
        );
    }

    if (passwordRequired) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
                    <div className="text-center mb-6">
                        <div className="bg-emerald-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <Lock className="text-emerald-600" size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 mb-2">Presupuesto Protegido</h2>
                        <p className="text-slate-600">Este presupuesto está protegido con contraseña</p>
                    </div>

                    <form onSubmit={handlePasswordSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                Contraseña
                            </label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                placeholder="Ingresa la contraseña"
                                required
                                autoFocus
                            />
                            {passwordError && (
                                <p className="text-red-600 text-sm mt-2">{passwordError}</p>
                            )}
                        </div>

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition shadow-lg shadow-emerald-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full text-center">
                    <div className="bg-red-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                        <Lock className="text-red-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">No disponible</h2>
                    <p className="text-slate-600 mb-6">{error}</p>
                    <button
                        onClick={() => navigate('/')}
                        className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                    >
                        Ir al Inicio
                    </button>
                </div>
            </div>
        );
    }

    if (!projectData) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <p className="text-slate-600">No hay datos disponibles</p>
                </div>
            </div>
        );
    }

    const { subtotal, tax, total } = calculateTotals();
    const items = projectData.items || [];

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 shadow-sm">
                <div className="max-w-6xl mx-auto px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                {projectData.projectInfo?.project || 'Presupuesto'}
                            </h1>
                            <div className="flex items-center gap-4 mt-2 text-sm text-slate-600">
                                {projectData.projectInfo?.client && (
                                    <div className="flex items-center gap-1">
                                        <User size={14} />
                                        <span>{projectData.projectInfo.client}</span>
                                    </div>
                                )}
                                {projectData.projectInfo?.type && (
                                    <div className="flex items-center gap-1">
                                        <Building2 size={14} />
                                        <span>{projectData.projectInfo.type}</span>
                                    </div>
                                )}
                                {shareInfo?.last_accessed_at && (
                                    <div className="flex items-center gap-1">
                                        <Clock size={14} />
                                        <span>Visto {new Date(shareInfo.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleExportPDF}
                                className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 shadow-lg shadow-emerald-200"
                            >
                                <Download size={18} />
                                Descargar PDF
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="max-w-6xl mx-auto px-6 py-8">
                {/* Resumen */}
                <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
                    <h2 className="text-lg font-bold text-slate-800 mb-4">Resumen del Presupuesto</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">Subtotal</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(subtotal)}</div>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">IVA ({projectData.projectInfo?.taxRate ?? 16}%)</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(tax)}</div>
                        </div>
                        <div className="bg-emerald-50 p-4 rounded-lg border-2 border-emerald-200">
                            <div className="text-sm text-emerald-600 font-medium mb-1">Total</div>
                            <div className="text-3xl font-bold text-emerald-700">{formatCurrency(total)}</div>
                        </div>
                    </div>
                </div>

                {/* Partidas */}
                <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                    <div className="p-6 border-b border-slate-200">
                        <h2 className="text-lg font-bold text-slate-800">Partidas del Presupuesto</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-slate-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">#</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Descripción</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">P. Unit.</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200">
                                {items.map((item, index) => (
                                    <tr key={item.id || index} className="hover:bg-slate-50 transition">
                                        <td className="px-6 py-4 text-sm text-slate-600">{index + 1}</td>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-medium text-slate-800">{item.description}</div>
                                            {item.category && (
                                                <div className="text-xs text-slate-500 mt-1">{item.category}</div>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600">{item.unit || 'pza'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{item.quantity?.toFixed(2) || '0.00'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(item.unitPrice || 0)}</td>
                                        <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                            {formatCurrency((item.quantity || 0) * (item.unitPrice || 0))}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot className="bg-slate-50">
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">Subtotal:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(subtotal)}</td>
                                </tr>
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                        IVA ({projectData.projectInfo?.taxRate ?? 16}%):
                                    </td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(tax)}</td>
                                </tr>
                                <tr className="bg-emerald-50">
                                    <td colSpan="4" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">Total:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">{formatCurrency(total)}</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>

                {/* Lista de Materiales/Insumos */}
                {projectData.materialList && projectData.materialList.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <Package size={20} className="text-indigo-600" />
                                Lista de Insumos y Materiales
                            </h2>
                        </div>
                        {projectData.materialAssumptions && projectData.materialAssumptions.length > 0 && (
                            <div className="bg-amber-50 border-b border-amber-100 p-4">
                                <h4 className="text-sm font-bold text-amber-800 mb-2">Notas Importantes</h4>
                                <ul className="list-disc list-inside text-xs text-amber-700 space-y-1">
                                    {projectData.materialAssumptions.map((assumption, idx) => (
                                        <li key={idx}>{assumption}</li>
                                    ))}
                                </ul>
                            </div>
                        )}
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-slate-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Material</th>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Categoría</th>
                                        <th className="px-6 py-3 text-center text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Costo Est.</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                        {projectData.materialList.some(m => m.notes) && (
                                            <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Notas</th>
                                        )}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-200">
                                    {projectData.materialList.map((mat, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50 transition">
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800">{mat.material}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600">{mat.category || 'Materiales'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600 text-center">{mat.unit || 'pza'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{mat.quantity?.toFixed(2) || '0.00'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(mat.unitPrice || 0)}</td>
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                                {formatCurrency((mat.quantity || 0) * (mat.unitPrice || 0))}
                                            </td>
                                            {projectData.materialList.some(m => m.notes) && (
                                                <td className="px-6 py-4 text-xs text-slate-500 italic">{mat.notes || '-'}</td>
                                            )}
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot className="bg-slate-50">
                                    <tr>
                                        <td colSpan={projectData.materialList.some(m => m.notes) ? 5 : 4} className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                            Total Estimado:
                                        </td>
                                        <td colSpan={2} className="px-6 py-4 text-right text-sm font-bold text-slate-800">
                                            {formatCurrency(
                                                projectData.materialList.reduce((sum, m) => sum + ((m.quantity || 0) * (m.unitPrice || 0)), 0)
                                            )}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                )}

                {/* Cronograma */}
                {shareInfo?.metadata?.showSchedule !== false && projectData.scheduleData && projectData.scheduleData.tasks && projectData.scheduleData.tasks.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <CalendarIcon size={20} className="text-blue-600" />
                                Cronograma de Obra
                            </h2>
                        </div>
                        <div className="p-6">
                            <div className="space-y-4">
                                {projectData.scheduleData.tasks.map((task, idx) => (
                                    <div key={task.id || idx} className="border border-slate-200 rounded-lg p-4 hover:bg-slate-50 transition">
                                        <div className="flex items-start justify-between mb-2">
                                            <div className="flex-1">
                                                <h3 className="text-sm font-bold text-slate-800">{task.name || `Tarea ${idx + 1}`}</h3>
                                                {task.description && (
                                                    <p className="text-xs text-slate-600 mt-1">{task.description}</p>
                                                )}
                                            </div>
                                            {task.progress !== undefined && (
                                                <div className="ml-4 text-right">
                                                    <div className="text-xs text-slate-500 mb-1">Progreso</div>
                                                    <div className="text-sm font-bold text-blue-600">{task.progress || 0}%</div>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-4 mt-3 text-xs text-slate-500">
                                            {task.startDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Inicio: {new Date(task.startDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.endDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Fin: {new Date(task.endDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.duration && (
                                                <div>
                                                    <span>Duración: {task.duration} {task.durationUnit || 'días'}</span>
                                                </div>
                                            )}
                                        </div>
                                        {task.dependencies && task.dependencies.length > 0 && (
                                            <div className="mt-2 text-xs text-slate-500">
                                                <span className="font-medium">Depende de:</span> {task.dependencies.join(', ')}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-8 text-center text-sm text-slate-500">
                    <p>Este presupuesto fue compartido contigo desde PresuGenius</p>
                    <p className="mt-1">Generado el {new Date().toLocaleDateString('es-MX', { 
                        year: 'numeric', 
                        month: 'long', 
                        day: 'numeric' 
                    })}</p>
                </div>
            </div>
        </div>
    );
};

export default SharedProjectPage;

import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { ProjectProvider } from './context/ProjectContext';
import { SubscriptionProvider } from './context/SubscriptionContext';
import { ThemeProvider } from './context/ThemeContext';
import { PricingModalProvider } from './context/PricingModalContext';
import { ErrorProvider } from './context/ErrorContext';
import { SidebarProvider } from './context/SidebarContext';
import ProtectedRoute from './components/ProtectedRoute';
import Layout from './components/layout/Layout';
import ErrorBoundary from './components/ErrorBoundary';
import Dashboard from './pages/Dashboard';
import Editor from './pages/Editor';
import Catalog from './pages/Catalog';
import History from './pages/History';
import Templates from './pages/Templates';
import PDFTemplatesPage from './pages/PDFTemplatesPage';
import Login from './pages/Login';
import LandingPage from './pages/LandingPage';
import DemoPage from './pages/DemoPage';
import BitacoraPage from './pages/BitacoraPage';
import PhotographicReportPage from './pages/PhotographicReportPage';
import PricingPage from './pages/PricingPage';
import UsageDashboard from './pages/UsageDashboard';
import ScheduleGanttPage from './pages/ScheduleGanttPage';
import SharedProjectPage from './pages/SharedProjectPage';
import UsageNotification from './components/subscription/UsageNotification';
import ConfirmEmail from './pages/ConfirmEmail';
import NotFound from './pages/NotFound';
import InactivityHandler from './components/auth/InactivityHandler';
import KeepAlive from './components/KeepAlive';
import AdminDashboard from './pages/AdminDashboard';
import AdminRoute from './components/auth/AdminRoute';
import PriceSearchPage from './pages/PriceSearchPage';
import PDFEditorPage from './pages/PDFEditorPage';
import ProjectReportsDashboard from './pages/ProjectReportsDashboard';


const App = () => {
    return (
        <ErrorBoundary>
            <ThemeProvider>
                <ErrorProvider>
                    <AuthProvider>
                        <SubscriptionProvider>
                            <PricingModalProvider>
                                <SidebarProvider>
                                    <ProjectProvider>
                                        <Router>
                                            <InactivityHandler />
                                            <KeepAlive />
                                            <Routes>
                                                {/* Landing Page - Public */}
                                                <Route path="/" element={<LandingPage />} />

                                                {/* Demo Page - Public */}
                                                <Route path="/demo" element={<DemoPage />} />

                                                {/* Email Confirmation - Public */}
                                                <Route path="/confirm-email" element={<ConfirmEmail />} />
                                                <Route path="/auth/callback" element={<ConfirmEmail />} />
                                                <Route path="/auth/confirm" element={<ConfirmEmail />} />

                                                {/* Shared Project Routes - Public */}
                                                <Route path="/share/:token" element={<SharedProjectPage />} />
                                                <Route path="/s/:token" element={<SharedProjectPage />} />

                                                {/* Public route - Login */}
                                                <Route path="/login" element={
                                                    <ProtectedRoute requireAuth={false}>
                                                        <Login />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Protected routes - Require authentication */}
                                                <Route path="/dashboard" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Visión General"><Dashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Editor Routes */}
                                                <Route path="/editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/editor/:id" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Constructor de Presupuestos"><Editor /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Bitacora Route */}
                                                <Route path="/project/:id/bitacora" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Bitácora de Obra"><BitacoraPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Schedule Gantt Route */}
                                                <Route path="/project/:id/schedule" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <ScheduleGanttPage />
                                                    </ProtectedRoute>
                                                } />

                                                {/* Photographic Report Routes */}
                                                <Route path="/project/:projectId/report/new" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Nuevo Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/project/:projectId/report/:logId/edit" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar Reporte Fotográfico"><PhotographicReportPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                <Route path="/catalog" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Base de Datos Maestra"><Catalog /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Plantillas"><Templates /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pdf-templates" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Configurar PDF"><PDFTemplatesPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/history" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Archivos Guardados"><History /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/pricing" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Planes y Precios"><PricingPage /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/usage" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Dashboard de Uso"><UsageDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />
                                                <Route path="/reports" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Módulo de Reportes"><ProjectReportsDashboard /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Price Search Route */}
                                                <Route path="/pricesearch" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Búsqueda de Precios"><PriceSearchPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* PDF Editor Route */}
                                                <Route path="/pdf-editor" element={
                                                    <ProtectedRoute requireAuth={true}>
                                                        <Layout title="Editar PDF"><PDFEditorPage /></Layout>
                                                    </ProtectedRoute>
                                                } />

                                                {/* Admin Route */}
                                                <Route path="/admin" element={
                                                    <AdminRoute>
                                                        <Layout title="Administración del Sistema"><AdminDashboard /></Layout>
                                                    </AdminRoute>
                                                } />

                                                {/* Catch-all route - 404 Not Found */}
                                                <Route path="*" element={<NotFound />} />
                                            </Routes>
                                        </Router>
                                    </ProjectProvider>
                                </SidebarProvider>
                            </PricingModalProvider>
                        </SubscriptionProvider>
                    </AuthProvider>
                </ErrorProvider>
            </ThemeProvider>
        </ErrorBoundary>
    );
};

export default App;

import React, { useState } from 'react';
import { Search, Trash2, Plus, X, Sparkles, MapPin, Eye, ArrowRight, Check, AlertTriangle, Info } from 'lucide-react';
import Badge from '../components/ui/Badge';
import { useProject } from '../context/ProjectContext';
import { formatCurrency } from '../utils/format';
import { AIBudgetService } from '../services/AIBudgetService';

const Catalog = () => {
    const { catalog, addToCatalog, deleteFromCatalog, updateCatalogBulk, showToast } = useProject();
    const [search, setSearch] = useState('');
    const [showAddModal, setShowAddModal] = useState(false);
    const [isUpdatingPrices, setIsUpdatingPrices] = useState(false);
    const [newItem, setNewItem] = useState({
        description: '',
        unit: 'pza',
        unitPrice: '',
        category: 'Materiales'
    });

    const [showUpdateModal, setShowUpdateModal] = useState(false);
    const [updateLocation, setUpdateLocation] = useState('México');
    const [isDetectingLocation, setIsDetectingLocation] = useState(false);

    // New state for Review Modal
    const [showReviewModal, setShowReviewModal] = useState(false);
    const [pendingUpdates, setPendingUpdates] = useState([]);
    const [selectedUpdates, setSelectedUpdates] = useState({}); // { itemId: boolean }

    const handleAdd = async (e) => {
        e.preventDefault();
        if (!newItem.description || !newItem.unitPrice) return;

        const success = await addToCatalog({
            ...newItem,
            unitPrice: parseFloat(newItem.unitPrice)
        });

        if (success) {
            setShowAddModal(false);
            setNewItem({ description: '', unit: 'pza', unitPrice: '', category: 'Materiales' });
        }
    };

    const handleOpenUpdateModal = () => {
        if (catalog.length === 0) {
            showToast('No hay conceptos en el catálogo para actualizar', 'warning');
            return;
        }
        setShowUpdateModal(true);
    };

    const handleDetectLocation = async () => {
        setIsDetectingLocation(true);

        const detectViaIp = async () => {
            try {
                const response = await fetch('https://ipapi.co/json/');
                if (!response.ok) throw new Error('Error fetching location');
                const data = await response.json();
                if (data.city && data.region) {
                    setUpdateLocation(`${data.city}, ${data.region}`);
                    showToast('Ubicación detectada (IP)', 'success');
                } else {
                    setUpdateLocation('México');
                    showToast('No se pudo detectar ciudad exacta', 'warning');
                }
            } catch (error) {
                console.error('Error detecting location:', error);
                setUpdateLocation('México');
                showToast('No se pudo detectar la ubicación', 'info');
            } finally {
                setIsDetectingLocation(false);
            }
        };

        if ('geolocation' in navigator) {
            navigator.geolocation.getCurrentPosition(
                async (position) => {
                    try {
                        const { latitude, longitude } = position.coords;
                        // Use OpenStreetMap Nominatim for free reverse geocoding
                        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                        const data = await response.json();

                        const address = data.address;
                        const city = address.city || address.town || address.village || address.municipality;
                        const state = address.state;

                        if (city) {
                            setUpdateLocation(`${city}, ${state || ''}`);
                            showToast('Ubicación detectada (GPS)', 'success');
                            setIsDetectingLocation(false);
                        } else {
                            detectViaIp();
                        }
                    } catch (error) {
                        console.warn('GPS Reverse geocoding failed, falling back to IP', error);
                        detectViaIp();
                    }
                },
                (error) => {
                    console.warn('GPS denied or failed', error);
                    detectViaIp();
                }
            );
        } else {
            detectViaIp();
        }
    };

    const confirmUpdatePrices = async () => {
        setShowUpdateModal(false);
        setIsUpdatingPrices(true);
        try {
            // 1. Get AI updates (without applying them yet)
            const updatedCatalog = await AIBudgetService.updateCatalogPrices(catalog, updateLocation);

            // 2. Identify ONLY items that changed
            const changes = updatedCatalog.filter(updatedItem => {
                const original = catalog.find(c => c.id === updatedItem.id);
                return original && Math.abs(original.unitPrice - updatedItem.unitPrice) > 0.01;
            }).map(updatedItem => {
                const original = catalog.find(c => c.id === updatedItem.id);
                return {
                    ...updatedItem,
                    originalPrice: original.unitPrice,
                    priceDiff: updatedItem.unitPrice - original.unitPrice,
                    diffPercent: ((updatedItem.unitPrice - original.unitPrice) / original.unitPrice) * 100
                };
            });

            if (changes.length === 0) {
                showToast('La IA analizó tu catálogo y los precios parecen actuales.', 'success');
                setIsUpdatingPrices(false);
                return;
            }

            // 3. Prepare Review Modal
            setPendingUpdates(changes);
            // Select all by default
            const initialSelection = {};
            changes.forEach(item => initialSelection[item.id] = true);
            setSelectedUpdates(initialSelection);

            setShowReviewModal(true);

        } catch (error) {
            console.error('Error updating prices:', error);
            showToast('Error al analizar precios', 'error');
        } finally {
            setIsUpdatingPrices(false);
        }
    };

    const handleApplyUpdates = async () => {
        const itemsToUpdate = pendingUpdates.filter(item => selectedUpdates[item.id]);

        if (itemsToUpdate.length === 0) {
            setShowReviewModal(false);
            return;
        }

        // Merge updates into catalog
        const newCatalog = catalog.map(item => {
            const update = itemsToUpdate.find(u => u.id === item.id);
            if (update) {
                return {
                    ...item,
                    unitPrice: update.unitPrice,
                    lastUpdate: update.lastUpdate,
                    priceNote: update.priceNote,
                    source: update.source
                };
            }
            return item;
        });

        await updateCatalogBulk(newCatalog);
        showToast(`${itemsToUpdate.length} precios actualizados correctamente`, 'success');
        setShowReviewModal(false);
    };

    const toggleUpdateSelection = (id) => {
        setSelectedUpdates(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const [activeTab, setActiveTab] = useState('personal'); // 'personal' | 'market'
    const [viewItem, setViewItem] = useState(null);
    const [marketItems, setMarketItems] = useState([]);
    const [marketLoading, setMarketLoading] = useState(false);
    const [marketPage, setMarketPage] = useState(1);
    const [marketTotal, setMarketTotal] = useState(0);
    const [marketSearch, setMarketSearch] = useState('');

    // Load market items when tab changes or search changes
    React.useEffect(() => {
        if (activeTab === 'market') {
            loadMarketItems();
        }
    }, [activeTab, marketPage, marketSearch]);

    const loadMarketItems = async () => {
        setMarketLoading(true);
        try {
            const { MarketPriceService } = await import('../services/MarketPriceService');
            const { data, count } = await MarketPriceService.searchPrices(marketSearch, marketPage, 20);
            setMarketItems(data);
            setMarketTotal(count);
        } catch (error) {
            console.error('Error loading market items:', error);
            showToast('Error al cargar precios de mercado', 'error');
        } finally {
            setMarketLoading(false);
        }
    };

    const handleAddToMyCatalog = async (item) => {
        const success = await addToCatalog({
            description: item.description,
            unit: item.unit,
            unitPrice: item.base_price,
            category: item.category || 'Materiales'
        });
        if (success) {
            showToast('Agregado a tu catálogo', 'success');
        }
    };

    return (
        <div className="space-y-6 animate-fadeIn pb-20">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Catálogo Maestro</h2>
                    <p className="text-slate-500 text-sm">
                        {activeTab === 'personal'
                            ? 'Gestiona tus precios personales y conceptos personalizados.'
                            : 'Consulta la base de datos compartida del mercado (solo lectura).'}
                    </p>
                </div>

                <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button
                        onClick={() => setActiveTab('personal')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Mis Conceptos
                    </button>
                    <button
                        onClick={() => setActiveTab('market')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition ${activeTab === 'market' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Base de Datos Maestra
                    </button>
                </div>
            </div>

            {/* Toolbar */}
            <div className="flex justify-between items-center">
                <div className="flex gap-3">
                    {activeTab === 'personal' && (
                        <button
                            onClick={handleOpenUpdateModal}
                            disabled={isUpdatingPrices}
                            className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition font-bold text-sm border border-indigo-200"
                            title="Actualizar precios con IA"
                        >
                            {isUpdatingPrices ? (
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-600 border-t-transparent"></div>
                            ) : (
                                <Sparkles size={16} />
                            )}
                            <span>{isUpdatingPrices ? 'Actualizando...' : 'Actualizar Precios IA'}</span>
                        </button>
                    )}
                </div>

                <div className="relative">
                    <Search className="absolute left-3 top-2.5 text-slate-400" size={16} />
                    <input
                        value={activeTab === 'personal' ? search : marketSearch}
                        onChange={(e) => activeTab === 'personal' ? setSearch(e.target.value) : setMarketSearch(e.target.value)}
                        placeholder={activeTab === 'personal' ? "Buscar en mis conceptos..." : "Buscar en base de datos maestra..."}
                        className="pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none w-64 md:w-80"
                    />
                </div>
            </div>

            {/* Content */}
            {activeTab === 'personal' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {catalog.filter(c => c.description.toLowerCase().includes(search.toLowerCase())).map(c => (
                        <div key={c.id} className="bg-white p-4 rounded-xl border border-slate-200 hover:shadow-md transition group relative">
                            <div className="flex justify-between items-start mb-2">
                                <Badge type={c.category} />
                                <button
                                    onClick={() => deleteFromCatalog(c.id)}
                                    className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition"
                                    title="Eliminar del catálogo"
                                >
                                    <Trash2 size={14} />
                                </button>
                            </div>
                            <p className="font-medium text-slate-800 text-sm mb-3 line-clamp-3 min-h-[3rem]">{c.description}</p>
                            <div className="flex justify-between items-center text-sm border-t border-slate-100 pt-3">
                                <span className="text-slate-500 bg-slate-50 px-2 py-0.5 rounded text-xs font-medium">{c.unit}</span>
                                <span className="font-mono font-bold text-blue-600">{formatCurrency(c.unitPrice)}</span>
                            </div>
                        </div>
                    ))}

                    {/* Add New Card - Solo visible en pestaña personal */}
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center p-6 text-slate-400 hover:border-blue-400 hover:text-blue-500 hover:bg-blue-50 transition cursor-pointer min-h-[160px]"
                    >
                        <div className="bg-blue-50 p-3 rounded-full mb-3 group-hover:bg-blue-100 transition">
                            <Plus size={24} />
                        </div>
                        <span className="font-bold">Nuevo Concepto</span>
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Información de solo lectura */}
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-sm text-blue-800 flex items-start gap-2">
                        <Eye size={18} className="text-blue-600 mt-0.5 flex-shrink-0" />
                        <div>
                            <span className="font-bold">Base de Datos Maestra (Solo Lectura)</span>
                            <p className="text-xs text-blue-700 mt-1">Esta base de datos es compartida y no se puede modificar. Puedes agregar conceptos a tu catálogo personal usando el botón +.</p>
                        </div>
                    </div>

                    {marketLoading ? (
                        <div className="flex justify-center py-12">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {marketItems.map(item => (
                                <div key={item.id} className="bg-white p-4 rounded-xl border border-indigo-100 hover:border-indigo-300 hover:shadow-md transition group relative">
                                    <div className="flex justify-between items-start mb-2">
                                        <Badge type={item.category || 'Materiales'} />
                                        <span className="text-[10px] text-slate-400 bg-slate-50 px-2 py-1 rounded-full border border-slate-100">
                                            {item.source === 'cdmx_tabulador' ? 'CDMX' :
                                                item.source === 'construbase_libre' ? 'Construbase' :
                                                    item.source === 'neodata' ? 'Neodata' : item.source}
                                        </span>
                                    </div>
                                    {/* Mostrar partida o código si está disponible */}
                                    {(item.metadata?.partida || item.metadata?.codigo) && (
                                        <div className="mb-2">
                                            <span className="text-[10px] font-mono text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-200">
                                                {item.metadata?.partida || item.metadata?.codigo}
                                                {item.metadata?.renglon && ` - ${item.metadata.renglon}`}
                                            </span>
                                        </div>
                                    )}
                                    <p className="font-medium text-slate-800 text-sm mb-3 line-clamp-3 min-h-[3rem]">{item.description}</p>
                                    <div className="flex justify-between items-center text-sm border-t border-slate-100 pt-3">
                                        <div className="flex flex-col">
                                            <span className="text-slate-500 text-xs">{item.unit}</span>
                                            <span className="text-[10px] text-slate-400">{item.location}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="font-mono font-bold text-indigo-600">{formatCurrency(item.base_price)}</span>
                                            <button
                                                onClick={() => setViewItem(item)}
                                                className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition"
                                                title="Ver detalles completos (Solo lectura)"
                                            >
                                                <Eye size={16} />
                                            </button>
                                            <button
                                                onClick={() => handleAddToMyCatalog(item)}
                                                className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition"
                                                title="Agregar a mi catálogo personal"
                                            >
                                                <Plus size={16} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Pagination */}
                    <div className="flex justify-between items-center pt-4 border-t border-slate-200">
                        <span className="text-sm text-slate-500">
                            Mostrando {marketItems.length} de {marketTotal} resultados
                        </span>
                        <div className="flex gap-2">
                            <button
                                onClick={() => setMarketPage(p => Math.max(1, p - 1))}
                                disabled={marketPage === 1}
                                className="px-3 py-1 border rounded hover:bg-slate-50 disabled:opacity-50 text-sm"
                            >
                                Anterior
                            </button>
                            <span className="px-3 py-1 text-sm font-medium text-slate-600 bg-slate-50 rounded">
                                Página {marketPage}
                            </span>
                            <button
                                onClick={() => setMarketPage(p => p + 1)}
                                disabled={marketItems.length < 20}
                                className="px-3 py-1 border rounded hover:bg-slate-50 disabled:opacity-50 text-sm"
                            >
                                Siguiente
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal Agregar */}
            {showAddModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                            <h3 className="font-bold text-slate-800">Agregar al Catálogo</h3>
                            <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleAdd} className="p-6 space-y-4">

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descripción</label>
                                <textarea
                                    value={newItem.description}
                                    onChange={e => setNewItem({ ...newItem, description: e.target.value })}
                                    className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                                    rows={3}
                                    placeholder="Ej: Muro de block..."
                                    required
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Unidad</label>
                                    <input
                                        value={newItem.unit}
                                        onChange={e => setNewItem({ ...newItem, unit: e.target.value })}
                                        className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                        placeholder="m2, pza..."
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Precio Unitario</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        min="0"
                                        value={newItem.unitPrice}
                                        onChange={e => setNewItem({ ...newItem, unitPrice: e.target.value })}
                                        className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                        placeholder="0.00"
                                        required
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría</label>
                                <select
                                    value={newItem.category}
                                    onChange={e => setNewItem({ ...newItem, category: e.target.value })}
                                    className="w-full border border-slate-200 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                                >
                                    {['Materiales', 'Mano de Obra', 'Equipos', 'Instalaciones', 'Obra Civil'].map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition">Cancelar</button>
                                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white font-bold hover:bg-blue-700 rounded-lg transition shadow-lg shadow-blue-200">Guardar</button>
                            </div>
                        </form>
                    </div>
                </div>
            )
            }

            {/* Modal Actualizar Precios */}
            {showUpdateModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-50">
                            <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                                <Sparkles size={18} className="text-indigo-600" /> Actualizar Precios con IA
                            </h3>
                            <button onClick={() => setShowUpdateModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-sm text-slate-600">
                                La IA analizará tu catálogo y actualizará los precios unitarios basándose en el mercado actual.
                            </p>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ubicación de Referencia</label>
                                <div className="flex gap-2">
                                    <input
                                        value={updateLocation}
                                        onChange={e => setUpdateLocation(e.target.value)}
                                        className="flex-1 border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                                        placeholder="Ej: Ciudad de México, Monterrey..."
                                    />
                                    <button
                                        onClick={handleDetectLocation}
                                        disabled={isDetectingLocation}
                                        className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition border border-slate-200"
                                        title="Usar ubicación actual"
                                    >
                                        {isDetectingLocation ? (
                                            <div className="animate-spin rounded-full h-4 w-4 border-2 border-slate-500 border-t-transparent"></div>
                                        ) : (
                                            <MapPin size={18} />
                                        )}
                                    </button>
                                </div>
                                <p className="text-xs text-slate-400 mt-1">Especifica la ciudad para obtener precios regionales más precisos.</p>
                            </div>

                            <div className="bg-amber-50 border border-amber-100 rounded-lg p-3 text-xs text-amber-800 flex gap-2">
                                <span className="font-bold">Nota:</span>
                                Este proceso puede tomar unos segundos dependiendo del tamaño de tu catálogo.
                            </div>

                            <div className="pt-2 flex gap-3">
                                <button onClick={() => setShowUpdateModal(false)} className="flex-1 px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg transition">Cancelar</button>
                                <button
                                    onClick={confirmUpdatePrices}
                                    className="flex-1 px-4 py-2 bg-indigo-600 text-white font-bold hover:bg-indigo-700 rounded-lg transition shadow-lg shadow-indigo-200"
                                >
                                    Confirmar Actualización
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal de Revisión de Precios */}
            {showReviewModal && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-2xl shadow-xl max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-50 flex-shrink-0">
                            <div>
                                <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                                    <Sparkles size={18} className="text-indigo-600" /> Revisión de Actualizaciones
                                </h3>
                                <p className="text-xs text-indigo-700 mt-1">
                                    Se encontraron {pendingUpdates.length} ajustes de precios para {updateLocation}. Selecciona los que deseas aplicar.
                                </p>
                            </div>
                            <button onClick={() => setShowReviewModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-0">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                                    <tr>
                                        <th className="p-4 w-10">
                                            <input
                                                type="checkbox"
                                                checked={Object.values(selectedUpdates).every(Boolean)}
                                                onChange={() => {
                                                    const allSelected = Object.values(selectedUpdates).every(Boolean);
                                                    const newSelection = {};
                                                    pendingUpdates.forEach(item => newSelection[item.id] = !allSelected);
                                                    setSelectedUpdates(newSelection);
                                                }}
                                                className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                                            />
                                        </th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase">Concepto</th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase text-right">Precio Anterior</th>
                                        <th className="p-4 w-8"></th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase text-right">Nuevo Precio</th>
                                        <th className="p-4 text-xs font-bold text-slate-500 uppercase">Razón / Fuente</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {pendingUpdates.map(item => (
                                        <tr key={item.id} className={`hover:bg-slate-50 transition ${!selectedUpdates[item.id] ? 'opacity-50 grayscale bg-slate-50' : ''}`}>
                                            <td className="p-4">
                                                <input
                                                    type="checkbox"
                                                    checked={!!selectedUpdates[item.id]}
                                                    onChange={() => toggleUpdateSelection(item.id)}
                                                    className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                                                />
                                            </td>
                                            <td className="p-4">
                                                <p className="text-sm font-medium text-slate-800 line-clamp-2">{item.description}</p>
                                                <span className="text-[10px] text-slate-400">{item.unit} | {item.category}</span>
                                            </td>
                                            <td className="p-4 text-right font-mono text-slate-500 text-sm">
                                                {formatCurrency(item.originalPrice)}
                                            </td>
                                            <td className="p-4 text-center text-slate-300">
                                                <ArrowRight size={14} />
                                            </td>
                                            <td className="p-4 text-right">
                                                <div className="flex flex-col items-end">
                                                    <span className="font-mono font-bold text-indigo-600 text-sm">{formatCurrency(item.unitPrice)}</span>
                                                    <span className={`text-[10px] font-bold px-1.5 rounded-full ${item.priceDiff > 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                                                        {item.priceDiff > 0 ? '+' : ''}{item.diffPercent.toFixed(1)}%
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="p-4">
                                                <div className="flex items-start gap-2">
