import { supabase } from '../lib/supabaseClient';
import { systemSettingsService } from './SystemSettingsService';

/**
 * Servicio para manejar planes y límites de usuarios
 */
export class SubscriptionService {
    // Emails con acceso Pro permanente (administradores/desarrolladores)
    static PRO_EMAILS = [
        'isc20350265@gmail.com'
    ];

    // Definición de planes
    static PLANS = {
        FREE: {
            id: 'free',
            name: 'Gratis',
            price: 0,
            limits: {
                budgets: 1,              // 1 presupuesto
                aiGenerations: 3,        // 3 usos de IA
                aiDescriptions: 5,       // 5 descripciones con IA
                aiPriceSuggestions: 10,  // 10 sugerencias de precio
                bitacoraEntries: 1,      // 1 bitácora
                photoReports: 1,         // 1 reporte fotográfico
                pdfExports: 5,           // 5 exportaciones PDF
                catalogItems: 50         // 50 items en catálogo
            }
        },
        PRO: {
            id: 'pro',
            name: 'Pro',
            price: 299, // MXN por mes
            limits: {
                budgets: -1,             // Ilimitado
                aiGenerations: -1,       // Ilimitado
                aiDescriptions: -1,      // Ilimitado
                aiPriceSuggestions: -1,  // Ilimitado
                bitacoraEntries: -1,     // Ilimitado
                photoReports: -1,       // Ilimitado
                pdfExports: -1,         // Ilimitado
                catalogItems: -1         // Ilimitado
            }
        }
    };

    /**
     * Obtener datos completos de precios y planes (para el modal)
     */
    static async getPricingData() {
        // Asegurar que tenemos settings cargados
        const settings = await systemSettingsService.getAllSettings();

        return {
            pro: {
                price: parseFloat(settings.plan_pro_price),
                description: settings.plan_pro_description,
                features: settings.plan_pro_features
            },
            free: {
                price: 0,
                description: settings.plan_free_description,
                features: settings.plan_free_features
            },
            bankDetails: settings.bank_details
        };
    };

    /**
     * Obtener el plan del usuario
     */
    /**
     * Verificar si un email tiene acceso Pro permanente
     */
    static isProEmail(email) {
        if (!email) return false;
        return this.PRO_EMAILS.includes(email.toLowerCase());
    }

    static async getUserPlan(userId) {
        try {
            // Obtener configuración dinámica
            const settings = await systemSettingsService.getAllSettings();
            const proPrice = settings.plan_pro_price || this.PLANS.PRO.price;
            const proLimits = settings.plan_pro_limits || {};

            // Preparar objeto de Plan Pro Dinámico
            const dynamicProPlan = {
                ...this.PLANS.PRO,
                price: proPrice,
                limits: {
                    ...this.PLANS.PRO.limits,
                    ...proLimits
                }
            };

            // Primero verificar si el usuario tiene un email Pro
            const { data: userData } = await supabase.auth.getUser();
            if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                return dynamicProPlan;
            }

            const { data, error } = await supabase
                .from('user_subscriptions')
                .select('*')
                .eq('user_id', userId)
                .maybeSingle();

            if (error) {
                console.error('Error getting user plan:', error);
                // Si hay error pero el email es Pro, devolver Pro
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    return dynamicProPlan;
                }
                return this.PLANS.FREE;
            }

            if (!data) {
                // Usuario nuevo, verificar si es email Pro
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    return dynamicProPlan;
                }
                // Asignar plan gratuito
                await this.setUserPlan(userId, 'free');
                return this.PLANS.FREE;
            }

            // Verificar si la suscripción está activa
            if (data.plan === 'pro') {
                const now = new Date();
                const expiresAt = new Date(data.expires_at);

                if (expiresAt < now) {
                    // Verificar si es email Pro antes de degradar
                    if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                        return dynamicProPlan;
                    }
                    // Suscripción expirada, cambiar a free
                    await this.setUserPlan(userId, 'free');
                    return this.PLANS.FREE;
                }
                // Retornar Pro dinámico si coincide
                return dynamicProPlan;
            }

            return this.PLANS[data.plan.toUpperCase()] || this.PLANS.FREE;
        } catch (error) {
            console.error('Error getting user plan:', error);
            // Intentar verificar email Pro incluso en caso de error
            try {
                const { data: userData } = await supabase.auth.getUser();
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    // Volver a calcular dinámico por si acaso (aunque debería estar en scope)
                    const settings = await systemSettingsService.getAllSettings();
                    return {
                        ...this.PLANS.PRO,
                        price: settings.plan_pro_price || this.PLANS.PRO.price,
                        limits: { ...this.PLANS.PRO.limits, ...(settings.plan_pro_limits || {}) }
                    };
                }
            } catch (e) {
                // Ignorar error secundario
            }
            return this.PLANS.FREE;
        }
    }

    /**
     * Establecer el plan del usuario
     */
    static async setUserPlan(userId, planId, expiresAt = null) {
        try {
            const planData = {
                user_id: userId,
                plan: planId,
                expires_at: expiresAt || (planId === 'pro' ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() : null),
                updated_at: new Date().toISOString()
            };

            const { error } = await supabase
                .from('user_subscriptions')
                .upsert(planData, { onConflict: 'user_id' });

            if (error) throw error;
            return true;
        } catch (error) {
            console.error('Error setting user plan:', error);
            return false;
        }
    }

    /**
     * Obtener el uso actual del usuario
     */
    static async getUserUsage(userId) {
        try {
            const { data, error } = await supabase
                .from('user_usage')
                .select('*')
                .eq('user_id', userId)
                .maybeSingle();

            if (error) {
                console.error('Error getting user usage:', error);
                return this.getDefaultUsage();
            }

            if (!data) {
                // Crear registro de uso inicial
                const defaultUsage = this.getDefaultUsage();
                await this.initializeUserUsage(userId);
                return defaultUsage;
            }

            // Resetear contadores mensuales si es nuevo mes
            const lastReset = new Date(data.last_reset);
            const now = new Date();
            if (now.getMonth() !== lastReset.getMonth() || now.getFullYear() !== lastReset.getFullYear()) {
                await this.resetMonthlyUsage(userId);
                return this.getDefaultUsage();
            }

            return {
                budgets_created: data.budgets_created || 0,
                ai_generations: data.ai_generations || 0,
                ai_descriptions: data.ai_descriptions || 0,
                ai_price_suggestions: data.ai_price_suggestions || 0,
                bitacora_entries: data.bitacora_entries || 0,
                photo_reports: data.photo_reports || 0,
                pdf_exports: data.pdf_exports || 0,
                catalog_items: data.catalog_items || 0
            };
        } catch (error) {
            console.error('Error getting user usage:', error);
            return this.getDefaultUsage();
        }
    }

    /**
     * Inicializar uso del usuario
     */
    static async initializeUserUsage(userId) {
        try {
            const { error } = await supabase
                .from('user_usage')
                .insert({
                    user_id: userId,
                    last_reset: new Date().toISOString()
                });

            if (error) throw error;
        } catch (error) {
            console.error('Error initializing user usage:', error);
        }
    }

    /**
     * Resetear uso mensual
     */
    static async resetMonthlyUsage(userId) {
        try {
            const { error } = await supabase
                .from('user_usage')
                .update({
                    budgets_created: 0,
                    ai_generations: 0,
                    ai_descriptions: 0,
                    ai_price_suggestions: 0,
                    bitacora_entries: 0,
                    photo_reports: 0,
                    pdf_exports: 0,
                    catalog_items: 0,
                    last_reset: new Date().toISOString()
                })
                .eq('user_id', userId);

            if (error) throw error;
        } catch (error) {
            console.error('Error resetting monthly usage:', error);
        }
    }

    /**
     * Incrementar contador de uso
     */
    static async incrementUsage(userId, type) {
        try {
            const { error } = await supabase.rpc('increment_user_usage', {
                p_user_id: userId,
                p_type: type
            });

            // Si la función RPC no existe, usar update manual
            if (error && error.message.includes('function')) {
                const usage = await this.getUserUsage(userId);
                const newValue = (usage[type] || 0) + 1;

                const { error: updateError } = await supabase
                    .from('user_usage')
                    .update({ [type]: newValue })
                    .eq('user_id', userId);

                if (updateError) throw updateError;
            } else if (error) {
                throw error;
            }
        } catch (error) {
            console.error('Error incrementing usage:', error);
        }
    }

    /**
     * Verificar si el usuario puede realizar una acción
     */
    static async canPerformAction(userId, actionType) {
        // Verificar primero si es un email Pro
        try {
            const { data: userData } = await supabase.auth.getUser();
            if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                return { allowed: true, remaining: -1, limit: -1, current: 0 };
            }
        } catch (e) {
            // Continuar con verificación normal
        }

        const plan = await this.getUserPlan(userId);
        const usage = await this.getUserUsage(userId);

        const limit = plan.limits[actionType];
        const current = usage[actionType] || 0;

        // -1 significa ilimitado
        if (limit === -1) return { allowed: true, remaining: -1 };

        const remaining = limit - current;
        return {
            allowed: remaining > 0,
            remaining: Math.max(0, remaining),
            limit,
            current
        };
    }

    /**
     * Obtener uso por defecto
     */
    static getDefaultUsage() {
        return {
            budgets_created: 0,
            ai_generations: 0,
            ai_descriptions: 0,
            ai_price_suggestions: 0,
            bitacora_entries: 0,
            photo_reports: 0,
            pdf_exports: 0,
            catalog_items: 0
        };
    }

    /**
     * Obtener mensaje de límite alcanzado
     */
    static getLimitMessage(actionType, plan) {
        const messages = {
            budgets: 'Has alcanzado el límite de presupuestos. ¡Actualiza a Pro para crear ilimitados!',
            aiGenerations: 'Has alcanzado el límite de generaciones con IA. ¡Actualiza a Pro para uso ilimitado!',
            aiDescriptions: 'Has alcanzado el límite de descripciones con IA. ¡Actualiza a Pro para uso ilimitado!',
            aiPriceSuggestions: 'Has alcanzado el límite de sugerencias de precio. ¡Actualiza a Pro para uso ilimitado!',
            bitacoraEntries: 'Has alcanzado el límite de bitácoras. ¡Actualiza a Pro para crear ilimitadas!',
            photoReports: 'Has alcanzado el límite de reportes fotográficos. ¡Actualiza a Pro para crear ilimitados!',
            pdfExports: 'Has alcanzado el límite de exportaciones PDF. ¡Actualiza a Pro para exportaciones ilimitadas!',
            catalogItems: 'Has alcanzado el límite de items en catálogo. ¡Actualiza a Pro para catálogo ilimitado!'
        };

        return messages[actionType] || 'Has alcanzado el límite de esta funcionalidad. ¡Actualiza a Pro!';
    }
}

import React, { useState } from 'react';
import { X, Lock, Eye, EyeOff, CheckCircle, AlertCircle } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';

const ChangePasswordModal = ({ isOpen, onClose }) => {
    const { updatePassword } = useAuth();
    const [formData, setFormData] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [showPasswords, setShowPasswords] = useState({
        current: false,
        new: false,
        confirm: false
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);

    // Validación de contraseña segura
    const validatePassword = (password) => {
        const validations = {
            length: password.length >= 12,
            uppercase: /[A-Z]/.test(password),
            lowercase: /[a-z]/.test(password),
            number: /[0-9]/.test(password),
            special: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)
        };

        const strength = Object.values(validations).filter(Boolean).length;
        const strengthLevel = strength <= 2 ? 'débil' : strength <= 4 ? 'media' : 'fuerte';

        return {
            valid: validations.length && validations.uppercase && validations.lowercase && validations.number,
            validations,
            strength,
            strengthLevel
        };
    };

    const passwordValidation = formData.newPassword ? validatePassword(formData.newPassword) : null;

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setSuccess(false);

        // Validaciones
        if (!formData.currentPassword) {
            setError('Ingresa tu contraseña actual');
            return;
        }

        if (!formData.newPassword) {
            setError('Ingresa una nueva contraseña');
            return;
        }

        if (!passwordValidation?.valid) {
            setError('La nueva contraseña no cumple con los requisitos de seguridad');
            return;
        }

        if (formData.newPassword !== formData.confirmPassword) {
            setError('Las contraseñas no coinciden');
            return;
        }

        if (formData.currentPassword === formData.newPassword) {
            setError('La nueva contraseña debe ser diferente a la actual');
            return;
        }

        setLoading(true);
        try {
            const { error: updateError } = await updatePassword(formData.newPassword);
            
            if (updateError) {
                // Si el error es de autenticación, puede ser que necesite reautenticarse
                if (updateError.message.includes('password') || updateError.message.includes('auth')) {
                    setError('Error al actualizar la contraseña. Asegúrate de que tu contraseña actual sea correcta.');
                } else {
                    setError(updateError.message || 'Error al actualizar la contraseña');
                }
                setLoading(false);
                return;
            }

            setSuccess(true);
            setFormData({ currentPassword: '', newPassword: '', confirmPassword: '' });
            
            // Cerrar modal después de 2 segundos
            setTimeout(() => {
                onClose();
                setSuccess(false);
            }, 2000);
        } catch (err) {
            setError('Error inesperado al actualizar la contraseña');
            console.error('Error updating password:', err);
        } finally {
            setLoading(false);
        }
    };

    const handleClose = () => {
        setFormData({ currentPassword: '', newPassword: '', confirmPassword: '' });
        setError('');
        setSuccess(false);
        onClose();
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-gradient-to-r from-blue-600 to-blue-700 text-white">
                    <h3 className="font-bold text-lg flex items-center">
                        <Lock className="mr-2" size={20} /> Cambiar Contraseña
                    </h3>
                    <button
                        onClick={handleClose}
                        className="text-white/60 hover:text-white hover:bg-white/10 p-1 rounded-full transition"
                    >
                        <X size={20} />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {success ? (
                        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-4 flex items-center gap-3">
                            <CheckCircle className="text-emerald-600" size={20} />
                            <div>
                                <p className="font-bold text-emerald-800">Contraseña actualizada exitosamente</p>
                                <p className="text-sm text-emerald-600">El modal se cerrará automáticamente...</p>
                            </div>
                        </div>
                    ) : (
                        <>
                            {error && (
                                <div className="bg-red-50 border border-red-200 rounded-lg p-3 flex items-center gap-2">
                                    <AlertCircle className="text-red-600" size={18} />
                                    <p className="text-sm text-red-700">{error}</p>
                                </div>
                            )}

                            {/* Contraseña Actual */}
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                    Contraseña Actual
                                </label>
                                <div className="relative">
                                    <input
                                        type={showPasswords.current ? 'text' : 'password'}
                                        value={formData.currentPassword}
                                        onChange={(e) => setFormData({ ...formData, currentPassword: e.target.value })}
                                        className="w-full px-4 py-2.5 pr-10 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                                        placeholder="Ingresa tu contraseña actual"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPasswords({ ...showPasswords, current: !showPasswords.current })}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                    >
                                        {showPasswords.current ? <EyeOff size={18} /> : <Eye size={18} />}
                                    </button>
                                </div>
                            </div>

                            {/* Nueva Contraseña */}
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                    Nueva Contraseña
                                </label>
                                <div className="relative">
                                    <input
                                        type={showPasswords.new ? 'text' : 'password'}
                                        value={formData.newPassword}
                                        onChange={(e) => setFormData({ ...formData, newPassword: e.target.value })}
                                        className="w-full px-4 py-2.5 pr-10 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                                        placeholder="Ingresa tu nueva contraseña"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPasswords({ ...showPasswords, new: !showPasswords.new })}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                    >
                                        {showPasswords.new ? <EyeOff size={18} /> : <Eye size={18} />}
                                    </button>
                                </div>

                                {/* Indicador de Fortaleza */}
                                {formData.newPassword && passwordValidation && (
                                    <div className="mt-2 space-y-2">
                                        <div className="flex items-center justify-between text-xs">
                                            <span className="text-slate-500">Fortaleza:</span>
                                            <span className={`font-bold ${
                                                passwordValidation.strengthLevel === 'fuerte' ? 'text-emerald-600' :
                                                passwordValidation.strengthLevel === 'media' ? 'text-amber-600' :
                                                'text-red-600'
                                            }`}>
                                                {passwordValidation.strengthLevel.toUpperCase()}
                                            </span>
                                        </div>
                                        <div className="h-1.5 bg-slate-200 rounded-full overflow-hidden">
                                            <div
                                                className={`h-full transition-all ${
                                                    passwordValidation.strength <= 2 ? 'bg-red-500' :
                                                    passwordValidation.strength <= 4 ? 'bg-amber-500' :
                                                    'bg-emerald-500'
                                                }`}
                                                style={{ width: `${(passwordValidation.strength / 5) * 100}%` }}
                                            />
                                        </div>
                                        <div className="space-y-1 text-xs">
                                            <div className={`flex items-center gap-2 ${passwordValidation.validations.length ? 'text-emerald-600' : 'text-slate-400'}`}>
                                                {passwordValidation.validations.length ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
                                                <span>Mínimo 12 caracteres</span>
                                            </div>
                                            <div className={`flex items-center gap-2 ${passwordValidation.validations.uppercase ? 'text-emerald-600' : 'text-slate-400'}`}>
                                                {passwordValidation.validations.uppercase ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
                                                <span>Al menos una mayúscula</span>
                                            </div>
                                            <div className={`flex items-center gap-2 ${passwordValidation.validations.lowercase ? 'text-emerald-600' : 'text-slate-400'}`}>
                                                {passwordValidation.validations.lowercase ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
                                                <span>Al menos una minúscula</span>
                                            </div>
                                            <div className={`flex items-center gap-2 ${passwordValidation.validations.number ? 'text-emerald-600' : 'text-slate-400'}`}>
                                                {passwordValidation.validations.number ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
                                                <span>Al menos un número</span>
                                            </div>
                                            <div className={`flex items-center gap-2 ${passwordValidation.validations.special ? 'text-emerald-600' : 'text-slate-400'}`}>
                                                {passwordValidation.validations.special ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
                                                <span>Al menos un carácter especial (opcional)</span>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Confirmar Contraseña */}
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                    Confirmar Nueva Contraseña
                                </label>
                                <div className="relative">
                                    <input
                                        type={showPasswords.confirm ? 'text' : 'password'}
                                        value={formData.confirmPassword}
                                        onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                                        className={`w-full px-4 py-2.5 pr-10 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none ${
                                            formData.confirmPassword && formData.newPassword !== formData.confirmPassword
                                                ? 'border-red-300 focus:border-red-500'
                                                : formData.confirmPassword && formData.newPassword === formData.confirmPassword
                                                ? 'border-emerald-300 focus:border-emerald-500'
                                                : 'border-slate-200 focus:border-blue-500'
                                        }`}
                                        placeholder="Confirma tu nueva contraseña"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPasswords({ ...showPasswords, confirm: !showPasswords.confirm })}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                    >
                                        {showPasswords.confirm ? <EyeOff size={18} /> : <Eye size={18} />}
                                    </button>
                                </div>
                                {formData.confirmPassword && formData.newPassword === formData.confirmPassword && (
                                    <p className="mt-1 text-xs text-emerald-600 flex items-center gap-1">
                                        <CheckCircle size={12} /> Las contraseñas coinciden
                                    </p>
                                )}
                            </div>

                            <div className="flex gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={handleClose}
                                    className="flex-1 px-4 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg font-bold transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="submit"
                                    disabled={loading || !passwordValidation?.valid || formData.newPassword !== formData.confirmPassword}
                                    className="flex-1 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white rounded-lg font-bold transition shadow-lg shadow-blue-900/20"
                                >
                                    {loading ? 'Actualizando...' : 'Actualizar Contraseña'}
                                </button>
                            </div>
                        </>
                    )}
                </form>
            </div>
        </div>
    );
};

export default ChangePasswordModal;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { supabase } from '../lib/supabaseClient';
import { setSentryUser, clearSentryUser } from '../lib/sentry';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check active session
        supabase.auth.getSession().then(({ data: { session } }) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);
            setLoading(false);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            }
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            } else {
                clearSentryUser();
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    const signUp = async (email, password, metadata = {}) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
                data: metadata,
                emailRedirectTo: `${baseUrl}/confirm-email`
            }
        });
        return { data, error };
    };

    const signIn = async (email, password) => {
        const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
        });
        return { data, error };
    };

    const signOut = async () => {
        // Limpiar estado inmediatamente para evitar race conditions antes de la navegación
        setUser(null);

        const { error } = await supabase.auth.signOut();

        // Limpiar usuario de Sentry
        clearSentryUser();

        return { error };
    };

    const resetPassword = async (email) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${baseUrl}/confirm-email`
        });
        return { data, error };
    };

    const updatePassword = async (newPassword) => {
        const { data, error } = await supabase.auth.updateUser({
            password: newPassword
        });
        return { data, error };
    };

    const value = {
        user,
        loading,
        signUp,
        signIn,
        signOut,
        resetPassword,
        updatePassword
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';

// 1 Hora en milisegundos
const INACTIVITY_LIMIT_MS = 60 * 60 * 1000;

const InactivityHandler = () => {
    const { user, signOut } = useAuth();
    const navigate = useNavigate();
    const timerRef = useRef(null);

    const handleLogout = useCallback(async () => {
        if (user) {
            console.log('Sesión cerrada automáticamente por inactividad');
            await signOut();
            // Redirigir a login con un parámetro para (opcionalmente) mostrar un mensaje
            navigate('/login?reason=inactivity', { replace: true });
        }
    }, [user, signOut, navigate]);

    const resetTimer = useCallback(() => {
        if (timerRef.current) {
            clearTimeout(timerRef.current);
        }
        if (user) {
            timerRef.current = setTimeout(handleLogout, INACTIVITY_LIMIT_MS);
        }
    }, [user, handleLogout]);

    useEffect(() => {
        // Solo activar si hay un usuario logueado
        if (!user) return;

        // Eventos a monitorear
        const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];

        // Handler para eventos de actividad
        // Usamos un throttle simple para no llamar a resetTimer en cada pixel de movimiento
        let lastReset = Date.now();
        const handleActivity = () => {
            const now = Date.now();
            // Solo reiniciar si ha pasado más de 1 segundo desde el último reinicio
            // para mejorar el rendimiento
            if (now - lastReset > 1000) {
                resetTimer();
                lastReset = now;
            }
        };

        // Iniciar timer inicial
        resetTimer();

        // Agregar listeners globales
        events.forEach(event => {
            window.addEventListener(event, handleActivity);
        });

        // Cleanup al desmontar o cambiar de usuario
        return () => {
            if (timerRef.current) clearTimeout(timerRef.current);
            events.forEach(event => {
                window.removeEventListener(event, handleActivity);
            });
        };
    }, [user, resetTimer]);

    return null; // Este componente no renderiza nada visualmente
};

export default InactivityHandler;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { supabase } from '../lib/supabaseClient';
import { setSentryUser, clearSentryUser } from '../lib/sentry';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check active session
        supabase.auth.getSession().then(({ data: { session } }) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);
            setLoading(false);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            }
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            } else {
                clearSentryUser();
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    const signUp = async (email, password, metadata = {}) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
                data: metadata,
                emailRedirectTo: `${baseUrl}/confirm-email`
            }
        });
        return { data, error };
    };

    const signIn = async (email, password) => {
        const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
        });
        return { data, error };
    };

    const signOut = async () => {
        // Limpiar estado inmediatamente para evitar race conditions antes de la navegación
        setUser(null);

        const { error } = await supabase.auth.signOut();

        // Limpiar usuario de Sentry
        clearSentryUser();

        return { error };
    };

    const resetPassword = async (email) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${baseUrl}/confirm-email`
        });
        return { data, error };
    };

    const updatePassword = async (newPassword) => {
        const { data, error } = await supabase.auth.updateUser({
            password: newPassword
        });
        return { data, error };
    };

    const value = {
        user,
        loading,
        signUp,
        signIn,
        signOut,
        resetPassword,
        updatePassword
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { useState } from 'react';
import { X, BookOpen, Save, Calendar } from 'lucide-react';
import BitacoraService from '../../services/BitacoraService';

const DiaryEntryModal = ({ isOpen, onClose, projectId, onSave, editingEntry = null }) => {
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [content, setContent] = useState('');
    const [authorName, setAuthorName] = useState('');
    const [authorRole, setAuthorRole] = useState('Residente');
    const [authorSignature, setAuthorSignature] = useState('');
    const [uploading, setUploading] = useState(false);
    const [noteNumber, setNoteNumber] = useState(null);

    // Cargar datos si se está editando
    React.useEffect(() => {
        if (isOpen && editingEntry) {
            const entryDate = editingEntry.log_date ? new Date(editingEntry.log_date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0];
            setDate(entryDate);
            setContent(editingEntry.content || '');
            setAuthorName(editingEntry.author_name || '');
            setAuthorRole(editingEntry.author_role || 'Residente');
            setAuthorSignature(editingEntry.author_signature || '');
        } else if (isOpen && !editingEntry) {
            // Resetear para nueva entrada
            setDate(new Date().toISOString().split('T')[0]);
            setContent('');
            setAuthorName('');
            setAuthorRole('Residente');
            setAuthorSignature('');
        }
    }, [isOpen, editingEntry]);

    // Obtener número de nota
    React.useEffect(() => {
        if (isOpen && projectId && !editingEntry) {
            const fetchNextNoteNumber = async () => {
                try {
                    const nextNumber = await BitacoraService.getNextNoteNumber(projectId);
                    setNoteNumber(nextNumber);
                } catch (error) {
                    console.error('Error fetching note number:', error);
                    setNoteNumber(1);
                }
            };
            fetchNextNoteNumber();
        } else if (editingEntry) {
            setNoteNumber(editingEntry.note_number);
        }
    }, [isOpen, projectId, editingEntry]);

    if (!isOpen) return null;

    const handleSubmit = async () => {
        if (!projectId) {
            alert('Error: No se encontró el ID del proyecto');
            return;
        }

        if (!content.trim()) {
            alert('Por favor, escribe el contenido del diario');
            return;
        }

        if (!authorName.trim()) {
            alert('Por favor, ingresa el nombre del autor');
            return;
        }

        setUploading(true);
        try {
            const logDate = new Date(date + 'T12:00:00').toISOString();

            if (editingEntry && editingEntry.id) {
                // Actualizar entrada existente
                await BitacoraService.updateLog(editingEntry.id, {
                    content,
                    logDate,
                    authorName,
                    authorRole,
                    authorSignature,
                    classification: 'Informe',
                    subject: `Diario de Obra - ${new Date(date).toLocaleDateString('es-MX')}`,
                    isDiaryEntry: true
                });
            } else {
                // Crear nueva entrada
                await BitacoraService.createLog({
                    projectId,
                    taskId: 'diary',
                    content,
                    progressPercentage: 0,
                    photos: [],
                    subject: `Diario de Obra - ${new Date(date).toLocaleDateString('es-MX')}`,
                    classification: 'Informe',
                    authorRole,
                    status: 'Abierta',
                    logDate,
                    noteNumber,
                    authorName,
                    authorSignature,
                    isDiaryEntry: true
                });
            }

            onSave();
            onClose();
            
            // Resetear formulario
            setDate(new Date().toISOString().split('T')[0]);
            setContent('');
            setAuthorName('');
            setAuthorRole('Residente');
            setAuthorSignature('');
        } catch (error) {
            console.error('Error saving diary entry:', error);
            alert('Error al guardar la entrada del diario: ' + error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-800 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-lg">
                            <BookOpen className="mr-2" size={20} /> 
                            {editingEntry ? 'Editar' : 'Nueva'} Entrada de Diario
                        </h3>
                        <p className="text-xs text-slate-400 mt-1">
                            Folio #{noteNumber || '...'} • Registro diario de actividades
                        </p>
                    </div>
                    <button onClick={onClose} className="text-white/60 hover:text-white">
                        <X size={24} />
                    </button>
                </div>

                <div className="p-6 space-y-5 overflow-y-auto flex-1">
                    {/* Fecha */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                            Fecha del Registro <span className="text-red-500">*</span>
                        </label>
                        <div className="relative">
                            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                            <input
                                type="date"
                                value={date}
                                onChange={(e) => setDate(e.target.value)}
                                className="w-full pl-10 bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm font-medium text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500"
                            />
                        </div>
                    </div>

                    {/* Contenido del Diario */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                            Registro de Actividades <span className="text-red-500">*</span>
                        </label>
                        <textarea
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            className="w-full p-4 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-64 text-sm leading-relaxed"
                            placeholder="Describe las actividades realizadas durante el día, trabajos ejecutados, observaciones, incidencias, personal presente, materiales utilizados, etc..."
                        />
                    </div>

                    {/* Información del Autor */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4 border-t border-slate-100">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                Nombre del Autor <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                value={authorName}
                                onChange={(e) => setAuthorName(e.target.value)}
                                className="w-full font-medium text-slate-800 border-b-2 border-slate-200 focus:border-indigo-500 outline-none py-2 px-1 transition"
                                placeholder="Ej: Ing. Juan Pérez"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                                Cargo / Rol
                            </label>
                            <div className="flex gap-3">
                                {['Supervisor', 'Residente', 'Superintendente', 'Otro'].map(role => (
                                    <button
                                        key={role}
                                        onClick={() => setAuthorRole(role)}
                                        className={`px-3 py-1.5 rounded-full text-xs font-bold border transition ${
                                            authorRole === role
                                                ? 'bg-indigo-50 border-indigo-200 text-indigo-700'
                                                : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'
                                        }`}
                                    >
                                        {role}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Firma */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                            Firma (Opcional)
                        </label>
                        <input
                            type="text"
                            value={authorSignature}
                            onChange={(e) => setAuthorSignature(e.target.value)}
                            className="w-full font-medium text-slate-800 border-b-2 border-slate-200 focus:border-indigo-500 outline-none py-2 px-1 transition"
                            placeholder="Firma digital o nombre para firmar"
                        />
                        <p className="text-xs text-slate-400 mt-1">
                            Este campo aparecerá como firma en el PDF del diario
                        </p>
                    </div>
                </div>

                <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-2">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition"
                    >
                        Cancelar
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={uploading}
                        className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold transition flex items-center shadow-lg shadow-indigo-200 disabled:opacity-50"
                    >
                        {uploading ? 'Guardando...' : <><Save size={18} className="mr-2" /> Guardar Entrada</>}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default DiaryEntryModal;

/**
 * BitacoraService
 * Servicio centralizado para gestión de bitácora de obra
 * Maneja logs, notas, avances y evidencias fotográficas
 */

import { supabase } from '../lib/supabaseClient';

export class BitacoraService {
    /**
     * Carga todos los logs de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Array de logs ordenados por fecha
     */
    static async loadLogs(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error loading logs:', error);
            throw error;
        }
    }

    /**
     * Carga el cronograma de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Cronograma o null
     */
    static async loadSchedule(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('project_schedules')
                .select('*')
                .eq('project_id', projectId)
                .maybeSingle();

            if (error && error.code !== 'PGRST116') throw error;
            return data || null;
        } catch (error) {
            console.error('Error loading schedule:', error);
            throw error;
        }
    }

    /**
     * Obtiene el siguiente número de folio para un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<number>} - Siguiente número de folio
     */
    static async getNextNoteNumber(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { count, error } = await supabase
                .from('site_logs')
                .select('*', { count: 'exact', head: true })
                .eq('project_id', projectId);

            if (error) throw error;
            return (count || 0) + 1;
        } catch (error) {
            console.error('Error getting next note number:', error);
            throw error;
        }
    }

    /**
     * Crea una nueva nota de bitácora
     * @param {Object} logData - Datos de la nota
     * @returns {Promise<Object>} - Nota creada
     */
    static async createLog(logData) {
        const {
            projectId,
            taskId,
            content,
            progressPercentage = 0,
            photos = [],
            subject,
            classification = 'Informe',
            authorRole = 'Residente',
            status = 'Abierta',
            noteNumber = null,
            logDate = null, // Fecha opcional del log (para reportes fotográficos)
            authorName = null, // Para entradas de diario
            authorSignature = null, // Para entradas de diario
            isDiaryEntry = false, // Flag para identificar entradas de diario
            metadata = null // Metadata adicional (clima, materiales, personal, observaciones)
        } = logData;

        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        if (!subject || !subject.trim()) {
            throw new Error('Subject is required');
        }

        try {
            // Obtener número de folio si no se proporciona
            const finalNoteNumber = noteNumber || await this.getNextNoteNumber(projectId);

            // Para entradas de diario, guardar metadata en el content con formato especial
            let finalContent = content || '';
            if (isDiaryEntry && (authorName || authorSignature)) {
                const diaryMetadata = {
                    authorName: authorName || '',
                    authorSignature: authorSignature || '',
                    isDiaryEntry: true
                };
                // Guardar metadata al final del content con un separador especial
                finalContent = content + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
            } else if (metadata && Object.keys(metadata).length > 0) {
                // Para bitácora normal, guardar metadata (clima, materiales, personal, observaciones)
                finalContent = content + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(metadata) + '-->';
            }

            const { data, error } = await supabase
                .from('site_logs')
                .insert([{
                    project_id: projectId,
                    task_id: taskId,
                    content: finalContent,
                    progress_percentage: progressPercentage,
                    photos: Array.isArray(photos) ? photos : [photos].filter(Boolean),
                    log_date: logDate || new Date().toISOString(), // Usar fecha proporcionada o actual
                    note_number: finalNoteNumber,
                    classification,
                    author_role: authorRole,
                    status,
                    subject: subject.trim()
                }])
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error creating log:', error);
            throw error;
        }
    }

    /**
     * Actualiza una nota existente
     * @param {string} logId - ID de la nota
     * @param {Object} updates - Campos a actualizar
     * @returns {Promise<Object>} - Nota actualizada
     */
    static async updateLog(logId, updates) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const updateData = {};
            
            // Manejar contenido con metadata de diario o bitácora
            if (updates.content !== undefined) {
                let finalContent = updates.content;
                if (updates.isDiaryEntry && (updates.authorName || updates.authorSignature)) {
                    const diaryMetadata = {
                        authorName: updates.authorName || '',
                        authorSignature: updates.authorSignature || '',
                        isDiaryEntry: true
                    };
                    // Remover metadata anterior si existe
                    finalContent = finalContent.replace(/\n\n<!--DIARY_METADATA:.*?-->/, '');
                    // Agregar nueva metadata
                    finalContent = finalContent + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
                } else if (updates.metadata && Object.keys(updates.metadata).length > 0) {
                    // Para bitácora normal, guardar metadata
                    finalContent = finalContent.replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '');
                    finalContent = finalContent + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(updates.metadata) + '-->';
                }
                updateData.content = finalContent;
            }
            if (updates.progressPercentage !== undefined) updateData.progress_percentage = updates.progressPercentage;
            if (updates.photos !== undefined) updateData.photos = Array.isArray(updates.photos) ? updates.photos : [updates.photos].filter(Boolean);
            if (updates.subject !== undefined) updateData.subject = updates.subject;
            if (updates.classification !== undefined) updateData.classification = updates.classification;
            if (updates.authorRole !== undefined) updateData.author_role = updates.authorRole;
            if (updates.status !== undefined) updateData.status = updates.status;
            if (updates.logDate !== undefined) updateData.log_date = updates.logDate;

            const { data, error } = await supabase
                .from('site_logs')
                .update(updateData)
                .eq('id', logId)
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error updating log:', error);
            throw error;
        }
    }

    /**
     * Elimina una nota
     * @param {string} logId - ID de la nota
     */
    static async deleteLog(logId) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const { error } = await supabase
                .from('site_logs')
                .delete()
                .eq('id', logId);

            if (error) throw error;
        } catch (error) {
            console.error('Error deleting log:', error);
            throw error;
        }
    }

    /**
     * Obtiene los logs de una tarea específica
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<Array>} - Logs de la tarea
     */
    static async getTaskLogs(projectId, taskId) {
        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .eq('task_id', taskId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error getting task logs:', error);
            throw error;
        }
    }

    /**
     * Calcula el avance de una tarea basado en sus logs
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<number>} - Porcentaje de avance (0-100)
     */
    static async getTaskProgress(projectId, taskId) {
        const logs = await this.getTaskLogs(projectId, taskId);
        if (logs.length === 0) return 0;
        
        // Retornar el avance más reciente
        return logs[0].progress_percentage || 0;
    }

    /**
     * Obtiene estadísticas de la bitácora
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object>} - Estadísticas
     */
    static async getStatistics(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const logs = await this.loadLogs(projectId);

            const stats = {
                totalLogs: logs.length,
                openLogs: logs.filter(l => l.status === 'Abierta').length,
                closedLogs: logs.filter(l => l.status === 'Cerrada').length,
                byClassification: {},
                byAuthorRole: {},
                totalPhotos: 0,
                averageProgress: 0
            };

            let totalProgress = 0;
            logs.forEach(log => {
                // Por clasificación
                stats.byClassification[log.classification] = 
                    (stats.byClassification[log.classification] || 0) + 1;

                // Por rol de autor
                stats.byAuthorRole[log.author_role] = 
                    (stats.byAuthorRole[log.author_role] || 0) + 1;

                // Fotos
                if (log.photos && Array.isArray(log.photos)) {
                    stats.totalPhotos += log.photos.length;
                }

                // Progreso
                totalProgress += log.progress_percentage || 0;
            });

            stats.averageProgress = logs.length > 0 
                ? Math.round(totalProgress / logs.length) 
                : 0;

            return stats;
        } catch (error) {
            console.error('Error getting statistics:', error);
            throw error;
        }
    }

    /**
     * Valida datos de una nota antes de guardar
     * @param {Object} logData - Datos a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateLogData(logData) {
        const errors = [];

        if (!logData.projectId) errors.push('Project ID is required');
        if (!logData.taskId) errors.push('Task ID is required');
        if (!logData.subject || !logData.subject.trim()) {
            errors.push('Subject is required');
        }

        if (logData.progressPercentage !== undefined) {
            const progress = parseInt(logData.progressPercentage);
            if (isNaN(progress) || progress < 0 || progress > 100) {
                errors.push('Progress must be between 0 and 100');
            }
        }

        const validClassifications = ['Apertura', 'Orden', 'Solicitud', 'Autorización', 'Informe', 'Cierre', 'Otro'];
        if (logData.classification && !validClassifications.includes(logData.classification)) {
            errors.push(`Classification must be one of: ${validClassifications.join(', ')}`);
        }

        const validAuthorRoles = ['Supervisor', 'Residente', 'Superintendente', 'Otro'];
        if (logData.authorRole && !validAuthorRoles.includes(logData.authorRole)) {
            errors.push(`Author role must be one of: ${validAuthorRoles.join(', ')}`);
        }

        const validStatuses = ['Abierta', 'Cerrada'];
        if (logData.status && !validStatuses.includes(logData.status)) {
            errors.push(`Status must be one of: ${validStatuses.join(', ')}`);
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Extrae los metadatos de una entrada de diario del content
     * @param {string} content - Contenido de la entrada
     * @returns {Object|null} - Metadatos del diario o null
     */
    static extractDiaryMetadata(content) {
        if (!content) return null;
        
        const metadataMatch = content.match(/<!--DIARY_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing diary metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Extrae metadata de bitácora del contenido
     * @param {string} content - Contenido con metadata
     * @returns {object|null} - Metadata extraída o null
     */
    static extractBitacoraMetadata(content) {
        if (!content) return null;
        const metadataMatch = content.match(/<!--BITACORA_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing bitacora metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Obtiene el contenido limpio sin metadata
     * @param {string} content - Contenido con metadata
     * @returns {string} - Contenido limpio
     */
    static getCleanContent(content) {
        if (!content) return '';
        return content
            .replace(/\n\n<!--DIARY_METADATA:.*?-->/, '')
            .replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '')
            // También limpiar metadata de descripciones de fotos en reportes fotográficos
            .replace(/\n?\s*<!--PHOTO_CAPTIONS:.*?-->$/s, '')
            .trim();
    }

    /**
     * Verifica si un log es una entrada de diario
     * @param {Object} log - Log a verificar
     * @returns {boolean} - True si es entrada de diario
     */
    static isDiaryEntry(log) {
        if (!log) return false;
        // Verificar por task_id o por metadata en content
        if (log.task_id === 'diary') return true;
        if (log.content && this.extractDiaryMetadata(log.content)) return true;
        return false;
    }
}

