/**
 * BitacoraService
 * Servicio centralizado para gestión de bitácora de obra
 * Maneja logs, notas, avances y evidencias fotográficas
 */

import { supabase } from '../lib/supabaseClient';

export class BitacoraService {
    /**
     * Carga todos los logs de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Array de logs ordenados por fecha
     */
    static async loadLogs(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error loading logs:', error);
            throw error;
        }
    }

    /**
     * Carga el cronograma de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Cronograma o null
     */
    static async loadSchedule(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('project_schedules')
                .select('*')
                .eq('project_id', projectId)
                .maybeSingle();

            if (error && error.code !== 'PGRST116') throw error;
            return data || null;
        } catch (error) {
            console.error('Error loading schedule:', error);
            throw error;
        }
    }

    /**
     * Obtiene el siguiente número de folio para un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<number>} - Siguiente número de folio
     */
    static async getNextNoteNumber(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { count, error } = await supabase
                .from('site_logs')
                .select('*', { count: 'exact', head: true })
                .eq('project_id', projectId);

            if (error) throw error;
            return (count || 0) + 1;
        } catch (error) {
            console.error('Error getting next note number:', error);
            throw error;
        }
    }

    /**
     * Crea una nueva nota de bitácora
     * @param {Object} logData - Datos de la nota
     * @returns {Promise<Object>} - Nota creada
     */
    static async createLog(logData) {
        const {
            projectId,
            taskId,
            content,
            progressPercentage = 0,
            photos = [],
            subject,
            classification = 'Informe',
            authorRole = 'Residente',
            status = 'Abierta',
            noteNumber = null,
            logDate = null, // Fecha opcional del log (para reportes fotográficos)
            authorName = null, // Para entradas de diario
            authorSignature = null, // Para entradas de diario
            isDiaryEntry = false, // Flag para identificar entradas de diario
            metadata = null // Metadata adicional (clima, materiales, personal, observaciones)
        } = logData;

        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        if (!subject || !subject.trim()) {
            throw new Error('Subject is required');
        }

        try {
            // Obtener número de folio si no se proporciona
            const finalNoteNumber = noteNumber || await this.getNextNoteNumber(projectId);

            // Para entradas de diario, guardar metadata en el content con formato especial
            let finalContent = content || '';
            if (isDiaryEntry && (authorName || authorSignature)) {
                const diaryMetadata = {
                    authorName: authorName || '',
                    authorSignature: authorSignature || '',
                    isDiaryEntry: true
                };
                // Guardar metadata al final del content con un separador especial
                finalContent = content + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
            } else if (metadata && Object.keys(metadata).length > 0) {
                // Para bitácora normal, guardar metadata (clima, materiales, personal, observaciones)
                finalContent = content + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(metadata) + '-->';
            }

            const { data, error } = await supabase
                .from('site_logs')
                .insert([{
                    project_id: projectId,
                    task_id: taskId,
                    content: finalContent,
                    progress_percentage: progressPercentage,
                    photos: Array.isArray(photos) ? photos : [photos].filter(Boolean),
                    log_date: logDate || new Date().toISOString(), // Usar fecha proporcionada o actual
                    note_number: finalNoteNumber,
                    classification,
                    author_role: authorRole,
                    status,
                    subject: subject.trim()
                }])
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error creating log:', error);
            throw error;
        }
    }

    /**
     * Actualiza una nota existente
     * @param {string} logId - ID de la nota
     * @param {Object} updates - Campos a actualizar
     * @returns {Promise<Object>} - Nota actualizada
     */
    static async updateLog(logId, updates) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const updateData = {};
            
            // Manejar contenido con metadata de diario o bitácora
            if (updates.content !== undefined) {
                let finalContent = updates.content;
                if (updates.isDiaryEntry && (updates.authorName || updates.authorSignature)) {
                    const diaryMetadata = {
                        authorName: updates.authorName || '',
                        authorSignature: updates.authorSignature || '',
                        isDiaryEntry: true
                    };
                    // Remover metadata anterior si existe
                    finalContent = finalContent.replace(/\n\n<!--DIARY_METADATA:.*?-->/, '');
                    // Agregar nueva metadata
                    finalContent = finalContent + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
                } else if (updates.metadata && Object.keys(updates.metadata).length > 0) {
                    // Para bitácora normal, guardar metadata
                    finalContent = finalContent.replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '');
                    finalContent = finalContent + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(updates.metadata) + '-->';
                }
                updateData.content = finalContent;
            }
            if (updates.progressPercentage !== undefined) updateData.progress_percentage = updates.progressPercentage;
            if (updates.photos !== undefined) updateData.photos = Array.isArray(updates.photos) ? updates.photos : [updates.photos].filter(Boolean);
            if (updates.subject !== undefined) updateData.subject = updates.subject;
            if (updates.classification !== undefined) updateData.classification = updates.classification;
            if (updates.authorRole !== undefined) updateData.author_role = updates.authorRole;
            if (updates.status !== undefined) updateData.status = updates.status;
            if (updates.logDate !== undefined) updateData.log_date = updates.logDate;

            const { data, error } = await supabase
                .from('site_logs')
                .update(updateData)
                .eq('id', logId)
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error updating log:', error);
            throw error;
        }
    }

    /**
     * Elimina una nota
     * @param {string} logId - ID de la nota
     */
    static async deleteLog(logId) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const { error } = await supabase
                .from('site_logs')
                .delete()
                .eq('id', logId);

            if (error) throw error;
        } catch (error) {
            console.error('Error deleting log:', error);
            throw error;
        }
    }

    /**
     * Obtiene los logs de una tarea específica
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<Array>} - Logs de la tarea
     */
    static async getTaskLogs(projectId, taskId) {
        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .eq('task_id', taskId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error getting task logs:', error);
            throw error;
        }
    }

    /**
     * Calcula el avance de una tarea basado en sus logs
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<number>} - Porcentaje de avance (0-100)
     */
    static async getTaskProgress(projectId, taskId) {
        const logs = await this.getTaskLogs(projectId, taskId);
        if (logs.length === 0) return 0;
        
        // Retornar el avance más reciente
        return logs[0].progress_percentage || 0;
    }

    /**
     * Obtiene estadísticas de la bitácora
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object>} - Estadísticas
     */
    static async getStatistics(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const logs = await this.loadLogs(projectId);

            const stats = {
                totalLogs: logs.length,
                openLogs: logs.filter(l => l.status === 'Abierta').length,
                closedLogs: logs.filter(l => l.status === 'Cerrada').length,
                byClassification: {},
                byAuthorRole: {},
                totalPhotos: 0,
                averageProgress: 0
            };

            let totalProgress = 0;
            logs.forEach(log => {
                // Por clasificación
                stats.byClassification[log.classification] = 
                    (stats.byClassification[log.classification] || 0) + 1;

                // Por rol de autor
                stats.byAuthorRole[log.author_role] = 
                    (stats.byAuthorRole[log.author_role] || 0) + 1;

                // Fotos
                if (log.photos && Array.isArray(log.photos)) {
                    stats.totalPhotos += log.photos.length;
                }

                // Progreso
                totalProgress += log.progress_percentage || 0;
            });

            stats.averageProgress = logs.length > 0 
                ? Math.round(totalProgress / logs.length) 
                : 0;

            return stats;
        } catch (error) {
            console.error('Error getting statistics:', error);
            throw error;
        }
    }

    /**
     * Valida datos de una nota antes de guardar
     * @param {Object} logData - Datos a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateLogData(logData) {
        const errors = [];

        if (!logData.projectId) errors.push('Project ID is required');
        if (!logData.taskId) errors.push('Task ID is required');
        if (!logData.subject || !logData.subject.trim()) {
            errors.push('Subject is required');
        }

        if (logData.progressPercentage !== undefined) {
            const progress = parseInt(logData.progressPercentage);
            if (isNaN(progress) || progress < 0 || progress > 100) {
                errors.push('Progress must be between 0 and 100');
            }
        }

        const validClassifications = ['Apertura', 'Orden', 'Solicitud', 'Autorización', 'Informe', 'Cierre', 'Otro'];
        if (logData.classification && !validClassifications.includes(logData.classification)) {
            errors.push(`Classification must be one of: ${validClassifications.join(', ')}`);
        }

        const validAuthorRoles = ['Supervisor', 'Residente', 'Superintendente', 'Otro'];
        if (logData.authorRole && !validAuthorRoles.includes(logData.authorRole)) {
            errors.push(`Author role must be one of: ${validAuthorRoles.join(', ')}`);
        }

        const validStatuses = ['Abierta', 'Cerrada'];
        if (logData.status && !validStatuses.includes(logData.status)) {
            errors.push(`Status must be one of: ${validStatuses.join(', ')}`);
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Extrae los metadatos de una entrada de diario del content
     * @param {string} content - Contenido de la entrada
     * @returns {Object|null} - Metadatos del diario o null
     */
    static extractDiaryMetadata(content) {
        if (!content) return null;
        
        const metadataMatch = content.match(/<!--DIARY_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing diary metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Extrae metadata de bitácora del contenido
     * @param {string} content - Contenido con metadata
     * @returns {object|null} - Metadata extraída o null
     */
    static extractBitacoraMetadata(content) {
        if (!content) return null;
        const metadataMatch = content.match(/<!--BITACORA_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing bitacora metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Obtiene el contenido limpio sin metadata
     * @param {string} content - Contenido con metadata
     * @returns {string} - Contenido limpio
     */
    static getCleanContent(content) {
        if (!content) return '';
        return content
            .replace(/\n\n<!--DIARY_METADATA:.*?-->/, '')
            .replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '')
            // También limpiar metadata de descripciones de fotos en reportes fotográficos
            .replace(/\n?\s*<!--PHOTO_CAPTIONS:.*?-->$/s, '')
            .trim();
    }

    /**
     * Verifica si un log es una entrada de diario
     * @param {Object} log - Log a verificar
     * @returns {boolean} - True si es entrada de diario
     */
    static isDiaryEntry(log) {
        if (!log) return false;
        // Verificar por task_id o por metadata en content
        if (log.task_id === 'diary') return true;
        if (log.content && this.extractDiaryMetadata(log.content)) return true;
        return false;
    }
}

export default BitacoraService;

import React, { useState } from 'react';
import { X, FileText, Save, Cloud, Users, Package, AlertCircle } from 'lucide-react';
import BitacoraService from '../../services/BitacoraService';
import { useSubscription } from '../../context/SubscriptionContext';
import LimitModal from '../subscription/LimitModal';

const LogEntryModal = ({ isOpen, onClose, task, projectId, onSave, editingLog = null }) => {
    const { checkLimit, incrementUsage, isPro } = useSubscription();
    const [content, setContent] = useState('');
    const [progress, setProgress] = useState(0);
    const [uploading, setUploading] = useState(false);
    const [limitModal, setLimitModal] = useState({
        isOpen: false,
        actionType: null,
        usage: 0,
        limit: 0
    });

    // Campos profesionales
    const [subject, setSubject] = useState('');
    const [classification, setClassification] = useState('Informe');
    const [authorRole, setAuthorRole] = useState('Residente');
    const [status, setStatus] = useState('Abierta');
    const [noteNumber, setNoteNumber] = useState(null);
    
    // Campos específicos para bitácora de obra civil
    const [weather, setWeather] = useState(''); // Condiciones climáticas
    const [materials, setMaterials] = useState(''); // Materiales utilizados
    const [personnel, setPersonnel] = useState(''); // Personal utilizado
    const [observations, setObservations] = useState(''); // Observaciones adicionales

    // Cargar datos si se está editando
    React.useEffect(() => {
        if (isOpen && editingLog) {
            // Limpiar contenido de metadata
            const cleanContent = BitacoraService.getCleanContent(editingLog.content || '');
            setContent(cleanContent);
            setProgress(editingLog.progress_percentage || 0);
            setSubject(editingLog.subject || '');
            setClassification(editingLog.classification || 'Informe');
            setAuthorRole(editingLog.author_role || 'Residente');
            setStatus(editingLog.status || 'Abierta');
            setNoteNumber(editingLog.note_number);
            // Cargar campos adicionales (extraer de metadata del contenido)
            const metadata = BitacoraService.extractBitacoraMetadata(editingLog.content) || {};
            setWeather(metadata.weather || '');
            setMaterials(metadata.materials || '');
            setPersonnel(metadata.personnel || '');
            setObservations(metadata.observations || '');
        } else if (isOpen && !editingLog) {
            // Resetear para nueva nota
            setContent('');
            setProgress(task?.progress || 0);
            setSubject('');
            setClassification('Informe');
            setAuthorRole('Residente');
            setStatus('Abierta');
            setWeather('');
            setMaterials('');
            setPersonnel('');
            setObservations('');
        }
    }, [isOpen, editingLog, task]);

    // Fetch next note number on open (solo si no se está editando)
    React.useEffect(() => {
        if (isOpen && projectId && !editingLog) {
            const fetchNextNoteNumber = async () => {
                try {
                    const nextNumber = await BitacoraService.getNextNoteNumber(projectId);
                    setNoteNumber(nextNumber);
                } catch (error) {
                    console.error('Error fetching note number:', error);
                    setNoteNumber(1); // Fallback
                }
            };
            fetchNextNoteNumber();
        } else if (editingLog) {
            setNoteNumber(editingLog.note_number);
        }
    }, [isOpen, projectId, editingLog]);

    if (!isOpen) return null;
    
    // Si no hay task, crear una por defecto
    const taskData = task || { id: 'general', name: 'Nota General', progress: 0 };

    const handleSubmit = async () => {
        if (!projectId) {
            alert('Error: No se encontró el ID del proyecto');
            return;
        }

        // Validar datos
        const validation = BitacoraService.validateLogData({
            projectId,
            taskId: taskData.id,
            subject,
            progressPercentage: progress,
            classification,
            authorRole,
            status
        });

        if (!validation.valid) {
            alert('Errores de validación:\n' + validation.errors.join('\n'));
            return;
        }

        setUploading(true);
        try {
            // Preparar metadata con campos adicionales
            const metadata = {
                weather,
                materials,
                personnel,
                observations
            };

            // Crear o actualizar nota
            if (editingLog) {
                // Actualizar nota existente
                await BitacoraService.updateLog(editingLog.id, {
                    content,
                    progressPercentage: progress,
                    subject,
                    classification,
                    authorRole,
                    status,
                    noteNumber,
                    metadata
                });
            } else {
                // Verificar límite antes de crear nueva nota
                if (!isPro) {
                    const limitCheck = await checkLimit('bitacoraEntries');
                    if (!limitCheck.allowed) {
                        setLimitModal({
                            isOpen: true,
                            actionType: 'bitacoraEntries',
                            usage: limitCheck.current,
                            limit: limitCheck.limit
                        });
                        setUploading(false);
                        return;
                    }
                }

                // Crear nueva nota
                await BitacoraService.createLog({
                    projectId,
                    taskId: taskData.id,
                    content,
                    progressPercentage: progress,
                    subject,
                    classification,
                    authorRole,
                    status,
                    noteNumber,
                    metadata
                });

                // Incrementar contador de uso
                if (!isPro) {
                    await incrementUsage('bitacoraEntries');
                }
            }

            onSave();
            onClose();
            
            // Resetear formulario
            setContent('');
            setProgress(taskData.progress || 0);
            setSubject('');
            setWeather('');
            setMaterials('');
            setPersonnel('');
            setObservations('');
        } catch (error) {
            console.error('Error saving log:', error);
            alert('Error al guardar la nota: ' + error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-800 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-lg">
                            <FileText className="mr-2" size={20} /> {editingLog ? 'Editar Nota de Bitácora' : 'Nueva Nota de Bitácora'}
                        </h3>
                        <p className="text-xs text-slate-400 mt-1">Folio #{noteNumber || '...'} • {taskData.name}</p>
                    </div>
                    <button onClick={onClose} className="text-white/60 hover:text-white"><X size={24} /></button>
                </div>

                <div className="p-6 space-y-5 overflow-y-auto flex-1">
                    {/* Top Row: Classification & Status */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Clasificación</label>
                            <select
                                value={classification}
                                onChange={(e) => setClassification(e.target.value)}
                                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm font-medium text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500"
                            >
                                <option>Apertura</option>
                                <option>Orden</option>
                                <option>Solicitud</option>
                                <option>Autorización</option>
                                <option>Informe</option>
                                <option>Cierre</option>
                                <option>Otro</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estatus</label>
                            <div className="flex bg-slate-100 rounded-lg p-1">
                                <button
                                    onClick={() => setStatus('Abierta')}
                                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition ${status === 'Abierta' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    Abierta
                                </button>
                                <button
                                    onClick={() => setStatus('Cerrada')}
                                    className={`flex-1 py-1.5 text-xs font-bold rounded-md transition ${status === 'Cerrada' ? 'bg-white text-green-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                                >
                                    Cerrada
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Subject */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Asunto <span className="text-red-500">*</span></label>
                        <input
                            value={subject}
                            onChange={(e) => setSubject(e.target.value)}
                            className="w-full font-bold text-slate-800 border-b-2 border-slate-200 focus:border-indigo-500 outline-none py-2 px-1 transition"
                            placeholder="Ej: Solicitud de estimación 1"
                        />
                    </div>

                    {/* Author Role */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Firma como</label>
                        <div className="flex gap-3">
                            {['Supervisor', 'Residente', 'Superintendente'].map(role => (
                                <button
                                    key={role}
                                    onClick={() => setAuthorRole(role)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-bold border transition ${authorRole === role ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                                >
                                    {role}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Content */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descripción de Actividades <span className="text-red-500">*</span></label>
                        <textarea
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            className="w-full p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-32 text-sm"
                            placeholder="Describe detalladamente las actividades realizadas, hechos, órdenes o solicitudes..."
                        />
                    </div>

                    {/* Campos específicos de bitácora de obra civil */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4 border-t border-slate-100">
                        {/* Condiciones Climáticas */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Cloud size={14} /> Condiciones Climáticas
                            </label>
                            <input
                                type="text"
                                value={weather}
                                onChange={(e) => setWeather(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                placeholder="Ej: Soleado, 25°C, sin viento"
                            />
                        </div>

                        {/* Avance Físico */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Avance Físico (%)</label>
                            <div className="flex items-center gap-3">
                                <input
                                    type="range"
                                    min="0"
                                    max="100"
                                    value={progress}
                                    onChange={(e) => setProgress(parseInt(e.target.value))}
                                    className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                                />
                                <div className="text-right text-sm font-bold text-indigo-600 w-12">{progress}%</div>
                            </div>
                        </div>
                    </div>

                    {/* Recursos Utilizados */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4 border-t border-slate-100">
                        {/* Materiales */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Package size={14} /> Materiales Utilizados
                            </label>
                            <textarea
                                value={materials}
                                onChange={(e) => setMaterials(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-20 text-sm"
                                placeholder="Ej: 50 m³ de concreto, 200 kg de acero..."
                            />
                        </div>

                        {/* Personal */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                                <Users size={14} /> Personal Utilizado
                            </label>
                            <textarea
                                value={personnel}
                                onChange={(e) => setPersonnel(e.target.value)}
                                className="w-full p-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-20 text-sm"
                                placeholder="Ej: 3 albañiles, 1 capataz, 1 ayudante..."
                            />
                        </div>
                    </div>

                    {/* Observaciones */}
                    <div className="pt-4 border-t border-slate-100">
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1 flex items-center gap-1">
                            <AlertCircle size={14} /> Observaciones Adicionales
                        </label>
                        <textarea
                            value={observations}
                            onChange={(e) => setObservations(e.target.value)}
                            className="w-full p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-24 text-sm"
                            placeholder="Incidentes, desviaciones, correcciones, o cualquier observación relevante..."
                        />
                    </div>
                </div>

                <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg font-medium transition">
                        Cancelar
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={uploading}
                        className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold transition flex items-center shadow-lg shadow-indigo-200 disabled:opacity-50"
                    >
                        {uploading ? 'Firmando...' : <><Save size={18} className="mr-2" /> Firmar Nota</>}
                    </button>
                </div>
            </div>
        </div>
    );
};

