                                                type="button"
                                                onClick={() => handleRemoveEntry(entry.id)}
                                                className="p-2 rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 transition touch-manipulation"
                                                title="Eliminar bloque"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </div>

                                        {/* Fotos */}
                                        <div className="mb-4">
                                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                                                {entry.previewUrls.map((url, idx) => (
                                                    <div key={idx} className="aspect-square relative group rounded-lg overflow-hidden border border-slate-200">
                                                        <img src={url} className="w-full h-full object-cover" alt="Evidencia" />
                                                        <button
                                                            type="button"
                                                            onClick={() => {
                                                                const newPreviewUrls = entry.previewUrls.filter((_, i) => i !== idx);
                                                                const newPhotoUrls = (entry.photoUrls || []).filter((_, i) => i !== idx);
                                                                const existingCount = (entry.photoUrls || []).length;
                                                                const newPhotos = idx >= existingCount ? entry.photos.filter((_, i) => i !== idx - existingCount) : entry.photos;
                                                                updateEntryFields(entry.id, { previewUrls: newPreviewUrls, photoUrls: newPhotoUrls, photos: newPhotos });
                                                            }}
                                                            className="absolute top-1.5 right-1.5 p-1.5 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition shadow-lg hover:bg-red-600 min-w-[28px] min-h-[28px] flex items-center justify-center"
                                                            title="Eliminar foto"
                                                        >
                                                            <Trash2 size={12} />
                                                        </button>
                                                    </div>
                                                ))}
                                                <label className="aspect-square border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-50/50 hover:border-indigo-400 transition text-slate-400 hover:text-indigo-600 touch-manipulation">
                                                    <Upload size={22} className="mb-1" />
                                                    <span className="text-xs font-bold">Subir</span>
                                                    <input type="file" accept="image/*" multiple className="hidden" onChange={(e) => handleFileChange(entry.id, e)} />
                                                </label>
                                            </div>
                                        </div>

                                        {/* Concepto debajo de las fotos (input, no select que se despliega) */}
                                        <div className="mb-4">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto</label>
                                            <input
                                                type="text"
                                                value={entry.itemName}
                                                onChange={(e) => updateEntry(entry.id, 'itemName', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl px-3 py-2.5 text-sm font-medium text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                                                placeholder="Nombre del concepto o partida"
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto general</label>
                                            <textarea
                                                value={entry.description}
                                                onChange={(e) => updateEntry(entry.id, 'description', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500 resize-none min-h-[80px]"
                                                placeholder="Concepto general de todas las fotos de este bloque..."
                                                rows={2}
                                            />
                                        </div>

                                        <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl border border-slate-100">
                                            <button
                                                type="button"
                                                onClick={() => updateEntry(entry.id, 'isCompleted', !entry.isCompleted)}
                                                className={`shrink-0 w-6 h-6 rounded-md border-2 flex items-center justify-center transition ${entry.isCompleted ? 'bg-green-500 border-green-600 text-white' : 'bg-white border-slate-300'}`}
                                                aria-checked={entry.isCompleted}
                                            >
                                                <Check size={14} strokeWidth={4} />
                                            </button>
                                            <span className="text-sm font-medium text-slate-700">Terminado (100%)</span>
                                        </div>
                                    </div>
                                </div>
                            ))}

                            <button
                                type="button"
                                onClick={handleAddBlock}
                                className="w-full py-4 border-2 border-dashed border-slate-300 rounded-xl text-slate-500 hover:border-indigo-400 hover:text-indigo-600 hover:bg-indigo-50/30 font-bold transition flex items-center justify-center gap-2 touch-manipulation"
                            >
                                <Plus size={22} /> Agregar más fotos y concepto
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PhotographicReportModal;

/**
 * ImageUploadService
 * Servicio para subida y gestión de imágenes
 * Soporta múltiples imágenes, compresión y validación
 */

export class ImageUploadService {
    // Configuración
    static MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB (actualizado)
    static ALLOWED_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];

    /**
     * Valida un archivo de imagen
     * @param {File} file - Archivo a validar
     * @returns {Object} - { valid: boolean, error: string|null }
     */
    static validateImage(file) {
        if (!file) {
            return { valid: false, error: 'No se seleccionó ningún archivo' };
        }

        if (!this.ALLOWED_TYPES.includes(file.type)) {
            return { 
                valid: false, 
                error: `Tipo de archivo no permitido. Use: ${this.ALLOWED_TYPES.join(', ')}` 
            };
        }

        if (file.size > this.MAX_FILE_SIZE) {
            const maxSizeMB = (this.MAX_FILE_SIZE / 1024 / 1024).toFixed(1);
            const fileSizeMB = (file.size / 1024 / 1024).toFixed(2);
            return { 
                valid: false, 
                error: `El archivo es demasiado grande (${fileSizeMB}MB). El tamaño máximo permitido es ${maxSizeMB}MB. Los usuarios Pro pueden comprimir imágenes automáticamente.` 
            };
        }

        return { valid: true, error: null };
    }

    /**
     * Comprime una imagen antes de subirla (compresión básica)
     * @param {File} file - Archivo de imagen
     * @param {number} maxWidth - Ancho máximo (default: 1920)
     * @param {number} quality - Calidad de compresión (0-1, default: 0.8)
     * @returns {Promise<File>} - Archivo comprimido
     */
    static async compressImage(file, maxWidth = 1920, quality = 0.8) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Redimensionar si es necesario
                    if (width > maxWidth) {
                        height = (height * maxWidth) / width;
                        width = maxWidth;
                    }

                    canvas.width = width;
                    canvas.height = height;

                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    canvas.toBlob(
                        (blob) => {
                            if (!blob) {
                                reject(new Error('Error al comprimir la imagen'));
                                return;
                            }
                            const compressedFile = new File([blob], file.name, {
                                type: file.type,
                                lastModified: Date.now()
                            });
                            resolve(compressedFile);
                        },
                        file.type,
                        quality
                    );
                };
                img.onerror = () => reject(new Error('Error al cargar la imagen'));
                img.src = e.target.result;
            };
            reader.onerror = () => reject(new Error('Error al leer el archivo'));
            reader.readAsDataURL(file);
        });
    }

    /**
     * Comprime una imagen de forma avanzada (para usuarios Pro)
     * Intenta comprimir hasta alcanzar el tamaño máximo deseado
     * @param {File} file - Archivo de imagen
     * @param {number} targetSizeMB - Tamaño objetivo en MB (default: 5MB)
     * @param {number} maxWidth - Ancho máximo (default: 1920)
     * @param {number} minQuality - Calidad mínima permitida (default: 0.6)
     * @returns {Promise<{file: File, originalSize: number, compressedSize: number, reduction: number}>} - Archivo comprimido con métricas
     */
    static async compressImageAdvanced(file, targetSizeMB = 5, maxWidth = 1920, minQuality = 0.6) {
        const targetSizeBytes = targetSizeMB * 1024 * 1024;
        const originalSize = file.size;
        
        // Si ya es menor al tamaño objetivo, retornar original
        if (originalSize <= targetSizeBytes) {
            return {
                file,
                originalSize,
                compressedSize: originalSize,
                reduction: 0
            };
        }

        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Calcular dimensiones optimizadas
                    if (width > maxWidth) {
                        height = (height * maxWidth) / width;
                        width = maxWidth;
                    }

                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    // Intentar diferentes niveles de calidad
                    const tryCompress = (quality) => {
                        return new Promise((resolveQuality) => {
                            canvas.toBlob(
                                (blob) => {
                                    if (!blob) {
                                        resolveQuality(null);
                                        return;
                                    }
                                    resolveQuality({
                                        blob,
                                        size: blob.size,
                                        quality
                                    });
                                },
                                file.type === 'image/png' ? 'image/jpeg' : file.type, // Convertir PNG a JPEG para mejor compresión
                                quality
                            );
                        });
                    };

                    // Búsqueda binaria de la calidad óptima
                    const findOptimalQuality = async (minQ, maxQ) => {
                        if (maxQ - minQ < 0.05) {
                            // Si la diferencia es muy pequeña, usar la calidad mínima
                            return await tryCompress(minQ);
                        }

                        const midQ = (minQ + maxQ) / 2;
                        const result = await tryCompress(midQ);

                        if (!result || result.size <= 0) {
                            return await tryCompress(minQ);
                        }

                        if (result.size <= targetSizeBytes) {
                            // Si es menor al objetivo, intentar calidad más alta
                            const higher = await tryCompress((midQ + maxQ) / 2);
                            if (higher && higher.size <= targetSizeBytes && higher.quality > result.quality) {
                                return higher;
                            }
                            return result;
                        } else {
                            // Si es mayor, reducir calidad
                            return await findOptimalQuality(minQ, midQ);
                        }
                    };

                    // Iniciar compresión
                    findOptimalQuality(minQuality, 0.95)
                        .then((result) => {
                            if (!result || !result.blob) {
                                reject(new Error('No se pudo comprimir la imagen'));
                                return;
                            }

                            const compressedFile = new File(
                                [result.blob],
                                file.name.replace(/\.png$/i, '.jpg'), // Cambiar extensión si era PNG
                                {
                                    type: result.blob.type,
                                    lastModified: Date.now()
                                }
                            );

                            const reduction = ((originalSize - compressedFile.size) / originalSize) * 100;

                            resolve({
                                file: compressedFile,
                                originalSize,
                                compressedSize: compressedFile.size,
                                reduction: Math.round(reduction * 100) / 100,
                                quality: result.quality
                            });
                        })
                        .catch((error) => {
                            reject(new Error(`Error al comprimir: ${error.message}`));
                        });
                };
                img.onerror = () => reject(new Error('Error al cargar la imagen'));
                img.src = e.target.result;
            };
            reader.onerror = () => reject(new Error('Error al leer el archivo'));
            reader.readAsDataURL(file);
        });
    }

    /**
     * Sube una imagen usando la API existente
     * @param {File} file - Archivo de imagen
     * @param {string} projectId - ID del proyecto (opcional, para organización)
     * @param {string} taskId - ID de la tarea (opcional)
     * @param {Object} options - Opciones adicionales
     * @param {boolean} options.isPro - Si el usuario es Pro (para compresión avanzada)
     * @param {boolean} options.autoCompress - Si debe comprimir automáticamente (default: true)
     * @returns {Promise<string>} - URL pública de la imagen
     */
    static async uploadImage(file, projectId = null, taskId = null, options = {}) {
        const { isPro = false, autoCompress = true } = options;
        
        // Validar archivo
        const validation = this.validateImage(file);
        if (!validation.valid) {
            throw new Error(validation.error);
        }

        // Comprimir imagen si es necesario
        let fileToUpload = file;
        
        if (autoCompress) {
            try {
                // Si el archivo excede el límite y es usuario Pro, usar compresión avanzada
                if (file.size > this.MAX_FILE_SIZE && isPro) {
                    const compressed = await this.compressImageAdvanced(file, 5, 1920, 0.6);
                    fileToUpload = compressed.file;
                    console.log(`Imagen comprimida: ${(file.size / 1024 / 1024).toFixed(2)}MB → ${(compressed.compressedSize / 1024 / 1024).toFixed(2)}MB (${compressed.reduction.toFixed(1)}% reducción)`);
                } else if (file.size > this.MAX_FILE_SIZE) {
                    // Usuario Free con archivo grande
                    throw new Error(`El archivo es demasiado grande (${(file.size / 1024 / 1024).toFixed(2)}MB). El tamaño máximo permitido es ${(this.MAX_FILE_SIZE / 1024 / 1024).toFixed(1)}MB. Los usuarios Pro pueden comprimir imágenes automáticamente.`);
                } else {
                    // Compresión básica para optimizar
                    fileToUpload = await this.compressImage(file, 1920, 0.85);
                }
            } catch (error) {
                // Si falla la compresión pero el archivo es válido, intentar subir el original
                if (file.size <= this.MAX_FILE_SIZE) {
                    console.warn('Error comprimiendo imagen, subiendo original:', error);
                    fileToUpload = file;
                } else {
                    // Si el archivo es demasiado grande y no se pudo comprimir, lanzar error
                    throw error;
                }
            }
        }

        try {
            const formData = new FormData();
            formData.append('file', fileToUpload);

            // En dev sin VITE_API_URL: subida local vía Vite (guardado en uploads/reporte). Con backend: usar su URL.
            const apiBaseUrl = import.meta.env.VITE_API_URL;
            const uploadUrl = apiBaseUrl ? `${apiBaseUrl}/api/upload` : '/api/upload';

            const response = await fetch(uploadUrl, {
                method: 'POST',
                body: formData
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({ error: 'Error desconocido' }));
                throw new Error(errorData.error || 'Error al subir la imagen');
            }

            const data = await response.json();
            return data.url; // La API retorna { url: "...", filename: "..." }
        } catch (error) {
            console.error('Error uploading image:', error);
            throw new Error(`Error al subir la imagen: ${error.message}`);
        }
    }

    /**
     * Sube múltiples imágenes
     * @param {Array<File>} files - Array de archivos
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea (opcional)
     * @returns {Promise<Array<string>>} - Array de URLs públicas
     */
    static async uploadMultipleImages(files, projectId, taskId = null) {
        if (!Array.isArray(files) || files.length === 0) {
            return [];
        }

        const uploadPromises = files.map(file => 
            this.uploadImage(file, projectId, taskId)
        );

        try {
            const urls = await Promise.all(uploadPromises);
            return urls.filter(Boolean); // Filtrar errores
        } catch (error) {
            console.error('Error uploading multiple images:', error);
            throw error;
        }
    }

    /**
     * Elimina una imagen (si se implementa en el backend)
     * @param {string} imageUrl - URL de la imagen
     * @returns {Promise<void>}
     */
    static async deleteImage(imageUrl) {
        if (!imageUrl) return;

        // Por ahora solo loguear, la eliminación se puede implementar en el backend si es necesario
        console.log('Delete image requested:', imageUrl);
        // TODO: Implementar endpoint de eliminación en el backend si es necesario
    }

    /**
     * Elimina múltiples imágenes
     * @param {Array<string>} imageUrls - Array de URLs
     * @returns {Promise<void>}
     */
    static async deleteMultipleImages(imageUrls) {
        if (!Array.isArray(imageUrls) || imageUrls.length === 0) return;

        const deletePromises = imageUrls.map(url => this.deleteImage(url));
        await Promise.allSettled(deletePromises);
    }

    /**
     * Crea una URL de preview local para mostrar antes de subir
     * @param {File} file - Archivo de imagen
     * @returns {string} - URL de preview
     */
    static createPreviewUrl(file) {
        if (!file) return null;
        return URL.createObjectURL(file);
    }

    /**
     * Revoca una URL de preview para liberar memoria
     * @param {string} url - URL de preview
     */
    static revokePreviewUrl(url) {
        if (url && url.startsWith('blob:')) {
            URL.revokeObjectURL(url);
        }
    }
}

export default ImageUploadService;

import React, { useState, useEffect } from 'react';
import { X, Camera, Save, Plus, Trash2, Check, Upload } from 'lucide-react';
import BitacoraService from '../../services/BitacoraService';
import ImageUploadService from '../../services/ImageUploadService';

const PhotographicReportModal = ({ isOpen, onClose, projectId, items = [], onSave, editingLog = null }) => {
    const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);
    const [entries, setEntries] = useState([]);
    const [uploading, setUploading] = useState(false);

    // Cargar datos del log cuando se está editando
    useEffect(() => {
        if (isOpen && editingLog) {
            // Establecer fecha del reporte
            const logDate = editingLog.log_date ? new Date(editingLog.log_date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0];
            setReportDate(logDate);

            // Extraer nombre del concepto del subject
            const conceptName = editingLog.subject?.replace('Reporte Fotográfico: ', '') || 'Concepto';
            
            // Buscar el item correspondiente
            const item = items.find(i => 
                i.description === conceptName || 
                i.id?.toString() === editingLog.task_id
            );

            // Crear entrada con los datos del log
            const entry = {
                id: Date.now(),
                logId: editingLog.id, // ID del log para actualizar
                itemId: item?.id || editingLog.task_id,
                itemName: conceptName,
                itemCode: item?.code || '',
                photos: [], // Se cargarán desde las URLs
                previewUrls: editingLog.photos || [], // URLs existentes
                photoUrls: editingLog.photos || [], // URLs originales para mantener
                description: editingLog.content || '',
                progress: editingLog.progress_percentage || 100,
                isCompleted: editingLog.progress_percentage === 100
            };

            setEntries([entry]);
        } else if (isOpen && !editingLog) {
            // Resetear cuando se crea uno nuevo
            setReportDate(new Date().toISOString().split('T')[0]);
            setEntries([]);
        }
    }, [isOpen, editingLog, items]);

    // Limpiar previews al cerrar
    useEffect(() => {
        return () => {
            entries.forEach(entry => {
                entry.previewUrls.forEach(url => {
                    // Solo revocar si es un blob URL (no URLs de servidor)
                    if (url.startsWith('blob:')) {
                        ImageUploadService.revokePreviewUrl(url);
                    }
                });
            });
        };
    }, [entries]);

    if (!isOpen) return null;

    const handleAddBlock = () => {
        setEntries([...entries, {
            id: Date.now(),
            itemId: 'block-' + Date.now(),
            itemName: '',
            itemCode: '',
            photos: [],
            previewUrls: [],
            photoUrls: [],
            description: '',
            progress: 100,
            isCompleted: true
        }]);
    };

    const handleRemoveEntry = (entryId) => {
        const entry = entries.find(e => e.id === entryId);
        if (entry) {
            entry.previewUrls.forEach(url => ImageUploadService.revokePreviewUrl(url));
        }
        setEntries(entries.filter(e => e.id !== entryId));
    };

    const handleFileChange = (entryId, e) => {
        const selectedFiles = Array.from(e.target.files || []);
        if (selectedFiles.length === 0) return;

        const validFiles = [];
        const newPreviewUrls = [];

        selectedFiles.forEach(file => {
            const validation = ImageUploadService.validateImage(file);
            if (validation.valid) {
                validFiles.push(file);
                newPreviewUrls.push(ImageUploadService.createPreviewUrl(file));
            } else {
                alert(`Error en ${file.name}: ${validation.error}`);
            }
        });

        setEntries(entries.map(entry => {
            if (entry.id === entryId) {
                return {
                    ...entry,
                    photos: [...entry.photos, ...validFiles],
                    previewUrls: [...entry.previewUrls, ...newPreviewUrls]
                };
            }
            return entry;
        }));
    };

    const updateEntry = (entryId, field, value) => {
        setEntries(entries.map(entry => {
            if (entry.id === entryId) {
                return { ...entry, [field]: value };
            }
            return entry;
        }));
    };

    /** Actualiza varios campos de una entrada a la vez (evita estados intermedios al eliminar fotos). */
    const updateEntryFields = (entryId, updates) => {
        setEntries(entries.map(entry =>
            entry.id === entryId ? { ...entry, ...updates } : entry
        ));
    };

    const handleSave = async () => {
        if (entries.length === 0) {
            alert('Agrega al menos un bloque (fotos y concepto).');
            return;
        }

        setUploading(true);
        try {
            // Procesar cada entrada secuencialmente
            for (const entry of entries) {
                // 1. Subir nuevas fotos (si hay)
                let newPhotoUrls = [];
                if (entry.photos.length > 0) {
                    newPhotoUrls = await ImageUploadService.uploadMultipleImages(
                        entry.photos,
                        projectId,
                        'report-' + entry.itemId
                    );
                }

                // 2. Combinar URLs existentes con nuevas
                const existingUrls = entry.photoUrls || [];
                const allPhotoUrls = [...existingUrls, ...newPhotoUrls];

                // 3. Fecha del reporte
                const logDate = new Date(reportDate + 'T12:00:00').toISOString();

                const conceptName = (entry.itemName || '').trim() || `Concepto ${entry.itemId}`;
                if (editingLog && entry.logId) {
                    await BitacoraService.updateLog(entry.logId, {
                        content: entry.description || `Reporte fotográfico: ${conceptName}`,
                        progressPercentage: entry.isCompleted ? 100 : entry.progress,
                        photos: allPhotoUrls,
                        subject: `Reporte Fotográfico: ${conceptName}`
                    });
                } else {
                    await BitacoraService.createLog({
                        projectId,
                        taskId: entry.itemId.toString(),
                        content: entry.description || `Reporte fotográfico: ${conceptName}`,
                        progressPercentage: entry.isCompleted ? 100 : entry.progress,
                        photos: allPhotoUrls,
                        subject: `Reporte Fotográfico: ${conceptName}`,
                        classification: 'Informe',
                        authorRole: 'Residente',
                        status: 'Abierta',
                        logDate: logDate
                    });
                }
            }

            onSave();
            onClose();
        } catch (error) {
            console.error('Error saving report:', error);
            alert('Error al guardar el reporte: ' + error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[90] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-t-2xl sm:rounded-2xl shadow-2xl max-w-4xl w-full h-[92vh] sm:h-[90vh] max-h-[900px] flex flex-col overflow-hidden">
                {/* Header: título, fecha y acciones */}
                <div className="shrink-0 p-4 sm:p-5 border-b border-slate-200 bg-slate-800 text-white flex flex-wrap items-center justify-between gap-3">
                    <div className="min-w-0 flex items-center gap-4 flex-wrap">
                        <div>
                            <h3 className="font-bold text-lg sm:text-xl flex items-center gap-2">
                                <Camera className="shrink-0" size={24} /> <span className="truncate">{editingLog ? 'Editar' : 'Nuevo'} Reporte Fotográfico</span>
                            </h3>
                            <p className="text-slate-400 text-xs sm:text-sm truncate mt-0.5">
                                {editingLog ? 'Modifica el reporte' : 'Fotos y concepto por bloque'}
                            </p>
                        </div>
                        <label className="flex items-center gap-2 shrink-0">
                            <span className="text-slate-400 text-xs font-medium">Fecha:</span>
                            <input
                                type="date"
                                value={reportDate}
                                onChange={(e) => setReportDate(e.target.value)}
                                className="bg-white/10 border border-slate-500 rounded-lg px-3 py-1.5 text-sm font-medium text-white focus:ring-2 focus:ring-indigo-400 outline-none"
                            />
                        </label>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                        <button
                            type="button"
                            onClick={handleSave}
                            disabled={uploading || entries.length === 0}
                            className="bg-indigo-500 hover:bg-indigo-600 text-white font-bold px-4 py-2 rounded-xl transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed min-h-[40px] touch-manipulation"
                        >
                            {uploading ? (
                                <><span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> Guardando...</>
                            ) : (
                                <><Save size={18} /> {editingLog ? 'Actualizar' : 'Guardar'}</>
                            )}
                        </button>
                        <button type="button" onClick={onClose} className="p-2 rounded-lg text-white/70 hover:text-white hover:bg-white/10 transition touch-manipulation" aria-label="Cerrar">
                            <X size={24} />
                        </button>
                    </div>
                </div>

                {/* Contenido: bloques de fotos + concepto debajo, sin barra lateral */}
                <div className="flex-1 min-h-0 overflow-y-auto p-4 sm:p-6 bg-slate-100">
                    {entries.length === 0 ? (
                        <div className="min-h-[280px] flex flex-col items-center justify-center text-slate-500 px-4">
                            <div className="w-16 h-16 rounded-2xl bg-slate-200/80 flex items-center justify-center mb-4">
                                <Camera size={32} className="text-slate-400" />
                            </div>
                            <p className="font-semibold text-base text-slate-600 text-center">Agrega fotos y concepto</p>
                            <p className="text-sm text-slate-400 text-center mt-1">Cada bloque puede tener varias fotos y un concepto debajo.</p>
                            <button
                                type="button"
                                onClick={handleAddBlock}
                                className="mt-6 inline-flex items-center gap-2 px-5 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl transition shadow-lg shadow-indigo-200/50 min-h-[44px] touch-manipulation"
                            >
                                <Plus size={20} /> Agregar fotos y concepto
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6 max-w-3xl mx-auto">
                            {entries.map((entry, index) => (
                                <div key={entry.id} className="bg-white rounded-xl shadow-sm border-2 border-slate-200 overflow-hidden">
                                    <div className="p-4 sm:p-5">
                                        <div className="flex items-center justify-between gap-3 mb-4">
                                            <span className="text-xs font-bold text-slate-500 uppercase tracking-wide">Bloque {index + 1}</span>
                                            <button
                                                type="button"
                                                onClick={() => handleRemoveEntry(entry.id)}
                                                className="p-2 rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 transition touch-manipulation"
                                                title="Eliminar bloque"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </div>

                                        {/* Fotos */}
                                        <div className="mb-4">
                                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                                                {entry.previewUrls.map((url, idx) => (
                                                    <div key={idx} className="aspect-square relative group rounded-lg overflow-hidden border border-slate-200">
                                                        <img src={url} className="w-full h-full object-cover" alt="Evidencia" />
                                                        <button
                                                            type="button"
                                                            onClick={() => {
                                                                const newPreviewUrls = entry.previewUrls.filter((_, i) => i !== idx);
                                                                const newPhotoUrls = (entry.photoUrls || []).filter((_, i) => i !== idx);
                                                                const existingCount = (entry.photoUrls || []).length;
                                                                const newPhotos = idx >= existingCount ? entry.photos.filter((_, i) => i !== idx - existingCount) : entry.photos;
                                                                updateEntryFields(entry.id, { previewUrls: newPreviewUrls, photoUrls: newPhotoUrls, photos: newPhotos });
                                                            }}
                                                            className="absolute top-1.5 right-1.5 p-1.5 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition shadow-lg hover:bg-red-600 min-w-[28px] min-h-[28px] flex items-center justify-center"
                                                            title="Eliminar foto"
                                                        >
                                                            <Trash2 size={12} />
                                                        </button>
                                                    </div>
                                                ))}
                                                <label className="aspect-square border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-50/50 hover:border-indigo-400 transition text-slate-400 hover:text-indigo-600 touch-manipulation">
                                                    <Upload size={22} className="mb-1" />
                                                    <span className="text-xs font-bold">Subir</span>
                                                    <input type="file" accept="image/*" multiple className="hidden" onChange={(e) => handleFileChange(entry.id, e)} />
                                                </label>
                                            </div>
                                        </div>

                                        {/* Concepto debajo de las fotos (input, no select que se despliega) */}
                                        <div className="mb-4">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto</label>
                                            <input
                                                type="text"
                                                value={entry.itemName}
                                                onChange={(e) => updateEntry(entry.id, 'itemName', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl px-3 py-2.5 text-sm font-medium text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                                                placeholder="Nombre del concepto o partida"
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-1.5">Concepto general</label>
                                            <textarea
                                                value={entry.description}
                                                onChange={(e) => updateEntry(entry.id, 'description', e.target.value)}
                                                className="w-full border-2 border-slate-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500 resize-none min-h-[80px]"
                                                placeholder="Concepto general de todas las fotos de este bloque..."
                                                rows={2}
                                            />
                                        </div>

                                        <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl border border-slate-100">
                                            <button
                                                type="button"
                                                onClick={() => updateEntry(entry.id, 'isCompleted', !entry.isCompleted)}
                                                className={`shrink-0 w-6 h-6 rounded-md border-2 flex items-center justify-center transition ${entry.isCompleted ? 'bg-green-500 border-green-600 text-white' : 'bg-white border-slate-300'}`}
                                                aria-checked={entry.isCompleted}
                                            >
                                                <Check size={14} strokeWidth={4} />
                                            </button>
                                            <span className="text-sm font-medium text-slate-700">Terminado (100%)</span>
                                        </div>
                                    </div>
                                </div>
                            ))}

                            <button
                                type="button"
                                onClick={handleAddBlock}
                                className="w-full py-4 border-2 border-dashed border-slate-300 rounded-xl text-slate-500 hover:border-indigo-400 hover:text-indigo-600 hover:bg-indigo-50/30 font-bold transition flex items-center justify-center gap-2 touch-manipulation"
                            >
                                <Plus size={22} /> Agregar más fotos y concepto
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PhotographicReportModal;

/**
 * BitacoraService
 * Servicio centralizado para gestión de bitácora de obra
 * Maneja logs, notas, avances y evidencias fotográficas
 */

import { supabase } from '../lib/supabaseClient';

export class BitacoraService {
    /**
     * Carga todos los logs de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Array de logs ordenados por fecha
     */
    static async loadLogs(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error loading logs:', error);
            throw error;
        }
    }

    /**
     * Carga el cronograma de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Cronograma o null
     */
    static async loadSchedule(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('project_schedules')
                .select('*')
                .eq('project_id', projectId)
                .maybeSingle();

            if (error && error.code !== 'PGRST116') throw error;
            return data || null;
        } catch (error) {
            console.error('Error loading schedule:', error);
            throw error;
        }
    }

    /**
     * Obtiene el siguiente número de folio para un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<number>} - Siguiente número de folio
     */
    static async getNextNoteNumber(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { count, error } = await supabase
                .from('site_logs')
                .select('*', { count: 'exact', head: true })
                .eq('project_id', projectId);

            if (error) throw error;
            return (count || 0) + 1;
        } catch (error) {
            console.error('Error getting next note number:', error);
            throw error;
        }
    }

    /**
     * Crea una nueva nota de bitácora
     * @param {Object} logData - Datos de la nota
     * @returns {Promise<Object>} - Nota creada
     */
    static async createLog(logData) {
        const {
            projectId,
            taskId,
            content,
            progressPercentage = 0,
            photos = [],
            subject,
            classification = 'Informe',
            authorRole = 'Residente',
            status = 'Abierta',
            noteNumber = null,
            logDate = null, // Fecha opcional del log (para reportes fotográficos)
            authorName = null, // Para entradas de diario
            authorSignature = null, // Para entradas de diario
            isDiaryEntry = false, // Flag para identificar entradas de diario
            metadata = null // Metadata adicional (clima, materiales, personal, observaciones)
        } = logData;

        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        if (!subject || !subject.trim()) {
            throw new Error('Subject is required');
        }

        try {
            // Obtener número de folio si no se proporciona
            const finalNoteNumber = noteNumber || await this.getNextNoteNumber(projectId);

            // Para entradas de diario, guardar metadata en el content con formato especial
            let finalContent = content || '';
            if (isDiaryEntry && (authorName || authorSignature)) {
                const diaryMetadata = {
                    authorName: authorName || '',
                    authorSignature: authorSignature || '',
                    isDiaryEntry: true
                };
                // Guardar metadata al final del content con un separador especial
                finalContent = content + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
            } else if (metadata && Object.keys(metadata).length > 0) {
                // Para bitácora normal, guardar metadata (clima, materiales, personal, observaciones)
                finalContent = content + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(metadata) + '-->';
            }

            const { data, error } = await supabase
                .from('site_logs')
                .insert([{
                    project_id: projectId,
                    task_id: taskId,
                    content: finalContent,
                    progress_percentage: progressPercentage,
                    photos: Array.isArray(photos) ? photos : [photos].filter(Boolean),
                    log_date: logDate || new Date().toISOString(), // Usar fecha proporcionada o actual
                    note_number: finalNoteNumber,
                    classification,
                    author_role: authorRole,
                    status,
                    subject: subject.trim()
                }])
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error creating log:', error);
            throw error;
        }
    }

    /**
     * Actualiza una nota existente
     * @param {string} logId - ID de la nota
     * @param {Object} updates - Campos a actualizar
     * @returns {Promise<Object>} - Nota actualizada
     */
    static async updateLog(logId, updates) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const updateData = {};
            
            // Manejar contenido con metadata de diario o bitácora
            if (updates.content !== undefined) {
                let finalContent = updates.content;
                if (updates.isDiaryEntry && (updates.authorName || updates.authorSignature)) {
                    const diaryMetadata = {
                        authorName: updates.authorName || '',
                        authorSignature: updates.authorSignature || '',
                        isDiaryEntry: true
                    };
                    // Remover metadata anterior si existe
                    finalContent = finalContent.replace(/\n\n<!--DIARY_METADATA:.*?-->/, '');
                    // Agregar nueva metadata
                    finalContent = finalContent + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
                } else if (updates.metadata && Object.keys(updates.metadata).length > 0) {
                    // Para bitácora normal, guardar metadata
                    finalContent = finalContent.replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '');
                    finalContent = finalContent + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(updates.metadata) + '-->';
                }
                updateData.content = finalContent;
            }
            if (updates.progressPercentage !== undefined) updateData.progress_percentage = updates.progressPercentage;
            if (updates.photos !== undefined) updateData.photos = Array.isArray(updates.photos) ? updates.photos : [updates.photos].filter(Boolean);
            if (updates.subject !== undefined) updateData.subject = updates.subject;
            if (updates.classification !== undefined) updateData.classification = updates.classification;
            if (updates.authorRole !== undefined) updateData.author_role = updates.authorRole;
            if (updates.status !== undefined) updateData.status = updates.status;
            if (updates.logDate !== undefined) updateData.log_date = updates.logDate;

            const { data, error } = await supabase
                .from('site_logs')
                .update(updateData)
                .eq('id', logId)
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error updating log:', error);
            throw error;
        }
    }

    /**
     * Elimina una nota
     * @param {string} logId - ID de la nota
     */
    static async deleteLog(logId) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const { error } = await supabase
                .from('site_logs')
                .delete()
                .eq('id', logId);

            if (error) throw error;
        } catch (error) {
            console.error('Error deleting log:', error);
            throw error;
        }
    }

    /**
     * Obtiene los logs de una tarea específica
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<Array>} - Logs de la tarea
     */
    static async getTaskLogs(projectId, taskId) {
        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .eq('task_id', taskId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error getting task logs:', error);
            throw error;
        }
    }

    /**
     * Calcula el avance de una tarea basado en sus logs
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<number>} - Porcentaje de avance (0-100)
     */
    static async getTaskProgress(projectId, taskId) {
        const logs = await this.getTaskLogs(projectId, taskId);
        if (logs.length === 0) return 0;
        
        // Retornar el avance más reciente
        return logs[0].progress_percentage || 0;
    }

    /**
     * Obtiene estadísticas de la bitácora
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object>} - Estadísticas
     */
    static async getStatistics(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const logs = await this.loadLogs(projectId);

            const stats = {
                totalLogs: logs.length,
                openLogs: logs.filter(l => l.status === 'Abierta').length,
                closedLogs: logs.filter(l => l.status === 'Cerrada').length,
                byClassification: {},
                byAuthorRole: {},
                totalPhotos: 0,
                averageProgress: 0
            };

            let totalProgress = 0;
            logs.forEach(log => {
                // Por clasificación
                stats.byClassification[log.classification] = 
                    (stats.byClassification[log.classification] || 0) + 1;

                // Por rol de autor
                stats.byAuthorRole[log.author_role] = 
                    (stats.byAuthorRole[log.author_role] || 0) + 1;

                // Fotos
                if (log.photos && Array.isArray(log.photos)) {
                    stats.totalPhotos += log.photos.length;
                }

                // Progreso
                totalProgress += log.progress_percentage || 0;
            });

            stats.averageProgress = logs.length > 0 
                ? Math.round(totalProgress / logs.length) 
                : 0;

            return stats;
        } catch (error) {
            console.error('Error getting statistics:', error);
            throw error;
        }
    }

    /**
     * Valida datos de una nota antes de guardar
     * @param {Object} logData - Datos a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateLogData(logData) {
        const errors = [];

        if (!logData.projectId) errors.push('Project ID is required');
        if (!logData.taskId) errors.push('Task ID is required');
        if (!logData.subject || !logData.subject.trim()) {
            errors.push('Subject is required');
        }

        if (logData.progressPercentage !== undefined) {
            const progress = parseInt(logData.progressPercentage);
            if (isNaN(progress) || progress < 0 || progress > 100) {
                errors.push('Progress must be between 0 and 100');
            }
        }

        const validClassifications = ['Apertura', 'Orden', 'Solicitud', 'Autorización', 'Informe', 'Cierre', 'Otro'];
        if (logData.classification && !validClassifications.includes(logData.classification)) {
            errors.push(`Classification must be one of: ${validClassifications.join(', ')}`);
        }

        const validAuthorRoles = ['Supervisor', 'Residente', 'Superintendente', 'Otro'];
        if (logData.authorRole && !validAuthorRoles.includes(logData.authorRole)) {
            errors.push(`Author role must be one of: ${validAuthorRoles.join(', ')}`);
        }

        const validStatuses = ['Abierta', 'Cerrada'];
        if (logData.status && !validStatuses.includes(logData.status)) {
            errors.push(`Status must be one of: ${validStatuses.join(', ')}`);
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Extrae los metadatos de una entrada de diario del content
     * @param {string} content - Contenido de la entrada
     * @returns {Object|null} - Metadatos del diario o null
     */
    static extractDiaryMetadata(content) {
        if (!content) return null;
        
        const metadataMatch = content.match(/<!--DIARY_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing diary metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Extrae metadata de bitácora del contenido
     * @param {string} content - Contenido con metadata
     * @returns {object|null} - Metadata extraída o null
     */
    static extractBitacoraMetadata(content) {
        if (!content) return null;
        const metadataMatch = content.match(/<!--BITACORA_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing bitacora metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Obtiene el contenido limpio sin metadata
     * @param {string} content - Contenido con metadata
     * @returns {string} - Contenido limpio
     */
    static getCleanContent(content) {
        if (!content) return '';
        return content
            .replace(/\n\n<!--DIARY_METADATA:.*?-->/, '')
            .replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '')
            // También limpiar metadata de descripciones de fotos en reportes fotográficos
            .replace(/\n?\s*<!--PHOTO_CAPTIONS:.*?-->$/s, '')
            .trim();
    }

    /**
     * Verifica si un log es una entrada de diario
     * @param {Object} log - Log a verificar
     * @returns {boolean} - True si es entrada de diario
     */
    static isDiaryEntry(log) {
        if (!log) return false;
        // Verificar por task_id o por metadata en content
        if (log.task_id === 'diary') return true;
        if (log.content && this.extractDiaryMetadata(log.content)) return true;
        return false;
    }
}

export default BitacoraService;

import React, { useState, useEffect } from 'react';
import { X, Calculator, Check, AlertTriangle, Settings } from 'lucide-react';
import { APUService } from '../../services/APUService';

const APUModal = ({ item, apuData, onClose, onApply }) => {
    const [editableData, setEditableData] = useState(null);
    const [totals, setTotals] = useState({
        materialsTotal: 0,
        laborTotal: 0,
        equipmentTotal: 0,
        minorToolsCost: 0,
        directCost: 0,
        indirectCost: 0,
        subtotal1: 0,
        financingCost: 0,
        subtotal2: 0,
        profitCost: 0,
        subtotal3: 0,
        additionalCost: 0,
        finalPrice: 0
    });

    useEffect(() => {
        if (apuData) {
            // Normalizar datos usando el servicio
            const normalized = APUService.normalizeAPUData(apuData);
            setEditableData(normalized);
        }
    }, [apuData]);

    useEffect(() => {
        if (editableData) {
            calculateTotals();
        }
    }, [editableData]);

    if (!item || !editableData) return null;

    const formatCurrency = (amount) => {
        return new Intl.NumberFormat('es-MX', {
            style: 'currency',
            currency: 'MXN'
        }).format(amount);
    };

    const formatPercent = (val) => `${(val * 100).toFixed(2)}%`;

    const calculateTotals = () => {
        // Usar el servicio para calcular todos los totales
        const calculatedTotals = APUService.calculateAPUTotals(editableData);
        setTotals(calculatedTotals);
    };

    const handleUpdateRow = (category, index, field, value) => {
        const newData = { ...editableData };
        const row = newData[category][index];
        row[field] = parseFloat(value) || 0;
        setEditableData(newData);
    };

    const handleUpdatePct = (field, value) => {
        const newData = { ...editableData };
        newData[field] = parseFloat(value) / 100;
        setEditableData(newData);
    };

    const renderLaborTable = () => (
        <div className="mb-6">
            <h3 className="text-sm font-bold uppercase tracking-wider mb-2 text-orange-700 dark:text-orange-400 border-b border-orange-200 dark:border-orange-700 pb-1">
                Mano de Obra
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-300 font-medium">
