                        .replace(/Se asumió/gi, 'Parámetro técnico')
                        .replace(/se asumió/gi, 'parámetro técnico')
                        .replace(/Asumió/gi, 'Estándar')
                        .replace(/Suposición/gi, 'Nota técnica')
