                    id: data.id,
                    description: data.description,
                    unit: data.unit,
                    unitPrice: data.unit_price,
                    category: data.category
                };
                setCatalog([addedItem, ...catalog]);
            } else {
                // Guardar en LocalStorage
                const newCatalog = [newItem, ...catalog];
                setCatalog(newCatalog);
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }
            showToast('Concepto agregado al catálogo', 'success');
            return true;
        } catch (error) {
            console.error('Error adding to catalog:', error);
            showToast('Error al agregar al catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    const deleteFromCatalog = async (id) => {
        if (!window.confirm('¿Estás seguro de eliminar este concepto del catálogo?')) return;

        setLoading(true);
        try {
            if (user) {
                const { error } = await supabase
                    .from('catalog_items')
                    .delete()
                    .eq('id', id);

                if (error) throw error;
            }

            // Actualizar estado local (para ambos casos)
            const newCatalog = catalog.filter(item => item.id !== id);
            setCatalog(newCatalog);

            if (!user) {
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }

            showToast('Concepto eliminado del catálogo');
        } catch (error) {
            console.error('Error deleting from catalog:', error);
            showToast('Error al eliminar del catálogo', 'error');
        } finally {
            setLoading(false);
        }
    };

    const updateCatalogBulk = async (updatedItems) => {
        setLoading(true);
        try {
            if (user) {
                // Upsert to Supabase
                const itemsToUpsert = updatedItems.map(item => ({
                    id: item.id,
                    user_id: user.id,
                    description: item.description,
                    unit: item.unit,
                    unit_price: item.unitPrice,
                    category: item.category,
                    is_public: false,
                    updated_at: new Date().toISOString()
                }));

                const { error } = await supabase
                    .from('catalog_items')
                    .upsert(itemsToUpsert);

                if (error) throw error;
            } else {
                // Save to LocalStorage
                localStorage.setItem('presugenius_catalog', JSON.stringify(updatedItems));
            }

            setCatalog(updatedItems);
            showToast('Catálogo actualizado correctamente', 'success');
            return true;
        } catch (error) {
            console.error('Error updating catalog bulk:', error.message || error);
            if (error.details) console.error('Error details:', error.details);
            showToast('Error al actualizar el catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR DATOS AL INICIAR ---
    // Evitar bucle: solo ejecutar carga una vez por user.id; si falla la red no reintentar en cada render
    useEffect(() => {
        if (authLoading) return;

        if (!user) {
            lastLoadedUserIdRef.current = null;
            loadFromLocalStorage();
            return;
        }

        if (lastLoadedUserIdRef.current === user.id) return;
        lastLoadedUserIdRef.current = user.id;
        loadUserData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user?.id, authLoading]);

    // --- Auto-timeout para toasts ---
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    const calculateSubtotal = () => CalculationsService.calculateSubtotal(items);

    const calculateTotal = () => {
        const calc = CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
        return calc.total;
    };

    const getCalculations = () => {
        return CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
    };

    // --- GUARDAR PROYECTO ---
    const saveBudget = async () => {
        setLoading(true);

        try {
            if (user) {
                // Guardar en Supabase
                const projectData = {
                    user_id: user.id,
                    name: projectInfo.project,
                    client: projectInfo.client,
                    type: projectInfo.type,
                    currency: projectInfo.currency,
                    tax_rate: projectInfo.taxRate,
                    indirect_percentage: projectInfo.indirect_percentage || 0,
                    profit_percentage: projectInfo.profit_percentage || 0,
                    updated_at: new Date().toISOString()
                };

                let projectId = projectInfo.id;

                // Verificar si el proyecto ya existe
                const { data: existingProject } = await supabase
                    .from('projects')
                    .select('id')
                    .eq('id', projectInfo.id)
                    .single();

                if (existingProject) {
                    // Actualizar proyecto existente
                    await supabase
                        .from('projects')
                        .update(projectData)
                        .eq('id', projectInfo.id);
                } else {
                    // Crear nuevo proyecto
                    const { data: newProject, error: projectError } = await supabase
                        .from('projects')
                        .insert([{ ...projectData, id: projectInfo.id }])
                        .select()
                        .single();

                    if (projectError) throw projectError;
                    projectId = newProject.id;
                }

                // Eliminar items antiguos
                await supabase
                    .from('budget_items')
                    .delete()
                    .eq('project_id', projectId);

                // Insertar items nuevos
                if (items.length > 0) {
                    const itemsData = items.map((item, index) => ({
                        project_id: projectId,
                        description: item.description,
                        unit: item.unit,
                        quantity: item.quantity,
                        unit_price: item.unitPrice,
                        category: item.category,
                        subcategory: item.subcategory || null,
                        tags: item.tags || [],
                        notes: item.notes || '',
                        is_catalog_item: item.isCatalogItem || false,
                        order_index: index
                    }));

                    await supabase
                        .from('budget_items')
                        .insert(itemsData);
                }

                // Recargar proyectos
                await loadUserData();
                showToast('Proyecto guardado en la nube', 'success');

            } else {
                // Guardar en localStorage (modo offline)
                const budgetData = {
                    ...projectInfo,
                    items,
                    lastModified: new Date().toISOString(),
                    total: calculateTotal()
                };

                const existingIndex = savedBudgets.findIndex(b => b.id === projectInfo.id);
                let newSaved;

                if (existingIndex >= 0) {
                    newSaved = [...savedBudgets];
                    newSaved[existingIndex] = budgetData;
                } else {
                    newSaved = [...savedBudgets, budgetData];
                }

                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto guardado localmente', 'success');
            }
        } catch (error) {
            console.error('Error saving budget:', error);
            showToast('Error al guardar proyecto', 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR PROYECTO ---
    const loadBudget = (budget) => {
        setProjectInfo({
            id: budget.id,
            client: budget.client,
            project: budget.name || budget.project,
            date: budget.date || new Date().toISOString().split('T')[0],
            currency: budget.currency,
            taxRate: budget.tax_rate || budget.taxRate,
            type: budget.type,
            indirect_percentage: budget.indirect_percentage || 0,
            profit_percentage: budget.profit_percentage || 0
        });
        setItems(budget.items || []);
        showToast(`Proyecto "${budget.name || budget.project}" cargado`);
    };

    // --- ELIMINAR PROYECTO ---
    const deleteBudget = async (id) => {
        setLoading(true);

        try {
            if (user) {
                // Eliminar de Supabase
                await supabase
                    .from('projects')
                    .delete()
                    .eq('id', id);

                await loadUserData();
                showToast('Proyecto eliminado de la nube', 'success');
            } else {
                // Eliminar de localStorage
                const newSaved = savedBudgets.filter(b => b.id !== id);
                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto eliminado');
            }
        } catch (error) {
            const errorMessage = error.message || 'Error al eliminar proyecto';
            console.error('Error deleting budget:', error);
            showToast(errorMessage, 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- NUEVO PROYECTO ---
    const newProject = () => {
        setProjectInfo({
            id: generateId(),
            client: '',
            project: 'Presupuesto Nuevo',
            date: new Date().toISOString().split('T')[0],
            currency: 'MXN',
            taxRate: 16,
            type: 'General',
            indirect_percentage: 0,
            profit_percentage: 0
        });
        setItems([]);
        showToast('Nuevo proyecto creado');
    };

    const value = React.useMemo(() => ({
        projectInfo, setProjectInfo,
        items, setItems,
        savedBudgets, setSavedBudgets,
        catalog, setCatalog,
        toast, showToast, setToast,
        calculateSubtotal, calculateTotal, getCalculations,
        saveBudget, loadBudget, deleteBudget, newProject,
        addToCatalog, deleteFromCatalog, updateCatalogBulk,
        loading,
        rateLimitModal, showRateLimitModal, closeRateLimitModal
    }), [
        projectInfo, items, savedBudgets, catalog, toast, loading, rateLimitModal,
        showToast, showRateLimitModal, closeRateLimitModal
    ]);

    return <ProjectContext.Provider value={value}>{children}</ProjectContext.Provider>;
};

import React from 'react';
import Sidebar from './Sidebar';
import Toast from '../ui/Toast';
import { useProject } from '../../context/ProjectContext';
import { useSidebar } from '../../context/SidebarContext';
import UsageNotification from '../subscription/UsageNotification';
import PricingModal from '../subscription/PricingModal';
import { usePricingModal } from '../../context/PricingModalContext';
import SupportChat from '../support/SupportChat';
import RateLimitModal from '../ui/RateLimitModal';
import { Menu } from 'lucide-react';

const Layout = ({ children, title }) => {
    const { toast, setToast, rateLimitModal, closeRateLimitModal } = useProject();
    const { isOpen, closePricingModal } = usePricingModal();
    const { isCollapsed } = useSidebar();
    const [isMobile, setIsMobile] = React.useState(false);
    const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

    React.useEffect(() => {
        const checkMobile = () => {
            const mobile = window.innerWidth < 768;
            setIsMobile(mobile);
            if (!mobile) setIsMobileMenuOpen(false); // Close mobile menu when switching to desktop
        };
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    // Calcular el ancho del sidebar según el estado
    // En mobile es 0px porque es overlay, en desktop depende del estado
    const sidebarWidth = isMobile ? '0px' : (isCollapsed ? '80px' : '256px'); // w-20 = 80px, w-64 = 256px

    return (
        <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 font-sans text-slate-800 dark:text-slate-100 transition-colors">
            {/* Mobile Overlay */}
            {isMobile && isMobileMenuOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-30 backdrop-blur-sm transition-opacity"
                    onClick={() => setIsMobileMenuOpen(false)}
                />
            )}

            <Sidebar mobileOpen={isMobileMenuOpen} setMobileOpen={setIsMobileMenuOpen} />

            <main className="flex-1 p-1 md:p-2 overflow-y-auto scrollbar-hide print:ml-0 print:p-0 transition-all duration-300" style={{ marginLeft: `${sidebarWidth}` }}>

                <div className="flex justify-between items-center mb-8 print:hidden">
                    <div className="flex items-center gap-3">
                        {/* Hamburger Button for Mobile */}
                        <button
                            className="md:hidden p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                            aria-label="Toggle menu"
                        >
                            <Menu size={24} />
                        </button>

                        <h2 className="text-xl font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest hidden md:block">
                            {title}
                        </h2>
                        {/* Show title on mobile too if hidden above, but user only asked for hamburger. Keeping original title logic partially but allowing it to show if needed. Original Code had it hidden on mobile: `hidden md:block`. I will keep it that way for now unless user wants title on mobile. */}
                        <h2 className="text-lg font-bold text-slate-600 dark:text-slate-300 md:hidden block">
                            {title}
                        </h2>
                    </div>

                    <div className="flex gap-4 ml-auto">
                        <div className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 rounded-full shadow-sm border border-slate-200 dark:border-slate-700">
                            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                            <span className="text-xs font-bold text-slate-600 dark:text-slate-300">v2.4.0 Pro</span>
                        </div>
                    </div>
                </div>

                {children}

                {toast && <Toast message={toast.message} type={toast.type} error={toast.error || null} onClose={() => setToast(null)} />}
            </main>

            <UsageNotification />

            <UsageNotification />

            <PricingModal isOpen={isOpen} onClose={closePricingModal} />

            <RateLimitModal
                isOpen={rateLimitModal.isOpen}
                onClose={closeRateLimitModal}
                message={rateLimitModal.message}
                retryAfter={rateLimitModal.retryAfter}
            />

            {/* AI Support Chat Widget */}
            <SupportChat />

            <style>{`
        @media print {
          aside, button, input, select, .no-print { display: none !important; }
          main { margin-left: 0 !important; padding: 0 !important; width: 100% !important; }
          body { background: white; -webkit-print-color-adjust: exact; }
          .shadow-sm, .shadow-md, .shadow-lg, .shadow-2xl { box-shadow: none !important; }
          table th { background-color: #f1f5f9 !important; color: #000 !important; }
        }
      `}</style>
        </div>
    );
};

export default Layout;

import React, { useState, useEffect, useRef } from 'react';
import { systemSettingsService } from '../../services/SystemSettingsService';
import {
    MessageCircle,
    X,
    Send,
    Loader,
    Bot,
    User,
    Phone,
    Sparkles,
    ChevronDown,
    RefreshCw,
    ExternalLink,
    AlertTriangle
} from 'lucide-react';
import { SupportAIService } from '../../services/SupportAIService';
import { useSubscription } from '../../context/SubscriptionContext';
import { useProject } from '../../context/ProjectContext';
import { useAuth } from '../../context/AuthContext';
import { useError } from '../../context/ErrorContext';
import { ErrorService } from '../../services/ErrorService';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useLocation } from 'react-router-dom';

const SupportChat = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState([]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [showQuickReplies, setShowQuickReplies] = useState(true);
    const [isMinimized, setIsMinimized] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);
    const [errorReportMode, setErrorReportMode] = useState(false);
    const [whatsappNumber, setWhatsappNumber] = useState('522811975587'); // Default fallback

    const messagesEndRef = useRef(null);
    const inputRef = useRef(null);
    const { plan } = useSubscription();
    const { user } = useAuth();
    const { showRateLimitModal } = useProject();
    const errorContext = useError(); // Retorna funciones por defecto si no está disponible
    const location = useLocation();

    // Get user's first name
    const getUserFirstName = () => {
        if (!user) return '';

        // Try to get from user metadata
        const fullName = user.user_metadata?.full_name || user.email?.split('@')[0] || '';

        // Get first name only
        const firstName = fullName.split(' ')[0];

        // Capitalize first letter
        return firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
    };

    // Scroll to bottom when new messages arrive
    useEffect(() => {
        if (messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages]);

    // Focus input when chat opens
    useEffect(() => {
        if (isOpen && inputRef.current) {
            inputRef.current.focus();
        }
    }, [isOpen]);

    // Initialize chat with personalized welcome message
    useEffect(() => {
        if (isOpen && messages.length === 0) {
            const firstName = getUserFirstName();
            const greeting = firstName
                ? `¡Hola ${firstName}! 👋`
                : '¡Hola! 👋';

            setMessages([{
                id: 1,
                type: 'bot',
                text: `${greeting} Soy Geni, tu asistente de PresuGenius. Estoy aquí para ayudarte con lo que necesites. ¿Cómo puedo apoyarte hoy?`,
                timestamp: new Date()
            }]);
        }
    }, [isOpen, user, messages]); // AÃ±adir 'messages' a las dependencias

    // Reset unread count when chat opens
    useEffect(() => {
        if (isOpen) {
            setUnreadCount(0);
        }
    }, [isOpen]);

    // Escuchar evento para abrir el chat desde otros componentes
    useEffect(() => {
        const handleOpenSupport = (event) => {
            if (event.detail?.errorReport) {
                setIsOpen(true);
                setErrorReportMode(true);
                // Auto-enviar mensaje sobre el error
                setTimeout(() => {
                    handleSendMessage('Tengo un error en la plataforma');
                }, 300);
            } else {
                setIsOpen(true);
            }
        };

        window.addEventListener('openSupportChat', handleOpenSupport);
        return () => window.removeEventListener('openSupportChat', handleOpenSupport);
    }, []);

    // Cargar configuración dinámica
    useEffect(() => {
        const loadSettings = async () => {
            const number = await systemSettingsService.getSetting('whatsapp_number');
            if (number) setWhatsappNumber(number);
        };
        loadSettings();
    }, []);

    const isProcessingRef = useRef(false);

    const handleSendMessage = async (text = inputValue) => {
        if (!text.trim() || isProcessingRef.current) return;

        isProcessingRef.current = true;
        setIsLoading(true);

        const userMessage = {
            id: Date.now(),
            type: 'user',
            text: text.trim(),
            timestamp: new Date()
        };

        setMessages(prev => [...prev, userMessage]);
        setInputValue('');
        setShowQuickReplies(false);

        // Check if user wants human support
        if (text.toLowerCase().includes('humano') || text.toLowerCase().includes('whatsapp') || text.toLowerCase().includes('persona')) {
            setTimeout(() => {
            setMessages(prev => [...prev, {
                id: Date.now(),
                type: 'bot',
                text: '¡Entendido! Con gusto te pongo en contacto con nuestro equipo. 🧑‍💻\n\nPara una atención más personalizada, puedes escribirnos directamente por WhatsApp. ¡Haz clic en el botón de abajo para empezar a chatear!',
                timestamp: new Date(),
                showWhatsApp: true
            }]);
                setIsLoading(false);
                isProcessingRef.current = false;
            }, 500);
            return;
        }

        // Check if user is reporting an error
        const errorKeywords = ['error', 'falla', 'no funciona', 'problema', 'bug', 'no carga', 'no abre', 'crashea', 'se traba'];
        const isReportingError = errorKeywords.some(keyword => text.toLowerCase().includes(keyword));

        if (isReportingError && !errorReportMode) {
            setErrorReportMode(true);

            // Intentar obtener el último error automáticamente
            const lastError = errorContext.getLastError ? errorContext.getLastError() : null;
            const errorDetails = lastError && errorContext.formatErrorForSupport ? errorContext.formatErrorForSupport() : null;

            setTimeout(() => {
                let helpMessage = `¡Oh no! Parece que hay un problema técnico. No te preocupes, estoy aquí para ayudarte a resolverlo. 🛠️\n\n`;

                if (errorDetails) {
                    helpMessage += `✅ **¡Buena noticia! He detectado un error reciente en tu sesión y lo estoy analizando automáticamente.** Esto nos ayudará mucho.\n\nPara que podamos darte la mejor solución, por favor cuéntame:\n\n1. **¿Qué estabas haciendo justo antes de que apareciera el error?**\n2. **¿Qué fue lo que viste o pasó exactamente?**\n\nSi tienes el mensaje de error exacto, ¡copiarlo y pegarlo sería genial!`;
                } else {
                    helpMessage += `Para que pueda ayudarte de la mejor manera, por favor cuéntame un poco más:\n\n1. **¿Qué estabas intentando hacer cuando ocurrió el problema?**\n2. **¿Apareció algún mensaje de error? Si es así, ¿cuál fue?**\n3. **¿En qué parte de la plataforma estabas?**\n\nCualquier detalle que me des, ¡por pequeño que sea, es de gran ayuda!`;
                }

                setMessages(prev => [...prev, {
                    id: Date.now(),
                    type: 'bot',
                    text: helpMessage,
                    timestamp: new Date(),
                    isErrorHelp: true,
                    hasAutoDetectedError: !!errorDetails,
                    autoErrorDetails: errorDetails
                }]);
                setIsLoading(false);
                isProcessingRef.current = false;
            }, 500);
            return;
        }

        try {
            // Obtener detalles del error si está en modo de reporte
            let errorDetails = null;
            if (errorReportMode && errorContext.getLastError && errorContext.formatErrorForSupport) {
                const lastError = errorContext.getLastError();
                if (lastError) {
                    errorDetails = errorContext.formatErrorForSupport();
                }
            }

            const response = await SupportAIService.sendMessage(text, {
                plan: plan?.name || 'Gratis',
                currentPage: location.pathname,
                userName: getUserFirstName(),
                userEmail: user?.email,
                isErrorReport: errorReportMode,
                errorDetails: errorDetails
            });

            // Reset error mode after getting response
            if (errorReportMode) {
                setErrorReportMode(false);
            }

            // Manejar errores de Rate Limit o mostrar respuesta exitosa
            if (!response.success && response.error && (response.message.includes('límite') || response.message.includes('espera'))) {
                const retryMatch = response.message.match(/espera (\d+)s/);
                const retryAfter = retryMatch ? parseInt(retryMatch[1]) : 60;
                showRateLimitModal(response.message, retryAfter);
            }

            // Detectar respuesta vacía, genérica o sin información útil
            const genericResponses = [
                '',
                'No tengo información suficiente para responder a eso.',
                'Lo siento, no tengo información sobre eso.',
                'Lo siento, tuve un problema al procesar tu mensaje.'
            ];
            const isGeneric =
                !response.message ||
                genericResponses.includes(response.message.trim()) ||
                (response.message.trim().toLowerCase().startsWith('lo siento') && response.message.trim().length < 80);

            let botMessage = {
                id: Date.now(),
                type: 'bot',
                text: response.message || "Lo siento, tuve un problema al procesar tu mensaje.",
                sender: 'bot',
                timestamp: new Date(),
                isError: !response.success || response.isError,
                showWhatsApp: response.showWhatsApp || false
            };

            if (isGeneric) {
                botMessage = {
                    ...botMessage,
                    text: 'No tengo información suficiente para responder a eso. Si lo deseas, puedes reformular tu pregunta o contactar a soporte humano por WhatsApp.',
                    showWhatsApp: true,
                    isError: true
                };
            }

            setMessages(prev => [...prev, botMessage]);

            if (!isOpen) {
                setUnreadCount(prev => prev + 1);
            }
        } catch (error) {
            console.error('Error sending message:', error);

            // Capturar el error para que pueda ser reportado
            ErrorService.logError(error, 'SupportChat.handleSendMessage');

            setMessages(prev => [...prev, {
                id: Date.now(),
                type: 'bot',
                text: '¡Ups! 😬 Parece que estoy teniendo algunos problemas técnicos en este momento. No te preocupes, nuestro equipo ya está al tanto y trabajando para solucionarlo.\n\nMientras tanto, si necesitas ayuda urgente, por favor contáctanos directamente por WhatsApp: +52 281 197 5587. ¡Estaremos encantados de ayudarte!',
                timestamp: new Date(),
                isError: true,
                showWhatsApp: true
            }]);
        } finally {
            setIsLoading(false);
            isProcessingRef.current = false;
        }
    };

    const handleQuickReply = (reply) => {
        if (reply.text === 'Hablar con soporte humano') {
            handleSendMessage('Quiero hablar con soporte humano');
        } else {
            handleSendMessage(reply.text);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSendMessage();
        }
    };

    const resetChat = () => {
        SupportAIService.resetChat();
        setErrorReportMode(false);
        const firstName = getUserFirstName();
        const greeting = firstName ? `¡Hola de nuevo ${firstName}!` : '¡Hola de nuevo!';
        setMessages([{
            id: Date.now(),
            type: 'bot',
            text: `${greeting} 👋 ¡Listo para seguir ayudándote! ¿Qué tienes en mente hoy?`,
            timestamp: new Date()
        }]);
        setShowQuickReplies(true);
    };

    const openWhatsApp = () => {
        const message = encodeURIComponent('Hola, necesito ayuda con PresuGenius');
        window.open(`https://wa.me/${whatsappNumber}?text=${message}`, '_blank');
    };

    const quickReplies = SupportAIService.getQuickReplies();

    return (
        <>
            {/* Floating Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`fixed bottom-6 right-6 z-50 w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all duration-300 transform hover:scale-110 ${isOpen
                    ? 'bg-slate-700 rotate-0'
                    : 'bg-gradient-to-r from-blue-600 to-purple-600 animate-pulse-slow'
                    }`}
            >
                {isOpen ? (
                    <X className="w-6 h-6 text-white" />
                ) : (
                    <>
                        <MessageCircle className="w-6 h-6 text-white" />
                        {unreadCount > 0 && (
                            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center font-bold animate-bounce">
                                {unreadCount}
                            </span>
                        )}
                    </>
                )}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className={`fixed bottom-24 right-6 z-50 w-96 max-w-[calc(100vw-3rem)] bg-white dark:bg-slate-800 rounded-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 transition-all duration-300 flex flex-col ${isMinimized ? 'h-14' : 'h-[500px] max-h-[70vh]'
                    }`}>
                    {/* Header */}
                    <div
                        className="bg-gradient-to-r from-blue-600 via-purple-600 to-blue-600 p-4 flex items-center justify-between cursor-pointer shadow-xl relative overflow-hidden"
                        onClick={() => setIsMinimized(!isMinimized)}
                    >
                        {/* Efecto de brillo sutil animado */}
                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent animate-shimmer"></div>

                        <div className="flex items-center gap-3 relative z-10">
                            <div className="w-11 h-11 bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center shadow-lg border border-white/30 ring-2 ring-white/20">
                                <Bot className="w-6 h-6 text-white drop-shadow-sm" />
                            </div>
                            <div>
                                <h3 className="text-white font-bold text-base leading-tight drop-shadow-sm">Geni - Soporte</h3>
                                <p className="text-white/95 text-xs flex items-center gap-1.5 mt-0.5">
                                    <span className="relative flex items-center justify-center">
                                        <span className="absolute w-2.5 h-2.5 bg-green-400 rounded-full animate-ping opacity-75"></span>
                                        <span className="relative w-2 h-2 bg-green-400 rounded-full block ring-2 ring-green-400/50"></span>
                                    </span>
                                    <span className="font-semibold">En línea</span>
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-1 relative z-10">
                            <button
                                onClick={(e) => { e.stopPropagation(); resetChat(); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95 group"
                                title="Reiniciar chat"
                            >
                                <RefreshCw className="w-4 h-4 text-white group-hover:rotate-180 transition-transform duration-500" />
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); openWhatsApp(); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95"
                                title="WhatsApp"
                            >
                                <Phone className="w-4 h-4 text-white" />
                            </button>
                            <button
                                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                                className="p-2.5 hover:bg-white/20 rounded-xl transition-all duration-200 hover:scale-110 active:scale-95"
                                title={isMinimized ? 'Expandir' : 'Minimizar'}
                            >
                                <ChevronDown className={`w-5 h-5 text-white transition-transform duration-300 ${isMinimized ? 'rotate-180' : ''}`} />
                            </button>
                        </div>
                    </div>

                    {!isMinimized && (
                        <>
                            {/* Messages */}
                            <div className="flex-1 overflow-y-auto p-4 space-y-4 h-[calc(100%-140px)] bg-slate-50 dark:bg-slate-900 scrollbar-hide">
                                {messages.map((message) => (
                                    <div
                                        key={message.id}
                                        className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
                                    >
                                        <div className={`flex items-start gap-2 max-w-[85%] ${message.type === 'user' ? 'flex-row-reverse' : ''}`}>
                                            {/* Avatar */}
                                            <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${message.type === 'user'
                                                ? 'bg-blue-600'
                                                : 'bg-gradient-to-br from-purple-500 to-blue-500'
                                                }`}>
                                                {message.type === 'user' ? (
                                                    <User className="w-4 h-4 text-white" />
                                                ) : (
                                                    <Sparkles className="w-4 h-4 text-white" />
                                                )}
                                            </div>

                                            {/* Message Bubble */}
                                            <div className={`rounded-2xl px-4 py-2.5 ${message.type === 'user'
                                                ? 'bg-blue-600 text-white rounded-tr-sm'
                                                : message.isError
                                                    ? 'bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200 rounded-tl-sm'
                                                    : message.isErrorHelp
                                                        ? 'bg-amber-50 dark:bg-amber-900/30 text-amber-800 dark:text-amber-200 rounded-tl-sm border border-amber-200 dark:border-amber-700'
                                                        : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 shadow-sm rounded-tl-sm'
                                                }`}>
                                                {message.isErrorHelp && (
                                                    <div className="flex items-center gap-2 mb-2 text-amber-600 dark:text-amber-400">
                                                        <AlertTriangle className="w-4 h-4" />
                                                        <span className="text-xs font-semibold">Modo Diagnóstico</span>
                                                    </div>
                                                )}
                                                <div className="text-sm leading-relaxed">
                                                    {renderMarkdown(message.text)}
                                                </div>

                                                {/* WhatsApp Button */}
                                                {message.showWhatsApp && (
                                                    <button
                                                        onClick={openWhatsApp}
                                                        className="mt-3 w-full bg-green-500 hover:bg-green-600 text-white font-medium py-2 px-4 rounded-xl flex items-center justify-center gap-2 transition-colors"
                                                    >
                                                        <Phone className="w-4 h-4" />
                                                        Abrir WhatsApp
                                                        <ExternalLink className="w-3 h-3" />
                                                    </button>
                                                )}

                                                <p className="text-[10px] opacity-50 mt-1">
                                                    {message.timestamp.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })}
                                                </p>
                                            </div>
                                        </div>
                                    </div>
                                ))}

                                {/* Loading indicator */}
                                {isLoading && (
                                    <div className="flex justify-start">
                                        <div className="flex items-start gap-2">
                                            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-500 to-blue-500 flex items-center justify-center">
                                                <Sparkles className="w-4 h-4 text-white" />
                                            </div>
                                            <div className="bg-white dark:bg-slate-800 rounded-2xl rounded-tl-sm px-4 py-3 shadow-sm">
                                                <div className="flex items-center gap-1">
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                                                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Quick Replies */}
                                {showQuickReplies && messages.length <= 1 && !isLoading && (
                                    <div className="space-y-2">
                                        <p className="text-xs text-slate-500 dark:text-slate-400 text-center">Preguntas frecuentes:</p>
                                        <div className="flex flex-wrap gap-2 justify-center">
                                            {quickReplies.map((reply) => (
                                                <button
                                                    key={reply.id}
                                                    onClick={() => handleQuickReply(reply)}
                                                    className="px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-xs text-slate-700 dark:text-slate-300 hover:bg-blue-50 dark:hover:bg-slate-700 hover:border-blue-300 transition-colors flex items-center gap-1"
                                                >
                                                    <span>{reply.icon}</span>
                                                    <span>{reply.text}</span>
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                <div ref={messagesEndRef} />
                            </div>

                            {/* Input */}
                            <div className="p-3 bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700">
                                <div className="flex items-center gap-2">
                                    <input
                                        ref={inputRef}
                                        type="text"
                                        value={inputValue}
                                        onChange={(e) => setInputValue(e.target.value)}
                                        onKeyPress={handleKeyPress}
                                        placeholder="Escribe tu mensaje..."
                                        disabled={isLoading}
                                        className="flex-1 px-4 py-2.5 bg-slate-100 dark:bg-slate-900 border-0 rounded-xl text-sm text-slate-800 dark:text-slate-200 placeholder-slate-500 focus:ring-2 focus:ring-blue-500/30 outline-none transition-all disabled:opacity-50"
                                    />
                                    <button
                                        onClick={() => handleSendMessage()}
                                        disabled={!inputValue.trim() || isLoading}
                                        className="w-10 h-10 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 rounded-xl flex items-center justify-center text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed transform hover:scale-105 active:scale-95"
                                    >
                                        {isLoading ? (
                                            <Loader className="w-5 h-5 animate-spin" />
                                        ) : (
                                            <Send className="w-5 h-5" />
                                        )}
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-400 text-center mt-2">
                                    Powered by AI • <button onClick={openWhatsApp} className="text-green-500 hover:underline">WhatsApp: +{whatsappNumber}</button>
                                </p>
                            </div>
                        </>
                    )}
                </div>
            )}

            {/* CSS for animations and scrollbar */}
            <style>{`
                @keyframes pulse-slow {
                    0%, 100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.5); }
                    50% { box-shadow: 0 0 0 10px rgba(59, 130, 246, 0); }
                }
                .animate-pulse-slow {
                    animation: pulse-slow 2s infinite;
                }
                
                @keyframes shimmer {
                    0% {
                        transform: translateX(-100%);
                    }
                    100% {
                        transform: translateX(100%);
                    }
                }
                .animate-shimmer {
                    animation: shimmer 3s ease-in-out infinite;
                }
                
                /* Ocultar scrollbar pero mantener funcionalidad */
                .scrollbar-hide {
                    -ms-overflow-style: none;  /* IE and Edge */
                    scrollbar-width: none;  /* Firefox */
                    scroll-behavior: smooth;
                }
                
                .scrollbar-hide::-webkit-scrollbar {
                    display: none;  /* Chrome, Safari and Opera */
                    width: 0;
                    height: 0;
                    background: transparent;
                }
            `}</style>
        </>
    );
};

export default SupportChat;

import React from 'react';
import Sidebar from './Sidebar';
import Toast from '../ui/Toast';
import { useProject } from '../../context/ProjectContext';
import { useSidebar } from '../../context/SidebarContext';
import UsageNotification from '../subscription/UsageNotification';
import PricingModal from '../subscription/PricingModal';
import { usePricingModal } from '../../context/PricingModalContext';
import SupportChat from '../support/SupportChat';
import RateLimitModal from '../ui/RateLimitModal';
import { Menu } from 'lucide-react';

const Layout = ({ children, title }) => {
    const { toast, setToast, rateLimitModal, closeRateLimitModal } = useProject();
    const { isOpen, closePricingModal } = usePricingModal();
    const { isCollapsed } = useSidebar();
    const [isMobile, setIsMobile] = React.useState(false);
    const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

    React.useEffect(() => {
        const checkMobile = () => {
            const mobile = window.innerWidth < 768;
            setIsMobile(mobile);
            if (!mobile) setIsMobileMenuOpen(false); // Close mobile menu when switching to desktop
        };
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    // Calcular el ancho del sidebar según el estado
    // En mobile es 0px porque es overlay, en desktop depende del estado
    const sidebarWidth = isMobile ? '0px' : (isCollapsed ? '80px' : '256px'); // w-20 = 80px, w-64 = 256px

    return (
        <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 font-sans text-slate-800 dark:text-slate-100 transition-colors">
            {/* Mobile Overlay */}
            {isMobile && isMobileMenuOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-30 backdrop-blur-sm transition-opacity"
                    onClick={() => setIsMobileMenuOpen(false)}
                />
            )}

            <Sidebar mobileOpen={isMobileMenuOpen} setMobileOpen={setIsMobileMenuOpen} />

            <main className="flex-1 p-1 md:p-2 overflow-y-auto scrollbar-hide print:ml-0 print:p-0 transition-all duration-300" style={{ marginLeft: `${sidebarWidth}` }}>

                <div className="flex justify-between items-center mb-8 print:hidden">
                    <div className="flex items-center gap-3">
                        {/* Hamburger Button for Mobile */}
                        <button
                            className="md:hidden p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                            aria-label="Toggle menu"
                        >
                            <Menu size={24} />
                        </button>

                        <h2 className="text-xl font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest hidden md:block">
                            {title}
                        </h2>
                        {/* Show title on mobile too if hidden above, but user only asked for hamburger. Keeping original title logic partially but allowing it to show if needed. Original Code had it hidden on mobile: `hidden md:block`. I will keep it that way for now unless user wants title on mobile. */}
                        <h2 className="text-lg font-bold text-slate-600 dark:text-slate-300 md:hidden block">
                            {title}
                        </h2>
                    </div>

                    <div className="flex gap-4 ml-auto">
                        <div className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 rounded-full shadow-sm border border-slate-200 dark:border-slate-700">
                            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                            <span className="text-xs font-bold text-slate-600 dark:text-slate-300">v2.4.0 Pro</span>
                        </div>
                    </div>
                </div>

                {children}

                {toast && <Toast message={toast.message} type={toast.type} error={toast.error || null} onClose={() => setToast(null)} />}
            </main>

            <UsageNotification />

            <UsageNotification />

            <PricingModal isOpen={isOpen} onClose={closePricingModal} />

            <RateLimitModal
                isOpen={rateLimitModal.isOpen}
                onClose={closeRateLimitModal}
                message={rateLimitModal.message}
                retryAfter={rateLimitModal.retryAfter}
            />

            {/* AI Support Chat Widget */}
            <SupportChat />

            <style>{`
        @media print {
          aside, button, input, select, .no-print { display: none !important; }
          main { margin-left: 0 !important; padding: 0 !important; width: 100% !important; }
          body { background: white; -webkit-print-color-adjust: exact; }
          .shadow-sm, .shadow-md, .shadow-lg, .shadow-2xl { box-shadow: none !important; }
          table th { background-color: #f1f5f9 !important; color: #000 !important; }
        }
      `}</style>
        </div>
    );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { LayoutDashboard, FileText, Book, History, Hammer, LogOut, User, Layers, FileImage, Key, Moon, Sun, BarChart3, ChevronLeft, ChevronRight, Shield, DollarSign, FileEdit, Camera } from 'lucide-react';

import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { useSidebar } from '../../context/SidebarContext';
import { PDFTemplateService } from '../../services/PDFTemplateService';
import ChangePasswordModal from '../auth/ChangePasswordModal';

const Sidebar = ({ mobileOpen, setMobileOpen }) => {
    const { user, signOut } = useAuth();
    const { isDark, toggleTheme } = useTheme();
    const { isCollapsed, toggleSidebar } = useSidebar();
    const navigate = useNavigate();
    const [hasActiveTemplate, setHasActiveTemplate] = useState(false);
    const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);

    // Verificar si es admin
    const isAdmin = user?.email === 'isc20350265@gmail.com';

    // Determinar si el sidebar debe mostrarse expandido (texto visible)
    // En mobile siempre expandido si está abierto, en desktop depende de isCollapsed
    const isExpanded = mobileOpen || !isCollapsed;

    useEffect(() => {
        const active = PDFTemplateService.getActiveTemplate();
        setHasActiveTemplate(!!active);
    }, []);

    const navItems = [
        { path: '/dashboard', icon: LayoutDashboard, label: 'Tablero' },
        { path: '/editor', icon: FileText, label: 'Presupuesto' },
        { path: '/reports', icon: Camera, label: 'Reportes' },
        { path: '/catalog', icon: Book, label: 'Catálogo' },
        { path: '/templates', icon: Layers, label: 'Plantillas' },
        { path: '/usage', icon: BarChart3, label: 'Mi Uso' },

        {
            path: '/pdf-templates',
            icon: FileImage,
            label: 'Configurar PDF',
            badge: hasActiveTemplate ? '✓' : null
        },
        { path: '/history', icon: History, label: 'Historial' },
        { path: '/pricesearch', icon: DollarSign, label: 'Precios IA' },
        ...(isAdmin ? [{ path: '/admin', icon: Shield, label: 'Administrar', badge: 'Admin' }] : [])
    ];

    const handleLogout = async () => {
        await signOut();
        navigate('/login', { replace: true });
    };

    return (
        <aside className={`
            fixed h-full z-40 transition-all duration-300 shadow-xl bg-slate-900 text-white flex flex-col
            ${mobileOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0
            w-64 ${isCollapsed ? 'md:w-20' : 'md:w-64'}
        `}>
            <div className={`p-6 flex items-center ${!isExpanded ? 'justify-center' : 'gap-3'} border-b border-slate-800 relative`}>
                <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
                    <Hammer className="text-white" size={24} />
                </div>
                {isExpanded && (
                    <div className="block">
                        <h1 className="font-bold text-lg tracking-tight">PresuGenius</h1>
                        <p className="text-[10px] text-slate-400 uppercase tracking-widest">Pro Edition</p>
                    </div>
                )}
                {/* Botón para colapsar/expandir - Solo visible en Desktop */}
                <button
                    onClick={toggleSidebar}
                    className="hidden md:block absolute -right-3 top-1/2 -translate-y-1/2 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-full p-1.5 transition-all z-50 shadow-lg"
                    title={isCollapsed ? 'Expandir menú' : 'Colapsar menú'}
                >
                    {isCollapsed ? (
                        <ChevronRight size={16} className="text-slate-300" />
                    ) : (
                        <ChevronLeft size={16} className="text-slate-300" />
                    )}
                </button>
            </div>

            <nav className="flex-1 py-6 px-3 space-y-2 overflow-y-auto max-h-full scrollbar-thin scrollbar-thumb-slate-700">
                {navItems.map(item => (
                    <NavLink
                        key={item.path}
                        to={item.path}
                        onClick={() => mobileOpen && setMobileOpen(false)} // Cerrar sidebar al navegar en mobile
                        className={({ isActive }) => `w-full flex items-center ${!isExpanded ? 'justify-center px-0' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 group relative
              ${isActive ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40 translate-x-1' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
                        title={!isExpanded ? item.label : ''}
                    >
                        {({ isActive }) => (
                            <>
                                <item.icon size={20} className={isActive ? 'animate-pulse' : ''} />
                                {isExpanded && (
                                    <>
                                        <span className="font-medium block">{item.label}</span>
                                        {item.badge && (
                                            <span className="ml-auto w-5 h-5 rounded-full bg-emerald-500 text-white text-xs flex items-center justify-center font-bold">
                                                {item.badge}
                                            </span>
                                        )}
                                        {isActive && !item.badge && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white block"></div>}
                                    </>
                                )}
                                {!isExpanded && item.badge && (
                                    <span className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 text-white text-[10px] flex items-center justify-center font-bold">
                                        {item.badge}
                                    </span>
                                )}
                            </>
                        )}
                    </NavLink>
                ))}

                {/* PDF Editor - Navigation Link */}
                <NavLink
                    to="/pdf-editor"
                    onClick={() => mobileOpen && setMobileOpen(false)}
                    className={({ isActive }) => `w-full flex items-center ${!isExpanded ? 'justify-center px-0' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 group relative
              ${isActive ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40 translate-x-1' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
                    title={!isExpanded ? 'Editar PDF' : ''}
                >
                    {({ isActive }) => (
                        <>
                            <FileEdit size={20} className={isActive ? 'animate-pulse' : ''} />
                            {isExpanded && <span className="font-medium block">Editar PDF</span>}
                            {isActive && isExpanded && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white block"></div>}
                        </>
                    )}
                </NavLink>
            </nav>

            <div className={`p-4 border-t border-slate-800 space-y-3 ${!isExpanded ? 'px-2' : ''}`}>
                {/* Toggle de Tema */}
                <button
                    onClick={toggleTheme}
                    className={`w-full flex items-center ${!isExpanded ? 'justify-center px-0' : 'justify-center gap-2 px-3'} py-2 bg-slate-800/50 hover:bg-slate-700 rounded-lg text-sm font-medium transition border border-slate-700`}
                    title={isDark ? 'Cambiar a modo claro' : 'Cambiar a modo oscuro'}
                >
                    {isDark ? (
                        <>
                            <Sun size={16} />
                            {isExpanded && <span className="inline">Modo Claro</span>}
                        </>
                    ) : (
                        <>
                            <Moon size={16} />
                            {isExpanded && <span className="inline">Modo Oscuro</span>}
                        </>
                    )}
                </button>

                {user ? (
                    <>
                        {!isExpanded ? (
                            <div className="flex flex-col gap-2">
                                <button
                                    onClick={() => setShowChangePasswordModal(true)}
                                    className="w-full flex items-center justify-center p-2 bg-slate-800/50 hover:bg-slate-700 rounded-lg transition border border-slate-700"
                                    title="Cambiar Contraseña"
                                >
                                    <Key size={16} />
                                </button>
                                <button
                                    onClick={handleLogout}
                                    className="w-full flex items-center justify-center p-2 bg-slate-800/50 hover:bg-slate-700 rounded-lg transition border border-slate-700"
                                    title="Cerrar Sesión"
                                >
                                    <LogOut size={16} />
                                </button>
                                <div className="w-full flex items-center justify-center p-2">
                                    <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center" title={user.email}>
                                        <User size={16} />
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="bg-slate-800/50 rounded-xl p-3 block border border-slate-700 space-y-2">
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center">
                                        <User size={16} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-xs text-slate-400">Conectado como</p>
                                        <p className="text-sm font-medium text-white truncate">{user.email}</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => setShowChangePasswordModal(true)}
                                    className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg text-sm font-medium transition"
                                >
                                    <Key size={14} />
                                    Cambiar Contraseña
                                </button>
                                <button
                                    onClick={handleLogout}
                                    className="w-full flex items-center justify-center gap-2 px-3 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg text-sm font-medium transition"
                                >
                                    <LogOut size={14} />
                                    Cerrar Sesión
                                </button>
                            </div>
                        )}
                    </>
                ) : (
                    isExpanded && (
                        <div className="bg-slate-800/50 rounded-xl p-4 block border border-slate-700">
                            <p className="text-xs text-slate-400 mb-2">Modo Local</p>
                            <button
                                onClick={() => navigate('/login')}
                                className="w-full px-3 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm font-medium transition"
                            >
                                Iniciar Sesión
                            </button>
                        </div>
                    )
                )}
            </div>

            {/* Change Password Modal */}
            <ChangePasswordModal
                isOpen={showChangePasswordModal}
                onClose={() => setShowChangePasswordModal(false)}
            />
        </aside>
    );
};

export default Sidebar;

import React from 'react';
import Sidebar from './Sidebar';
import Toast from '../ui/Toast';
import { useProject } from '../../context/ProjectContext';
import { useSidebar } from '../../context/SidebarContext';
import UsageNotification from '../subscription/UsageNotification';
import PricingModal from '../subscription/PricingModal';
import { usePricingModal } from '../../context/PricingModalContext';
import SupportChat from '../support/SupportChat';
import RateLimitModal from '../ui/RateLimitModal';
import { Menu } from 'lucide-react';

const Layout = ({ children, title }) => {
    const { toast, setToast, rateLimitModal, closeRateLimitModal } = useProject();
    const { isOpen, closePricingModal } = usePricingModal();
    const { isCollapsed } = useSidebar();
    const [isMobile, setIsMobile] = React.useState(false);
    const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

    React.useEffect(() => {
        const checkMobile = () => {
            const mobile = window.innerWidth < 768;
            setIsMobile(mobile);
            if (!mobile) setIsMobileMenuOpen(false); // Close mobile menu when switching to desktop
        };
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    // Calcular el ancho del sidebar según el estado
    // En mobile es 0px porque es overlay, en desktop depende del estado
    const sidebarWidth = isMobile ? '0px' : (isCollapsed ? '80px' : '256px'); // w-20 = 80px, w-64 = 256px

    return (
        <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 font-sans text-slate-800 dark:text-slate-100 transition-colors">
            {/* Mobile Overlay */}
            {isMobile && isMobileMenuOpen && (
                <div
                    className="fixed inset-0 bg-black/50 z-30 backdrop-blur-sm transition-opacity"
                    onClick={() => setIsMobileMenuOpen(false)}
                />
            )}

            <Sidebar mobileOpen={isMobileMenuOpen} setMobileOpen={setIsMobileMenuOpen} />

            <main className="flex-1 p-1 md:p-2 overflow-y-auto scrollbar-hide print:ml-0 print:p-0 transition-all duration-300" style={{ marginLeft: `${sidebarWidth}` }}>

                <div className="flex justify-between items-center mb-8 print:hidden">
                    <div className="flex items-center gap-3">
                        {/* Hamburger Button for Mobile */}
                        <button
                            className="md:hidden p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                            aria-label="Toggle menu"
                        >
                            <Menu size={24} />
                        </button>

                        <h2 className="text-xl font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest hidden md:block">
                            {title}
                        </h2>
                        {/* Show title on mobile too if hidden above, but user only asked for hamburger. Keeping original title logic partially but allowing it to show if needed. Original Code had it hidden on mobile: `hidden md:block`. I will keep it that way for now unless user wants title on mobile. */}
                        <h2 className="text-lg font-bold text-slate-600 dark:text-slate-300 md:hidden block">
                            {title}
                        </h2>
                    </div>

                    <div className="flex gap-4 ml-auto">
                        <div className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 rounded-full shadow-sm border border-slate-200 dark:border-slate-700">
                            <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                            <span className="text-xs font-bold text-slate-600 dark:text-slate-300">v2.4.0 Pro</span>
                        </div>
                    </div>
                </div>

                {children}

                {toast && <Toast message={toast.message} type={toast.type} error={toast.error || null} onClose={() => setToast(null)} />}
            </main>

            <UsageNotification />

            <UsageNotification />

            <PricingModal isOpen={isOpen} onClose={closePricingModal} />

            <RateLimitModal
                isOpen={rateLimitModal.isOpen}
                onClose={closeRateLimitModal}
                message={rateLimitModal.message}
                retryAfter={rateLimitModal.retryAfter}
            />

            {/* AI Support Chat Widget */}
            <SupportChat />

            <style>{`
        @media print {
          aside, button, input, select, .no-print { display: none !important; }
          main { margin-left: 0 !important; padding: 0 !important; width: 100% !important; }
          body { background: white; -webkit-print-color-adjust: exact; }
          .shadow-sm, .shadow-md, .shadow-lg, .shadow-2xl { box-shadow: none !important; }
          table th { background-color: #f1f5f9 !important; color: #000 !important; }
        }
      `}</style>
        </div>
    );
};

export default Layout;

import React from 'react';
import { X, Check, Zap, Crown, ArrowRight, Sparkles, Shield, CheckCircle, Smartphone } from 'lucide-react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useSubscription } from '../../context/SubscriptionContext';
import { SubscriptionService } from '../../services/SubscriptionService';

const PricingModal = ({ isOpen, onClose, previewData = null }) => {
    const { plan } = useSubscription();
    const [pricingData, setPricingData] = React.useState(null);
    const [loading, setLoading] = React.useState(true);
    const [showPayment, setShowPayment] = React.useState(false);

    React.useEffect(() => {
        const loadData = async () => {
            if (previewData) {
                setPricingData(previewData);
                setLoading(false);
                return;
            }

            try {
                const data = await SubscriptionService.getPricingData();
                setPricingData(data);
            } catch (error) {
                console.error('Error loading pricing data:', error);
            } finally {
                setLoading(false);
            }
        };

        if (isOpen) {
            loadData();
        }
    }, [isOpen, previewData]);

    // Reset payment view when modal closes or opens
    React.useEffect(() => {
        if (!isOpen) {
            setShowPayment(false);
        }
    }, [isOpen]);

    if (!isOpen) return null;

    // Default features as fallback
    const defaultFeatures = {
        free: [],
        pro: []
    };

    const plans = [
        {
            id: 'free',
            name: 'Gratis',
            price: 0,
            description: pricingData?.free?.description || 'Perfecto para probar la plataforma',
            icon: Zap,
            iconBg: 'bg-blue-100',
            iconColor: 'text-blue-600',
            borderColor: 'border-slate-200',
            hoverBorder: 'hover:border-blue-300',
            features: (pricingData?.free?.features || defaultFeatures.free).map(text => ({ text, included: true }))
        },
        {
            id: 'pro',
            name: 'Pro',
            price: pricingData?.pro?.price || 299,
            description: pricingData?.pro?.description || 'Para profesionales que necesitan más',
            icon: Crown,
            iconBg: 'bg-indigo-100',
            iconColor: 'text-indigo-600',
            borderColor: 'border-indigo-500',
            hoverBorder: 'hover:border-indigo-600',
            popular: true,
            features: (pricingData?.pro?.features || defaultFeatures.pro).map(text => ({ text, included: true }))
        }
    ];

    const handleUpgrade = (planId) => {
        if (planId === 'pro') {
            setShowPayment(true);
        } else {
            // Logic for downgrading to free if needed
            console.log('Downgrade to free requested');
        }
    };

    const handleCopyInstructions = () => {
        const textToCopy = pricingData?.bankDetails || '';
        navigator.clipboard.writeText(textToCopy);
        // Could add a toast here but for now just simple copy
    };

    const handleWhatsAppClick = () => {
        const text = encodeURIComponent(`Hola, acabo de realizar mi transferencia para el Plan Pro. Mi correo es: [TU CORREO AQUÍ]`);
        window.open(`https://wa.me/5216677981504?text=${text}`, '_blank');
    };

    if (showPayment) {
        return (
            <div
                className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-fadeIn"
                onClick={onClose}
            >
                <div
                    className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col border border-slate-200 dark:border-slate-800"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-2xl translate-x-1/2 -translate-y-1/2"></div>
                        <h2 className="text-2xl font-bold relative z-10">¡Excelente Elección! 🚀</h2>
                        <p className="text-indigo-100 text-sm relative z-10">Estás a un paso de activar tu cuenta Pro</p>
                        <button onClick={() => setShowPayment(false)} className="absolute top-4 left-4 text-white/70 hover:text-white transition z-50">
                            <ArrowRight className="rotate-180" size={20} />
                        </button>
                    </div>

                    <div className="p-8 space-y-6">
                        <div className="bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-200 dark:border-yellow-800 rounded-xl p-4">
                            <p className="text-sm text-yellow-800 dark:text-yellow-200 text-center">
                                Por el momento los pagos son <strong>manuales vía transferencia</strong>.
                            </p>
                        </div>

                        <div className="space-y-2">
                            <div className="flex justify-between items-center mb-2">
                                <h3 className="font-bold text-slate-700 dark:text-slate-300 uppercase text-xs tracking-wider">Instrucciones de Pago</h3>
                                <button
                                    onClick={handleCopyInstructions}
                                    className="text-xs text-indigo-600 hover:text-indigo-700 font-bold flex items-center gap-1 bg-indigo-50 px-2 py-1 rounded-full transition-colors"
                                >
                                    COPIAR DATOS
                                </button>
                            </div>
                            <div className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-5 rounded-2xl text-left text-sm leading-relaxed text-slate-700 dark:text-slate-300">
                                {renderMarkdown(pricingData?.bankDetails || 'Datos bancarios no configurados. Contacta a soporte.')}
                            </div>
                        </div>

                        <div className="pt-2">
                            <button
                                onClick={handleWhatsAppClick}
                                className="w-full bg-[#25D366] hover:bg-[#20bd5a] text-white font-bold py-3.5 rounded-xl flex items-center justify-center gap-2 transition-transform hover:-translate-y-0.5 shadow-lg shadow-green-500/20"
                            >
                                <Smartphone size={20} />
                                Enviar Comprobante por WhatsApp
                            </button>
                            <p className="text-xs text-center text-slate-400 mt-3">
                                Tu cuenta será activada manualmente en cuanto verifiquemos tu pago.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-fadeIn"
            onClick={onClose}
        >
            <div
                className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col transform transition-all scale-100 border border-slate-200 dark:border-slate-800"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Compact Header */}
                <div className="relative bg-gradient-to-r from-blue-700 via-indigo-700 to-purple-700 text-white p-6 overflow-hidden shrink-0">
                    {/* Decorative background shapes */}
                    <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -translate-y-1/2 translate-x-1/2 blur-2xl"></div>
                    <div className="absolute bottom-0 left-0 w-32 h-32 bg-purple-500/20 rounded-full translate-y-1/2 -translate-x-1/2 blur-xl"></div>

                    <button
                        onClick={onClose}
                        className="absolute top-4 right-4 text-white/70 hover:text-white transition p-2 hover:bg-white/10 rounded-full z-50"
                    >
                        <X size={20} />
                    </button>

                    <div className="flex flex-col items-center text-center relative z-10">
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 backdrop-blur-sm border border-white/20 text-xs font-medium mb-3 text-blue-100">
                            <Sparkles size={12} className="text-yellow-300" />
                            <span>Sube de nivel tu productividad</span>
                        </div>
                        <h2 className="text-2xl md:text-3xl font-bold mb-1 tracking-tight">Elige tu Plan Ideal</h2>
                        <p className="text-blue-100 text-sm max-w-lg mx-auto leading-relaxed opacity-90">
                            Desbloquea todo el potencial de la IA para tus presupuestos
                        </p>
                    </div>
                </div>

                {/* Scrollable Content */}
                <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-slate-50 dark:bg-slate-950/50">
                    <div className="grid md:grid-cols-2 gap-6 max-w-3xl mx-auto items-start">
                        {plans.map((planOption) => {
                            const Icon = planOption.icon;
                            const isCurrentPlan = plan.id === planOption.id;
                            const isPro = planOption.id === 'pro';

                            return (
                                <div
                                    key={planOption.id}
                                    className={`relative rounded-2xl transition-all duration-300 ${isPro
                                        ? 'bg-white dark:bg-slate-900 border-2 border-indigo-500 shadow-xl shadow-indigo-500/10 scale-[1.02] md:-mt-2 z-10'
                                        : 'bg-white/80 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm hover:shadow-md'
                                        }`}
                                >
                                    {isPro && (
                                        <div className="absolute -top-3 left-1/2 transform -translate-x-1/2 z-20">
                                            <span className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white px-3 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider shadow-lg border border-white/20">
                                                Recomendado
                                            </span>
                                        </div>
                                    )}

                                    <div className={`p-6 ${isPro ? 'pt-8' : ''}`}>
                                        <div className="flex justify-between items-start mb-4">
                                            <div>
                                                <h3 className={`text-lg font-bold ${isPro ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-700 dark:text-slate-300'}`}>
                                                    {planOption.name}
                                                </h3>
                                                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 min-h-[32px] md:min-h-0">
                                                    {planOption.description}
                                                </p>
                                            </div>
                                            <div className={`p-2.5 rounded-xl ${planOption.iconBg} ${planOption.iconColor}`}>
                                                <Icon size={20} />
                                            </div>
                                        </div>

                                        <div className="flex items-baseline gap-1 mb-6">
                                            <span className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">
                                                ${planOption.price}
                                            </span>
                                            {planOption.price > 0 && (
                                                <span className="text-slate-500 text-sm font-medium">/mes</span>
                                            )}
                                        </div>

                                        <button
                                            onClick={isCurrentPlan ? undefined : () => handleUpgrade(planOption.id)}
                                            disabled={isCurrentPlan}
                                            className={`w-full py-2.5 rounded-lg text-sm font-bold transition-all mb-6 flex items-center justify-center gap-2 ${isCurrentPlan
                                                ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 cursor-default'
                                                : isPro
                                                    ? 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white shadow-lg shadow-indigo-500/25 hover:shadow-indigo-500/40 transform hover:-translate-y-0.5'
                                                    : 'bg-white border-2 border-slate-200 hover:border-slate-300 text-slate-600 hover:text-slate-800'
                                                }`}
                                        >
                                            {isCurrentPlan ? (
                                                <>Plan Actual <CheckCircle size={14} /></>
                                            ) : isPro ? (
                                                <>Actualizar Ahora <Sparkles size={14} /></>
                                            ) : (
                                                'Continuar Gratis'
                                            )}
                                        </button>

                                        <div className="space-y-3">
                                            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">
                                                Incluye:
                                            </div>
                                            {planOption.features.map((feature, index) => (
                                                <div key={index} className="flex items-start gap-2.5 group">
                                                    <div className={`mt-0.5 shrink-0 w-4 h-4 rounded-full flex items-center justify-center ${isPro ? 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400' : 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'
                                                        }`}>
                                                        <Check size={10} strokeWidth={3} />
                                                    </div>
                                                    <span className={`text-sm ${isPro ? 'text-slate-700 dark:text-slate-200 font-medium' : 'text-slate-600 dark:text-slate-400'}`}>
                                                        {feature.text}
                                                    </span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Footer Minimal */}
                <div className="p-4 bg-slate-50 dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 text-center">
                    <p className="text-xs text-slate-400 dark:text-slate-500 flex items-center justify-center gap-4">
                        <span className="flex items-center gap-1"><Shield size={12} /> Pago Seguro</span>
                        <span className="flex items-center gap-1"><Zap size={12} /> Cancelación en cualquier momento</span>
                    </p>
                </div>
            </div>
        </div>
    );
};

