import React, { createContext, useContext, useState, useEffect } from 'react';

const SidebarContext = createContext();

export const useSidebar = () => {
    const context = useContext(SidebarContext);
    if (!context) {
        throw new Error('useSidebar must be used within a SidebarProvider');
    }
    return context;
};

export const SidebarProvider = ({ children }) => {
    const [isCollapsed, setIsCollapsed] = useState(() => {
        const saved = localStorage.getItem('sidebarCollapsed');
        return saved ? JSON.parse(saved) : false;
    });

    useEffect(() => {
        localStorage.setItem('sidebarCollapsed', JSON.stringify(isCollapsed));
    }, [isCollapsed]);

    const toggleSidebar = () => {
        setIsCollapsed(prev => !prev);
    };

    return (
        <SidebarContext.Provider value={{ isCollapsed, setIsCollapsed, toggleSidebar }}>
            {children}
        </SidebarContext.Provider>
    );
};

import React, { useState, useEffect } from 'react';
import { Package, Sparkles, X, AlertTriangle, Loader } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';
import ProjectPersistenceService from '../../services/ProjectPersistenceService';
import MaterialModal from './MaterialModal';

/**
 * MaterialGenerator
 * Componente independiente para generar listas de materiales/insumos con IA
 * Maneja toda la lógica de generación, validación y persistencia
 */
const MaterialGenerator = ({
    items = [],
    projectInfo = {},
    projectId = null,
    materialList: initialMaterialList = [],
    materialAssumptions: initialMaterialAssumptions = [],
    onMaterialsGenerated = null,
    onClose = null,
    showToast = null
}) => {
    const [materialList, setMaterialList] = useState(initialMaterialList);
    const [materialAssumptions, setMaterialAssumptions] = useState(initialMaterialAssumptions);
    const [isGenerating, setIsGenerating] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState(null);

    // Sincronizar cuando cambien las props
    useEffect(() => {
        if (initialMaterialList !== null) {
            setMaterialList(initialMaterialList);
        }
        if (initialMaterialAssumptions !== null) {
            setMaterialAssumptions(initialMaterialAssumptions);
        }
    }, [initialMaterialList, initialMaterialAssumptions]);

    // Validar items antes de generar
    const validateItems = () => {
        if (!items || items.length === 0) {
            return { valid: false, message: 'Agrega partidas antes de generar la lista de insumos' };
        }
        return { valid: true };
    };

    // Abrir modal o generar
    const handleOpenMaterials = () => {
        const validation = validateItems();
        if (!validation.valid) {
            if (showToast) {
                showToast(validation.message, 'warning');
            } else {
                setError(validation.message);
            }
            return;
        }

        // Si ya existe lista de materiales VÁLIDA, abrir el visualizador
        const hasValidMaterials = materialList && Array.isArray(materialList) && materialList.length > 0;

        if (hasValidMaterials) {
            setShowModal(true);
            return;
        }

        // Si no existe, generar directamente
        handleGenerateMaterials();
    };

    // Generar materiales con IA
    const handleGenerateMaterials = async (forceRegenerate = false) => {
        if (items.length === 0) {
            if (showToast) {
                showToast('Agrega partidas primero para generar insumos', 'warning');
            }
            return;
        }

        // Si ya existe y no se fuerza regeneración, solo mostrar
        if (materialList.length > 0 && !forceRegenerate) {
            setShowModal(true);
            return;
        }

        setIsGenerating(true);
        setError(null);
        setShowModal(true);

        try {
            const { materials, assumptions } = await AIBudgetService.generateMaterialTakeoff(items);
            setMaterialList(materials);
            setMaterialAssumptions(assumptions || []);

            // Auto-guardar si hay projectId
            if (projectId && materials) {
                try {
                    // Guardar mediante el guardado del proyecto completo
                    // El autoguardado se encargará de guardarlo
                    if (showToast) {
                        showToast('Lista de insumos generada exitosamente. Se guardará automáticamente.', 'success');
                    }
                } catch (err) {
                    console.error('Error saving materials:', err);
                }
            }

            // Callback opcional
            if (onMaterialsGenerated) {
                onMaterialsGenerated(materials, assumptions || []);
            }
        } catch (error) {
            console.error('Error generating materials:', error);
            const errorMessage = error.message || 'Error al generar la lista de insumos';
            setError(errorMessage);
            if (showToast) {
                showToast(errorMessage, 'error');
            }
            setMaterialList([]);
            setMaterialAssumptions([]);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleClose = () => {
        setShowModal(false);
        if (onClose) {
            onClose();
        }
    };

    // Función para regenerar materiales
    const handleRegenerate = () => {
        setShowModal(false);
        handleGenerateMaterials(true);
    };

    // Actualizar materiales cuando se editen
    const handleMaterialsUpdate = (updatedList, updatedAssumptions) => {
        setMaterialList(updatedList);
        setMaterialAssumptions(updatedAssumptions || []);
        
        // Callback para notificar al componente padre
        if (onMaterialsGenerated) {
            onMaterialsGenerated(updatedList, updatedAssumptions || []);
        }
    };

    return (
        <>
            {/* Botón de Generar/Ver Insumos */}
            <button
                onClick={handleOpenMaterials}
                disabled={isGenerating || !items || items.length === 0}
                className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg font-bold shadow-lg transition-all text-sm
                    ${isGenerating || !items || items.length === 0
                        ? 'bg-slate-700 text-slate-500 cursor-not-allowed shadow-none'
                        : 'bg-indigo-500 hover:bg-indigo-600 text-white shadow-indigo-900/20'
                    }
                `}
                title={!items || items.length === 0 ? 'Agrega partidas primero' : materialList.length > 0 ? 'Ver Lista de Insumos' : 'Generar Lista de Insumos con IA'}
            >
                {isGenerating ? (
                    <>
                        <Loader className="animate-spin" size={16} />
                        <span>Generando...</span>
                    </>
                ) : (
                    <>
                        <Package size={16} />
                        <span className="hidden sm:inline">Insumos</span>
                    </>
                )}
            </button>

            {/* Modal de Materiales */}
            {showModal && (
                <MaterialModal
                    isOpen={showModal}
                    onClose={handleClose}
                    materialList={materialList}
                    materialAssumptions={materialAssumptions}
                    isGenerating={isGenerating}
                    onRegenerate={handleRegenerate}
                    onMaterialsUpdate={handleMaterialsUpdate}
                    projectInfo={projectInfo}
                    error={error}
                />
            )}

            {/* Mensaje de Error (si no hay showToast) */}
            {error && !showToast && (
                <div className="fixed bottom-4 right-4 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 z-50 animate-fadeIn">
                    <AlertTriangle size={20} />
                    <span className="text-sm font-medium">{error}</span>
                    <button
                        onClick={() => setError(null)}
                        className="text-red-600 hover:text-red-800"
                    >
                        <X size={16} />
                    </button>
                </div>
            )}
        </>
    );
};

export default MaterialGenerator;

/**
 * ProjectPersistenceService
 * Servicio centralizado para persistencia de proyectos
 * Maneja guardado, carga, eliminación y sincronización con Supabase
 */

import SupabaseService from './SupabaseService';
import { supabase } from '../lib/supabaseClient';

export class ProjectPersistenceService {
    /**
     * Guarda un proyecto completo con sincronización de cronograma
     * @param {Object} projectData - Datos completos del proyecto
     * @returns {Promise<Object>} - Proyecto guardado con ID actualizado
     */
    static async saveProject(projectData) {
        // Validar que tenga nombre
        if (!projectData.projectInfo?.project) {
            throw new Error('El proyecto debe tener un nombre');
        }
        if (import.meta.env?.DEV) {
            console.debug('[Reporte] ProjectPersistence.saveProject - id:', projectData?.id, 'projectInfo:', {
                project: projectData.projectInfo?.project,
                contractor: projectData.projectInfo?.contractor,
                concepts: projectData.projectInfo?.concepts,
                ubicacion: projectData.projectInfo?.ubicacion,
                lastReportDate: projectData.projectInfo?.lastReportDate,
            })
        }
        // Guardar proyecto principal
        const saved = await SupabaseService.saveProject(projectData);
        if (import.meta.env?.DEV) console.debug('[Reporte] ProjectPersistence.saveProject - resultado OK, id:', saved?.id)

        // Sincronizar cronograma si existe
        if (projectData.scheduleData && saved.id) {
            await this.syncSchedule(saved.id, projectData.scheduleData);
        }

        return saved;
    }

    /**
     * Sincroniza el cronograma con la tabla project_schedules
     * @param {string} projectId - ID del proyecto
     * @param {Object} scheduleData - Datos del cronograma
     */
    static async syncSchedule(projectId, scheduleData) {
        if (!projectId || !scheduleData) return;

        try {
            // Verificar si existe cronograma
            const { data: existing } = await supabase
                .from('project_schedules')
                .select('id')
                .eq('project_id', projectId)
                .maybeSingle();

            if (existing) {
                // Actualizar existente
                await supabase
                    .from('project_schedules')
                    .update({
                        tasks: scheduleData,
                        updated_at: new Date().toISOString()
                    })
                    .eq('id', existing.id);
            } else {
                // Crear nuevo
                await supabase
                    .from('project_schedules')
                    .insert([{
                        project_id: projectId,
                        tasks: scheduleData
                    }]);
            }
        } catch (error) {
            console.error('Error syncing schedule:', error);
            // No lanzar error para no interrumpir el guardado del proyecto
        }
    }

    /**
     * Carga un proyecto completo por ID
     * Valida que el proyecto pertenezca al usuario actual
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Datos completos del proyecto o null
     * @throws {Error} - Si el proyecto no existe o el usuario no tiene permisos
     */
    static async loadProject(projectId) {
        if (!projectId) {
            throw new Error('ID de proyecto requerido');
        }

        try {
            const fullData = await SupabaseService.getProject(projectId);
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] ProjectPersistence.loadProject - projectId:', projectId, 'projectInfo leído:', {
                    project: fullData.projectInfo?.project,
                    contractor: fullData.projectInfo?.contractor,
                    concepts: fullData.projectInfo?.concepts,
                    ubicacion: fullData.projectInfo?.ubicacion,
                    lastReportDate: fullData.projectInfo?.lastReportDate,
                })
            }
            if (!fullData) {
                throw new Error('Proyecto no encontrado');
            }

            // Cargar cronograma desde tabla separada si existe
            const { data: schedule } = await supabase
                .from('project_schedules')
                .select('tasks')
                .eq('project_id', projectId)
                .maybeSingle();

            // Priorizar cronograma de tabla separada, sino usar el del JSON
            if (schedule) {
                fullData.scheduleData = schedule.tasks;
            }

            return fullData;
        } catch (error) {
            console.error('Error loading project:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Lista todos los proyectos (solo metadata)
     * @returns {Promise<Array>} - Lista de proyectos
     */
    static async listProjects() {
        return await SupabaseService.listProjects();
    }

    /**
     * Elimina un proyecto
     * @param {string} projectId - ID del proyecto a eliminar
     */
    static async deleteProject(projectId) {
        if (!projectId) throw new Error('Project ID is required');

        // 1. Eliminar logs de bitácora
        try {
            await supabase
                .from('site_logs')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting logs:', error);
        }

        // 2. Eliminar cronograma asociado
        try {
            await supabase
                .from('project_schedules')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting schedule:', error);
        }

        // 3. Eliminar proyecto principal
        await SupabaseService.deleteProject(projectId);
    }


    /**
     * Renombra un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {string} newName - Nuevo nombre
     */
    static async renameProject(projectId, newName) {
        if (!projectId || !newName) {
            throw new Error('Project ID and new name are required');
        }

        await SupabaseService.updateProjectName(projectId, newName);
    }

    /**
     * Carga un proyecto desde URL params
     * Incluye carga de cronograma desde tabla separada
     * @param {string} projectId - ID del proyecto desde URL
     * @returns {Promise<Object|null>} - Datos completos del proyecto
     */
    static async loadProjectFromUrl(projectId) {
        return await this.loadProject(projectId);
    }
}

export default ProjectPersistenceService;

