                            console.warn(`   ⚠️ Error buscando precio para "${item.description}":`, error.message);
                        }
                    }
                }

                if (replacedCount > 0) {
                    console.log(`✅ ${replacedCount} precio(s) reemplazado(s) con valores exactos de la Base Maestra para mayor consistencia`);
                }
