            let replacedCount = 0;
            let materialsWithRealData = 0;

            const finalMaterials = await Promise.all(validMaterials.map(async (mat) => {
                try {
                    // Buscar precio exacto en la Base Maestra
                    const exactPrices = await MarketPriceService.findReferencePrice(
