import React, { useEffect } from 'react';
import { Navigate, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Loader } from 'lucide-react';

const ProtectedRoute = ({ children, requireAuth = false }) => {
    const { user, loading } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();

    // Monitorear continuamente el estado de autenticación
    useEffect(() => {
        if (!loading) {
            // Si requiere autenticación y no hay usuario, forzar redirección
            if (requireAuth && !user) {
                navigate('/login', { replace: true });
            }
            // Si está en login/registro y ya hay usuario, forzar redirección al dashboard
            if (!requireAuth && user && (location.pathname === '/login' || location.pathname === '/register')) {
                navigate('/dashboard', { replace: true });
            }
        }
    }, [user, loading, requireAuth, navigate, location.pathname]);

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="text-center">
                    <Loader size={48} className="animate-spin text-blue-600 mx-auto mb-4" />
                    <p className="text-slate-600">Cargando...</p>
                </div>
            </div>
        );
    }

    // Si requiere autenticación y no hay usuario, redirigir a login
    if (requireAuth && !user) {
        return <Navigate to="/login" replace />;
    }

    // Si está en login y ya hay usuario, redirigir al dashboard
    if (!requireAuth && user) {
        return <Navigate to="/dashboard" replace />;
    }

    return children;
};

export default ProtectedRoute;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { supabase } from '../lib/supabaseClient';
import { setSentryUser, clearSentryUser } from '../lib/sentry';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check active session
        supabase.auth.getSession().then(({ data: { session } }) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);
            setLoading(false);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            }
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            } else {
                clearSentryUser();
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    const signUp = async (email, password, metadata = {}) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
                data: metadata,
                emailRedirectTo: `${baseUrl}/confirm-email`
            }
        });
        return { data, error };
    };

    const signIn = async (email, password) => {
        const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
        });
        return { data, error };
    };

    const signOut = async () => {
        // Limpiar estado inmediatamente para evitar race conditions antes de la navegación
        setUser(null);

        const { error } = await supabase.auth.signOut();

        // Limpiar usuario de Sentry
        clearSentryUser();

        return { error };
    };

    const resetPassword = async (email) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${baseUrl}/confirm-email`
        });
        return { data, error };
    };

    const updatePassword = async (newPassword) => {
        const { data, error } = await supabase.auth.updateUser({
            password: newPassword
        });
        return { data, error };
    };

    const value = {
        user,
        loading,
        signUp,
        signIn,
        signOut,
        resetPassword,
        updatePassword
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { useState, useEffect } from 'react';
import { Calendar, X, Sparkles, AlertTriangle, CheckCircle, Loader } from 'lucide-react';
import { AIBudgetService } from '../../services/AIBudgetService';
import ProjectPersistenceService from '../../services/ProjectPersistenceService';
import ScheduleModal from '../budget/ScheduleModal';

/**
 * ScheduleGenerator
 * Componente independiente para generar cronogramas de obra con IA
 * Maneja toda la lógica de generación, validación y persistencia
 */
const ScheduleGenerator = ({
    items = [],
    projectInfo = {},
    projectId = null,
    scheduleData: initialScheduleData = null,
    onScheduleGenerated = null,
    onClose = null,
    showToast = null,
    onSaveToBitacora = null
}) => {
    const [scheduleData, setScheduleData] = useState(initialScheduleData);
    const [isGenerating, setIsGenerating] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState(null);
    const [showConfigModal, setShowConfigModal] = useState(false);
    const [config, setConfig] = useState({
        startDate: new Date().toISOString().split('T')[0],
        workDays: {
            mon: true,
            tue: true,
            wed: true,
            thu: true,
            fri: true,
            sat: true,
            sun: false
        },
        notes: ''
    });

    // Sincronizar scheduleData cuando cambie la prop
    useEffect(() => {
        if (initialScheduleData !== null) {
            setScheduleData(initialScheduleData);
        }
    }, [initialScheduleData]);

    // Validar items antes de generar
    const validateItems = () => {
        if (!items || items.length === 0) {
            return { valid: false, message: 'Agrega partidas antes de generar el cronograma' };
        }

        const hasZeroQuantity = items.some(item => item.quantity <= 0);
        if (hasZeroQuantity) {
            return {
                valid: false,
                message: 'Hay partidas con cantidad 0. Por favor completa las cantidades antes de continuar.'
            };
        }

        return { valid: true };
    };

    // Abrir modal de configuración
    const handleOpenConfig = () => {
        const validation = validateItems();
        if (!validation.valid) {
            if (showToast) {
                showToast(validation.message, 'warning');
            } else {
                setError(validation.message);
            }
            return;
        }

        // Si ya existe cronograma VÁLIDO, abrir el visualizador sin regenerar
        // Si existe pero está vacío o inválido, permitir configurar uno nuevo
        const hasValidSchedule = scheduleData && (
            (scheduleData.tasks && Array.isArray(scheduleData.tasks) && scheduleData.tasks.length > 0) ||
            (scheduleData.phases && Array.isArray(scheduleData.phases) && scheduleData.phases.length > 0)
        );

        if (hasValidSchedule) {
            setShowModal(true);
            return;
        }

        setShowConfigModal(true);
    };

