                    <div>
                        <h3 className="font-bold flex items-center text-lg">
                            <Calendar className="mr-2 text-emerald-200" /> Cronograma de Obra Estimado
                        </h3>
                        {scheduleData && (scheduleData.phases?.length > 0 || scheduleData.tasks?.length > 0) && (
                            <p className="text-xs text-emerald-200 mt-1">
                                Cronograma guardado - Puedes editar o regenerar con IA
                            </p>
                        )}
                    </div>
                    <div className="flex items-center gap-2">
                        {onRegenerate && scheduleData && (scheduleData.phases?.length > 0 || scheduleData.tasks?.length > 0) && (
                            <button
                                onClick={onRegenerate}
                                disabled={isGenerating}
                                className="px-3 py-1.5 bg-emerald-700 hover:bg-emerald-500 text-white text-xs font-medium rounded-lg transition flex items-center gap-1 disabled:opacity-50"
                                title="Regenerar cronograma con IA"
                            >
                                <Sparkles size={14} />
                                Regenerar
                            </button>
                        )}
                        <button onClick={onClose} className="text-white/60 hover:text-white transition">
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Pestañas de Vista */}
                {!isGenerating && phases.length > 0 && (
                    <div className="px-6 pt-4 border-b border-slate-200 bg-white">
                        <div className="flex gap-2">
                            <button
                                onClick={() => setViewMode('gantt')}
                                className={`flex items-center gap-2 px-4 py-2 rounded-t-lg font-medium transition ${
                                    viewMode === 'gantt'
                                        ? 'bg-slate-50 text-emerald-600 border-b-2 border-emerald-600'
                                        : 'text-slate-600 hover:text-slate-800 hover:bg-slate-50'
                                }`}
                            >
                                <BarChart3 size={18} />
                                Vista Gantt
                            </button>
                            <button
                                onClick={() => setViewMode('list')}
                                className={`flex items-center gap-2 px-4 py-2 rounded-t-lg font-medium transition ${
                                    viewMode === 'list'
                                        ? 'bg-slate-50 text-emerald-600 border-b-2 border-emerald-600'
                                        : 'text-slate-600 hover:text-slate-800 hover:bg-slate-50'
                                }`}
                            >
                                <List size={18} />
                                Vista Lista
                            </button>
                        </div>
                    </div>
                )}

                {/* Content */}
                <div className={`p-0 flex-1 bg-slate-50 ${viewMode === 'gantt' ? 'overflow-hidden' : 'overflow-y-auto'}`}>
                    {isGenerating ? (
                        <div className="flex flex-col items-center justify-center h-64 space-y-4">
                            <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent"></div>
                            <p className="text-slate-500 font-medium">Calculando tiempos y fases...</p>
                        </div>
                    ) : phases.length > 0 ? (
                        <>
                            {/* Vista Gantt Chart */}
                            {viewMode === 'gantt' ? (
                                <div className="h-full flex flex-col">
                                    {/* Summary Card - Compacta con botón de página dedicada */}
                                    <div className="bg-white p-3 border-b border-slate-200 flex items-center justify-between shrink-0">
                                        <div>
                                            <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Duración Total Estimada</h4>
                                            <div className="flex items-baseline gap-2">
                                                <span className="text-2xl font-bold text-slate-800">{totalDurationWeeks}</span>
                                                <span className="text-slate-500 font-medium text-sm">Semanas</span>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <div className="h-10 w-10 bg-emerald-100 rounded-full flex items-center justify-center">
                                                <Clock className="text-emerald-600" size={20} />
                                            </div>
                                            {currentProjectId && (
                                                <button
                                                    onClick={() => {
                                                        onClose();
                                                        navigate(`/project/${currentProjectId}/schedule`);
                                                    }}
                                                    className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 shadow-lg shadow-emerald-200"
                                                    title="Abrir en página dedicada para mejor visualización"
                                                >
                                                    <ExternalLink size={16} />
                                                    <span>Ver en Página Completa</span>
                                                </button>
                                            )}
                                        </div>
                                    </div>

                                    {/* Gantt Chart Component - Vista previa compacta */}
                                    <div className="flex-1 overflow-hidden p-4">
                                        <div className="bg-slate-100 rounded-lg p-4 h-full flex items-center justify-center border-2 border-dashed border-slate-300">
                                            <div className="text-center">
                                                <BarChart3 className="mx-auto mb-3 text-slate-400" size={48} />
                                                <p className="text-slate-600 font-medium mb-2">Vista Gantt Completa</p>
                                                <p className="text-sm text-slate-500 mb-4">Para una mejor experiencia, abre el cronograma en una página dedicada</p>
                                                {currentProjectId && (
                                                    <button
                                                        onClick={() => {
                                                            onClose();
                                                            navigate(`/project/${currentProjectId}/schedule`);
                                                        }}
                                                        className="px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 mx-auto shadow-lg shadow-emerald-200"
                                                    >
                                                        <ExternalLink size={18} />
                                                        <span>Abrir Página Completa</span>
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                /* Vista Lista (original) */
                                <div className="p-6 space-y-6">
                                    {/* Summary Card */}
                                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
                                        <div>
                                            <h4 className="text-sm font-bold text-slate-400 uppercase mb-1">Duración Total Estimada</h4>
                                            <div className="flex items-baseline gap-2">
                                                <span className="text-3xl font-bold text-slate-800">{totalDurationWeeks}</span>
                                                <span className="text-slate-500 font-medium">Semanas</span>
                                            </div>
                                        </div>
                                        <div className="h-12 w-12 bg-emerald-100 rounded-full flex items-center justify-center">
                                            <Clock className="text-emerald-600" size={24} />
                                        </div>
                                    </div>

                                    {/* Timeline / List */}
                                    <div className="space-y-4">
                                        <h4 className="text-sm font-bold text-slate-700 uppercase">Fases del Proyecto</h4>
                                        <div className="space-y-3">
                                    {phases.map((phase, index) => (
                                        <div key={index} className={`bg-white p-4 rounded-xl border shadow-sm hover:shadow-md transition-shadow ${phase.isCritical ? 'border-red-200 ring-1 ring-red-100' : 'border-slate-200'}`}>
                                            <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center mb-3">
                                                <div>
                                                    <div className="flex items-center gap-2">
                                                        <h5 className="font-bold text-slate-800 text-lg">{phase.name}</h5>
                                                        {phase.isCritical && (
                                                            <span className="px-2 py-0.5 bg-red-100 text-red-700 rounded text-[10px] font-bold border border-red-200 uppercase tracking-wider">
                                                                Ruta Crítica
                                                            </span>
                                                        )}
                                                    </div>
                                                    <p className="text-xs text-slate-500 mt-1">
                                                        {phase.startDate && phase.endDate ? (
                                                            <span className="font-medium text-slate-700">
                                                                {new Date(phase.startDate).toLocaleDateString()} - {new Date(phase.endDate).toLocaleDateString()}
                                                            </span>
                                                        ) : (
                                                            <span>Semana {phase.startWeek} - Semana {phase.endWeek}</span>
                                                        )}
                                                        <span className="ml-2 text-slate-400">({phase.durationWeeks} semanas)</span>
                                                    </p>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <span className={`px-3 py-1 rounded-full text-xs font-bold border ${phase.isCritical ? 'bg-red-50 text-red-700 border-red-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                                                        {phase.durationWeeks} Semanas
                                                    </span>
                                                </div>
                                            </div>

                                            {/* Progress Bar Visual */}
                                            <div className="w-full bg-slate-100 rounded-full h-2 mb-3 overflow-hidden relative">
                                                {/* Grid lines for weeks could go here */}
                                                <div
                                                    className={`h-2 rounded-full opacity-70 ${phase.isCritical ? 'bg-red-500' : 'bg-emerald-500'}`}
                                                    style={{
                                                        width: `${(phase.durationWeeks / totalDurationWeeks) * 100}%`,
                                                        marginLeft: `${((phase.startWeek - 1) / totalDurationWeeks) * 100}%`
                                                    }}
                                                ></div>
                                            </div>

                                            {/* Resources & Risks Grid */}
                                            {(phase.resources?.length > 0 || phase.risks?.length > 0) && (
                                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-3">
                                                    {phase.resources?.length > 0 && (
                                                        <div className="bg-blue-50/50 p-2 rounded border border-blue-100">
                                                            <p className="text-[10px] font-bold text-blue-500 uppercase mb-1">Recursos Clave</p>
                                                            <div className="flex flex-wrap gap-1">
                                                                {phase.resources.map((res, i) => (
                                                                    <span key={i} className="text-[10px] text-blue-700 bg-white px-1.5 py-0.5 rounded border border-blue-200">
                                                                        {res}
                                                                    </span>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    )}
                                                    {phase.risks?.length > 0 && (
                                                        <div className="bg-amber-50/50 p-2 rounded border border-amber-100">
                                                            <p className="text-[10px] font-bold text-amber-600 uppercase mb-1">Riesgos Potenciales</p>
                                                            <ul className="list-disc list-inside text-[10px] text-amber-800">
                                                                {phase.risks.map((risk, i) => (
                                                                    <li key={i}>{risk}</li>
                                                                ))}
                                                            </ul>
                                                        </div>
                                                    )}
                                                </div>
                                            )}

                                            {/* Items included */}
                                            <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                                                <p className="text-xs font-bold text-slate-500 mb-2 uppercase">Partidas Incluidas:</p>
                                                <div className="flex flex-wrap gap-2">
                                                    {phase.items?.map((item, i) => (
                                                        <span key={i} className="text-xs text-slate-600 bg-white px-2 py-1 rounded border border-slate-200">
                                                            {item}
                                                        </span>
                                                    ))}
                                                </div>
                                            </div>

                                            {phase.notes && (
                                                <div className="mt-3 flex gap-2 items-start text-xs text-slate-500 italic">
                                                    <AlertCircle size={14} className="mt-0.5 shrink-0" />
                                                    <span>{phase.notes}</span>
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                        )}
                        </>
                    ) : (
                        <div className="p-12 text-center">
                            <Calendar size={48} className="mx-auto mb-4 opacity-50 text-slate-400" />
                            <p className="text-slate-400 mb-2 font-medium">No se pudo generar el cronograma.</p>
                            {error && (
                                <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-lg max-w-md mx-auto text-left">
                                    <p className="text-sm text-red-700 font-bold mb-2">Error:</p>
                                    <p className="text-sm text-red-700 mb-3">{error}</p>
                                    <div className="text-xs text-red-600 space-y-1">
                                        <p className="font-bold">Posibles soluciones:</p>
                                        <ul className="list-disc list-inside space-y-1 ml-2">
                                            <li>Verifica que el servidor de IA esté corriendo: <code className="bg-red-100 px-1 rounded">npm run gemini-proxy</code></li>
                                            <li>Asegúrate de que todas las partidas tengan cantidad mayor a 0</li>
                                            <li>Revisa la consola del navegador (F12) para más detalles</li>
                                            <li>Intenta generar el cronograma nuevamente</li>
                                        </ul>
                                    </div>
                                </div>
                            )}
                            {!error && (
                                <p className="text-xs text-slate-500 mt-4">Abre la consola del navegador (F12) para ver más detalles del error.</p>
                            )}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-4 bg-white border-t border-slate-200 flex justify-between items-center text-xs text-slate-400">
                    <p>* Tiempos estimados por IA. Verificar disponibilidad de recursos.</p>
                    <div className="flex gap-3">
                        <button className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-bold transition flex items-center gap-2" disabled>
                            <Download size={16} /> PDF (Próximamente)
                        </button>
                        <button onClick={onClose} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-bold transition">
                            Cerrar
                        </button>
                        <button
                            onClick={onSaveToBitacora}
                            disabled={!scheduleData || phases.length === 0}
                            className={`px-6 py-2 rounded-lg font-bold transition flex items-center shadow-lg ${
                                !scheduleData || phases.length === 0
                                    ? 'bg-slate-300 text-slate-500 cursor-not-allowed'
                                    : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-200'
                            }`}
                        >
                            Guardar y ver Bitácora
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ScheduleModal;

import React, { useState, useEffect } from 'react';
import { Share2, X, Copy, Check, Lock, Calendar, Trash2, Eye, ExternalLink, Settings, Clock } from 'lucide-react';
import { ShareService } from '../../services/ShareService';

const ShareProjectModal = ({ isOpen, onClose, projectId, projectName }) => {
    const [shares, setShares] = useState([]);
    const [loading, setLoading] = useState(false);
    const [creating, setCreating] = useState(false);
    const [copiedToken, setCopiedToken] = useState(null);
    const [shareConfig, setShareConfig] = useState({
        expiresIn: null, // días
        password: '',
        includeShortCode: true,
        canEdit: false,
        showSchedule: true // Por defecto mostrar cronograma
    });

    useEffect(() => {
        if (isOpen && projectId) {
            loadShares();
        }
    }, [isOpen, projectId]);

    const loadShares = async () => {
        try {
            setLoading(true);
            const data = await ShareService.getProjectShares(projectId);
            setShares(data || []);
        } catch (error) {
            console.error('Error loading shares:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateShare = async () => {
        if (!projectId) return;

        try {
            setCreating(true);
            
            const expiresAt = shareConfig.expiresIn 
                ? new Date(Date.now() + shareConfig.expiresIn * 24 * 60 * 60 * 1000).toISOString()
                : null;

            const share = await ShareService.createShare(projectId, {
                expiresAt,
                password: shareConfig.password || null,
                includeShortCode: shareConfig.includeShortCode,
                canEdit: shareConfig.canEdit,
                metadata: {
                    showSchedule: shareConfig.showSchedule
                }
            });

            // Recargar lista
            await loadShares();

            // Resetear config
            setShareConfig({
                expiresIn: null,
                password: '',
                includeShortCode: true,
                canEdit: false,
                showSchedule: true
            });

            // Copiar automáticamente
            copyToClipboard(share.shareUrl);
        } catch (error) {
            console.error('Error creating share:', error);
            const errorMessage = error.message || 'Error al crear el enlace compartido. Verifica que el proyecto esté guardado y que la tabla project_shares exista en Supabase.';
            alert(errorMessage);
        } finally {
            setCreating(false);
        }
    };

    const copyToClipboard = async (text) => {
        try {
            await navigator.clipboard.writeText(text);
            setCopiedToken(text);
            setTimeout(() => setCopiedToken(null), 2000);
        } catch (error) {
            console.error('Error copying to clipboard:', error);
        }
    };

    const handleDeleteShare = async (shareId) => {
        if (!confirm('¿Eliminar este enlace compartido?')) return;

        try {
            await ShareService.deleteShare(shareId);
            await loadShares();
        } catch (error) {
            console.error('Error deleting share:', error);
            alert('Error al eliminar el enlace');
        }
    };

    const formatExpiresAt = (date) => {
        if (!date) return 'Sin expiración';
        const expires = new Date(date);
        const now = new Date();
        const diffDays = Math.ceil((expires - now) / (1000 * 60 * 60 * 24));
        
        if (diffDays < 0) return 'Expirado';
        if (diffDays === 0) return 'Expira hoy';
        if (diffDays === 1) return 'Expira mañana';
        return `Expira en ${diffDays} días`;
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 dark:bg-slate-900/80 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-slate-200 dark:border-slate-700">
                {/* Header */}
                <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                    <div>
                        <h3 className="font-bold flex items-center text-xl">
                            <Share2 className="mr-2 text-emerald-200" size={24} />
                            Compartir Presupuesto
                        </h3>
                        <p className="text-sm text-emerald-100 mt-1">{projectName}</p>
                    </div>
                    <button onClick={onClose} className="text-white/80 hover:text-white transition">
                        <X size={24} />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6">
                    {/* Crear nuevo enlace */}
                    <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-6 mb-6 border border-slate-200 dark:border-slate-600">
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Crear Nuevo Enlace Compartido</h4>
                        
                        <div className="space-y-4">
                            {/* Opciones de expiración */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Expiración (opcional)
                                </label>
                                <select
                                    value={shareConfig.expiresIn || ''}
                                    onChange={(e) => setShareConfig({ ...shareConfig, expiresIn: e.target.value ? parseInt(e.target.value) : null })}
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200"
                                >
                                    <option value="">Sin expiración</option>
                                    <option value="1">1 día</option>
                                    <option value="7">7 días</option>
                                    <option value="30">30 días</option>
                                    <option value="90">90 días</option>
                                </select>
                            </div>

                            {/* Contraseña opcional */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                                    Contraseña (opcional)
                                </label>
                                <input
                                    type="password"
                                    value={shareConfig.password}
                                    onChange={(e) => setShareConfig({ ...shareConfig, password: e.target.value })}
                                    placeholder="Dejar vacío para sin contraseña"
                                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none text-slate-800 dark:text-slate-200 placeholder:text-slate-400 dark:placeholder:text-slate-500"
                                />
                            </div>

                            {/* Opciones adicionales */}
                            <div className="space-y-3">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.includeShortCode}
                                        onChange={(e) => setShareConfig({ ...shareConfig, includeShortCode: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">Generar código corto</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={shareConfig.showSchedule}
                                        onChange={(e) => setShareConfig({ ...shareConfig, showSchedule: e.target.checked })}
                                        className="w-4 h-4 text-emerald-600 border-slate-300 dark:border-slate-600 rounded focus:ring-emerald-500 bg-white dark:bg-slate-800"
                                    />
                                    <span className="text-sm text-slate-700 dark:text-slate-300">
                                        Mostrar cronograma al cliente
                                        <span className="text-xs text-slate-500 dark:text-slate-400 ml-1">(si existe)</span>
                                    </span>
                                </label>
                            </div>

                            <button
                                onClick={handleCreateShare}
                                disabled={creating}
                                className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {creating ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                                        Creando...
                                    </>
                                ) : (
                                    <>
                                        <Share2 size={20} />
                                        Crear Enlace Compartido
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {/* Lista de enlaces existentes */}
                    <div>
                        <h4 className="font-bold text-slate-800 dark:text-slate-100 mb-4">Enlaces Compartidos Activos</h4>
                        
                        {loading ? (
                            <div className="text-center py-8">
                                <div className="animate-spin rounded-full h-8 w-8 border-4 border-emerald-500 border-t-transparent mx-auto mb-2"></div>
                                <p className="text-slate-600 dark:text-slate-400 text-sm">Cargando...</p>
                            </div>
                        ) : shares.length === 0 ? (
                            <div className="text-center py-8 bg-slate-50 dark:bg-slate-700/50 rounded-lg border-2 border-dashed border-slate-300 dark:border-slate-600">
                                <Share2 className="mx-auto mb-3 text-slate-400 dark:text-slate-500" size={32} />
                                <p className="text-slate-600 dark:text-slate-300">No hay enlaces compartidos aún</p>
                                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Crea uno usando el formulario de arriba</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {shares.map((share) => {
                                    const isExpired = share.expires_at && new Date(share.expires_at) < new Date();
                                    const isCopied = copiedToken === share.shareUrl;

                                    return (
                                        <div
                                            key={share.id}
                                            className={`rounded-lg border-2 p-4 ${
                                                isExpired 
                                                    ? 'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20' 
                                                    : 'border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-700/50'
                                            }`}
                                        >
                                            <div className="flex items-start justify-between gap-4">
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center gap-2 mb-2">
                                                        <ExternalLink size={16} className="text-slate-400 dark:text-slate-500" />
                                                        <span className="text-xs font-medium text-slate-500 dark:text-slate-400 truncate">
                                                            {share.shareUrl}
                                                        </span>
                                                        {share.password && (
                                                            <Lock size={14} className="text-amber-600 dark:text-amber-500" />
                                                        )}
                                                        {isExpired && (
                                                            <span className="px-2 py-0.5 bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-400 rounded text-xs font-bold">
                                                                Expirado
                                                            </span>
                                                        )}
                                                    </div>

