        const newWarnings = [];
        Object.keys(plan.limits).forEach(key => {
            const limit = plan.limits[key];
            const current = usage[key] || 0;
            
            if (limit !== -1) {
                const percentage = (current / limit) * 100;
                
                // Mostrar advertencia si está entre 80% y 100%
