                        key,
                        name: limitName,
                        current,
                        limit,
                        percentage: Math.round(percentage),
                        remaining: limit - current
                    });
                }
            }
        });

        setWarnings(newWarnings);
    }, [plan, usage, isPro, dismissed]);

