                                    onClick={() => navigate('/usage')}
                                    className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-medium transition"
                                >
                                    Ver Detalles
                                </button>
                            </div>
                        </div>
