        setErrorReportMode(false);
        const firstName = getUserFirstName();
        const greeting = firstName ? `¡Hola de nuevo ${firstName}!` : '¡Hola de nuevo!';
        setMessages([{
            id: Date.now(),
            type: 'bot',
            text: `${greeting} 👋 ¡Listo para seguir ayudándote! ¿Qué tienes en mente hoy?`,
