import React from 'react';

/**
 * Renderiza texto con formato markdown básico a elementos React
 * Soporta: **negrita**, listas numeradas (1. 2. 3.), listas con viñetas (- *), saltos de línea
 */
export function renderMarkdown(text) {
    if (!text || typeof text !== 'string') return null;

    // Dividir por líneas
    const lines = text.split('\n');
    const elements = [];
    let inList = false;
    let listItems = [];
    let listType = null;
    let keyCounter = 0;

    const closeList = () => {
        if (inList && listItems.length > 0) {
            if (listType === 'ordered') {
                elements.push(
                    <ol key={`list-${keyCounter++}`} className="list-decimal list-inside space-y-1 my-2 ml-4">
                        {listItems.map((item, idx) => (
                            <li key={idx} className="ml-2">{renderInlineMarkdown(item)}</li>
                        ))}
                    </ol>
                );
            } else {
                elements.push(
                    <ul key={`list-${keyCounter++}`} className="list-disc list-inside space-y-1 my-2 ml-4">
                        {listItems.map((item, idx) => (
                            <li key={idx} className="ml-2">{renderInlineMarkdown(item)}</li>
                        ))}
                    </ul>
                );
            }
            listItems = [];
            inList = false;
            listType = null;
        }
    };

    lines.forEach((line, index) => {
        const trimmedLine = line.trim();

        // Lista numerada (1. 2. 3.)
        if (/^\d+\.\s/.test(trimmedLine)) {
            if (inList && listType !== 'ordered') {
                closeList();
            }
            inList = true;
            listType = 'ordered';
            const itemText = trimmedLine.replace(/^\d+\.\s/, '');
            listItems.push(itemText);
            return;
        }

        // Lista con viñetas (- * •)
        if (/^[-*•]\s/.test(trimmedLine)) {
            if (inList && listType !== 'unordered') {
                closeList();
            }
            inList = true;
            listType = 'unordered';
            const itemText = trimmedLine.replace(/^[-*•]\s/, '');
            listItems.push(itemText);
            return;
        }

        // Si hay una lista acumulada y esta línea no es parte de la lista
        if (inList) {
            closeList();
        }

        // Línea vacía
        if (trimmedLine.length === 0) {
            if (index > 0 && index < lines.length - 1 && elements.length > 0) {
                elements.push(<br key={`br-${keyCounter++}`} />);
            }
            return;
        }

        // Párrafo normal
        elements.push(
            <p key={`p-${keyCounter++}`} className="my-1.5 leading-relaxed">
                {renderInlineMarkdown(trimmedLine)}
            </p>
        );
    });

    // Cerrar lista si quedó abierta
    closeList();

    return elements.length > 0 ? <>{elements}</> : <p>{text}</p>;
}

/**
 * Renderiza markdown inline (negritas, código, etc.)
 */
function renderInlineMarkdown(text) {
    if (!text || typeof text !== 'string') return null;

    const result = [];
    let remainingText = text;
    let keyCounter = 0;

    // Procesar mientras haya texto
    while (remainingText.length > 0) {
        // Buscar próxima negrita
        const boldMatch = remainingText.match(/\*\*([^*]+?)\*\*/);

        // Buscar próximo código
        const codeMatch = remainingText.match(/`([^`]+)`/);

        // Determinar qué viene primero
        let nextIndex = remainingText.length;
        let nextType = null;
        let nextContent = null;

        if (boldMatch && boldMatch.index !== undefined) {
            if (boldMatch.index < nextIndex) {
                nextIndex = boldMatch.index;
                nextType = 'bold';
                nextContent = boldMatch[1];
            }
        }

        if (codeMatch && codeMatch.index !== undefined) {
            if (codeMatch.index < nextIndex) {
                nextIndex = codeMatch.index;
                nextType = 'code';
                nextContent = codeMatch[1];
            }
        }

        // Si encontramos un formato
        if (nextType) {
            // Agregar texto previo al formato
            if (nextIndex > 0) {
                const beforeText = remainingText.substring(0, nextIndex);
                if (beforeText) {
                    result.push(<span key={`text-${keyCounter++}`}>{beforeText}</span>);
                }
            }

            // Procesar el formato encontrado
            if (nextType === 'bold') {
                result.push(
                    <strong key={`bold-${keyCounter++}`} className="font-semibold">
                        {nextContent}
                    </strong>
                );
                remainingText = remainingText.substring(nextIndex + boldMatch[0].length);
            } else if (nextType === 'code') {
                result.push(
                    <code
                        key={`code-${keyCounter++}`}
                        className="bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded text-xs font-mono"
                    >
                        {nextContent}
                    </code>
                );
                remainingText = remainingText.substring(nextIndex + codeMatch[0].length);
            }
        } else {
            // No hay más formato, agregar el resto del texto y terminar
            if (remainingText) {
                result.push(<span key={`text-${keyCounter++}`}>{remainingText}</span>);
            }
            break;
        }
    }

    return result.length > 0 ? <>{result}</> : text;
}

import React, { useState, useEffect } from 'react';
import { X, Save, Loader, Globe, Lock, AlertTriangle } from 'lucide-react';
import { TemplateService } from '../../services/TemplateService';
import { ErrorService } from '../../services/ErrorService';

const CreateTemplateModal = ({ project, onClose, onSuccess }) => {
    // Safety check
    if (!project) return null;

    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState([]);
    const [error, setError] = useState(null);
    const [formData, setFormData] = useState({
        name: project.name || '',
        description: '',
        categoryId: '',
        isPublic: false
    });

    useEffect(() => {
        loadCategories();
    }, []);

    const loadCategories = async () => {
        try {
            const cats = await TemplateService.getCategories();
            if (cats && cats.length > 0) {
                setCategories(cats);
                setFormData(prev => ({ ...prev, categoryId: cats[0].id }));
            } else {
                setError('No se encontraron categorías disponibles.');
            }
        } catch (error) {
            console.error('Error loading categories:', error);
            setError('Error al cargar las categorías. Por favor recarga la página.');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        // Validate category
        if (!formData.categoryId) {
            setError('Por favor selecciona una categoría.');
            return;
        }

        setLoading(true);
        setError(null); // Limpiar errores anteriores

        try {
            await TemplateService.createTemplate(project.id, formData);
            onSuccess();
            onClose();
        } catch (error) {
            // Capturar el error con ErrorService
            ErrorService.logError(error, 'CreateTemplateModal.handleSubmit', {
                projectId: project.id,
                formData: formData
            });

            // Obtener mensaje amigable
            let userMessage = 'Error al crear la plantilla. Por favor intenta de nuevo.';

            // Mensajes específicos según el tipo de error
            if (error?.code === 'PGRST204') {
                userMessage = 'Error de configuración en la base de datos. Por favor contacta a soporte.';
            } else if (error?.message?.includes('Could not find')) {
                userMessage = 'Error de configuración del servidor. El equipo técnico ha sido notificado.';
            } else if (error?.message) {
                // Usar mensaje del error si es amigable
                userMessage = ErrorService.getErrorMessage(error);
            }

            setError(userMessage);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full">
                {/* Header */}
                <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white rounded-t-xl">
                    <div className="flex items-center justify-between">
                        <h3 className="text-xl font-bold">Guardar como Plantilla</h3>
                        <button
                            onClick={onClose}
                            className="hover:bg-white/20 p-2 rounded-lg transition"
                        >
                            <X size={20} />
                        </button>
                    </div>
                    <p className="text-indigo-100 text-sm mt-2">
                        Convierte este presupuesto en una plantilla reutilizable
                    </p>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {/* Error Message */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-start gap-3">
                            <AlertTriangle className="text-red-600 flex-shrink-0 mt-0.5" size={20} />
                            <div className="flex-1">
                                <p className="text-sm font-medium text-red-800">{error}</p>
                                <p className="text-xs text-red-600 mt-1">
                                    Si el problema persiste, puedes contactar a soporte desde el chat de ayuda.
                                </p>
                            </div>
                            <button
                                type="button"
                                onClick={() => setError(null)}
                                className="text-red-400 hover:text-red-600 transition"
                            >
                                <X size={16} />
                            </button>
                        </div>
                    )}

                    {/* Name */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Nombre de la Plantilla *
                        </label>
                        <input
                            type="text"
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Ej: Casa Habitación Estándar"
                        />
                    </div>

                    {/* Description */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Descripción
                        </label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            rows={3}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Describe para qué tipo de proyectos es útil esta plantilla..."
                        />
                    </div>

                    {/* Category */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Categoría *
                        </label>
                        <select
                            value={formData.categoryId}
                            onChange={(e) => setFormData({ ...formData, categoryId: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-800"
                        >
                            {categories.map(cat => (
                                <option key={cat.id} value={cat.id}>{cat.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Public/Private */}
                    <div className="bg-slate-50 rounded-lg p-4 border border-slate-200">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.isPublic}
                                onChange={(e) => setFormData({ ...formData, isPublic: e.target.checked })}
                                className="w-4 h-4 text-indigo-600 rounded focus:ring-2 focus:ring-indigo-500"
                            />
                            <div className="flex-1">
                                <div className="flex items-center gap-2">
                                    {formData.isPublic ? (
                                        <>
                                            <Globe size={16} className="text-green-600" />
                                            <span className="font-medium text-slate-800">Plantilla Pública</span>
                                        </>
                                    ) : (
                                        <>
                                            <Lock size={16} className="text-slate-600" />
                                            <span className="font-medium text-slate-800">Plantilla Privada</span>
                                        </>
                                    )}
                                </div>
                                <p className="text-xs text-slate-500 mt-1">
                                    {formData.isPublic
                                        ? 'Otros usuarios podrán ver y usar esta plantilla'
                                        : 'Solo tú podrás ver y usar esta plantilla'}
                                </p>
                            </div>
                        </label>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition font-medium"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={loading}
                            className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition font-medium flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            {loading ? (
                                <>
                                    <Loader size={18} className="animate-spin" />
                                    Guardando...
                                </>
                            ) : (
                                <>
                                    <Save size={18} />
                                    Crear Plantilla
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

