import React, { useState, useEffect } from 'react';
import { X, Save, Loader, Globe, Lock, AlertTriangle } from 'lucide-react';
import { TemplateService } from '../../services/TemplateService';
import { ErrorService } from '../../services/ErrorService';

const CreateTemplateModal = ({ project, onClose, onSuccess }) => {
    // Safety check
    if (!project) return null;

    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState([]);
    const [error, setError] = useState(null);
    const [formData, setFormData] = useState({
        name: project.name || '',
        description: '',
        categoryId: '',
        isPublic: false
    });

    useEffect(() => {
        loadCategories();
    }, []);

    const loadCategories = async () => {
        try {
            const cats = await TemplateService.getCategories();
            if (cats && cats.length > 0) {
                setCategories(cats);
                setFormData(prev => ({ ...prev, categoryId: cats[0].id }));
            } else {
                setError('No se encontraron categorías disponibles.');
            }
        } catch (error) {
            console.error('Error loading categories:', error);
            setError('Error al cargar las categorías. Por favor recarga la página.');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        // Validate category
        if (!formData.categoryId) {
            setError('Por favor selecciona una categoría.');
            return;
        }

        setLoading(true);
        setError(null); // Limpiar errores anteriores

        try {
            await TemplateService.createTemplate(project.id, formData);
            onSuccess();
            onClose();
        } catch (error) {
            // Capturar el error con ErrorService
            ErrorService.logError(error, 'CreateTemplateModal.handleSubmit', {
                projectId: project.id,
                formData: formData
            });

            // Obtener mensaje amigable
            let userMessage = 'Error al crear la plantilla. Por favor intenta de nuevo.';

            // Mensajes específicos según el tipo de error
            if (error?.code === 'PGRST204') {
                userMessage = 'Error de configuración en la base de datos. Por favor contacta a soporte.';
            } else if (error?.message?.includes('Could not find')) {
                userMessage = 'Error de configuración del servidor. El equipo técnico ha sido notificado.';
            } else if (error?.message) {
                // Usar mensaje del error si es amigable
                userMessage = ErrorService.getErrorMessage(error);
            }

            setError(userMessage);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full">
                {/* Header */}
                <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white rounded-t-xl">
                    <div className="flex items-center justify-between">
                        <h3 className="text-xl font-bold">Guardar como Plantilla</h3>
                        <button
                            onClick={onClose}
                            className="hover:bg-white/20 p-2 rounded-lg transition"
                        >
                            <X size={20} />
                        </button>
                    </div>
                    <p className="text-indigo-100 text-sm mt-2">
                        Convierte este presupuesto en una plantilla reutilizable
                    </p>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    {/* Error Message */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-start gap-3">
                            <AlertTriangle className="text-red-600 flex-shrink-0 mt-0.5" size={20} />
                            <div className="flex-1">
                                <p className="text-sm font-medium text-red-800">{error}</p>
                                <p className="text-xs text-red-600 mt-1">
                                    Si el problema persiste, puedes contactar a soporte desde el chat de ayuda.
                                </p>
                            </div>
                            <button
                                type="button"
                                onClick={() => setError(null)}
                                className="text-red-400 hover:text-red-600 transition"
                            >
                                <X size={16} />
                            </button>
                        </div>
                    )}

                    {/* Name */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Nombre de la Plantilla *
                        </label>
                        <input
                            type="text"
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Ej: Casa Habitación Estándar"
                        />
                    </div>

                    {/* Description */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Descripción
                        </label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            rows={3}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none resize-none text-slate-800 bg-white placeholder:text-slate-400"
                            placeholder="Describe para qué tipo de proyectos es útil esta plantilla..."
                        />
                    </div>

                    {/* Category */}
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">
                            Categoría *
                        </label>
                        <select
                            value={formData.categoryId}
                            onChange={(e) => setFormData({ ...formData, categoryId: e.target.value })}
                            required
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none bg-white text-slate-800"
                        >
                            {categories.map(cat => (
                                <option key={cat.id} value={cat.id}>{cat.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Public/Private */}
                    <div className="bg-slate-50 rounded-lg p-4 border border-slate-200">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={formData.isPublic}
                                onChange={(e) => setFormData({ ...formData, isPublic: e.target.checked })}
                                className="w-4 h-4 text-indigo-600 rounded focus:ring-2 focus:ring-indigo-500"
                            />
                            <div className="flex-1">
                                <div className="flex items-center gap-2">
                                    {formData.isPublic ? (
                                        <>
                                            <Globe size={16} className="text-green-600" />
                                            <span className="font-medium text-slate-800">Plantilla Pública</span>
                                        </>
                                    ) : (
                                        <>
                                            <Lock size={16} className="text-slate-600" />
                                            <span className="font-medium text-slate-800">Plantilla Privada</span>
                                        </>
                                    )}
                                </div>
                                <p className="text-xs text-slate-500 mt-1">
                                    {formData.isPublic
                                        ? 'Otros usuarios podrán ver y usar esta plantilla'
                                        : 'Solo tú podrás ver y usar esta plantilla'}
                                </p>
                            </div>
                        </label>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition font-medium"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={loading}
                            className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition font-medium flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            {loading ? (
                                <>
                                    <Loader size={18} className="animate-spin" />
                                    Guardando...
                                </>
                            ) : (
                                <>
                                    <Save size={18} />
                                    Crear Plantilla
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CreateTemplateModal;

/**
 * PDFTemplateService
 * Maneja las plantillas de PDF para presupuestos
 * Guarda en localStorage y permite sincronizar con Supabase
 */

import { generateId } from '../utils/helpers';

const STORAGE_KEY = 'presugenius_pdf_templates';
const ACTIVE_TEMPLATE_KEY = 'presugenius_active_pdf_template';

export class PDFTemplateService {
    /**
     * Obtener todas las plantillas
     * @returns {Array} Lista de plantillas
     */
    static getTemplates() {
        try {
            const stored = localStorage.getItem(STORAGE_KEY);
            return stored ? JSON.parse(stored) : [];
        } catch (error) {
            console.error('Error loading PDF templates:', error);
            return [];
        }
    }

    /**
     * Obtener la plantilla activa
     * @returns {Object|null} Plantilla activa o null
     */
    static getActiveTemplate() {
        try {
            const activeId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
            if (!activeId) return null;

            const templates = this.getTemplates();
            return templates.find(t => t.id === activeId) || null;
        } catch (error) {
            console.error('Error loading active template:', error);
            return null;
        }
    }

    /**
     * Guardar una nueva plantilla
     * @param {Object} templateData - Datos de la plantilla
     * @returns {Object} Plantilla guardada
     */
    static saveTemplate(templateData) {
        try {
            const templates = this.getTemplates();
            const now = new Date().toISOString();

            const template = {
                id: templateData.id || generateId(),
                name: templateData.name || 'Plantilla sin nombre',
                headerColor: templateData.headerColor || null, // null = sin color, o array [r, g, b]
                headerTextColor: templateData.headerTextColor || [255, 255, 255], // Color del texto [r, g, b]
                headerTextSize: templateData.headerTextSize || 18, // Tamaño del título en pt
                headerSubtextSize: templateData.headerSubtextSize || 9, // Tamaño del subtítulo en pt
                logoUrl: templateData.logoUrl || null, // URL base64 o blob URL
                logoPosition: templateData.logoPosition || 'left', // 'left', 'center', 'right'
                logoSize: templateData.logoSize || { width: 40, height: 40 }, // mm
                showHeader: templateData.showHeader !== false, // true por defecto
                headerText: templateData.headerText || 'PRESUPUESTO DE OBRA',
                headerSubtext: templateData.headerSubtext || 'DOCUMENTO TÉCNICO',
                footerText: templateData.footerText || '',
                createdAt: templateData.createdAt || now,
                updatedAt: now,
                isActive: templateData.isActive || false
            };

            // Si es la plantilla activa, actualizar la referencia
            // IMPORTANTE: Solo activar si explícitamente se indica isActive = true
            if (template.isActive === true) {
                localStorage.setItem(ACTIVE_TEMPLATE_KEY, template.id);
                // Desactivar otras plantillas
                templates.forEach(t => {
                    if (t.id !== template.id) t.isActive = false;
                });
            } else {
                // Si no está activa, asegurarse de que no esté en la referencia activa
                const currentActiveId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
                if (currentActiveId === template.id) {
                    // Esta plantilla estaba activa pero ahora no lo está, limpiar referencia
                    localStorage.removeItem(ACTIVE_TEMPLATE_KEY);
                }
            }

            // Actualizar o agregar
            const index = templates.findIndex(t => t.id === template.id);
            if (index >= 0) {
                templates[index] = template;
            } else {
                templates.push(template);
            }

            localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
            return template;
        } catch (error) {
            console.error('Error saving PDF template:', error);
            throw new Error('No se pudo guardar la plantilla');
        }
    }

    /**
     * Eliminar una plantilla
     * @param {string} templateId - ID de la plantilla
     */
    static deleteTemplate(templateId) {
        try {
            const templates = this.getTemplates();
            const filtered = templates.filter(t => t.id !== templateId);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));

            // Si era la activa, limpiar referencia
            const activeId = localStorage.getItem(ACTIVE_TEMPLATE_KEY);
            if (activeId === templateId) {
                localStorage.removeItem(ACTIVE_TEMPLATE_KEY);
            }
        } catch (error) {
            console.error('Error deleting template:', error);
            throw new Error('No se pudo eliminar la plantilla');
        }
    }

    /**
     * Establecer una plantilla como activa
     * @param {string} templateId - ID de la plantilla
     */
    static setActiveTemplate(templateId) {
        try {
            const templates = this.getTemplates();

            // Desactivar todas
            templates.forEach(t => t.isActive = false);

            // Activar la seleccionada
            const template = templates.find(t => t.id === templateId);
            if (template) {
                template.isActive = true;
                localStorage.setItem(ACTIVE_TEMPLATE_KEY, templateId);
                localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
                return template;
            }
            return null;
        } catch (error) {
            console.error('Error setting active template:', error);
            throw new Error('No se pudo activar la plantilla');
        }
    }

    /**
     * Convertir imagen a base64
     * @param {File} file - Archivo de imagen
     * @returns {Promise<string>} Base64 string
     */
    static async imageToBase64(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => {
                const base64 = reader.result;
                resolve(base64);
            };
            reader.onerror = reject;
            reader.readAsDataURL(file);
        });
    }

    /**
     * Validar plantilla
     * @param {Object} template - Plantilla a validar
     * @returns {{valid: boolean, errors: string[]}}
     */
    static validateTemplate(template) {
        const errors = [];

        if (!template.name || template.name.trim() === '') {
            errors.push('El nombre de la plantilla es requerido');
        }

        if (template.headerColor && !Array.isArray(template.headerColor)) {
            errors.push('El color del header debe ser un array [r, g, b]');
        }

        if (template.headerColor && template.headerColor.length !== 3) {
            errors.push('El color del header debe tener 3 valores (RGB)');
        }

        if (template.logoUrl && !template.logoUrl.startsWith('data:image')) {
            errors.push('La URL del logo debe ser una imagen en base64');
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }
}

