/**
 * ErrorService
 * Centralized error handling and user-friendly error messages
 * Integrado con Sentry para monitoreo en producción
 */

import { captureException, captureMessage } from '../lib/sentry';

// Variable global para almacenar el contexto de errores (se inyectará desde ErrorContext)
let errorContextRef = null;

export const setErrorContext = (context) => {
    errorContextRef = context;
};

export class ErrorService {
    /**
     * Get user-friendly error message
     * @param {Error|string} error - Error object or message
     * @returns {string}
     */
    static getErrorMessage(error) {
        if (typeof error === 'string') {
            return error;
        }

        if (!error) {
            return 'Ha ocurrido un error desconocido';
        }

        // Network errors
        if (error.message?.includes('fetch') || error.message?.includes('network')) {
            return 'Error de conexión. Verifica tu internet e intenta de nuevo.';
        }

        // API errors
        if (error.message?.includes('API') || error.message?.includes('Gemini')) {
            return 'Error al conectar con el servicio de IA. Intenta más tarde.';
        }

        // Overloaded/Service unavailable errors
        if (error.message?.includes('overloaded') || error.message?.includes('sobrecargado')) {
            return '⚠️ El servicio de IA está sobrecargado en este momento. Por favor espera 30-60 segundos e intenta de nuevo.';
        }

        if (error.message?.includes('quota') || error.message?.includes('limit exceeded') || error.message?.includes('límite')) {
            return '⚠️ Has alcanzado el límite de uso del servicio de IA. Por favor intenta más tarde.';
        }

        // Supabase errors
        if (error.message?.includes('JWT') || error.message?.includes('auth')) {
            return 'Error de autenticación. Por favor, inicia sesión nuevamente.';
        }

        if (error.message?.includes('permission') || error.message?.includes('policy')) {
            return 'No tienes permisos para realizar esta acción.';
        }

        // JSON parsing errors
        if (error.message?.includes('JSON') || error.message?.includes('parse')) {
            return 'Error al procesar los datos. Verifica el formato.';
        }

        // Validation errors
        if (error.message?.includes('validation') || error.message?.includes('valid')) {
            return error.message;
        }

        // Default: return the error message or a generic one
        return error.message || 'Ha ocurrido un error. Intenta nuevamente.';
    }

    /**
     * Log error with context
     * @param {Error|string} error - Error to log
     * @param {string} context - Context where error occurred
     * @param {Object} metadata - Additional metadata
     * @param {string} level - Error level: 'error', 'warning', 'info'
     */
    static logError(error, context = 'Unknown', metadata = {}, level = 'error') {
        const errorMessage = this.getErrorMessage(error);
        
        console.error(`[${context}]`, {
            error: errorMessage,
            originalError: error,
            metadata,
            timestamp: new Date().toISOString()
        });

        // Registrar en el contexto de errores para que el asistente pueda acceder
        if (errorContextRef && errorContextRef.logError) {
            try {
                errorContextRef.logError(error, {
                    context,
                    ...metadata,
                    currentPage: window.location.pathname,
                });
            } catch (e) {
                console.warn('Error al registrar en ErrorContext:', e);
            }
        }

        // Enviar a Sentry si está configurado (solo en producción)
        try {
            const errorObj = error instanceof Error ? error : new Error(errorMessage);
            
            // Agregar contexto adicional al error
            errorObj.context = context;
            errorObj.metadata = metadata;
            
            captureException(errorObj, {
                context,
                ...metadata,
                userFriendlyMessage: errorMessage,
            }, level);
        } catch (sentryError) {
            // Si Sentry falla, continuar sin interrumpir
            console.warn('Error al enviar a Sentry:', sentryError);
        }
    }

    /**
     * Handle API error with retry logic
     * @param {Function} fn - Function to retry
     * @param {number} maxRetries - Maximum number of retries
     * @param {number} delay - Delay between retries in ms
     * @returns {Promise}
     */
    static async withRetry(fn, maxRetries = 3, delay = 1000) {
        let lastError;
        
        for (let i = 0; i < maxRetries; i++) {
            try {
                return await fn();
            } catch (error) {
                lastError = error;
                
                // Don't retry on certain errors
                if (error.message?.includes('validation') || 
                    error.message?.includes('permission') ||
                    error.message?.includes('auth')) {
                    throw error;
                }
                
                if (i < maxRetries - 1) {
                    await new Promise(resolve => setTimeout(resolve, delay * (i + 1)));
                }
            }
        }
        
        throw lastError;
    }
}

export default ErrorService;

import React, { useState } from 'react';
import { Compress, Loader2, CheckCircle, AlertCircle, Zap } from 'lucide-react';
import { useSubscription } from '../../context/SubscriptionContext';
import { ImageUploadService } from '../../services/ImageUploadService';

/**
 * Componente para comprimir imágenes automáticamente
 * Para usuarios Pro: compresión avanzada automática
 * Para usuarios Free: compresión básica o mensaje de error
 */
const ImageCompressor = ({ file, onCompressed, onError, showDetails = false }) => {
    const { isPro } = useSubscription();
    const [compressing, setCompressing] = useState(false);
    const [compressionResult, setCompressionResult] = useState(null);
    const [error, setError] = useState(null);

    const handleCompress = async () => {
        if (!file) {
            const errMsg = 'No se proporcionó ningún archivo';
            setError(errMsg);
            if (onError) onError(errMsg);
            return;
        }

        // Validar tamaño primero
        const validation = ImageUploadService.validateImage(file);
        if (!validation.valid) {
            const errMsg = validation.error;
            setError(errMsg);
            if (onError) onError(errMsg);
            return;
        }

        setCompressing(true);
        setError(null);
        setCompressionResult(null);

        try {
            let result;

            if (isPro) {
                // Usuarios Pro: compresión avanzada
                result = await ImageUploadService.compressImageAdvanced(
                    file,
                    5, // 5MB objetivo
                    1920, // Max width
                    0.6 // Min quality
                );

                setCompressionResult({
                    originalSize: result.originalSize,
                    compressedSize: result.compressedSize,
                    reduction: result.reduction,
                    quality: result.quality,
                    file: result.file
                });

                if (onCompressed) {
                    onCompressed(result.file, {
                        originalSize: result.originalSize,
                        compressedSize: result.compressedSize,
                        reduction: result.reduction
                    });
                }
            } else {
                // Usuarios Free: compresión básica
                if (file.size > ImageUploadService.MAX_FILE_SIZE) {
                    const errMsg = `Tu imagen es demasiado grande (${(file.size / 1024 / 1024).toFixed(2)}MB). El plan Gratis permite máximo 5MB. Actualiza a Pro para compresión automática de imágenes grandes.`;
                    setError(errMsg);
                    if (onError) onError(errMsg);
                    return;
                }

                // Compresión básica para usuarios Free
                result = await ImageUploadService.compressImage(file, 1920, 0.8);
                
                setCompressionResult({
                    originalSize: file.size,
                    compressedSize: result.size,
                    reduction: ((file.size - result.size) / file.size) * 100,
                    file: result
                });

                if (onCompressed) {
                    onCompressed(result, {
                        originalSize: file.size,
                        compressedSize: result.size,
                        reduction: ((file.size - result.size) / file.size) * 100
                    });
                }
            }
        } catch (err) {
            const errMsg = err.message || 'Error al comprimir la imagen';
            console.error('Error comprimiendo imagen:', err);
            setError(errMsg);
            if (onError) onError(errMsg);
        } finally {
            setCompressing(false);
        }
    };

    // Auto-comprimir si es usuario Pro y el archivo es mayor a 5MB
    React.useEffect(() => {
        if (file && isPro && file.size > ImageUploadService.MAX_FILE_SIZE) {
            handleCompress();
        }
    }, [file, isPro]);

    const formatBytes = (bytes) => {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
    };

    if (!file) return null;

    const fileSizeMB = file.size / 1024 / 1024;
    const exceedsLimit = file.size > ImageUploadService.MAX_FILE_SIZE;

    return (
        <div className="w-full">
            {/* Información del archivo */}
            <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-4 mb-3 border border-slate-200 dark:border-slate-700">
                <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                        {file.name}
                    </span>
                    <span className={`text-sm font-bold ${
                        exceedsLimit 
                            ? 'text-red-600 dark:text-red-400' 
                            : 'text-slate-600 dark:text-slate-400'
                    }`}>
                        {formatBytes(file.size)}
                    </span>
                </div>
                
                {exceedsLimit && (
                    <div className="flex items-start gap-2 mt-2 p-2 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded">
                        <AlertCircle className="text-amber-600 dark:text-amber-400 flex-shrink-0 mt-0.5" size={16} />
                        <div className="flex-1">
                            <p className="text-xs font-medium text-amber-800 dark:text-amber-300">
                                {isPro 
                                    ? 'La imagen será comprimida automáticamente'
                                    : `La imagen excede el límite de 5MB. ${fileSizeMB.toFixed(2)}MB detectado.`
                                }
                            </p>
                        </div>
                    </div>
                )}
            </div>

            {/* Resultado de compresión */}
            {compressionResult && (
                <div className="bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded-lg p-3 mb-3">
                    <div className="flex items-center gap-2 mb-2">
                        <CheckCircle className="text-emerald-600 dark:text-emerald-400" size={18} />
                        <span className="text-sm font-bold text-emerald-800 dark:text-emerald-300">
                            Imagen comprimida exitosamente
                        </span>
                    </div>
                    {showDetails && (
                        <div className="text-xs text-emerald-700 dark:text-emerald-400 space-y-1 mt-2">
                            <div className="flex justify-between">
                                <span>Tamaño original:</span>
                                <span className="font-bold">{formatBytes(compressionResult.originalSize)}</span>
                            </div>
                            <div className="flex justify-between">
                                <span>Tamaño comprimido:</span>
                                <span className="font-bold">{formatBytes(compressionResult.compressedSize)}</span>
                            </div>
                            <div className="flex justify-between">
                                <span>Reducción:</span>
                                <span className="font-bold">{compressionResult.reduction.toFixed(1)}%</span>
                            </div>
                            {compressionResult.quality && (
                                <div className="flex justify-between">
                                    <span>Calidad:</span>
                                    <span className="font-bold">{(compressionResult.quality * 100).toFixed(0)}%</span>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Error */}
            {error && (
                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-3 mb-3">
                    <div className="flex items-start gap-2">
                        <AlertCircle className="text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5" size={18} />
                        <p className="text-sm text-red-800 dark:text-red-300">{error}</p>
                    </div>
                </div>
            )}

            {/* Botón de compresión manual (si no es Pro o no se auto-comprimió) */}
            {!isPro && exceedsLimit && !compressing && !compressionResult && (
                <button
                    onClick={handleCompress}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition flex items-center justify-center gap-2"
                >
                    <Compress size={18} />
                    Intentar Comprimir
                </button>
            )}

            {/* Loading */}
            {compressing && (
                <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
                    <div className="flex items-center justify-center gap-3">
                        <Loader2 className="text-blue-600 dark:text-blue-400 animate-spin" size={20} />
                        <span className="text-sm font-medium text-blue-800 dark:text-blue-300">
                            {isPro ? 'Comprimiendo imagen...' : 'Comprimiendo imagen (básico)...'}
                        </span>
                    </div>
                    {isPro && (
                        <p className="text-xs text-blue-600 dark:text-blue-400 text-center mt-2">
                            Usando compresión avanzada Pro
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};

export default ImageCompressor;

/**
 * ImageUploadService
 * Servicio para subida y gestión de imágenes
 * Soporta múltiples imágenes, compresión y validación
 */

export class ImageUploadService {
    // Configuración
    static MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB (actualizado)
    static ALLOWED_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];

    /**
     * Valida un archivo de imagen
     * @param {File} file - Archivo a validar
     * @returns {Object} - { valid: boolean, error: string|null }
     */
    static validateImage(file) {
        if (!file) {
            return { valid: false, error: 'No se seleccionó ningún archivo' };
        }

        if (!this.ALLOWED_TYPES.includes(file.type)) {
            return { 
                valid: false, 
                error: `Tipo de archivo no permitido. Use: ${this.ALLOWED_TYPES.join(', ')}` 
            };
        }

        if (file.size > this.MAX_FILE_SIZE) {
            const maxSizeMB = (this.MAX_FILE_SIZE / 1024 / 1024).toFixed(1);
            const fileSizeMB = (file.size / 1024 / 1024).toFixed(2);
            return { 
                valid: false, 
                error: `El archivo es demasiado grande (${fileSizeMB}MB). El tamaño máximo permitido es ${maxSizeMB}MB. Los usuarios Pro pueden comprimir imágenes automáticamente.` 
            };
        }

        return { valid: true, error: null };
    }

    /**
     * Comprime una imagen antes de subirla (compresión básica)
     * @param {File} file - Archivo de imagen
     * @param {number} maxWidth - Ancho máximo (default: 1920)
     * @param {number} quality - Calidad de compresión (0-1, default: 0.8)
     * @returns {Promise<File>} - Archivo comprimido
     */
    static async compressImage(file, maxWidth = 1920, quality = 0.8) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Redimensionar si es necesario
                    if (width > maxWidth) {
                        height = (height * maxWidth) / width;
                        width = maxWidth;
                    }

                    canvas.width = width;
                    canvas.height = height;

                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    canvas.toBlob(
                        (blob) => {
                            if (!blob) {
                                reject(new Error('Error al comprimir la imagen'));
                                return;
                            }
                            const compressedFile = new File([blob], file.name, {
                                type: file.type,
                                lastModified: Date.now()
                            });
                            resolve(compressedFile);
                        },
                        file.type,
                        quality
                    );
                };
                img.onerror = () => reject(new Error('Error al cargar la imagen'));
                img.src = e.target.result;
            };
            reader.onerror = () => reject(new Error('Error al leer el archivo'));
            reader.readAsDataURL(file);
        });
    }

    /**
     * Comprime una imagen de forma avanzada (para usuarios Pro)
     * Intenta comprimir hasta alcanzar el tamaño máximo deseado
     * @param {File} file - Archivo de imagen
     * @param {number} targetSizeMB - Tamaño objetivo en MB (default: 5MB)
     * @param {number} maxWidth - Ancho máximo (default: 1920)
     * @param {number} minQuality - Calidad mínima permitida (default: 0.6)
     * @returns {Promise<{file: File, originalSize: number, compressedSize: number, reduction: number}>} - Archivo comprimido con métricas
     */
    static async compressImageAdvanced(file, targetSizeMB = 5, maxWidth = 1920, minQuality = 0.6) {
        const targetSizeBytes = targetSizeMB * 1024 * 1024;
        const originalSize = file.size;
        
        // Si ya es menor al tamaño objetivo, retornar original
        if (originalSize <= targetSizeBytes) {
            return {
                file,
                originalSize,
                compressedSize: originalSize,
                reduction: 0
            };
        }

        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    // Calcular dimensiones optimizadas
                    if (width > maxWidth) {
                        height = (height * maxWidth) / width;
                        width = maxWidth;
                    }

                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0, width, height);

                    // Intentar diferentes niveles de calidad
                    const tryCompress = (quality) => {
                        return new Promise((resolveQuality) => {
                            canvas.toBlob(
                                (blob) => {
                                    if (!blob) {
                                        resolveQuality(null);
                                        return;
                                    }
                                    resolveQuality({
                                        blob,
                                        size: blob.size,
                                        quality
                                    });
                                },
                                file.type === 'image/png' ? 'image/jpeg' : file.type, // Convertir PNG a JPEG para mejor compresión
                                quality
                            );
                        });
                    };

                    // Búsqueda binaria de la calidad óptima
                    const findOptimalQuality = async (minQ, maxQ) => {
                        if (maxQ - minQ < 0.05) {
                            // Si la diferencia es muy pequeña, usar la calidad mínima
                            return await tryCompress(minQ);
                        }

                        const midQ = (minQ + maxQ) / 2;
                        const result = await tryCompress(midQ);

                        if (!result || result.size <= 0) {
                            return await tryCompress(minQ);
                        }

                        if (result.size <= targetSizeBytes) {
                            // Si es menor al objetivo, intentar calidad más alta
                            const higher = await tryCompress((midQ + maxQ) / 2);
                            if (higher && higher.size <= targetSizeBytes && higher.quality > result.quality) {
                                return higher;
                            }
                            return result;
                        } else {
                            // Si es mayor, reducir calidad
                            return await findOptimalQuality(minQ, midQ);
                        }
                    };

                    // Iniciar compresión
                    findOptimalQuality(minQuality, 0.95)
                        .then((result) => {
                            if (!result || !result.blob) {
                                reject(new Error('No se pudo comprimir la imagen'));
                                return;
                            }

                            const compressedFile = new File(
                                [result.blob],
                                file.name.replace(/\.png$/i, '.jpg'), // Cambiar extensión si era PNG
                                {
                                    type: result.blob.type,
                                    lastModified: Date.now()
                                }
                            );

                            const reduction = ((originalSize - compressedFile.size) / originalSize) * 100;

                            resolve({
                                file: compressedFile,
                                originalSize,
                                compressedSize: compressedFile.size,
                                reduction: Math.round(reduction * 100) / 100,
                                quality: result.quality
                            });
                        })
                        .catch((error) => {
                            reject(new Error(`Error al comprimir: ${error.message}`));
                        });
                };
                img.onerror = () => reject(new Error('Error al cargar la imagen'));
                img.src = e.target.result;
            };
            reader.onerror = () => reject(new Error('Error al leer el archivo'));
            reader.readAsDataURL(file);
        });
    }

    /**
     * Sube una imagen usando la API existente
     * @param {File} file - Archivo de imagen
     * @param {string} projectId - ID del proyecto (opcional, para organización)
     * @param {string} taskId - ID de la tarea (opcional)
     * @param {Object} options - Opciones adicionales
     * @param {boolean} options.isPro - Si el usuario es Pro (para compresión avanzada)
     * @param {boolean} options.autoCompress - Si debe comprimir automáticamente (default: true)
     * @returns {Promise<string>} - URL pública de la imagen
     */
    static async uploadImage(file, projectId = null, taskId = null, options = {}) {
        const { isPro = false, autoCompress = true } = options;
        
        // Validar archivo
        const validation = this.validateImage(file);
        if (!validation.valid) {
            throw new Error(validation.error);
        }

        // Comprimir imagen si es necesario
        let fileToUpload = file;
        
        if (autoCompress) {
            try {
                // Si el archivo excede el límite y es usuario Pro, usar compresión avanzada
                if (file.size > this.MAX_FILE_SIZE && isPro) {
                    const compressed = await this.compressImageAdvanced(file, 5, 1920, 0.6);
                    fileToUpload = compressed.file;
                    console.log(`Imagen comprimida: ${(file.size / 1024 / 1024).toFixed(2)}MB → ${(compressed.compressedSize / 1024 / 1024).toFixed(2)}MB (${compressed.reduction.toFixed(1)}% reducción)`);
                } else if (file.size > this.MAX_FILE_SIZE) {
                    // Usuario Free con archivo grande
                    throw new Error(`El archivo es demasiado grande (${(file.size / 1024 / 1024).toFixed(2)}MB). El tamaño máximo permitido es ${(this.MAX_FILE_SIZE / 1024 / 1024).toFixed(1)}MB. Los usuarios Pro pueden comprimir imágenes automáticamente.`);
                } else {
                    // Compresión básica para optimizar
                    fileToUpload = await this.compressImage(file, 1920, 0.85);
                }
            } catch (error) {
                // Si falla la compresión pero el archivo es válido, intentar subir el original
                if (file.size <= this.MAX_FILE_SIZE) {
                    console.warn('Error comprimiendo imagen, subiendo original:', error);
                    fileToUpload = file;
                } else {
                    // Si el archivo es demasiado grande y no se pudo comprimir, lanzar error
                    throw error;
                }
            }
        }

        try {
            const formData = new FormData();
            formData.append('file', fileToUpload);

            // En dev sin VITE_API_URL: subida local vía Vite (guardado en uploads/reporte). Con backend: usar su URL.
            const apiBaseUrl = import.meta.env.VITE_API_URL;
            const uploadUrl = apiBaseUrl ? `${apiBaseUrl}/api/upload` : '/api/upload';

            const response = await fetch(uploadUrl, {
                method: 'POST',
                body: formData
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({ error: 'Error desconocido' }));
                throw new Error(errorData.error || 'Error al subir la imagen');
            }

            const data = await response.json();
            return data.url; // La API retorna { url: "...", filename: "..." }
        } catch (error) {
            console.error('Error uploading image:', error);
            throw new Error(`Error al subir la imagen: ${error.message}`);
        }
    }

    /**
     * Sube múltiples imágenes
     * @param {Array<File>} files - Array de archivos
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea (opcional)
     * @returns {Promise<Array<string>>} - Array de URLs públicas
     */
    static async uploadMultipleImages(files, projectId, taskId = null) {
        if (!Array.isArray(files) || files.length === 0) {
            return [];
        }

        const uploadPromises = files.map(file => 
            this.uploadImage(file, projectId, taskId)
        );

        try {
            const urls = await Promise.all(uploadPromises);
            return urls.filter(Boolean); // Filtrar errores
        } catch (error) {
            console.error('Error uploading multiple images:', error);
            throw error;
        }
    }

    /**
     * Elimina una imagen (si se implementa en el backend)
     * @param {string} imageUrl - URL de la imagen
     * @returns {Promise<void>}
     */
    static async deleteImage(imageUrl) {
        if (!imageUrl) return;

        // Por ahora solo loguear, la eliminación se puede implementar en el backend si es necesario
        console.log('Delete image requested:', imageUrl);
        // TODO: Implementar endpoint de eliminación en el backend si es necesario
    }

    /**
     * Elimina múltiples imágenes
     * @param {Array<string>} imageUrls - Array de URLs
     * @returns {Promise<void>}
     */
    static async deleteMultipleImages(imageUrls) {
        if (!Array.isArray(imageUrls) || imageUrls.length === 0) return;

        const deletePromises = imageUrls.map(url => this.deleteImage(url));
        await Promise.allSettled(deletePromises);
    }

    /**
     * Crea una URL de preview local para mostrar antes de subir
     * @param {File} file - Archivo de imagen
     * @returns {string} - URL de preview
     */
    static createPreviewUrl(file) {
        if (!file) return null;
        return URL.createObjectURL(file);
    }

    /**
     * Revoca una URL de preview para liberar memoria
     * @param {string} url - URL de preview
     */
    static revokePreviewUrl(url) {
        if (url && url.startsWith('blob:')) {
            URL.revokeObjectURL(url);
        }
    }
}

export default ImageUploadService;

import React, { useState } from 'react';
import { Compress, Loader2, CheckCircle, AlertCircle, Zap } from 'lucide-react';
import { useSubscription } from '../../context/SubscriptionContext';
import { ImageUploadService } from '../../services/ImageUploadService';

/**
 * Componente para comprimir imágenes automáticamente
 * Para usuarios Pro: compresión avanzada automática
 * Para usuarios Free: compresión básica o mensaje de error
 */
const ImageCompressor = ({ file, onCompressed, onError, showDetails = false }) => {
    const { isPro } = useSubscription();
    const [compressing, setCompressing] = useState(false);
    const [compressionResult, setCompressionResult] = useState(null);
    const [error, setError] = useState(null);

    const handleCompress = async () => {
        if (!file) {
            const errMsg = 'No se proporcionó ningún archivo';
            setError(errMsg);
            if (onError) onError(errMsg);
            return;
        }

        // Validar tamaño primero
        const validation = ImageUploadService.validateImage(file);
        if (!validation.valid) {
            const errMsg = validation.error;
            setError(errMsg);
            if (onError) onError(errMsg);
            return;
        }

        setCompressing(true);
        setError(null);
        setCompressionResult(null);

        try {
            let result;

            if (isPro) {
                // Usuarios Pro: compresión avanzada
                result = await ImageUploadService.compressImageAdvanced(
                    file,
                    5, // 5MB objetivo
                    1920, // Max width
                    0.6 // Min quality
                );

                setCompressionResult({
                    originalSize: result.originalSize,
                    compressedSize: result.compressedSize,
                    reduction: result.reduction,
                    quality: result.quality,
                    file: result.file
                });

                if (onCompressed) {
                    onCompressed(result.file, {
                        originalSize: result.originalSize,
                        compressedSize: result.compressedSize,
                        reduction: result.reduction
                    });
                }
            } else {
                // Usuarios Free: compresión básica
                if (file.size > ImageUploadService.MAX_FILE_SIZE) {
                    const errMsg = `Tu imagen es demasiado grande (${(file.size / 1024 / 1024).toFixed(2)}MB). El plan Gratis permite máximo 5MB. Actualiza a Pro para compresión automática de imágenes grandes.`;
                    setError(errMsg);
                    if (onError) onError(errMsg);
                    return;
                }

                // Compresión básica para usuarios Free
                result = await ImageUploadService.compressImage(file, 1920, 0.8);
                
                setCompressionResult({
                    originalSize: file.size,
                    compressedSize: result.size,
                    reduction: ((file.size - result.size) / file.size) * 100,
                    file: result
                });

                if (onCompressed) {
                    onCompressed(result, {
                        originalSize: file.size,
                        compressedSize: result.size,
                        reduction: ((file.size - result.size) / file.size) * 100
                    });
                }
            }
        } catch (err) {
            const errMsg = err.message || 'Error al comprimir la imagen';
            console.error('Error comprimiendo imagen:', err);
            setError(errMsg);
            if (onError) onError(errMsg);
        } finally {
            setCompressing(false);
        }
    };

    // Auto-comprimir si es usuario Pro y el archivo es mayor a 5MB
    React.useEffect(() => {
        if (file && isPro && file.size > ImageUploadService.MAX_FILE_SIZE) {
            handleCompress();
        }
    }, [file, isPro]);

    const formatBytes = (bytes) => {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
    };

    if (!file) return null;

    const fileSizeMB = file.size / 1024 / 1024;
    const exceedsLimit = file.size > ImageUploadService.MAX_FILE_SIZE;

    return (
        <div className="w-full">
            {/* Información del archivo */}
            <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-4 mb-3 border border-slate-200 dark:border-slate-700">
                <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                        {file.name}
                    </span>
                    <span className={`text-sm font-bold ${
                        exceedsLimit 
                            ? 'text-red-600 dark:text-red-400' 
                            : 'text-slate-600 dark:text-slate-400'
                    }`}>
                        {formatBytes(file.size)}
                    </span>
                </div>
                
                {exceedsLimit && (
                    <div className="flex items-start gap-2 mt-2 p-2 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded">
                        <AlertCircle className="text-amber-600 dark:text-amber-400 flex-shrink-0 mt-0.5" size={16} />
                        <div className="flex-1">
                            <p className="text-xs font-medium text-amber-800 dark:text-amber-300">
                                {isPro 
                                    ? 'La imagen será comprimida automáticamente'
                                    : `La imagen excede el límite de 5MB. ${fileSizeMB.toFixed(2)}MB detectado.`
                                }
                            </p>
                        </div>
                    </div>
                )}
            </div>

            {/* Resultado de compresión */}
            {compressionResult && (
                <div className="bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded-lg p-3 mb-3">
                    <div className="flex items-center gap-2 mb-2">
                        <CheckCircle className="text-emerald-600 dark:text-emerald-400" size={18} />
                        <span className="text-sm font-bold text-emerald-800 dark:text-emerald-300">
                            Imagen comprimida exitosamente
                        </span>
                    </div>
                    {showDetails && (
                        <div className="text-xs text-emerald-700 dark:text-emerald-400 space-y-1 mt-2">
                            <div className="flex justify-between">
                                <span>Tamaño original:</span>
                                <span className="font-bold">{formatBytes(compressionResult.originalSize)}</span>
                            </div>
                            <div className="flex justify-between">
                                <span>Tamaño comprimido:</span>
                                <span className="font-bold">{formatBytes(compressionResult.compressedSize)}</span>
                            </div>
                            <div className="flex justify-between">
                                <span>Reducción:</span>
                                <span className="font-bold">{compressionResult.reduction.toFixed(1)}%</span>
                            </div>
                            {compressionResult.quality && (
                                <div className="flex justify-between">
                                    <span>Calidad:</span>
                                    <span className="font-bold">{(compressionResult.quality * 100).toFixed(0)}%</span>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Error */}
            {error && (
                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-3 mb-3">
                    <div className="flex items-start gap-2">
                        <AlertCircle className="text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5" size={18} />
                        <p className="text-sm text-red-800 dark:text-red-300">{error}</p>
                    </div>
                </div>
            )}

            {/* Botón de compresión manual (si no es Pro o no se auto-comprimió) */}
            {!isPro && exceedsLimit && !compressing && !compressionResult && (
                <button
                    onClick={handleCompress}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition flex items-center justify-center gap-2"
                >
                    <Compress size={18} />
                    Intentar Comprimir
                </button>
            )}

            {/* Loading */}
            {compressing && (
                <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
                    <div className="flex items-center justify-center gap-3">
                        <Loader2 className="text-blue-600 dark:text-blue-400 animate-spin" size={20} />
                        <span className="text-sm font-medium text-blue-800 dark:text-blue-300">
                            {isPro ? 'Comprimiendo imagen...' : 'Comprimiendo imagen (básico)...'}
                        </span>
                    </div>
                    {isPro && (
                        <p className="text-xs text-blue-600 dark:text-blue-400 text-center mt-2">
                            Usando compresión avanzada Pro
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};

export default ImageCompressor;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { useAuth } from './AuthContext';
import { SubscriptionService } from '../services/SubscriptionService';

const SubscriptionContext = createContext();

export const useSubscription = () => {
    const context = useContext(SubscriptionContext);
    if (context === undefined) {
        throw new Error('useSubscription must be used within a SubscriptionProvider');
    }
    return context;
};

export const SubscriptionProvider = ({ children }) => {
    const { user } = useAuth();
    const [plan, setPlan] = useState(SubscriptionService.PLANS.FREE);
    const [usage, setUsage] = useState(SubscriptionService.getDefaultUsage());
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            // Verificar inmediatamente si es un email Pro
            if (user.email && SubscriptionService.isProEmail(user.email)) {
                setPlan(SubscriptionService.PLANS.PRO);
                setUsage(SubscriptionService.getDefaultUsage());
                setLoading(false);
            } else {
                loadSubscriptionData();
            }
        } else {
            setPlan(SubscriptionService.PLANS.FREE);
            setUsage(SubscriptionService.getDefaultUsage());
            setLoading(false);
        }
    }, [user]);

    const loadSubscriptionData = async () => {
        if (!user) return;

        // Verificar primero si es email Pro
        if (user.email && SubscriptionService.isProEmail(user.email)) {
            setPlan(SubscriptionService.PLANS.PRO);
            setUsage(SubscriptionService.getDefaultUsage());
            setLoading(false);
            return;
        }

        setLoading(true);
        try {
            const [userPlan, userUsage] = await Promise.all([
                SubscriptionService.getUserPlan(user.id),
                SubscriptionService.getUserUsage(user.id)
            ]);

            setPlan(userPlan);
            setUsage(userUsage);
        } catch (error) {
            console.error('Error loading subscription data:', error);
            // Si hay error pero es email Pro, asignar Pro
            if (user.email && SubscriptionService.isProEmail(user.email)) {
                setPlan(SubscriptionService.PLANS.PRO);
            }
        } finally {
            setLoading(false);
        }
    };

    const checkLimit = async (actionType) => {
        if (!user) return { allowed: false, remaining: 0 };

        // Si es email Pro, siempre permitir
        if (user.email && SubscriptionService.isProEmail(user.email)) {
            return { allowed: true, remaining: -1, limit: -1, current: 0 };
        }

        const result = await SubscriptionService.canPerformAction(user.id, actionType);

        // Actualizar uso local
        if (result.allowed) {
            setUsage(prev => ({
                ...prev,
                [actionType]: (prev[actionType] || 0) + 1
            }));
        }

        return result;
    };

    const incrementUsage = async (actionType) => {
        if (!user) return;

        try {
            await SubscriptionService.incrementUsage(user.id, actionType);
            await loadSubscriptionData(); // Recargar datos
        } catch (error) {
            console.error('Error incrementing usage:', error);
        }
    };

    const refreshData = async () => {
        await loadSubscriptionData();
    };

    // Determinar si es Pro (por plan o por email especial)
    const isProUser = plan.id === 'pro' || (user?.email && SubscriptionService.isProEmail(user.email));

    const value = {
        plan: isProUser ? SubscriptionService.PLANS.PRO : plan,
        usage,
        loading,
        checkLimit,
        incrementUsage,
        refreshData,
        isPro: isProUser
    };

    return (
        <SubscriptionContext.Provider value={value}>
            {children}
        </SubscriptionContext.Provider>
    );
};

