            errorContext.logError(displayError, {
                source: 'Toast',
                message: message,
                timestamp: new Date().toISOString()
            });
        }
    }, [type, displayError, message, errorContext]);

    const handleReportError = () => {
        if (!displayError && !lastError) return;
        
        setIsReporting(true);
        // Abrir el chat de soporte automáticamente
