                            <AlertTriangle size={20} />
                        ) : (
                            <Info size={20} />
                        )}
                    </div>
                    <div className="flex-1 min-w-0">
                        <p className="font-medium text-sm leading-relaxed">{message}</p>
                        
                        {/* Botón para reportar error */}
