                ai_generations: -1,
                descriptions: -1,
                suggestions: -1
            },
            api_keys: {
                gemini: {
                    free: [],
                    pro: []
                },
                groq: {
                    free: [],
                    pro: []
                },
                deepseek: {
                    free: [],
                    pro: []
                }
            }
        };
    }

    /**
     * Obtener todas las configuraciones
     */
    async getAllSettings(forceRefresh = false) {
        try {
            // Usar caché si es válido
            const now = Date.now();
            if (!forceRefresh && this.cache && (now - this.lastFetch < this.CACHE_DURATION)) {
                return this.cache;
            }

            const { data, error } = await supabase
                .from('app_settings')
                .select('*');

            if (error) throw error;

            // Convertir array a objeto
            const settings = { ...this.defaults };

            for (const item of data) {
                // Desencriptar valores sensibles (api_keys)
                if (item.key === 'api_keys' && item.value && item.value.__encrypted) {
                    try {
                        const decryptedStr = await SecurityUtils.decrypt(item.value.data);
                        if (decryptedStr) {
                            settings[item.key] = JSON.parse(decryptedStr);
                            console.log('🔓 Settings: API Keys desencriptadas correctamente');
                        } else {
                            console.error('❌ Settings: Falló la desencriptación de API Keys');
                        }
                    } catch (e) {
                        console.error('❌ Settings: Error al desencriptar keys', e);
                        // Mantener valor por defecto o raw si falló
                    }
                } else {
                    settings[item.key] = item.value;
                }
            }

            this.cache = settings;
            this.lastFetch = now;
            return settings;
        } catch (error) {
            console.error('Error fetching system settings:', error);
            return this.defaults;
        }
    }

    /**
     * Guardar una configuración
     */
    async saveSetting(key, value) {
        try {
            let valueToSave = value;

            // Encriptar si es api_keys
            if (key === 'api_keys') {
                console.log('🔒 Settings: Encriptando API Keys antes de guardar...');
                const jsonStr = JSON.stringify(value);
                const encryptedData = await SecurityUtils.encrypt(jsonStr);

                if (encryptedData) {
                    valueToSave = {
                        __encrypted: true,
                        data: encryptedData
                    };
                }
            }

            const { error } = await supabase
                .from('app_settings')
                .upsert({
                    key,
                    value: valueToSave,
                    updated_at: new Date().toISOString(),
                    updated_by: (await supabase.auth.getUser()).data.user?.email
                });

            if (error) throw error;

            // Actualizar caché local (con el valor plano para la app)
            if (this.cache) {
                this.cache[key] = value;
            }

            return true;
        } catch (error) {
            console.error(`Error saving setting ${key}:`, error);
            throw error;
        }
    }

    /**
     * Obtiene una configuración específica
     */
    async getSetting(key, defaultValue = null) {
        const settings = await this.getAllSettings();
        return settings[key] ?? defaultValue;
    }
}

export const systemSettingsService = new SystemSettingsService();

import React, { useState, useEffect } from 'react';
import { Save, RefreshCw, Smartphone, CreditCard, Key, Shield, CheckCircle, AlertCircle, Plus, Trash2, Eye, Users, Search, ToggleLeft, ToggleRight } from 'lucide-react';
import { renderMarkdown } from '../utils/markdownRenderer';
import { systemSettingsService } from '../services/SystemSettingsService';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../lib/supabaseClient'; // Import supabase for user management
import PricingModal from '../components/subscription/PricingModal';
import Toast from '../components/ui/Toast';
import { SubscriptionService } from '../services/SubscriptionService';

const AdminDashboard = () => {
    const { user } = useAuth();
    const [settings, setSettings] = useState(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [activeTab, setActiveTab] = useState('general');
    const [toast, setToast] = useState(null);
    const [showPreview, setShowPreview] = useState(false);

    // User Management State
    const [users, setUsers] = useState([]);
    const [loadingUsers, setLoadingUsers] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Initial load
    useEffect(() => {
        loadSettings();
    }, []);

    // Load users when tab changes
    useEffect(() => {
        if (activeTab === 'users') {
            loadUsers();
        }
    }, [activeTab]);

    const loadSettings = async () => {
        setLoading(true);
        try {
            const data = await systemSettingsService.getAllSettings();
            setSettings(data);
        } catch (error) {
            console.error(error);
            showToast('Error cargando configuración', 'error');
        } finally {
            setLoading(false);
        }
    };

    const loadUsers = async () => {
        setLoadingUsers(true);
        try {
            // Fetch profiles
            const { data: profiles, error: profilesError } = await supabase
                .from('profiles')
                .select('*')
                .order('created_at', { ascending: false });

            if (profilesError) throw profilesError;

            // Fetch subscriptions
            const { data: subs, error: subsError } = await supabase
                .from('user_subscriptions')
                .select('user_id, plan');

            if (subsError) throw subsError;

            // Merge data
            const mergedUsers = profiles.map(profile => {
                const sub = subs.find(s => s.user_id === profile.id);
                return {
                    ...profile,
                    subscription_tier: sub ? sub.plan : 'free'
                };
            });

            setUsers(mergedUsers || []);
        } catch (error) {
            console.error(error);
            showToast('Error cargando usuarios', 'error');
        } finally {
            setLoadingUsers(false);
        }
    };

    const toggleUserPlan = async (userId, currentTier) => {
        const newTier = currentTier === 'pro' ? 'free' : 'pro';
        try {
            const success = await SubscriptionService.setUserPlan(userId, newTier);

            if (!success) throw new Error('Error updating plan');

            setUsers(users.map(u => u.id === userId ? { ...u, subscription_tier: newTier } : u));
            showToast(`Usuario actualizado a ${newTier.toUpperCase()}`, 'success');
        } catch (error) {
            console.error(error);
            showToast('Error actualizando usuario', 'error');
        }
    };

    const handleSave = async (key, value) => {
        setSaving(true);
        try {
            const success = await systemSettingsService.saveSetting(key, value);
            if (success) {
                setSettings(prev => ({ ...prev, [key]: value }));
                showToast('Configuración guardada', 'success');
            } else {
                showToast('Error al guardar', 'error');
            }
        } catch (error) {
            showToast('Error inesperado', 'error');
        } finally {
            setSaving(false);
        }
    };

    const showToast = (message, type) => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    };

    const getPreviewData = () => {
        if (!settings) return null;
        return {
            pro: {
                price: settings.plan_pro_price,
                description: settings.plan_pro_description,
                features: settings.plan_pro_features || []
            },
            free: {
                description: settings.plan_free_description,
                features: settings.plan_free_features || []
            },
            bankDetails: settings.bank_details
        };
    };

    const filteredUsers = users.filter(u =>
        u.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        u.full_name?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (loading) {
        return <div className="p-8 text-center text-slate-500">Cargando configuración del sistema...</div>;
    }

    return (
