        limit: 0
    });

    // Auto-load project from URL
    React.useEffect(() => {
        if (id && id !== projectInfo.id && !isDemoMode) {
            const loadProjectFromUrl = async () => {
                try {
                    const fullData = await ProjectPersistenceService.loadProjectFromUrl(id);
