                }
                if (data.totals?.total) {
                    console.log(`  - Total: $${data.totals.total.toLocaleString('es-MX')}`);
                }
            } else {
                throw new Error('Formato de respuesta inválido');
            }

        } catch (error) {
            console.error(error);
            showToast(error.message || 'Error al importar PDF', 'error');
        } finally {
