                }
            } else {
                throw new Error('Formato de respuesta inválido');
            }

        } catch (error) {
            console.error(error);
            showToast(error.message || 'Error al importar PDF', 'error');
        } finally {
            setIsImporting(false);
            e.target.value = null; // Reset input
