                <ShareProjectModal
                    isOpen={showShareModal}
                    onClose={() => setShowShareModal(false)}
                    projectId={projectInfo.id}
                    projectName={projectInfo.project || 'Presupuesto'}
                />
            )}
        </div>
    );
};

