import React from 'react';
import { AlertTriangle } from 'lucide-react';

const ConfirmModal = ({ isOpen, onClose, onConfirm, onCancel, title, message, confirmText = 'Confirmar', cancelText = 'Cancelar', type = 'warning' }) => {
    if (!isOpen) return null;

    const handleCancel = () => {
        if (onCancel) {
            onCancel();
        }
        onClose();
    };

    const handleConfirm = () => {
        if (onConfirm) {
            onConfirm();
        }
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden transform transition-all scale-100">
                <div className="p-6 text-center">
                    <div className={`mx-auto flex items-center justify-center h-12 w-12 rounded-full mb-4 ${type === 'danger' ? 'bg-red-100' : type === 'info' ? 'bg-blue-100' : 'bg-amber-100'}`}>
                        <AlertTriangle className={`h-6 w-6 ${type === 'danger' ? 'text-red-600' : type === 'info' ? 'text-blue-600' : 'text-amber-600'}`} />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900 mb-2">{title}</h3>
                    <p className="text-sm text-slate-500 mb-6 whitespace-pre-line">{message}</p>

                    <div className="flex gap-3 justify-center">
                        <button
                            onClick={handleCancel}
                            className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg font-medium transition"
                        >
                            {cancelText}
                        </button>
                        <button
                            onClick={handleConfirm}
                            className={`px-4 py-2 text-white rounded-lg font-bold transition shadow-lg ${type === 'danger'
                                    ? 'bg-red-600 hover:bg-red-700 shadow-red-200'
                                    : type === 'info'
                                    ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'
                                    : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'
                                }`}
                        >
                            {confirmText}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ConfirmModal;

import React, { useState, useEffect, useMemo } from 'react';
import { History as HistoryIcon, Trash2, Search, Filter, X, Calendar, DollarSign, ChevronUp, ChevronDown } from 'lucide-react';
import { useProject } from '../context/ProjectContext';
import { formatCurrency } from '../utils/format';
import Card from '../components/ui/Card';

const History = () => {
    const { loadBudget, deleteBudget: contextDeleteBudget } = useProject();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState('date'); // 'date', 'name', 'total', 'items'
    const [sortOrder, setSortOrder] = useState('desc'); // 'asc', 'desc'
    const [filterType, setFilterType] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [priceRange, setPriceRange] = useState({ min: '', max: '' });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            // Import dynamically to avoid circular dependencies if any, or just use the imported service
            const { default: ProjectPersistenceService } = await import('../services/ProjectPersistenceService');
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading history:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id, name) => {
        if (window.confirm(`¿Eliminar el proyecto "${name}"?`)) {
            await contextDeleteBudget(id);
            // Reload list to ensure sync
            loadProjects();
        }
    };

    // Filtrar y ordenar proyectos
    const filteredAndSortedProjects = useMemo(() => {
        let filtered = [...projects];

        // Búsqueda por texto
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => 
                p.project?.toLowerCase().includes(searchLower) ||
                p.client?.toLowerCase().includes(searchLower) ||
                p.type?.toLowerCase().includes(searchLower)
            );
        }

        // Filtro por tipo
        if (filterType !== 'all') {
            filtered = filtered.filter(p => p.type === filterType);
        }

        // Filtro por rango de fechas
        if (dateRange.start || dateRange.end) {
            filtered = filtered.filter(p => {
                if (!p.lastModified) return false;
                const projectDate = new Date(p.lastModified);
                if (dateRange.start && projectDate < new Date(dateRange.start)) return false;
                if (dateRange.end && projectDate > new Date(dateRange.end + 'T23:59:59')) return false;
                return true;
