                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Ordenamiento */}
                    <div className="flex items-center gap-4 pt-2 border-t border-slate-200 dark:border-slate-700">
                        <span className="text-sm text-slate-600 dark:text-slate-400">Ordenar por:</span>
                        <div className="flex gap-2">
                            {[
                                { key: 'date', label: 'Fecha' },
                                { key: 'name', label: 'Nombre' },
                                { key: 'total', label: 'Total' },
                                { key: 'items', label: 'Partidas' }
                            ].map(option => (
                                <button
                                    key={option.key}
                                    onClick={() => handleSort(option.key)}
                                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm transition ${
                                        sortBy === option.key
                                            ? 'bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 font-medium'
                                            : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                                    }`}
                                >
                                    {option.label}
                                    {sortBy === option.key && (
                                        sortOrder === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </Card>

            {/* Contador de resultados */}
            {!loading && projects.length > 0 && (
                <div className="text-sm text-slate-600 dark:text-slate-400">
                    Mostrando {filteredAndSortedProjects.length} de {projects.length} proyectos
                    {hasActiveFilters && ' (filtrados)'}
                </div>
            )}

            {loading ? (
                <div className="text-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                </div>
            ) : projects.length === 0 ? (
                <Card className="text-center py-20">
                    <HistoryIcon size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400">No hay proyectos guardados aún.</p>
                </Card>
            ) : filteredAndSortedProjects.length === 0 ? (
                <Card className="text-center py-20">
                    <Search size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400 mb-2">No se encontraron proyectos con los filtros seleccionados.</p>
                    <button
                        onClick={clearFilters}
                        className="text-blue-600 dark:text-blue-400 hover:underline"
                    >
                        Limpiar filtros
                    </button>
                </Card>
            ) : (
                <div className="grid gap-4">
                    {filteredAndSortedProjects.map(b => (
                        <Card key={b.id} className="p-6 hover:shadow-md transition">
                            <div className="flex justify-between items-center">
                                <div className="flex-1">
                                    <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100 mb-1">{b.project}</h3>
                                    <p className="text-sm text-slate-600 dark:text-slate-400 mb-2">
                                        Cliente: {b.client || 'Sin cliente'} • {b.lastModified ? new Date(b.lastModified).toLocaleDateString('es-MX', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        }) : 'Fecha desconocida'}
                                    </p>
                                    <div className="flex gap-2 flex-wrap">
                                        <span className="text-xs bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 px-2 py-1 rounded font-medium">{b.type || 'General'}</span>
                                        <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 px-2 py-1 rounded">{b.items?.length || 0} partidas</span>
                                    </div>
                                </div>
                                <div className="text-right ml-4">
                                    <p className="font-bold text-xl text-blue-600 dark:text-blue-400 font-mono mb-3">{formatCurrency(b.total || 0)}</p>
                                    <div className="flex gap-2 justify-end">
                                        <button 
                                            onClick={() => loadBudget(b)} 
                                            className="px-4 py-2 text-sm bg-blue-600 dark:bg-blue-500 hover:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold rounded-lg transition"
                                        >
                                            Abrir
                                        </button>
                                        <button
                                            onClick={() => handleDelete(b.id, b.project)}
                                            className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                            title="Eliminar proyecto"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

export default History;

/**
 * ProjectPersistenceService
 * Servicio centralizado para persistencia de proyectos
 * Maneja guardado, carga, eliminación y sincronización con Supabase
 */

import SupabaseService from './SupabaseService';
import { supabase } from '../lib/supabaseClient';

export class ProjectPersistenceService {
    /**
     * Guarda un proyecto completo con sincronización de cronograma
     * @param {Object} projectData - Datos completos del proyecto
     * @returns {Promise<Object>} - Proyecto guardado con ID actualizado
     */
    static async saveProject(projectData) {
        // Validar que tenga nombre
        if (!projectData.projectInfo?.project) {
            throw new Error('El proyecto debe tener un nombre');
        }
        if (import.meta.env?.DEV) {
            console.debug('[Reporte] ProjectPersistence.saveProject - id:', projectData?.id, 'projectInfo:', {
                project: projectData.projectInfo?.project,
                contractor: projectData.projectInfo?.contractor,
                concepts: projectData.projectInfo?.concepts,
                ubicacion: projectData.projectInfo?.ubicacion,
                lastReportDate: projectData.projectInfo?.lastReportDate,
            })
        }
        // Guardar proyecto principal
        const saved = await SupabaseService.saveProject(projectData);
        if (import.meta.env?.DEV) console.debug('[Reporte] ProjectPersistence.saveProject - resultado OK, id:', saved?.id)

        // Sincronizar cronograma si existe
        if (projectData.scheduleData && saved.id) {
            await this.syncSchedule(saved.id, projectData.scheduleData);
        }

        return saved;
    }

    /**
     * Sincroniza el cronograma con la tabla project_schedules
     * @param {string} projectId - ID del proyecto
     * @param {Object} scheduleData - Datos del cronograma
     */
    static async syncSchedule(projectId, scheduleData) {
        if (!projectId || !scheduleData) return;

        try {
            // Verificar si existe cronograma
            const { data: existing } = await supabase
                .from('project_schedules')
                .select('id')
                .eq('project_id', projectId)
                .maybeSingle();

            if (existing) {
                // Actualizar existente
                await supabase
                    .from('project_schedules')
                    .update({
                        tasks: scheduleData,
                        updated_at: new Date().toISOString()
                    })
                    .eq('id', existing.id);
            } else {
                // Crear nuevo
                await supabase
                    .from('project_schedules')
                    .insert([{
                        project_id: projectId,
                        tasks: scheduleData
                    }]);
            }
        } catch (error) {
            console.error('Error syncing schedule:', error);
            // No lanzar error para no interrumpir el guardado del proyecto
        }
    }

    /**
     * Carga un proyecto completo por ID
     * Valida que el proyecto pertenezca al usuario actual
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Datos completos del proyecto o null
     * @throws {Error} - Si el proyecto no existe o el usuario no tiene permisos
     */
    static async loadProject(projectId) {
        if (!projectId) {
            throw new Error('ID de proyecto requerido');
        }

        try {
            const fullData = await SupabaseService.getProject(projectId);
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] ProjectPersistence.loadProject - projectId:', projectId, 'projectInfo leído:', {
                    project: fullData.projectInfo?.project,
                    contractor: fullData.projectInfo?.contractor,
                    concepts: fullData.projectInfo?.concepts,
                    ubicacion: fullData.projectInfo?.ubicacion,
                    lastReportDate: fullData.projectInfo?.lastReportDate,
                })
            }
            if (!fullData) {
                throw new Error('Proyecto no encontrado');
            }

            // Cargar cronograma desde tabla separada si existe
            const { data: schedule } = await supabase
                .from('project_schedules')
                .select('tasks')
                .eq('project_id', projectId)
                .maybeSingle();

            // Priorizar cronograma de tabla separada, sino usar el del JSON
            if (schedule) {
                fullData.scheduleData = schedule.tasks;
            }

            return fullData;
        } catch (error) {
            console.error('Error loading project:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Lista todos los proyectos (solo metadata)
     * @returns {Promise<Array>} - Lista de proyectos
     */
    static async listProjects() {
        return await SupabaseService.listProjects();
    }

    /**
     * Elimina un proyecto
     * @param {string} projectId - ID del proyecto a eliminar
     */
    static async deleteProject(projectId) {
        if (!projectId) throw new Error('Project ID is required');

        // 1. Eliminar logs de bitácora
        try {
            await supabase
                .from('site_logs')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting logs:', error);
        }

        // 2. Eliminar cronograma asociado
        try {
            await supabase
                .from('project_schedules')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting schedule:', error);
        }

        // 3. Eliminar proyecto principal
        await SupabaseService.deleteProject(projectId);
    }


    /**
     * Renombra un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {string} newName - Nuevo nombre
     */
    static async renameProject(projectId, newName) {
        if (!projectId || !newName) {
            throw new Error('Project ID and new name are required');
        }

        await SupabaseService.updateProjectName(projectId, newName);
    }

    /**
     * Carga un proyecto desde URL params
     * Incluye carga de cronograma desde tabla separada
     * @param {string} projectId - ID del proyecto desde URL
     * @returns {Promise<Object|null>} - Datos completos del proyecto
     */
    static async loadProjectFromUrl(projectId) {
        return await this.loadProject(projectId);
    }
}

export default ProjectPersistenceService;

import React, { useState, useEffect, useMemo } from 'react';
import { History as HistoryIcon, Trash2, Search, Filter, X, Calendar, DollarSign, ChevronUp, ChevronDown } from 'lucide-react';
import { useProject } from '../context/ProjectContext';
import { formatCurrency } from '../utils/format';
import Card from '../components/ui/Card';

const History = () => {
    const { loadBudget, deleteBudget: contextDeleteBudget } = useProject();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState('date'); // 'date', 'name', 'total', 'items'
    const [sortOrder, setSortOrder] = useState('desc'); // 'asc', 'desc'
    const [filterType, setFilterType] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [priceRange, setPriceRange] = useState({ min: '', max: '' });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            // Import dynamically to avoid circular dependencies if any, or just use the imported service
            const { default: ProjectPersistenceService } = await import('../services/ProjectPersistenceService');
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading history:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id, name) => {
        if (window.confirm(`¿Eliminar el proyecto "${name}"?`)) {
            await contextDeleteBudget(id);
            // Reload list to ensure sync
            loadProjects();
        }
    };

    // Filtrar y ordenar proyectos
    const filteredAndSortedProjects = useMemo(() => {
        let filtered = [...projects];

        // Búsqueda por texto
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => 
                p.project?.toLowerCase().includes(searchLower) ||
                p.client?.toLowerCase().includes(searchLower) ||
                p.type?.toLowerCase().includes(searchLower)
            );
        }

        // Filtro por tipo
        if (filterType !== 'all') {
            filtered = filtered.filter(p => p.type === filterType);
        }

        // Filtro por rango de fechas
        if (dateRange.start || dateRange.end) {
            filtered = filtered.filter(p => {
                if (!p.lastModified) return false;
                const projectDate = new Date(p.lastModified);
                if (dateRange.start && projectDate < new Date(dateRange.start)) return false;
                if (dateRange.end && projectDate > new Date(dateRange.end + 'T23:59:59')) return false;
                return true;
            });
        }

        // Filtro por rango de precios
        if (priceRange.min || priceRange.max) {
            filtered = filtered.filter(p => {
                const total = p.total || 0;
                if (priceRange.min && total < parseFloat(priceRange.min)) return false;
                if (priceRange.max && total > parseFloat(priceRange.max)) return false;
                return true;
            });
        }

        // Ordenamiento
        filtered.sort((a, b) => {
            let aVal, bVal;
            switch (sortBy) {
                case 'name':
                    aVal = (a.project || '').toLowerCase();
                    bVal = (b.project || '').toLowerCase();
                    break;
                case 'total':
                    aVal = a.total || 0;
                    bVal = b.total || 0;
                    break;
                case 'items':
                    aVal = a.items?.length || 0;
                    bVal = b.items?.length || 0;
                    break;
                case 'date':
                default:
                    aVal = new Date(a.lastModified || 0).getTime();
                    bVal = new Date(b.lastModified || 0).getTime();
                    break;
            }

            if (sortOrder === 'asc') {
                return aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
            } else {
                return aVal < bVal ? 1 : aVal > bVal ? -1 : 0;
            }
        });

        return filtered;
    }, [projects, searchTerm, filterType, dateRange, priceRange, sortBy, sortOrder]);

    // Obtener tipos únicos para el filtro
    const projectTypes = useMemo(() => {
        const types = new Set(projects.map(p => p.type).filter(Boolean));
        return ['all', ...Array.from(types)];
    }, [projects]);

    const handleSort = (field) => {
        if (sortBy === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setSortOrder('desc');
        }
    };

    const clearFilters = () => {
        setSearchTerm('');
        setFilterType('all');
        setDateRange({ start: '', end: '' });
        setPriceRange({ min: '', max: '' });
    };

    const hasActiveFilters = searchTerm || filterType !== 'all' || dateRange.start || dateRange.end || priceRange.min || priceRange.max;

    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-50">Historial de Proyectos</h2>
                <button 
                    onClick={loadProjects} 
                    className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                >
                    Actualizar
                </button>
            </div>

            {/* Búsqueda y Filtros */}
            <Card className="p-4">
                <div className="space-y-4">
                    {/* Barra de búsqueda */}
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar por nombre, cliente o tipo..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                        />
                    </div>

                    {/* Botón de filtros */}
                    <div className="flex items-center justify-between">
                        <button
                            onClick={() => setShowFilters(!showFilters)}
                            className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition"
                        >
                            <Filter size={18} />
                            Filtros Avanzados
                            {hasActiveFilters && (
                                <span className="bg-blue-500 text-white text-xs px-2 py-0.5 rounded-full">
                                    {[searchTerm && 1, filterType !== 'all' && 1, dateRange.start && 1, dateRange.end && 1, priceRange.min && 1, priceRange.max && 1].filter(Boolean).length}
                                </span>
                            )}
                        </button>
                        {hasActiveFilters && (
                            <button
                                onClick={clearFilters}
                                className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200"
                            >
                                <X size={16} />
                                Limpiar filtros
                            </button>
                        )}
                    </div>

                    {/* Panel de filtros expandible */}
                    {showFilters && (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pt-4 border-t border-slate-200 dark:border-slate-700">
                            {/* Filtro por tipo */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    Tipo de Proyecto
                                </label>
                                <select
                                    value={filterType}
                                    onChange={(e) => setFilterType(e.target.value)}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                >
                                    {projectTypes.map(type => (
                                        <option key={type} value={type}>
                                            {type === 'all' ? 'Todos los tipos' : type}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Rango de fechas - Inicio */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Desde
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.start}
                                    onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de fechas - Fin */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Hasta
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.end}
                                    onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de precios */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <DollarSign size={14} className="inline mr-1" />
                                    Rango de Precio
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="number"
                                        placeholder="Mín"
                                        value={priceRange.min}
                                        onChange={(e) => setPriceRange({ ...priceRange, min: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                    <input
                                        type="number"
                                        placeholder="Máx"
                                        value={priceRange.max}
                                        onChange={(e) => setPriceRange({ ...priceRange, max: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Ordenamiento */}
                    <div className="flex items-center gap-4 pt-2 border-t border-slate-200 dark:border-slate-700">
                        <span className="text-sm text-slate-600 dark:text-slate-400">Ordenar por:</span>
                        <div className="flex gap-2">
                            {[
                                { key: 'date', label: 'Fecha' },
                                { key: 'name', label: 'Nombre' },
                                { key: 'total', label: 'Total' },
                                { key: 'items', label: 'Partidas' }
                            ].map(option => (
                                <button
                                    key={option.key}
                                    onClick={() => handleSort(option.key)}
                                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm transition ${
                                        sortBy === option.key
                                            ? 'bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 font-medium'
                                            : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                                    }`}
                                >
                                    {option.label}
                                    {sortBy === option.key && (
                                        sortOrder === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </Card>

            {/* Contador de resultados */}
            {!loading && projects.length > 0 && (
                <div className="text-sm text-slate-600 dark:text-slate-400">
                    Mostrando {filteredAndSortedProjects.length} de {projects.length} proyectos
                    {hasActiveFilters && ' (filtrados)'}
                </div>
            )}

            {loading ? (
                <div className="text-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                </div>
            ) : projects.length === 0 ? (
                <Card className="text-center py-20">
                    <HistoryIcon size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400">No hay proyectos guardados aún.</p>
                </Card>
            ) : filteredAndSortedProjects.length === 0 ? (
                <Card className="text-center py-20">
                    <Search size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400 mb-2">No se encontraron proyectos con los filtros seleccionados.</p>
                    <button
                        onClick={clearFilters}
                        className="text-blue-600 dark:text-blue-400 hover:underline"
                    >
                        Limpiar filtros
                    </button>
                </Card>
            ) : (
                <div className="grid gap-4">
                    {filteredAndSortedProjects.map(b => (
                        <Card key={b.id} className="p-6 hover:shadow-md transition">
                            <div className="flex justify-between items-center">
                                <div className="flex-1">
                                    <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100 mb-1">{b.project}</h3>
                                    <p className="text-sm text-slate-600 dark:text-slate-400 mb-2">
                                        Cliente: {b.client || 'Sin cliente'} • {b.lastModified ? new Date(b.lastModified).toLocaleDateString('es-MX', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        }) : 'Fecha desconocida'}
                                    </p>
                                    <div className="flex gap-2 flex-wrap">
                                        <span className="text-xs bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 px-2 py-1 rounded font-medium">{b.type || 'General'}</span>
                                        <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 px-2 py-1 rounded">{b.items?.length || 0} partidas</span>
                                    </div>
                                </div>
                                <div className="text-right ml-4">
                                    <p className="font-bold text-xl text-blue-600 dark:text-blue-400 font-mono mb-3">{formatCurrency(b.total || 0)}</p>
                                    <div className="flex gap-2 justify-end">
                                        <button 
                                            onClick={() => loadBudget(b)} 
                                            className="px-4 py-2 text-sm bg-blue-600 dark:bg-blue-500 hover:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold rounded-lg transition"
                                        >
                                            Abrir
                                        </button>
                                        <button
                                            onClick={() => handleDelete(b.id, b.project)}
                                            className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                            title="Eliminar proyecto"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

export default History;

import React, { createContext, useState, useEffect, useContext, useRef } from 'react';
// Context for managing project state
import { supabase } from '../lib/supabaseClient';
import { useAuth } from './AuthContext';
import { generateId } from '../utils/helpers';
import { CalculationsService } from '../services/CalculationsService';

const ProjectContext = createContext();

export const useProject = () => useContext(ProjectContext);

export const ProjectProvider = ({ children }) => {
    const { user, loading: authLoading } = useAuth();
    const [toast, setToast] = useState(null);
    const lastLoadedUserIdRef = useRef(null);

    // --- ESTADOS DEL PROYECTO ---
    const [projectInfo, setProjectInfo] = useState({
        id: generateId(),
        client: '',
        project: 'Presupuesto Nuevo',
        date: new Date().toISOString().split('T')[0],
        currency: 'MXN',
        taxRate: 16,
        type: 'General',
        indirect_percentage: 0,
        profit_percentage: 0,
        location: 'México'
    });

    const [items, setItems] = useState([]);
    const [savedBudgets, setSavedBudgets] = useState([]);
    const [catalog, setCatalog] = useState([]);
    const [loading, setLoading] = useState(false);

    // --- RATE LIMIT MODAL STATE ---
    const [rateLimitModal, setRateLimitModal] = useState({
        isOpen: false,
        message: '',
        retryAfter: 0
    });

    // --- FUNCIONES CORE ---
    const showToast = React.useCallback((msg, type = 'info', error = null) => {
        setToast({ message: msg, type, error });
    }, []);

    const showRateLimitModal = React.useCallback((message, retryAfter) => {
        setRateLimitModal({
            isOpen: true,
            message: message || 'Has excedido el límite de solicitudes.',
            retryAfter: retryAfter || 0
        });
    }, []);

    const closeRateLimitModal = React.useCallback(() => {
        setRateLimitModal(prev => ({ ...prev, isOpen: false }));
    }, []);

    // --- FUNCIONES DE CARGA ---
    const loadUserData = async () => {
        if (!user) return;

        setLoading(true);
        try {
            // Cargar proyectos guardados
            const { data: projects, error: projectsError } = await supabase
                .from('projects')
                .select('*')
                .eq('user_id', user.id)
                .order('updated_at', { ascending: false });

            if (projectsError) throw projectsError;

            // Cargar items de cada proyecto
            const projectsWithItems = await Promise.all(
                projects.map(async (project) => {
                    const { data: items } = await supabase
                        .from('budget_items')
                        .select('*')
                        .eq('project_id', project.id)
                        .order('order_index', { ascending: true });

                    return { ...project, items: items || [] };
                })
            );

            setSavedBudgets(projectsWithItems);

            // Cargar catálogo
            const { data: catalogData, error: catalogError } = await supabase
                .from('catalog_items')
                .select('*')
                .or(`user_id.eq.${user.id},is_public.eq.true`)
                .order('created_at', { ascending: false });

            if (catalogError) throw catalogError;

            // Si el catálogo está vacío, sembrar datos de ejemplo
            if (!catalogData || catalogData.length === 0) {
                const defaultItems = [
                    { description: 'Trazo y nivelación de terreno con equipo topográfico', unit: 'm2', unit_price: 15.50, category: 'Mano de Obra', user_id: user.id, is_public: false },
                    { description: 'Excavación a mano en cepas de cimentación material tipo II', unit: 'm3', unit_price: 280.00, category: 'Obra Civil', user_id: user.id, is_public: false },
                    { description: 'Salida eléctrica de centro para alumbrado con cable THW-LS calibre 12', unit: 'sal', unit_price: 650.00, category: 'Instalaciones', user_id: user.id, is_public: false },
                    { description: 'Muro de block hueco 15x20x40 cm asentado con mortero cemento-arena 1:4', unit: 'm2', unit_price: 420.00, category: 'Obra Civil', user_id: user.id, is_public: false },
                    { description: 'Pintura vinílica en muros a dos manos marca Comex', unit: 'm2', unit_price: 65.00, category: 'Materiales', user_id: user.id, is_public: false },
                ];

                const { data: seededData, error: seedError } = await supabase
                    .from('catalog_items')
                    .insert(defaultItems)
                    .select();

                if (!seedError && seededData) {
                    setCatalog(seededData.map(item => ({
                        id: item.id,
                        description: item.description,
                        unit: item.unit,
                        unitPrice: item.unit_price,
                        category: item.category
                    })));
                    showToast('Catálogo inicial cargado', 'success');
                } else {
                    setCatalog([]);
                }
            } else {
                setCatalog(catalogData.map(item => ({
                    id: item.id,
                    description: item.description,
                    unit: item.unit,
                    unitPrice: item.unit_price,
                    category: item.category
                })));
            }

        } catch (error) {
            console.error('Error loading user data:', error);
            // Mensaje amigable para errores de red (ERR_CONNECTION_CLOSED, Failed to fetch)
            const isNetworkError = !error.message || /fetch|network|connection|closed/i.test(error?.message || '');
            showToast(
                isNetworkError
                    ? 'Error de conexión. Revisa tu internet y que Supabase esté accesible.'
                    : 'Error al cargar datos',
                'error'
            );
        } finally {
            setLoading(false);
        }
    };

    const loadFromLocalStorage = () => {
        const saved = localStorage.getItem('presugenius_budgets');
        if (saved) {
            try {
                setSavedBudgets(JSON.parse(saved));
            } catch (e) {
                console.error('Error parsing localStorage:', e);
            }
        }

        // Cargar catálogo del localStorage o usar default
        const savedCatalog = localStorage.getItem('presugenius_catalog');
        if (savedCatalog) {
            try {
                setCatalog(JSON.parse(savedCatalog));
            } catch (e) {
                console.error('Error parsing catalog from localStorage:', e);
                setDefaultCatalog();
            }
        } else {
            setDefaultCatalog();
        }
    };

    const setDefaultCatalog = () => {
        setCatalog([
            { id: 'c1', description: 'Trazo y nivelación de terreno con equipo topográfico', unit: 'm2', unitPrice: 15.50, category: 'Mano de Obra' },
            { id: 'c2', description: 'Excavación a mano en cepas de cimentación material tipo II', unit: 'm3', unitPrice: 280.00, category: 'Obra Civil' },
            { id: 'c3', description: 'Salida eléctrica de centro para alumbrado con cable THW-LS calibre 12', unit: 'sal', unitPrice: 650.00, category: 'Instalaciones' },
            { id: 'c4', description: 'Muro de block hueco 15x20x40 cm asentado con mortero cemento-arena 1:4', unit: 'm2', unitPrice: 420.00, category: 'Obra Civil' },
            { id: 'c5', description: 'Pintura vinílica en muros a dos manos marca Comex', unit: 'm2', unitPrice: 65.00, category: 'Materiales' },
        ]);
    };

    // --- GESTIÓN DEL CATÁLOGO ---
    const addToCatalog = async (item) => {
        setLoading(true);
        try {
            const newItem = { ...item, id: generateId() };

            if (user) {
                // Guardar en Supabase
                const { data, error } = await supabase
                    .from('catalog_items')
                    .insert([{
                        user_id: user.id,
                        description: newItem.description,
                        unit: newItem.unit,
                        unit_price: newItem.unitPrice,
                        category: newItem.category,
                        is_public: false
                    }])
                    .select()
                    .single();

                if (error) throw error;

                // Actualizar estado local con el item devuelto (que tendrá el ID real de DB)
                const addedItem = {
                    id: data.id,
                    description: data.description,
                    unit: data.unit,
                    unitPrice: data.unit_price,
                    category: data.category
                };
                setCatalog([addedItem, ...catalog]);
            } else {
                // Guardar en LocalStorage
                const newCatalog = [newItem, ...catalog];
                setCatalog(newCatalog);
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }
            showToast('Concepto agregado al catálogo', 'success');
            return true;
        } catch (error) {
            console.error('Error adding to catalog:', error);
            showToast('Error al agregar al catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    const deleteFromCatalog = async (id) => {
        if (!window.confirm('¿Estás seguro de eliminar este concepto del catálogo?')) return;

        setLoading(true);
        try {
            if (user) {
                const { error } = await supabase
                    .from('catalog_items')
                    .delete()
                    .eq('id', id);

                if (error) throw error;
            }

            // Actualizar estado local (para ambos casos)
            const newCatalog = catalog.filter(item => item.id !== id);
            setCatalog(newCatalog);

            if (!user) {
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }

            showToast('Concepto eliminado del catálogo');
        } catch (error) {
            console.error('Error deleting from catalog:', error);
            showToast('Error al eliminar del catálogo', 'error');
        } finally {
            setLoading(false);
        }
    };

    const updateCatalogBulk = async (updatedItems) => {
        setLoading(true);
        try {
            if (user) {
                // Upsert to Supabase
                const itemsToUpsert = updatedItems.map(item => ({
                    id: item.id,
                    user_id: user.id,
                    description: item.description,
                    unit: item.unit,
                    unit_price: item.unitPrice,
                    category: item.category,
                    is_public: false,
                    updated_at: new Date().toISOString()
                }));

                const { error } = await supabase
                    .from('catalog_items')
                    .upsert(itemsToUpsert);

                if (error) throw error;
            } else {
                // Save to LocalStorage
                localStorage.setItem('presugenius_catalog', JSON.stringify(updatedItems));
            }

            setCatalog(updatedItems);
            showToast('Catálogo actualizado correctamente', 'success');
            return true;
        } catch (error) {
            console.error('Error updating catalog bulk:', error.message || error);
            if (error.details) console.error('Error details:', error.details);
            showToast('Error al actualizar el catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR DATOS AL INICIAR ---
    // Evitar bucle: solo ejecutar carga una vez por user.id; si falla la red no reintentar en cada render
    useEffect(() => {
        if (authLoading) return;

        if (!user) {
            lastLoadedUserIdRef.current = null;
            loadFromLocalStorage();
            return;
        }

        if (lastLoadedUserIdRef.current === user.id) return;
        lastLoadedUserIdRef.current = user.id;
        loadUserData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user?.id, authLoading]);

    // --- Auto-timeout para toasts ---
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    const calculateSubtotal = () => CalculationsService.calculateSubtotal(items);

    const calculateTotal = () => {
        const calc = CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
        return calc.total;
    };

    const getCalculations = () => {
        return CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
    };

    // --- GUARDAR PROYECTO ---
    const saveBudget = async () => {
        setLoading(true);

        try {
            if (user) {
                // Guardar en Supabase
                const projectData = {
                    user_id: user.id,
                    name: projectInfo.project,
                    client: projectInfo.client,
                    type: projectInfo.type,
                    currency: projectInfo.currency,
                    tax_rate: projectInfo.taxRate,
                    indirect_percentage: projectInfo.indirect_percentage || 0,
                    profit_percentage: projectInfo.profit_percentage || 0,
                    updated_at: new Date().toISOString()
                };

                let projectId = projectInfo.id;

                // Verificar si el proyecto ya existe
                const { data: existingProject } = await supabase
                    .from('projects')
                    .select('id')
                    .eq('id', projectInfo.id)
                    .single();

                if (existingProject) {
                    // Actualizar proyecto existente
                    await supabase
                        .from('projects')
                        .update(projectData)
                        .eq('id', projectInfo.id);
                } else {
                    // Crear nuevo proyecto
                    const { data: newProject, error: projectError } = await supabase
                        .from('projects')
                        .insert([{ ...projectData, id: projectInfo.id }])
                        .select()
                        .single();

                    if (projectError) throw projectError;
                    projectId = newProject.id;
                }

                // Eliminar items antiguos
                await supabase
                    .from('budget_items')
                    .delete()
                    .eq('project_id', projectId);

                // Insertar items nuevos
                if (items.length > 0) {
                    const itemsData = items.map((item, index) => ({
                        project_id: projectId,
                        description: item.description,
                        unit: item.unit,
                        quantity: item.quantity,
                        unit_price: item.unitPrice,
                        category: item.category,
                        subcategory: item.subcategory || null,
                        tags: item.tags || [],
                        notes: item.notes || '',
                        is_catalog_item: item.isCatalogItem || false,
                        order_index: index
                    }));

                    await supabase
                        .from('budget_items')
                        .insert(itemsData);
                }

                // Recargar proyectos
                await loadUserData();
                showToast('Proyecto guardado en la nube', 'success');

            } else {
                // Guardar en localStorage (modo offline)
                const budgetData = {
                    ...projectInfo,
                    items,
                    lastModified: new Date().toISOString(),
                    total: calculateTotal()
                };

                const existingIndex = savedBudgets.findIndex(b => b.id === projectInfo.id);
                let newSaved;

                if (existingIndex >= 0) {
                    newSaved = [...savedBudgets];
                    newSaved[existingIndex] = budgetData;
                } else {
                    newSaved = [...savedBudgets, budgetData];
                }

                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto guardado localmente', 'success');
            }
        } catch (error) {
            console.error('Error saving budget:', error);
            showToast('Error al guardar proyecto', 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR PROYECTO ---
    const loadBudget = (budget) => {
        setProjectInfo({
            id: budget.id,
            client: budget.client,
            project: budget.name || budget.project,
            date: budget.date || new Date().toISOString().split('T')[0],
            currency: budget.currency,
            taxRate: budget.tax_rate || budget.taxRate,
            type: budget.type,
            indirect_percentage: budget.indirect_percentage || 0,
            profit_percentage: budget.profit_percentage || 0
        });
        setItems(budget.items || []);
        showToast(`Proyecto "${budget.name || budget.project}" cargado`);
    };

    // --- ELIMINAR PROYECTO ---
    const deleteBudget = async (id) => {
        setLoading(true);

        try {
            if (user) {
                // Eliminar de Supabase
                await supabase
                    .from('projects')
                    .delete()
                    .eq('id', id);

                await loadUserData();
                showToast('Proyecto eliminado de la nube', 'success');
            } else {
                // Eliminar de localStorage
                const newSaved = savedBudgets.filter(b => b.id !== id);
                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto eliminado');
            }
        } catch (error) {
            const errorMessage = error.message || 'Error al eliminar proyecto';
            console.error('Error deleting budget:', error);
            showToast(errorMessage, 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- NUEVO PROYECTO ---
    const newProject = () => {
        setProjectInfo({
            id: generateId(),
            client: '',
            project: 'Presupuesto Nuevo',
            date: new Date().toISOString().split('T')[0],
            currency: 'MXN',
            taxRate: 16,
            type: 'General',
            indirect_percentage: 0,
            profit_percentage: 0
        });
        setItems([]);
        showToast('Nuevo proyecto creado');
    };

    const value = React.useMemo(() => ({
        projectInfo, setProjectInfo,
        items, setItems,
        savedBudgets, setSavedBudgets,
        catalog, setCatalog,
        toast, showToast, setToast,
        calculateSubtotal, calculateTotal, getCalculations,
        saveBudget, loadBudget, deleteBudget, newProject,
        addToCatalog, deleteFromCatalog, updateCatalogBulk,
        loading,
        rateLimitModal, showRateLimitModal, closeRateLimitModal
    }), [
        projectInfo, items, savedBudgets, catalog, toast, loading, rateLimitModal,
        showToast, showRateLimitModal, closeRateLimitModal
    ]);

    return <ProjectContext.Provider value={value}>{children}</ProjectContext.Provider>;
};

import React, { useState, useEffect, useMemo } from 'react';
import { History as HistoryIcon, Trash2, Search, Filter, X, Calendar, DollarSign, ChevronUp, ChevronDown } from 'lucide-react';
import { useProject } from '../context/ProjectContext';
import { formatCurrency } from '../utils/format';
import Card from '../components/ui/Card';

const History = () => {
    const { loadBudget, deleteBudget: contextDeleteBudget } = useProject();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState('date'); // 'date', 'name', 'total', 'items'
    const [sortOrder, setSortOrder] = useState('desc'); // 'asc', 'desc'
    const [filterType, setFilterType] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [dateRange, setDateRange] = useState({ start: '', end: '' });
    const [priceRange, setPriceRange] = useState({ min: '', max: '' });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            // Import dynamically to avoid circular dependencies if any, or just use the imported service
            const { default: ProjectPersistenceService } = await import('../services/ProjectPersistenceService');
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading history:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id, name) => {
        if (window.confirm(`¿Eliminar el proyecto "${name}"?`)) {
            await contextDeleteBudget(id);
            // Reload list to ensure sync
            loadProjects();
        }
    };

    // Filtrar y ordenar proyectos
    const filteredAndSortedProjects = useMemo(() => {
        let filtered = [...projects];

        // Búsqueda por texto
        if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            filtered = filtered.filter(p => 
                p.project?.toLowerCase().includes(searchLower) ||
                p.client?.toLowerCase().includes(searchLower) ||
                p.type?.toLowerCase().includes(searchLower)
            );
        }

        // Filtro por tipo
        if (filterType !== 'all') {
            filtered = filtered.filter(p => p.type === filterType);
        }

        // Filtro por rango de fechas
        if (dateRange.start || dateRange.end) {
            filtered = filtered.filter(p => {
                if (!p.lastModified) return false;
                const projectDate = new Date(p.lastModified);
                if (dateRange.start && projectDate < new Date(dateRange.start)) return false;
                if (dateRange.end && projectDate > new Date(dateRange.end + 'T23:59:59')) return false;
                return true;
            });
        }

        // Filtro por rango de precios
        if (priceRange.min || priceRange.max) {
            filtered = filtered.filter(p => {
                const total = p.total || 0;
                if (priceRange.min && total < parseFloat(priceRange.min)) return false;
                if (priceRange.max && total > parseFloat(priceRange.max)) return false;
                return true;
            });
        }

        // Ordenamiento
        filtered.sort((a, b) => {
            let aVal, bVal;
            switch (sortBy) {
                case 'name':
                    aVal = (a.project || '').toLowerCase();
                    bVal = (b.project || '').toLowerCase();
                    break;
                case 'total':
                    aVal = a.total || 0;
                    bVal = b.total || 0;
                    break;
                case 'items':
                    aVal = a.items?.length || 0;
                    bVal = b.items?.length || 0;
                    break;
                case 'date':
                default:
                    aVal = new Date(a.lastModified || 0).getTime();
                    bVal = new Date(b.lastModified || 0).getTime();
                    break;
            }

            if (sortOrder === 'asc') {
                return aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
            } else {
                return aVal < bVal ? 1 : aVal > bVal ? -1 : 0;
            }
        });

        return filtered;
    }, [projects, searchTerm, filterType, dateRange, priceRange, sortBy, sortOrder]);

    // Obtener tipos únicos para el filtro
    const projectTypes = useMemo(() => {
        const types = new Set(projects.map(p => p.type).filter(Boolean));
        return ['all', ...Array.from(types)];
    }, [projects]);

    const handleSort = (field) => {
        if (sortBy === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setSortOrder('desc');
        }
    };

    const clearFilters = () => {
        setSearchTerm('');
        setFilterType('all');
        setDateRange({ start: '', end: '' });
        setPriceRange({ min: '', max: '' });
    };

    const hasActiveFilters = searchTerm || filterType !== 'all' || dateRange.start || dateRange.end || priceRange.min || priceRange.max;

    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-50">Historial de Proyectos</h2>
                <button 
                    onClick={loadProjects} 
                    className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                >
                    Actualizar
                </button>
            </div>

            {/* Búsqueda y Filtros */}
            <Card className="p-4">
                <div className="space-y-4">
                    {/* Barra de búsqueda */}
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar por nombre, cliente o tipo..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                        />
                    </div>

                    {/* Botón de filtros */}
                    <div className="flex items-center justify-between">
                        <button
                            onClick={() => setShowFilters(!showFilters)}
                            className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-lg transition"
                        >
                            <Filter size={18} />
                            Filtros Avanzados
                            {hasActiveFilters && (
                                <span className="bg-blue-500 text-white text-xs px-2 py-0.5 rounded-full">
                                    {[searchTerm && 1, filterType !== 'all' && 1, dateRange.start && 1, dateRange.end && 1, priceRange.min && 1, priceRange.max && 1].filter(Boolean).length}
                                </span>
                            )}
                        </button>
                        {hasActiveFilters && (
                            <button
                                onClick={clearFilters}
                                className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200"
                            >
                                <X size={16} />
                                Limpiar filtros
                            </button>
                        )}
                    </div>

                    {/* Panel de filtros expandible */}
                    {showFilters && (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pt-4 border-t border-slate-200 dark:border-slate-700">
                            {/* Filtro por tipo */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    Tipo de Proyecto
                                </label>
                                <select
                                    value={filterType}
                                    onChange={(e) => setFilterType(e.target.value)}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                >
                                    {projectTypes.map(type => (
                                        <option key={type} value={type}>
                                            {type === 'all' ? 'Todos los tipos' : type}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            {/* Rango de fechas - Inicio */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Desde
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.start}
                                    onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de fechas - Fin */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <Calendar size={14} className="inline mr-1" />
                                    Fecha Hasta
                                </label>
                                <input
                                    type="date"
                                    value={dateRange.end}
                                    onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                                    className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                />
                            </div>

                            {/* Rango de precios */}
                            <div>
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                                    <DollarSign size={14} className="inline mr-1" />
                                    Rango de Precio
                                </label>
                                <div className="flex gap-2">
                                    <input
                                        type="number"
                                        placeholder="Mín"
                                        value={priceRange.min}
                                        onChange={(e) => setPriceRange({ ...priceRange, min: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                    <input
                                        type="number"
                                        placeholder="Máx"
                                        value={priceRange.max}
                                        onChange={(e) => setPriceRange({ ...priceRange, max: e.target.value })}
                                        className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100"
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Ordenamiento */}
                    <div className="flex items-center gap-4 pt-2 border-t border-slate-200 dark:border-slate-700">
                        <span className="text-sm text-slate-600 dark:text-slate-400">Ordenar por:</span>
                        <div className="flex gap-2">
                            {[
                                { key: 'date', label: 'Fecha' },
                                { key: 'name', label: 'Nombre' },
                                { key: 'total', label: 'Total' },
                                { key: 'items', label: 'Partidas' }
                            ].map(option => (
                                <button
                                    key={option.key}
                                    onClick={() => handleSort(option.key)}
                                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm transition ${
                                        sortBy === option.key
                                            ? 'bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 font-medium'
                                            : 'bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'
                                    }`}
                                >
                                    {option.label}
                                    {sortBy === option.key && (
                                        sortOrder === 'asc' ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </Card>

            {/* Contador de resultados */}
            {!loading && projects.length > 0 && (
                <div className="text-sm text-slate-600 dark:text-slate-400">
                    Mostrando {filteredAndSortedProjects.length} de {projects.length} proyectos
                    {hasActiveFilters && ' (filtrados)'}
                </div>
            )}

            {loading ? (
                <div className="text-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                </div>
            ) : projects.length === 0 ? (
                <Card className="text-center py-20">
                    <HistoryIcon size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400">No hay proyectos guardados aún.</p>
                </Card>
            ) : filteredAndSortedProjects.length === 0 ? (
                <Card className="text-center py-20">
                    <Search size={48} className="mx-auto mb-4 text-slate-300 dark:text-slate-600 opacity-50" />
                    <p className="text-slate-500 dark:text-slate-400 mb-2">No se encontraron proyectos con los filtros seleccionados.</p>
                    <button
                        onClick={clearFilters}
                        className="text-blue-600 dark:text-blue-400 hover:underline"
                    >
                        Limpiar filtros
                    </button>
                </Card>
            ) : (
                <div className="grid gap-4">
                    {filteredAndSortedProjects.map(b => (
                        <Card key={b.id} className="p-6 hover:shadow-md transition">
                            <div className="flex justify-between items-center">
                                <div className="flex-1">
                                    <h3 className="font-bold text-lg text-slate-800 dark:text-slate-100 mb-1">{b.project}</h3>
                                    <p className="text-sm text-slate-600 dark:text-slate-400 mb-2">
                                        Cliente: {b.client || 'Sin cliente'} • {b.lastModified ? new Date(b.lastModified).toLocaleDateString('es-MX', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        }) : 'Fecha desconocida'}
                                    </p>
                                    <div className="flex gap-2 flex-wrap">
                                        <span className="text-xs bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 px-2 py-1 rounded font-medium">{b.type || 'General'}</span>
                                        <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300 px-2 py-1 rounded">{b.items?.length || 0} partidas</span>
                                    </div>
                                </div>
                                <div className="text-right ml-4">
                                    <p className="font-bold text-xl text-blue-600 dark:text-blue-400 font-mono mb-3">{formatCurrency(b.total || 0)}</p>
                                    <div className="flex gap-2 justify-end">
                                        <button 
                                            onClick={() => loadBudget(b)} 
                                            className="px-4 py-2 text-sm bg-blue-600 dark:bg-blue-500 hover:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold rounded-lg transition"
                                        >
                                            Abrir
                                        </button>
                                        <button
                                            onClick={() => handleDelete(b.id, b.project)}
                                            className="p-2 text-slate-400 dark:text-slate-500 hover:text-red-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                            title="Eliminar proyecto"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

