import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Hammer, Mail, Lock, User, AlertCircle, Loader, CheckCircle, Sparkles } from 'lucide-react';

const Login = () => {
    const navigate = useNavigate();
    const { signIn, signUp } = useAuth();

    const [isSignUp, setIsSignUp] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [rememberMe, setRememberMe] = useState(false);
    const [loginSuccess, setLoginSuccess] = useState(false);
    const [particles, setParticles] = useState([]);

    const [formData, setFormData] = useState({
        email: '',
        password: '',
        confirmPassword: '',
        fullName: ''
    });

    // Generate confetti particles
    const generateParticles = () => {
        const colors = ['#3b82f6', '#8b5cf6', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#ec4899'];
        const newParticles = [];
        for (let i = 0; i < 50; i++) {
            newParticles.push({
                id: i,
                x: Math.random() * 100,
                y: Math.random() * 100,
                size: Math.random() * 8 + 4,
                color: colors[Math.floor(Math.random() * colors.length)],
                delay: Math.random() * 0.5,
                duration: Math.random() * 1 + 1.5,
                rotation: Math.random() * 360
            });
        }
        setParticles(newParticles);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (isSignUp) {
                if (formData.password !== formData.confirmPassword) {
                    setError('Las contraseñas no coinciden');
                    setLoading(false);
                    return;
                }

                if (formData.password.length < 6) {
                    setError('La contraseña debe tener al menos 6 caracteres');
                    setLoading(false);
                    return;
                }

                const { error: signUpError } = await signUp(
                    formData.email,
                    formData.password,
                    { full_name: formData.fullName }
                );

                if (signUpError) throw signUpError;

                setError('');
                alert('Cuenta creada! Por favor revisa tu email para confirmar tu cuenta.');
                setIsSignUp(false);
            } else {
                const { error: signInError } = await signIn(formData.email, formData.password);

                if (signInError) throw signInError;

                // Show success animation
                setLoginSuccess(true);
                generateParticles();
                
                // Navigate after animation
                setTimeout(() => {
                    navigate('/dashboard');
                }, 2000);
            }
        } catch (err) {
            console.error('Auth error:', err);

            if (err.message?.includes('Failed to fetch') || err.message?.includes('ERR_NAME_NOT_RESOLVED')) {
                setError('⚠️ No se puede conectar con Supabase. Usa el modo local para continuar.');
            } else {
                setError(err.message || 'Error de autenticación');
            }
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-950 to-slate-900 flex items-center justify-center p-4 overflow-hidden relative">
