            </div>

            {/* Main Card Container */}
            <div className="relative z-10 w-full max-w-5xl bg-slate-800/50 backdrop-blur-sm rounded-3xl shadow-2xl overflow-hidden flex flex-col lg:flex-row min-h-[600px] border border-slate-700/50">
                
