            {
                name: 'Moderno Oscuro',
                headerColor: [30, 41, 59], // Slate 800
                headerTextColor: [255, 255, 255],
                headerTextSize: 20,
                headerSubtextSize: 10,
                headerText: 'PRESUPUESTO',
                headerSubtext: 'PROYECTO EJECUTIVO',
                showHeader: true,
                isActive: false
