            {/* PDF Preview Modal */}
            {showPDFPreview && previewTemplate && (() => {
                const exampleProjectInfo = {
                    project: 'Ejemplo de Proyecto',
                    client: 'Cliente de Ejemplo',
                    location: 'Ciudad de México',
                    taxRate: 16,
