                                    value={reportDate}
                                    onChange={(e) => setReportDate(e.target.value)}
                                    className="w-full text-xs md:text-sm font-medium text-slate-800 border-b-2 border-slate-400 pb-1 focus:outline-none focus:border-indigo-600 bg-transparent"
