                    </button>
                    <button
                        onClick={onClose}
                        className="w-full py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-medium transition"
                    >
                        Cerrar
                    </button>
                </div>
            </div>
        </div>
    );
};

