import React, { useState } from 'react';
import { Search, MapPin, DollarSign, Building, Store, Loader2, Info } from 'lucide-react';
import { useProject } from '../context/ProjectContext';
import { useAuth } from '../context/AuthContext'; // Para obtener el userTier
import { FUNCTION_TYPE, USER_TIER } from '../services/ApiKeyManager'; // Para tipos de función y tiers

const PriceSearchPage = () => {
    const [material, setMaterial] = useState('');
    const [locations, setLocations] = useState('');
    const [prices, setPrices] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const { toast, setToast, showRateLimitModal } = useProject();
    const { user } = useAuth(); // Obtener el usuario para determinar el tier

    const handleSearch = async (e) => {
        e.preventDefault();
        if (!material.trim() || !locations.trim()) {
            setToast({ message: 'Por favor, ingresa un material y al menos una ubicación.', type: 'error' });
            return;
        }

        setLoading(true);
        setError(null);
        setPrices([]);

        try {
            const userTier = user?.isPro ? USER_TIER.PRO : USER_TIER.FREE;

            const response = await fetch('http://localhost:4001/api/ai/pricesearch', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    material,
                    locations,
                    userTier,
                    functionType: FUNCTION_TYPE.PRICE_SEARCH,
                }),
            });

            const data = await response.json();

            if (response.ok && data.success) {
                if (response.status === 429) {
                    const retryAfter = data.retryAfter || 60;
                    showRateLimitModal(data.error, retryAfter);
                    return;
                }

                if (data.data.length > 0) {
                    setPrices(data.data);
                    setToast({ message: 'Búsqueda de precios completada.', type: 'success' });
                } else {
                    setToast({ message: 'No se encontraron precios para los criterios especificados.', type: 'info' });
                }
            } else {
                if (response.status === 429) {
                    const retryAfter = data.retryAfter || 60;
                    showRateLimitModal(data.error, retryAfter);
                    return;
                }
                setError(data.error || 'Ocurrió un error al buscar precios.');
                setToast({ message: data.error || 'Error al buscar precios.', type: 'error' });
            }
        } catch (err) {
            console.error('Error fetching prices:', err);
            setError('No se pudo conectar con el servicio de búsqueda de precios.');
            setToast({ message: 'Error de conexión con la IA.', type: 'error' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto p-4 md:p-8">
            <h1 className="text-3xl font-bold text-slate-800 dark:text-slate-100 mb-6">Búsqueda de Precios con IA</h1>

            <div className="bg-white dark:bg-slate-800 rounded-lg shadow-md p-6 mb-8">
                <form onSubmit={handleSearch} className="space-y-4">
                    <div>
                        <label htmlFor="material" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Material a buscar:
                        </label>
                        <input
                            type="text"
                            id="material"
                            className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-md bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-slate-100 focus:ring-blue-500 focus:border-blue-500"
                            placeholder="Ej: Cemento gris, Varilla 3/8, Ladrillo rojo"
                            value={material}
                            onChange={(e) => setMaterial(e.target.value)}
                            required
                        />
                    </div>
                    <div>
                        <label htmlFor="locations" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Ubicaciones (separadas por comas):
                        </label>
                        <textarea
                            id="locations"
                            rows="3"
                            className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-md bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-slate-100 focus:ring-blue-500 focus:border-blue-500"
                            placeholder="Ej: México Ciudad de México, Nezahualcóyotl, Oaxaca San Juan Bautista Tuxtepec Oaxaca"
                            value={locations}
                            onChange={(e) => setLocations(e.target.value)}
                            required
                        ></textarea>
                        <p className="mt-2 text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1">
                            <Info size={14} />
                            La IA intentará buscar en empresas y tiendas dentro de estas regiones.
                        </p>
                    </div>
                    <button
                        type="submit"
                        className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white font-semibold rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-slate-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        disabled={loading}
                    >
                        {loading ? (
                            <>
                                <Loader2 className="animate-spin" size={20} />
                                Buscando precios...
                            </>
                        ) : (
                            <>
                                <Search size={20} />
                                Buscar Precios
                            </>
                        )}
                    </button>
                </form>
            </div>

            {error && (
                <div className="bg-red-100 dark:bg-red-900 border border-red-400 text-red-700 dark:text-red-200 px-4 py-3 rounded relative mb-8" role="alert">
                    <strong className="font-bold">Error:</strong>
                    <span className="block sm:inline"> {error}</span>
                </div>
            )}

            {prices.length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {prices.map((item, index) => (
                        <div key={index} className="bg-white dark:bg-slate-800 rounded-lg shadow-md p-6 border border-slate-200 dark:border-slate-700 hover:shadow-lg transition-shadow">
                            <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-100 mb-3 flex items-center gap-2">
                                <DollarSign size={20} className="text-green-500" />
                                {item.name}
                            </h3>
                            <p className="text-slate-700 dark:text-slate-300 mb-2 flex items-center gap-2">
                                <MapPin size={16} className="text-blue-500" />
                                <span className="font-medium">Ubicación:</span> {item.location}
                            </p>
                            <p className="text-slate-700 dark:text-slate-300 mb-2 flex items-center gap-2">
                                <Building size={16} className="text-purple-500" />
                                <span className="font-medium">Precio:</span> <span className="text-green-600 dark:text-green-400 font-bold">{item.price}</span>
                            </p>
                            <p className="text-slate-600 dark:text-slate-400 text-sm flex items-center gap-2">
                                <Store size={16} className="text-orange-500" />
                                <span className="font-medium">Fuente:</span> {item.source}
                            </p>
                        </div>
                    ))}
                </div>
            )}

            {!loading && prices.length === 0 && !error && (material.trim() || locations.trim()) && (
                <div className="bg-blue-100 dark:bg-blue-900 border border-blue-400 text-blue-700 dark:text-blue-200 px-4 py-3 rounded relative" role="alert">
                    <strong className="font-bold">Consejo:</strong>
                    <span className="block sm:inline"> Ingresa un material y una o varias ubicaciones para iniciar la búsqueda de precios.</span>
                </div>
            )}
        </div>
    );
};

export default PriceSearchPage;

import React, { createContext, useState, useEffect, useContext, useRef } from 'react';
// Context for managing project state
import { supabase } from '../lib/supabaseClient';
import { useAuth } from './AuthContext';
import { generateId } from '../utils/helpers';
import { CalculationsService } from '../services/CalculationsService';

const ProjectContext = createContext();

export const useProject = () => useContext(ProjectContext);

export const ProjectProvider = ({ children }) => {
    const { user, loading: authLoading } = useAuth();
    const [toast, setToast] = useState(null);
    const lastLoadedUserIdRef = useRef(null);

    // --- ESTADOS DEL PROYECTO ---
    const [projectInfo, setProjectInfo] = useState({
        id: generateId(),
        client: '',
        project: 'Presupuesto Nuevo',
        date: new Date().toISOString().split('T')[0],
        currency: 'MXN',
        taxRate: 16,
        type: 'General',
        indirect_percentage: 0,
        profit_percentage: 0,
        location: 'México'
    });

    const [items, setItems] = useState([]);
    const [savedBudgets, setSavedBudgets] = useState([]);
    const [catalog, setCatalog] = useState([]);
    const [loading, setLoading] = useState(false);

    // --- RATE LIMIT MODAL STATE ---
    const [rateLimitModal, setRateLimitModal] = useState({
        isOpen: false,
        message: '',
        retryAfter: 0
    });

    // --- FUNCIONES CORE ---
    const showToast = React.useCallback((msg, type = 'info', error = null) => {
        setToast({ message: msg, type, error });
    }, []);

    const showRateLimitModal = React.useCallback((message, retryAfter) => {
        setRateLimitModal({
            isOpen: true,
            message: message || 'Has excedido el límite de solicitudes.',
            retryAfter: retryAfter || 0
        });
    }, []);

    const closeRateLimitModal = React.useCallback(() => {
        setRateLimitModal(prev => ({ ...prev, isOpen: false }));
    }, []);

    // --- FUNCIONES DE CARGA ---
    const loadUserData = async () => {
        if (!user) return;

        setLoading(true);
        try {
            // Cargar proyectos guardados
            const { data: projects, error: projectsError } = await supabase
                .from('projects')
                .select('*')
                .eq('user_id', user.id)
                .order('updated_at', { ascending: false });

            if (projectsError) throw projectsError;

            // Cargar items de cada proyecto
            const projectsWithItems = await Promise.all(
                projects.map(async (project) => {
                    const { data: items } = await supabase
                        .from('budget_items')
                        .select('*')
                        .eq('project_id', project.id)
                        .order('order_index', { ascending: true });

                    return { ...project, items: items || [] };
                })
            );

            setSavedBudgets(projectsWithItems);

            // Cargar catálogo
            const { data: catalogData, error: catalogError } = await supabase
                .from('catalog_items')
                .select('*')
                .or(`user_id.eq.${user.id},is_public.eq.true`)
                .order('created_at', { ascending: false });

            if (catalogError) throw catalogError;

            // Si el catálogo está vacío, sembrar datos de ejemplo
            if (!catalogData || catalogData.length === 0) {
                const defaultItems = [
                    { description: 'Trazo y nivelación de terreno con equipo topográfico', unit: 'm2', unit_price: 15.50, category: 'Mano de Obra', user_id: user.id, is_public: false },
                    { description: 'Excavación a mano en cepas de cimentación material tipo II', unit: 'm3', unit_price: 280.00, category: 'Obra Civil', user_id: user.id, is_public: false },
                    { description: 'Salida eléctrica de centro para alumbrado con cable THW-LS calibre 12', unit: 'sal', unit_price: 650.00, category: 'Instalaciones', user_id: user.id, is_public: false },
                    { description: 'Muro de block hueco 15x20x40 cm asentado con mortero cemento-arena 1:4', unit: 'm2', unit_price: 420.00, category: 'Obra Civil', user_id: user.id, is_public: false },
                    { description: 'Pintura vinílica en muros a dos manos marca Comex', unit: 'm2', unit_price: 65.00, category: 'Materiales', user_id: user.id, is_public: false },
                ];

                const { data: seededData, error: seedError } = await supabase
                    .from('catalog_items')
                    .insert(defaultItems)
                    .select();

                if (!seedError && seededData) {
                    setCatalog(seededData.map(item => ({
                        id: item.id,
                        description: item.description,
                        unit: item.unit,
                        unitPrice: item.unit_price,
                        category: item.category
                    })));
                    showToast('Catálogo inicial cargado', 'success');
                } else {
                    setCatalog([]);
                }
            } else {
                setCatalog(catalogData.map(item => ({
                    id: item.id,
                    description: item.description,
                    unit: item.unit,
                    unitPrice: item.unit_price,
                    category: item.category
                })));
            }

        } catch (error) {
            console.error('Error loading user data:', error);
            // Mensaje amigable para errores de red (ERR_CONNECTION_CLOSED, Failed to fetch)
            const isNetworkError = !error.message || /fetch|network|connection|closed/i.test(error?.message || '');
            showToast(
                isNetworkError
                    ? 'Error de conexión. Revisa tu internet y que Supabase esté accesible.'
                    : 'Error al cargar datos',
                'error'
            );
        } finally {
            setLoading(false);
        }
    };

    const loadFromLocalStorage = () => {
        const saved = localStorage.getItem('presugenius_budgets');
        if (saved) {
            try {
                setSavedBudgets(JSON.parse(saved));
            } catch (e) {
                console.error('Error parsing localStorage:', e);
            }
        }

        // Cargar catálogo del localStorage o usar default
        const savedCatalog = localStorage.getItem('presugenius_catalog');
        if (savedCatalog) {
            try {
                setCatalog(JSON.parse(savedCatalog));
            } catch (e) {
                console.error('Error parsing catalog from localStorage:', e);
                setDefaultCatalog();
            }
        } else {
            setDefaultCatalog();
        }
    };

    const setDefaultCatalog = () => {
        setCatalog([
            { id: 'c1', description: 'Trazo y nivelación de terreno con equipo topográfico', unit: 'm2', unitPrice: 15.50, category: 'Mano de Obra' },
            { id: 'c2', description: 'Excavación a mano en cepas de cimentación material tipo II', unit: 'm3', unitPrice: 280.00, category: 'Obra Civil' },
            { id: 'c3', description: 'Salida eléctrica de centro para alumbrado con cable THW-LS calibre 12', unit: 'sal', unitPrice: 650.00, category: 'Instalaciones' },
            { id: 'c4', description: 'Muro de block hueco 15x20x40 cm asentado con mortero cemento-arena 1:4', unit: 'm2', unitPrice: 420.00, category: 'Obra Civil' },
            { id: 'c5', description: 'Pintura vinílica en muros a dos manos marca Comex', unit: 'm2', unitPrice: 65.00, category: 'Materiales' },
        ]);
    };

    // --- GESTIÓN DEL CATÁLOGO ---
    const addToCatalog = async (item) => {
        setLoading(true);
        try {
            const newItem = { ...item, id: generateId() };

            if (user) {
                // Guardar en Supabase
                const { data, error } = await supabase
                    .from('catalog_items')
                    .insert([{
                        user_id: user.id,
                        description: newItem.description,
                        unit: newItem.unit,
                        unit_price: newItem.unitPrice,
                        category: newItem.category,
                        is_public: false
                    }])
                    .select()
                    .single();

                if (error) throw error;

                // Actualizar estado local con el item devuelto (que tendrá el ID real de DB)
                const addedItem = {
                    id: data.id,
                    description: data.description,
                    unit: data.unit,
                    unitPrice: data.unit_price,
                    category: data.category
                };
                setCatalog([addedItem, ...catalog]);
            } else {
                // Guardar en LocalStorage
                const newCatalog = [newItem, ...catalog];
                setCatalog(newCatalog);
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }
            showToast('Concepto agregado al catálogo', 'success');
            return true;
        } catch (error) {
            console.error('Error adding to catalog:', error);
            showToast('Error al agregar al catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    const deleteFromCatalog = async (id) => {
        if (!window.confirm('¿Estás seguro de eliminar este concepto del catálogo?')) return;

        setLoading(true);
        try {
            if (user) {
                const { error } = await supabase
                    .from('catalog_items')
                    .delete()
                    .eq('id', id);

                if (error) throw error;
            }

            // Actualizar estado local (para ambos casos)
            const newCatalog = catalog.filter(item => item.id !== id);
            setCatalog(newCatalog);

            if (!user) {
                localStorage.setItem('presugenius_catalog', JSON.stringify(newCatalog));
            }

            showToast('Concepto eliminado del catálogo');
        } catch (error) {
            console.error('Error deleting from catalog:', error);
            showToast('Error al eliminar del catálogo', 'error');
        } finally {
            setLoading(false);
        }
    };

    const updateCatalogBulk = async (updatedItems) => {
        setLoading(true);
        try {
            if (user) {
                // Upsert to Supabase
                const itemsToUpsert = updatedItems.map(item => ({
                    id: item.id,
                    user_id: user.id,
                    description: item.description,
                    unit: item.unit,
                    unit_price: item.unitPrice,
                    category: item.category,
                    is_public: false,
                    updated_at: new Date().toISOString()
                }));

                const { error } = await supabase
                    .from('catalog_items')
                    .upsert(itemsToUpsert);

                if (error) throw error;
            } else {
                // Save to LocalStorage
                localStorage.setItem('presugenius_catalog', JSON.stringify(updatedItems));
            }

            setCatalog(updatedItems);
            showToast('Catálogo actualizado correctamente', 'success');
            return true;
        } catch (error) {
            console.error('Error updating catalog bulk:', error.message || error);
            if (error.details) console.error('Error details:', error.details);
            showToast('Error al actualizar el catálogo', 'error');
            return false;
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR DATOS AL INICIAR ---
    // Evitar bucle: solo ejecutar carga una vez por user.id; si falla la red no reintentar en cada render
    useEffect(() => {
        if (authLoading) return;

        if (!user) {
            lastLoadedUserIdRef.current = null;
            loadFromLocalStorage();
            return;
        }

        if (lastLoadedUserIdRef.current === user.id) return;
        lastLoadedUserIdRef.current = user.id;
        loadUserData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user?.id, authLoading]);

    // --- Auto-timeout para toasts ---
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    const calculateSubtotal = () => CalculationsService.calculateSubtotal(items);

    const calculateTotal = () => {
        const calc = CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
        return calc.total;
    };

    const getCalculations = () => {
        return CalculationsService.calculateTotal(items, {
            indirectPercentage: projectInfo.indirect_percentage ?? 0,
            profitPercentage: projectInfo.profit_percentage ?? 0,
            taxRate: projectInfo.taxRate ?? 0  // Respetar 0, solo usar default si es null/undefined
        });
    };

    // --- GUARDAR PROYECTO ---
    const saveBudget = async () => {
        setLoading(true);

        try {
            if (user) {
                // Guardar en Supabase
                const projectData = {
                    user_id: user.id,
                    name: projectInfo.project,
                    client: projectInfo.client,
                    type: projectInfo.type,
                    currency: projectInfo.currency,
                    tax_rate: projectInfo.taxRate,
                    indirect_percentage: projectInfo.indirect_percentage || 0,
                    profit_percentage: projectInfo.profit_percentage || 0,
                    updated_at: new Date().toISOString()
                };

                let projectId = projectInfo.id;

                // Verificar si el proyecto ya existe
                const { data: existingProject } = await supabase
                    .from('projects')
                    .select('id')
                    .eq('id', projectInfo.id)
                    .single();

                if (existingProject) {
                    // Actualizar proyecto existente
                    await supabase
                        .from('projects')
                        .update(projectData)
                        .eq('id', projectInfo.id);
                } else {
                    // Crear nuevo proyecto
                    const { data: newProject, error: projectError } = await supabase
                        .from('projects')
                        .insert([{ ...projectData, id: projectInfo.id }])
                        .select()
                        .single();

                    if (projectError) throw projectError;
                    projectId = newProject.id;
                }

                // Eliminar items antiguos
                await supabase
                    .from('budget_items')
                    .delete()
                    .eq('project_id', projectId);

                // Insertar items nuevos
                if (items.length > 0) {
                    const itemsData = items.map((item, index) => ({
                        project_id: projectId,
                        description: item.description,
                        unit: item.unit,
                        quantity: item.quantity,
                        unit_price: item.unitPrice,
                        category: item.category,
                        subcategory: item.subcategory || null,
                        tags: item.tags || [],
                        notes: item.notes || '',
                        is_catalog_item: item.isCatalogItem || false,
                        order_index: index
                    }));

                    await supabase
                        .from('budget_items')
                        .insert(itemsData);
                }

                // Recargar proyectos
                await loadUserData();
                showToast('Proyecto guardado en la nube', 'success');

            } else {
                // Guardar en localStorage (modo offline)
                const budgetData = {
                    ...projectInfo,
                    items,
                    lastModified: new Date().toISOString(),
                    total: calculateTotal()
                };

                const existingIndex = savedBudgets.findIndex(b => b.id === projectInfo.id);
                let newSaved;

                if (existingIndex >= 0) {
                    newSaved = [...savedBudgets];
                    newSaved[existingIndex] = budgetData;
                } else {
                    newSaved = [...savedBudgets, budgetData];
                }

                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto guardado localmente', 'success');
            }
        } catch (error) {
            console.error('Error saving budget:', error);
            showToast('Error al guardar proyecto', 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- CARGAR PROYECTO ---
    const loadBudget = (budget) => {
        setProjectInfo({
            id: budget.id,
            client: budget.client,
            project: budget.name || budget.project,
            date: budget.date || new Date().toISOString().split('T')[0],
            currency: budget.currency,
            taxRate: budget.tax_rate || budget.taxRate,
            type: budget.type,
            indirect_percentage: budget.indirect_percentage || 0,
            profit_percentage: budget.profit_percentage || 0
        });
        setItems(budget.items || []);
        showToast(`Proyecto "${budget.name || budget.project}" cargado`);
    };

    // --- ELIMINAR PROYECTO ---
    const deleteBudget = async (id) => {
        setLoading(true);

        try {
            if (user) {
                // Eliminar de Supabase
                await supabase
                    .from('projects')
                    .delete()
                    .eq('id', id);

                await loadUserData();
                showToast('Proyecto eliminado de la nube', 'success');
            } else {
                // Eliminar de localStorage
                const newSaved = savedBudgets.filter(b => b.id !== id);
                setSavedBudgets(newSaved);
                localStorage.setItem('presugenius_budgets', JSON.stringify(newSaved));
                showToast('Proyecto eliminado');
            }
        } catch (error) {
            const errorMessage = error.message || 'Error al eliminar proyecto';
            console.error('Error deleting budget:', error);
            showToast(errorMessage, 'error');
        } finally {
            setLoading(false);
        }
    };

    // --- NUEVO PROYECTO ---
    const newProject = () => {
        setProjectInfo({
            id: generateId(),
            client: '',
            project: 'Presupuesto Nuevo',
            date: new Date().toISOString().split('T')[0],
            currency: 'MXN',
            taxRate: 16,
            type: 'General',
            indirect_percentage: 0,
            profit_percentage: 0
        });
        setItems([]);
        showToast('Nuevo proyecto creado');
    };

    const value = React.useMemo(() => ({
        projectInfo, setProjectInfo,
        items, setItems,
        savedBudgets, setSavedBudgets,
        catalog, setCatalog,
        toast, showToast, setToast,
        calculateSubtotal, calculateTotal, getCalculations,
        saveBudget, loadBudget, deleteBudget, newProject,
        addToCatalog, deleteFromCatalog, updateCatalogBulk,
        loading,
        rateLimitModal, showRateLimitModal, closeRateLimitModal
    }), [
        projectInfo, items, savedBudgets, catalog, toast, loading, rateLimitModal,
        showToast, showRateLimitModal, closeRateLimitModal
    ]);

    return <ProjectContext.Provider value={value}>{children}</ProjectContext.Provider>;
};

import React, { useState } from 'react';
import { Search, MapPin, DollarSign, Building, Store, Loader2, Info } from 'lucide-react';
import { useProject } from '../context/ProjectContext';
import { useAuth } from '../context/AuthContext'; // Para obtener el userTier
import { FUNCTION_TYPE, USER_TIER } from '../services/ApiKeyManager'; // Para tipos de función y tiers

const PriceSearchPage = () => {
    const [material, setMaterial] = useState('');
    const [locations, setLocations] = useState('');
    const [prices, setPrices] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const { toast, setToast, showRateLimitModal } = useProject();
    const { user } = useAuth(); // Obtener el usuario para determinar el tier

    const handleSearch = async (e) => {
        e.preventDefault();
        if (!material.trim() || !locations.trim()) {
            setToast({ message: 'Por favor, ingresa un material y al menos una ubicación.', type: 'error' });
            return;
        }

        setLoading(true);
        setError(null);
        setPrices([]);

        try {
            const userTier = user?.isPro ? USER_TIER.PRO : USER_TIER.FREE;

            const response = await fetch('http://localhost:4001/api/ai/pricesearch', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    material,
                    locations,
                    userTier,
                    functionType: FUNCTION_TYPE.PRICE_SEARCH,
                }),
            });

            const data = await response.json();

            if (response.ok && data.success) {
                if (response.status === 429) {
                    const retryAfter = data.retryAfter || 60;
                    showRateLimitModal(data.error, retryAfter);
                    return;
                }

                if (data.data.length > 0) {
                    setPrices(data.data);
                    setToast({ message: 'Búsqueda de precios completada.', type: 'success' });
                } else {
                    setToast({ message: 'No se encontraron precios para los criterios especificados.', type: 'info' });
                }
            } else {
                if (response.status === 429) {
                    const retryAfter = data.retryAfter || 60;
                    showRateLimitModal(data.error, retryAfter);
                    return;
                }
                setError(data.error || 'Ocurrió un error al buscar precios.');
                setToast({ message: data.error || 'Error al buscar precios.', type: 'error' });
            }
        } catch (err) {
            console.error('Error fetching prices:', err);
            setError('No se pudo conectar con el servicio de búsqueda de precios.');
            setToast({ message: 'Error de conexión con la IA.', type: 'error' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto p-4 md:p-8">
            <h1 className="text-3xl font-bold text-slate-800 dark:text-slate-100 mb-6">Búsqueda de Precios con IA</h1>

            <div className="bg-white dark:bg-slate-800 rounded-lg shadow-md p-6 mb-8">
                <form onSubmit={handleSearch} className="space-y-4">
                    <div>
                        <label htmlFor="material" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Material a buscar:
                        </label>
                        <input
                            type="text"
                            id="material"
                            className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-md bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-slate-100 focus:ring-blue-500 focus:border-blue-500"
                            placeholder="Ej: Cemento gris, Varilla 3/8, Ladrillo rojo"
                            value={material}
                            onChange={(e) => setMaterial(e.target.value)}
                            required
                        />
                    </div>
                    <div>
                        <label htmlFor="locations" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                            Ubicaciones (separadas por comas):
                        </label>
                        <textarea
                            id="locations"
                            rows="3"
                            className="w-full p-3 border border-slate-300 dark:border-slate-600 rounded-md bg-slate-50 dark:bg-slate-700 text-slate-900 dark:text-slate-100 focus:ring-blue-500 focus:border-blue-500"
                            placeholder="Ej: México Ciudad de México, Nezahualcóyotl, Oaxaca San Juan Bautista Tuxtepec Oaxaca"
                            value={locations}
                            onChange={(e) => setLocations(e.target.value)}
                            required
                        ></textarea>
                        <p className="mt-2 text-xs text-slate-500 dark:text-slate-400 flex items-center gap-1">
                            <Info size={14} />
                            La IA intentará buscar en empresas y tiendas dentro de estas regiones.
                        </p>
                    </div>
                    <button
                        type="submit"
                        className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white font-semibold rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-slate-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        disabled={loading}
                    >
                        {loading ? (
                            <>
                                <Loader2 className="animate-spin" size={20} />
                                Buscando precios...
                            </>
                        ) : (
                            <>
                                <Search size={20} />
                                Buscar Precios
                            </>
                        )}
                    </button>
                </form>
            </div>

            {error && (
                <div className="bg-red-100 dark:bg-red-900 border border-red-400 text-red-700 dark:text-red-200 px-4 py-3 rounded relative mb-8" role="alert">
                    <strong className="font-bold">Error:</strong>
                    <span className="block sm:inline"> {error}</span>
                </div>
            )}

            {prices.length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {prices.map((item, index) => (
                        <div key={index} className="bg-white dark:bg-slate-800 rounded-lg shadow-md p-6 border border-slate-200 dark:border-slate-700 hover:shadow-lg transition-shadow">
                            <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-100 mb-3 flex items-center gap-2">
                                <DollarSign size={20} className="text-green-500" />
                                {item.name}
                            </h3>
                            <p className="text-slate-700 dark:text-slate-300 mb-2 flex items-center gap-2">
                                <MapPin size={16} className="text-blue-500" />
                                <span className="font-medium">Ubicación:</span> {item.location}
                            </p>
                            <p className="text-slate-700 dark:text-slate-300 mb-2 flex items-center gap-2">
                                <Building size={16} className="text-purple-500" />
                                <span className="font-medium">Precio:</span> <span className="text-green-600 dark:text-green-400 font-bold">{item.price}</span>
                            </p>
                            <p className="text-slate-600 dark:text-slate-400 text-sm flex items-center gap-2">
                                <Store size={16} className="text-orange-500" />
                                <span className="font-medium">Fuente:</span> {item.source}
                            </p>
                        </div>
                    ))}
                </div>
            )}

            {!loading && prices.length === 0 && !error && (material.trim() || locations.trim()) && (
                <div className="bg-blue-100 dark:bg-blue-900 border border-blue-400 text-blue-700 dark:text-blue-200 px-4 py-3 rounded relative" role="alert">
                    <strong className="font-bold">Consejo:</strong>
                    <span className="block sm:inline"> Ingresa un material y una o varias ubicaciones para iniciar la búsqueda de precios.</span>
                </div>
            )}
        </div>
    );
};

export default PriceSearchPage;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { supabase } from '../lib/supabaseClient';
import { setSentryUser, clearSentryUser } from '../lib/sentry';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check active session
        supabase.auth.getSession().then(({ data: { session } }) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);
            setLoading(false);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            }
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            const currentUser = session?.user ?? null;
            setUser(currentUser);

            // Configurar usuario en Sentry
            if (currentUser) {
                setSentryUser(currentUser);
            } else {
                clearSentryUser();
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    const signUp = async (email, password, metadata = {}) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.signUp({
            email,
            password,
            options: {
                data: metadata,
                emailRedirectTo: `${baseUrl}/confirm-email`
            }
        });
        return { data, error };
    };

    const signIn = async (email, password) => {
        const { data, error } = await supabase.auth.signInWithPassword({
            email,
            password
        });
        return { data, error };
    };

    const signOut = async () => {
        // Limpiar estado inmediatamente para evitar race conditions antes de la navegación
        setUser(null);

        const { error } = await supabase.auth.signOut();

        // Limpiar usuario de Sentry
        clearSentryUser();

        return { error };
    };

    const resetPassword = async (email) => {
        // Obtener la URL base de la aplicación
        const baseUrl = window.location.origin;

        const { data, error } = await supabase.auth.resetPasswordForEmail(email, {
            redirectTo: `${baseUrl}/confirm-email`
        });
        return { data, error };
    };

    const updatePassword = async (newPassword) => {
        const { data, error } = await supabase.auth.updateUser({
            password: newPassword
        });
        return { data, error };
    };

    const value = {
        user,
        loading,
        signUp,
        signIn,
        signOut,
        resetPassword,
        updatePassword
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSubscription } from '../context/SubscriptionContext';
import { usePricingModal } from '../context/PricingModalContext';
import PricingModal from '../components/subscription/PricingModal';

const PricingPage = () => {
    const navigate = useNavigate();
    const { openPricingModal, closePricingModal, isOpen } = usePricingModal();

    // Abrir el modal automáticamente cuando se accede a esta página
    useEffect(() => {
        openPricingModal();
    }, [openPricingModal]);

    const handleClose = () => {
        closePricingModal();
        // Si se cierra el modal y estamos en la ruta /pricing, volver atrás
        navigate(-1);
    };

    return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
            <PricingModal isOpen={isOpen} onClose={handleClose} />
        </div>
    );
};

