                                <button
                                    type="submit"
                                    className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none transition"
                                >
                                    Crear Proyecto
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={confirmModal.onConfirm}
                type={confirmModal.type}
            />

            {/* Alert Modal */}

            <AlertModal
                isOpen={alertModal.isOpen}
                onClose={() => setAlertModal({ ...alertModal, isOpen: false })}
                title={alertModal.title}
                message={alertModal.message}
                type={alertModal.type}
            />
        </div>
    );
};

export default ProjectReportsDashboard;

import React from 'react';
import { AlertTriangle } from 'lucide-react';

const ConfirmModal = ({ isOpen, onClose, onConfirm, onCancel, title, message, confirmText = 'Confirmar', cancelText = 'Cancelar', type = 'warning' }) => {
    if (!isOpen) return null;

    const handleCancel = () => {
        if (onCancel) {
            onCancel();
        }
        onClose();
    };

    const handleConfirm = () => {
        if (onConfirm) {
            onConfirm();
        }
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden transform transition-all scale-100">
                <div className="p-6 text-center">
                    <div className={`mx-auto flex items-center justify-center h-12 w-12 rounded-full mb-4 ${type === 'danger' ? 'bg-red-100' : type === 'info' ? 'bg-blue-100' : 'bg-amber-100'}`}>
                        <AlertTriangle className={`h-6 w-6 ${type === 'danger' ? 'text-red-600' : type === 'info' ? 'text-blue-600' : 'text-amber-600'}`} />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900 mb-2">{title}</h3>
                    <p className="text-sm text-slate-500 mb-6 whitespace-pre-line">{message}</p>

                    <div className="flex gap-3 justify-center">
                        <button
                            onClick={handleCancel}
                            className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg font-medium transition"
                        >
                            {cancelText}
                        </button>
                        <button
                            onClick={handleConfirm}
                            className={`px-4 py-2 text-white rounded-lg font-bold transition shadow-lg ${type === 'danger'
                                    ? 'bg-red-600 hover:bg-red-700 shadow-red-200'
                                    : type === 'info'
                                    ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'
                                    : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'
                                }`}
                        >
                            {confirmText}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ConfirmModal;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    FileText,
    Camera,
    Plus,
    Search,
    Filter,
    Folder,
    Calendar,
    ChevronRight,
    LayoutGrid,
    List,
    Clock,
    User,
    MapPin,
    AlertCircle,
    BookOpen,
    Trash2
} from 'lucide-react';
import ConfirmModal from '../components/ui/ConfirmModal';

import Card from '../components/ui/Card';
import ProjectPersistenceService from '../services/ProjectPersistenceService';
import { formatCurrency } from '../utils/format';
import AlertModal from '../components/ui/AlertModal';

const ProjectReportsDashboard = () => {
    const navigate = useNavigate();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
    const [showNewProjectModal, setShowNewProjectModal] = useState(false);
    const [alertModal, setAlertModal] = useState({ isOpen: false, title: '', message: '', type: 'info' });
    const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', type: 'danger', onConfirm: () => { } });


    // Formulario para nuevo proyecto express (sin presupuesto)
    const [newProject, setNewProject] = useState({
        name: '',
        client: '',
        location: '',
        type: 'General'
    });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading projects:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateProject = async (e) => {
        e.preventDefault();
        if (!newProject.name.trim()) {
            setAlertModal({
                isOpen: true,
                title: 'Campo requerido',
                message: 'El nombre del proyecto es obligatorio.',
                type: 'warning'
            });
            return;
        }

        try {
            const projectData = {
                projectInfo: {
                    project: newProject.name,
                    client: newProject.client,
                    location: newProject.location,
                    type: newProject.type,
                    taxRate: 16
                },
                items: [],
                lastModified: new Date().toISOString()
            };

            const saved = await ProjectPersistenceService.saveProject(projectData);
            setShowNewProjectModal(false);
            setNewProject({ name: '', client: '', location: '', type: 'General' });
            loadProjects();

            setAlertModal({
                isOpen: true,
                title: 'Proyecto Creado',
                message: `El proyecto "${newProject.name}" ha sido creado. Ahora puedes agregar bitácoras o reportes.`,
                type: 'success'
            });
        } catch (error) {
            console.error('Error creating project:', error);
            setAlertModal({
                isOpen: true,
                title: 'Error',
                message: 'No se pudo crear el proyecto: ' + error.message,
                type: 'error'
            });
        }
    };

    const handleDeleteProject = (project) => {
        setConfirmModal({
            isOpen: true,
            title: 'Eliminar Proyecto',
            message: `¿Estás seguro de que deseas eliminar el proyecto "${project.project}"? Se eliminarán también todas las bitácoras y reportes asociados. Esta acción no se puede deshacer.`,
            type: 'danger',
            onConfirm: async () => {
                try {
                    await ProjectPersistenceService.deleteProject(project.id);
                    loadProjects();
                    setAlertModal({
                        isOpen: true,
                        title: 'Proyecto Eliminado',
                        message: 'El proyecto y todos sus datos asociados han sido eliminados.',
                        type: 'success'
                    });
                } catch (error) {
                    console.error('Error deleting project:', error);
                    setAlertModal({
                        isOpen: true,
                        title: 'Error',
                        message: 'No se pudo eliminar el proyecto: ' + error.message,
                        type: 'error'
                    });
                }
            }
        });
    };


    const filteredProjects = useMemo(() => {
        return projects.filter(p =>
            p.project?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.client?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.location?.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [projects, searchTerm]);

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleDateString('es-MX', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    return (
        <div className="flex flex-col min-h-[calc(100vh-140px)] animate-fadeIn pb-4">

            {/* Header */}
            <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center">
                <div>
                    <h1 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-slate-50 mb-1">Módulo de Reportes</h1>
                    <p className="text-sm md:text-base text-slate-600 dark:text-slate-300">Gestiona Bitácoras y Reportes Fotográficos de tus obras</p>
                </div>
                <button
                    onClick={() => setShowNewProjectModal(true)}
                    className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-blue-200 dark:shadow-blue-900/50 transition flex items-center justify-center gap-2"
                >
                    <Plus size={20} />
                    <span>Nuevo Proyecto</span>
                </button>
            </div>


            <div className="space-y-6 flex-1 flex flex-col">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">

                    <div className="flex-1 relative order-2 sm:order-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar proyecto..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 sm:py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setViewMode('grid')}
                            className={`p-2 rounded-lg transition ${viewMode === 'grid' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <LayoutGrid size={20} />
                        </button>
                        <button
                            onClick={() => setViewMode('list')}
                            className={`p-2 rounded-lg transition ${viewMode === 'list' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <List size={20} />
                        </button>
                    </div>
                </div>

                {/* Projects Content */}
                {loading ? (
                    <div className="flex flex-col items-center justify-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-600 border-t-transparent mb-4"></div>
                        <p className="text-slate-500">Cargando proyectos...</p>
                    </div>
                ) : filteredProjects.length === 0 ? (
                    <div className="flex-1 flex flex-col items-center justify-center bg-white dark:bg-slate-800 rounded-2xl p-8 md:p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-700 my-4">
                        <Folder size={64} className="mx-auto text-slate-300 mb-4" />
                        <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200">No se encontraron proyectos</h3>
                        <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-md">Crea un proyecto nuevo para comenzar a generar reportes bibliográficos, fotográficos y bitácoras.</p>
                        <button
                            onClick={() => setShowNewProjectModal(true)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-bold transition shadow-lg shadow-blue-200"
                        >
                            Crear mi primer proyecto
                        </button>
                    </div>
                ) : viewMode === 'grid' ? (

                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">

                        {filteredProjects.map(project => (
                            <Card key={project.id} className="group hover:shadow-xl transition-all duration-300 border-t-4 border-t-blue-500">
                                <div className="p-1">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                                            <Folder size={24} />
                                        </div>
                                        <span className="text-[10px] font-bold uppercase tracking-widest px-2 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 rounded">
                                            {project.type || 'General'}
                                        </span>
                                    </div>
                                    <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2 line-clamp-1">{project.project}</h3>

                                    <div className="space-y-2 mb-6">
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <User size={14} />
                                            <span className="truncate">{project.client || 'Sin cliente'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <MapPin size={14} />
                                            <span className="truncate">{project.location || 'Sin ubicación'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-500 gap-2">
                                            <Clock size={14} />
                                            <span>Última mod: {formatDate(project.lastModified)}</span>
                                        </div>
                                    </div>

                                    <div className="mt-4 flex gap-2">
                                        <button
                                            onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                            className="flex-1 flex items-center justify-center gap-2 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition shadow-lg shadow-blue-200 dark:shadow-none"
                                        >
                                            <Folder size={18} />
                                            Gestionar
                                        </button>
                                        <button
                                            onClick={() => handleDeleteProject(project)}
                                            className="p-3 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition"
                                            title="Eliminar Proyecto"
                                        >
                                            <Trash2 size={20} />
                                        </button>
                                    </div>


                                </div>
                            </Card>
                        ))}
                    </div>
                ) : (
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-x-auto overflow-y-hidden">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Proyecto</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Cliente</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Última Modificación</th>
                                    <th className="px-6 py-4 text-center text-xs font-bold text-slate-500 uppercase tracking-wider">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {filteredProjects.map(project => (
                                    <tr key={project.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="p-2 bg-blue-100 dark:bg-blue-900/50 text-blue-600 rounded-lg">
                                                    <Folder size={18} />
                                                </div>
                                                <div>
                                                    <p className="font-bold text-slate-900 dark:text-white">{project.project}</p>
                                                    <p className="text-xs text-slate-500">{project.type || 'General'}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-400">
                                            {project.client || 'N/A'}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-500">
                                            {formatDate(project.lastModified)}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex items-center justify-center gap-2">
                                                <button
                                                    onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                                    className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-300 rounded-lg font-bold hover:bg-blue-100 transition flex items-center gap-2"
                                                >
                                                    <Folder size={16} />
                                                    Gestionar
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteProject(project)}
                                                    className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                                    title="Eliminar"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>


                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modal para Nuevo Proyecto Express */}
            {showNewProjectModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100 border border-slate-200 dark:border-slate-700">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                <Plus className="text-blue-500" size={24} />
                                Nuevo Proyecto de Obra
                            </h2>
                            <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
                                <Plus size={24} className="rotate-45" />
                            </button>
                        </div>

                        <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Nombre de la Obra *</label>
                                <input
                                    autoFocus
                                    type="text"
                                    required
                                    value={newProject.name}
                                    onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ej: Remodelación Casa Blanca"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Cliente/Empresa</label>
                                <input
                                    type="text"
                                    value={newProject.client}
                                    onChange={(e) => setNewProject({ ...newProject, client: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Nombre del cliente"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Ubicación</label>
                                <input
                                    type="text"
                                    value={newProject.location}
                                    onChange={(e) => setNewProject({ ...newProject, location: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ubicación de la obra"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Tipo de Proyecto</label>
                                <select
                                    value={newProject.type}
                                    onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                >
                                    <option value="General">General</option>
                                    <option value="Residencial">Residencial</option>
                                    <option value="Comercial">Comercial</option>
                                    <option value="Industrial">Industrial</option>
                                    <option value="Infraestructura">Infraestructura</option>
                                </select>
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setShowNewProjectModal(false)}
                                    className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-bold hover:bg-slate-200 transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none transition"
                                >
                                    Crear Proyecto
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={confirmModal.onConfirm}
                type={confirmModal.type}
            />

            {/* Alert Modal */}

            <AlertModal
                isOpen={alertModal.isOpen}
                onClose={() => setAlertModal({ ...alertModal, isOpen: false })}
                title={alertModal.title}
                message={alertModal.message}
                type={alertModal.type}
            />
        </div>
    );
};

export default ProjectReportsDashboard;

import React from 'react';
import { Info, CheckCircle, AlertCircle, X } from 'lucide-react';

const AlertModal = ({ isOpen, onClose, title, message, type = 'info' }) => {
    if (!isOpen) return null;

    const icons = {
        info: <Info className="h-6 w-6 text-blue-600" />,
        success: <CheckCircle className="h-6 w-6 text-emerald-600" />,
        warning: <AlertCircle className="h-6 w-6 text-amber-600" />,
        error: <AlertCircle className="h-6 w-6 text-red-600" />
    };

    const bgColors = {
        info: 'bg-blue-100',
        success: 'bg-emerald-100',
        warning: 'bg-amber-100',
        error: 'bg-red-100'
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden transform transition-all scale-100">
                <div className="p-6">
                    <div className="flex items-start gap-4">
                        <div className={`flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full ${bgColors[type]}`}>
                            {icons[type]}
                        </div>
                        <div className="flex-1">
                            <div className="flex items-start justify-between mb-2">
                                <h3 className="text-lg font-bold text-slate-900">{title}</h3>
                                <button
                                    onClick={onClose}
                                    className="text-slate-400 hover:text-slate-600 transition p-1 -mt-1 -mr-1"
                                >
                                    <X size={18} />
                                </button>
                            </div>
                            <p className="text-sm text-slate-600 mb-6 whitespace-pre-line">{message}</p>
                            <div className="flex justify-end">
                                <button
                                    onClick={onClose}
                                    className={`px-4 py-2 text-white rounded-lg font-bold transition shadow-lg ${
                                        type === 'error' ? 'bg-red-600 hover:bg-red-700 shadow-red-200' :
                                        type === 'success' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200' :
                                        type === 'warning' ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-200' :
                                        'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'
                                    }`}
                                >
                                    Aceptar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AlertModal;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    FileText,
    Camera,
    Plus,
    Search,
    Filter,
    Folder,
    Calendar,
    ChevronRight,
    LayoutGrid,
    List,
    Clock,
    User,
    MapPin,
    AlertCircle,
    BookOpen,
    Trash2
} from 'lucide-react';
import ConfirmModal from '../components/ui/ConfirmModal';

import Card from '../components/ui/Card';
import ProjectPersistenceService from '../services/ProjectPersistenceService';
import { formatCurrency } from '../utils/format';
import AlertModal from '../components/ui/AlertModal';

const ProjectReportsDashboard = () => {
    const navigate = useNavigate();
    const [projects, setProjects] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
    const [showNewProjectModal, setShowNewProjectModal] = useState(false);
    const [alertModal, setAlertModal] = useState({ isOpen: false, title: '', message: '', type: 'info' });
    const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', type: 'danger', onConfirm: () => { } });


    // Formulario para nuevo proyecto express (sin presupuesto)
    const [newProject, setNewProject] = useState({
        name: '',
        client: '',
        location: '',
        type: 'General'
    });

    useEffect(() => {
        loadProjects();
    }, []);

    const loadProjects = async () => {
        try {
            setLoading(true);
            const data = await ProjectPersistenceService.listProjects();
            setProjects(data);
        } catch (error) {
            console.error('Error loading projects:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateProject = async (e) => {
        e.preventDefault();
        if (!newProject.name.trim()) {
            setAlertModal({
                isOpen: true,
                title: 'Campo requerido',
                message: 'El nombre del proyecto es obligatorio.',
                type: 'warning'
            });
            return;
        }

        try {
            const projectData = {
                projectInfo: {
                    project: newProject.name,
                    client: newProject.client,
                    location: newProject.location,
                    type: newProject.type,
                    taxRate: 16
                },
                items: [],
                lastModified: new Date().toISOString()
            };

            const saved = await ProjectPersistenceService.saveProject(projectData);
            setShowNewProjectModal(false);
            setNewProject({ name: '', client: '', location: '', type: 'General' });
            loadProjects();

            setAlertModal({
                isOpen: true,
                title: 'Proyecto Creado',
                message: `El proyecto "${newProject.name}" ha sido creado. Ahora puedes agregar bitácoras o reportes.`,
                type: 'success'
            });
        } catch (error) {
            console.error('Error creating project:', error);
            setAlertModal({
                isOpen: true,
                title: 'Error',
                message: 'No se pudo crear el proyecto: ' + error.message,
                type: 'error'
            });
        }
    };

    const handleDeleteProject = (project) => {
        setConfirmModal({
            isOpen: true,
            title: 'Eliminar Proyecto',
            message: `¿Estás seguro de que deseas eliminar el proyecto "${project.project}"? Se eliminarán también todas las bitácoras y reportes asociados. Esta acción no se puede deshacer.`,
            type: 'danger',
            onConfirm: async () => {
                try {
                    await ProjectPersistenceService.deleteProject(project.id);
                    loadProjects();
                    setAlertModal({
                        isOpen: true,
                        title: 'Proyecto Eliminado',
                        message: 'El proyecto y todos sus datos asociados han sido eliminados.',
                        type: 'success'
                    });
                } catch (error) {
                    console.error('Error deleting project:', error);
                    setAlertModal({
                        isOpen: true,
                        title: 'Error',
                        message: 'No se pudo eliminar el proyecto: ' + error.message,
                        type: 'error'
                    });
                }
            }
        });
    };


    const filteredProjects = useMemo(() => {
        return projects.filter(p =>
            p.project?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.client?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            p.location?.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [projects, searchTerm]);

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleDateString('es-MX', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    return (
        <div className="flex flex-col min-h-[calc(100vh-140px)] animate-fadeIn pb-4">

            {/* Header */}
            <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center">
                <div>
                    <h1 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-slate-50 mb-1">Módulo de Reportes</h1>
                    <p className="text-sm md:text-base text-slate-600 dark:text-slate-300">Gestiona Bitácoras y Reportes Fotográficos de tus obras</p>
                </div>
                <button
                    onClick={() => setShowNewProjectModal(true)}
                    className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-blue-200 dark:shadow-blue-900/50 transition flex items-center justify-center gap-2"
                >
                    <Plus size={20} />
                    <span>Nuevo Proyecto</span>
                </button>
            </div>


            <div className="space-y-6 flex-1 flex flex-col">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">

                    <div className="flex-1 relative order-2 sm:order-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar proyecto..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 sm:py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setViewMode('grid')}
                            className={`p-2 rounded-lg transition ${viewMode === 'grid' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <LayoutGrid size={20} />
                        </button>
                        <button
                            onClick={() => setViewMode('list')}
                            className={`p-2 rounded-lg transition ${viewMode === 'list' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/50 dark:text-blue-300' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
                        >
                            <List size={20} />
                        </button>
                    </div>
                </div>

                {/* Projects Content */}
                {loading ? (
                    <div className="flex flex-col items-center justify-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-600 border-t-transparent mb-4"></div>
                        <p className="text-slate-500">Cargando proyectos...</p>
                    </div>
                ) : filteredProjects.length === 0 ? (
                    <div className="flex-1 flex flex-col items-center justify-center bg-white dark:bg-slate-800 rounded-2xl p-8 md:p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-700 my-4">
                        <Folder size={64} className="mx-auto text-slate-300 mb-4" />
                        <h3 className="text-xl font-bold text-slate-700 dark:text-slate-200">No se encontraron proyectos</h3>
                        <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-md">Crea un proyecto nuevo para comenzar a generar reportes bibliográficos, fotográficos y bitácoras.</p>
                        <button
                            onClick={() => setShowNewProjectModal(true)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-bold transition shadow-lg shadow-blue-200"
                        >
                            Crear mi primer proyecto
                        </button>
                    </div>
                ) : viewMode === 'grid' ? (

                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">

                        {filteredProjects.map(project => (
                            <Card key={project.id} className="group hover:shadow-xl transition-all duration-300 border-t-4 border-t-blue-500">
                                <div className="p-1">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="p-2 bg-blue-50 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                                            <Folder size={24} />
                                        </div>
                                        <span className="text-[10px] font-bold uppercase tracking-widest px-2 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 rounded">
                                            {project.type || 'General'}
                                        </span>
                                    </div>
                                    <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2 line-clamp-1">{project.project}</h3>

                                    <div className="space-y-2 mb-6">
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <User size={14} />
                                            <span className="truncate">{project.client || 'Sin cliente'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-600 dark:text-slate-400 gap-2">
                                            <MapPin size={14} />
                                            <span className="truncate">{project.location || 'Sin ubicación'}</span>
                                        </div>
                                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-500 gap-2">
                                            <Clock size={14} />
                                            <span>Última mod: {formatDate(project.lastModified)}</span>
                                        </div>
                                    </div>

                                    <div className="mt-4 flex gap-2">
                                        <button
                                            onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                            className="flex-1 flex items-center justify-center gap-2 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition shadow-lg shadow-blue-200 dark:shadow-none"
                                        >
                                            <Folder size={18} />
                                            Gestionar
                                        </button>
                                        <button
                                            onClick={() => handleDeleteProject(project)}
                                            className="p-3 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition"
                                            title="Eliminar Proyecto"
                                        >
                                            <Trash2 size={20} />
                                        </button>
                                    </div>


                                </div>
                            </Card>
                        ))}
                    </div>
                ) : (
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-x-auto overflow-y-hidden">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Proyecto</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Cliente</th>
                                    <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Última Modificación</th>
                                    <th className="px-6 py-4 text-center text-xs font-bold text-slate-500 uppercase tracking-wider">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {filteredProjects.map(project => (
                                    <tr key={project.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="p-2 bg-blue-100 dark:bg-blue-900/50 text-blue-600 rounded-lg">
                                                    <Folder size={18} />
                                                </div>
                                                <div>
                                                    <p className="font-bold text-slate-900 dark:text-white">{project.project}</p>
                                                    <p className="text-xs text-slate-500">{project.type || 'General'}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-400">
                                            {project.client || 'N/A'}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-500">
                                            {formatDate(project.lastModified)}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex items-center justify-center gap-2">
                                                <button
                                                    onClick={() => navigate(`/project/${project.id}/bitacora`)}
                                                    className="px-4 py-2 bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-300 rounded-lg font-bold hover:bg-blue-100 transition flex items-center gap-2"
                                                >
                                                    <Folder size={16} />
                                                    Gestionar
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteProject(project)}
                                                    className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition"
                                                    title="Eliminar"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>


                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modal para Nuevo Proyecto Express */}
            {showNewProjectModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100 border border-slate-200 dark:border-slate-700">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                <Plus className="text-blue-500" size={24} />
                                Nuevo Proyecto de Obra
                            </h2>
                            <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300">
                                <Plus size={24} className="rotate-45" />
                            </button>
                        </div>

                        <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Nombre de la Obra *</label>
                                <input
                                    autoFocus
                                    type="text"
                                    required
                                    value={newProject.name}
                                    onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ej: Remodelación Casa Blanca"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Cliente/Empresa</label>
                                <input
                                    type="text"
                                    value={newProject.client}
                                    onChange={(e) => setNewProject({ ...newProject, client: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Nombre del cliente"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Ubicación</label>
                                <input
                                    type="text"
                                    value={newProject.location}
                                    onChange={(e) => setNewProject({ ...newProject, location: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                    placeholder="Ubicación de la obra"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 tracking-wider">Tipo de Proyecto</label>
                                <select
                                    value={newProject.type}
                                    onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition"
                                >
                                    <option value="General">General</option>
                                    <option value="Residencial">Residencial</option>
                                    <option value="Comercial">Comercial</option>
                                    <option value="Industrial">Industrial</option>
                                    <option value="Infraestructura">Infraestructura</option>
                                </select>
                            </div>

                            <div className="pt-4 flex gap-3">
                                <button
                                    type="button"
                                    onClick={() => setShowNewProjectModal(false)}
                                    className="flex-1 px-4 py-3 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl font-bold hover:bg-slate-200 transition"
                                >
                                    Cancelar
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none transition"
                                >
                                    Crear Proyecto
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={confirmModal.onConfirm}
                type={confirmModal.type}
            />

            {/* Alert Modal */}

            <AlertModal
                isOpen={alertModal.isOpen}
                onClose={() => setAlertModal({ ...alertModal, isOpen: false })}
                title={alertModal.title}
                message={alertModal.message}
                type={alertModal.type}
            />
        </div>
    );
};

export default ProjectReportsDashboard;

import React from 'react';

const Card = ({ children, className = "", title, action }) => (
    <div className={`bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden transition-all hover:shadow-md ${className}`}>
        {(title || action) && (
            <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/50">
                {title && <h3 className="font-bold text-slate-800 dark:text-slate-100 flex items-center">{title}</h3>}
                {action && <div>{action}</div>}
            </div>
        )}
        <div className="p-6">{children}</div>
    </div>
);

export default Card;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Calendar, Clock } from 'lucide-react';
import GanttChart from '../components/schedule/GanttChart';
import ProjectPersistenceService from '../services/ProjectPersistenceService';

const ScheduleGanttPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [scheduleData, setScheduleData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [projectInfo, setProjectInfo] = useState(null);

    useEffect(() => {
        loadSchedule();
    }, [id]);

    const loadSchedule = async () => {
        if (!id) {
            navigate('/editor');
            return;
        }

        try {
            setLoading(true);
            const project = await ProjectPersistenceService.loadProject(id);
            
            if (project && project.scheduleData) {
                setScheduleData(project.scheduleData);
                setProjectInfo(project.projectInfo);
            } else {
                // Si no hay cronograma, redirigir al editor
                navigate(`/editor/${id}`);
            }
        } catch (error) {
            console.error('Error loading schedule:', error);
            navigate(`/editor/${id}`);
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = async (updatedSchedule) => {
        setScheduleData(updatedSchedule);
        
        // Guardar automáticamente
        if (id) {
            try {
                await ProjectPersistenceService.syncSchedule(id, updatedSchedule);
            } catch (error) {
                console.error('Error saving schedule:', error);
            }
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600">Cargando cronograma...</p>
                </div>
            </div>
        );
    }

    if (!scheduleData || !scheduleData.phases || scheduleData.phases.length === 0) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-lg p-8 max-w-md w-full text-center">
                    <Calendar className="mx-auto mb-4 text-slate-400" size={48} />
                    <h2 className="text-xl font-bold text-slate-800 mb-2">No hay cronograma disponible</h2>
                    <p className="text-slate-600 mb-6">Genera un cronograma desde el editor del proyecto.</p>
                    <button
                        onClick={() => navigate(`/editor/${id}`)}
                        className="px-6 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition"
                    >
                        Ir al Editor
                    </button>
                </div>
            </div>
        );
    }

    const { totalDurationWeeks = 0, startDate = new Date().toISOString().split('T')[0] } = scheduleData || {};

    return (
        <div className="min-h-screen bg-slate-50">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 sticky top-0 z-10">
                <div className="w-full px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                            <button
                                onClick={() => navigate(`/editor/${id}`)}
                                className="p-2 hover:bg-slate-100 rounded-lg transition"
                                title="Volver al editor"
                            >
                                <ArrowLeft size={20} className="text-slate-600" />
                            </button>
                            <div>
                                <h1 className="text-xl font-bold text-slate-800">
                                    {projectInfo?.project || 'Cronograma de Obra'}
                                </h1>
                                <p className="text-sm text-slate-500">
                                    Vista Gantt - Cronograma Visual Interactivo
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4">
                            {/* Summary Card Compacta */}
                            <div className="bg-emerald-50 px-4 py-2 rounded-lg border border-emerald-200">
                                <div className="flex items-center gap-2">
                                    <Clock className="text-emerald-600" size={18} />
                                    <div>
                                        <div className="text-xs text-emerald-600 font-medium">Duración Total</div>
                                        <div className="text-sm font-bold text-emerald-700">{totalDurationWeeks} Semanas</div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Gantt Chart - Ocupa todo el espacio disponible */}
            <div className="w-full h-[calc(100vh-100px)] p-4">
                <div className="h-full w-full bg-slate-50 rounded-lg overflow-hidden border border-slate-200">
                    <GanttChart
                        scheduleData={scheduleData}
                        onUpdate={handleUpdate}
                        startDate={startDate ? new Date(startDate) : new Date()}
                    />
                </div>
            </div>
        </div>
    );
};

export default ScheduleGanttPage;

/**
 * ProjectPersistenceService
 * Servicio centralizado para persistencia de proyectos
 * Maneja guardado, carga, eliminación y sincronización con Supabase
 */

import SupabaseService from './SupabaseService';
import { supabase } from '../lib/supabaseClient';

export class ProjectPersistenceService {
    /**
     * Guarda un proyecto completo con sincronización de cronograma
     * @param {Object} projectData - Datos completos del proyecto
     * @returns {Promise<Object>} - Proyecto guardado con ID actualizado
     */
    static async saveProject(projectData) {
        // Validar que tenga nombre
        if (!projectData.projectInfo?.project) {
            throw new Error('El proyecto debe tener un nombre');
        }
        if (import.meta.env?.DEV) {
            console.debug('[Reporte] ProjectPersistence.saveProject - id:', projectData?.id, 'projectInfo:', {
                project: projectData.projectInfo?.project,
                contractor: projectData.projectInfo?.contractor,
                concepts: projectData.projectInfo?.concepts,
                ubicacion: projectData.projectInfo?.ubicacion,
                lastReportDate: projectData.projectInfo?.lastReportDate,
            })
        }
        // Guardar proyecto principal
        const saved = await SupabaseService.saveProject(projectData);
        if (import.meta.env?.DEV) console.debug('[Reporte] ProjectPersistence.saveProject - resultado OK, id:', saved?.id)

        // Sincronizar cronograma si existe
        if (projectData.scheduleData && saved.id) {
            await this.syncSchedule(saved.id, projectData.scheduleData);
        }

        return saved;
    }

    /**
     * Sincroniza el cronograma con la tabla project_schedules
     * @param {string} projectId - ID del proyecto
     * @param {Object} scheduleData - Datos del cronograma
     */
    static async syncSchedule(projectId, scheduleData) {
        if (!projectId || !scheduleData) return;

        try {
            // Verificar si existe cronograma
            const { data: existing } = await supabase
                .from('project_schedules')
                .select('id')
                .eq('project_id', projectId)
                .maybeSingle();

            if (existing) {
                // Actualizar existente
                await supabase
                    .from('project_schedules')
                    .update({
                        tasks: scheduleData,
                        updated_at: new Date().toISOString()
                    })
                    .eq('id', existing.id);
            } else {
                // Crear nuevo
                await supabase
                    .from('project_schedules')
                    .insert([{
                        project_id: projectId,
                        tasks: scheduleData
                    }]);
            }
        } catch (error) {
            console.error('Error syncing schedule:', error);
            // No lanzar error para no interrumpir el guardado del proyecto
        }
    }

    /**
     * Carga un proyecto completo por ID
     * Valida que el proyecto pertenezca al usuario actual
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Datos completos del proyecto o null
     * @throws {Error} - Si el proyecto no existe o el usuario no tiene permisos
     */
    static async loadProject(projectId) {
        if (!projectId) {
            throw new Error('ID de proyecto requerido');
        }

        try {
            const fullData = await SupabaseService.getProject(projectId);
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] ProjectPersistence.loadProject - projectId:', projectId, 'projectInfo leído:', {
                    project: fullData.projectInfo?.project,
                    contractor: fullData.projectInfo?.contractor,
                    concepts: fullData.projectInfo?.concepts,
                    ubicacion: fullData.projectInfo?.ubicacion,
                    lastReportDate: fullData.projectInfo?.lastReportDate,
                })
            }
            if (!fullData) {
                throw new Error('Proyecto no encontrado');
            }

            // Cargar cronograma desde tabla separada si existe
            const { data: schedule } = await supabase
                .from('project_schedules')
                .select('tasks')
                .eq('project_id', projectId)
                .maybeSingle();

            // Priorizar cronograma de tabla separada, sino usar el del JSON
            if (schedule) {
                fullData.scheduleData = schedule.tasks;
            }

            return fullData;
        } catch (error) {
            console.error('Error loading project:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Lista todos los proyectos (solo metadata)
     * @returns {Promise<Array>} - Lista de proyectos
     */
    static async listProjects() {
        return await SupabaseService.listProjects();
    }

    /**
     * Elimina un proyecto
     * @param {string} projectId - ID del proyecto a eliminar
     */
    static async deleteProject(projectId) {
        if (!projectId) throw new Error('Project ID is required');

        // 1. Eliminar logs de bitácora
        try {
            await supabase
                .from('site_logs')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting logs:', error);
        }

        // 2. Eliminar cronograma asociado
        try {
            await supabase
                .from('project_schedules')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting schedule:', error);
        }

        // 3. Eliminar proyecto principal
        await SupabaseService.deleteProject(projectId);
    }


    /**
     * Renombra un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {string} newName - Nuevo nombre
     */
    static async renameProject(projectId, newName) {
        if (!projectId || !newName) {
            throw new Error('Project ID and new name are required');
        }

        await SupabaseService.updateProjectName(projectId, newName);
    }

    /**
     * Carga un proyecto desde URL params
     * Incluye carga de cronograma desde tabla separada
     * @param {string} projectId - ID del proyecto desde URL
     * @returns {Promise<Object|null>} - Datos completos del proyecto
     */
    static async loadProjectFromUrl(projectId) {
        return await this.loadProject(projectId);
    }
}

