                                        const monthWidth = containerWidth / Math.ceil(totalDays / 30);
                                        xPos = monthsSinceStart * monthWidth;
                                        cellWidth = monthWidth;
                                        label = date.toLocaleDateString('es-MX', { month: 'short', year: '2-digit' });
                                    }
                                    
                                    return (
                                        <div
                                            key={index}
                                            className="absolute top-0 border-r border-slate-200"
                                            style={{
                                                left: `${xPos + 180}px`,
                                                width: `${cellWidth}px`,
                                                height: `${headerHeight}px`
                                            }}
                                        >
                                            <div className="p-0.5 text-[9px] font-medium text-slate-600 text-center">
                                                {label}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>

                    {/* Filas de tareas */}
                    <div className="relative">
                        {tasksWithDependencies.map((task, index) => {
                            const taskX = dateToX(task.start);
                            const taskWidth = dateToX(task.end) - taskX;
                            const taskY = index * rowHeight;
                            const isDragging = draggingTask?.id === task.id;

                            return (
                                <div key={task.id} className="relative" style={{ height: `${rowHeight}px` }}>
                                    {/* Fondo de la fila */}
                                    <div className="absolute inset-0 bg-slate-50 border-b border-slate-100" />
                                    
                                    {/* Nombre de la tarea (sticky) */}
                                    <div 
                                        className="sticky left-0 z-10 bg-white border-r-2 border-slate-300 px-1.5 py-0.5 h-full flex items-center"
                                        style={{ width: '180px' }}
                                    >
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-1">
                                                <span className="font-medium text-slate-800 text-[10px] truncate leading-tight">{task.name}</span>
                                                {task.isCritical && (
                                                    <span className="px-0.5 py-0 bg-red-100 text-red-700 rounded text-[8px] font-bold shrink-0">
                                                        C
                                                    </span>
                                                )}
                                            </div>
                                            <div className="text-[9px] text-slate-500 mt-0 truncate leading-tight">
                                                {task.start.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })} - {task.end.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })}
                                            </div>
                                        </div>
                                        <Move size={10} className="text-slate-400 shrink-0 ml-0.5" />
                                    </div>

                                    {/* Barra de la tarea */}
                                    <div
                                        className={`absolute cursor-pointer transition-all group ${
                                            task.isCritical 
                                                ? 'bg-red-500 hover:bg-red-600' 
                                                : 'bg-blue-500 hover:bg-blue-600'
                                        } ${isDragging ? 'opacity-70 shadow-lg' : 'shadow-sm'} rounded px-1 flex items-center`}
                                        style={{
                                            left: `${taskX + 180}px`,
                                            top: '4px',
                                            width: `${Math.max(taskWidth, 50)}px`,
                                            height: `${rowHeight - 8}px`,
                                            zIndex: isDragging ? 50 : 5
                                        }}
                                        onMouseDown={(e) => {
                                            // Si es click simple, mostrar detalles; si es drag, mover
                                            if (e.button === 0) {
                                                const startX = e.clientX;
                                                const startY = e.clientY;
                                                const handleMouseMove = (moveEvent) => {
                                                    const deltaX = Math.abs(moveEvent.clientX - startX);
                                                    const deltaY = Math.abs(moveEvent.clientY - startY);
                                                    if (deltaX > 5 || deltaY > 5) {
                                                        // Es un drag, usar función de drag
                                                        handleTaskMouseDown(task, e);
                                                        document.removeEventListener('mousemove', handleMouseMove);
                                                    }
                                                };
                                                const handleMouseUp = () => {
                                                    document.removeEventListener('mousemove', handleMouseMove);
                                                    document.removeEventListener('mouseup', handleMouseUp);
                                                    // Si no hubo movimiento significativo, mostrar detalles
                                                    setSelectedTask(task);
                                                    setShowTaskDetails(true);
                                                };
                                                document.addEventListener('mousemove', handleMouseMove);
                                                document.addEventListener('mouseup', handleMouseUp);
                                            } else {
                                                handleTaskMouseDown(task, e);
                                            }
                                        }}
                                        title={`${task.name} - Click para ver detalles, arrastra para mover`}
                                    >
                                        <span className="text-white text-[9px] font-medium truncate leading-tight">
                                            {task.name}
                                        </span>
                                        {/* Indicador de que tiene detalles */}
                                        {(task.resources?.length > 0 || task.risks?.length > 0 || task.notes || task.originalPhase?.items?.length > 0) && (
                                            <Info size={8} className="text-white opacity-70 group-hover:opacity-100 ml-1" />
                                        )}
                                    </div>

                                    {/* Dependencias (líneas) */}
                                    {task.dependencies && task.dependencies.length > 0 && (
                                        <svg 
                                            className="absolute pointer-events-none"
                                            style={{ width: `${containerWidth}px`, height: `${rowHeight}px`, top: 0, left: 0, zIndex: 1 }}
                                        >
                                            {task.dependencies.map((depId, depIndex) => {
                                                const depTask = tasksWithDependencies.find(t => t.id === depId);
                                                if (!depTask) return null;
                                                
                                                const depX = dateToX(depTask.end) + 180;
                                                const depY = tasksWithDependencies.findIndex(t => t.id === depId) * rowHeight + (rowHeight / 2);
                                                const taskXCenter = taskX + 180;
                                                const taskYCenter = taskY + (rowHeight / 2);
                                                
                                                return (
                                                    <g key={depIndex}>
                                                        <path
                                                            d={`M ${depX} ${depY} L ${depX + 20} ${depY} L ${depX + 20} ${taskYCenter} L ${taskXCenter} ${taskYCenter}`}
                                                            stroke="#64748b"
                                                            strokeWidth="2"
                                                            fill="none"
                                                            strokeDasharray="5,5"
                                                            markerEnd="url(#arrowhead)"
                                                        />
                                                    </g>
                                                );
                                            })}
                                        </svg>
                                    )}
                                </div>
                            );
                        })}
                    </div>

                    {/* SVG markers para flechas */}
                    <svg style={{ position: 'absolute', width: 0, height: 0 }}>
                        <defs>
                            <marker
                                id="arrowhead"
                                markerWidth="10"
                                markerHeight="10"
                                refX="9"
                                refY="3"
                                orient="auto"
                            >
                                <polygon points="0 0, 10 3, 0 6" fill="#64748b" />
                            </marker>
                        </defs>
                    </svg>
                </div>
            </div>

            {/* Modal de Detalles de Tarea */}
            {showTaskDetails && selectedTask && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-sm animate-fadeIn">
                    <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                        {/* Header */}
                        <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                            <h3 className="font-bold flex items-center text-lg">
                                <Info className="mr-2 text-emerald-200" size={20} />
                                {selectedTask.name}
                            </h3>
                            <button 
                                onClick={() => {
                                    setShowTaskDetails(false);
                                    setSelectedTask(null);
                                }}
                                className="text-white/60 hover:text-white transition"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        {/* Content */}
                        <div className="p-6 overflow-y-auto flex-1">
                            <div className="space-y-4">
                                {/* Fechas */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Fecha Inicio</div>
                                        <div className="text-sm font-medium text-slate-800">
                                            {selectedTask.start.toLocaleDateString('es-MX', { 
                                                weekday: 'long', 
                                                year: 'numeric', 
                                                month: 'long', 
                                                day: 'numeric' 
                                            })}
                                        </div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Fecha Fin</div>
                                        <div className="text-sm font-medium text-slate-800">
                                            {selectedTask.end.toLocaleDateString('es-MX', { 
                                                weekday: 'long', 
                                                year: 'numeric', 
                                                month: 'long', 
                                                day: 'numeric' 
                                            })}
                                        </div>
                                    </div>
                                </div>

                                {/* Duración y Estado */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Duración</div>
                                        <div className="text-sm font-medium text-slate-800">{selectedTask.duration} semanas</div>
                                    </div>
                                    <div className="bg-slate-50 p-3 rounded-lg">
                                        <div className="text-xs font-bold text-slate-500 uppercase mb-1">Estado</div>
                                        <div className="flex items-center gap-2">
                                            {selectedTask.isCritical ? (
                                                <span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">
                                                    Ruta Crítica
                                                </span>
                                            ) : (
                                                <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-bold">
                                                    Fase Normal
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                {/* Recursos */}
                                {selectedTask.resources && selectedTask.resources.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Wrench size={16} className="text-blue-600" />
                                            <h4 className="font-bold text-slate-700">Recursos Clave</h4>
                                        </div>
                                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                                            <div className="flex flex-wrap gap-2">
                                                {selectedTask.resources.map((resource, i) => (
                                                    <span key={i} className="px-3 py-1.5 bg-white text-blue-700 rounded-lg text-xs font-medium border border-blue-200">
                                                        {resource}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Riesgos */}
                                {selectedTask.risks && selectedTask.risks.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <AlertTriangle size={16} className="text-amber-600" />
                                            <h4 className="font-bold text-slate-700">Riesgos Potenciales</h4>
                                        </div>
                                        <div className="bg-amber-50 p-4 rounded-lg border border-amber-100">
                                            <ul className="space-y-2">
                                                {selectedTask.risks.map((risk, i) => (
                                                    <li key={i} className="flex items-start gap-2 text-sm text-amber-800">
                                                        <span className="text-amber-600 mt-0.5">•</span>
                                                        <span>{risk}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    </div>
                                )}

                                {/* Partidas Incluidas */}
                                {selectedTask.originalPhase?.items && selectedTask.originalPhase.items.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Package size={16} className="text-emerald-600" />
                                            <h4 className="font-bold text-slate-700">Partidas Incluidas</h4>
                                        </div>
                                        <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-100">
                                            <div className="flex flex-wrap gap-2">
                                                {selectedTask.originalPhase.items.map((item, i) => (
                                                    <span key={i} className="px-3 py-1.5 bg-white text-emerald-700 rounded-lg text-xs font-medium border border-emerald-200">
                                                        {item}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Notas */}
                                {selectedTask.notes && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <Info size={16} className="text-slate-600" />
                                            <h4 className="font-bold text-slate-700">Notas</h4>
                                        </div>
                                        <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                                            <p className="text-sm text-slate-700 leading-relaxed">{selectedTask.notes}</p>
                                        </div>
                                    </div>
                                )}

                                {/* Dependencias */}
                                {selectedTask.dependencies && selectedTask.dependencies.length > 0 && (
                                    <div>
                                        <div className="flex items-center gap-2 mb-2">
                                            <LinkIcon size={16} className="text-purple-600" />
                                            <h4 className="font-bold text-slate-700">Dependencias</h4>
                                        </div>
                                        <div className="bg-purple-50 p-4 rounded-lg border border-purple-100">
                                            <ul className="space-y-2">
                                                {selectedTask.dependencies.map((depId, i) => {
                                                    const depTask = tasksWithDependencies.find(t => t.id === depId);
                                                    return depTask ? (
                                                        <li key={i} className="text-sm text-purple-800">
                                                            <span className="font-medium">→</span> {depTask.name}
                                                        </li>
                                                    ) : null;
                                                })}
                                            </ul>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Footer */}
                        <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end">
                            <button
                                onClick={() => {
                                    setShowTaskDetails(false);
                                    setSelectedTask(null);
                                }}
                                className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                            >
                                Cerrar
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Leyenda */}
            <div className="p-1.5 bg-slate-50 border-t border-slate-200 flex items-center justify-between text-[9px] shrink-0">
                <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1">
                        <div className="w-2.5 h-2.5 bg-blue-500 rounded"></div>
                        <span className="text-slate-600">Fase Normal</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <div className="w-2.5 h-2.5 bg-red-500 rounded"></div>
                        <span className="text-slate-600">Ruta Crítica</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <LinkIcon size={10} className="text-slate-600" />
                        <span className="text-slate-600">Dependencias</span>
                    </div>
                </div>
                <div className="text-slate-500">
                    Arrastra las barras para cambiar fechas
                </div>
            </div>
        </div>
    );
};

export default GanttChart;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, Lock, Eye, Download, ArrowLeft, Clock, User, Building2, Package, Calendar as CalendarIcon } from 'lucide-react';
import { ShareService } from '../services/ShareService';
import { PDFService } from '../services/PDFService';
import { formatCurrency } from '../utils/format';

const SharedProjectPage = () => {
    const { token } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [projectData, setProjectData] = useState(null);
    const [shareInfo, setShareInfo] = useState(null);
    const [passwordRequired, setPasswordRequired] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [error, setError] = useState(null);

    useEffect(() => {
        loadSharedProject();
    }, [token]);

    const loadSharedProject = async () => {
        try {
            setLoading(true);
            setError(null);

            const shareData = await ShareService.getShareByToken(token);

            // Verificar si requiere contraseña
            if (shareData.password) {
                // Verificar si ya se verificó (usando sessionStorage)
                const verified = sessionStorage.getItem(`share_verified_${token}`);
                if (!verified) {
                    setPasswordRequired(true);
                    setShareInfo(shareData);
                    setLoading(false);
                    return;
                }
            }

            setShareInfo(shareData);

            // Extraer datos del proyecto
            const project = shareData.projects;
            if (!project || !project.data) {
                throw new Error('Proyecto no encontrado o no disponible');
            }

            const fullProjectData = project.data;
            
            // Normalizar projectInfo para asegurar que todos los campos se carguen correctamente
            const normalizedProjectInfo = {
                project: fullProjectData.projectInfo?.project || project.name,
                client: fullProjectData.projectInfo?.client || project.client,
                type: fullProjectData.projectInfo?.type || project.type,
                taxRate: fullProjectData.projectInfo?.taxRate ?? 16, // Usar ?? para permitir 0
                currency: fullProjectData.projectInfo?.currency || 'MXN',
                date: fullProjectData.projectInfo?.date || new Date().toISOString().split('T')[0],
                location: fullProjectData.projectInfo?.location || 'México',
                ...fullProjectData.projectInfo // Preservar otros campos
            };
            
            setProjectData({
                projectInfo: normalizedProjectInfo,
                items: fullProjectData.items || [],
                scheduleData: fullProjectData.scheduleData,
                materialList: fullProjectData.materialList,
                apuData: fullProjectData.apuData
            });

        } catch (error) {
            console.error('Error loading shared project:', error);
            setError(error.message || 'No se pudo cargar el proyecto compartido');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        setPasswordError('');

        try {
            const isValid = await ShareService.verifyPassword(token, password);
            if (isValid) {
                // Guardar en sessionStorage para esta sesión
                sessionStorage.setItem(`share_verified_${token}`, 'true');
                setPasswordRequired(false);
                // Recargar con contraseña verificada
                await loadSharedProject();
            } else {
                setPasswordError('Contraseña incorrecta');
            }
        } catch (error) {
            setPasswordError('Error al verificar contraseña');
        }
    };

    const calculateTotals = () => {
        if (!projectData || !projectData.items || projectData.items.length === 0) {
            return { subtotal: 0, tax: 0, total: 0 };
        }

        const subtotal = projectData.items.reduce((sum, item) => {
            return sum + (item.quantity || 0) * (item.unitPrice || 0);
        }, 0);

        // Usar nullish coalescing para permitir taxRate = 0
        const taxRateValue = projectData.projectInfo?.taxRate ?? 16;
        const taxRate = taxRateValue / 100;
        const tax = subtotal * taxRate;
        const total = subtotal + tax;

        return { subtotal, tax, total };
    };

    const handleExportPDF = () => {
        if (!projectData) return;

        const { subtotal, tax, total } = calculateTotals();
        PDFService.exportBudget(
            projectData.projectInfo,
            projectData.items,
            total,
            subtotal,
            tax
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600 font-medium">Cargando presupuesto...</p>
                </div>
            </div>
        );
    }

    if (passwordRequired) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
                    <div className="text-center mb-6">
                        <div className="bg-emerald-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <Lock className="text-emerald-600" size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 mb-2">Presupuesto Protegido</h2>
                        <p className="text-slate-600">Este presupuesto está protegido con contraseña</p>
                    </div>

                    <form onSubmit={handlePasswordSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                Contraseña
                            </label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                placeholder="Ingresa la contraseña"
                                required
                                autoFocus
                            />
                            {passwordError && (
                                <p className="text-red-600 text-sm mt-2">{passwordError}</p>
                            )}
                        </div>

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition shadow-lg shadow-emerald-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full text-center">
                    <div className="bg-red-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                        <Lock className="text-red-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">No disponible</h2>
                    <p className="text-slate-600 mb-6">{error}</p>
                    <button
                        onClick={() => navigate('/')}
                        className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                    >
                        Ir al Inicio
                    </button>
                </div>
            </div>
        );
    }

    if (!projectData) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <p className="text-slate-600">No hay datos disponibles</p>
                </div>
            </div>
        );
    }

    const { subtotal, tax, total } = calculateTotals();
    const items = projectData.items || [];

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 shadow-sm">
                <div className="max-w-6xl mx-auto px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                {projectData.projectInfo?.project || 'Presupuesto'}
                            </h1>
                            <div className="flex items-center gap-4 mt-2 text-sm text-slate-600">
                                {projectData.projectInfo?.client && (
                                    <div className="flex items-center gap-1">
                                        <User size={14} />
                                        <span>{projectData.projectInfo.client}</span>
                                    </div>
                                )}
                                {projectData.projectInfo?.type && (
                                    <div className="flex items-center gap-1">
                                        <Building2 size={14} />
                                        <span>{projectData.projectInfo.type}</span>
                                    </div>
                                )}
                                {shareInfo?.last_accessed_at && (
                                    <div className="flex items-center gap-1">
                                        <Clock size={14} />
                                        <span>Visto {new Date(shareInfo.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleExportPDF}
                                className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 shadow-lg shadow-emerald-200"
                            >
                                <Download size={18} />
                                Descargar PDF
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="max-w-6xl mx-auto px-6 py-8">
                {/* Resumen */}
                <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
                    <h2 className="text-lg font-bold text-slate-800 mb-4">Resumen del Presupuesto</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">Subtotal</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(subtotal)}</div>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-lg">
                            <div className="text-sm text-slate-500 font-medium mb-1">IVA ({projectData.projectInfo?.taxRate ?? 16}%)</div>
                            <div className="text-2xl font-bold text-slate-800">{formatCurrency(tax)}</div>
                        </div>
                        <div className="bg-emerald-50 p-4 rounded-lg border-2 border-emerald-200">
                            <div className="text-sm text-emerald-600 font-medium mb-1">Total</div>
                            <div className="text-3xl font-bold text-emerald-700">{formatCurrency(total)}</div>
                        </div>
                    </div>
                </div>

                {/* Partidas */}
                <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                    <div className="p-6 border-b border-slate-200">
                        <h2 className="text-lg font-bold text-slate-800">Partidas del Presupuesto</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-slate-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">#</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Descripción</th>
                                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">P. Unit.</th>
                                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200">
                                {items.map((item, index) => (
                                    <tr key={item.id || index} className="hover:bg-slate-50 transition">
                                        <td className="px-6 py-4 text-sm text-slate-600">{index + 1}</td>
                                        <td className="px-6 py-4">
                                            <div className="text-sm font-medium text-slate-800">{item.description}</div>
                                            {item.category && (
                                                <div className="text-xs text-slate-500 mt-1">{item.category}</div>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-600">{item.unit || 'pza'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{item.quantity?.toFixed(2) || '0.00'}</td>
                                        <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(item.unitPrice || 0)}</td>
                                        <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                            {formatCurrency((item.quantity || 0) * (item.unitPrice || 0))}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot className="bg-slate-50">
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">Subtotal:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(subtotal)}</td>
                                </tr>
                                <tr>
                                    <td colSpan="4" className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                        IVA ({projectData.projectInfo?.taxRate ?? 16}%):
                                    </td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-sm font-bold text-slate-800">{formatCurrency(tax)}</td>
                                </tr>
                                <tr className="bg-emerald-50">
                                    <td colSpan="4" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">Total:</td>
                                    <td colSpan="2" className="px-6 py-4 text-right text-lg font-bold text-emerald-700">{formatCurrency(total)}</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>

                {/* Lista de Materiales/Insumos */}
                {projectData.materialList && projectData.materialList.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <Package size={20} className="text-indigo-600" />
                                Lista de Insumos y Materiales
                            </h2>
                        </div>
                        {projectData.materialAssumptions && projectData.materialAssumptions.length > 0 && (
                            <div className="bg-amber-50 border-b border-amber-100 p-4">
                                <h4 className="text-sm font-bold text-amber-800 mb-2">Notas Importantes</h4>
                                <ul className="list-disc list-inside text-xs text-amber-700 space-y-1">
                                    {projectData.materialAssumptions.map((assumption, idx) => (
                                        <li key={idx}>{assumption}</li>
                                    ))}
                                </ul>
                            </div>
                        )}
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-slate-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Material</th>
                                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Categoría</th>
                                        <th className="px-6 py-3 text-center text-xs font-bold text-slate-600 uppercase">Unidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Cantidad</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Costo Est.</th>
                                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-600 uppercase">Total</th>
                                        {projectData.materialList.some(m => m.notes) && (
                                            <th className="px-6 py-3 text-left text-xs font-bold text-slate-600 uppercase">Notas</th>
                                        )}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-200">
                                    {projectData.materialList.map((mat, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50 transition">
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800">{mat.material}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600">{mat.category || 'Materiales'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-600 text-center">{mat.unit || 'pza'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{mat.quantity?.toFixed(2) || '0.00'}</td>
                                            <td className="px-6 py-4 text-sm text-slate-800 text-right">{formatCurrency(mat.unitPrice || 0)}</td>
                                            <td className="px-6 py-4 text-sm font-medium text-slate-800 text-right">
                                                {formatCurrency((mat.quantity || 0) * (mat.unitPrice || 0))}
                                            </td>
                                            {projectData.materialList.some(m => m.notes) && (
                                                <td className="px-6 py-4 text-xs text-slate-500 italic">{mat.notes || '-'}</td>
                                            )}
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot className="bg-slate-50">
                                    <tr>
                                        <td colSpan={projectData.materialList.some(m => m.notes) ? 5 : 4} className="px-6 py-4 text-right text-sm font-bold text-slate-700">
                                            Total Estimado:
                                        </td>
                                        <td colSpan={2} className="px-6 py-4 text-right text-sm font-bold text-slate-800">
                                            {formatCurrency(
                                                projectData.materialList.reduce((sum, m) => sum + ((m.quantity || 0) * (m.unitPrice || 0)), 0)
                                            )}
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                )}

                {/* Cronograma */}
                {shareInfo?.metadata?.showSchedule !== false && projectData.scheduleData && projectData.scheduleData.tasks && projectData.scheduleData.tasks.length > 0 && (
                    <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
                        <div className="p-6 border-b border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                <CalendarIcon size={20} className="text-blue-600" />
                                Cronograma de Obra
                            </h2>
                        </div>
                        <div className="p-6">
                            <div className="space-y-4">
                                {projectData.scheduleData.tasks.map((task, idx) => (
                                    <div key={task.id || idx} className="border border-slate-200 rounded-lg p-4 hover:bg-slate-50 transition">
                                        <div className="flex items-start justify-between mb-2">
                                            <div className="flex-1">
                                                <h3 className="text-sm font-bold text-slate-800">{task.name || `Tarea ${idx + 1}`}</h3>
                                                {task.description && (
                                                    <p className="text-xs text-slate-600 mt-1">{task.description}</p>
                                                )}
                                            </div>
                                            {task.progress !== undefined && (
                                                <div className="ml-4 text-right">
                                                    <div className="text-xs text-slate-500 mb-1">Progreso</div>
                                                    <div className="text-sm font-bold text-blue-600">{task.progress || 0}%</div>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-4 mt-3 text-xs text-slate-500">
                                            {task.startDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Inicio: {new Date(task.startDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.endDate && (
                                                <div className="flex items-center gap-1">
                                                    <Calendar size={12} />
                                                    <span>Fin: {new Date(task.endDate).toLocaleDateString('es-MX')}</span>
                                                </div>
                                            )}
                                            {task.duration && (
                                                <div>
                                                    <span>Duración: {task.duration} {task.durationUnit || 'días'}</span>
                                                </div>
                                            )}
                                        </div>
                                        {task.dependencies && task.dependencies.length > 0 && (
                                            <div className="mt-2 text-xs text-slate-500">
                                                <span className="font-medium">Depende de:</span> {task.dependencies.join(', ')}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-8 text-center text-sm text-slate-500">
                    <p>Este presupuesto fue compartido contigo desde PresuGenius</p>
                    <p className="mt-1">Generado el {new Date().toLocaleDateString('es-MX', { 
                        year: 'numeric', 
                        month: 'long', 
                        day: 'numeric' 
                    })}</p>
                </div>
            </div>
        </div>
    );
};

export default SharedProjectPage;

export const formatCurrency = (amount, currency = 'MXN') => {
    return new Intl.NumberFormat('es-MX', {
        style: 'currency',
        currency: currency,
        minimumFractionDigits: 2
    }).format(amount);
};

export const numberToWords = (amount) => {
    const units = ['', 'UN', 'DOS', 'TRES', 'CUATRO', 'CINCO', 'SEIS', 'SIETE', 'OCHO', 'NUEVE'];
    const tens = ['', 'DIEZ', 'VEINTE', 'TREINTA', 'CUARENTA', 'CINCUENTA', 'SESENTA', 'SETENTA', 'OCHENTA', 'NOVENTA'];
    const teens = ['DIEZ', 'ONCE', 'DOCE', 'TRECE', 'CATORCE', 'QUINCE', 'DIECISEIS', 'DIECISIETE', 'DIECIOCHO', 'DIECINUEVE'];
    const hundreds = ['', 'CIENTO', 'DOSCIENTOS', 'TRESCIENTOS', 'CUATROCIENTOS', 'QUINIENTOS', 'SEISCIENTOS', 'SETECIENTOS', 'OCHOCIENTOS', 'NOVECIENTOS'];

    const numberToWordsRecursive = (number) => {
        if (number === 0) return '';
        if (number === 1) return 'UN '; // Special case for 1 to ensure "UN" instead of "UNO" in compound numbers often, but mainly handled by getTens/Hundreds logic if needed, actually "UNO" might be needed at end but usually "UN" for currency. Let's stick to current logic which uses 'UN' in units array? 
        // Wait, original units array had 'UN'.
        // Let's refine the helper functions inside.
    };

    const getHundreds = (num) => {
        if (num > 99) {
            if (num === 100) return 'CIEN ';
            return hundreds[Math.floor(num / 100)] + ' ' + getTens(num % 100);
        }
        return getTens(num);
    };

    const getTens = (num) => {
        if (num < 10) return units[num];
        if (num >= 10 && num < 20) return teens[num - 10];

        // Special handling for 20-29 (VEINTI...)
        if (num >= 20 && num < 30) {
            if (num === 20) return 'VEINTE';
            // VEINTIUN, VEINTIDOS, etc.
            // Note: We use 'VEINTI' + unit. 
            // Since unit[1] is 'UN', we get 'VEINTIUN'. Correct for adjectives.
            // unit[2] is 'DOS', 'VEINTIDOS'.
            return 'VEINTI' + units[num - 20];
        }

        if (num >= 30) {
            const ten = Math.floor(num / 10);
            const unit = num % 10;
            return tens[ten] + (unit > 0 ? ' Y ' + units[unit] : '');
        }
        return '';
    };

    const convertGroup = (n) => {
        if (n === 0) return '';
        return getHundreds(n);
    };

    const integerPart = Math.floor(amount);
    const decimalPart = Math.round((amount - integerPart) * 100);

    let output = '';

    if (integerPart === 0) {
        output = 'CERO ';
    } else if (integerPart >= 1000000) {
        const millions = Math.floor(integerPart / 1000000);
        const remainder = integerPart % 1000000;

        if (millions === 1) {
            output = 'UN MILLÓN ';
        } else {
            output = convertGroup(millions) + ' MILLONES ';
        }

        if (remainder > 0) {
            if (remainder >= 1000) {
                const thousands = Math.floor(remainder / 1000);
                const units = remainder % 1000;

                if (thousands === 1) {
                    output += 'MIL ';
                } else {
                    output += convertGroup(thousands) + ' MIL ';
                }

                if (units > 0) output += convertGroup(units);
            } else {
                output += convertGroup(remainder);
            }
        }
    } else if (integerPart >= 1000) {
        const thousands = Math.floor(integerPart / 1000);
        const units = integerPart % 1000;

        if (thousands === 1) {
            output += 'MIL ';
        } else {
            output += convertGroup(thousands) + ' MIL ';
        }

        if (units > 0) output += convertGroup(units);
    } else {
        output = convertGroup(integerPart);
    }

    const currencyName = integerPart === 1 ? 'PESO' : 'PESOS';
    return `${output.trim()} ${currencyName} ${decimalPart.toString().padStart(2, '0')}/100 M.N.`;
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, Lock, Eye, Download, ArrowLeft, Clock, User, Building2, Package, Calendar as CalendarIcon } from 'lucide-react';
import { ShareService } from '../services/ShareService';
import { PDFService } from '../services/PDFService';
import { formatCurrency } from '../utils/format';

const SharedProjectPage = () => {
    const { token } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [projectData, setProjectData] = useState(null);
    const [shareInfo, setShareInfo] = useState(null);
    const [passwordRequired, setPasswordRequired] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [error, setError] = useState(null);

    useEffect(() => {
        loadSharedProject();
    }, [token]);

    const loadSharedProject = async () => {
        try {
            setLoading(true);
            setError(null);

            const shareData = await ShareService.getShareByToken(token);

            // Verificar si requiere contraseña
            if (shareData.password) {
                // Verificar si ya se verificó (usando sessionStorage)
                const verified = sessionStorage.getItem(`share_verified_${token}`);
                if (!verified) {
                    setPasswordRequired(true);
                    setShareInfo(shareData);
                    setLoading(false);
                    return;
                }
            }

            setShareInfo(shareData);

            // Extraer datos del proyecto
            const project = shareData.projects;
            if (!project || !project.data) {
                throw new Error('Proyecto no encontrado o no disponible');
            }

            const fullProjectData = project.data;
            
            // Normalizar projectInfo para asegurar que todos los campos se carguen correctamente
            const normalizedProjectInfo = {
                project: fullProjectData.projectInfo?.project || project.name,
                client: fullProjectData.projectInfo?.client || project.client,
                type: fullProjectData.projectInfo?.type || project.type,
                taxRate: fullProjectData.projectInfo?.taxRate ?? 16, // Usar ?? para permitir 0
                currency: fullProjectData.projectInfo?.currency || 'MXN',
                date: fullProjectData.projectInfo?.date || new Date().toISOString().split('T')[0],
                location: fullProjectData.projectInfo?.location || 'México',
                ...fullProjectData.projectInfo // Preservar otros campos
            };
            
            setProjectData({
                projectInfo: normalizedProjectInfo,
                items: fullProjectData.items || [],
                scheduleData: fullProjectData.scheduleData,
                materialList: fullProjectData.materialList,
                apuData: fullProjectData.apuData
            });

        } catch (error) {
            console.error('Error loading shared project:', error);
            setError(error.message || 'No se pudo cargar el proyecto compartido');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        setPasswordError('');

        try {
            const isValid = await ShareService.verifyPassword(token, password);
            if (isValid) {
                // Guardar en sessionStorage para esta sesión
                sessionStorage.setItem(`share_verified_${token}`, 'true');
                setPasswordRequired(false);
                // Recargar con contraseña verificada
                await loadSharedProject();
            } else {
                setPasswordError('Contraseña incorrecta');
            }
        } catch (error) {
            setPasswordError('Error al verificar contraseña');
        }
    };

    const calculateTotals = () => {
        if (!projectData || !projectData.items || projectData.items.length === 0) {
            return { subtotal: 0, tax: 0, total: 0 };
        }

        const subtotal = projectData.items.reduce((sum, item) => {
            return sum + (item.quantity || 0) * (item.unitPrice || 0);
        }, 0);

        // Usar nullish coalescing para permitir taxRate = 0
        const taxRateValue = projectData.projectInfo?.taxRate ?? 16;
        const taxRate = taxRateValue / 100;
        const tax = subtotal * taxRate;
        const total = subtotal + tax;

        return { subtotal, tax, total };
    };

    const handleExportPDF = () => {
        if (!projectData) return;

        const { subtotal, tax, total } = calculateTotals();
        PDFService.exportBudget(
            projectData.projectInfo,
            projectData.items,
            total,
            subtotal,
            tax
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600 font-medium">Cargando presupuesto...</p>
                </div>
            </div>
        );
    }

    if (passwordRequired) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
                    <div className="text-center mb-6">
                        <div className="bg-emerald-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <Lock className="text-emerald-600" size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 mb-2">Presupuesto Protegido</h2>
                        <p className="text-slate-600">Este presupuesto está protegido con contraseña</p>
                    </div>

                    <form onSubmit={handlePasswordSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                Contraseña
                            </label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                placeholder="Ingresa la contraseña"
                                required
                                autoFocus
                            />
                            {passwordError && (
                                <p className="text-red-600 text-sm mt-2">{passwordError}</p>
                            )}
                        </div>

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition shadow-lg shadow-emerald-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full text-center">
                    <div className="bg-red-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                        <Lock className="text-red-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">No disponible</h2>
                    <p className="text-slate-600 mb-6">{error}</p>
                    <button
                        onClick={() => navigate('/')}
                        className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                    >
                        Ir al Inicio
                    </button>
                </div>
            </div>
        );
    }

    if (!projectData) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <p className="text-slate-600">No hay datos disponibles</p>
                </div>
            </div>
        );
    }

    const { subtotal, tax, total } = calculateTotals();
    const items = projectData.items || [];

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 shadow-sm">
                <div className="max-w-6xl mx-auto px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                {projectData.projectInfo?.project || 'Presupuesto'}
                            </h1>
                            <div className="flex items-center gap-4 mt-2 text-sm text-slate-600">
                                {projectData.projectInfo?.client && (
                                    <div className="flex items-center gap-1">
                                        <User size={14} />
                                        <span>{projectData.projectInfo.client}</span>
                                    </div>
                                )}
                                {projectData.projectInfo?.type && (
                                    <div className="flex items-center gap-1">
                                        <Building2 size={14} />
                                        <span>{projectData.projectInfo.type}</span>
                                    </div>
                                )}
                                {shareInfo?.last_accessed_at && (
                                    <div className="flex items-center gap-1">
                                        <Clock size={14} />
                                        <span>Visto {new Date(shareInfo.last_accessed_at).toLocaleDateString('es-MX')}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleExportPDF}
                                className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition flex items-center gap-2 shadow-lg shadow-emerald-200"
                            >
                                <Download size={18} />
                                Descargar PDF
                            </button>
