                    })}</p>
                </div>
            </div>
        </div>
    );
};

export default SharedProjectPage;

/**
 * ShareService
 * Servicio para manejar el compartir proyectos con clientes mediante enlaces seguros
 */

import { supabase } from '../lib/supabaseClient';

export class ShareService {
    /**
     * Crear un enlace compartido para un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {Object} options - Opciones de compartir
     * @returns {Promise<Object>} - Información del enlace compartido
     */
    static async createShare(projectId, options = {}) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            if (!projectId) {
                throw new Error('ID del proyecto es requerido');
            }

            // Verificar que el proyecto existe y pertenece al usuario
            const { data: project, error: projectError } = await supabase
                .from('projects')
                .select('id, user_id')
                .eq('id', projectId)
                .single();

            if (projectError || !project) {
                throw new Error('Proyecto no encontrado');
            }

            if (project.user_id !== user.id) {
                throw new Error('No tienes permisos para compartir este proyecto');
            }

            // Generar token único
            const shareToken = this.generateToken();

            // Generar código corto opcional (verificar unicidad)
            let shareCode = null;
            if (options.includeShortCode) {
                let attempts = 0;
                let codeExists = true;
                while (codeExists && attempts < 10) {
                    shareCode = this.generateShortCode();
                    // Verificar si ya existe - usar consulta sin single() para evitar error si no existe
                    const { data: existing, error: checkError } = await supabase
                        .from('project_shares')
                        .select('id')
                        .eq('share_code', shareCode)
                        .limit(1);
                    
                    // Si hay datos, el código existe
                    codeExists = existing && existing.length > 0;
                    attempts++;
                }
                if (codeExists) {
                    // Si después de 10 intentos no encontramos uno único, no usar código corto
                    shareCode = null;
                }
            }

            // Preparar metadata
            const metadata = options.metadata || {};
            
            const shareData = {
                project_id: projectId,
                share_token: shareToken,
                share_code: shareCode,
                can_edit: options.canEdit || false,
                expires_at: options.expiresAt || null,
                password: options.password || null,
                allowed_emails: options.allowedEmails || null,
                metadata: metadata,
                created_by: user.id
            };

            const { data, error } = await supabase
                .from('project_shares')
                .insert(shareData)
                .select()
                .single();

            if (error) {
                console.error('Error al crear share:', error);
                
                // Si el error es por token duplicado (poco probable pero posible), reintentar
                if (error.code === '23505') {
                    // Reintentar con nuevo token/código
                    shareData.share_token = this.generateToken();
                    if (shareData.share_code) {
                        shareData.share_code = this.generateShortCode();
                    }
                    
                    const { data: retryData, error: retryError } = await supabase
                        .from('project_shares')
                        .insert(shareData)
                        .select()
                        .single();
                    
                    if (retryError) {
                        console.error('Error en reintento:', retryError);
                        throw new Error('Error al crear el enlace compartido. Por favor intenta de nuevo.');
                    }
                    
                    return {
                        ...retryData,
                        shareUrl: `${window.location.origin}/share/${retryData.share_token}`,
                        shortUrl: retryData.share_code ? `${window.location.origin}/s/${retryData.share_code}` : null
                    };
                }
                
                // Otros errores
                if (error.message) {
                    throw new Error(`Error al crear el enlace: ${error.message}`);
                }
                throw new Error('Error desconocido al crear el enlace compartido');
            }

            // Generar URL completa
            const baseUrl = window.location.origin;
            const shareUrl = `${baseUrl}/share/${shareToken}`;

            return {
                ...data,
                shareUrl: shareUrl,
                shortUrl: shareCode ? `${baseUrl}/s/${shareCode}` : null
            };
        } catch (error) {
            console.error('Error creating share:', error);
            throw error;
        }
    }

    /**
     * Obtener información de un enlace compartido por token
     * @param {string} token - Token del enlace compartido
     * @returns {Promise<Object>} - Información del share y proyecto
     */
    static async getShareByToken(token) {
        try {
            if (!token) {
                throw new Error('Token no proporcionado');
            }

            // Buscar por token o código corto - hacer dos consultas separadas para evitar problemas con .or()
            let data = null;

            // Primero intentar buscar por token
            const { data: tokenData, error: tokenError } = await supabase
                .from('project_shares')
                .select(`
                    *,
                    projects (
                        id,
                        name,
                        client,
                        type,
                        created_at,
                        updated_at,
                        data
                    )
                `)
                .eq('share_token', token)
                .single();

            // Si se encuentra por token, usarlo
            if (tokenData && !tokenError) {
                data = tokenData;
            } else {
                // Si no se encuentra por token, buscar por código corto
                const { data: codeData, error: codeError } = await supabase
                    .from('project_shares')
                    .select(`
                        *,
                        projects (
                            id,
                            name,
                            client,
                            type,
                            created_at,
                            updated_at,
                            data
                        )
                    `)
                    .eq('share_code', token)
                    .single();

                if (codeError && codeError.code !== 'PGRST116') { // PGRST116 = no rows found
                    throw codeError;
                }
                if (codeData) {
                    data = codeData;
                }
            }

            if (!data) {
                throw new Error('Enlace no encontrado o inválido');
            }

            // Verificar si ha expirado
            if (data.expires_at && new Date(data.expires_at) < new Date()) {
                throw new Error('Este enlace ha expirado');
            }

            // Incrementar contador de accesos
            await this.recordAccess(data.id);

            return data;
        } catch (error) {
            console.error('Error getting share:', error);
            throw error;
        }
    }

    /**
     * Verificar contraseña del enlace compartido
     * @param {string} token - Token del enlace
     * @param {string} password - Contraseña ingresada
     * @returns {Promise<boolean>} - True si la contraseña es correcta
     */
    static async verifyPassword(token, password) {
        try {
            if (!token) return false;

            // Buscar por token primero
            let data = null;
            const { data: tokenData, error: tokenError } = await supabase
                .from('project_shares')
                .select('password')
                .eq('share_token', token)
                .single();

            if (tokenData) {
                data = tokenData;
            } else {
                // Si no se encuentra por token, buscar por código corto
                const { data: codeData, error: codeError } = await supabase
                    .from('project_shares')
                    .select('password')
                    .eq('share_code', token)
                    .single();

                if (codeError && codeError.code !== 'PGRST116') {
                    return false;
                }
                data = codeData;
            }

            if (!data || !data.password) return false;

            // Comparación simple (en producción debería usar hash)
            return data.password === password;
        } catch (error) {
            console.error('Error verifying password:', error);
            return false;
        }
    }

    /**
     * Registrar acceso al enlace compartido
     * @param {string} shareId - ID del share
     */
    static async recordAccess(shareId, metadata = {}) {
        try {
            // Obtener IP y user agent
            const accessData = {
                share_id: shareId,
                ip_address: metadata.ipAddress || null,
                user_agent: metadata.userAgent || navigator.userAgent,
                metadata: metadata.extra || {}
            };

            await supabase
                .from('project_share_access')
                .insert(accessData);

            // Actualizar contador en project_shares
            // Primero obtener el valor actual
            const { data: currentShare } = await supabase
                .from('project_shares')
                .select('access_count')
                .eq('id', shareId)
                .single();

            const newCount = (currentShare?.access_count || 0) + 1;

            await supabase
                .from('project_shares')
                .update({
                    access_count: newCount,
                    last_accessed_at: new Date().toISOString()
                })
                .eq('id', shareId);
        } catch (error) {
            console.error('Error recording access:', error);
            // No lanzar error, solo registrar
        }
    }

    /**
     * Obtener todos los enlaces compartidos de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Lista de enlaces compartidos
     */
    static async getProjectShares(projectId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { data, error } = await supabase
                .from('project_shares')
                .select('*')
                .eq('project_id', projectId)
                .order('created_at', { ascending: false });

            if (error) throw error;

            // Generar URLs completas
            const baseUrl = window.location.origin;
            return data.map(share => ({
                ...share,
                shareUrl: `${baseUrl}/share/${share.share_token}`,
                shortUrl: share.share_code ? `${baseUrl}/s/${share.share_code}` : null
            }));
        } catch (error) {
            console.error('Error getting project shares:', error);
            throw error;
        }
    }

    /**
     * Obtener estadísticas de un enlace compartido
     * @param {string} shareId - ID del share
     * @returns {Promise<Object>} - Estadísticas de acceso
     */
    static async getShareStats(shareId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            // Obtener información del share
            const { data: share, error: shareError } = await supabase
                .from('project_shares')
                .select('*')
                .eq('id', shareId)
                .single();

            if (shareError) throw shareError;

            // Obtener accesos recientes
            const { data: accesses, error: accessError } = await supabase
                .from('project_share_access')
                .select('*')
                .eq('share_id', shareId)
                .order('accessed_at', { ascending: false })
                .limit(50);

            if (accessError) throw accessError;

            // Calcular estadísticas
            const stats = {
                totalAccesses: share.access_count || 0,
                recentAccesses: accesses || [],
                lastAccessed: share.last_accessed_at,
                createdAt: share.created_at,
                expiresAt: share.expires_at,
                isExpired: share.expires_at ? new Date(share.expires_at) < new Date() : false
            };

            return stats;
        } catch (error) {
            console.error('Error getting share stats:', error);
            throw error;
        }
    }

    /**
     * Eliminar un enlace compartido
     * @param {string} shareId - ID del share
     */
    static async deleteShare(shareId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { error } = await supabase
                .from('project_shares')
                .delete()
                .eq('id', shareId);

            if (error) throw error;

            return true;
        } catch (error) {
            console.error('Error deleting share:', error);
            throw error;
        }
    }

    /**
     * Actualizar configuración de un enlace compartido
     * @param {string} shareId - ID del share
     * @param {Object} updates - Campos a actualizar
     */
    static async updateShare(shareId, updates) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('Usuario no autenticado');
            }

            const { data, error } = await supabase
                .from('project_shares')
                .update(updates)
                .eq('id', shareId)
                .select()
                .single();

            if (error) throw error;

            return data;
        } catch (error) {
            console.error('Error updating share:', error);
            throw error;
        }
    }

    /**
     * Generar token único
     */
    static generateToken() {
        const array = new Uint8Array(32);
        crypto.getRandomValues(array);
        return btoa(String.fromCharCode.apply(null, array))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');
    }

    /**
     * Generar código corto único (6 caracteres)
     */
    static generateShortCode() {
        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // Sin caracteres confusos
        let code = '';
        for (let i = 0; i < 6; i++) {
            code += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return code;
    }
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, Lock, Eye, Download, ArrowLeft, Clock, User, Building2, Package, Calendar as CalendarIcon } from 'lucide-react';
import { ShareService } from '../services/ShareService';
import { PDFService } from '../services/PDFService';
import { formatCurrency } from '../utils/format';

const SharedProjectPage = () => {
    const { token } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [projectData, setProjectData] = useState(null);
    const [shareInfo, setShareInfo] = useState(null);
    const [passwordRequired, setPasswordRequired] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [error, setError] = useState(null);

    useEffect(() => {
        loadSharedProject();
    }, [token]);

    const loadSharedProject = async () => {
        try {
            setLoading(true);
            setError(null);

            const shareData = await ShareService.getShareByToken(token);

            // Verificar si requiere contraseña
            if (shareData.password) {
                // Verificar si ya se verificó (usando sessionStorage)
                const verified = sessionStorage.getItem(`share_verified_${token}`);
                if (!verified) {
                    setPasswordRequired(true);
                    setShareInfo(shareData);
                    setLoading(false);
                    return;
                }
            }

            setShareInfo(shareData);

            // Extraer datos del proyecto
            const project = shareData.projects;
            if (!project || !project.data) {
                throw new Error('Proyecto no encontrado o no disponible');
            }

            const fullProjectData = project.data;
            
            // Normalizar projectInfo para asegurar que todos los campos se carguen correctamente
            const normalizedProjectInfo = {
                project: fullProjectData.projectInfo?.project || project.name,
                client: fullProjectData.projectInfo?.client || project.client,
                type: fullProjectData.projectInfo?.type || project.type,
                taxRate: fullProjectData.projectInfo?.taxRate ?? 16, // Usar ?? para permitir 0
                currency: fullProjectData.projectInfo?.currency || 'MXN',
                date: fullProjectData.projectInfo?.date || new Date().toISOString().split('T')[0],
                location: fullProjectData.projectInfo?.location || 'México',
                ...fullProjectData.projectInfo // Preservar otros campos
            };
            
            setProjectData({
                projectInfo: normalizedProjectInfo,
                items: fullProjectData.items || [],
                scheduleData: fullProjectData.scheduleData,
                materialList: fullProjectData.materialList,
                apuData: fullProjectData.apuData
            });

        } catch (error) {
            console.error('Error loading shared project:', error);
            setError(error.message || 'No se pudo cargar el proyecto compartido');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        setPasswordError('');

        try {
            const isValid = await ShareService.verifyPassword(token, password);
            if (isValid) {
                // Guardar en sessionStorage para esta sesión
                sessionStorage.setItem(`share_verified_${token}`, 'true');
                setPasswordRequired(false);
                // Recargar con contraseña verificada
                await loadSharedProject();
            } else {
                setPasswordError('Contraseña incorrecta');
            }
        } catch (error) {
            setPasswordError('Error al verificar contraseña');
        }
    };

    const calculateTotals = () => {
        if (!projectData || !projectData.items || projectData.items.length === 0) {
            return { subtotal: 0, tax: 0, total: 0 };
        }

        const subtotal = projectData.items.reduce((sum, item) => {
            return sum + (item.quantity || 0) * (item.unitPrice || 0);
        }, 0);

        // Usar nullish coalescing para permitir taxRate = 0
        const taxRateValue = projectData.projectInfo?.taxRate ?? 16;
        const taxRate = taxRateValue / 100;
        const tax = subtotal * taxRate;
        const total = subtotal + tax;

        return { subtotal, tax, total };
    };

    const handleExportPDF = () => {
        if (!projectData) return;

        const { subtotal, tax, total } = calculateTotals();
        PDFService.exportBudget(
            projectData.projectInfo,
            projectData.items,
            total,
            subtotal,
            tax
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-4 border-emerald-500 border-t-transparent mx-auto mb-4"></div>
                    <p className="text-slate-600 font-medium">Cargando presupuesto...</p>
                </div>
            </div>
        );
    }

    if (passwordRequired) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
                    <div className="text-center mb-6">
                        <div className="bg-emerald-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <Lock className="text-emerald-600" size={32} />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 mb-2">Presupuesto Protegido</h2>
                        <p className="text-slate-600">Este presupuesto está protegido con contraseña</p>
                    </div>

                    <form onSubmit={handlePasswordSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                Contraseña
                            </label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none"
                                placeholder="Ingresa la contraseña"
                                required
                                autoFocus
                            />
                            {passwordError && (
                                <p className="text-red-600 text-sm mt-2">{passwordError}</p>
                            )}
                        </div>

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition shadow-lg shadow-emerald-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center p-4">
                <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full text-center">
                    <div className="bg-red-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                        <Lock className="text-red-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">No disponible</h2>
                    <p className="text-slate-600 mb-6">{error}</p>
                    <button
                        onClick={() => navigate('/')}
                        className="px-6 py-2 bg-slate-600 text-white rounded-lg font-medium hover:bg-slate-700 transition"
                    >
                        Ir al Inicio
                    </button>
                </div>
            </div>
        );
    }

    if (!projectData) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 flex items-center justify-center">
                <div className="text-center">
                    <p className="text-slate-600">No hay datos disponibles</p>
                </div>
            </div>
        );
    }

    const { subtotal, tax, total } = calculateTotals();
    const items = projectData.items || [];

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100">
            {/* Header */}
            <div className="bg-white border-b border-slate-200 shadow-sm">
                <div className="max-w-6xl mx-auto px-6 py-4">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold text-slate-800">
                                {projectData.projectInfo?.project || 'Presupuesto'}
                            </h1>
                            <div className="flex items-center gap-4 mt-2 text-sm text-slate-600">
                                {projectData.projectInfo?.client && (
                                    <div className="flex items-center gap-1">
                                        <User size={14} />
                                        <span>{projectData.projectInfo.client}</span>
                                    </div>
                                )}
                                {projectData.projectInfo?.type && (
                                    <div className="flex items-center gap-1">
                                        <Building2 size={14} />
                                        <span>{projectData.projectInfo.type}</span>
                                    </div>
