            return { status: 'exceeded', text: 'Límite alcanzado', icon: AlertTriangle, color: 'text-red-600' };
        }
        if (percentage >= 80) {
            return { status: 'warning', text: 'Cerca del límite', icon: AlertTriangle, color: 'text-amber-600' };
        }
        return { status: 'ok', text: 'Normal', icon: CheckCircle, color: 'text-green-600' };
    };

    const usageItems = [
        {
            key: 'budgets',
            label: 'Presupuestos',
            icon: FileText,
            description: 'Presupuestos creados este mes'
        },
        {
            key: 'aiGenerations',
            label: 'Generaciones con IA',
            icon: Bot,
            description: 'Presupuestos generados con IA'
        },
        {
            key: 'aiDescriptions',
            label: 'Descripciones con IA',
            icon: Zap,
            description: 'Descripciones generadas con IA'
        },
        {
            key: 'aiPriceSuggestions',
            label: 'Sugerencias de Precio',
            icon: TrendingUp,
            description: 'Sugerencias de precio con IA'
        },
        {
            key: 'bitacoraEntries',
            label: 'Bitácoras',
            icon: BookOpen,
            description: 'Notas de bitácora creadas'
        },
        {
            key: 'photoReports',
            label: 'Reportes Fotográficos',
            icon: Camera,
            description: 'Reportes fotográficos creados'
        },
        {
            key: 'pdfExports',
            label: 'Exportaciones PDF',
            icon: FileText,
            description: 'PDFs generados'
        },
        {
            key: 'catalogItems',
            label: 'Items en Catálogo',
            icon: Package,
            description: 'Items en tu catálogo maestro'
        }
    ];

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="text-center">
                    <div className="animate-spin h-8 w-8 border-4 border-blue-600 border-t-transparent rounded-full mx-auto mb-4"></div>
                    <p className="text-slate-600">Cargando uso...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 mb-2">Dashboard de Uso</h1>
                    <p className="text-slate-600">
                        Monitorea tu uso mensual y gestiona tus límites
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <div className={`px-4 py-2 rounded-lg font-bold ${
                        isPro 
                            ? 'bg-gradient-to-r from-purple-500 to-pink-500 text-white' 
                            : 'bg-slate-100 text-slate-700'
                    }`}>
                        {plan.name}
                    </div>
                    {!isPro && (
                        <button
                            onClick={openPricingModal}
                            className="px-4 py-2 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-700 hover:to-blue-700 text-white rounded-lg font-bold transition flex items-center gap-2"
                        >
                            <Crown size={18} />
                            Actualizar a Pro
                        </button>
                    )}
                </div>
            </div>

            {/* Plan Info Card */}
            <Card className="bg-gradient-to-r from-blue-50 to-purple-50 border-blue-200">
                <div className="flex items-center justify-between">
                    <div>
                        <h3 className="text-lg font-bold text-slate-900 mb-1">
                            Plan {plan.name}
                        </h3>
                        <p className="text-sm text-slate-600">
                            {isPro 
                                ? 'Disfruta de todas las funcionalidades sin límites'
                                : 'Límites mensuales - Se reinician cada mes'
                            }
                        </p>
                    </div>
                    <div className="text-right">
                        <div className="text-2xl font-bold text-slate-900">
                            {isPro ? 'Ilimitado' : 'Gratis'}
                        </div>
                        {!isPro && (
                            <button
                                onClick={openPricingModal}
                                className="text-sm text-blue-600 hover:text-blue-700 font-medium mt-1"
                            >
                                Ver planes →
                            </button>
                        )}
                    </div>
                </div>
            </Card>

            {/* Usage Stats Grid */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
                {usageItems.map((item) => {
                    const Icon = item.icon;
                    const limit = plan.limits[item.key];
                    const current = usage[item.key] || 0;
                    const percentage = limit === -1 ? 0 : Math.min(100, (current / limit) * 100);
                    const status = getUsageStatus(item.key);
                    const StatusIcon = status.icon;

                    return (
                        <Card key={item.key} className="hover:shadow-lg transition">
                            <div className="space-y-4">
                                {/* Header */}
                                <div className="flex items-start justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${
                                            status.status === 'exceeded' 
                                                ? 'bg-red-100' 
                                                : status.status === 'warning'
                                                ? 'bg-amber-100'
                                                : 'bg-blue-100'
                                        }`}>
                                            <Icon className={status.color} size={20} />
                                        </div>
                                        <div>
                                            <h3 className="font-bold text-slate-900">{item.label}</h3>
                                            <p className="text-xs text-slate-500">{item.description}</p>
                                        </div>
                                    </div>
                                    <StatusIcon className={status.color} size={18} />
                                </div>

                                {/* Usage Bar */}
                                {limit !== -1 && (
                                    <>
                                        <div className="space-y-2">
                                            <div className="flex justify-between text-sm">
                                                <span className="font-medium text-slate-700">
                                                    {current} / {limit}
                                                </span>
                                                <span className={`font-bold ${
                                                    percentage >= 100 
                                                        ? 'text-red-600' 
                                                        : percentage >= 80
                                                        ? 'text-amber-600'
                                                        : 'text-slate-600'
                                                }`}>
                                                    {Math.round(percentage)}%
                                                </span>
                                            </div>
                                            <div className="w-full bg-slate-200 rounded-full h-2 overflow-hidden">
                                                <div
                                                    className={`h-full rounded-full transition-all ${getUsageColor(percentage)}`}
                                                    style={{ width: `${percentage}%` }}
                                                ></div>
                                            </div>
                                        </div>
                                    </>
                                )}

                                {limit === -1 && (
                                    <div className="flex items-center gap-2 text-green-600">
                                        <CheckCircle size={16} />
                                        <span className="text-sm font-medium">Ilimitado</span>
                                    </div>
                                )}

                                {/* Status Message */}
                                {status.status === 'exceeded' && (
                                    <button
                                        onClick={openPricingModal}
                                        className="w-full py-2 bg-red-50 hover:bg-red-100 text-red-700 rounded-lg text-sm font-medium transition flex items-center justify-center gap-2"
                                    >
                                        Actualizar Plan
                                        <ArrowRight size={14} />
                                    </button>
                                )}

                                {status.status === 'warning' && (
                                    <div className="text-xs text-amber-600 bg-amber-50 p-2 rounded">
                                        ⚠️ Te quedan {limit - current} usos restantes
                                    </div>
                                )}
                            </div>
                        </Card>
                    );
                })}
            </div>

            {/* Summary */}
            <Card className="bg-slate-50">
                <div className="flex items-center justify-between">
                    <div>
                        <h3 className="font-bold text-slate-900 mb-1">Resumen del Mes</h3>
                        <p className="text-sm text-slate-600">
                            Los contadores se reinician automáticamente cada mes
                        </p>
                    </div>
                    <div className="flex items-center gap-2 text-slate-600">
                        <Calendar size={20} />
                        <span className="text-sm font-medium">
                            {new Date().toLocaleDateString('es-MX', { month: 'long', year: 'numeric' })}
                        </span>
                    </div>
                </div>
            </Card>

            {/* Upgrade CTA */}
            {!isPro && (
                <Card className="bg-gradient-to-r from-indigo-600 to-blue-600 text-white">
                    <div className="flex items-center justify-between">
                        <div>
                            <h3 className="text-xl font-bold mb-2 flex items-center gap-2">
                                <Crown size={24} />
                                Actualiza a Pro
                            </h3>
                            <p className="text-purple-100">
                                Desbloquea todas las funcionalidades sin límites por solo $299 MXN/mes
                            </p>
                        </div>
                        <button
                            onClick={openPricingModal}
                            className="px-6 py-3 bg-white text-indigo-600 rounded-xl font-bold hover:bg-indigo-50 transition flex items-center gap-2"
                        >
                            Ver Planes
                            <ArrowRight size={20} />
                        </button>
                    </div>
                </Card>
            )}
        </div>
    );
};

export default UsageDashboard;

import { supabase } from '../lib/supabaseClient';
import { systemSettingsService } from './SystemSettingsService';

/**
 * Servicio para manejar planes y límites de usuarios
 */
export class SubscriptionService {
    // Emails con acceso Pro permanente (administradores/desarrolladores)
    static PRO_EMAILS = [
        'isc20350265@gmail.com'
    ];

    // Definición de planes
    static PLANS = {
        FREE: {
            id: 'free',
            name: 'Gratis',
            price: 0,
            limits: {
                budgets: 1,              // 1 presupuesto
                aiGenerations: 3,        // 3 usos de IA
                aiDescriptions: 5,       // 5 descripciones con IA
                aiPriceSuggestions: 10,  // 10 sugerencias de precio
                bitacoraEntries: 1,      // 1 bitácora
                photoReports: 1,         // 1 reporte fotográfico
                pdfExports: 5,           // 5 exportaciones PDF
                catalogItems: 50         // 50 items en catálogo
            }
        },
        PRO: {
            id: 'pro',
            name: 'Pro',
            price: 299, // MXN por mes
            limits: {
                budgets: -1,             // Ilimitado
                aiGenerations: -1,       // Ilimitado
                aiDescriptions: -1,      // Ilimitado
                aiPriceSuggestions: -1,  // Ilimitado
                bitacoraEntries: -1,     // Ilimitado
                photoReports: -1,       // Ilimitado
                pdfExports: -1,         // Ilimitado
                catalogItems: -1         // Ilimitado
            }
        }
    };

    /**
     * Obtener datos completos de precios y planes (para el modal)
     */
    static async getPricingData() {
        // Asegurar que tenemos settings cargados
        const settings = await systemSettingsService.getAllSettings();

        return {
            pro: {
                price: parseFloat(settings.plan_pro_price),
                description: settings.plan_pro_description,
                features: settings.plan_pro_features
            },
            free: {
                price: 0,
                description: settings.plan_free_description,
                features: settings.plan_free_features
            },
            bankDetails: settings.bank_details
        };
    };

    /**
     * Obtener el plan del usuario
     */
    /**
     * Verificar si un email tiene acceso Pro permanente
     */
    static isProEmail(email) {
        if (!email) return false;
        return this.PRO_EMAILS.includes(email.toLowerCase());
    }

    static async getUserPlan(userId) {
        try {
            // Obtener configuración dinámica
            const settings = await systemSettingsService.getAllSettings();
            const proPrice = settings.plan_pro_price || this.PLANS.PRO.price;
            const proLimits = settings.plan_pro_limits || {};

            // Preparar objeto de Plan Pro Dinámico
            const dynamicProPlan = {
                ...this.PLANS.PRO,
                price: proPrice,
                limits: {
                    ...this.PLANS.PRO.limits,
                    ...proLimits
                }
            };

            // Primero verificar si el usuario tiene un email Pro
            const { data: userData } = await supabase.auth.getUser();
            if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                return dynamicProPlan;
            }

            const { data, error } = await supabase
                .from('user_subscriptions')
                .select('*')
                .eq('user_id', userId)
                .maybeSingle();

            if (error) {
                console.error('Error getting user plan:', error);
                // Si hay error pero el email es Pro, devolver Pro
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    return dynamicProPlan;
                }
                return this.PLANS.FREE;
            }

            if (!data) {
                // Usuario nuevo, verificar si es email Pro
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    return dynamicProPlan;
                }
                // Asignar plan gratuito
                await this.setUserPlan(userId, 'free');
                return this.PLANS.FREE;
            }

            // Verificar si la suscripción está activa
            if (data.plan === 'pro') {
                const now = new Date();
                const expiresAt = new Date(data.expires_at);

                if (expiresAt < now) {
                    // Verificar si es email Pro antes de degradar
                    if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                        return dynamicProPlan;
                    }
                    // Suscripción expirada, cambiar a free
                    await this.setUserPlan(userId, 'free');
                    return this.PLANS.FREE;
                }
                // Retornar Pro dinámico si coincide
                return dynamicProPlan;
            }

            return this.PLANS[data.plan.toUpperCase()] || this.PLANS.FREE;
        } catch (error) {
            console.error('Error getting user plan:', error);
            // Intentar verificar email Pro incluso en caso de error
            try {
                const { data: userData } = await supabase.auth.getUser();
                if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                    // Volver a calcular dinámico por si acaso (aunque debería estar en scope)
                    const settings = await systemSettingsService.getAllSettings();
                    return {
                        ...this.PLANS.PRO,
                        price: settings.plan_pro_price || this.PLANS.PRO.price,
                        limits: { ...this.PLANS.PRO.limits, ...(settings.plan_pro_limits || {}) }
                    };
                }
            } catch (e) {
                // Ignorar error secundario
            }
            return this.PLANS.FREE;
        }
    }

    /**
     * Establecer el plan del usuario
     */
    static async setUserPlan(userId, planId, expiresAt = null) {
        try {
            const planData = {
                user_id: userId,
                plan: planId,
                expires_at: expiresAt || (planId === 'pro' ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() : null),
                updated_at: new Date().toISOString()
            };

            const { error } = await supabase
                .from('user_subscriptions')
                .upsert(planData, { onConflict: 'user_id' });

            if (error) throw error;
            return true;
        } catch (error) {
            console.error('Error setting user plan:', error);
            return false;
        }
    }

    /**
     * Obtener el uso actual del usuario
     */
    static async getUserUsage(userId) {
        try {
            const { data, error } = await supabase
                .from('user_usage')
                .select('*')
                .eq('user_id', userId)
                .maybeSingle();

            if (error) {
                console.error('Error getting user usage:', error);
                return this.getDefaultUsage();
            }

            if (!data) {
                // Crear registro de uso inicial
                const defaultUsage = this.getDefaultUsage();
                await this.initializeUserUsage(userId);
                return defaultUsage;
            }

            // Resetear contadores mensuales si es nuevo mes
            const lastReset = new Date(data.last_reset);
            const now = new Date();
            if (now.getMonth() !== lastReset.getMonth() || now.getFullYear() !== lastReset.getFullYear()) {
                await this.resetMonthlyUsage(userId);
                return this.getDefaultUsage();
            }

            return {
                budgets_created: data.budgets_created || 0,
                ai_generations: data.ai_generations || 0,
                ai_descriptions: data.ai_descriptions || 0,
                ai_price_suggestions: data.ai_price_suggestions || 0,
                bitacora_entries: data.bitacora_entries || 0,
                photo_reports: data.photo_reports || 0,
                pdf_exports: data.pdf_exports || 0,
                catalog_items: data.catalog_items || 0
            };
        } catch (error) {
            console.error('Error getting user usage:', error);
            return this.getDefaultUsage();
        }
    }

    /**
     * Inicializar uso del usuario
     */
    static async initializeUserUsage(userId) {
        try {
            const { error } = await supabase
                .from('user_usage')
                .insert({
                    user_id: userId,
                    last_reset: new Date().toISOString()
                });

            if (error) throw error;
        } catch (error) {
            console.error('Error initializing user usage:', error);
        }
    }

    /**
     * Resetear uso mensual
     */
    static async resetMonthlyUsage(userId) {
        try {
            const { error } = await supabase
                .from('user_usage')
                .update({
                    budgets_created: 0,
                    ai_generations: 0,
                    ai_descriptions: 0,
                    ai_price_suggestions: 0,
                    bitacora_entries: 0,
                    photo_reports: 0,
                    pdf_exports: 0,
                    catalog_items: 0,
                    last_reset: new Date().toISOString()
                })
                .eq('user_id', userId);

            if (error) throw error;
        } catch (error) {
            console.error('Error resetting monthly usage:', error);
        }
    }

    /**
     * Incrementar contador de uso
     */
    static async incrementUsage(userId, type) {
        try {
            const { error } = await supabase.rpc('increment_user_usage', {
                p_user_id: userId,
                p_type: type
            });

            // Si la función RPC no existe, usar update manual
            if (error && error.message.includes('function')) {
                const usage = await this.getUserUsage(userId);
                const newValue = (usage[type] || 0) + 1;

                const { error: updateError } = await supabase
                    .from('user_usage')
                    .update({ [type]: newValue })
                    .eq('user_id', userId);

                if (updateError) throw updateError;
            } else if (error) {
                throw error;
            }
        } catch (error) {
            console.error('Error incrementing usage:', error);
        }
    }

    /**
     * Verificar si el usuario puede realizar una acción
     */
    static async canPerformAction(userId, actionType) {
        // Verificar primero si es un email Pro
        try {
            const { data: userData } = await supabase.auth.getUser();
            if (userData?.user?.email && this.isProEmail(userData.user.email)) {
                return { allowed: true, remaining: -1, limit: -1, current: 0 };
            }
        } catch (e) {
            // Continuar con verificación normal
        }

        const plan = await this.getUserPlan(userId);
        const usage = await this.getUserUsage(userId);

        const limit = plan.limits[actionType];
        const current = usage[actionType] || 0;

        // -1 significa ilimitado
        if (limit === -1) return { allowed: true, remaining: -1 };

        const remaining = limit - current;
        return {
            allowed: remaining > 0,
            remaining: Math.max(0, remaining),
            limit,
            current
        };
    }

    /**
     * Obtener uso por defecto
     */
    static getDefaultUsage() {
        return {
            budgets_created: 0,
            ai_generations: 0,
            ai_descriptions: 0,
            ai_price_suggestions: 0,
            bitacora_entries: 0,
            photo_reports: 0,
            pdf_exports: 0,
            catalog_items: 0
        };
    }

    /**
     * Obtener mensaje de límite alcanzado
     */
    static getLimitMessage(actionType, plan) {
        const messages = {
            budgets: 'Has alcanzado el límite de presupuestos. ¡Actualiza a Pro para crear ilimitados!',
            aiGenerations: 'Has alcanzado el límite de generaciones con IA. ¡Actualiza a Pro para uso ilimitado!',
            aiDescriptions: 'Has alcanzado el límite de descripciones con IA. ¡Actualiza a Pro para uso ilimitado!',
            aiPriceSuggestions: 'Has alcanzado el límite de sugerencias de precio. ¡Actualiza a Pro para uso ilimitado!',
            bitacoraEntries: 'Has alcanzado el límite de bitácoras. ¡Actualiza a Pro para crear ilimitadas!',
            photoReports: 'Has alcanzado el límite de reportes fotográficos. ¡Actualiza a Pro para crear ilimitados!',
            pdfExports: 'Has alcanzado el límite de exportaciones PDF. ¡Actualiza a Pro para exportaciones ilimitadas!',
            catalogItems: 'Has alcanzado el límite de items en catálogo. ¡Actualiza a Pro para catálogo ilimitado!'
        };

        return messages[actionType] || 'Has alcanzado el límite de esta funcionalidad. ¡Actualiza a Pro!';
    }
}

/**
 * AIBudgetService
 * Centralized service for AI-powered budget generation and analysis
 * Uses BackendAIService to keep API keys secure
 */

import { BackendAIService } from './BackendAIService';
import { ErrorService } from './ErrorService';
import { MarketPriceService } from './MarketPriceService';
import { APUService } from './APUService';
import { getCurrentYear, getCurrentYearRange } from '../utils/helpers';
import { generateId } from '../utils/helpers';

export class AIBudgetService {
    /**
     * Generate budget items from natural language description
     * @param {string} prompt - User's natural language description
     * @param {Object} projectInfo - Project information
     * @param {Array} catalog - Catalog items for context
     * @param {Object} config - Optional configuration (prices, location override)
     * @returns {Promise<Array>} - Generated budget items
     */
    static async generateBudgetFromPrompt(prompt, projectInfo, catalog = [], config = {}) {
        if (!prompt || !prompt.trim()) {
            throw new Error('El prompt no puede estar vacío');
        }

        try {
            // Smart Context: Filter catalog to most relevant items instead of just slicing
            const relevantCatalog = this.filterCatalogByRelevance(catalog, prompt, 30);

            const catalogContext = JSON.stringify(
                relevantCatalog.map(c => ({
                    d: c.description,
                    u: c.unit,
                    p: c.unitPrice,
                    c: c.category
                }))
            );

            const location = config.location || projectInfo.location || 'México';
            const catalogCount = relevantCatalog.length;
            const catalogInfo = catalogCount > 0
                ? `\n\nCATÁLOGO MAESTRO DISPONIBLE (${catalogCount} partidas más relevantes):\n${catalogContext}\n\nIMPORTANTE: Si encuentras coincidencias en el catálogo, DEBES usar los datos exactos (descripción, unidad, precio, categoría) y marcar "isCatalogItem": true.`
                : '\n\nNOTA: No hay catálogo disponible. Genera precios basados en estándares de la industria.';

            // Dynamic Price Injection - Cargar precios del Tabulador Oficial CDMX y otras fuentes
            let basePrices = config.basePrices;
            let officialPrices = {};

            if (!basePrices) {
                // Obtener precios del Tabulador Oficial CDMX (PRIORIDAD MÁXIMA)
                const categories = ['Materiales', 'Mano de Obra', 'Obra Civil', 'Instalaciones', 'Equipos'];
                const referencePricesByCategory = {};
                const officialPricesByCategory = {};

                // Cargar TODAS las categorías siempre (el tabulador CDMX tiene miles de conceptos)
                const categoriesToSearch = categories;

                for (const cat of categoriesToSearch) {
                    // PRIORIDAD 1: Buscar precios oficiales del Tabulador CDMX (AUMENTAR a 50 para más opciones)
                    // También buscar precios relevantes según el prompt del usuario
                    let officialRefPrices = await MarketPriceService.getPricesByCategory(cat, location, 50);

                    // Si el prompt menciona conceptos específicos, buscar precios relevantes
                    const promptTerms = prompt.toLowerCase().split(/\s+/).filter(t => t.length > 4);
                    if (promptTerms.length > 0) {
                        // Buscar precios específicos basados en términos del prompt
                        const relevantPrices = await Promise.all(
                            promptTerms.slice(0, 3).map(term =>
                                MarketPriceService.findReferencePrice(term, cat, location, 5)
                            )
                        );
                        const flatRelevant = relevantPrices.flat();
                        // Combinar con los precios generales, priorizando los relevantes
                        const relevantOfficial = flatRelevant.filter(p => p.source === 'cdmx_tabulador');
                        officialRefPrices = [...relevantOfficial, ...officialRefPrices].slice(0, 50);
                    }

                    // Separar precios oficiales de otros
                    const official = officialRefPrices.filter(p => p.source === 'cdmx_tabulador');
                    const others = officialRefPrices.filter(p => p.source !== 'cdmx_tabulador');

                    if (official.length > 0) {
                        officialPricesByCategory[cat] = official.slice(0, 30).map(p => ({
                            description: p.description,
                            unit: p.unit,
                            basePrice: parseFloat(p.base_price),
                            priceRange: p.price_range,
                            source: 'Tabulador Oficial CDMX',
                            official: true
                        }));
                    }

