            console.log(`   - ${replacedMaterialsCount} material(es) reemplazado(s) con valores EXACTOS de Base Maestra`);
            console.log(`   - ${replacedLaborCount} concepto(s) de mano de obra reemplazado(s) con valores EXACTOS`);
            console.log(`   - ${realDataItems}/${totalItems} componentes basados en datos reales (${realDataPercentage}%)`);

            // VALIDACIONES DE COHERENCIA DEL APU - DETECCIÓN DE ERRORES CRÍTICOS
            const validationWarnings = [];
            const validationErrors = [];
            const itemQuantity = item.quantity || 1;
            const itemUnit = item.unit ? item.unit.toLowerCase().replace(/\./g, '').trim() : '';

            // Validar cantidades de materiales típicos
            if (apuData.materials && Array.isArray(apuData.materials)) {
                const concrete = apuData.materials.find(m => m.description?.toLowerCase().includes('concreto'));
                const steel = apuData.materials.filter(m => m.description?.toLowerCase().includes('acero') || m.description?.toLowerCase().includes('varilla'));
                const wood = apuData.materials.find(m => m.description?.toLowerCase().includes('madera') || m.description?.toLowerCase().includes('pino'));

                // Validar concreto: SOLO si el item es m3
                if (concrete && concrete.unit === 'm3') {
                    if (itemUnit === 'm3') {
                        // Para 1 m3 de item, esperamos ~1.0-1.1 m3 de concreto
                        if (concrete.quantity < 0.9 || concrete.quantity > 1.2) {
                            if (Math.abs(concrete.quantity - itemQuantity) < 0.2 && itemQuantity !== 1) {
                                validationErrors.push(`❌ ERROR CRÍTICO: Cantidad de concreto (${concrete.quantity} m3) es igual a la cantidad del proyecto (${itemQuantity} m3). El APU está calculando para ${itemQuantity} m3 en lugar de 1 m3.`);
                            } else {
                                validationWarnings.push(`⚠️ Cantidad de concreto (${concrete.quantity} m3) parece incorrecta para 1 m3 de elemento.`);
                            }
                        }
                    } else if (['ml', 'm', 'metro'].includes(itemUnit)) {
                        // Para elementos lineales, la cantidad debe ser pequeña (ej. 0.03 m3/ml)
                        if (concrete.quantity > 0.5) {
                            validationWarnings.push(`⚠️ Cantidad de concreto (${concrete.quantity} m3) parece muy alta para 1 ml de elemento.`);
                        }
                    }
                }

                // Validar acero: SOLO si el item es m3 (para kg/m3)
                const totalSteel = steel.reduce((sum, s) => sum + (s.quantity || 0), 0);
                if (totalSteel > 0) {
                    if (itemUnit === 'm3') {
                        const expectedSteelPerM3 = 60; // kg/m3 típico
                        const expectedSteelForProject = expectedSteelPerM3 * itemQuantity;
                        if (Math.abs(totalSteel - expectedSteelForProject) < Math.abs(totalSteel - expectedSteelPerM3) && itemQuantity !== 1) {
                            validationErrors.push(`❌ ERROR CRÍTICO: Cantidad de acero (${totalSteel.toFixed(2)} kg) parece calculada para ${itemQuantity} m3.`);
                        } else if (totalSteel > 150) {
                            validationWarnings.push(`⚠️ Cantidad de acero (${totalSteel.toFixed(2)} kg) es MUY ALTA para 1 m3.`);
                        }
                    }
                    // Para ml, no validamos rango estricto porque depende de la sección
                }

                // Validar madera: SOLO si el item es m3
                if (wood && (wood.unit === 'p.t.' || wood.unit === 'pt') && itemUnit === 'm3') {
                    const expectedWoodPerM3 = 1.0;
                    const expectedWoodForProject = expectedWoodPerM3 * itemQuantity;
                    if (Math.abs(wood.quantity - expectedWoodForProject) < Math.abs(wood.quantity - expectedWoodPerM3) && itemQuantity !== 1) {
                        validationErrors.push(`❌ ERROR CRÍTICO: Cantidad de madera parece calculada para el total del proyecto.`);
                    }
                }
            }

            // Validar mano de obra
            if (apuData.labor && Array.isArray(apuData.labor)) {
                const totalLabor = apuData.labor.reduce((sum, l) => sum + (l.quantity || 0), 0);
                if (itemUnit === 'm3' && item.description?.toLowerCase().includes('colado')) {
                    const expectedLaborPerM3 = 0.25;
                    const expectedLaborForProject = expectedLaborPerM3 * itemQuantity;
                    if (Math.abs(totalLabor - expectedLaborForProject) < Math.abs(totalLabor - expectedLaborPerM3) && itemQuantity !== 1) {
                        validationErrors.push(`❌ ERROR CRÍTICO: Mano de obra (${totalLabor.toFixed(2)} jor) parece calculada para ${itemQuantity} m3.`);
                    }
                }
            }

            // Mostrar errores críticos primero
            if (validationErrors.length > 0) {
                console.error('❌ ERRORES CRÍTICOS EN EL APU:');
                validationErrors.forEach(error => console.error(`   ${error}`));
                console.error(`   🔴 El APU está calculando para ${itemQuantity} ${item.unit || 'unidades'} en lugar de 1 ${item.unit || 'unidad'}.`);
                console.error(`   🔴 REGENERA el APU y verifica que el prompt indique claramente calcular para 1 unidad.`);
            }

            if (validationWarnings.length > 0) {
                console.warn('🔍 VALIDACIONES DE COHERENCIA DEL APU:');
                validationWarnings.forEach(warning => console.warn(`   ${warning}`));
            }

            // Validar y reportar precio unitario final
            let finalPrice = APUService.calculateFinalPrice(apuData);
            const currentPrice = item.unitPrice || 0;
            const quantity = item.quantity || 1;

            // CORRECCIÓN AUTOMÁTICA: Si detectamos que está calculando para la cantidad total, corregir
            let wasCorrected = false;
            if (currentPrice > 0 && quantity !== 1) {
                const priceRatio = finalPrice / currentPrice;
                const totalProjectPrice = currentPrice * quantity;

                // Si el precio del APU es similar al precio total del proyecto, está mal calculado
                const isCalculatingForTotal = Math.abs(finalPrice - totalProjectPrice) < Math.abs(finalPrice - currentPrice);

                // Si el ratio es similar a la cantidad, está calculando para la cantidad total
                const isPriceProportionalToQuantity = Math.abs(priceRatio - quantity) < 0.3;

                // Si la diferencia es >500% y el precio es proporcional a la cantidad, corregir automáticamente
                const priceDiffPercent = (Math.abs(finalPrice - currentPrice) / currentPrice) * 100;
                if ((isCalculatingForTotal || isPriceProportionalToQuantity) && priceDiffPercent > 200) {
                    console.warn(`   ⚠️ CORRECCIÓN AUTOMÁTICA: El APU parece estar calculando para ${quantity} ${item.unit || 'unidades'}.`);
                    console.warn(`   ⚠️ Precio detectado: $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })}`);
                    console.warn(`   ⚠️ Dividiendo por ${quantity} para obtener el precio por 1 ${item.unit || 'unidad'}...`);

                    // Dividir todas las cantidades del APU por la cantidad del proyecto
                    if (apuData.materials && Array.isArray(apuData.materials)) {
                        apuData.materials = apuData.materials.map(mat => ({
                            ...mat,
                            quantity: (mat.quantity || 0) / quantity
                        }));
                    }
                    if (apuData.labor && Array.isArray(apuData.labor)) {
                        apuData.labor = apuData.labor.map(lab => ({
                            ...lab,
                            quantity: (lab.quantity || 0) / quantity
                        }));
                    }
                    if (apuData.equipment && Array.isArray(apuData.equipment)) {
                        apuData.equipment = apuData.equipment.map(eq => ({
                            ...eq,
                            quantity: (eq.quantity || 0) / quantity
                        }));
                    }

                    // Recalcular el precio final
                    finalPrice = APUService.calculateFinalPrice(apuData);
                    wasCorrected = true;

                    console.warn(`   ✅ Precio corregido: $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })} por 1 ${item.unit || 'unidad'}`);
                }
            }

            console.log(`💰 PRECIO UNITARIO FINAL DEL APU: $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })} por ${item.unit || 'unidad'}`);
            if (wasCorrected) {
                console.log(`   ✅ Este precio fue CORREGIDO automáticamente (el APU estaba calculando para ${quantity} ${item.unit || 'unidades'})`);
                // Actualizar las notas para reflejar la corrección
                apuData.notes = `${apuData.notes || ''} | ⚠️ CORRECCIÓN AUTOMÁTICA: Las cantidades originales parecían estar calculadas para el total del proyecto (${quantity} ${item.unit}). Se han dividido por ${quantity} para obtener el unitario.`.trim();
            } else {
                console.log(`   ⚠️ Este es el precio por 1 ${item.unit || 'unidad'} del concepto "${item.description}"`);
                console.log(`   ⚠️ NO multipliques este precio por la cantidad del proyecto (${quantity} ${item.unit || 'unidades'})`);
            }

            if (currentPrice > 0) {
                const priceDiff = Math.abs(finalPrice - currentPrice);
                const priceDiffPercent = (priceDiff / currentPrice) * 100;
                const totalProjectPrice = currentPrice * quantity;

                console.log(`   📊 Precio actual del item: $${currentPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })} por ${item.unit || 'unidad'}`);
                console.log(`   📊 Diferencia: $${priceDiff.toLocaleString('es-MX', { minimumFractionDigits: 2 })} (${priceDiffPercent.toFixed(1)}%)`);

                if (!wasCorrected) {
                    const priceRatio = finalPrice / currentPrice;
                    const isPriceProportionalToQuantity = quantity !== 1 && Math.abs(priceRatio - quantity) < 0.3;

                    if (isPriceProportionalToQuantity && quantity !== 1) {
                        console.error(`   ❌❌❌ ERROR CRÍTICO DETECTADO ❌❌❌`);
                        console.error(`   ❌ El APU está calculando para ${quantity} ${item.unit || 'unidades'} en lugar de 1 ${item.unit || 'unidad'}.`);
                        console.error(`   ❌ Precio del APU: $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })}`);
                        console.error(`   ❌ Precio esperado para 1 ${item.unit || 'unidad'}: ~$${currentPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })}`);
                        console.error(`   ❌ El APU generó un precio ${priceRatio.toFixed(2)}x mayor, lo cual coincide con la cantidad del proyecto (${quantity}).`);
                        console.error(`   🔴 NO APLIQUES ESTE PRECIO. REGENERA el APU.`);
                    } else if (priceDiffPercent > 500) {
                        console.error(`   ❌ ERROR: El precio del APU ($${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })}) es ${priceDiffPercent.toFixed(1)}% mayor que el precio actual.`);
                        console.error(`   ❌ Esto es EXTREMADAMENTE sospechoso. Verifica que el APU esté calculando para 1 ${item.unit || 'unidad'} y no para ${quantity} ${item.unit || 'unidades'}.`);
                    } else if (priceDiffPercent > 200) {
                        console.warn(`   ⚠️ ADVERTENCIA: El precio del APU ($${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })}) difiere significativamente del precio actual (${priceDiffPercent.toFixed(1)}% de diferencia).`);
                        console.warn(`   ⚠️ Esto puede ser normal si el precio actual es una estimación. El APU calcula el precio real basado en materiales, mano de obra y equipos.`);
                    } else if (priceDiffPercent > 50 && priceDiffPercent <= 200) {
                        console.log(`   ℹ️ El precio del APU difiere del precio actual en ${priceDiffPercent.toFixed(1)}%. Esto puede ser normal.`);
                    }
                }
            }

            console.log(`   💡 Precio total del concepto en el proyecto: $${(finalPrice * quantity).toLocaleString('es-MX', { minimumFractionDigits: 2 })} (${quantity} ${item.unit || 'unidades'} × $${finalPrice.toLocaleString('es-MX', { minimumFractionDigits: 2 })} por ${item.unit || 'unidad'})`);

            return apuData;

        } catch (error) {
            console.error('Error generating APU:', error);
            throw error;
        }
    }

    /**
     * Calculates volume/quantity from a natural language description.
     * @param {string} description - The user's description (e.g., "Muro de 5x3").
     * @param {string} unit - The target unit (e.g., "m2").
     * @returns {Promise<{formula: string, explanation: string, result: number}>}
     */
    static async calculateVolume(description, unit) {
        const prompt = `
            Act as a quantity surveyor (Generador de Obra).
            Calculate the quantity/volume based on the following description and unit.
            
            Description: "${description}"
            Target Unit: "${unit}"

            Return a JSON object with:
            - "formula": The mathematical formula used (e.g., "5 * 3").
            - "explanation": A brief explanation of the calculation.
            - "result": The numeric result.
        `;

        try {
            const result = await BackendAIService.sendPrompt(prompt);
            const text = result.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
            const cleanJson = this.cleanJson(text);
            return JSON.parse(cleanJson);
        } catch (error) {
            console.error('Error calculating volume:', error);
            return { formula: '', explanation: 'Error calculating', result: 0 };
        }
    }

    /**
     * Generate professional descriptions for budget items (Ported from GeminiService)
     * @param {Object} itemData - Item information (code, unit, category)
     * @param {Array} context - Other items in budget for context
     * @returns {Promise<Array<string>>} - Array of 2-3 description suggestions
     */
    static async generateDescription(itemData, context = []) {
        const { code, unit, category, partialDescription } = itemData;

        // Build prompt
        const contextInfo = context.length > 0
            ? `\n\nContexto del presupuesto:\n${context.slice(0, 5).map(item => `- ${item.description} (${item.unit})`).join('\n')}`
            : '';

        const prompt = `Eres un experto en presupuestos de construcción en México. \nGenera 3 descripciones profesionales y técnicas para una partida de presupuesto con las siguientes características:\n\n- Código/Clave: ${code || 'No especificado'}\n- Unidad: ${unit || 'No especificada'}\n- Categoría: ${category || 'General'}\n${partialDescription ? `- Descripción parcial: ${partialDescription}` : ''}\n${contextInfo}\n\nRequisitos:\n1. Descripciones técnicas y profesionales\n2. Incluir especificaciones relevantes\n3. Usar terminología de construcción mexicana\n4. Máximo 100 caracteres cada una\n5. Diferentes niveles de detalle (básica, media, detallada)\n\nResponde SOLO con las 3 descripciones separadas por saltos de línea, sin numeración ni texto adicional.`;

        try {
            const result = await BackendAIService.sendPrompt(prompt);
            const text = result.candidates?.[0]?.content?.parts?.[0]?.text || '';
            const descriptions = text.split('\n').filter(l => l.trim().length > 0).slice(0, 3);
            return descriptions.length > 0 ? descriptions : [
                'Suministro y colocación de material',
                'Mano de obra y materiales incluidos',
                'Partida de construcción'
            ];
        } catch (error) {
            console.error('Error generating description:', error);
            throw error;
        }
    }

    /**
     * Suggest price range based on catalog and context (Ported from GeminiService)
     * @param {Object} itemData - Item information
     * @param {Array} catalogData - Catalog items for reference
     * @returns {Promise<Object>} - Price suggestion with range
     */
    static async suggestPrice(itemData, catalogData = [], location = 'México') {
        const { description, unit, category } = itemData;

        // PRIORIDAD 1: Buscar en catálogo del usuario
        const similarItems = this.filterCatalogByRelevance(catalogData, description, 10);

        // PRIORIDAD 2: Buscar en Tabulador Oficial CDMX y otras fuentes de mercado
        let marketPrices = [];
        try {
            marketPrices = await MarketPriceService.findReferencePrice(description, category || 'Materiales', location, 10);
        } catch (error) {
            console.error('Error fetching market prices for suggestion:', error);
        }

        // Priorizar precios oficiales del tabulador CDMX
        const officialPrices = marketPrices.filter(p => p.source === 'cdmx_tabulador').map(p => parseFloat(p.base_price));
        const otherMarketPrices = marketPrices.filter(p => p.source !== 'cdmx_tabulador').map(p => parseFloat(p.base_price));

        // Combinar fuentes: catálogo primero, luego oficiales, luego otros
        const catalogPrices = similarItems
            .map(item => item.unitPrice || item.price || 0)
            .filter(p => p > 0);

        const allPrices = [...catalogPrices, ...officialPrices, ...otherMarketPrices].filter(p => p > 0);

        if (allPrices.length === 0) {
            return {
                suggested: null,
                min: null,
                max: null,
                confidence: 'low',
                message: 'No hay datos suficientes para sugerir un precio',
                source: 'none'
            };
        }

        // Calcular estadísticas, dando más peso a precios oficiales
        const avg = allPrices.reduce((a, b) => a + b, 0) / allPrices.length;
        const min = Math.min(...allPrices);
        const max = Math.max(...allPrices);

        // Si hay precios oficiales, priorizar el promedio de esos
        const suggestedPrice = officialPrices.length > 0
            ? officialPrices.reduce((a, b) => a + b, 0) / officialPrices.length
            : catalogPrices.length > 0
                ? catalogPrices.reduce((a, b) => a + b, 0) / catalogPrices.length
                : avg;

        const priceSources = [];
        if (catalogPrices.length > 0) priceSources.push(`${catalogPrices.length} del catálogo del usuario`);
        if (officialPrices.length > 0) priceSources.push(`${officialPrices.length} del Tabulador Oficial CDMX`);
        if (otherMarketPrices.length > 0) priceSources.push(`${otherMarketPrices.length} de otras fuentes`);

        let promptText = `Eres un experto en costos de construcción en México.\n\n`;

        if (priceSources.length > 0) {
            promptText += `Fuentes de precios disponibles:\n${priceSources.join('\n')}\n\n`;
        }

        if (officialPrices.length > 0) {
            promptText += `⭐ PRECIOS OFICIALES DEL TABULADOR CDMX:\n${officialPrices.map(p => `- $${p.toFixed(2)}`).join('\n')}\n\n`;
        }

        if (catalogPrices.length > 0) {
            promptText += `Precios del catálogo del usuario:\n${catalogPrices.slice(0, 5).map(p => `- $${p.toFixed(2)}`).join('\n')}\n\n`;
        }

        promptText += `Sugiere un precio razonable para:\n- Descripción: ${description}\n- Unidad: ${unit}\n- Categoría: ${category || 'General'}\n- Ubicación: ${location}\n\n`;
        promptText += `Estadísticas disponibles:\n- Precio promedio general: $${avg.toFixed(2)}\n- Rango: $${min.toFixed(2)} - $${max.toFixed(2)}\n`;

        if (officialPrices.length > 0) {
            const officialAvg = officialPrices.reduce((a, b) => a + b, 0) / officialPrices.length;
            promptText += `- Precio promedio del Tabulador Oficial CDMX: $${officialAvg.toFixed(2)}\n`;
            promptText += `\nIMPORTANTE: Si hay precios del Tabulador Oficial CDMX, prioriza esos (son oficiales y actualizados).\n`;
        }

        promptText += `\nResponde SOLO con un número (el precio sugerido en pesos mexicanos), sin símbolos ni texto adicional.`;

        try {
            const result = await BackendAIService.sendPrompt(promptText);
            const text = result.candidates?.[0]?.content?.parts?.[0]?.text || '';
            const aiSuggestedPrice = parseFloat(text.replace(/[^0-9.]/g, ''));

            const finalPrice = !isNaN(aiSuggestedPrice) && aiSuggestedPrice > 0 ? aiSuggestedPrice : suggestedPrice;

            return {
                suggested: finalPrice,
                min: min * 0.9,
                max: max * 1.1,
                confidence: officialPrices.length > 0 ? 'high' : catalogPrices.length >= 5 ? 'high' : catalogPrices.length >= 2 ? 'medium' : 'low',
                similarCount: similarItems.length + marketPrices.length,
                source: officialPrices.length > 0 ? 'cdmx_tabulador' : catalogPrices.length > 0 ? 'catalog' : 'market',
                officialPricesCount: officialPrices.length
            };
        } catch (error) {
            console.error('Error suggesting price:', error);
            return {
                suggested: suggestedPrice,
                min: min * 0.9,
                max: max * 1.1,
                confidence: officialPrices.length > 0 ? 'high' : 'medium',
                similarCount: similarItems.length + marketPrices.length,
                source: officialPrices.length > 0 ? 'cdmx_tabulador' : catalogPrices.length > 0 ? 'catalog' : 'market',
                officialPricesCount: officialPrices.length
            };
        }
    }

    /**
     * Helper to clean JSON string
     * @param {string} text 
     * @returns {string}
     */
    static cleanJson(text) {
        return text
            .replace(/```json/g, '')
            .replace(/```/g, '')
            .trim();
    }
}

/**
 * APUService
 * Servicio dedicado para Análisis de Precios Unitarios (APU)
 * Maneja cálculos, validaciones y transformaciones de datos APU
 * 
 * Estándar: NEODATA/OPUS
 */

import { MarketPriceService } from './MarketPriceService';

export class APUService {
    // Valores por defecto según estándar mexicano
    static DEFAULT_CONFIG = {
        minorToolsPct: 0.03,      // 3% de herramienta menor sobre mano de obra
        indirectsPct: 0.16,        // 16% indirectos sobre costo directo
        financingPct: 0.01,       // 1% financiamiento
        profitPct: 0.10,          // 10% utilidad
        additionalPct: 0.005,      // 0.5% cargos adicionales
        defaultFSR: 1.75          // Factor de Salario Real por defecto
    };

    // Lógica de ingeniería por especialidad (Nivel Neodata)
    static SPECIALTY_LOGIC = {
        'ELECTRICA_BAJA_TENSION': {
            consumablesPct: 0.05, // 5% para "Material Menor" (pijas, cinta, conectores)
            safetyGearPct: 0.02,  // Equipo de seguridad dieléctrico
            recommendedUnits: ['salida', 'ml', 'pza']
        },
        'ELECTRICA_MEDIA_TENSION': {
            heavyEquipment: true, // Requiere grúas o canastillas
            specializedLabor: 'Cuadrilla de Linieros',
            testingPct: 0.03      // Pruebas de megger/continuidad
        },
        'JARDINERIA_PAISAJISMO': {
            shrinkagePct: 0.10,   // 10% merma en plantas/pasto (se secan)
            waterConsumption: true,
            laborType: 'Jornaleros Paisajistas'
        },
        'ALBAÑILERIA': {
            minorToolsPct: 0.05, // Mayor desgaste de herramienta
            cleanupPct: 0.02     // Limpieza constante
        }
    };

    /**
     * Enriquece el APU con lógica de ingeniería según la especialidad
     * Inyecta componentes "fantasma" que Neodata siempre incluye
     * @param {Object} apuData - Datos base del APU
     * @param {string} specialty - Especialidad (ej: 'electrica', 'jardineria')
     * @returns {Object} - APU enriquecido con items automáticos
     */
    static enrichWithEngineeringLogic(apuData, specialty) {
        if (!specialty) return apuData;

        const normalizedSpecialty = specialty.toUpperCase();
        let logic = {};

        // Detectar lógica a aplicar
        if (normalizedSpecialty.includes('ELECTRICA') || normalizedSpecialty.includes('ELECTRIC')) {
            logic = this.SPECIALTY_LOGIC['ELECTRICA_BAJA_TENSION'];
        } else if (normalizedSpecialty.includes('JARDIN')) {
            logic = this.SPECIALTY_LOGIC['JARDINERIA_PAISAJISMO'];
        } else if (normalizedSpecialty.includes('ALBAÑIL') || normalizedSpecialty.includes('CIVIL')) {
            logic = this.SPECIALTY_LOGIC['ALBAÑILERIA'];
        }

        const enriched = JSON.parse(JSON.stringify(apuData));
        enriched.materials = enriched.materials || [];

        // Lógica: Material Menor (Consumibles)
        if (logic.consumablesPct) {
            const matTotal = this.calculateMaterialsTotal(enriched.materials);
            if (matTotal > 0) {
                // Verificar si ya existe para no duplicar
                const hasConsumables = enriched.materials.some(m => m.description.includes('Material menor') || m.description.includes('Consumibles'));
                if (!hasConsumables) {
                    enriched.materials.push({
                        description: "Material menor (Cinta aislante, conectores, tornillería, etc.)",
                        unit: "%",
                        quantity: 1,
                        unitPrice: matTotal * logic.consumablesPct,
                        isGenerated: true
                    });
                }
            }
        }

        // Lógica: Merma por ser vivos (Jardinería)
        if (logic.shrinkagePct) {
            const matTotal = this.calculateMaterialsTotal(enriched.materials);
            if (matTotal > 0) {
                enriched.materials.push({
                    description: "Merma y reposición de material vegetal (Garantía)",
                    unit: "%",
                    quantity: 1,
                    unitPrice: matTotal * logic.shrinkagePct,
                    isGenerated: true
                });
            }
        }

        // Lógica: Limpieza fina (Albañilería)
        if (logic.cleanupPct) {
            const directCost = this.calculateDirectCost(enriched);
            if (directCost > 0) {
                enriched.materials.push({
                    description: "Limpieza fina de obra y retiro de escombro fuera de la zona",
                    unit: "lote",
                    quantity: 1,
                    unitPrice: directCost * logic.cleanupPct,
                    isGenerated: true
                });
            }
        }

        return enriched;
    }

    /**
     * Enforces official prices from the Master Catalog if a match is found.
     * @param {Object} apuData - The APU data to process.
     * @param {string} location - The location for price lookup.
     * @returns {Promise<{apuData: Object, stats: Object}>} - The updated APU data and statistics.
     */
    static async enforceMasterCatalogPrices(apuData, location) {
        let replacedMaterialsCount = 0;
        let materialsWithRealData = 0;
        let replacedLaborCount = 0;
        let laborWithRealData = 0;

        const normalizeUnit = (u) => {
            if (!u) return '';
            const unit = u.toLowerCase().replace(/\./g, '').trim();
            const map = {
                'jor': 'jor', 'jornal': 'jor', 'dia': 'jor', 'dias': 'jor',
                'hr': 'h', 'hora': 'h', 'horas': 'h', 'h': 'h'
            };
            return map[unit] || unit;
        };

        const processedAPU = JSON.parse(JSON.stringify(apuData));

        // Process Materials
        if (processedAPU.materials && Array.isArray(processedAPU.materials)) {
            const updatedMaterials = await Promise.all(processedAPU.materials.map(async (mat) => {
                try {
                    const validPrices = await MarketPriceService.findReferencePrice(
                        mat.description,
                        'Materiales',
                        location,
                        5
                    );

                    if (validPrices && validPrices.length > 0) {
                        const matUnit = normalizeUnit(mat.unit);
                        const exactMatch = validPrices.find(p => normalizeUnit(p.unit) === matUnit);

                        if (exactMatch) {
                            const exactPrice = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactPrice) && exactPrice > 0) {
                                replacedMaterialsCount++;
                                materialsWithRealData++;
                                return {
                                    ...mat,
                                    unitPrice: exactPrice,
                                    total: (mat.quantity || 0) * exactPrice,
                                    source: 'Base Maestra Neodata',
                                    sourceDetail: exactMatch.source || 'Base Maestra'
                                };
                            }
                        }
                    }
                    return mat;
                } catch (error) {
                    console.warn(`Error finding price for material ${mat.description}:`, error);
                    return mat;
                }
            }));
            processedAPU.materials = updatedMaterials;
        }

        // Process Labor
        if (processedAPU.labor && Array.isArray(processedAPU.labor)) {
            const updatedLabor = await Promise.all(processedAPU.labor.map(async (lab) => {
                try {
                    const exactPrices = await MarketPriceService.findReferencePrice(
                        lab.description,
                        'Mano de Obra',
                        location,
                        3
                    );

                    if (exactPrices && exactPrices.length > 0) {
                        const labUnit = normalizeUnit(lab.unit);
                        const exactMatch = exactPrices.find(p => normalizeUnit(p.unit) === labUnit);

                        if (exactMatch) {
                            const exactSalary = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactSalary) && exactSalary > 0) {
                                const fsr = lab.fsr || 1.75;
                                const unitPrice = exactSalary * fsr;
                                replacedLaborCount++;
                                laborWithRealData++;
                                return {
                                    ...lab,
                                    baseSalary: exactSalary,
                                    unitPrice: unitPrice,
                                    total: (lab.quantity || 0) * unitPrice,
                                    source: 'Base Maestra Neodata',
                                    sourceDetail: exactMatch.source || 'Base Maestra',
                                    notes: `${lab.notes || ''} | Salario base: Base Maestra Neodata`.trim()
                                };
                            }
                        }
                    }
                    return lab;
                } catch (error) {
                    console.warn(`Error finding salary for labor ${lab.description}:`, error);
                    return lab;
                }
            }));
            processedAPU.labor = updatedLabor;
        }

        // Process Equipment
        if (processedAPU.equipment && Array.isArray(processedAPU.equipment)) {
            const updatedEquipment = await Promise.all(processedAPU.equipment.map(async (eq) => {
                try {
                    const exactPrices = await MarketPriceService.findReferencePrice(
                        eq.description,
                        'Equipos',
                        location,
                        1
                    );

                    if (exactPrices && exactPrices.length > 0) {
                        const eqUnit = normalizeUnit(eq.unit);
                        const exactMatch = exactPrices.find(p => normalizeUnit(p.unit) === eqUnit);

                        if (exactMatch) {
                            const exactPrice = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactPrice) && exactPrice > 0) {
                                return {
                                    ...eq,
                                    unitPrice: exactPrice,
                                    total: (eq.quantity || 0) * exactPrice,
                                    source: 'Base Maestra Neodata'
                                };
                            }
                        }
                    }
                    return eq;
                } catch (error) {
                    console.warn(`Error finding price for equipment ${eq.description}:`, error);
                    return eq;
                }
            }));
            processedAPU.equipment = updatedEquipment;
        }

        return {
            apuData: processedAPU,
            stats: {
                replacedMaterialsCount,
                materialsWithRealData,
                replacedLaborCount,
                laborWithRealData
            }
        };
    }

    /**
     * Valida la estructura de datos APU
     * @param {Object} apuData - Datos del APU a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateAPUData(apuData) {
        const errors = [];

        if (!apuData || typeof apuData !== 'object') {
            return { valid: false, errors: ['APU data debe ser un objeto'] };
        }

        // Validar arrays requeridos
        if (!Array.isArray(apuData.materials)) {
            errors.push('materials debe ser un array');
        }
        if (!Array.isArray(apuData.labor)) {
            errors.push('labor debe ser un array');
        }
        if (!Array.isArray(apuData.equipment)) {
            errors.push('equipment debe ser un array');
        }

        // Validar porcentajes
        const percentages = ['minorToolsPct', 'indirectsPct', 'financingPct', 'profitPct', 'additionalPct'];
        percentages.forEach(pct => {
            if (apuData[pct] !== undefined && (typeof apuData[pct] !== 'number' || apuData[pct] < 0 || apuData[pct] > 1)) {
                errors.push(`${pct} debe ser un número entre 0 y 1`);
            }
        });

        // Validar estructura de materiales
        if (Array.isArray(apuData.materials)) {
            apuData.materials.forEach((mat, idx) => {
                if (!mat.description) errors.push(`Material ${idx + 1}: falta descripción`);
                if (typeof mat.quantity !== 'number' || mat.quantity < 0) {
                    errors.push(`Material ${idx + 1}: cantidad inválida`);
                }
                if (typeof mat.unitPrice !== 'number' || mat.unitPrice < 0) {
                    errors.push(`Material ${idx + 1}: precio unitario inválido`);
                }
            });
        }

        // Validar estructura de mano de obra
        if (Array.isArray(apuData.labor)) {
            apuData.labor.forEach((lab, idx) => {
                if (!lab.description) errors.push(`Mano de obra ${idx + 1}: falta descripción`);
                if (typeof lab.quantity !== 'number' || lab.quantity < 0) {
                    errors.push(`Mano de obra ${idx + 1}: cantidad inválida`);
                }
                const baseSalary = lab.baseSalary || lab.unitPrice;
                if (typeof baseSalary !== 'number' || baseSalary < 0) {
                    errors.push(`Mano de obra ${idx + 1}: salario base inválido`);
                }
                if (lab.fsr !== undefined && (typeof lab.fsr !== 'number' || lab.fsr <= 0)) {
                    errors.push(`Mano de obra ${idx + 1}: FSR inválido`);
                }
            });
        }

        // Validar estructura de equipo
        if (Array.isArray(apuData.equipment)) {
            apuData.equipment.forEach((eq, idx) => {
                if (!eq.description) errors.push(`Equipo ${idx + 1}: falta descripción`);
                if (typeof eq.quantity !== 'number' || eq.quantity < 0) {
                    errors.push(`Equipo ${idx + 1}: cantidad inválida`);
                }
                if (typeof eq.unitPrice !== 'number' || eq.unitPrice < 0) {
                    errors.push(`Equipo ${idx + 1}: precio unitario inválido`);
                }
            });
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Normaliza y completa datos APU con valores por defecto
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Datos normalizados
     */
    static normalizeAPUData(apuData) {
        if (!apuData) return null;

        const normalized = JSON.parse(JSON.stringify(apuData));

        // Asegurar arrays
        normalized.materials = normalized.materials || [];
        normalized.labor = normalized.labor || [];
        normalized.equipment = normalized.equipment || [];

        // Aplicar valores por defecto
        normalized.minorToolsPct = normalized.minorToolsPct ?? this.DEFAULT_CONFIG.minorToolsPct;
        normalized.indirectsPct = normalized.indirectsPct ?? this.DEFAULT_CONFIG.indirectsPct;
        normalized.financingPct = normalized.financingPct ?? this.DEFAULT_CONFIG.financingPct;
        normalized.profitPct = normalized.profitPct ?? this.DEFAULT_CONFIG.profitPct;
        normalized.additionalPct = normalized.additionalPct ?? this.DEFAULT_CONFIG.additionalPct;

        // Normalizar mano de obra: asegurar baseSalary y fsr
        normalized.labor = normalized.labor.map(lab => ({
            ...lab,
            baseSalary: lab.baseSalary ?? lab.unitPrice ?? 0,
            fsr: lab.fsr ?? this.DEFAULT_CONFIG.defaultFSR,
            unit: lab.unit || 'jor'
        }));

        // Normalizar materiales y equipo: asegurar valores numéricos
        normalized.materials = normalized.materials.map(mat => ({
            ...mat,
            quantity: mat.quantity ?? 0,
            unitPrice: mat.unitPrice ?? 0,
            unit: mat.unit || 'pza'
        }));

        normalized.equipment = normalized.equipment.map(eq => ({
            ...eq,
            quantity: eq.quantity ?? 0,
            unitPrice: eq.unitPrice ?? 0,
            unit: eq.unit || 'hora'
        }));

        return normalized;
    }

    /**
     * Calcula el costo total de materiales
     * @param {Array} materials - Array de materiales
     * @returns {number} - Total de materiales
     */
    static calculateMaterialsTotal(materials) {
        if (!Array.isArray(materials)) return 0;
        return materials.reduce((sum, mat) => {
            const quantity = mat.quantity || 0;
            const unitPrice = mat.unitPrice || 0;
            return sum + (quantity * unitPrice);
        }, 0);
    }

    /**
     * Calcula el costo total de mano de obra (con FSR)
     * @param {Array} labor - Array de mano de obra
     * @returns {number} - Total de mano de obra
     */
    static calculateLaborTotal(labor) {
        if (!Array.isArray(labor)) return 0;
        return labor.reduce((sum, lab) => {
            const baseSalary = lab.baseSalary || lab.unitPrice || 0;
            const fsr = lab.fsr || this.DEFAULT_CONFIG.defaultFSR;
            const realSalary = baseSalary * fsr;
            const quantity = lab.quantity || 0;
            return sum + (quantity * realSalary);
        }, 0);
    }

    /**
     * Calcula el costo total de equipo
     * @param {Array} equipment - Array de equipo
     * @returns {number} - Total de equipo
     */
    static calculateEquipmentTotal(equipment) {
        if (!Array.isArray(equipment)) return 0;
        return equipment.reduce((sum, eq) => {
            const quantity = eq.quantity || 0;
            const unitPrice = eq.unitPrice || 0;
            return sum + (quantity * unitPrice);
        }, 0);
    }

    /**
     * Calcula el costo de herramienta menor
     * @param {number} laborTotal - Total de mano de obra
     * @param {number} minorToolsPct - Porcentaje de herramienta menor
     * @returns {number} - Costo de herramienta menor
     */
    static calculateMinorToolsCost(laborTotal, minorToolsPct) {
        return laborTotal * (minorToolsPct || this.DEFAULT_CONFIG.minorToolsPct);
    }

    /**
     * Calcula el costo directo
     * @param {Object} apuData - Datos del APU normalizados
     * @returns {number} - Costo directo
     */
    static calculateDirectCost(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) return 0;

        const materialsTotal = this.calculateMaterialsTotal(normalized.materials);
        const laborTotal = this.calculateLaborTotal(normalized.labor);
        const equipmentTotal = this.calculateEquipmentTotal(normalized.equipment);
        const minorToolsCost = this.calculateMinorToolsCost(laborTotal, normalized.minorToolsPct);

        return materialsTotal + laborTotal + equipmentTotal + minorToolsCost;
    }

    /**
     * Calcula todos los costos en cascada del APU
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Objeto con todos los cálculos
     */
    static calculateAPUTotals(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) {
            return {
                materialsTotal: 0,
                laborTotal: 0,
                equipmentTotal: 0,
                minorToolsCost: 0,
                directCost: 0,
                indirectCost: 0,
                subtotal1: 0,
                financingCost: 0,
                subtotal2: 0,
                profitCost: 0,
                subtotal3: 0,
                additionalCost: 0,
                finalPrice: 0
            };
        }

        // Costos directos
        const materialsTotal = this.calculateMaterialsTotal(normalized.materials);
        const laborTotal = this.calculateLaborTotal(normalized.labor);
        const equipmentTotal = this.calculateEquipmentTotal(normalized.equipment);
        const minorToolsCost = this.calculateMinorToolsCost(laborTotal, normalized.minorToolsPct);
        const directCost = materialsTotal + laborTotal + equipmentTotal + minorToolsCost;

        // Cascada de costos indirectos
        const indirectCost = directCost * normalized.indirectsPct;
        const subtotal1 = directCost + indirectCost;

        const financingCost = subtotal1 * normalized.financingPct;
        const subtotal2 = subtotal1 + financingCost;

        const profitCost = subtotal2 * normalized.profitPct;
        const subtotal3 = subtotal2 + profitCost;

        const additionalCost = subtotal3 * normalized.additionalPct;
        const finalPrice = subtotal3 + additionalCost;

        return {
            materialsTotal,
            laborTotal,
            equipmentTotal,
            minorToolsCost,
            directCost,
            indirectCost,
            subtotal1,
            financingCost,
            subtotal2,
            profitCost,
            subtotal3,
            additionalCost,
            finalPrice
        };
    }

    /**
     * Calcula el precio unitario final del APU
     * @param {Object} apuData - Datos del APU
     * @returns {number} - Precio unitario final
     */
    static calculateFinalPrice(apuData) {
        const totals = this.calculateAPUTotals(apuData);
        return totals.finalPrice;
    }

    /**
     * Obtiene el salario real de un elemento de mano de obra
     * @param {Object} laborItem - Item de mano de obra
     * @returns {number} - Salario real (baseSalary * fsr)
     */
    static getRealSalary(laborItem) {
        if (!laborItem) return 0;
        const baseSalary = laborItem.baseSalary || laborItem.unitPrice || 0;
        const fsr = laborItem.fsr || this.DEFAULT_CONFIG.defaultFSR;
        return baseSalary * fsr;
    }

    /**
     * Calcula el total de un item de mano de obra
     * @param {Object} laborItem - Item de mano de obra
     * @returns {number} - Total (quantity * realSalary)
     */
    static calculateLaborItemTotal(laborItem) {
        if (!laborItem) return 0;
        const realSalary = this.getRealSalary(laborItem);
        const quantity = laborItem.quantity || 0;
        return quantity * realSalary;
    }

    /**
     * Exporta datos APU a formato estándar para guardado
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Datos exportados
     */
    static exportAPUData(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) return null;

        return {
            ...normalized,
            calculatedTotals: this.calculateAPUTotals(normalized),
            calculatedAt: new Date().toISOString(),
            version: '1.0'
        };
    }

    /**
     * Crea un APU vacío con estructura básica
     * @returns {Object} - APU vacío
     */
    static createEmptyAPU() {
        return {
            materials: [],
            labor: [],
            equipment: [],
            minorToolsPct: this.DEFAULT_CONFIG.minorToolsPct,
            indirectsPct: this.DEFAULT_CONFIG.indirectsPct,
            financingPct: this.DEFAULT_CONFIG.financingPct,
            profitPct: this.DEFAULT_CONFIG.profitPct,
            additionalPct: this.DEFAULT_CONFIG.additionalPct,
            notes: ''
        };
    }

    /**
     * Agrega un material al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} material - Material a agregar
     * @returns {Object} - APU actualizado
     */
    static addMaterial(apuData, material) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.materials.push({
            description: material.description || '',
            unit: material.unit || 'pza',
            quantity: material.quantity || 0,
            unitPrice: material.unitPrice || 0
        });
        return normalized;
    }

    /**
     * Agrega un elemento de mano de obra al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} labor - Mano de obra a agregar
     * @returns {Object} - APU actualizado
     */
    static addLabor(apuData, labor) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.labor.push({
            description: labor.description || '',
            unit: labor.unit || 'jor',
            quantity: labor.quantity || 0,
            baseSalary: labor.baseSalary || 0,
            fsr: labor.fsr || this.DEFAULT_CONFIG.defaultFSR
        });
        return normalized;
    }

    /**
     * Agrega un equipo al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} equipment - Equipo a agregar
     * @returns {Object} - APU actualizado
     */
    static addEquipment(apuData, equipment) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.equipment.push({
            description: equipment.description || '',
            unit: equipment.unit || 'hora',
            quantity: equipment.quantity || 0,
            unitPrice: equipment.unitPrice || 0
        });
        return normalized;
    }
}

export default APUService;

/**
 * AIBudgetService
 * Centralized service for AI-powered budget generation and analysis
 * Uses BackendAIService to keep API keys secure
 */

import { BackendAIService } from './BackendAIService';
