        try {
            const itemsList = items.map(item => {
                const basis = item.calculation_basis ? ` [Base: ${item.calculation_basis}]` : '';
                return `- ${item.description} (Cant: ${item.quantity} ${item.unit}, Cat: ${item.category})${basis}`;
