RECUERDA: IGNORA COMPLETAMENTE LA CANTIDAD DEL PROYECTO (${item.quantity || 1}). SOLO CALCULA PARA 1 ${item.unit || 'unidad'}.`;

            const result = await BackendAIService.sendPrompt(userPrompt, systemPrompt);
