                                validationErrors.push(`❌ ERROR CRÍTICO: Cantidad de concreto (${concrete.quantity} m3) es igual a la cantidad del proyecto (${itemQuantity} m3). El APU está calculando para ${itemQuantity} m3 en lugar de 1 m3.`);
