                }
                if (item.category === 'Mano de Obra' && item.unitPrice > 1200) {
                    priceWarnings.push(`Partida ${index + 1}: Precio de mano de obra muy alto ($${item.unitPrice}/jor). Rango típico: $400-800/jor`);
