                    No incluyas markdown, ni explicaciones fuera del JSON.
                `;

                const userPrompt = `Lista de conceptos a actualizar para ${location}:\n${itemsList}`;

                const result = await BackendAIService.sendPrompt(userPrompt, systemPrompt);
