/**
 * APUService
 * Servicio dedicado para Análisis de Precios Unitarios (APU)
 * Maneja cálculos, validaciones y transformaciones de datos APU
 * 
 * Estándar: NEODATA/OPUS
 */

import { MarketPriceService } from './MarketPriceService';

export class APUService {
    // Valores por defecto según estándar mexicano
    static DEFAULT_CONFIG = {
        minorToolsPct: 0.03,      // 3% de herramienta menor sobre mano de obra
        indirectsPct: 0.16,        // 16% indirectos sobre costo directo
        financingPct: 0.01,       // 1% financiamiento
        profitPct: 0.10,          // 10% utilidad
        additionalPct: 0.005,      // 0.5% cargos adicionales
        defaultFSR: 1.75          // Factor de Salario Real por defecto
    };

    // Lógica de ingeniería por especialidad (Nivel Neodata)
    static SPECIALTY_LOGIC = {
        'ELECTRICA_BAJA_TENSION': {
            consumablesPct: 0.05, // 5% para "Material Menor" (pijas, cinta, conectores)
            safetyGearPct: 0.02,  // Equipo de seguridad dieléctrico
            recommendedUnits: ['salida', 'ml', 'pza']
        },
        'ELECTRICA_MEDIA_TENSION': {
            heavyEquipment: true, // Requiere grúas o canastillas
            specializedLabor: 'Cuadrilla de Linieros',
            testingPct: 0.03      // Pruebas de megger/continuidad
        },
        'JARDINERIA_PAISAJISMO': {
            shrinkagePct: 0.10,   // 10% merma en plantas/pasto (se secan)
            waterConsumption: true,
            laborType: 'Jornaleros Paisajistas'
        },
        'ALBAÑILERIA': {
            minorToolsPct: 0.05, // Mayor desgaste de herramienta
            cleanupPct: 0.02     // Limpieza constante
        }
    };

    /**
     * Enriquece el APU con lógica de ingeniería según la especialidad
     * Inyecta componentes "fantasma" que Neodata siempre incluye
     * @param {Object} apuData - Datos base del APU
     * @param {string} specialty - Especialidad (ej: 'electrica', 'jardineria')
     * @returns {Object} - APU enriquecido con items automáticos
     */
    static enrichWithEngineeringLogic(apuData, specialty) {
        if (!specialty) return apuData;

        const normalizedSpecialty = specialty.toUpperCase();
        let logic = {};

        // Detectar lógica a aplicar
        if (normalizedSpecialty.includes('ELECTRICA') || normalizedSpecialty.includes('ELECTRIC')) {
            logic = this.SPECIALTY_LOGIC['ELECTRICA_BAJA_TENSION'];
        } else if (normalizedSpecialty.includes('JARDIN')) {
            logic = this.SPECIALTY_LOGIC['JARDINERIA_PAISAJISMO'];
        } else if (normalizedSpecialty.includes('ALBAÑIL') || normalizedSpecialty.includes('CIVIL')) {
            logic = this.SPECIALTY_LOGIC['ALBAÑILERIA'];
        }

        const enriched = JSON.parse(JSON.stringify(apuData));
        enriched.materials = enriched.materials || [];

        // Lógica: Material Menor (Consumibles)
        if (logic.consumablesPct) {
            const matTotal = this.calculateMaterialsTotal(enriched.materials);
            if (matTotal > 0) {
                // Verificar si ya existe para no duplicar
                const hasConsumables = enriched.materials.some(m => m.description.includes('Material menor') || m.description.includes('Consumibles'));
                if (!hasConsumables) {
                    enriched.materials.push({
                        description: "Material menor (Cinta aislante, conectores, tornillería, etc.)",
                        unit: "%",
                        quantity: 1,
                        unitPrice: matTotal * logic.consumablesPct,
                        isGenerated: true
                    });
                }
            }
        }

        // Lógica: Merma por ser vivos (Jardinería)
        if (logic.shrinkagePct) {
            const matTotal = this.calculateMaterialsTotal(enriched.materials);
            if (matTotal > 0) {
                enriched.materials.push({
                    description: "Merma y reposición de material vegetal (Garantía)",
                    unit: "%",
                    quantity: 1,
                    unitPrice: matTotal * logic.shrinkagePct,
                    isGenerated: true
                });
            }
        }

        // Lógica: Limpieza fina (Albañilería)
        if (logic.cleanupPct) {
            const directCost = this.calculateDirectCost(enriched);
            if (directCost > 0) {
                enriched.materials.push({
                    description: "Limpieza fina de obra y retiro de escombro fuera de la zona",
                    unit: "lote",
                    quantity: 1,
                    unitPrice: directCost * logic.cleanupPct,
                    isGenerated: true
                });
            }
        }

        return enriched;
    }

    /**
     * Enforces official prices from the Master Catalog if a match is found.
     * @param {Object} apuData - The APU data to process.
     * @param {string} location - The location for price lookup.
     * @returns {Promise<{apuData: Object, stats: Object}>} - The updated APU data and statistics.
     */
    static async enforceMasterCatalogPrices(apuData, location) {
        let replacedMaterialsCount = 0;
        let materialsWithRealData = 0;
        let replacedLaborCount = 0;
        let laborWithRealData = 0;

        const normalizeUnit = (u) => {
            if (!u) return '';
            const unit = u.toLowerCase().replace(/\./g, '').trim();
            const map = {
                'jor': 'jor', 'jornal': 'jor', 'dia': 'jor', 'dias': 'jor',
                'hr': 'h', 'hora': 'h', 'horas': 'h', 'h': 'h'
            };
            return map[unit] || unit;
        };

        const processedAPU = JSON.parse(JSON.stringify(apuData));

        // Process Materials
        if (processedAPU.materials && Array.isArray(processedAPU.materials)) {
            const updatedMaterials = await Promise.all(processedAPU.materials.map(async (mat) => {
                try {
                    const validPrices = await MarketPriceService.findReferencePrice(
                        mat.description,
                        'Materiales',
                        location,
                        5
                    );

                    if (validPrices && validPrices.length > 0) {
                        const matUnit = normalizeUnit(mat.unit);
                        const exactMatch = validPrices.find(p => normalizeUnit(p.unit) === matUnit);

                        if (exactMatch) {
                            const exactPrice = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactPrice) && exactPrice > 0) {
                                replacedMaterialsCount++;
                                materialsWithRealData++;
                                return {
                                    ...mat,
                                    unitPrice: exactPrice,
                                    total: (mat.quantity || 0) * exactPrice,
                                    source: 'Base Maestra Neodata',
                                    sourceDetail: exactMatch.source || 'Base Maestra'
                                };
                            }
                        }
                    }
                    return mat;
                } catch (error) {
                    console.warn(`Error finding price for material ${mat.description}:`, error);
                    return mat;
                }
            }));
            processedAPU.materials = updatedMaterials;
        }

        // Process Labor
        if (processedAPU.labor && Array.isArray(processedAPU.labor)) {
            const updatedLabor = await Promise.all(processedAPU.labor.map(async (lab) => {
                try {
                    const exactPrices = await MarketPriceService.findReferencePrice(
                        lab.description,
                        'Mano de Obra',
                        location,
                        3
                    );

                    if (exactPrices && exactPrices.length > 0) {
                        const labUnit = normalizeUnit(lab.unit);
                        const exactMatch = exactPrices.find(p => normalizeUnit(p.unit) === labUnit);

                        if (exactMatch) {
                            const exactSalary = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactSalary) && exactSalary > 0) {
                                const fsr = lab.fsr || 1.75;
                                const unitPrice = exactSalary * fsr;
                                replacedLaborCount++;
                                laborWithRealData++;
                                return {
                                    ...lab,
                                    baseSalary: exactSalary,
                                    unitPrice: unitPrice,
                                    total: (lab.quantity || 0) * unitPrice,
                                    source: 'Base Maestra Neodata',
                                    sourceDetail: exactMatch.source || 'Base Maestra',
                                    notes: `${lab.notes || ''} | Salario base: Base Maestra Neodata`.trim()
                                };
                            }
                        }
                    }
                    return lab;
                } catch (error) {
                    console.warn(`Error finding salary for labor ${lab.description}:`, error);
                    return lab;
                }
            }));
            processedAPU.labor = updatedLabor;
        }

        // Process Equipment
        if (processedAPU.equipment && Array.isArray(processedAPU.equipment)) {
            const updatedEquipment = await Promise.all(processedAPU.equipment.map(async (eq) => {
                try {
                    const exactPrices = await MarketPriceService.findReferencePrice(
                        eq.description,
                        'Equipos',
                        location,
                        1
                    );

                    if (exactPrices && exactPrices.length > 0) {
                        const eqUnit = normalizeUnit(eq.unit);
                        const exactMatch = exactPrices.find(p => normalizeUnit(p.unit) === eqUnit);

                        if (exactMatch) {
                            const exactPrice = parseFloat(exactMatch.base_price);
                            if (!isNaN(exactPrice) && exactPrice > 0) {
                                return {
                                    ...eq,
                                    unitPrice: exactPrice,
                                    total: (eq.quantity || 0) * exactPrice,
                                    source: 'Base Maestra Neodata'
                                };
                            }
                        }
                    }
                    return eq;
                } catch (error) {
                    console.warn(`Error finding price for equipment ${eq.description}:`, error);
                    return eq;
                }
            }));
            processedAPU.equipment = updatedEquipment;
        }

        return {
            apuData: processedAPU,
            stats: {
                replacedMaterialsCount,
                materialsWithRealData,
                replacedLaborCount,
                laborWithRealData
            }
        };
    }

    /**
     * Valida la estructura de datos APU
     * @param {Object} apuData - Datos del APU a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateAPUData(apuData) {
        const errors = [];

        if (!apuData || typeof apuData !== 'object') {
            return { valid: false, errors: ['APU data debe ser un objeto'] };
        }

        // Validar arrays requeridos
        if (!Array.isArray(apuData.materials)) {
            errors.push('materials debe ser un array');
        }
        if (!Array.isArray(apuData.labor)) {
            errors.push('labor debe ser un array');
        }
        if (!Array.isArray(apuData.equipment)) {
            errors.push('equipment debe ser un array');
        }

        // Validar porcentajes
        const percentages = ['minorToolsPct', 'indirectsPct', 'financingPct', 'profitPct', 'additionalPct'];
        percentages.forEach(pct => {
            if (apuData[pct] !== undefined && (typeof apuData[pct] !== 'number' || apuData[pct] < 0 || apuData[pct] > 1)) {
                errors.push(`${pct} debe ser un número entre 0 y 1`);
            }
        });

        // Validar estructura de materiales
        if (Array.isArray(apuData.materials)) {
            apuData.materials.forEach((mat, idx) => {
                if (!mat.description) errors.push(`Material ${idx + 1}: falta descripción`);
                if (typeof mat.quantity !== 'number' || mat.quantity < 0) {
                    errors.push(`Material ${idx + 1}: cantidad inválida`);
                }
                if (typeof mat.unitPrice !== 'number' || mat.unitPrice < 0) {
                    errors.push(`Material ${idx + 1}: precio unitario inválido`);
                }
            });
        }

        // Validar estructura de mano de obra
        if (Array.isArray(apuData.labor)) {
            apuData.labor.forEach((lab, idx) => {
                if (!lab.description) errors.push(`Mano de obra ${idx + 1}: falta descripción`);
                if (typeof lab.quantity !== 'number' || lab.quantity < 0) {
                    errors.push(`Mano de obra ${idx + 1}: cantidad inválida`);
                }
                const baseSalary = lab.baseSalary || lab.unitPrice;
                if (typeof baseSalary !== 'number' || baseSalary < 0) {
                    errors.push(`Mano de obra ${idx + 1}: salario base inválido`);
                }
                if (lab.fsr !== undefined && (typeof lab.fsr !== 'number' || lab.fsr <= 0)) {
                    errors.push(`Mano de obra ${idx + 1}: FSR inválido`);
                }
            });
        }

        // Validar estructura de equipo
        if (Array.isArray(apuData.equipment)) {
            apuData.equipment.forEach((eq, idx) => {
                if (!eq.description) errors.push(`Equipo ${idx + 1}: falta descripción`);
                if (typeof eq.quantity !== 'number' || eq.quantity < 0) {
                    errors.push(`Equipo ${idx + 1}: cantidad inválida`);
                }
                if (typeof eq.unitPrice !== 'number' || eq.unitPrice < 0) {
                    errors.push(`Equipo ${idx + 1}: precio unitario inválido`);
                }
            });
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Normaliza y completa datos APU con valores por defecto
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Datos normalizados
     */
    static normalizeAPUData(apuData) {
        if (!apuData) return null;

        const normalized = JSON.parse(JSON.stringify(apuData));

        // Asegurar arrays
        normalized.materials = normalized.materials || [];
        normalized.labor = normalized.labor || [];
        normalized.equipment = normalized.equipment || [];

        // Aplicar valores por defecto
        normalized.minorToolsPct = normalized.minorToolsPct ?? this.DEFAULT_CONFIG.minorToolsPct;
        normalized.indirectsPct = normalized.indirectsPct ?? this.DEFAULT_CONFIG.indirectsPct;
        normalized.financingPct = normalized.financingPct ?? this.DEFAULT_CONFIG.financingPct;
        normalized.profitPct = normalized.profitPct ?? this.DEFAULT_CONFIG.profitPct;
        normalized.additionalPct = normalized.additionalPct ?? this.DEFAULT_CONFIG.additionalPct;

        // Normalizar mano de obra: asegurar baseSalary y fsr
        normalized.labor = normalized.labor.map(lab => ({
            ...lab,
            baseSalary: lab.baseSalary ?? lab.unitPrice ?? 0,
            fsr: lab.fsr ?? this.DEFAULT_CONFIG.defaultFSR,
            unit: lab.unit || 'jor'
        }));

        // Normalizar materiales y equipo: asegurar valores numéricos
        normalized.materials = normalized.materials.map(mat => ({
            ...mat,
            quantity: mat.quantity ?? 0,
            unitPrice: mat.unitPrice ?? 0,
            unit: mat.unit || 'pza'
        }));

        normalized.equipment = normalized.equipment.map(eq => ({
            ...eq,
            quantity: eq.quantity ?? 0,
            unitPrice: eq.unitPrice ?? 0,
            unit: eq.unit || 'hora'
        }));

        return normalized;
    }

    /**
     * Calcula el costo total de materiales
     * @param {Array} materials - Array de materiales
     * @returns {number} - Total de materiales
     */
    static calculateMaterialsTotal(materials) {
        if (!Array.isArray(materials)) return 0;
        return materials.reduce((sum, mat) => {
            const quantity = mat.quantity || 0;
            const unitPrice = mat.unitPrice || 0;
            return sum + (quantity * unitPrice);
        }, 0);
    }

    /**
     * Calcula el costo total de mano de obra (con FSR)
     * @param {Array} labor - Array de mano de obra
     * @returns {number} - Total de mano de obra
     */
    static calculateLaborTotal(labor) {
        if (!Array.isArray(labor)) return 0;
        return labor.reduce((sum, lab) => {
            const baseSalary = lab.baseSalary || lab.unitPrice || 0;
            const fsr = lab.fsr || this.DEFAULT_CONFIG.defaultFSR;
            const realSalary = baseSalary * fsr;
            const quantity = lab.quantity || 0;
            return sum + (quantity * realSalary);
        }, 0);
    }

    /**
     * Calcula el costo total de equipo
     * @param {Array} equipment - Array de equipo
     * @returns {number} - Total de equipo
     */
    static calculateEquipmentTotal(equipment) {
        if (!Array.isArray(equipment)) return 0;
        return equipment.reduce((sum, eq) => {
            const quantity = eq.quantity || 0;
            const unitPrice = eq.unitPrice || 0;
            return sum + (quantity * unitPrice);
        }, 0);
    }

    /**
     * Calcula el costo de herramienta menor
     * @param {number} laborTotal - Total de mano de obra
     * @param {number} minorToolsPct - Porcentaje de herramienta menor
     * @returns {number} - Costo de herramienta menor
     */
    static calculateMinorToolsCost(laborTotal, minorToolsPct) {
        return laborTotal * (minorToolsPct || this.DEFAULT_CONFIG.minorToolsPct);
    }

    /**
     * Calcula el costo directo
     * @param {Object} apuData - Datos del APU normalizados
     * @returns {number} - Costo directo
     */
    static calculateDirectCost(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) return 0;

        const materialsTotal = this.calculateMaterialsTotal(normalized.materials);
        const laborTotal = this.calculateLaborTotal(normalized.labor);
        const equipmentTotal = this.calculateEquipmentTotal(normalized.equipment);
        const minorToolsCost = this.calculateMinorToolsCost(laborTotal, normalized.minorToolsPct);

        return materialsTotal + laborTotal + equipmentTotal + minorToolsCost;
    }

    /**
     * Calcula todos los costos en cascada del APU
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Objeto con todos los cálculos
     */
    static calculateAPUTotals(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) {
            return {
                materialsTotal: 0,
                laborTotal: 0,
                equipmentTotal: 0,
                minorToolsCost: 0,
                directCost: 0,
                indirectCost: 0,
                subtotal1: 0,
                financingCost: 0,
                subtotal2: 0,
                profitCost: 0,
                subtotal3: 0,
                additionalCost: 0,
                finalPrice: 0
            };
        }

        // Costos directos
        const materialsTotal = this.calculateMaterialsTotal(normalized.materials);
        const laborTotal = this.calculateLaborTotal(normalized.labor);
        const equipmentTotal = this.calculateEquipmentTotal(normalized.equipment);
        const minorToolsCost = this.calculateMinorToolsCost(laborTotal, normalized.minorToolsPct);
        const directCost = materialsTotal + laborTotal + equipmentTotal + minorToolsCost;

        // Cascada de costos indirectos
        const indirectCost = directCost * normalized.indirectsPct;
        const subtotal1 = directCost + indirectCost;

        const financingCost = subtotal1 * normalized.financingPct;
        const subtotal2 = subtotal1 + financingCost;

        const profitCost = subtotal2 * normalized.profitPct;
        const subtotal3 = subtotal2 + profitCost;

        const additionalCost = subtotal3 * normalized.additionalPct;
        const finalPrice = subtotal3 + additionalCost;

        return {
            materialsTotal,
            laborTotal,
            equipmentTotal,
            minorToolsCost,
            directCost,
            indirectCost,
            subtotal1,
            financingCost,
            subtotal2,
            profitCost,
            subtotal3,
            additionalCost,
            finalPrice
        };
    }

    /**
     * Calcula el precio unitario final del APU
     * @param {Object} apuData - Datos del APU
     * @returns {number} - Precio unitario final
     */
    static calculateFinalPrice(apuData) {
        const totals = this.calculateAPUTotals(apuData);
        return totals.finalPrice;
    }

    /**
     * Obtiene el salario real de un elemento de mano de obra
     * @param {Object} laborItem - Item de mano de obra
     * @returns {number} - Salario real (baseSalary * fsr)
     */
    static getRealSalary(laborItem) {
        if (!laborItem) return 0;
        const baseSalary = laborItem.baseSalary || laborItem.unitPrice || 0;
        const fsr = laborItem.fsr || this.DEFAULT_CONFIG.defaultFSR;
        return baseSalary * fsr;
    }

    /**
     * Calcula el total de un item de mano de obra
     * @param {Object} laborItem - Item de mano de obra
     * @returns {number} - Total (quantity * realSalary)
     */
    static calculateLaborItemTotal(laborItem) {
        if (!laborItem) return 0;
        const realSalary = this.getRealSalary(laborItem);
        const quantity = laborItem.quantity || 0;
        return quantity * realSalary;
    }

    /**
     * Exporta datos APU a formato estándar para guardado
     * @param {Object} apuData - Datos del APU
     * @returns {Object} - Datos exportados
     */
    static exportAPUData(apuData) {
        const normalized = this.normalizeAPUData(apuData);
        if (!normalized) return null;

        return {
            ...normalized,
            calculatedTotals: this.calculateAPUTotals(normalized),
            calculatedAt: new Date().toISOString(),
            version: '1.0'
        };
    }

    /**
     * Crea un APU vacío con estructura básica
     * @returns {Object} - APU vacío
     */
    static createEmptyAPU() {
        return {
            materials: [],
            labor: [],
            equipment: [],
            minorToolsPct: this.DEFAULT_CONFIG.minorToolsPct,
            indirectsPct: this.DEFAULT_CONFIG.indirectsPct,
            financingPct: this.DEFAULT_CONFIG.financingPct,
            profitPct: this.DEFAULT_CONFIG.profitPct,
            additionalPct: this.DEFAULT_CONFIG.additionalPct,
            notes: ''
        };
    }

    /**
     * Agrega un material al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} material - Material a agregar
     * @returns {Object} - APU actualizado
     */
    static addMaterial(apuData, material) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.materials.push({
            description: material.description || '',
            unit: material.unit || 'pza',
            quantity: material.quantity || 0,
            unitPrice: material.unitPrice || 0
        });
        return normalized;
    }

    /**
     * Agrega un elemento de mano de obra al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} labor - Mano de obra a agregar
     * @returns {Object} - APU actualizado
     */
    static addLabor(apuData, labor) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.labor.push({
            description: labor.description || '',
            unit: labor.unit || 'jor',
            quantity: labor.quantity || 0,
            baseSalary: labor.baseSalary || 0,
            fsr: labor.fsr || this.DEFAULT_CONFIG.defaultFSR
        });
        return normalized;
    }

    /**
     * Agrega un equipo al APU
     * @param {Object} apuData - Datos del APU
     * @param {Object} equipment - Equipo a agregar
     * @returns {Object} - APU actualizado
     */
    static addEquipment(apuData, equipment) {
        const normalized = this.normalizeAPUData(apuData) || this.createEmptyAPU();
        normalized.equipment.push({
            description: equipment.description || '',
            unit: equipment.unit || 'hora',
            quantity: equipment.quantity || 0,
            unitPrice: equipment.unitPrice || 0
        });
        return normalized;
    }
}

export default APUService;

/**
 * MarketPriceService
 * Servicio para gestionar precios de referencia del mercado
 * Se usa cuando el usuario no tiene un concepto en su catálogo personal
 */

import { supabase } from '../lib/supabaseClient';

export class MarketPriceService {
    /**
     * Buscar precio de referencia por descripción, categoría y ubicación
     * Prioriza precios oficiales (CDMX Tabulador) sobre otras fuentes
     * @param {string} description - Descripción del concepto
     * @param {string} category - Categoría (Materiales, Mano de Obra, etc.)
     * @param {string} location - Ubicación (México, CDMX, Monterrey, etc.)
     * @param {number} limit - Máximo de resultados
     * @returns {Promise<Array>} - Array de precios de referencia (ordenados por prioridad)
     */
    static async findReferencePrice(description, category, location = 'México', limit = 5) {
        try {
            if (!description || !category) {
                return [];
            }

            const officialSources = ['cdmx_tabulador'];
            const isCDMX = location && (location.includes('CDMX') || location.includes('Ciudad de México'));

            // Buscar todos los precios de la categoría
            let query = supabase
                .from('market_price_reference')
                .select('*')
                .eq('category', category)
                .eq('is_active', true);

            // Filtrar por ubicación
            let locationConditions = [];
            if (isCDMX) {
                locationConditions.push('location.ilike.%CDMX%');
                locationConditions.push('location.ilike.%Ciudad de México%');
                locationConditions.push('location.eq.México');
            } else {
                // Simplificar la ubicación para evitar errores con comas en Supabase
                const simpleLocation = location.split(',')[0].trim();
                const searchLocation = simpleLocation.includes('%') ? simpleLocation : `%${simpleLocation}%`;

                // Usar comillas para manejar espacios y caracteres especiales
                locationConditions.push(`location.ilike."${searchLocation}"`);
                locationConditions.push('location.eq.México');
            }
            query = query.or(locationConditions.join(','));

            const { data, error } = await query;
            if (error) throw error;

            if (!data || data.length === 0) {
                // Fallback: buscar en "México" genérico
                const { data: fallbackData, error: fallbackError } = await supabase
                    .from('market_price_reference')
                    .select('*')
                    .eq('category', category)
                    .eq('is_active', true)
                    .eq('location', 'México')
                    .limit(limit);

                if (fallbackError) throw fallbackError;
                return fallbackData || [];
            }

            // Calcular relevancia y priorizar fuentes oficiales
            const descriptionTerms = description.toLowerCase().split(/\s+/).filter(t => t.length > 3);
            const scoredResults = data.map(item => {
                let score = 0;
                const itemText = item.description.toLowerCase();

                // Puntos por coincidencias en descripción
                descriptionTerms.forEach(term => {
                    if (itemText.includes(term)) score += 1;
                });

                // Bonificación por ser fuente oficial (CDMX Tabulador)
                if (officialSources.includes(item.source)) {
                    score += 10;
                }

                // Bonificación por ubicación específica (CDMX para proyectos CDMX)
                if (isCDMX && (item.location?.includes('CDMX') || item.location?.includes('Ciudad de México'))) {
                    score += 5;
                }

                return { ...item, relevanceScore: score };
            });

            // Ordenar por relevancia (oficiales primero)
            const sorted = scoredResults.sort((a, b) => {
                // Primero por score de relevancia
                if (b.relevanceScore !== a.relevanceScore) {
                    return b.relevanceScore - a.relevanceScore;
                }
                // Si mismo score, priorizar oficiales
                const aOfficial = officialSources.includes(a.source) ? 1 : 0;
                const bOfficial = officialSources.includes(b.source) ? 1 : 0;
                return bOfficial - aOfficial;
            });

            return sorted.slice(0, limit);

        } catch (error) {
            console.error('Error finding reference price:', error);
            return [];
        }
    }

    /**
     * Buscar precios en la base de datos maestra con paginación
     * @param {string} query - Término de búsqueda
     * @param {number} page - Número de página (1-based)
     * @param {number} limit - Resultados por página
     * @returns {Promise<{data: Array, count: number}>}
     */
    static async searchPrices(query = '', page = 1, limit = 50) {
        try {
            const from = (page - 1) * limit;
            const to = from + limit - 1;

            let dbQuery = supabase
                .from('market_price_reference')
                .select('*', { count: 'exact' })
                .eq('is_active', true)
                .order('description', { ascending: true });

            if (query) {
                dbQuery = dbQuery.ilike('description', `%${query}%`);
            }

            const { data, count, error } = await dbQuery.range(from, to);

            if (error) throw error;

            // Ordenar priorizando fuentes oficiales
            const officialSources = ['cdmx_tabulador'];
            const sorted = (data || []).sort((a, b) => {
                const aOfficial = officialSources.includes(a.source) ? 1 : 0;
                const bOfficial = officialSources.includes(b.source) ? 1 : 0;
                if (bOfficial !== aOfficial) {
                    return bOfficial - aOfficial;
                }
                return (a.description || '').localeCompare(b.description || '');
            });

            return { data: sorted, count: count || 0 };
        } catch (error) {
            console.error('Error searching prices:', error);
            return { data: [], count: 0 };
        }
    }

    /**
     * Obtener precios de referencia por categoría y ubicación
     * @param {string} category - Categoría
     * @param {string} location - Ubicación
     * @param {number} limit - Máximo de resultados
     * @returns { Promise < Array >} - Array de precios de referencia
     */
    static async getPricesByCategory(category, location = 'México', limit = 50) {
        try {
            const officialSources = ['cdmx_tabulador'];
            const isCDMX = location && (location.includes('CDMX') || location.includes('Ciudad de México'));

            let query = supabase
                .from('market_price_reference')
                .select('*')
                .eq('category', category)
                .eq('is_active', true);

            // Filtrar por ubicación
            let locationConditions = [];
            if (isCDMX) {
                locationConditions.push('location.ilike.%CDMX%');
                locationConditions.push('location.ilike.%Ciudad de México%');
                locationConditions.push('location.eq.México');
            } else {
                // Simplificar la ubicación para evitar errores con comas en Supabase
                // Ej: "Loma Bonita, Oaxaca" -> "Loma Bonita"
                const simpleLocation = location.split(',')[0].trim();
                const searchLocation = simpleLocation.includes('%') ? simpleLocation : `%${simpleLocation}%`;

                // Usar comillas para manejar espacios y caracteres especiales
                locationConditions.push(`location.ilike."${searchLocation}"`);
                locationConditions.push('location.eq.México');
            }

            query = query.or(locationConditions.join(','));

            const { data, error } = await query;
            if (error) throw error;

            if (!data || data.length === 0) {
                return [];
            }

            // Ordenar: precios oficiales primero, luego por descripción
            const sorted = data.sort((a, b) => {
                // Priorizar fuentes oficiales
                const aOfficial = officialSources.includes(a.source) ? 1 : 0;
                const bOfficial = officialSources.includes(b.source) ? 1 : 0;
                if (bOfficial !== aOfficial) {
                    return bOfficial - aOfficial;
                }
                // Luego ordenar por descripción
                return (a.description || '').localeCompare(b.description || '');
            });

            return sorted.slice(0, limit);

        } catch (error) {
            console.error('Error getting prices by category:', error);
            return [];
        }
    }

    /**
     * Obtener precio promedio de referencia para un concepto
     * Útil para tener un precio base cuando no hay coincidencia exacta
     * @param {string} category - Categoría
     * @param {string} location - Ubicación
     * @returns {Promise<number|null>} - Precio promedio o null
     */
    static async getAveragePriceByCategory(category, location = 'México') {
        try {
            const prices = await this.getPricesByCategory(category, location, 100);

            if (prices.length === 0) return null;

            const validPrices = prices
                .map(p => parseFloat(p.base_price))
                .filter(p => !isNaN(p) && p > 0);

            if (validPrices.length === 0) return null;

            const sum = validPrices.reduce((a, b) => a + b, 0);
            return sum / validPrices.length;

        } catch (error) {
            console.error('Error getting average price:', error);
            return null;
        }
    }

    /**
     * Agregar o actualizar precio de referencia
     * @param {Object} priceData - Datos del precio
     * @returns {Promise<Object>} - Precio creado/actualizado
     */
    static async upsertPrice(priceData) {
        try {
            const { description, unit, category, location, base_price, price_range, source, metadata } = priceData;

            // Buscar si ya existe un precio similar
            const { data: existing } = await supabase
                .from('market_price_reference')
                .select('id')
                .eq('description', description)
                .eq('unit', unit)
                .eq('category', category)
                .eq('location', location)
                .single();

            const priceRecord = {
                description,
                unit,
                category,
                location: location || 'México',
                base_price: parseFloat(base_price),
                price_range: price_range || null,
                source: source || 'manual',
                metadata: metadata || null,
                is_active: true,
                last_updated: new Date().toISOString()
            };

            if (existing) {
                // Actualizar existente
                const { data, error } = await supabase
                    .from('market_price_reference')
                    .update(priceRecord)
                    .eq('id', existing.id)
                    .select()
                    .single();

                if (error) throw error;
                return data;
            } else {
                // Crear nuevo
                const { data, error } = await supabase
                    .from('market_price_reference')
                    .insert([priceRecord])
                    .select()
                    .single();

                if (error) throw error;
                return data;
            }

        } catch (error) {
            console.error('Error upserting price:', error);
            throw error;
        }
    }

    /**
     * Obtener estadísticas de precios de referencia
     * @returns {Promise<Object>} - Estadísticas
     */
    static async getStatistics() {
        try {
            const { data, error } = await supabase
                .from('market_price_reference')
                .select('category, location, is_active')
                .eq('is_active', true);

            if (error) throw error;

            const stats = {
                total: data.length,
                byCategory: {},
                byLocation: {},
                bySource: {}
            };

            data.forEach(item => {
                // Por categoría
                stats.byCategory[item.category] = (stats.byCategory[item.category] || 0) + 1;

                // Por ubicación
                stats.byLocation[item.location] = (stats.byLocation[item.location] || 0) + 1;
            });

            return stats;

        } catch (error) {
            console.error('Error getting statistics:', error);
            return { total: 0, byCategory: {}, byLocation: {} };
        }
    }
}

/**
 * BitacoraService
 * Servicio centralizado para gestión de bitácora de obra
 * Maneja logs, notas, avances y evidencias fotográficas
 */

import { supabase } from '../lib/supabaseClient';

export class BitacoraService {
    /**
     * Carga todos los logs de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Array>} - Array de logs ordenados por fecha
     */
    static async loadLogs(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error loading logs:', error);
            throw error;
        }
    }

    /**
     * Carga el cronograma de un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Cronograma o null
     */
    static async loadSchedule(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { data, error } = await supabase
                .from('project_schedules')
                .select('*')
                .eq('project_id', projectId)
                .maybeSingle();

            if (error && error.code !== 'PGRST116') throw error;
            return data || null;
        } catch (error) {
            console.error('Error loading schedule:', error);
            throw error;
        }
    }

    /**
     * Obtiene el siguiente número de folio para un proyecto
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<number>} - Siguiente número de folio
     */
    static async getNextNoteNumber(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const { count, error } = await supabase
                .from('site_logs')
                .select('*', { count: 'exact', head: true })
                .eq('project_id', projectId);

            if (error) throw error;
            return (count || 0) + 1;
        } catch (error) {
            console.error('Error getting next note number:', error);
            throw error;
        }
    }

    /**
     * Crea una nueva nota de bitácora
     * @param {Object} logData - Datos de la nota
     * @returns {Promise<Object>} - Nota creada
     */
    static async createLog(logData) {
        const {
            projectId,
            taskId,
            content,
            progressPercentage = 0,
            photos = [],
            subject,
            classification = 'Informe',
            authorRole = 'Residente',
            status = 'Abierta',
            noteNumber = null,
            logDate = null, // Fecha opcional del log (para reportes fotográficos)
            authorName = null, // Para entradas de diario
            authorSignature = null, // Para entradas de diario
            isDiaryEntry = false, // Flag para identificar entradas de diario
            metadata = null // Metadata adicional (clima, materiales, personal, observaciones)
        } = logData;

        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        if (!subject || !subject.trim()) {
            throw new Error('Subject is required');
        }

        try {
            // Obtener número de folio si no se proporciona
            const finalNoteNumber = noteNumber || await this.getNextNoteNumber(projectId);

            // Para entradas de diario, guardar metadata en el content con formato especial
            let finalContent = content || '';
            if (isDiaryEntry && (authorName || authorSignature)) {
                const diaryMetadata = {
                    authorName: authorName || '',
                    authorSignature: authorSignature || '',
                    isDiaryEntry: true
                };
                // Guardar metadata al final del content con un separador especial
                finalContent = content + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
            } else if (metadata && Object.keys(metadata).length > 0) {
                // Para bitácora normal, guardar metadata (clima, materiales, personal, observaciones)
                finalContent = content + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(metadata) + '-->';
            }

            const { data, error } = await supabase
                .from('site_logs')
                .insert([{
                    project_id: projectId,
                    task_id: taskId,
                    content: finalContent,
                    progress_percentage: progressPercentage,
                    photos: Array.isArray(photos) ? photos : [photos].filter(Boolean),
                    log_date: logDate || new Date().toISOString(), // Usar fecha proporcionada o actual
                    note_number: finalNoteNumber,
                    classification,
                    author_role: authorRole,
                    status,
                    subject: subject.trim()
                }])
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error creating log:', error);
            throw error;
        }
    }

    /**
     * Actualiza una nota existente
     * @param {string} logId - ID de la nota
     * @param {Object} updates - Campos a actualizar
     * @returns {Promise<Object>} - Nota actualizada
     */
    static async updateLog(logId, updates) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const updateData = {};
            
            // Manejar contenido con metadata de diario o bitácora
            if (updates.content !== undefined) {
                let finalContent = updates.content;
                if (updates.isDiaryEntry && (updates.authorName || updates.authorSignature)) {
                    const diaryMetadata = {
                        authorName: updates.authorName || '',
                        authorSignature: updates.authorSignature || '',
                        isDiaryEntry: true
                    };
                    // Remover metadata anterior si existe
                    finalContent = finalContent.replace(/\n\n<!--DIARY_METADATA:.*?-->/, '');
                    // Agregar nueva metadata
                    finalContent = finalContent + '\n\n<!--DIARY_METADATA:' + JSON.stringify(diaryMetadata) + '-->';
                } else if (updates.metadata && Object.keys(updates.metadata).length > 0) {
                    // Para bitácora normal, guardar metadata
                    finalContent = finalContent.replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '');
                    finalContent = finalContent + '\n\n<!--BITACORA_METADATA:' + JSON.stringify(updates.metadata) + '-->';
                }
                updateData.content = finalContent;
            }
            if (updates.progressPercentage !== undefined) updateData.progress_percentage = updates.progressPercentage;
            if (updates.photos !== undefined) updateData.photos = Array.isArray(updates.photos) ? updates.photos : [updates.photos].filter(Boolean);
            if (updates.subject !== undefined) updateData.subject = updates.subject;
            if (updates.classification !== undefined) updateData.classification = updates.classification;
            if (updates.authorRole !== undefined) updateData.author_role = updates.authorRole;
            if (updates.status !== undefined) updateData.status = updates.status;
            if (updates.logDate !== undefined) updateData.log_date = updates.logDate;

            const { data, error } = await supabase
                .from('site_logs')
                .update(updateData)
                .eq('id', logId)
                .select()
                .single();

            if (error) throw error;
            return data;
        } catch (error) {
            console.error('Error updating log:', error);
            throw error;
        }
    }

    /**
     * Elimina una nota
     * @param {string} logId - ID de la nota
     */
    static async deleteLog(logId) {
        if (!logId) {
            throw new Error('Log ID is required');
        }

        try {
            const { error } = await supabase
                .from('site_logs')
                .delete()
                .eq('id', logId);

            if (error) throw error;
        } catch (error) {
            console.error('Error deleting log:', error);
            throw error;
        }
    }

    /**
     * Obtiene los logs de una tarea específica
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<Array>} - Logs de la tarea
     */
    static async getTaskLogs(projectId, taskId) {
        if (!projectId || !taskId) {
            throw new Error('Project ID and Task ID are required');
        }

        try {
            const { data, error } = await supabase
                .from('site_logs')
                .select('*')
                .eq('project_id', projectId)
                .eq('task_id', taskId)
                .order('log_date', { ascending: false });

            if (error) throw error;
            return data || [];
        } catch (error) {
            console.error('Error getting task logs:', error);
            throw error;
        }
    }

    /**
     * Calcula el avance de una tarea basado en sus logs
     * @param {string} projectId - ID del proyecto
     * @param {string} taskId - ID de la tarea
     * @returns {Promise<number>} - Porcentaje de avance (0-100)
     */
    static async getTaskProgress(projectId, taskId) {
        const logs = await this.getTaskLogs(projectId, taskId);
        if (logs.length === 0) return 0;
        
        // Retornar el avance más reciente
        return logs[0].progress_percentage || 0;
    }

    /**
     * Obtiene estadísticas de la bitácora
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object>} - Estadísticas
     */
    static async getStatistics(projectId) {
        if (!projectId) {
            throw new Error('Project ID is required');
        }

        try {
            const logs = await this.loadLogs(projectId);

            const stats = {
                totalLogs: logs.length,
                openLogs: logs.filter(l => l.status === 'Abierta').length,
                closedLogs: logs.filter(l => l.status === 'Cerrada').length,
                byClassification: {},
                byAuthorRole: {},
                totalPhotos: 0,
                averageProgress: 0
            };

            let totalProgress = 0;
            logs.forEach(log => {
                // Por clasificación
                stats.byClassification[log.classification] = 
                    (stats.byClassification[log.classification] || 0) + 1;

                // Por rol de autor
                stats.byAuthorRole[log.author_role] = 
                    (stats.byAuthorRole[log.author_role] || 0) + 1;

                // Fotos
                if (log.photos && Array.isArray(log.photos)) {
                    stats.totalPhotos += log.photos.length;
                }

                // Progreso
                totalProgress += log.progress_percentage || 0;
            });

            stats.averageProgress = logs.length > 0 
                ? Math.round(totalProgress / logs.length) 
                : 0;

            return stats;
        } catch (error) {
            console.error('Error getting statistics:', error);
            throw error;
        }
    }

    /**
     * Valida datos de una nota antes de guardar
     * @param {Object} logData - Datos a validar
     * @returns {Object} - { valid: boolean, errors: Array<string> }
     */
    static validateLogData(logData) {
        const errors = [];

        if (!logData.projectId) errors.push('Project ID is required');
        if (!logData.taskId) errors.push('Task ID is required');
        if (!logData.subject || !logData.subject.trim()) {
            errors.push('Subject is required');
        }

        if (logData.progressPercentage !== undefined) {
            const progress = parseInt(logData.progressPercentage);
            if (isNaN(progress) || progress < 0 || progress > 100) {
                errors.push('Progress must be between 0 and 100');
            }
        }

        const validClassifications = ['Apertura', 'Orden', 'Solicitud', 'Autorización', 'Informe', 'Cierre', 'Otro'];
        if (logData.classification && !validClassifications.includes(logData.classification)) {
            errors.push(`Classification must be one of: ${validClassifications.join(', ')}`);
        }

        const validAuthorRoles = ['Supervisor', 'Residente', 'Superintendente', 'Otro'];
        if (logData.authorRole && !validAuthorRoles.includes(logData.authorRole)) {
            errors.push(`Author role must be one of: ${validAuthorRoles.join(', ')}`);
        }

        const validStatuses = ['Abierta', 'Cerrada'];
        if (logData.status && !validStatuses.includes(logData.status)) {
            errors.push(`Status must be one of: ${validStatuses.join(', ')}`);
        }

        return {
            valid: errors.length === 0,
            errors
        };
    }

    /**
     * Extrae los metadatos de una entrada de diario del content
     * @param {string} content - Contenido de la entrada
     * @returns {Object|null} - Metadatos del diario o null
     */
    static extractDiaryMetadata(content) {
        if (!content) return null;
        
        const metadataMatch = content.match(/<!--DIARY_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing diary metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Extrae metadata de bitácora del contenido
     * @param {string} content - Contenido con metadata
     * @returns {object|null} - Metadata extraída o null
     */
    static extractBitacoraMetadata(content) {
        if (!content) return null;
        const metadataMatch = content.match(/<!--BITACORA_METADATA:(.*?)-->/);
        if (metadataMatch) {
            try {
                return JSON.parse(metadataMatch[1]);
            } catch (e) {
                console.error('Error parsing bitacora metadata:', e);
                return null;
            }
        }
        return null;
    }

    /**
     * Obtiene el contenido limpio sin metadata
     * @param {string} content - Contenido con metadata
     * @returns {string} - Contenido limpio
     */
    static getCleanContent(content) {
        if (!content) return '';
        return content
            .replace(/\n\n<!--DIARY_METADATA:.*?-->/, '')
            .replace(/\n\n<!--BITACORA_METADATA:.*?-->/, '')
            // También limpiar metadata de descripciones de fotos en reportes fotográficos
            .replace(/\n?\s*<!--PHOTO_CAPTIONS:.*?-->$/s, '')
            .trim();
    }

    /**
     * Verifica si un log es una entrada de diario
     * @param {Object} log - Log a verificar
     * @returns {boolean} - True si es entrada de diario
     */
    static isDiaryEntry(log) {
        if (!log) return false;
        // Verificar por task_id o por metadata en content
        if (log.task_id === 'diary') return true;
        if (log.content && this.extractDiaryMetadata(log.content)) return true;
        return false;
    }
}

