/**
 * ErrorService
 * Centralized error handling and user-friendly error messages
 * Integrado con Sentry para monitoreo en producción
 */

import { captureException, captureMessage } from '../lib/sentry';

// Variable global para almacenar el contexto de errores (se inyectará desde ErrorContext)
let errorContextRef = null;

export const setErrorContext = (context) => {
    errorContextRef = context;
};

export class ErrorService {
    /**
     * Get user-friendly error message
     * @param {Error|string} error - Error object or message
     * @returns {string}
     */
    static getErrorMessage(error) {
        if (typeof error === 'string') {
            return error;
        }

        if (!error) {
            return 'Ha ocurrido un error desconocido';
        }

        // Network errors
        if (error.message?.includes('fetch') || error.message?.includes('network')) {
            return 'Error de conexión. Verifica tu internet e intenta de nuevo.';
        }

        // API errors
        if (error.message?.includes('API') || error.message?.includes('Gemini')) {
            return 'Error al conectar con el servicio de IA. Intenta más tarde.';
        }

        // Overloaded/Service unavailable errors
        if (error.message?.includes('overloaded') || error.message?.includes('sobrecargado')) {
            return '⚠️ El servicio de IA está sobrecargado en este momento. Por favor espera 30-60 segundos e intenta de nuevo.';
        }

        if (error.message?.includes('quota') || error.message?.includes('limit exceeded') || error.message?.includes('límite')) {
            return '⚠️ Has alcanzado el límite de uso del servicio de IA. Por favor intenta más tarde.';
        }

        // Supabase errors
        if (error.message?.includes('JWT') || error.message?.includes('auth')) {
            return 'Error de autenticación. Por favor, inicia sesión nuevamente.';
        }

        if (error.message?.includes('permission') || error.message?.includes('policy')) {
            return 'No tienes permisos para realizar esta acción.';
        }

        // JSON parsing errors
        if (error.message?.includes('JSON') || error.message?.includes('parse')) {
            return 'Error al procesar los datos. Verifica el formato.';
        }

        // Validation errors
        if (error.message?.includes('validation') || error.message?.includes('valid')) {
            return error.message;
        }

        // Default: return the error message or a generic one
        return error.message || 'Ha ocurrido un error. Intenta nuevamente.';
    }

    /**
     * Log error with context
     * @param {Error|string} error - Error to log
     * @param {string} context - Context where error occurred
     * @param {Object} metadata - Additional metadata
     * @param {string} level - Error level: 'error', 'warning', 'info'
     */
    static logError(error, context = 'Unknown', metadata = {}, level = 'error') {
        const errorMessage = this.getErrorMessage(error);
        
        console.error(`[${context}]`, {
            error: errorMessage,
            originalError: error,
            metadata,
            timestamp: new Date().toISOString()
        });

        // Registrar en el contexto de errores para que el asistente pueda acceder
        if (errorContextRef && errorContextRef.logError) {
            try {
                errorContextRef.logError(error, {
                    context,
                    ...metadata,
                    currentPage: window.location.pathname,
                });
            } catch (e) {
                console.warn('Error al registrar en ErrorContext:', e);
            }
        }

        // Enviar a Sentry si está configurado (solo en producción)
        try {
            const errorObj = error instanceof Error ? error : new Error(errorMessage);
            
            // Agregar contexto adicional al error
            errorObj.context = context;
            errorObj.metadata = metadata;
            
            captureException(errorObj, {
                context,
                ...metadata,
                userFriendlyMessage: errorMessage,
            }, level);
        } catch (sentryError) {
            // Si Sentry falla, continuar sin interrumpir
            console.warn('Error al enviar a Sentry:', sentryError);
        }
    }

    /**
     * Handle API error with retry logic
     * @param {Function} fn - Function to retry
     * @param {number} maxRetries - Maximum number of retries
     * @param {number} delay - Delay between retries in ms
     * @returns {Promise}
     */
    static async withRetry(fn, maxRetries = 3, delay = 1000) {
        let lastError;
        
        for (let i = 0; i < maxRetries; i++) {
            try {
                return await fn();
            } catch (error) {
                lastError = error;
                
                // Don't retry on certain errors
                if (error.message?.includes('validation') || 
                    error.message?.includes('permission') ||
                    error.message?.includes('auth')) {
                    throw error;
                }
                
                if (i < maxRetries - 1) {
                    await new Promise(resolve => setTimeout(resolve, delay * (i + 1)));
                }
            }
        }
        
        throw lastError;
    }
}

export default ErrorService;

/**
 * Sentry Configuration
 * Monitoreo de errores en producción
 * Solo se inicializa si SENTRY_DSN está configurado
 * 
 * NOTA: Para usar Sentry, instala: npm install @sentry/react
 */

let Sentry = null;
let isInitialized = false;

// Cargar Sentry de forma dinámica solo si está disponible
async function loadSentry() {
    if (typeof window === 'undefined') return; // Solo en el cliente
    
    try {
        // Intentar importar Sentry dinámicamente
        const SentryModule = await import('@sentry/react').catch(() => null);
        
        if (SentryModule && (SentryModule.default || SentryModule)) {
            Sentry = SentryModule.default || SentryModule;
            initializeSentry();
        } else {
            console.log('📝 Sentry no está disponible. Para habilitar monitoreo de errores, ejecuta: npm install @sentry/react');
        }
    } catch (error) {
        // Sentry no está instalado o hubo error - esto es normal
        console.log('📝 Sentry no está disponible. Para habilitar monitoreo de errores, ejecuta: npm install @sentry/react');
    }
}

// Cargar Sentry cuando el módulo se importe (sin bloquear)
if (typeof window !== 'undefined') {
    // Usar setTimeout para no bloquear la carga inicial
    setTimeout(() => {
        loadSentry();
    }, 0);
}

function initializeSentry() {
    if (isInitialized || !Sentry) return;

    const dsn = import.meta.env.VITE_SENTRY_DSN;
    const environment = import.meta.env.MODE || 'development';
    
    // Solo inicializar si hay DSN configurado (producción)
    if (!dsn) {
        console.log('📝 Sentry no configurado (VITE_SENTRY_DSN no encontrado). Esto es normal en desarrollo.');
        return;
    }

    try {
        // Verificar que Sentry tenga el método init
        if (!Sentry || !Sentry.init) {
            console.warn('Sentry no está disponible correctamente');
            return;
        }

        const integrations = [];
        
        // Agregar integraciones solo si están disponibles
        if (Sentry.browserTracingIntegration) {
            integrations.push(Sentry.browserTracingIntegration());
        }
        if (Sentry.replayIntegration) {
            integrations.push(Sentry.replayIntegration({
                maskAllText: true,
                blockAllMedia: true,
            }));
        }

        Sentry.init({
            dsn,
            environment,
            integrations,
            
            // Performance Monitoring
            tracesSampleRate: environment === 'production' ? 0.1 : 1.0, // 10% en producción, 100% en desarrollo
            
            // Session Replay
            replaysSessionSampleRate: environment === 'production' ? 0.1 : 1.0,
            replaysOnErrorSampleRate: 1.0, // Siempre grabar cuando hay errores
            
            // Configuración adicional
            beforeSend(event, hint) {
                // Filtrar errores que no queremos reportar
                if (event.exception) {
                    const errorMessage = event.exception.values?.[0]?.value || '';
                    
                    // Filtrar errores comunes de red que no son críticos
                    if (errorMessage.includes('Failed to fetch') ||
                        errorMessage.includes('NetworkError') ||
                        errorMessage.includes('ERR_NAME_NOT_RESOLVED')) {
                        // Solo reportar si es error recurrente
                        return null;
                    }
                    
                    // Filtrar errores de validación del usuario (no son bugs)
                    if (errorMessage.includes('validation') && 
                        !errorMessage.includes('internal')) {
                        return null;
                    }
                }
                
                // Agregar información del usuario si está disponible
                if (window.user) {
                    event.user = {
                        id: window.user.id,
                        email: window.user.email,
                    };
                }
                
                return event;
            },
            
            // Ignorar ciertos errores
            ignoreErrors: [
                // Errores de red comunes
                'NetworkError',
                'Failed to fetch',
                'Network request failed',
                // Errores de extensiones del navegador
                'ResizeObserver loop limit exceeded',
                'Non-Error promise rejection captured',
                // Errores específicos del navegador
                'Script error',
            ],
        });
        
        isInitialized = true;
        console.log('✅ Sentry inicializado correctamente para:', environment);
    } catch (error) {
        console.error('❌ Error al inicializar Sentry:', error);
    }
}

/**
 * Obtener instancia de Sentry (solo si está inicializado)
 */
export function getSentry() {
    if (!isInitialized || !Sentry) return null;
    return Sentry;
}

/**
 * Verificar si Sentry está inicializado
 */
export function isSentryInitialized() {
    return isInitialized && Sentry !== null;
}

/**
 * Capturar excepción manualmente
 */
export function captureException(error, context = {}, level = 'error') {
    // Si Sentry no está instalado o inicializado, solo loggear
    if (!Sentry || !isInitialized) {
        console.error('[Error no enviado a Sentry]:', error, context);
        return;
    }
    
    try {
        if (Sentry.captureException) {
            Sentry.captureException(error, {
                level,
                extra: context,
                tags: {
                    source: context.source || 'manual',
                },
            });
        }
    } catch (err) {
        console.error('Error al capturar excepción en Sentry:', err);
    }
}

/**
 * Capturar mensaje manualmente
 */
export function captureMessage(message, level = 'info', context = {}) {
    // Si Sentry no está disponible, solo loggear
    if (!Sentry || !isInitialized) {
        console.log(`[${level.toUpperCase()}]`, message, context);
        return;
    }
    
    try {
        if (Sentry.captureMessage) {
            Sentry.captureMessage(message, {
                level,
                extra: context,
            });
        }
    } catch (err) {
        console.error('Error al capturar mensaje en Sentry:', err);
    }
}

/**
 * Configurar usuario para contexto de errores
 */
export function setSentryUser(user) {
    // Guardar en window para acceso rápido (siempre)
    if (typeof window !== 'undefined') {
        window.user = user;
    }
    
    if (!Sentry || !isInitialized) return;
    
    try {
        if (Sentry.setUser) {
            Sentry.setUser({
                id: user?.id,
                email: user?.email,
                username: user?.email?.split('@')[0],
            });
        }
    } catch (err) {
        console.error('Error al configurar usuario en Sentry:', err);
    }
}

/**
 * Limpiar usuario (al hacer logout)
 */
export function clearSentryUser() {
    // Limpiar siempre window.user
    if (typeof window !== 'undefined') {
        delete window.user;
    }
    
    if (!Sentry || !isInitialized) return;
    
    try {
        if (Sentry.setUser) {
            Sentry.setUser(null);
        }
    } catch (err) {
        console.error('Error al limpiar usuario en Sentry:', err);
    }
}

/**
 * Agregar contexto adicional a errores futuros
 */
export function setSentryContext(key, value) {
    if (!Sentry || !isInitialized) return;
    
    try {
        if (Sentry.setContext) {
            Sentry.setContext(key, value);
        }
    } catch (err) {
        console.error('Error al configurar contexto en Sentry:', err);
    }
}

export default {
    getSentry,
    isSentryInitialized,
    captureException,
    captureMessage,
    setSentryUser,
    clearSentryUser,
    setSentryContext,
};

