/**
 * Generate a valid UUID v4
 * Compatible with Supabase UUID columns
 */
export const generateId = () => {
    // Use crypto.randomUUID if available (modern browsers)
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
        return crypto.randomUUID();
    }

    // Fallback: Generate UUID v4 manually
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
};

/**
 * Get current year dynamically
 * Used to ensure all prices and APUs use current year references
 */
export const getCurrentYear = () => {
    return new Date().getFullYear();
};

/**
 * Get current year range (current and previous year)
 * Format: "2024-2025"
 */
export const getCurrentYearRange = () => {
    const currentYear = getCurrentYear();
    const previousYear = currentYear - 1;
    return `${previousYear}-${currentYear}`;
};

/**
 * ProjectPersistenceService
 * Servicio centralizado para persistencia de proyectos
 * Maneja guardado, carga, eliminación y sincronización con Supabase
 */

import SupabaseService from './SupabaseService';
import { supabase } from '../lib/supabaseClient';

export class ProjectPersistenceService {
    /**
     * Guarda un proyecto completo con sincronización de cronograma
     * @param {Object} projectData - Datos completos del proyecto
     * @returns {Promise<Object>} - Proyecto guardado con ID actualizado
     */
    static async saveProject(projectData) {
        // Validar que tenga nombre
        if (!projectData.projectInfo?.project) {
            throw new Error('El proyecto debe tener un nombre');
        }
        if (import.meta.env?.DEV) {
            console.debug('[Reporte] ProjectPersistence.saveProject - id:', projectData?.id, 'projectInfo:', {
                project: projectData.projectInfo?.project,
                contractor: projectData.projectInfo?.contractor,
                concepts: projectData.projectInfo?.concepts,
                ubicacion: projectData.projectInfo?.ubicacion,
                lastReportDate: projectData.projectInfo?.lastReportDate,
            })
        }
        // Guardar proyecto principal
        const saved = await SupabaseService.saveProject(projectData);
        if (import.meta.env?.DEV) console.debug('[Reporte] ProjectPersistence.saveProject - resultado OK, id:', saved?.id)

        // Sincronizar cronograma si existe
        if (projectData.scheduleData && saved.id) {
            await this.syncSchedule(saved.id, projectData.scheduleData);
        }

        return saved;
    }

    /**
     * Sincroniza el cronograma con la tabla project_schedules
     * @param {string} projectId - ID del proyecto
     * @param {Object} scheduleData - Datos del cronograma
     */
    static async syncSchedule(projectId, scheduleData) {
        if (!projectId || !scheduleData) return;

        try {
            // Verificar si existe cronograma
            const { data: existing } = await supabase
                .from('project_schedules')
                .select('id')
                .eq('project_id', projectId)
                .maybeSingle();

            if (existing) {
                // Actualizar existente
                await supabase
                    .from('project_schedules')
                    .update({
                        tasks: scheduleData,
                        updated_at: new Date().toISOString()
                    })
                    .eq('id', existing.id);
            } else {
                // Crear nuevo
                await supabase
                    .from('project_schedules')
                    .insert([{
                        project_id: projectId,
                        tasks: scheduleData
                    }]);
            }
        } catch (error) {
            console.error('Error syncing schedule:', error);
            // No lanzar error para no interrumpir el guardado del proyecto
        }
    }

    /**
     * Carga un proyecto completo por ID
     * Valida que el proyecto pertenezca al usuario actual
     * @param {string} projectId - ID del proyecto
     * @returns {Promise<Object|null>} - Datos completos del proyecto o null
     * @throws {Error} - Si el proyecto no existe o el usuario no tiene permisos
     */
    static async loadProject(projectId) {
        if (!projectId) {
            throw new Error('ID de proyecto requerido');
        }

        try {
            const fullData = await SupabaseService.getProject(projectId);
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] ProjectPersistence.loadProject - projectId:', projectId, 'projectInfo leído:', {
                    project: fullData.projectInfo?.project,
                    contractor: fullData.projectInfo?.contractor,
                    concepts: fullData.projectInfo?.concepts,
                    ubicacion: fullData.projectInfo?.ubicacion,
                    lastReportDate: fullData.projectInfo?.lastReportDate,
                })
            }
            if (!fullData) {
                throw new Error('Proyecto no encontrado');
            }

            // Cargar cronograma desde tabla separada si existe
            const { data: schedule } = await supabase
                .from('project_schedules')
                .select('tasks')
                .eq('project_id', projectId)
                .maybeSingle();

            // Priorizar cronograma de tabla separada, sino usar el del JSON
            if (schedule) {
                fullData.scheduleData = schedule.tasks;
            }

            return fullData;
        } catch (error) {
            console.error('Error loading project:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Lista todos los proyectos (solo metadata)
     * @returns {Promise<Array>} - Lista de proyectos
     */
    static async listProjects() {
        return await SupabaseService.listProjects();
    }

    /**
     * Elimina un proyecto
     * @param {string} projectId - ID del proyecto a eliminar
     */
    static async deleteProject(projectId) {
        if (!projectId) throw new Error('Project ID is required');

        // 1. Eliminar logs de bitácora
        try {
            await supabase
                .from('site_logs')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting logs:', error);
        }

        // 2. Eliminar cronograma asociado
        try {
            await supabase
                .from('project_schedules')
                .delete()
                .eq('project_id', projectId);
        } catch (error) {
            console.error('Error deleting schedule:', error);
        }

        // 3. Eliminar proyecto principal
        await SupabaseService.deleteProject(projectId);
    }


    /**
     * Renombra un proyecto
     * @param {string} projectId - ID del proyecto
     * @param {string} newName - Nuevo nombre
     */
    static async renameProject(projectId, newName) {
        if (!projectId || !newName) {
            throw new Error('Project ID and new name are required');
        }

        await SupabaseService.updateProjectName(projectId, newName);
    }

    /**
     * Carga un proyecto desde URL params
     * Incluye carga de cronograma desde tabla separada
     * @param {string} projectId - ID del proyecto desde URL
     * @returns {Promise<Object|null>} - Datos completos del proyecto
     */
    static async loadProjectFromUrl(projectId) {
        return await this.loadProject(projectId);
    }
}

export default ProjectPersistenceService;

/**
 * SupabaseService
 * Handles cloud persistence of projects using Supabase
 */

import { supabase } from '../lib/supabaseClient';
import { generateId } from '../utils/helpers';

export class SupabaseService {
    /**
     * Save a project to Supabase
     * @param {Object} projectData - Full project data
     * @returns {Object} - Saved project metadata
     */
    static async saveProject(projectData) {
        try {
            const user = (await supabase.auth.getUser()).data.user;
            const userId = user ? user.id : null; // Optional: handle auth later

            // Prepare data for DB
            // We store the heavy JSON in a 'data' column. Usar siempre projectData.id si existe
            // para actualizar la fila correcta (evitar crear fila nueva y que los datos no persistan).
            const id = projectData.id || generateId();
            const dataToStore = { ...projectData, id }; // Incluir id en el JSON para que al cargar venga el id

            const payload = {
                id: id,
                name: projectData.projectInfo?.project || 'Sin Nombre',
                client: projectData.projectInfo?.client || '',
                location: projectData.projectInfo?.location || '',
                data: dataToStore, // Store full JSON con id incluido
                updated_at: new Date().toISOString()
            };

            if (userId) payload.user_id = userId;

            if (import.meta.env?.DEV && payload.data?.projectInfo) {
                console.debug('[Reporte] Supabase.saveProject - enviando projectInfo:', {
                    project: payload.data.projectInfo.project,
                    contractor: payload.data.projectInfo.contractor,
                    concepts: payload.data.projectInfo.concepts,
                    ubicacion: payload.data.projectInfo.ubicacion,
                    lastReportDate: payload.data.projectInfo.lastReportDate,
                });
            }
            const { data, error } = await supabase
                .from('projects')
                .upsert(payload)
                .select()
                .single();

            if (error) throw error;

            return data;
        } catch (error) {
            console.error('Error saving project to Supabase:', error);
            throw error;
        }
    }

    /**
     * Get all projects (metadata)
     * @returns {Array} - List of projects sorted by date
     */
    static async getAllProjects() {
        try {
            const { data, error } = await supabase
                .from('projects')
                .select('id, name, client, location, updated_at, data')
                .order('updated_at', { ascending: false });

            if (error) throw error;

            return data.map(p => {
                const projectData = p.data || {};
                const info = projectData.projectInfo || {};
                const items = projectData.items || [];

                // Calculate total for display
                const total = items.reduce((sum, item) => {
                    return sum + (item.quantity * item.unitPrice);
                }, 0);

                return {
                    id: p.id,
                    project: info.project || p.name || 'Sin Nombre',
                    client: info.client || p.client || 'Sin Cliente',
                    type: info.type || 'General',
                    location: info.location || p.location,
                    lastModified: p.updated_at,
                    items: items,
                    total: total,
                    // Keep full data for loading
                    ...projectData
                };
            });

        } catch (error) {
            console.error('Error loading projects from Supabase:', error);
            return [];
        }
    }

    /**
     * Alias for getAllProjects - used in Editor component
     * @returns {Array} - List of projects sorted by date
     */
    static async listProjects() {
        return this.getAllProjects();
    }

    /**
     * Get a specific project by ID
     * RLS policies ensure user can only access their own projects
     * @param {string} id 
     * @returns {Object|null}
     */
    static async getProject(id) {
        try {
            // Verificar autenticación primero
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                throw new Error('No autenticado');
            }

            // RLS policies de Supabase aseguran que solo se obtengan proyectos del usuario
            const { data, error } = await supabase
                .from('projects')
                .select('id, user_id, data')
                .eq('id', id)
                .maybeSingle();

            if (error) throw error;
            if (!data) return null;

            // Validación adicional: verificar que el proyecto pertenece al usuario
            // (aunque RLS debería proteger esto, validamos como capa adicional)
            if (data.user_id && data.user_id !== user.id) {
                throw new Error('No tienes permisos para acceder a este proyecto');
            }

            const fullData = data.data || {}; // The 'data' column contains our JSON
            // Incluir siempre el id de la fila para que saveProject actualice la misma fila y no cree una nueva
            const projectWithId = { ...fullData, id: data.id };
            if (import.meta.env?.DEV && fullData?.projectInfo) {
                console.debug('[Reporte] Supabase.getProject - projectInfo en data:', {
                    project: fullData.projectInfo.project,
                    contractor: fullData.projectInfo.contractor,
                    concepts: fullData.projectInfo.concepts,
                    ubicacion: fullData.projectInfo.ubicacion,
                    lastReportDate: fullData.projectInfo.lastReportDate,
                });
            }
            return projectWithId;
        } catch (error) {
            console.error('Error loading project details:', error);
            // Re-lanzar el error para que el componente pueda manejarlo
            throw error;
        }
    }

    /**
     * Delete a project by ID
     * @param {string} id 
     */
    static async deleteProject(id) {
        try {
