export class SystemSettingsService {
    constructor() {
        this.cache = null;
        this.lastFetch = 0;
        this.CACHE_DURATION = 5 * 60 * 1000; // 5 minutos

        // Valores por defecto
        this.defaults = {
            whatsapp_number: '522811975587',
            support_message: 'Hola, necesito ayuda con PresuGenius',
